package shortestpath;

import java.awt.*;
import java.awt.image.BufferedImage;
import java.util.*;
import java.util.List;
import javax.swing.*;
import javax.swing.border.*;
import lombok.*;
import lombok.experimental.Accessors;
import net.runelite.client.ui.*;
import net.runelite.client.util.*;
import shortestpath.ShortestPathPanel.SearchRow;

/**
 * One drilled section of the sidebar: a back-arrow header pinned over its
 * own scroll of rows. A tile click on the home grid shows it; the arrow
 * returns to the grid. The back icon reuses the bundled chevron rotated
 * 180 degrees; the header keeps the section chrome (orange bold name,
 * bottom divider) and carries a trailing slot on its right edge — the
 * restrictions section parks its "Owned" checkbox there.
 *
 * <p>Each section filters its own rows in place on a search query; the
 * pinned header keeps the back affordance and the trailing slot reachable
 * while the rows scroll.</p>
 */
class CategoryPanel extends JPanel
{
	private static final ImageIcon BACK_ICON;

	static
	{
		BufferedImage chevron = ImageUtil.loadImageResource(ShortestPathPanel.class, "/shortestpath/expand.png");
		chevron = ImageUtil.luminanceOffset(chevron, -121);
		BACK_ICON = new ImageIcon(ImageUtil.rotateImage(chevron, Math.PI));
	}

	@Getter(AccessLevel.PACKAGE) @Accessors(fluent = true) private final String categoryName;
	// Lowercased name + aliases: a query contained here shows the whole
	// section (the names double as search aliases, e.g. "routing" finds
	// the renamed "General" section).
	/**
	 * The section's own match text (lowercased name + aliases). Rows
	 * that self-filter — the restriction checklist's items-disabled
	 * hint — match on this text rather than a second hardcoded copy,
	 * so renaming the section or its alias cannot desync them.
	 */
	@Getter(AccessLevel.PACKAGE) @Accessors(fluent = true) private final String matchText;
	private final JPanel header;
	private final FixedWidthPanel content;
	@Getter(AccessLevel.PACKAGE) @Accessors(fluent = true)
	private final List<SearchRow> rows = new ArrayList<>();

	CategoryPanel(String name, String alias, Runnable onBack)
	{
		this.categoryName = name;
		this.matchText = ShortestPathPanel.searchable(name, alias);

		setLayout(new BorderLayout());
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		header = new JPanel(new BorderLayout());
		header.setBackground(ColorScheme.DARK_GRAY_COLOR);
		header.setBorder(new CompoundBorder(
			new MatteBorder(0, 0, 1, 0, ColorScheme.MEDIUM_GRAY_COLOR),
			new EmptyBorder(0, 4, 3, 1)));

		JButton back = new JButton(BACK_ICON);
		SwingUtil.removeButtonDecorations(back);
		back.setPreferredSize(new Dimension(22, 0));
		back.setBorder(new EmptyBorder(0, 0, 0, 5));
		back.setToolTipText("Back");
		back.addActionListener(e -> onBack.run());
		header.add(back, BorderLayout.WEST);

		JLabel nameLabel = new JLabel(name);
		nameLabel.setForeground(ColorScheme.BRAND_ORANGE);
		nameLabel.setFont(FontManager.getRunescapeBoldFont());
		header.add(nameLabel, BorderLayout.CENTER);

		add(header, BorderLayout.NORTH);

		content = new FixedWidthPanel();
		content.setLayout(new DynamicGridLayout(0, 1, 0, 5));
		content.setBackground(ColorScheme.DARK_GRAY_COLOR);
		content.setBorder(new CompoundBorder(
			new MatteBorder(0, 0, 1, 0, ColorScheme.MEDIUM_GRAY_COLOR),
			new EmptyBorder(PluginPanel.BORDER_OFFSET, 8, PluginPanel.BORDER_OFFSET, 8)));

		FixedWidthPanel view = new FixedWidthPanel();
		view.setLayout(new BorderLayout());
		view.add(content, BorderLayout.NORTH);

		JScrollPane scrollPane = new JScrollPane(view);
		scrollPane.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
		add(scrollPane, BorderLayout.CENTER);
	}

	/**
	 * Extra header slot on the right edge — the Restrictions section parks
	 * its "Owned" checkbox here.
	 */
	void setTrailing(JComponent component)
	{
		header.add(component, BorderLayout.EAST);
		header.revalidate();
	}

	/**
	 * Appends a searchable row to the section's content column.
	 */
	void addRow(JComponent component, String displayText, String searchText)
	{
		addRow(new SearchRow(component, displayText, searchText));
	}

	void addRow(SearchRow row)
	{
		rows.add(row);
		content.add(row.component);
	}

	/**
	 * The rows matching {@code query} (already lowercased): every row when
	 * the query is empty or hits the section's own name/alias, otherwise
	 * rows whose search text contains it. The restriction checklist matches
	 * by its own family/member labels rather than its row text.
	 */
	List<SearchRow> matchingRows(String query)
	{
		if (query.isEmpty() || matchText.contains(query))
		{
			return new ArrayList<>(rows);
		}
		List<SearchRow> matches = new ArrayList<>();
		for (SearchRow row : rows)
		{
			if (row.component instanceof RestrictionListPanel)
			{
				if (!((RestrictionListPanel) row.component).matchingLabels(query).isEmpty())
				{
					matches.add(row);
				}
				continue;
			}
			if (row.text.contains(query))
			{
				matches.add(row);
			}
		}
		return matches;
	}

	/**
	 * Rebuilds the visible rows for {@code query}: all rows on an empty
	 * query or a name/alias hit, otherwise only the matching rows — with
	 * the same per-row semantics the old section filter applied (detail-
	 * label hits force the card open; the restriction checklist filters
	 * itself). An empty query also collapses search-forced expansions.
	 */
	void applyQuery(String rawQuery)
	{
		String query = rawQuery.trim().toLowerCase(Locale.ROOT);
		boolean nameMatch = !query.isEmpty() && matchText.contains(query);

		content.removeAll();
		for (SearchRow row : rows)
		{
			if (row.component instanceof RestrictionListPanel)
			{
				RestrictionListPanel list = (RestrictionListPanel) row.component;
				if (list.applyFilter(nameMatch ? "" : query))
				{
					content.add(row.component);
				}
				continue;
			}
			if (query.isEmpty() && row.component instanceof SearchExpandable)
			{
				((SearchExpandable) row.component).clearSearchExpanded();
			}
			// Expandable rows can stack expandable children (enum groups
			// inside a family card): an empty query clears their search
			// state too, and a member-label hit expands the group inside
			// the card the same query opens.
			if (row.component instanceof ExpandableSurface)
			{
				for (Component child : ((ExpandableSurface) row.component).detail.getComponents())
				{
					if (child instanceof CollapsibleEnumGroup)
					{
						CollapsibleEnumGroup<?> group = (CollapsibleEnumGroup<?>) child;
						if (query.isEmpty())
						{
							group.clearSearchExpanded();
						}
						else if (!nameMatch && group.matchesMember(query))
						{
							group.setSearchExpanded();
						}
					}
				}
			}
			if (query.isEmpty() || nameMatch || row.text.contains(query))
			{
				content.add(row.component);
				// A match on a detail label (not the component's own name)
				// opens the detail well so the matched control is visible.
				if (!query.isEmpty() && !nameMatch && row.component instanceof SearchExpandable)
				{
					SearchExpandable expandable = (SearchExpandable) row.component;
					String rowName = expandable.getNameLabel().getText().toLowerCase(Locale.ROOT);
					if (!rowName.contains(query))
					{
						expandable.setSearchExpanded();
					}
				}
			}
		}
		content.revalidate();
		content.repaint();
	}
}

package shortestpath;

import java.awt.*;
import java.util.*;
import java.util.List;
import javax.swing.*;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.*;
import lombok.*;

/**
 * One collapsible bucket inside a {@code Set<Enum>} config sub-list: a
 * header row (chevron + group name + a live "n/total" selected count) over
 * a detail well holding one {@link JCheckBox} per member. Collapsed by
 * default; clicking the header toggles it.
 *
 * <p>Member read/write rides the exact mechanics the flat sub-list used:
 * checked state mirrors {@code currentSet(keyName)}, a toggle writes a
 * mutated {@link EnumSet} copy through {@code settings.write}, and the
 * shared {@link #syncing} guard keeps the config listener's programmatic
 * {@code setSelected} calls from writing the mirrored set back. Grouping
 * is display structure only — the config key, type and persistence are
 * untouched.</p>
 */
class CollapsibleEnumGroup<E extends Enum<E>> extends ExpandableSurface
{
	private final ShortestPathPanel panel;
	private final String keyName;
	private final Class<E> type;
	private final List<E> members;
	private final List<JCheckBox> boxes = new ArrayList<>();

	private final JPanel header;
	@Getter private final JLabel nameLabel;
	@Getter(AccessLevel.PACKAGE) private final JLabel countLabel;
	// Held while a config sync mirrors the stored set into the checkboxes,
	// so the programmatic setSelected calls do not write it back.
	private final PanelRows.SyncGuard syncing = new PanelRows.SyncGuard();

	CollapsibleEnumGroup(ShortestPathPanel panel, String keyName, Class<E> type,
		String groupLabel, List<E> members, String description)
	{
		super(new EmptyBorder(0, ShortestPathPanel.SUB_LIST_INDENT, 4, 0));
		this.panel = panel;
		this.keyName = keyName;
		this.type = type;
		this.members = members;

		setOpaque(false);

		header = new JPanel(new BorderLayout());

		expander = newExpander();
		expander.setPreferredSize(new Dimension(ShortestPathPanel.SECTION_TOGGLE_WIDTH, 0));
		expander.setBorder(new EmptyBorder(0, 0, 0, 5));
		header.add(expander, BorderLayout.WEST);

		nameLabel = new JLabel(ShortestPathPanel.html(groupLabel));
		nameLabel.setToolTipText(ShortestPathPanel.html(description));
		header.add(nameLabel, BorderLayout.CENTER);

		countLabel = new JLabel();
		countLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		countLabel.setFont(FontManager.getRunescapeSmallFont());
		header.add(countLabel, BorderLayout.EAST);
		add(header);

		add(detail);

		// The shared expandable chrome: dark header bar over the
		// category-toned, orange-bordered detail well.
		ShortestPathPanel.styleExpandable(header, detail);

		for (E member : members)
		{
			JCheckBox checkBox = new JCheckBox(ShortestPathPanel.html(member.toString()));
			checkBox.setSelected(panel.currentSet(keyName, type).contains(member));
			checkBox.setToolTipText(ShortestPathPanel.html(description));
			checkBox.addActionListener(e ->
				PanelRows.guardedWrite(syncing, () ->
				{
					EnumSet<E> updated = EnumSet.noneOf(type);
					updated.addAll(panel.currentSet(keyName, type));
					if (checkBox.isSelected())
					{
						updated.add(member);
					}
					else
					{
						updated.remove(member);
					}
					panel.settings.write(keyName, updated);
				}));
			boxes.add(checkBox);
			detail.add(checkBox);
		}

		panel.registerConfigListener(keyName, this::syncFromConfig);
		updateCount();
		installExpandListener(header, nameLabel, countLabel);
	}

	/**
	 * Whether {@code query} (already lowercased) hits a member label —
	 * the nested expansion hook {@link CategoryPanel#applyQuery} runs so
	 * a member-name query opens a group stacked inside a card's detail
	 * well the same way it opens a free-standing one.
	 */
	boolean matchesMember(String query)
	{
		for (E member : members)
		{
			if (member.toString().toLowerCase(Locale.ROOT).contains(query))
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Re-reads the stored set and mirrors it into the member checkboxes +
	 * the header's "n/total" count — one listener keeps both in step, so
	 * the count never carries separate state.
	 */
	void syncFromConfig()
	{
		Set<E> set = panel.currentSet(keyName, type);
		PanelRows.resync(syncing, () ->
		{
			for (int i = 0; i < members.size(); i++)
			{
				boxes.get(i).setSelected(set.contains(members.get(i)));
			}
		}, this::updateCount);
	}

	private void updateCount()
	{
		Set<E> set = panel.currentSet(keyName, type);
		int selected = 0;
		for (E member : members)
		{
			if (set.contains(member))
			{
				selected++;
			}
		}
		countLabel.setText(selected + "/" + members.size());
	}
}

package shortestpath;

import java.awt.event.*;
import javax.swing.*;
import javax.swing.border.Border;
import net.runelite.client.ui.DynamicGridLayout;
import net.runelite.client.util.SwingUtil;

/**
 * The header-over-collapsible-detail-well contract every expandable
 * sidebar surface shares — transport family cards, restriction rows and
 * collapsible enum groups: a {@link #detail} well that starts hidden, a
 * chevron {@link #expander} that toggles it, and the search-expansion
 * semantics of {@link SearchExpandable} (a detail-label match opens a
 * collapsed surface; clearing the query restores user-collapsed state,
 * while a manual toggle marks the state user-owned and exempt from
 * collapse).
 *
 * <p>Subclasses lay out their own header, call {@link #newExpander()} when
 * detail content exists, add {@link #detail} after the header, and wire
 * click-anywhere-to-toggle through {@link #installExpandListener}. A
 * surface that never grows detail content stays expander-free —
 * {@link #setDetailOpen} and the search hooks all no-op then.</p>
 */
abstract class ExpandableSurface extends JPanel implements SearchExpandable
{
	final JPanel detail;
	JButton expander;
	private boolean detailOpen;
	private boolean searchExpanded;

	ExpandableSurface(Border detailBorder)
	{
		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		detail = new JPanel(new DynamicGridLayout(0, 1, 0, 4));
		detail.setBorder(detailBorder);
		detail.setVisible(false);
	}

	boolean isDetailOpen()
	{
		return detailOpen;
	}

	/**
	 * The decorated chevron button — sized and placed by the caller's
	 * header layout. Creating it is also what enables the toggle paths:
	 * every method below treats {@link #expander} == null as "no detail
	 * affordance".
	 */
	JButton newExpander()
	{
		expander = new JButton(ShortestPathPanel.SECTION_EXPAND_ICON);
		expander.setToolTipText("Expand");
		SwingUtil.removeButtonDecorations(expander);
		expander.addActionListener(e -> setDetailOpen(!isDetailOpen()));
		// If the lock lands while the detail is open, collapse it so it cannot
		// be stuck open behind a disabled chevron.
		expander.addPropertyChangeListener("enabled", e ->
		{
			if (!expander.isEnabled() && detailOpen)
			{
				searchExpanded = false;
				setDetailOpenInternal(false);
			}
		});
		return expander;
	}

	/**
	 * Manual toggle: counts as user intent, so search no longer owns the
	 * expansion state of this surface.
	 */
	void setDetailOpen(boolean open)
	{
		if (expander == null)
		{
			return;
		}
		searchExpanded = false;
		setDetailOpenInternal(open);
	}

	/**
	 * Search-driven expansion: opens the detail well when the query
	 * matched a detail label rather than the surface's own name, so the
	 * matched control is visible. {@link #clearSearchExpanded()} restores
	 * the collapsed state when the query clears.
	 */
	@Override
	public void setSearchExpanded()
	{
		if (expander != null && !detailOpen)
		{
			searchExpanded = true;
			setDetailOpenInternal(true);
		}
	}

	@Override
	public void clearSearchExpanded()
	{
		if (searchExpanded)
		{
			searchExpanded = false;
			setDetailOpenInternal(false);
		}
	}

	private void setDetailOpenInternal(boolean open)
	{
		detailOpen = open;
		if (expander != null)
		{
			expander.setIcon(open ? ShortestPathPanel.SECTION_RETRACT_ICON
				: ShortestPathPanel.SECTION_EXPAND_ICON);
			expander.setToolTipText(open ? "Retract" : "Expand");
		}
		detail.setVisible(open);
		revalidate();
		repaint();
	}

	/**
	 * Click-anywhere-to-toggle wiring for the header components: Swing
	 * never forwards child mouse events to the parent, so each component
	 * needs the adapter. The expander's enabled flag gates the toggle — a
	 * surface whose detail is locked (disabled master) stays shut.
	 */
	void installExpandListener(JComponent... targets)
	{
		MouseAdapter adapter = new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				if (expander != null && expander.isEnabled())
				{
					setDetailOpen(!isDetailOpen());
				}
			}
		};
		for (JComponent target : targets)
		{
			target.addMouseListener(adapter);
		}
	}
}

package shortestpath;

import java.awt.Dimension;
import javax.swing.JPanel;
import net.runelite.client.ui.PluginPanel;

/**
 * A panel whose preferred width is pinned to {@link PluginPanel#PANEL_WIDTH}
 * so a {@code JScrollPane} view can never outgrow the 225px viewport — the
 * RuneLite config-package pattern (package-private there, reimplemented
 * here). The outer {@code super(false)} panel requests
 * PANEL_WIDTH + SCROLLBAR_WIDTH = 242px and the scroll viewport is
 * 242 - 17 = 225px, so the view must prefer exactly 225: wider content would
 * lay out under the vertical scrollbar's column instead of shrinking to the
 * viewport. This is the only width contract in the panel tree — children
 * must never re-pin a width.
 */
class FixedWidthPanel extends JPanel
{
	@Override
	public Dimension getPreferredSize()
	{
		return new Dimension(PluginPanel.PANEL_WIDTH, super.getPreferredSize().height);
	}
}

package shortestpath;

import java.util.*;
import lombok.*;
import lombok.experimental.Accessors;

/**
 * Item-name to item-id variation table, loaded from a bundled resource.
 *
 * <p>The table lives in {@code item-variations.tsv}: name, the item ids the
 * name covers, the staff alternatives for rune names, and the offhand (tome)
 * alternatives. Columns after the first two may be empty.
 */
@AllArgsConstructor(access = AccessLevel.PRIVATE)
public final class ItemVariations
{
	private static final Map<String, ItemVariations> BY_NAME = new HashMap<>();
	private static final Map<String, int[]> STAVES = new HashMap<>();
	private static final Map<String, int[]> OFFHANDS = new HashMap<>();

	static
	{
		try
		{
			Util.each("/item-variations.tsv", (line, cols) ->
			{
				ItemVariations v = new ItemVariations(cols[0], parseIds(cols[1]));
				BY_NAME.put(v.name, v);
				if (cols.length > 2 && !cols[2].isEmpty())
				{
					STAVES.put(v.name, parseIds(cols[2]));
				}
				if (cols.length > 3 && !cols[3].isEmpty())
				{
					OFFHANDS.put(v.name, parseIds(cols[3]));
				}
			});
		}
		catch (Exception e)
		{
			throw new IllegalStateException("failed to load item-variations.tsv", e);
		}
	}

	private static int[] parseIds(String col)
	{
		String[] parts = col.split(",");
		int[] out = new int[parts.length];
		for (int i = 0; i < parts.length; i++)
		{
			out[i] = Integer.parseInt(parts[i].trim());
		}
		return out;
	}

	@Getter @Accessors(fluent = true) private final String name;
	@Getter private final int[] ids;

	public static int[] staves(ItemVariations itemVariation)
	{
		return itemVariation == null ? null : STAVES.get(itemVariation.name);
	}

	public static int[] offhands(ItemVariations itemVariation)
	{
		return itemVariation == null ? null : OFFHANDS.get(itemVariation.name);
	}

	public static ItemVariations fromName(String name)
	{
		return BY_NAME.get(name);
	}

	public static java.util.Collection<ItemVariations> values()
	{
		return java.util.Collections.unmodifiableCollection(BY_NAME.values());
	}
}

package shortestpath;

import java.awt.*;
import javax.swing.*;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.components.TitleCaseListCellRenderer;

/**
 * The panel's single combo styling path: a dark closed face over a lighter
 * medium-grey popup list — the contrast direction the teleport-restriction
 * surface already shows. Both call sites ({@link ShortestPathPanel}'s
 * {@code comboRow} and {@link TransportFamilyCard}'s enum master) run
 * through {@link #apply(JComboBox)} so the face colour, popup colours,
 * height and the width cap can never diverge per combo.
 */
final class PanelComboStyle
{
	/** Closed face: the dark control tone the transport-card combos show. */
	static final Color FACE_BACKGROUND = ColorScheme.DARKER_GRAY_COLOR;
	/** Popup rows: the lighter grey that reads as the expanded surface. */
	static final Color POPUP_BACKGROUND = ColorScheme.MEDIUM_GRAY_COLOR;
	/**
	 * The selection highlight inside the popup. The LAF's own selection
	 * colour is the same medium grey as {@link #POPUP_BACKGROUND} — reusing
	 * it would hide the highlight — so selected rows invert to the darker
	 * panel tone instead.
	 */
	static final Color POPUP_SELECTED_BACKGROUND = ColorScheme.DARK_GRAY_COLOR;
	/**
	 * Width ceiling for a combo's preferred size: past it a long enum
	 * constant squeezes the row's label column until the label wraps and
	 * the row grows extra lines.
	 */
	static final int MAX_WIDTH = 110;
	static final int HEIGHT = 22;

	private PanelComboStyle()
	{
	}

	/**
	 * Applies the shared renderer and face colour, then pins the preferred
	 * size: a fixed height with the width capped at {@link #MAX_WIDTH}. The
	 * renderer goes on first — {@code getPreferredSize()} consults it to
	 * measure the display text.
	 */
	static void apply(JComboBox<?> combo)
	{
		combo.setRenderer(Renderer.INSTANCE);
		combo.setBackground(FACE_BACKGROUND);
		combo.setPreferredSize(new Dimension(
			Math.min(combo.getPreferredSize().width, MAX_WIDTH), HEIGHT));
	}

	/**
	 * Title-Cases enum constants like RuneLite's own combos while restyling
	 * the colours: popup rows take the lighter grey with the inverted
	 * selection tone, and the index {@code -1} closed-face render takes the
	 * dark face colour for look-and-feels that style the face through the
	 * renderer (FlatLaf overrides it with the combo's own background, which
	 * {@link #apply} sets to the same tone).
	 */
	static final class Renderer extends DefaultListCellRenderer
	{
		private static final Renderer INSTANCE = new Renderer();

		// TitleCaseListCellRenderer is final — delegate for its text
		// transform rather than reimplementing the casing rules.
		private final TitleCaseListCellRenderer titleCase = new TitleCaseListCellRenderer();

		@Override
		public Component getListCellRendererComponent(JList<?> list, Object value,
			int index, boolean isSelected, boolean cellHasFocus)
		{
			Component c = titleCase.getListCellRendererComponent(
				list, value, index, isSelected, cellHasFocus);
			if (index < 0)
			{
				c.setBackground(FACE_BACKGROUND);
			}
			else
			{
				c.setBackground(isSelected ? POPUP_SELECTED_BACKGROUND : POPUP_BACKGROUND);
			}
			return c;
		}
	}
}

package shortestpath;

import java.util.function.BiConsumer;
import javax.swing.JComponent;

/**
 * The wiring ceremony every config-bound panel control shares. A control
 * writes through {@link shortestpath.settings.Settings#write}, which
 * delivers same-key listeners <em>synchronously</em> inside the write —
 * so a config listener that mirrors stored state back into the control
 * (a programmatic {@code setSelected}/{@code setValue}/{@code setSelectedItem})
 * re-fires the control's own listener and would write the mirrored value
 * straight back to config. The {@link SyncGuard} is the only thing
 * suppressing that echo, and the ordering around it is the contract:
 *
 * <ul>
 *   <li>the guard exists <b>before</b> the control's listener is
 *   installed — a guard created after registration could miss the first
 *   echo;</li>
 *   <li>the listener's write goes through {@link #guardedWrite} so an
 *   event raised while a mirror is in flight is skipped, not persisted;</li>
 *   <li>the mirror itself runs inside {@link #resync}: guard raised
 *   first, released in a {@code finally} so a throwing mirror never
 *   leaves it stuck;</li>
 *   <li>any post-resync hook runs <b>after</b> the release — it observes
 *   the mirror's effects as an outside caller would.</li>
 * </ul>
 *
 * <p>The helper owns only this plumbing. Control construction, what the
 * write persists, and what the mirror re-applies stay call-site detail —
 * an envelope that needs side-effects the plumbing cannot express stays
 * hand-rolled rather than growing parameters here.</p>
 */
final class PanelRows
{
	private PanelRows()
	{
	}

	/**
	 * The write-echo guard shared by a control's listener and its config
	 * resync. Opaque to call sites — {@link #guardedWrite} reads it and
	 * {@link #resync} raises/releases it. Sites whose several controls
	 * mirror one stored value share one instance across the whole group,
	 * so a resync on any member suppresses every member's echo; sites
	 * with one control per guard mint a fresh one through
	 * {@link #controlRow}.
	 */
	static final class SyncGuard
	{
		private boolean held;
	}

	/**
	 * Runs {@code write} unless {@code guard} is held — the listener-side
	 * half of the echo contract: a control event raised while a resync
	 * mirrors stored state into the control is the echo, not a user edit.
	 */
	static void guardedWrite(SyncGuard guard, Runnable write)
	{
		if (!guard.held)
		{
			write.run();
		}
	}

	/**
	 * Runs {@code reapply} under the held guard: raised before the mirror
	 * runs (so the echoes it triggers read as sync, not edits) and
	 * released in a {@code finally} so a throwing mirror never wedges the
	 * guard. {@code postResync} — nullable — runs after the release, so
	 * it sees the control in its mirrored state as any outside observer
	 * would.
	 */
	static void resync(SyncGuard guard, Runnable reapply, Runnable postResync)
	{
		guard.held = true;
		try
		{
			reapply.run();
		}
		finally
		{
			guard.held = false;
		}
		if (postResync != null)
		{
			postResync.run();
		}
	}

	/**
	 * Registers {@code keyName}'s config listener as a guarded resync
	 * through the panel's shared registration seam — the panel retains
	 * the unlisten handle so one teardown drops the whole listener graph.
	 */
	static void listen(ShortestPathPanel panel, String keyName, SyncGuard guard,
		Runnable reapply, Runnable postResync)
	{
		panel.registerConfigListener(keyName, () -> resync(guard, reapply, postResync));
	}

	/**
	 * The full ceremony over a fresh guard: mint the guard, install the
	 * control's listener, register the resync — in that order, so the
	 * guard always predates the listener that consults it.
	 *
	 * @param installListener attaches the control's own listener. Each
	 *     control type takes a different listener (Action/Change/Item),
	 *     so the site installs whichever fits and routes its write
	 *     through {@link #guardedWrite}.
	 * @param reapply mirrors the stored value into the control; runs
	 *     under the held guard.
	 * @param postResync nullable hook run after the guard releases.
	 */
	static <C extends JComponent> C controlRow(ShortestPathPanel panel, String keyName, C control,
		BiConsumer<C, SyncGuard> installListener, Runnable reapply, Runnable postResync)
	{
		return controlRow(panel, keyName, control, new SyncGuard(), installListener, reapply, postResync);
	}

	/**
	 * The same ceremony over a caller-supplied guard — the shape sites
	 * take when several controls mirror one stored value and must share
	 * the guard across the group rather than each minting their own.
	 */
	static <C extends JComponent> C controlRow(ShortestPathPanel panel, String keyName, C control,
		SyncGuard guard, BiConsumer<C, SyncGuard> installListener,
		Runnable reapply, Runnable postResync)
	{
		installListener.accept(control, guard);
		listen(panel, keyName, guard, reapply, postResync);
		return control;
	}
}

package shortestpath;

import java.util.*;
import lombok.Getter;
import lombok.experimental.Accessors;

/**
 * A lightweight hash map keyed by primitive {@code int} values using an open-addressed table with
 * linear probing.
 * <p>
 * Keys and values are stored in two parallel arrays ({@link #keys} / {@link #values}) rather than a
 * node object per entry, so the map holds only a couple of arrays regardless of how many entries it
 * contains (issue #491). A slot is occupied iff its value reference is non-null; since null values
 * are rejected, {@code int} keys including {@code 0} need no separate sentinel. When the entry count
 * reaches the configured {@linkplain #capacity load threshold} the table is rehashed into a larger
 * power-of-two array.
 * <p>
 * This implementation is intentionally minimal and tailored for the plugin's pathfinding needs:
 * <ul>
 * <li>No support for removing entries.</li>
 * <li>No iteration views (keys, values, or entry set) are exposed beyond {@link #keys()}.</li>
 * <li>Duplicate key insertion replaces the previous value, or appends collection contents when both
 * the old and new values are {@link Collection}s (best effort; falls back to replacement on
 * errors).</li>
 * </ul>
 *
 * @param <V> the value type stored for each primitive {@code int} key. Must be non-null.
 */
public class PrimitiveIntHashMap<V>
{
	private static final int MINIMUM_SIZE = 8;

	// How full the map should get before growing it again. Smaller values speed up
	// lookup times at the expense of space
	private static final float DEFAULT_LOAD_FACTOR = 0.75f;
	private final float loadFactor;
	private int[] keys;
	private Object[] values;
	@Getter @Accessors(fluent = true) private int size;
	private int capacity;
	private int maxSize;
	private int mask;

	/**
	 * Creates a new map with the specified initial size and the default load factor (0.75).
	 *
	 * @param initialSize initial expected number of elements; rounded to the next power of two
	 *                    internally.
	 */
	public PrimitiveIntHashMap(int initialSize)
	{
		this(initialSize, DEFAULT_LOAD_FACTOR);
	}

	/**
	 * Creates a new map with the given initial size and load factor.
	 *
	 * @param initialSize initial expected number of elements; rounded up to maintain a
	 *                    power-of-two capacity.
	 * @param loadFactor  a value in the range {@code [0.0, 1.0]} determining when the map rehashes.
	 * @throws IllegalArgumentException if {@code loadFactor} is outside the inclusive range 0..1.
	 */
	public PrimitiveIntHashMap(int initialSize, float loadFactor)
	{
		if (loadFactor < 0.0f || loadFactor > 1.0f)
		{
			throw new IllegalArgumentException("Load factor must be between 0 and 1");
		}

		this.loadFactor = loadFactor;
		size = 0;
		setNewSize(initialSize);
		recreateArrays();
	}

	/**
	 * Hash function tuned for packed world point integer encodings. Mixes higher bits downward to
	 * reduce clustering while remaining inexpensive.
	 */
	private static int hash(int value)
	{
		// Full multiplicative avalanche. Linear probing is very sensitive to clustering, and packed
		// world points of nearby tiles differ only in a few low bits, so the cheap xor-shift mix used
		// previously left spatially-clustered transport origins clustered in the table too -> long
		// probe runs on the per-tile miss lookups. Fibonacci-style multiply + xorshift spreads them.
		int h = value * 0x9E3779B1;
		return h ^ (h >>> 16);
	}

	/**
	 * Returns the number of key/value pairs currently stored.
	 *
	 * @return current entry count (always {@code >= 0}).
	 */


	/**
	 * Returns all keys present in the map as a freshly allocated {@code int[]}.
	 *
	 * @return array of all keys in unspecified order; length equals {@link #size()}.
	 */
	@SuppressWarnings("unused")
	public int[] keys()
	{
		int[] result = new int[size];
		int index = 0;
		for (int i = 0; i < values.length; ++i)
		{
			if (values[i] != null)
			{
				result[index++] = keys[i];
			}
		}
		return result;
	}

	/**
	 * Retrieves the value mapped to the provided key, or {@code null} if absent.
	 *
	 * @param key primitive key to look up.
	 * @return the mapped value, or {@code null} if the key does not exist.
	 */
	public V get(int key)
	{
		return getOrDefault(key, null);
	}

	/**
	 * Retrieves the value mapped to the provided key.
	 *
	 * @param key          primitive key to look up.
	 * @param defaultValue value to return if the key is not present.
	 * @return the mapped value, or {@code defaultValue} when absent.
	 */
	@SuppressWarnings("unchecked")
	public V getOrDefault(int key, V defaultValue)
	{
		final int slot = findSlot(key);
		if (slot < 0)
		{
			return defaultValue;
		}
		return (V) values[slot];
	}

	/**
	 * Associates the specified value with the given key.
	 * <p>
	 * If a mapping already exists and both the existing and new values implement {@link Collection},
	 * the method attempts to append all elements of the new collection into the existing one. If the
	 * append fails (e.g., due to incompatible element types or an unsupported operation) the existing
	 * value is replaced entirely. Otherwise the existing value is simply replaced.
	 *
	 * @param key   primitive key to insert or update.
	 * @param value non-null value to associate.
	 * @param <E>   inferred element type if both values are collections.
	 * @return the previous value mapped to {@code key} (if any), or {@code null} if inserting a new
	 * entry.
	 * @throws IllegalArgumentException if {@code value} is {@code null}.
	 */
	@SuppressWarnings({"unchecked"})
	public <E> V put(int key, V value)
	{
		if (value == null)
		{
			throw new IllegalArgumentException("Cannot insert a null value");
		}

		int i = (hash(key) & 0x7FFFFFFF) & mask;
		while (values[i] != null)
		{
			if (keys[i] == key)
			{
				V previous = (V) values[i];
				if (previous instanceof Collection<?> && value instanceof Collection<?>)
				{ // append
					try
					{
						Collection<E> prevCollection = (Collection<E>) values[i];
						Collection<E> newCollection = (Collection<E>) value;
						prevCollection.addAll(newCollection);
					}
					catch (ClassCastException | UnsupportedOperationException e)
					{
						// If the collections contain incompatible types or the operation is not
						// supported, just replace instead of append
						values[i] = value;
					}
				}
				else
				{ // replace
					values[i] = value;
				}
				return previous;
			}
			i = (i + 1) & mask;
		}

		keys[i] = key;
		values[i] = value;
		incrementSize();
		return null;
	}

	private int findSlot(int key)
	{
		int i = (hash(key) & 0x7FFFFFFF) & mask;
		while (values[i] != null)
		{
			if (keys[i] == key)
			{
				return i;
			}
			i = (i + 1) & mask;
		}
		return -1;
	}

	private void incrementSize()
	{
		size++;
		if (size >= capacity)
		{
			rehash();
		}
	}

	private int getNewMaxSize(int size)
	{
		int nextPow2 = -1 >>> Integer.numberOfLeadingZeros(size);
		if (nextPow2 >= (Integer.MAX_VALUE >>> 1))
		{
			return (Integer.MAX_VALUE >>> 1) + 1;
		}
		return nextPow2 + 1;
	}

	private void setNewSize(int size)
	{
		if (size < MINIMUM_SIZE)
		{
			size = MINIMUM_SIZE - 1;
		}

		maxSize = getNewMaxSize(size);
		mask = maxSize - 1;
		capacity = (int) (maxSize * loadFactor);
	}

	private void growCapacity()
	{
		setNewSize(maxSize);
	}

	// Grow the table then rehash all the values into it and discard the old arrays
	private void rehash()
	{
		growCapacity();

		final int[] oldKeys = keys;
		final Object[] oldValues = values;
		recreateArrays();

		for (int i = 0; i < oldValues.length; ++i)
		{
			if (oldValues[i] == null)
			{
				continue;
			}

			int slot = (hash(oldKeys[i]) & 0x7FFFFFFF) & mask;
			while (values[slot] != null)
			{
				slot = (slot + 1) & mask;
			}
			keys[slot] = oldKeys[i];
			values[slot] = oldValues[i];
		}
	}

	private void recreateArrays()
	{
		keys = new int[maxSize];
		values = new Object[maxSize];
	}

	/**
	 * Removes all entries from the map. The backing arrays are retained and reused.
	 */
	public void clear()
	{
		size = 0;
		Arrays.fill(values, null);
	}
}

package shortestpath;

import java.util.Arrays;
import lombok.Getter;
import lombok.experimental.Accessors;

/**
 * A minimal, growable list implementation for primitive {@code int} values.
 * <p>
 * This class avoids boxing overhead present in {@link java.util.List Integer}
 * collections
 * by storing values in a backing {@code int[]} that grows as needed. It
 * purposefully
 * implements only the operations required by the pathfinding logic in this
 * plugin; it is
 * <strong>not</strong> a drop‑in replacement for {@link java.util.ArrayList}.
 * <p>
 * The growth policy increases capacity by 50% (similar to {@code ArrayList})
 * when the
 * existing array is exhausted. Capacity never shrinks.
 */
public class PrimitiveIntList
{
	private static final int MAX_ARRAY_SIZE = Integer.MAX_VALUE - 8;

	private int[] elementData;
	@Getter @Accessors(fluent = true) private int size;

	/**
	 * Creates a new list with the specified initial capacity.
	 *
	 * @param initialCapacity the initial length of the backing array (must be
	 *                        {@code >= 0}).
	 * @param initialize      if {@code true}, the {@link #size} is set equal to
	 *                        {@code initialCapacity},
	 *                        effectively pre-filling the logical list with zeroes.
	 *                        If {@code false},
	 *                        the list is created empty.
	 * @throws IllegalArgumentException if {@code initialCapacity < 0}.
	 */
	public PrimitiveIntList(int initialCapacity, boolean initialize)
	{
		if (initialCapacity < 0)
		{
			throw new IllegalArgumentException("Illegal capacity: " + initialCapacity);
		}
		this.elementData = new int[initialCapacity];
		if (initialize)
		{
			size = initialCapacity;
		}
	}

	/**
	 * Creates an empty list with the given backing array capacity.
	 *
	 * @param initialCapacity initial length of the internal array (must be
	 *                        {@code >= 0}).
	 */
	public PrimitiveIntList(int initialCapacity)
	{
		this(initialCapacity, false);
	}

	/**
	 * Creates an empty list with a default initial capacity of 10.
	 */
	public PrimitiveIntList()
	{
		this(10);
	}

	private static int hugeCapacity(int minCapacity)
	{
		if (minCapacity < 0)
		{ // overflow
			throw new OutOfMemoryError();
		}
		return (minCapacity > MAX_ARRAY_SIZE) ? Integer.MAX_VALUE : MAX_ARRAY_SIZE;
	}

	/**
	 * Ensures that the backing array can store at least {@code minCapacity}
	 * elements.
	 * If the current capacity is already sufficient the call is a no-op.
	 *
	 * @param minCapacity the desired minimum capacity (ignored if {@code <= 0}).
	 */
	public void ensureCapacity(int minCapacity)
	{
		if (minCapacity > 0)
		{
			ensureCapacityInternal(minCapacity);
		}
	}

	private void ensureCapacityInternal(int minCapacity)
	{
		if (minCapacity - elementData.length > 0)
		{
			grow(minCapacity);
		}
	}

	private void grow(int minCapacity)
	{
		int oldCapacity = elementData.length;
		int newCapacity = oldCapacity + (oldCapacity >> 1);
		if (newCapacity - minCapacity < 0)
		{
			newCapacity = minCapacity;
		}
		if (newCapacity - MAX_ARRAY_SIZE > 0)
		{
			newCapacity = hugeCapacity(minCapacity);
		}
		elementData = Arrays.copyOf(elementData, newCapacity);
	}

	/**
	 * Returns the number of elements that have been added to (or initialized in)
	 * this list.
	 *
	 * @return current element count (always {@code >= 0}).
	 */


	/**
	 * Indicates whether the list currently holds zero elements.
	 *
	 * @return {@code true} if {@link #size()} is zero; {@code false} otherwise.
	 */
	public boolean isEmpty()
	{
		return size == 0;
	}

	/**
	 * Tests whether the specified primitive value exists in the list.
	 *
	 * @param e the value to search for.
	 * @return {@code true} if the value occurs at least once; {@code false}
	 * otherwise.
	 */
	public boolean contains(int e)
	{
		return indexOf(e) >= 0;
	}

	/**
	 * Returns the index of the first occurrence of the given value, or {@code -1}
	 * if absent.
	 *
	 * @param e the value to locate.
	 * @return zero-based index of the value, or {@code -1} if not found.
	 */
	public int indexOf(int e)
	{
		for (int i = 0; i < size; i++)
		{
			if (e == elementData[i])
			{
				return i;
			}
		}
		return -1;
	}

	/**
	 * Retrieves the value at the specified index.
	 *
	 * @param index zero-based position of the element to return.
	 * @return the value stored at {@code index}.
	 * @throws IndexOutOfBoundsException if {@code index < 0 || index >= size}.
	 */
	public int get(int index)
	{
		rangeCheck(index);
		return elementData[index];
	}

	/**
	 * Reads the list as groups of {@code stride} interleaved values and returns
	 * the value at {@code offset} of every complete group. An incomplete
	 * trailing group is ignored.
	 *
	 * @param stride number of values per group.
	 * @param offset position inside a group of the value to extract.
	 * @return one value per complete group, in list order.
	 * @throws IllegalArgumentException if {@code stride < 1} or {@code offset} is not inside a group.
	 */
	public int[] column(int stride, int offset)
	{
		if (stride < 1 || offset < 0 || offset >= stride)
		{
			throw new IllegalArgumentException("Stride: " + stride + ", Offset: " + offset);
		}
		int[] out = new int[size / stride];
		for (int i = 0; i < out.length; i++)
		{
			out[i] = elementData[i * stride + offset];
		}
		return out;
	}

	/**
	 * Replaces the value at the specified index.
	 *
	 * @param index   zero-based position of the element to overwrite.
	 * @param element the new value.
	 * @return the previous value stored at {@code index}.
	 * @throws IndexOutOfBoundsException if {@code index < 0 || index >= size}.
	 */
	public int set(int index, int element)
	{
		rangeCheck(index);
		int oldValue = elementData[index];
		elementData[index] = element;
		return oldValue;
	}

	/**
	 * Appends a value to the end of the list, growing the backing array if
	 * required.
	 *
	 * @param e value to append.
	 */
	public void add(int e)
	{
		ensureCapacityInternal(size + 1);
		elementData[size++] = e;
	}

	/**
	 * Inserts a value at the specified index, shifting subsequent elements one
	 * position to the right.
	 *
	 * @param index   zero-based insertion point (may be equal to {@link #size()} to
	 *                append).
	 * @param element the value to insert.
	 * @throws IndexOutOfBoundsException if {@code index < 0 || index > size}.
	 */
	public void add(int index, int element)
	{
		rangeCheckForAdd(index);
		ensureCapacityInternal(size + 1);
		System.arraycopy(elementData, index, elementData, index + 1, size - index);
		elementData[index] = element;
		size++;
	}

	/**
	 * Removes the first occurrence of the specified value, if present.
	 *
	 * @param e value to remove.
	 * @return {@code true} if a value was removed; {@code false} otherwise.
	 */
	public boolean remove(int e)
	{
		for (int i = 0; i < size; i++)
		{
			if (e == elementData[i])
			{
				fastRemove(i);
				return true;
			}
		}
		return false;
	}

	private void fastRemove(int index)
	{
		int numMoved = size - index - 1;
		if (numMoved > 0)
		{
			System.arraycopy(elementData, index + 1, elementData, index, numMoved);
		}
		elementData[--size] = 0;
	}

	/**
	 * Removes all elements from the list and resets {@link #size()} to zero.
	 * The backing array is retained for reuse.
	 */
	public void clear()
	{
		for (int i = 0; i < size; i++)
		{
			elementData[i] = 0;
		}
		size = 0;
	}

	private void rangeCheck(int index)
	{
		if (index >= size)
		{
			throw new IndexOutOfBoundsException("Index: " + index + ", Size: " + size);
		}
	}

	private void rangeCheckForAdd(int index)
	{
		if (index > size || index < 0)
		{
			throw new IndexOutOfBoundsException("Index: " + index + ", Size: " + size);
		}
	}
}

package shortestpath;

import java.awt.*;
import java.util.*;
import java.util.List;
import javax.swing.*;
import javax.swing.border.EmptyBorder;
import net.runelite.api.Client;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.ui.*;
import net.runelite.client.ui.components.shadowlabel.JShadowedLabel;
import shortestpath.items.*;
import shortestpath.requirement.TeleportRestriction;
import shortestpath.settings.*;

/**
 * The Teleport Restrictions checklist: one row per {@link TeleportRestriction.Family}
 * with an icon, name, allow-checkbox and a chevron expander revealing the
 * per-family "min. tiles saved" override. Checked means routable; unchecking
 * writes every member id to the {@code blockedTeleportItems} CSV, checking
 * removes them, and a spinner value &gt; 0 writes {@code id:N} threshold
 * overrides for all member ids.
 *
 * <p>
 * The panel filters itself in {@link #applyFilter(String)} — the owning
 * {@link ShortestPathPanel} treats it as one searchable row and delegates the
 * per-family matching here so a member-label hit can force its row open.
 * Container reads for the Owned filter run on the client thread via
 * {@link ClientThread#invoke}; only the Swing update hops back to the EDT.
 * </p>
 */
class RestrictionListPanel extends JPanel
{
	private static final int ICON_LABEL_GAP = 4;
	private static final int DETAIL_INDENT = ShortestPathPanel.CARD_ICON_SIZE + ICON_LABEL_GAP;
	private static final int SPINNER_FIELD_WIDTH = 6;
	private static final int EXPANDER_WIDTH = 18;

	private final ShortestPathPanel panel;
	private final Settings settings;
	private final Client client;
	private final ClientThread clientThread;
	private final ItemStateService itemState;
	// The owning category's match text (lowercased name + aliases) — the
	// items-disabled hint treats a query that hits it as a name match, so
	// a category rename cannot silently drop the hint's search surface.
	private final String categoryMatchText;

	private final List<RestrictionRow> rows = new ArrayList<>();
	private final Set<Integer> blocked = new HashSet<>();
	private final Map<Integer, Integer> thresholds = new HashMap<>();
	// rep (displayItemId) -> blocked option destinations, parsed from and
	// serialized to rep@dest records in the same blockedTeleportItems CSV.
	private final Map<Integer, Set<Integer>> optionBlocks = new HashMap<>();
	private volatile Set<Integer> ownedIds = Collections.emptySet();

	private final JComponent disabledHint;
	private final JComponent ownedEmpty;
	private final JPanel footer;

	private boolean itemsDisabled;
	private boolean ownedOnly;
	private String lastQuery = "";
	// Set while a config sync mirrors the blocked/threshold model into the
	// controls, so the programmatic selection changes do not write back.
	private boolean syncing;

	RestrictionListPanel(ShortestPathPanel panel, Settings settings, Client client,
		ClientThread clientThread, ItemStateService itemState, String categoryMatchText)
	{
		this.panel = panel;
		this.settings = settings;
		this.client = client;
		this.clientThread = clientThread;
		this.itemState = itemState;
		this.categoryMatchText = categoryMatchText;

		setLayout(new DynamicGridLayout(0, 1, 0, 3));
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		TeleportRestriction.parseBlocked(blockedCsv(), blocked, thresholds, optionBlocks);
		itemsDisabled = TeleportationItem.NONE.equals(
			settings.configured("useTeleportationItems"));

		// checklistFamilies adds the code-defined fairy-staff family to the
		// generated map — the injected ring requirement is restrictable like
		// an item family's ids but no TSV row owns it.
		for (TeleportRestriction.Family family : TeleportRestriction.checklistFamilies())
		{
			rows.add(new RestrictionRow(family));
		}

		// HTML wrapping makes the label word-wrap at column width — plain
		// text renders as a single clipped line.
		disabledHint = hintLabel(ShortestPathPanel.html(
			ShortestPathPanel.RESTRICTIONS_DISABLED_HINT));
		ownedEmpty = hintLabel(ShortestPathPanel.html(
			ShortestPathPanel.OWNED_EMPTY_LINE_1 + "<br>" + ShortestPathPanel.OWNED_EMPTY_LINE_2));

		footer = new JPanel(new BorderLayout());
		footer.setOpaque(false);
		footer.setBorder(new EmptyBorder(8, 0, 4, 0));
		JButton reset = new JButton("Reset Restrictions");
		reset.addActionListener(e -> confirmReset());
		footer.add(reset, BorderLayout.CENTER);

		// External edits to either key rebuild the checklist state in place.
		panel.registerConfigListener("blockedTeleportItems", this::syncFromConfig);
		panel.registerConfigListener("useTeleportationItems", this::syncFromConfig);

		refreshOwnedItems();
		applyFilter("");
	}

	/**
	 * Rebuilds the visible row set for {@code query}. Returns false when the
	 * query matches nothing and the section should drop out of the layout —
	 * except for the owned-filter empty state, which renders pinned copy
	 * inside the section rather than collapsing it.
	 */
	boolean applyFilter(String query)
	{
		lastQuery = query;
		removeAll();
		boolean showing = true;

		if (itemsDisabled)
		{
			// The hint still honours the search filter: a non-matching query
			// drops the section like every other, while a category-name hit
			// keeps it.
			showing = query.isEmpty() || categoryMatchText.contains(query);
			if (showing)
			{
				add(disabledHint);
			}
		}
		else
		{
			boolean anyShown = false;
			for (RestrictionRow row : rows)
			{
				if (query.isEmpty())
				{
					row.clearSearchExpanded();
				}
				boolean matches = query.isEmpty() || row.searchText.contains(query);
				boolean ownedOk = !ownedOnly || row.isOwned();
				if (matches && ownedOk)
				{
					add(row);
					anyShown = true;
					// A hit on a member label rather than the family name
					// opens the row detail so the matched item is visible.
					if (!query.isEmpty() && !row.nameLower.contains(query))
					{
						row.setSearchExpanded();
					}
				}
			}

			if (anyShown)
			{
				add(footer);
			}
			else
			{
				showing = false;
				if (query.isEmpty() && ownedOnly)
				{
					add(ownedEmpty);
					showing = true;
				}
			}
		}

		revalidate();
		repaint();
		return showing;
	}

	/**
	 * The destination group {@code canonicalDest}'s option covers for the
	 * family headed by {@code rep}, or {@code null} when it resolves to no
	 * option group.
	 */
	private static Set<Integer> optionGroup(int rep, int canonicalDest)
	{
		Map<Integer, Set<Integer>> repIndex =
			TeleportRestriction.optionExpansionIndex().get(rep);
		return repIndex == null ? null : repIndex.get(canonicalDest);
	}

	/**
	 * Whether {@code canonicalDest}'s option is blocked for the family
	 * headed by {@code rep}: the recorded set blocks the option when it
	 * intersects the option's whole destination group — not only when it
	 * names the canonical key. The engine expands any member destination
	 * to the full option ({@link TeleportRestriction#expandOptionDests}),
	 * so a record naming a non-canonical member — a hand edit, or a TSV
	 * reorder that changed which destination is first-seen — blocks the
	 * option, and the checkbox must render the same way. Falls back to the
	 * literal canonical key when the destination resolves to no group.
	 */
	private boolean isOptionBlocked(int rep, int canonicalDest)
	{
		Set<Integer> recorded = optionBlocks.getOrDefault(rep, Set.of());
		Set<Integer> group = optionGroup(rep, canonicalDest);
		return group == null
			? recorded.contains(canonicalDest)
			: !Collections.disjoint(group, recorded);
	}

	/**
	 * Removes every recorded destination of {@code canonicalDest}'s option
	 * group — canonical and non-canonical member records alike — so
	 * re-checking the option box genuinely unblocks an option whose stored
	 * record named a non-canonical member tile.
	 */
	private void clearOptionBlock(int rep, int canonicalDest)
	{
		Set<Integer> recorded = optionBlocks.get(rep);
		if (recorded == null)
		{
			return;
		}
		Set<Integer> group = optionGroup(rep, canonicalDest);
		if (group == null)
		{
			recorded.remove(canonicalDest);
		}
		else
		{
			recorded.removeAll(group);
		}
		if (recorded.isEmpty())
		{
			// No rep key with an empty set — empty
			// records must never serialize.
			optionBlocks.remove(rep);
		}
	}

	/**
	 * The number of active restriction records — bare blocked ids,
	 * {@code id:N} threshold overrides and {@code rep@dest} option blocks
	 * alike — the "N restricted" status the home tile shows. All three
	 * kinds suppress routes, so a CSV holding only option blocks or
	 * thresholds must not read "All allowed".
	 */
	int restrictionCount()
	{
		int count = blocked.size() + thresholds.size();
		for (Set<Integer> dests : optionBlocks.values())
		{
			count += dests.size();
		}
		return count;
	}

	/**
	 * The display names of the families a query would surface: every family
	 * whose {@code searchText} (name + member labels) contains the query and
	 * that passes the current owned-only filter. An empty query lists every
	 * visible family; teleportation-items-disabled lists nothing because the
	 * hint replaces the rows entirely.
	 */
	List<String> matchingLabels(String query)
	{
		List<String> labels = new ArrayList<>();
		if (itemsDisabled)
		{
			return labels;
		}
		for (RestrictionRow row : rows)
		{
			boolean matches = query.isEmpty() || row.searchText.contains(query);
			boolean ownedOk = !ownedOnly || row.isOwned();
			if (matches && ownedOk)
			{
				labels.add(ShortestPathPanel.titleCase(row.family.name()));
			}
		}
		return labels;
	}

	/**
	 * Display-only filter: with {@code ownedOnly} set, families with no member
	 * id found in inventory, equipment or bank drop out of the list. Routing
	 * semantics are untouched — the config CSV is never written here.
	 */
	void setOwnedOnly(boolean ownedOnly)
	{
		this.ownedOnly = ownedOnly;
		refreshOwnedItems();
		applyFilter(lastQuery);
	}

	/**
	 * Re-reads inventory, equipment and bank contents for the Owned filter.
	 * The container reads run on the client thread; the Swing rebuild hops
	 * back to the EDT. The bank contributes its live container while open
	 * plus the per-account last-seen snapshot the item-state service persists
	 * — bank items keep counting as owned once the bank is closed and across
	 * sessions, without any per-session open requirement.
	 */
	void refreshOwnedItems()
	{
		clientThread.invoke(() ->
		{
			Map<Integer, Integer> owned = OwnedItems.collect(
				client.getItemContainer(InventoryID.INV),
				client.getItemContainer(InventoryID.WORN),
				client.getItemContainer(InventoryID.BANK));
			// The last-seen snapshot may only add ids the live containers
			// lack — a stale extra id keeps its family listed, which is
			// exactly the wanted behavior.
			owned.putAll(itemState.lastSeenBank());
			SwingUtilities.invokeLater(() ->
			{
				ownedIds = owned.keySet();
				if (ownedOnly)
				{
					applyFilter(lastQuery);
				}
			});
		});
	}

	/**
	 * Re-reads the hidden CSV key + the teleportation-items mode and mirrors
	 * them into every row. Runs under the {@link #syncing} guard, so the
	 * setValue / setSelected calls this triggers never write back to config.
	 */
	private void syncFromConfig()
	{
		blocked.clear();
		thresholds.clear();
		optionBlocks.clear();
		TeleportRestriction.parseBlocked(blockedCsv(), blocked, thresholds, optionBlocks);
		itemsDisabled = TeleportationItem.NONE.equals(
			settings.configured("useTeleportationItems"));
		syncing = true;
		try
		{
			for (RestrictionRow row : rows)
			{
				row.syncFromModel();
			}
		}
		finally
		{
			syncing = false;
		}
		applyFilter(lastQuery);
	}

	private String blockedCsv()
	{
		Object csv = settings.configured("blockedTeleportItems");
		return csv instanceof String ? (String) csv : "";
	}

	private void writeCsv()
	{
		// A family the master row has fully blocked (rep id in blocked)
		// never emits rep@dest records — stale records would resurface the
		// option blocks on unblock. Empty sets never serialize either.
		Map<Integer, Set<Integer>> serializableBlocks = new HashMap<>();
		for (Map.Entry<Integer, Set<Integer>> entry : optionBlocks.entrySet())
		{
			if (!blocked.contains(entry.getKey()) && !entry.getValue().isEmpty())
			{
				serializableBlocks.put(entry.getKey(), entry.getValue());
			}
		}
		settings.write("blockedTeleportItems",
			TeleportRestriction.toCsv(blocked, thresholds, serializableBlocks));
	}

	private void confirmReset()
	{
		int result = JOptionPane.showOptionDialog(this,
			"Remove all teleport restrictions? All blocked items will be re-enabled.",
			"Reset Restrictions",
			JOptionPane.YES_NO_OPTION,
			JOptionPane.WARNING_MESSAGE,
			null,
			new String[]{"Yes", "No"},
			"No");
		if (result == JOptionPane.YES_OPTION)
		{
			blocked.clear();
			thresholds.clear();
			optionBlocks.clear();
			writeCsv();
		}
	}

	private static JComponent hintLabel(String text)
	{
		JShadowedLabel label = new JShadowedLabel(text);
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		label.setHorizontalAlignment(SwingConstants.CENTER);
		label.setBorder(new EmptyBorder(8, 8, 8, 8));
		JPanel wrapper = new JPanel(new BorderLayout());
		wrapper.setOpaque(false);
		wrapper.add(label, BorderLayout.CENTER);
		return wrapper;
	}

	/**
	 * One family row: icon + name + allow checkbox + chevron expander on the
	 * header line, with the threshold spinner in the collapsible detail well.
	 */
	private final class RestrictionRow extends ExpandableSurface
	{
		final TeleportRestriction.Family family;
		final String nameLower;
		final String searchText;

		private final JLabel iconLabel;
		private final JLabel nameLabel;
		private final JCheckBox allow;
		private final JSpinner thresholdSpinner;
		// canonical packedDest -> option checkbox, in the options map's
		// first-seen order — kept so syncFromModel can mirror external edits.
		private final Map<Integer, JCheckBox> optionBoxes = new LinkedHashMap<>();

		RestrictionRow(TeleportRestriction.Family family)
		{
			super(new EmptyBorder(4, DETAIL_INDENT, 4, 0));
			this.family = family;
			this.nameLower = family.name().toLowerCase(Locale.ROOT);
			StringBuilder sb = new StringBuilder(nameLower);
			for (String label : family.memberLabels().values())
			{
				sb.append(' ').append(label.toLowerCase(Locale.ROOT));
			}
			for (String optionLabel : family.options().values())
			{
				sb.append(' ').append(optionLabel.toLowerCase(Locale.ROOT));
			}
			this.searchText = sb.toString();

			setOpaque(false);
			setBorder(new EmptyBorder(4, 0, 4, 0));

			JPanel header = new JPanel(new BorderLayout(ICON_LABEL_GAP, 0));

			iconLabel = new JLabel();
			iconLabel.setPreferredSize(new Dimension(
				ShortestPathPanel.CARD_ICON_SIZE, ShortestPathPanel.CARD_ICON_SIZE));
			iconLabel.setHorizontalAlignment(SwingConstants.CENTER);
			panel.loadItemIcon(family.displayItemId(), iconLabel);
			header.add(iconLabel, BorderLayout.WEST);

			// The wrap makes long family names break onto a second line at
			// row width instead of clipping; Title Case matches the config
			// names (the raw name stays the search identity below).
			nameLabel = new JLabel(ShortestPathPanel.html(
				ShortestPathPanel.titleCase(family.name())));
			// Clicking the label expands the row; the uncheck tooltip belongs
			// on the checkbox alone. The label tooltip carries the full family
			// name for names that clip at row width.
			nameLabel.setToolTipText(ShortestPathPanel.html(family.name()));
			header.add(nameLabel, BorderLayout.CENTER);

			JPanel controls = new JPanel();
			controls.setOpaque(false);
			controls.setLayout(new BoxLayout(controls, BoxLayout.X_AXIS));

			expander = newExpander();
			expander.setPreferredSize(new Dimension(EXPANDER_WIDTH, 0));
			controls.add(expander);

			allow = new JCheckBox();
			// Selected state is set before the listener is attached so
			// construction never fires a spurious config write.
			allow.setSelected(!isBlocked());
			allow.setToolTipText(ShortestPathPanel.html("Uncheck to never route via " + family.name()));
			allow.addActionListener(e ->
			{
				boolean allowed = allow.isSelected();
				applyAllowedState(allowed);
				if (!syncing)
				{
					if (allowed)
					{
						family.memberItemIds().forEach(blocked::remove);
					}
					else
					{
						blocked.addAll(family.memberItemIds());
						// Blocking supersedes any per-item threshold override.
						family.memberItemIds().forEach(thresholds::remove);
					}
					writeCsv();
				}
			});
			controls.add(allow);
			header.add(controls, BorderLayout.EAST);

			// Clicking anywhere on the header (icon/name area) also toggles the
			// detail well, mirroring the transport cards.
			add(header);
			installExpandListener(header, iconLabel, nameLabel);

			// The shared expandable chrome: the header paints as an
			// opaque dark bar while the detail well keeps the category
			// background behind a thin orange border, like the cards.
			ShortestPathPanel.styleExpandable(header, detail);

			JPanel thresholdRow = new JPanel(new BorderLayout());
			thresholdRow.setOpaque(false);
			JLabel thresholdLabel = new JLabel(ShortestPathPanel.html("Min. Tiles Saved"));
			thresholdLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			thresholdLabel.setFont(FontManager.getRunescapeSmallFont());
			String thresholdTooltip = "Tiles this teleport must save to be used. 0 uses the family threshold.";
			thresholdLabel.setToolTipText(ShortestPathPanel.html(thresholdTooltip));
			thresholdRow.add(thresholdLabel, BorderLayout.CENTER);

			thresholdSpinner = new JSpinner(new SpinnerNumberModel(
				Integer.valueOf(currentThreshold()), Integer.valueOf(0), null, Integer.valueOf(1)));
			((JSpinner.DefaultEditor) thresholdSpinner.getEditor()).getTextField()
				.setColumns(SPINNER_FIELD_WIDTH);
			thresholdSpinner.setToolTipText(ShortestPathPanel.html(thresholdTooltip));
			thresholdSpinner.addChangeListener(e ->
			{
				if (syncing)
				{
					return;
				}
				int value = ((Number) thresholdSpinner.getValue()).intValue();
				if (value > 0)
				{
					for (int id : family.memberItemIds())
					{
						thresholds.put(id, value);
					}
				}
				else
				{
					family.memberItemIds().forEach(thresholds::remove);
				}
				writeCsv();
			});
			thresholdRow.add(thresholdSpinner, BorderLayout.EAST);
			detail.add(thresholdRow);

			if (family.options().size() > 1)
			{
				buildOptionsBlock();
			}
			add(detail);

			syncFromModel();
		}

		/**
		 * The "Options:" section of the detail well: one checkbox per
		 * in-game teleport name (the option group's label), checked when
		 * the option is routable. Unchecking writes a {@code rep@dest}
		 * record keyed on the family's displayItemId and the option's
		 * canonical (first-seen) destination; re-checking removes it.
		 * The block lives inside the existing detail well — no new
		 * top-level rows, so collapsed families stay one line each.
		 */
		private void buildOptionsBlock()
		{
			JLabel optionsHeader = new JLabel("Options:");
			optionsHeader.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			optionsHeader.setFont(FontManager.getRunescapeSmallFont());
			detail.add(optionsHeader);

			int rep = family.displayItemId();
			for (Map.Entry<Integer, String> option : family.options().entrySet())
			{
				int dest = option.getKey();
				String label = option.getValue();
				if (label == null || label.isBlank())
				{
					// Labels arrive pre-derived and are never blank in
					// practice — fall back to the unpacked coordinates so a
					// checkbox never renders unlabeled.
					WorldPoint point = WorldPointUtil.unpackWorldPoint(dest);
					label = point.getX() + ", " + point.getY() + ", " + point.getPlane();
				}
				JCheckBox optionBox = new JCheckBox(ShortestPathPanel.html(label));
				optionBox.setFont(FontManager.getRunescapeSmallFont());
				// Selected state is set before the listener attaches, so
				// construction never fires a spurious config write — the
				// same discipline the master allow checkbox uses.
				optionBox.setSelected(!isOptionBlocked(rep, dest));
				optionBox.addActionListener(e ->
				{
					if (syncing)
					{
						return;
					}
					if (optionBox.isSelected())
					{
						clearOptionBlock(rep, dest);
					}
					else
					{
						optionBlocks.computeIfAbsent(rep, k -> new HashSet<>()).add(dest);
					}
					writeCsv();
				});
				optionBoxes.put(dest, optionBox);
				detail.add(optionBox);
			}
		}

		/**
		 * The row counts as blocked when any member id is in the blocked set —
		 * a partially blocked CSV renders unchecked, and re-checking clears all
		 * member ids back to allowed.
		 */
		boolean isBlocked()
		{
			for (int id : family.memberItemIds())
			{
				if (blocked.contains(id))
				{
					return true;
				}
			}
			return false;
		}

		boolean isOwned()
		{
			for (int id : family.memberItemIds())
			{
				if (ownedIds.contains(id))
				{
					return true;
				}
			}
			return false;
		}

		private int currentThreshold()
		{
			int current = 0;
			for (int id : family.memberItemIds())
			{
				current = Math.max(current, thresholds.getOrDefault(id, 0));
			}
			return current;
		}

		/**
		 * Mirrors the blocked/threshold/option-block model into the
		 * controls. Safe under the syncing guard: suppressed listeners skip
		 * the config write.
		 */
		void syncFromModel()
		{
			boolean blockedNow = isBlocked();
			allow.setSelected(!blockedNow);
			thresholdSpinner.setValue(currentThreshold());
			for (Map.Entry<Integer, JCheckBox> entry : optionBoxes.entrySet())
			{
				entry.getValue().setSelected(
					!isOptionBlocked(family.displayItemId(), entry.getKey()));
			}
			applyAllowedState(!blockedNow);
		}

		private void applyAllowedState(boolean allowed)
		{
			nameLabel.setForeground(allowed ? Color.WHITE : ColorScheme.LIGHT_GRAY_COLOR);
			iconLabel.setEnabled(allowed);
			expander.setEnabled(allowed);
			ShortestPathPanel.applyRowDisabledState(detail, allowed);
		}

		/** The header name — {@link SearchExpandable} reads it to tell
		 * name-label matches from detail-label matches. */
		@Override
		public JLabel getNameLabel()
		{
			return nameLabel;
		}
	}
}

package shortestpath;

import javax.swing.JLabel;

/**
 * A category row component whose detail well search can force open: when
 * a query matches one of the row's detail/member labels rather than its
 * own name, {@code CategoryPanel.applyQuery} calls
 * {@link #setSearchExpanded()} so the matched control is visible, and
 * {@link #clearSearchExpanded()} on an empty query restores the collapsed
 * state (only expansions search itself performed collapse back).
 */
interface SearchExpandable
{
	void setSearchExpanded();

	void clearSearchExpanded();

	/**
	 * The label holding the component's own display name — a query
	 * contained here counts as a name match (no force-expand needed).
	 */
	JLabel getNameLabel();
}

