package shortestpath;

import java.awt.*;
import java.awt.event.ItemEvent;
import javax.swing.*;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.components.DimmableJPanel;
import lombok.*;

/**
 * One transport-family card in the sidebar panel: a 16px icon slot, the family
 * name, a chevron expander (only rendered once detail content exists) and the
 * family's master control on the right edge. Boolean masters render a checkbox;
 * enum-valued masters (teleportation items) render an enum combo. Detail rows
 * live in an indented well that is dimmed and disabled while the master is off.
 */
class TransportFamilyCard extends ExpandableSurface
{
	private static final int ICON_LABEL_GAP = 4;
	private static final int DETAIL_INDENT = ShortestPathPanel.CARD_ICON_SIZE + ICON_LABEL_GAP;

	private final ShortestPathPanel panel;
	@Getter(AccessLevel.PACKAGE) private final String keyName;
	// True when the family's on/off state is owned by a control elsewhere
	// (the teleport-items mode combo lives in the plugin configuration):
	// no master control renders, and isMasterOn() reads the configured
	// value directly.
	private final boolean masterless;
	// True when the card drops the collapsible chrome entirely — no
	// expander, no framed well, detail always expanded. A card that is a
	// section's only row (the house card) uses this so it reads like a
	// plain labelled group instead of a lone boxed expander.
	private final boolean flat;

	private final DimmableJPanel header;
	private final JPanel nameArea;
	private final JLabel iconLabel;
	@Getter private final JLabel nameLabel;
	private final JPanel headerControls;
	@Getter(AccessLevel.PACKAGE) private final JComponent masterControl;
	// Held while a config sync mirrors values into the controls, so the
	// programmatic selection changes do not write back to config.
	private final PanelRows.SyncGuard syncing = new PanelRows.SyncGuard();

	TransportFamilyCard(ShortestPathPanel panel, String keyName, String title, String description, Integer iconItemId)
	{
		this(panel, keyName, title, description, iconItemId, false);
	}

	TransportFamilyCard(ShortestPathPanel panel, String keyName, String title, String description, Integer iconItemId,
		boolean masterless)
	{
		this(panel, keyName, title, description, iconItemId, masterless, false);
	}

	TransportFamilyCard(ShortestPathPanel panel, String keyName, String title, String description, Integer iconItemId,
		boolean masterless, boolean flat)
	{
		// Indented under the icon column so detail rows line up with the name.
		super(new EmptyBorder(4, DETAIL_INDENT, 4, 0));
		this.panel = panel;
		this.keyName = keyName;
		this.masterless = masterless;
		this.flat = flat;

		setBackground(ColorScheme.DARKER_GRAY_COLOR);
		setBorder(new EmptyBorder(4, 8, 4, 8));

		header = new DimmableJPanel();
		header.setLayout(new BorderLayout());

		nameArea = new JPanel(new BorderLayout(ICON_LABEL_GAP, 0));
		nameArea.setOpaque(false);

		iconLabel = new JLabel();
		iconLabel.setPreferredSize(new Dimension(ShortestPathPanel.CARD_ICON_SIZE, ShortestPathPanel.CARD_ICON_SIZE));
		iconLabel.setHorizontalAlignment(SwingConstants.CENTER);
		if (iconItemId != null)
		{
			panel.loadItemIcon(iconItemId, iconLabel);
		}
		nameArea.add(iconLabel, BorderLayout.WEST);

		nameLabel = new JLabel(ShortestPathPanel.html(title));
		nameLabel.setToolTipText(ShortestPathPanel.html(description));
		nameArea.add(nameLabel, BorderLayout.CENTER);
		header.add(nameArea, BorderLayout.CENTER);

		headerControls = new JPanel();
		headerControls.setOpaque(false);
		headerControls.setLayout(new BoxLayout(headerControls, BoxLayout.X_AXIS));

		masterControl = masterless ? null : createMasterControl(description);
		if (masterControl != null)
		{
			headerControls.add(masterControl);
		}
		header.add(headerControls, BorderLayout.EAST);
		add(header);

		add(detail);

		if (flat)
		{
			// No expandable chrome: the card and its rows sit transparent
			// on the section tone, and the detail stays expanded — no
			// expander ever installs, so the toggle paths no-op.
			setOpaque(false);
			header.setOpaque(false);
			detail.setOpaque(false);
			detail.setVisible(true);
		}
		else
		{
			// The shared expandable chrome: dark header bar over the
			// category-toned, orange-bordered detail well.
			ShortestPathPanel.styleExpandable(header, detail);
		}

		applyEnabled(isMasterOn());
		panel.registerConfigListener(keyName, this::syncFromConfig);
	}

	/**
	 * Adds a row to the detail well. The first detail row also installs the
	 * chevron expander and makes the header clickable — cards with no detail
	 * content never grow a dead expander, and flat cards never grow one at
	 * all.
	 */
	void addDetailRow(JComponent row)
	{
		detail.add(row);
		ShortestPathPanel.applyRowDisabledState(row, isMasterOn());
		if (expander == null && !flat)
		{
			expander = newExpander();
			expander.setPreferredSize(new Dimension(ShortestPathPanel.SECTION_TOGGLE_WIDTH, 0));
			expander.setBorder(new EmptyBorder(0, 0, 0, 5));
			headerControls.add(expander, 0);
			installExpandListener(header, nameArea, iconLabel, nameLabel);
		}
		detail.revalidate();
	}

	boolean isMasterOn()
	{
		if (masterless)
		{
			// No master control to ask — the configured value itself says
			// whether the family routes (enums: anything but NONE).
			Object value = panel.settings.configured(keyName);
			if (value instanceof Enum)
			{
				return !"NONE".equals(((Enum<?>) value).name());
			}
			return Boolean.TRUE.equals(value);
		}
		if (masterControl instanceof JCheckBox)
		{
			return ((JCheckBox) masterControl).isSelected();
		}
		Object selected = ((JComboBox<?>) masterControl).getSelectedItem();
		return !(selected instanceof Enum) || !"NONE".equals(((Enum<?>) selected).name());
	}

	/**
	 * Master-off interaction contract: the card stays visible and clickable,
	 * the name label drops to LIGHT_GRAY and the icon + every detail control is
	 * disabled. The master control itself always stays enabled.
	 */
	void applyEnabled(boolean enabled)
	{
		nameLabel.setForeground(enabled ? Color.WHITE : ColorScheme.LIGHT_GRAY_COLOR);
		iconLabel.setEnabled(enabled);
		ShortestPathPanel.applyRowDisabledState(detail, enabled);
	}

	/**
	 * Re-reads the configured master value and mirrors it into the master
	 * control + dim state. The {@link #syncing} guard stops the programmatic
	 * selection change from writing back to config.
	 */
	void syncFromConfig()
	{
		Object value = panel.settings.configured(keyName);
		PanelRows.resync(syncing, () ->
		{
			if (masterControl instanceof JCheckBox)
			{
				((JCheckBox) masterControl).setSelected(Boolean.TRUE.equals(value));
			}
			else if (masterControl instanceof JComboBox && value instanceof Enum)
			{
				((JComboBox<?>) masterControl).setSelectedItem(value);
			}
		}, () ->
		{
			// Masterless cards hold no control to mirror into — only the
			// dim state follows the configured value.
			applyEnabled(isMasterOn());
		});
	}

	private JComponent createMasterControl(String description)
	{
		Object value = panel.settings.configured(keyName);
		if (value instanceof Enum)
		{
			@SuppressWarnings("unchecked")
			Class<? extends Enum> type = (Class<? extends Enum>) ((Enum<?>) value).getClass();
			JComboBox<Enum<?>> combo = new JComboBox<Enum<?>>(type.getEnumConstants()); // NOPMD: UseDiamondOperator
			combo.setSelectedItem(value);
			PanelComboStyle.apply(combo);
			combo.setToolTipText(ShortestPathPanel.html(description));
			combo.addItemListener(e ->
			{
				if (e.getStateChange() == ItemEvent.SELECTED)
				{
					PanelRows.guardedWrite(syncing,
						() -> panel.settings.write(keyName, combo.getSelectedItem()));
					applyEnabled(isMasterOn());
				}
			});
			return combo;
		}

		JCheckBox checkBox = new JCheckBox();
		checkBox.setSelected(Boolean.TRUE.equals(value));
		checkBox.setToolTipText(ShortestPathPanel.html(description));
		checkBox.addActionListener(e ->
		{
			PanelRows.guardedWrite(syncing,
				() -> panel.settings.write(keyName, checkBox.isSelected()));
			applyEnabled(checkBox.isSelected());
		});
		return checkBox;
	}

}

package shortestpath;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.Objects;
import java.util.function.BiConsumer;

/**
 * General utility helpers for I/O and primitive array manipulation used by the
 * shortest path plugin.
 */
public class Util
{
	/**
	 * Reads all bytes from the provided {@link InputStream} until EOF.
	 * This method does not close the stream; the caller retains responsibility for
	 * resource management.
	 *
	 * @param in the input stream to read from.
	 * @return a newly allocated byte array containing all bytes read (may be empty,
	 * never {@code null}).
	 * @throws IOException if an I/O error occurs while reading.
	 */
	public static byte[] readAllBytes(InputStream in) throws IOException
	{
		return in.readAllBytes();
	}

	/**
	 * Reads a bundled TSV resource line by line, invoking {@code row} for
	 * every non-empty, non-{@code #}-comment line with the raw line and its
	 * keep-arity tab-split columns ({@code split("\t", -1)}). The resource is
	 * resolved from an absolute classpath path ({@code "/name.tsv"}) anchored
	 * on {@code Util.class} — identical to each caller's own
	 * {@code *.class.getResourceAsStream} lookup for {@code /}-prefixed
	 * paths. A missing resource throws {@link NullPointerException}; an I/O
	 * failure propagates to the caller so each call site keeps its own error
	 * posture.
	 *
	 * @param path the absolute classpath path of the resource to read.
	 * @param row  consumer invoked once per visited row with the line and its
	 *             columns.
	 * @throws IllegalArgumentException if {@code path} is not absolute.
	 * @throws IOException if an I/O error occurs while reading.
	 */
	public static void each(String path, BiConsumer<String, String[]> row) throws IOException
	{
		if (!path.startsWith("/"))
		{
			throw new IllegalArgumentException("resource path must be absolute: " + path);
		}
		try (BufferedReader reader = new BufferedReader(new InputStreamReader(
			Objects.requireNonNull(Util.class.getResourceAsStream(path)), StandardCharsets.UTF_8)))
		{
			String line;
			while ((line = reader.readLine()) != null)
			{
				if (line.isEmpty() || line.startsWith("#"))
				{
					continue;
				}
				row.accept(line, line.split("\t", -1));
			}
		}
	}

	/**
	 * Reads an entire bundled resource into a UTF-8 {@link String}. Absolute
	 * classpath paths only; a missing resource throws
	 * {@link NullPointerException} and an I/O failure propagates to the
	 * caller.
	 *
	 * @param path the absolute classpath path of the resource to read.
	 * @return the resource contents decoded as UTF-8.
	 * @throws IllegalArgumentException if {@code path} is not absolute.
	 * @throws IOException if an I/O error occurs while reading.
	 */
	public static String resourceString(String path) throws IOException
	{
		if (!path.startsWith("/"))
		{
			throw new IllegalArgumentException("resource path must be absolute: " + path);
		}
		return new String(
			readAllBytes(Objects.requireNonNull(Util.class.getResourceAsStream(path))),
			StandardCharsets.UTF_8);
	}

	/**
	 * Concatenates the contents of multiple {@code int[]} arrays into one
	 * contiguous array.
	 * {@code null} elements in {@code arrays} are skipped. If all arrays are
	 * {@code null} or empty, {@code null}
	 * is returned (this mirrors the existing behavior relied upon by callers).
	 *
	 * @param arrays an array of {@code int[]} segments to concatenate (may contain
	 *               {@code null}).
	 * @return a new combined array, or {@code null} if there are no elements to
	 * copy.
	 */
	public static int[] concatenate(int[][] arrays)
	{
		int n = 0;
		for (int[] value : arrays)
		{
			n += (value == null) ? 0 : value.length;
		}
		if (n == 0)
		{
			return null;
		}
		int[] array = new int[n];
		int k = 0;
		for (int[] ints : arrays)
		{
			if (ints != null)
			{
				for (int anInt : ints)
				{
					array[k++] = anInt;
				}
			}
		}
		return array;
	}
}

package shortestpath;

import net.runelite.api.*;
import static net.runelite.api.Constants.CHUNK_SIZE;
import static net.runelite.api.Perspective.LOCAL_COORD_BITS;
import net.runelite.api.coords.*;

/**
 * Utility functions for packing, unpacking, and transforming {@link WorldPoint}
 * coordinates as compact {@code int} values.
 * <p>
 * A packed world point encodes {@code x}, {@code y}, and {@code plane} into a
 * single 32-bit integer using:
 *
 * <pre>
 * bits 0..14   : x (15 bits)
 * bits 15..29  : y (15 bits)
 * bits 30..31  : plane (2 bits)
 * </pre>
 * <p>
 * This representation allows efficient storage and hashing of coordinates
 * within the pathfinding data structures.
 */
public class WorldPointUtil
{
	public static final int CHEBYSHEV_DISTANCE_METRIC = 1;
	public static final int EUCLIDEAN_SQUARED_DISTANCE_METRIC = 1414213562;
	public static final int MANHATTAN_DISTANCE_METRIC = 2;
	public static final int UNDEFINED = -1;

	/**
	 * Packs a {@link WorldPoint} into a compact {@code int} encoding.
	 *
	 * @param point world point (may be {@code null}).
	 * @return packed integer value, or {@link #UNDEFINED} if {@code point} is
	 * {@code null}.
	 */
	public static int packWorldPoint(WorldPoint point)
	{
		if (point == null)
		{
			return -1;
		}
		return packWorldPoint(point.getX(), point.getY(), point.getPlane());
	}

	/**
	 * Packs the provided coordinate triple into a single {@code int}.
	 * First 15 bits are {@code x}, next 15 bits are {@code y}, final 2 bits are the
	 * plane.
	 * Values are masked into range; overflow bits are discarded.
	 *
	 * @param x     world x (0..32767 effectively supported).
	 * @param y     world y (0..32767 effectively supported).
	 * @param plane plane (0..3).
	 * @return packed integer representation.
	 */
	public static int packWorldPoint(int x, int y, int plane)
	{
		return (x & 0x7FFF) | ((y & 0x7FFF) << 15) | ((plane & 0x3) << 30);
	}

	/**
	 * Unpacks a packed world point into a new {@link WorldPoint} instance.
	 *
	 * @param packedPoint packed coordinate.
	 * @return decoded {@link WorldPoint}.
	 */
	public static WorldPoint unpackWorldPoint(int packedPoint)
	{
		final int x = unpackWorldX(packedPoint);
		final int y = unpackWorldY(packedPoint);
		final int plane = unpackWorldPlane(packedPoint);
		return new WorldPoint(x, y, plane);
	}

	/**
	 * Extracts the x component from a packed world point.
	 *
	 * @param packedPoint packed coordinate.
	 * @return x value.
	 */
	public static int unpackWorldX(int packedPoint)
	{
		return packedPoint & 0x7FFF;
	}

	/**
	 * Extracts the y component from a packed world point.
	 *
	 * @param packedPoint packed coordinate.
	 * @return y value.
	 */
	public static int unpackWorldY(int packedPoint)
	{
		return (packedPoint >> 15) & 0x7FFF;
	}

	/**
	 * Extracts the plane component from a packed world point.
	 *
	 * @param packedPoint packed coordinate.
	 * @return plane value (0..3).
	 */
	public static int unpackWorldPlane(int packedPoint)
	{
		return (packedPoint >> 30) & 0x3;
	}

	/**
	 * Offsets a packed world point by {@code (dx, dy)} on the same plane.
	 *
	 * @param packedPoint base packed point.
	 * @param dx          delta x to add.
	 * @param dy          delta y to add.
	 * @return packed point after applying deltas.
	 */
	public static int dxdy(int packedPoint, int dx, int dy)
	{
		int x = unpackWorldX(packedPoint);
		int y = unpackWorldY(packedPoint);
		int z = unpackWorldPlane(packedPoint);
		return packWorldPoint(x + dx, y + dy, z);
	}

	/**
	 * Computes the distance between two packed points using Chebyshev metric
	 * (diagonal = 1).
	 */
	public static int distanceBetween(int previousPacked, int currentPacked)
	{
		return distanceBetween(previousPacked, currentPacked, 1);
	}

	/**
	 * Computes the 2D distance (ignoring plane) between two packed points using
	 * Chebyshev metric (diagonal = 1).
	 */
	public static int distanceBetween2D(int previousPacked, int currentPacked)
	{
		return distanceBetween2D(previousPacked, currentPacked, 1);
	}

	/**
	 * Computes distance between two packed points with selectable distance metric.
	 *
	 * @param previousPacked first packed point.
	 * @param currentPacked  second packed point.
	 * @param diagonal       {@code 1} for Chebyshev (max), {@code 2} for Manhattan
	 *                       (sum). Otherwise returns Euclidean squared distance.
	 * @return distance or {@code Integer.MAX_VALUE} if plane differs.
	 */
	public static int distanceBetween(int previousPacked, int currentPacked, int diagonal)
	{
		final int previousX = WorldPointUtil.unpackWorldX(previousPacked);
		final int previousY = WorldPointUtil.unpackWorldY(previousPacked);
		final int previousZ = WorldPointUtil.unpackWorldPlane(previousPacked);
		final int currentX = WorldPointUtil.unpackWorldX(currentPacked);
		final int currentY = WorldPointUtil.unpackWorldY(currentPacked);
		final int currentZ = WorldPointUtil.unpackWorldPlane(currentPacked);
		return distanceBetween(previousX, previousY, previousZ,
			currentX, currentY, currentZ, diagonal);
	}

	/**
	 * Computes 2D distance (ignoring plane) between two packed points with
	 * selectable metric.
	 *
	 * @see #distanceBetween(int, int, int, int, int, int, int)
	 */
	public static int distanceBetween2D(int previousPacked, int currentPacked, int diagonal)
	{
		final int previousX = WorldPointUtil.unpackWorldX(previousPacked);
		final int previousY = WorldPointUtil.unpackWorldY(previousPacked);
		final int currentX = WorldPointUtil.unpackWorldX(currentPacked);
		final int currentY = WorldPointUtil.unpackWorldY(currentPacked);
		return distanceBetween2D(previousX, previousY, currentX, currentY, diagonal);
	}

	/**
	 * Computes distance between two coordinates with selectable metric; returns
	 * {@code Integer.MAX_VALUE} if planes differ.
	 *
	 * @param previousX x of first point.
	 * @param previousY y of first point.
	 * @param previousZ plane of first point.
	 * @param currentX  x of second point.
	 * @param currentY  y of second point.
	 * @param currentZ  plane of second point.
	 * @param diagonal  metric selector ({@code 1}=Chebyshev, {@code 2}=Manhattan,
	 *                  otherwise Euclidean squared distance).
	 * @return distance or {@code Integer.MAX_VALUE} if planes differ.
	 */
	public static int distanceBetween(
		int previousX,
		int previousY,
		int previousZ,
		int currentX,
		int currentY,
		int currentZ,
		int diagonal)
	{
		final int dz = previousZ - currentZ;

		if (dz != 0)
		{
			return Integer.MAX_VALUE;
		}

		return distanceBetween2D(previousX, previousY, currentX, currentY, diagonal);
	}

	/**
	 * Computes a 2D distance using either Chebyshev, Manhattan or Euclidean squared
	 * distance metric.
	 *
	 * @param previousX x of first point.
	 * @param previousY y of first point.
	 * @param currentX  x of second point.
	 * @param currentY  y of second point.
	 * @param diagonal  metric selector ({@code 1}=Chebyshev, {@code 2}=Manhattan,
	 *                  otherwise Euclidean squared distance).
	 * @return distance.
	 */
	public static int distanceBetween2D(int previousX, int previousY,
		int currentX, int currentY, int diagonal)
	{
		final int dx = previousX - currentX;
		final int dy = previousY - currentY;

		if (diagonal == CHEBYSHEV_DISTANCE_METRIC)
		{
			return Math.max(Math.abs(dx), Math.abs(dy));
		}
		else if (diagonal == MANHATTAN_DISTANCE_METRIC)
		{
			return Math.abs(dx) + Math.abs(dy);
		}

		return dx * dx + dy * dy;
	}

	/**
	 * Convenience overload using Chebyshev distance between two
	 * {@link WorldPoint}s.
	 */
	public static int distanceBetween(WorldPoint previous, WorldPoint current)
	{
		return distanceBetween(previous, current, 1);
	}

	/**
	 * Distance between two {@link WorldPoint}s with selectable metric.
	 *
	 * @see #distanceBetween(int, int, int, int, int, int, int)
	 */
	public static int distanceBetween(WorldPoint previous, WorldPoint current, int diagonal)
	{
		return distanceBetween(previous.getX(), previous.getY(), previous.getPlane(),
			current.getX(), current.getY(), current.getPlane(), diagonal);
	}

	/**
	 * 2D distance (Chebyshev) from a packed point to a {@link WorldArea} ignoring
	 * plane, equivalent to
	 * {@link WorldArea#distanceTo(WorldPoint)} semantics in 2D.
	 */
	public static int distanceToArea2D(int packedPoint, WorldArea area)
	{
		final int y = unpackWorldY(packedPoint);
		final int x = unpackWorldX(packedPoint);
		final int areaMaxX = area.getX() + area.getWidth() - 1;
		final int areaMaxY = area.getY() + area.getHeight() - 1;
		final int dx = Math.max(Math.max(area.getX() - x, 0), x - areaMaxX);
		final int dy = Math.max(Math.max(area.getY() - y, 0), y - areaMaxY);

		return Math.max(dx, dy);
	}

	private static int rotate(int originalX, int originalY, int z, int rotation)
	{
		int chunkX = originalX & -CHUNK_SIZE;
		int chunkY = originalY & -CHUNK_SIZE;
		int x = originalX & (CHUNK_SIZE - 1);
		int y = originalY & (CHUNK_SIZE - 1);
		switch (rotation)
		{
			case 1:
				return packWorldPoint(chunkX + y, chunkY + (CHUNK_SIZE - 1 - x), z);
			case 2:
				return packWorldPoint(chunkX + (CHUNK_SIZE - 1 - x), chunkY + (CHUNK_SIZE - 1 - y), z);
			case 3:
				return packWorldPoint(chunkX + (CHUNK_SIZE - 1 - y), chunkY + x, z);
		}
		return packWorldPoint(originalX, originalY, z);
	}

	private static int unpackChunkRotation(int chunkData)
	{
		return chunkData >> 1 & 0x3;
	}

	private static int unpackChunkTemplateY(int chunkData)
	{
		return (chunkData >> 3 & 0x7FF) * CHUNK_SIZE;
	}

	private static int unpackChunkTemplateX(int chunkData)
	{
		return (chunkData >> 14 & 0x3FF) * CHUNK_SIZE;
	}

	private static int unpackChunkTemplatePlane(int chunkData)
	{
		return chunkData >> 24 & 0x3;
	}

	public static int fromLocalInstance(Client client, Player localPlayer)
	{
		WorldView worldView = localPlayer.getWorldView();
		int worldViewId = worldView.getId();
		boolean isOnBoat = worldViewId != WorldView.TOPLEVEL;
		if (isOnBoat)
		{
			WorldEntity worldEntity = client.getTopLevelWorldView().worldEntities().byIndex(worldViewId);
			return fromLocalInstance(client, worldEntity.getLocalLocation());
		}
		return fromLocalInstance(client, localPlayer.getLocalLocation());
	}

	/**
	 * The position of the boat the player is on, in the top-level world and in local units (128 per tile,
	 * so the low 7 bits are the position within the tile). Uses the server's position for this tick rather
	 * than the smoothed render position. Returns {@code null} when the player is not on a boat.
	 */
	public static LocalPoint boatLocation(Client client, Player localPlayer)
	{
		WorldEntity boat = boat(client, localPlayer);
		if (boat == null)
		{
			return null;
		}
		LocalPoint target = boat.getTargetLocation();
		return target != null ? target : boat.getLocalLocation();
	}

	/**
	 * The boat the player is on, or {@code null} when the player is not on a boat. The world-view
	 * chain tolerates transient nulls — during a world hop a live player can sit on a world view
	 * that is still being rebuilt.
	 */
	public static WorldEntity boat(Client client, Player localPlayer)
	{
		WorldView worldView = localPlayer.getWorldView();
		if (worldView == null || worldView.getId() == WorldView.TOPLEVEL)
		{
			return null;
		}
		WorldView topLevel = client.getTopLevelWorldView();
		if (topLevel == null || topLevel.worldEntities() == null)
		{
			return null;
		}
		return topLevel.worldEntities().byIndex(worldView.getId());
	}

	/**
	 * Converts an instanced {@link LocalPoint} to its corresponding packed world
	 * point coordinate, resolving the
	 * underlying template chunk mapping and rotation.
	 *
	 * @param client     RuneLite client.
	 * @param localPoint local scene coordinate.
	 * @return packed world point, or {@link #UNDEFINED} when the point's world view is unavailable
	 *         (e.g. still being rebuilt during a world hop).
	 */
	public static int fromLocalInstance(Client client, LocalPoint localPoint)
	{
		WorldView worldView = client.getWorldView(localPoint.getWorldView());
		if (worldView == null)
		{
			return UNDEFINED;
		}
		int plane = worldView.getPlane();

		if (!worldView.isInstance())
		{
			return packWorldPoint(
				(localPoint.getX() >> LOCAL_COORD_BITS) + worldView.getBaseX(),
				(localPoint.getY() >> LOCAL_COORD_BITS) + worldView.getBaseY(),
				plane);
		}

		int[][][] instanceTemplateChunks = worldView.getInstanceTemplateChunks();

		// get position in the scene
		int sceneX = localPoint.getSceneX();
		int sceneY = localPoint.getSceneY();

		// get chunk from scene
		int chunkX = sceneX / CHUNK_SIZE;
		int chunkY = sceneY / CHUNK_SIZE;

		// get the template chunk for the chunk
		int templateChunk = instanceTemplateChunks[plane][chunkX][chunkY];

		int rotation = unpackChunkRotation(templateChunk);
		int templateChunkY = unpackChunkTemplateY(templateChunk);
		int templateChunkX = unpackChunkTemplateX(templateChunk);
		int templateChunkPlane = unpackChunkTemplatePlane(templateChunk);

		// calculate world point of the template
		int x = templateChunkX + (sceneX & (CHUNK_SIZE - 1));
		int y = templateChunkY + (sceneY & (CHUNK_SIZE - 1));

		// create and rotate point back to 0, to match with template
		return rotate(x, y, templateChunkPlane, 4 - rotation);
	}

	/**
	 * Converts a packed world point to one or more packed world points representing
	 * its locations within an instanced
	 * map (e.g., dungeons or raids). If the current top-level world is not
	 * instanced, the result contains exactly the
	 * original point.
	 *
	 * @param client      RuneLite client.
	 * @param packedPoint packed world coordinate.
	 * @return list of packed coordinates valid in the current instance.
	 */
	public static PrimitiveIntList toLocalInstance(Client client, int packedPoint)
	{
		WorldView worldView = client.getTopLevelWorldView();

		PrimitiveIntList worldPoints = new PrimitiveIntList();
		if (!worldView.isInstance())
		{
			worldPoints.add(packedPoint);
			return worldPoints;
		}

		int baseX = worldView.getBaseX();
		int baseY = worldView.getBaseY();
		int worldPointX = unpackWorldX(packedPoint);
		int worldPointY = unpackWorldY(packedPoint);
		int worldPointPlane = unpackWorldPlane(packedPoint);

		int[][][] instanceTemplateChunks = worldView.getInstanceTemplateChunks();

		// find instance chunks using the template point. there might be more than one.
		for (int z = 0; z < instanceTemplateChunks.length; z++)
		{
			for (int x = 0; x < instanceTemplateChunks[z].length; ++x)
			{
				for (int y = 0; y < instanceTemplateChunks[z][x].length; ++y)
				{
					int chunkData = instanceTemplateChunks[z][x][y];
					int rotation = unpackChunkRotation(chunkData);
					int templateChunkY = unpackChunkTemplateY(chunkData);
					int templateChunkX = unpackChunkTemplateX(chunkData);
					int plane = unpackChunkTemplatePlane(chunkData);
					if (worldPointX >= templateChunkX && worldPointX < templateChunkX + CHUNK_SIZE
						&& worldPointY >= templateChunkY && worldPointY < templateChunkY + CHUNK_SIZE
						&& plane == worldPointPlane)
					{
						worldPoints.add(rotate(
							baseX + x * CHUNK_SIZE + (worldPointX & (CHUNK_SIZE - 1)),
							baseY + y * CHUNK_SIZE + (worldPointY & (CHUNK_SIZE - 1)),
							z,
							rotation));
					}
				}
			}
		}
		return worldPoints;
	}

	private static boolean isInScene(WorldView worldView, int packedPoint)
	{
		int x = unpackWorldX(packedPoint);
		int y = unpackWorldY(packedPoint);

		int baseX = worldView.getBaseX();
		int baseY = worldView.getBaseY();

		int maxX = baseX + worldView.getSizeX();
		int maxY = baseY + worldView.getSizeY();

		return x >= baseX && x < maxX && y >= baseY && y < maxY;
	}

	/**
	 * Converts a packed world point into a {@link LocalPoint} relative to the
	 * top-level world view if it resides in
	 * the currently loaded scene and on the same plane; returns {@code null}
	 * otherwise.
	 *
	 * @param client      RuneLite client.
	 * @param packedPoint packed world point.
	 * @return {@link LocalPoint} or {@code null} if out of scene or plane.
	 */
	public static LocalPoint toLocalPoint(Client client, int packedPoint)
	{
		WorldView worldView = client.getTopLevelWorldView();

		if (worldView.getPlane() != unpackWorldPlane(packedPoint))
		{
			return null;
		}

		if (!isInScene(worldView, packedPoint))
		{
			return null;
		}

		return new LocalPoint(
			(unpackWorldX(packedPoint) - worldView.getBaseX() << LOCAL_COORD_BITS) + (1 << LOCAL_COORD_BITS - 1),
			(unpackWorldY(packedPoint) - worldView.getBaseY() << LOCAL_COORD_BITS) + (1 << LOCAL_COORD_BITS - 1),
			worldView.getId());
	}
}

package shortestpath.api;

import java.awt.Shape;
import java.util.*;
import javax.inject.*;
import lombok.RequiredArgsConstructor;
import net.runelite.api.*;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.JagexColors;
import net.runelite.client.util.*;
import shortestpath.WorldPointUtil;
import shortestpath.pathfinder.*;
import shortestpath.presentation.PathAnnotator;
import shortestpath.scheduler.PathScheduler;
import shortestpath.widgets.WidgetGeometry;

/**
 * Owns the plugin's menu-verb surface: the colour-tagged {@code Set Target}/
 * {@code Set Start}/{@code Clear Path}/{@code Find closest} entries offered on
 * shift-right-click and on the world map, and the click handler that turns a
 * chosen verb into scheduler target/start updates. The verb constants live on
 * this one type so the builder and the click matcher compare the same
 * instances. Selected-tile and minimap reads flow through the widget-geometry
 * seam; destination lookups flow through the annotator's config facade.
 *
 * <p>This package is a leaf: nothing here may reference the plugin type.
 */
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class MenuVerbs
{
	private static final String CLEAR = "Clear";
	private static final String PATH = ColorUtil.wrapWithColorTag("Path", JagexColors.MENU_TARGET);
	private static final String SET = "Set";
	private static final String FIND_CLOSEST = "Find closest";
	private static final String FLASH_ICONS = "Flash icons";
	private static final String START = ColorUtil.wrapWithColorTag("Start", JagexColors.MENU_TARGET);
	private static final String TARGET = ColorUtil.wrapWithColorTag("Target", JagexColors.MENU_TARGET);

	private final Client client;
	private final PathScheduler scheduler;
	private final PathAnnotator annotator;
	private final WidgetGeometry geometry;

	public void onMenuEntryAdded(MenuEntryAdded event)
	{
		if (client.isKeyPressed(KeyCode.KC_SHIFT)
			&& event.getType() == MenuAction.WALK.getId())
		{
			addSurfaceEntries(event, 1, true);
		}

		final Widget map = client.getWidget(InterfaceID.Worldmap.MAP_CONTAINER);

		if (map != null)
		{
			if (map.getBounds().contains(
				client.getMouseCanvasPosition().getX(),
				client.getMouseCanvasPosition().getY()))
			{
				addSurfaceEntries(event, 0, false);
			}
			if (event.getOption().equals(FLASH_ICONS) && annotator.hasDestination(simplify(event.getTarget())))
			{
				addMenuEntry(event, FIND_CLOSEST, event.getTarget(), 1);
			}
		}

		final Shape minimap = geometry.getMinimapClipArea();

		if (minimap != null && scheduler.getActiveSearch() != null
			&& minimap.contains(
			client.getMouseCanvasPosition().getX(),
			client.getMouseCanvasPosition().getY()))
		{
			addMenuEntry(event, CLEAR, PATH, 0);
		}

		if (minimap != null && scheduler.getActiveSearch() != null
			&& ("Floating World Map".equals(Text.removeTags(event.getOption()))
			|| "Close Floating panel".equals(Text.removeTags(event.getOption()))))
		{
			addMenuEntry(event, CLEAR, PATH, 1);
		}
	}

	private String simplify(String text)
	{
		return Text.removeTags(text).toLowerCase()
			.replaceAll("[^a-zA-Z ]", "")
			.replace(" ", "_")
			.replace("__", "_");
	}

	private void onMenuOptionClicked(MenuEntry entry)
	{
		ActiveSearch pathfinder = scheduler.getActiveSearch();
		if (entry.getOption().equals(SET) && entry.getTarget().equals(TARGET))
		{
			scheduler.setTarget(geometry.getSelectedWorldPoint());
		}
		else if (entry.getOption().equals(SET) && pathfinder != null && entry.getTarget().equals(TARGET +
			ColorUtil.wrapWithColorTag(" " + (pathfinder.getTargets().size() + 1), JagexColors.MENU_TARGET)))
		{
			scheduler.setTarget(geometry.getSelectedWorldPoint(), true);
		}
		else if (entry.getOption().equals(SET) && entry.getTarget().equals(START))
		{
			scheduler.setStart(geometry.getSelectedWorldPoint());
		}
		else if (entry.getOption().equals(CLEAR) && entry.getTarget().equals(PATH))
		{
			scheduler.setTarget(WorldPointUtil.UNDEFINED);
		}
		else if (entry.getOption().equals(FIND_CLOSEST))
		{
			scheduler.setTargets(annotator.getDestinations(simplify(entry.getTarget())), true);
		}
	}

	/**
	 * The shared emission path for both verb surfaces: the two Set-target
	 * entries, then SET/START on the first defined target (shift-right-click)
	 * or SET/START + CLEAR/PATH on every defined target (world map —
	 * addMenuEntry dedup makes the repeats idempotent). When
	 * {@code clearOnSelectedTile} is set, CLEAR/PATH is instead offered only
	 * when the selected tile sits on the displayed path.
	 */
	private void addSurfaceEntries(MenuEntryAdded event, int position, boolean clearOnSelectedTile)
	{
		ActiveSearch pathfinder = addSetTargetEntries(event, position);
		if (pathfinder == null)
		{
			return;
		}
		for (int target : pathfinder.getTargets().points())
		{
			if (target == WorldPointUtil.UNDEFINED)
			{
				continue;
			}
			addMenuEntry(event, SET, START, position);
			if (clearOnSelectedTile)
			{
				break;
			}
			addMenuEntry(event, CLEAR, PATH, position);
		}
		if (!clearOnSelectedTile)
		{
			return;
		}
		int selectedTile = geometry.getSelectedWorldPoint();
		List<PathStep> path;
		if ((path = pathfinder.getPath()) != null)
		{
			for (PathStep pathStep : path)
			{
				if (pathStep.getPackedPosition() == selectedTile)
				{
					addMenuEntry(event, CLEAR, PATH, position);
					break;
				}
			}
		}
	}

	/**
	 * Offers the two Set-target entries every verb surface shares and hands
	 * back the active search (or null) so the caller can emit its own
	 * Start/Clear verbs.
	 */
	private ActiveSearch addSetTargetEntries(MenuEntryAdded event, int position)
	{
		addMenuEntry(event, SET, TARGET, position);
		ActiveSearch pathfinder = scheduler.getActiveSearch();
		if (pathfinder != null && !pathfinder.getTargets().isEmpty())
		{
			addMenuEntry(event, SET, TARGET + ColorUtil.wrapWithColorTag(" " +
				(pathfinder.getTargets().size() + 1), JagexColors.MENU_TARGET), position);
		}
		return pathfinder;
	}

	private void addMenuEntry(MenuEntryAdded event, String option, String target, int position)
	{
		List<MenuEntry> entries = new LinkedList<>(Arrays.asList(client.getMenu().getMenuEntries()));

		if (entries.stream().anyMatch(e -> e.getOption().equals(option) && e.getTarget().equals(target)))
		{
			return;
		}

		client.getMenu().createMenuEntry(position)
			.setOption(option)
			.setTarget(target)
			.setParam0(event.getActionParam0())
			.setParam1(event.getActionParam1())
			.setIdentifier(event.getIdentifier())
			.setType(MenuAction.RUNELITE)
			.onClick(this::onMenuOptionClicked);
	}
}

package shortestpath.api;

import shortestpath.settings.ConfigKey;
import java.util.*;
import java.util.function.Consumer;
import javax.inject.*;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.events.PluginMessage;
import shortestpath.WorldPointUtil;
import shortestpath.pathfinder.*;
import shortestpath.presentation.PathAnnotator;
import shortestpath.scheduler.*;
import shortestpath.settings.Settings;
import shortestpath.transport.Transport;

/**
 * Owns the plugin's external plugin-message surface: the dispatch of incoming
 * {@code path}/{@code query}/{@code clear}/{@code getTarget} messages and the
 * serialization of the outgoing {@code result}/{@code currentTarget}/
 * {@code transports} responses. Implements the scheduler's narrow
 * {@link QueryResponder} callback seam so query completions can be answered
 * without the scheduler knowing the wire contract.
 *
 * <p>The annotator/serializer seam is the documented injection point for any
 * future verdict channel — none is wired today; the payload shapes are the
 * live external contract and stay byte-identical.
 *
 * <p>Thread affinity is load-bearing: the serializers that answer scheduler
 * callbacks hop to the client thread via {@code clientThread.invokeLater},
 * while {@link #postPluginMessages()} posts directly because it already runs
 * on the pathfinder completion path.
 *
 * <p>This package is a leaf: nothing here may reference the plugin type.
 */
@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class PluginMessageHandler implements QueryResponder
{
	private static final String PLUGIN_MESSAGE_PATH = "path";
	private static final String PLUGIN_MESSAGE_CLEAR = "clear";
	private static final String PLUGIN_MESSAGE_START = "start";
	private static final String PLUGIN_MESSAGE_TARGET = "target";
	private static final String PLUGIN_MESSAGE_CONFIG_OVERRIDE = "config";
	private static final String PLUGIN_MESSAGE_TRANSPORTS = "transports";
	private static final String PLUGIN_MESSAGE_QUERY = "query";
	private static final String PLUGIN_MESSAGE_RESULT = "result";
	private static final String PLUGIN_MESSAGE_GET_TARGET = "getTarget";
	private static final String PLUGIN_MESSAGE_CURRENT_TARGET = "currentTarget";
	private static final String PLUGIN_MESSAGE_ID = "id";
	private static final String PLUGIN_MESSAGE_BANK_VISITED = "bankVisited";
	private static final String PLUGIN_MESSAGE_TARGET_STATUS = "targetStatus";
	private static final String PLUGIN_MESSAGE_MISSING_ITEMS = "missingItems";

	private final Client client;
	private final ClientThread clientThread;
	private final EventBus eventBus;
	private final PathScheduler scheduler;
	private final RefreshCoordinator coordinator;
	private final Settings settings;
	private final PathAnnotator annotator;

	/**
	 * The inbound action dispatch: message name to its handler. Lookup — not
	 * iteration — dispatches, so an unmatched action falls through to silence
	 * exactly as the former chain's absent {@code else} did.
	 */
	private final Map<String, Consumer<PluginMessage>> actions = Map.of(
		PLUGIN_MESSAGE_PATH, this::onPathMessage,
		PLUGIN_MESSAGE_QUERY, this::onQueryMessage,
		PLUGIN_MESSAGE_GET_TARGET, this::onGetTargetMessage,
		PLUGIN_MESSAGE_CLEAR, this::onClearMessage);

	public void onPluginMessage(PluginMessage event)
	{
		if (!Settings.CONFIG_GROUP.equals(event.getNamespace()))
		{
			return;
		}

		Consumer<PluginMessage> handler = actions.get(event.getName());
		if (handler == null)
		{
			return;
		}
		handler.accept(event);
	}

	private void onPathMessage(PluginMessage event)
	{
		Map<String, Object> data = event.getData();
		if (data == null)
		{
			return;
		}
		Object objStart = data.getOrDefault(PLUGIN_MESSAGE_START, null);
		Object objTarget = data.getOrDefault(PLUGIN_MESSAGE_TARGET, null);
		Object objConfigOverride = data.getOrDefault(PLUGIN_MESSAGE_CONFIG_OVERRIDE, null);

		@SuppressWarnings("unchecked")
		Map<String, Object> payloadOverrides = (objConfigOverride instanceof Map<?, ?>) ? ((Map<String, Object>) objConfigOverride) : null;
		if (payloadOverrides != null && !payloadOverrides.isEmpty())
		{
			scheduler.withSchedulerLock(() -> settings.applyOverrides(payloadOverrides));
		}

		if (objStart == null && objTarget == null)
		{
			return;
		}

		int start = parseStart(objStart);
		Targets targets = decodeTargets(objTarget);
		if (start == WorldPointUtil.UNDEFINED || targets == null)
		{
			return;
		}

		coordinator.targetRequest(start, targets);
	}

	private void onQueryMessage(PluginMessage event)
	{
		Map<String, Object> data = event.getData();
		if (data == null)
		{
			return;
		}
		Object id = data.get(PLUGIN_MESSAGE_ID);
		int start = parseStart(data.get(PLUGIN_MESSAGE_START));
		Targets targets = decodeTargets(data.get(PLUGIN_MESSAGE_TARGET));
		if (start == WorldPointUtil.UNDEFINED || targets == null || targets.isEmpty())
		{
			postQueryFailure(id, "INVALID");
			return;
		}
		scheduler.queryPath(id, start, targets);
	}

	private void onGetTargetMessage(PluginMessage event)
	{
		Map<String, Object> data = event.getData();
		postCurrentTarget(data == null ? null : data.get(PLUGIN_MESSAGE_ID));
	}

	private void onClearMessage(PluginMessage event)
	{
		scheduler.withSchedulerLock(() -> settings.clearOverrides());
		scheduler.setTarget(WorldPointUtil.UNDEFINED);
	}

	/**
	 * The packed start of a plugin message path, defaulting to the player's location.
	 * {@link WorldPointUtil#UNDEFINED} when there is neither.
	 */
	private int parseStart(Object objStart)
	{
		int start = (objStart instanceof WorldPoint) ? WorldPointUtil.packWorldPoint((WorldPoint) objStart)
			: ((objStart instanceof Integer) ? ((int) objStart) : WorldPointUtil.UNDEFINED);
		if (start == WorldPointUtil.UNDEFINED && client.getLocalPlayer() != null)
		{
			start = WorldPointUtil.packWorldPoint(client.getLocalPlayer().getWorldLocation());
		}
		return start;
	}

	/**
	 * The targets of a plugin message, with the items each needs on arrival; see
	 * {@link PluginMessageTargets}. {@link Targets#NONE} when none were given, and {@code null} when
	 * the value is malformed.
	 */
	private static Targets decodeTargets(Object objTarget)
	{
		try
		{
			return PluginMessageTargets.decode(objTarget);
		}
		catch (IllegalArgumentException e)
		{
			log.warn("Ignoring plugin message with invalid target: {}", e.getMessage());
			return null;
		}
	}

	@Override
	public void postQueryResult(Object id, ActiveSearch query)
	{
		PathfinderResult result = query.getResult();
		if (result == null)
		{
			postQueryFailure(id, "ERROR");
			return;
		}

		List<PathStep> steps = result.getPathSteps();
		List<WorldPoint> path = new ArrayList<>(steps.size());
		List<Map<String, Object>> transports = new ArrayList<>();
		for (int i = 0; i < steps.size(); i++)
		{
			path.add(WorldPointUtil.unpackWorldPoint(steps.get(i).getPackedPosition()));
			if (i > 0)
			{
				for (Transport transport : annotator.transportsForEdge(steps.get(i - 1), steps.get(i)))
				{
					Map<String, Object> edge = new HashMap<>();
					edge.put("origin", WorldPointUtil.unpackWorldPoint(steps.get(i - 1).getPackedPosition()));
					edge.put("destination", WorldPointUtil.unpackWorldPoint(steps.get(i).getPackedPosition()));
					edge.put("objectInfo", transport.getObjectInfo());
					edge.put("displayInfo", annotator.formatTransportDisplay(transport));
					transports.add(edge);
				}
			}
		}

		Map<String, Object> data = new HashMap<>();
		data.put(PLUGIN_MESSAGE_ID, id);
		data.put("reached", result.isReached());
		data.put(PLUGIN_MESSAGE_START, WorldPointUtil.unpackWorldPoint(result.getStart()));
		data.put(PLUGIN_MESSAGE_TARGET, WorldPointUtil.unpackWorldPoint(result.getTarget()));
		data.put("path", path);
		data.put(PLUGIN_MESSAGE_TRANSPORTS, transports);
		data.put("closest", WorldPointUtil.unpackWorldPoint(result.getClosestReachedPoint()));
		data.put("cost", result.getPathCost());
		PathTerminationReason reason = result.getTerminationReason();
		data.put("reason", reason == null ? null : reason.name());
		putArrival(data, steps, result.getArrival());
		clientThread.invokeLater(() -> eventBus.post(new PluginMessage(Settings.CONFIG_GROUP, PLUGIN_MESSAGE_RESULT, data)));
	}

	/**
	 * Adds the item fields of a {@code result} message: whether the path visits a bank, and the
	 * reached target's item status and the item groups it is missing. A target that needs no items
	 * has no status.
	 */
	private static void putArrival(Map<String, Object> data, List<PathStep> steps, Arrival arrival)
	{
		boolean requiresItems = arrival != null && arrival.getTarget().hasRequiredItems();
		data.put(PLUGIN_MESSAGE_BANK_VISITED, !steps.isEmpty() && steps.get(steps.size() - 1).getBankVisitState() == BankVisitState.BANKED);
		data.put(PLUGIN_MESSAGE_TARGET_STATUS, requiresItems ? arrival.getStatus().name() : null);
		data.put(PLUGIN_MESSAGE_MISSING_ITEMS,
			requiresItems ? PluginMessageTargets.itemIds(arrival.getMissingItems()) : List.of());
	}

	/**
	 * Answers a query that produced no result: a malformed message, a plugin shutdown, a
	 * cancelled search, or a failure while running.
	 */
	@Override
	public void postQueryFailure(Object id, String reason)
	{
		Map<String, Object> data = new HashMap<>();
		data.put(PLUGIN_MESSAGE_ID, id);
		data.put("reached", false);
		data.put("path", List.of());
		data.put(PLUGIN_MESSAGE_TRANSPORTS, List.of());
		data.put("reason", reason);
		putArrival(data, List.of(), null);
		clientThread.invokeLater(() -> eventBus.post(new PluginMessage(Settings.CONFIG_GROUP, PLUGIN_MESSAGE_RESULT, data)));
	}

	/**
	 * Answers a {@code getTarget} plugin message with a {@code currentTarget} message carrying
	 * the caller's {@code id} and a snapshot of the displayed path's start and targets. This is
	 * a read-only request: it launches no pathfinding work and mutates no state.
	 *
	 * <p>The start/targets/overrides triple is read while holding the scheduler's lock so a
	 * request arriving mid-search sees one consistent snapshot rather than a torn pair; the
	 * lock is released before the response hops to the client thread. When no path is set the
	 * response carries {@code set=false} and no start or target fields.
	 */
	private void postCurrentTarget(Object id)
	{
		Map<String, Object> data = scheduler.withSchedulerLock(() ->
		{
			ActiveSearch pathfinder = scheduler.getActiveSearch();
			int start = (pathfinder == null) ? WorldPointUtil.UNDEFINED : pathfinder.getStart();
			Targets targets = (pathfinder == null) ? Targets.NONE : pathfinder.getTargets();
			Map<String, Object> overrides =
				settings.getOverrides().isEmpty() ? null : new HashMap<>(settings.getOverrides());

			Map<String, Object> message = new HashMap<>();
			message.put(PLUGIN_MESSAGE_ID, id);
			message.put("set", !targets.isEmpty());
			if (!targets.isEmpty())
			{
				message.put(PLUGIN_MESSAGE_START,
					start == WorldPointUtil.UNDEFINED ? null : WorldPointUtil.unpackWorldPoint(start));
				List<Object> encodedTargets = new ArrayList<>(targets.size());
				for (Target target : targets)
				{
					encodedTargets.add(PluginMessageTargets.encode(target));
				}
				message.put(PLUGIN_MESSAGE_TARGET, encodedTargets);
			}
			if (overrides != null)
			{
				message.put(PLUGIN_MESSAGE_CONFIG_OVERRIDE, overrides);
			}
			return message;
		});
		clientThread.invokeLater(() -> eventBus.post(new PluginMessage(Settings.CONFIG_GROUP, PLUGIN_MESSAGE_CURRENT_TARGET, data)));
	}

	@Override
	public void postPluginMessages()
	{
		ActiveSearch pathfinder = scheduler.getActiveSearch();
		if (pathfinder == null)
		{
			return;
		}
		if (settings.bool(ConfigKey.POST_TRANSPORTS))
		{
			Map<String, Object> data = new HashMap<>();
			List<WorldPoint> transportOrigins = new ArrayList<>();
			List<WorldPoint> transportDestinations = new ArrayList<>();
			List<String> transportObjectInfos = new ArrayList<>();
			List<String> transportDisplayInfos = new ArrayList<>();
			List<PathStep> currentPath = pathfinder.getPath();
			for (int i = 1; i < currentPath.size(); i++)
			{
				PathStep currentStep = currentPath.get(i - 1);
				PathStep nextStep = currentPath.get(i);
				for (Transport transport : annotator.transportsForEdge(currentStep, nextStep))
				{
					transportOrigins.add(WorldPointUtil.unpackWorldPoint(currentStep.getPackedPosition()));
					transportDestinations.add(WorldPointUtil.unpackWorldPoint(nextStep.getPackedPosition()));
					transportObjectInfos.add(transport.getObjectInfo());
					transportDisplayInfos.add(annotator.formatTransportDisplay(transport));
				}
			}
			data.put("origin", transportOrigins);
			data.put("destination", transportDestinations);
			data.put("objectInfo", transportObjectInfos);
			data.put("displayInfo", transportDisplayInfos);
			eventBus.post(new PluginMessage(Settings.CONFIG_GROUP, PLUGIN_MESSAGE_TRANSPORTS, data));
		}
	}
}

package shortestpath.api;

import java.util.*;
import net.runelite.api.coords.WorldPoint;
import shortestpath.WorldPointUtil;
import shortestpath.pathfinder.*;
import shortestpath.requirement.model.*;

/**
 * Converts between {@link Targets} and the values other plugins put in the {@code target} of a
 * {@code path} or {@code query} message, using only JDK and RuneLite types, since plugins can't
 * share classes.
 *
 * <p>A target is a {@link WorldPoint}, a packed {@link Integer}, or a target map
 * {@code {"point": WorldPoint|Integer, "requirements": requirement}}; a message's {@code target} is
 * one target or a {@link Collection} of them. A requirement is:
 * <ul>
 *     <li>an {@code Integer} item id: one of that item;</li>
 *     <li>a {@code Map<Integer, Integer>} of item id to quantity: any one of those items, at
 *     least that many;</li>
 *     <li>any other {@code Collection} of item ids: any one of them;</li>
 *     <li>a {@code List} of the above: all of them. Inside it, a {@code List} is an "any of"
 *     group like any other collection.</li>
 * </ul>
 * Item ids are matched exactly; no item variations are added.
 */
final class PluginMessageTargets
{
	static final String POINT = "point";
	static final String REQUIREMENTS = "requirements";

	private static final int[] NONE = new int[0];

	private PluginMessageTargets()
	{
	}

	/**
	 * The targets in a message's {@code target} value; {@link Targets#NONE} for {@code null}.
	 * Throws {@link IllegalArgumentException} for anything malformed.
	 */
	static Targets decode(Object value)
	{
		if (value == null)
		{
			return Targets.NONE;
		}
		List<Target> targets = new ArrayList<>();
		if (value instanceof Collection<?>)
		{
			for (Object element : (Collection<?>) value)
			{
				targets.add(decodeTarget(element));
			}
		}
		else
		{
			targets.add(decodeTarget(value));
		}
		return Targets.of(targets);
	}

	private static Target decodeTarget(Object value)
	{
		if (!(value instanceof Map<?, ?>))
		{
			return Target.at(decodePoint(value));
		}
		Map<?, ?> map = (Map<?, ?>) value;
		int point = decodePoint(map.get(POINT));
		Object requirements = map.get(REQUIREMENTS);
		return requirements == null ? Target.at(point) : Target.requiring(point, decodeRequirements(requirements));
	}

	private static int decodePoint(Object value)
	{
		int packed = WorldPointUtil.UNDEFINED;
		if (value instanceof WorldPoint)
		{
			packed = WorldPointUtil.packWorldPoint((WorldPoint) value);
		}
		else if (value instanceof Integer)
		{
			packed = (Integer) value;
		}
		if (packed == WorldPointUtil.UNDEFINED)
		{
			throw new IllegalArgumentException("not a target point: " + value);
		}
		return packed;
	}

	/** One requirement value; see the class documentation for the accepted shapes. */
	static TransportItems decodeRequirements(Object value)
	{
		List<ItemRequirement> groups = new ArrayList<>();
		if (value instanceof List<?>)
		{
			List<?> all = (List<?>) value;
			if (all.isEmpty())
			{
				throw new IllegalArgumentException("a requirement list needs at least one item");
			}
			for (Object element : all)
			{
				groups.add(decodeGroup(element));
			}
		}
		else
		{
			groups.add(decodeGroup(value));
		}
		return new TransportItems(groups);
	}

	/** One "any of" group: an item id, a collection of item ids, or a map of item id to quantity. */
	private static ItemRequirement decodeGroup(Object value)
	{
		List<ItemRequirement.Branch> branches = new ArrayList<>();
		if (value instanceof Integer)
		{
			branches.add(branch(value, 1));
		}
		else if (value instanceof Map<?, ?>)
		{
			for (Map.Entry<?, ?> entry : ((Map<?, ?>) value).entrySet())
			{
				Object quantity = entry.getValue();
				if (!(quantity instanceof Integer) || (Integer) quantity < 1)
				{
					throw new IllegalArgumentException("not an item quantity: " + quantity);
				}
				branches.add(branch(entry.getKey(), (Integer) quantity));
			}
		}
		else if (value instanceof Collection<?>)
		{
			for (Object id : (Collection<?>) value)
			{
				branches.add(branch(id, 1));
			}
		}
		else
		{
			throw new IllegalArgumentException("not an item requirement: " + value);
		}
		if (branches.isEmpty())
		{
			throw new IllegalArgumentException("an item group needs at least one item");
		}
		return new ItemRequirement(branches);
	}

	private static ItemRequirement.Branch branch(Object id, int quantity)
	{
		if (!(id instanceof Integer) || (Integer) id < 0)
		{
			throw new IllegalArgumentException("not an item id: " + id);
		}
		return new ItemRequirement.Branch(new int[] {(Integer) id}, NONE, NONE, quantity);
	}

	/**
	 * {@code target} as a message value: a {@link WorldPoint}, or a target map when it has required
	 * items. The requirements take their canonical shape, a {@code List} with one
	 * {@code Map<Integer, Integer>} of item id to quantity per group, which decodes to the same
	 * target.
	 */
	static Object encode(Target target)
	{
		WorldPoint point = WorldPointUtil.unpackWorldPoint(target.getPoint());
		if (!target.hasRequiredItems())
		{
			return point;
		}
		List<Map<Integer, Integer>> groups = new ArrayList<>();
		for (ItemRequirement group : target.getRequiredItems().getRequirements())
		{
			Map<Integer, Integer> alternatives = new LinkedHashMap<>();
			for (ItemRequirement.Branch branch : group.getBranches())
			{
				for (int id : branch.getItemIds())
				{
					// A group may repeat an id at several quantities; the alternatives are
					// OR-ed, so the smallest quantity is the most permissive reading.
					alternatives.merge(id, branch.getQuantity(), Math::min);
				}
			}
			groups.add(alternatives);
		}
		Map<String, Object> map = new HashMap<>();
		map.put(POINT, point);
		map.put(REQUIREMENTS, groups);
		return map;
	}

	/** The item ids of each group, for reporting the groups a target is missing. */
	static List<List<Integer>> itemIds(List<ItemRequirement> groups)
	{
		List<List<Integer>> ids = new ArrayList<>(groups.size());
		for (ItemRequirement group : groups)
		{
			List<Integer> groupIds = new ArrayList<>();
			for (ItemRequirement.Branch branch : group.getBranches())
			{
				for (int id : branch.getItemIds())
				{
					groupIds.add(id);
				}
			}
			ids.add(groupIds);
		}
		return ids;
	}
}

package shortestpath.items;

import java.util.*;

import lombok.Getter;

import shortestpath.settings.Effect;

/**
 * An immutable fact describing a single item-state change: the input that
 * changed (keyed as {@code "container:<id>"} or {@code "varbit:<id>"}) and the
 * {@link Effect}s it triggers. Produced by {@link ItemStateService}; the shell
 * reads the effect set to decide which follow-up actions to run rather than
 * re-deriving them from the event.
 */
@Getter
public final class ItemChange
{
	private final String key;
	private final Set<Effect> effects;

	ItemChange(String key, Set<Effect> effects)
	{
		this.key = Objects.requireNonNull(key);
		this.effects = Set.copyOf(effects);
	}
}

package shortestpath.items;

import java.util.*;

import javax.inject.*;

import lombok.*;
import lombok.experimental.Accessors;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.*;
import net.runelite.client.config.ConfigManager;

import shortestpath.scheduler.RefreshCoordinator;
import shortestpath.settings.*;

/**
 * Owns the plugin's player item state observed from game events — the live
 * open-bank container and the container/varbit inputs that feed the
 * eligibility snapshot — and declares each admitted change to the
 * {@link RefreshCoordinator} as an {@link ItemChange} fact. The service
 * never writes back to the engine; the coordinator maps the fact's declared
 * effects to its follow-up actions, and downstream projections key their
 * caches on {@link #itemStateRevision()} rather than pulling path types in
 * here.
 * <p>
 * Two bank concepts live here and must never cross. {@link #getBank()} is
 * the session-scoped LIVE eligibility reference: a handle on the last-opened
 * bank container that reads empty once the bank closes and is dropped by
 * {@link #reset()} so nothing observed in one session feeds eligibility in
 * the next. {@link #lastSeenBank()} is a per-account <i>last-seen</i> bank
 * contents record for the panel's Owned filter — explicitly display-only,
 * never consulted by eligibility, persisted through RSProfile so it survives
 * sessions and plugin restarts by design; {@link #reset()} does not clear it.
 * </p>
 */
@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class ItemStateService
{
	private final RefreshCoordinator coordinator;
	private final ConfigManager configManager;

	/**
	 * LIVE reference to the last-opened bank container — never copied or
	 * snapshotted, so it reads empty once the bank closes.
	 */
	@Getter private ItemContainer bank;

	/**
	 * The per-account last-seen bank contents — an immutable id-to-quantity
	 * map remembered across sessions for the panel's Owned filter. Display
	 * state only: eligibility never reads it, and {@link #reset()} leaves it
	 * intact.
	 */
	@Getter @Accessors(fluent = true) private volatile Map<Integer, Integer> lastSeenBank = Map.of();

	// The serialized form last written to (or read back from) the profile;
	// identical re-persists are skipped on it, mirroring the PohService
	// lastSaved guard so steady-state bank ticks never churn the config file.
	private String lastSeenBankSaved = "";

	static final String LAST_SEEN_BANK_KEY = "lastSeenBankItems";

	// Bumped by every admitted item-state change; readers that project this
	// state (e.g. the bank-pickup projection) key their caches on it instead
	// of this service observing their invalidation needs.
	@Getter @Accessors(fluent = true) private int itemStateRevision;

	/**
	 * Consumes an item-container event. The bank container id additionally
	 * updates the live bank reference; the tracked containers (bank,
	 * inventory, worn equipment) declare a fact carrying
	 * {@link Effect#ELIGIBILITY_STALE} to the coordinator. Any other
	 * container is not item state and declares nothing.
	 */
	public void onContainerChanged(int containerId, ItemContainer container)
	{
		if (containerId == InventoryID.BANK)
		{
			this.bank = container;
		}
		if (containerId == InventoryID.BANK || containerId == InventoryID.INV
			|| containerId == InventoryID.WORN)
		{
			itemStateRevision++;
			declare(new ItemChange("container:" + containerId, Set.of(Effect.ELIGIBILITY_STALE)));
		}
	}

	/**
	 * Consumes a varbit event. Rune pouch contents and the Lumbridge Elite
	 * diary feed the eligibility snapshot but change without firing a
	 * container event, so their varbits declare a fact carrying
	 * {@link Effect#ELIGIBILITY_STALE} to the coordinator. Any other varbit
	 * declares nothing.
	 */
	public void onVarbitChanged(int varbitId)
	{
		if (varbitId == VarbitID.LUMBRIDGE_DIARY_ELITE_COMPLETE
			|| containsVarbit(OwnedItems.RUNE_POUCH_RUNE_VARBITS, varbitId)
			|| containsVarbit(OwnedItems.RUNE_POUCH_AMOUNT_VARBITS, varbitId))
		{
			itemStateRevision++;
			declare(new ItemChange("varbit:" + varbitId, Set.of(Effect.ELIGIBILITY_STALE)));
		}
	}

	/**
	 * Hands an admitted fact to the refresh coordinator. Detached
	 * instances (built with a null coordinator) carry none, so the declare
	 * no-ops there; a null fact declares nothing, mirroring the return-null
	 * convention the shell's mapper used to guard.
	 */
	private void declare(ItemChange change)
	{
		if (change != null && coordinator != null)
		{
			coordinator.itemsChanged(change);
		}
	}

	private static boolean containsVarbit(int[] varbits, int varbitId)
	{
		for (int id : varbits)
		{
			if (id == varbitId)
			{
				return true;
			}
		}
		return false;
	}



	/**
	 * Harness/test seeding seam; production writes arrive through
	 * {@link #onContainerChanged} for the bank container id. Bumps
	 * {@link #itemStateRevision()} like the event path does, so a re-seeded
	 * bank is never served by a projection computed against the previous
	 * container.
	 */
	public void noteBankContainer(ItemContainer container)
	{
		this.bank = container;
		itemStateRevision++;
	}

	/**
	 * Records the bank's contents for the display-side last-seen snapshot.
	 * The shell calls this on the client thread with the bank-open verdict
	 * already computed — the widget read behind it is a client-thread call
	 * the service cannot make without a client. A {@code false} verdict
	 * means the event is the post-close drain: the container reads empty
	 * because the bank is gone, not because it was emptied, so it is ignored
	 * and the previous snapshot survives. When the bank is open the
	 * container's current contents become the snapshot — a legitimately
	 * emptied bank persists as an empty snapshot — and only a change
	 * repersists.
	 */
	public void noteLastSeenBank(ItemContainer container, boolean bankOpen)
	{
		if (!bankOpen)
		{
			return;
		}
		Map<Integer, Integer> snapshot = new HashMap<>();
		OwnedItems.addContainer(snapshot, container);
		Map<Integer, Integer> immutable = Collections.unmodifiableMap(snapshot);
		if (!immutable.equals(lastSeenBank))
		{
			lastSeenBank = immutable;
			persistLastSeenBank();
		}
	}

	/**
	 * Loads the persisted last-seen bank snapshot for the active RuneScape
	 * profile — RSProfile keying gives per-account isolation for free.
	 * Hand-edited or stale profile data can never throw here: malformed
	 * entries are skipped with a warn and a missing or blank value loads as
	 * no snapshot. Detached instances (no config manager) clear to empty and
	 * return.
	 */
	public void loadFromProfile()
	{
		lastSeenBank = Map.of();
		lastSeenBankSaved = "";
		if (configManager == null)
		{
			return;
		}
		String stored = configManager.getRSProfileConfiguration(
			Settings.CONFIG_GROUP, LAST_SEEN_BANK_KEY);
		Map<Integer, Integer> loaded = new HashMap<>();
		if (stored != null && !stored.isBlank())
		{
			for (String rawEntry : stored.split(","))
			{
				String entry = rawEntry.trim();
				int split = entry.indexOf(':');
				if (split <= 0 || split == entry.length() - 1)
				{
					log.warn("ignoring malformed {} entry '{}'", LAST_SEEN_BANK_KEY, entry);
					continue;
				}
				try
				{
					int id = Integer.parseInt(entry.substring(0, split));
					int quantity = Integer.parseInt(entry.substring(split + 1));
					if (id < 0 || quantity <= 0)
					{
						log.warn("ignoring malformed {} entry '{}'", LAST_SEEN_BANK_KEY, entry);
						continue;
					}
					loaded.merge(id, quantity, Integer::sum);
				}
				catch (NumberFormatException e)
				{
					log.warn("ignoring malformed {} entry '{}'", LAST_SEEN_BANK_KEY, entry);
				}
			}
		}
		lastSeenBank = Collections.unmodifiableMap(loaded);
		lastSeenBankSaved = stored == null ? "" : stored;
	}

	/**
	 * Writes the snapshot to the active RuneScape profile as an
	 * {@code id:quantity} CSV sorted by item id. An empty snapshot unsets
	 * the key so "emptied the bank" and "never opened the bank" stay
	 * distinguishable on the next load from "nothing persisted". Identical
	 * serialized forms are skipped on {@link #lastSeenBankSaved}; detached
	 * instances persist nothing.
	 */
	private void persistLastSeenBank()
	{
		if (configManager == null)
		{
			return;
		}
		StringBuilder serialized = new StringBuilder();
		for (Map.Entry<Integer, Integer> entry : new TreeMap<>(lastSeenBank).entrySet())
		{
			if (serialized.length() > 0)
			{
				serialized.append(',');
			}
			serialized.append(entry.getKey().intValue())
				.append(':').append(entry.getValue().intValue());
		}
		String value = serialized.toString();
		if (value.equals(lastSeenBankSaved))
		{
			return;
		}
		lastSeenBankSaved = value;
		if (value.isEmpty())
		{
			configManager.unsetRSProfileConfiguration(
				Settings.CONFIG_GROUP, LAST_SEEN_BANK_KEY);
		}
		else
		{
			configManager.setRSProfileConfiguration(
				Settings.CONFIG_GROUP, LAST_SEEN_BANK_KEY, value);
		}
	}

	/**
	 * The item-state epoch: bumped by every admitted container/varbit change,
	 * by {@link #noteBankContainer}, and by {@link #reset}. Readers that cache
	 * a projection over this state must recompute when it moves.
	 */


	/**
	 * Clears the session-scoped state — the live bank reference. The service
	 * is a singleton on the plugin injector, which RuneLite reuses across
	 * shutDown/startUp cycles, so the shell calls this on shutdown to restore
	 * the lifetime the bank field had when it lived on the per-session
	 * pathfinder config: nothing observed in one session may feed eligibility
	 * in the next. The revision bump keeps downstream caches from serving a
	 * projection computed against the cleared state. The last-seen snapshot
	 * is deliberately untouched — surviving sessions is its whole point.
	 */
	public void reset()
	{
		bank = null;
		itemStateRevision++;
	}
}

package shortestpath.items;

import java.util.*;
import net.runelite.api.*;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;

/**
 * Collects the items a player owns as item id to quantity, summing an item
 * held in several places. Pathfinding and the item hints share it so they
 * count items the same way.
 */
public final class OwnedItems
{
	private OwnedItems()
	{
	}

	public static final List<Integer> RUNE_POUCHES = Arrays.asList(
		ItemID.BH_RUNE_POUCH, ItemID.BH_RUNE_POUCH_TROUVER,
		ItemID.DIVINE_RUNE_POUCH, ItemID.DIVINE_RUNE_POUCH_TROUVER
	);
	public static final int[] RUNE_POUCH_RUNE_VARBITS =
		{
			VarbitID.RUNE_POUCH_TYPE_1, VarbitID.RUNE_POUCH_TYPE_2, VarbitID.RUNE_POUCH_TYPE_3, VarbitID.RUNE_POUCH_TYPE_4,
			VarbitID.RUNE_POUCH_TYPE_5, VarbitID.RUNE_POUCH_TYPE_6
		};
	public static final int[] RUNE_POUCH_AMOUNT_VARBITS =
		{
			VarbitID.RUNE_POUCH_QUANTITY_1, VarbitID.RUNE_POUCH_QUANTITY_2, VarbitID.RUNE_POUCH_QUANTITY_3, VarbitID.RUNE_POUCH_QUANTITY_4,
			VarbitID.RUNE_POUCH_QUANTITY_5, VarbitID.RUNE_POUCH_QUANTITY_6
		};

	/**
	 * Item id to quantity summed across the given containers — the
	 * "everything the player currently owns" view. Callers hand it the
	 * containers they mean to union, e.g. inventory + worn + last-seen bank.
	 */
	public static Map<Integer, Integer> collect(ItemContainer... containers)
	{
		Map<Integer, Integer> owned = new HashMap<>();
		for (ItemContainer container : containers)
		{
			addContainer(owned, container);
		}
		return owned;
	}

	public static void addContainer(Map<Integer, Integer> owned, ItemContainer container)
	{
		if (container == null || container.getItems() == null)
		{
			return;
		}
		for (Item item : container.getItems())
		{
			if (item.getId() >= 0 && item.getQuantity() > 0)
			{
				owned.merge(item.getId(), item.getQuantity(), Integer::sum);
			}
		}
	}

	/**
	 * Adds the runes in the rune pouch, if {@code owned} already holds a rune pouch.
	 */
	public static void addRunePouchContents(Client client, Map<Integer, Integer> owned)
	{
		if (RUNE_POUCHES.stream().noneMatch(owned::containsKey))
		{
			return;
		}
		runePouchContents(client).forEach((runeId, amount) -> owned.merge(runeId, amount, Integer::sum));
	}

	/**
	 * Returns the runes in the rune pouch as rune id to amount. The varbits that
	 * hold the contents are current wherever the pouch is, including the bank.
	 */
	public static Map<Integer, Integer> runePouchContents(Client client)
	{
		Map<Integer, Integer> runes = new HashMap<>();
		EnumComposition runePouchEnum = client.getEnum(EnumID.RUNEPOUCH_RUNE);
		if (runePouchEnum == null)
		{
			return runes;
		}
		for (int i = 0; i < RUNE_POUCH_RUNE_VARBITS.length; i++)
		{
			int runeEnumId = client.getVarbitValue(RUNE_POUCH_RUNE_VARBITS[i]);
			int runeId = runeEnumId > 0 ? runePouchEnum.getIntValue(runeEnumId) : 0;
			int runeAmount = client.getVarbitValue(RUNE_POUCH_AMOUNT_VARBITS[i]);
			if (runeId > 0 && runeAmount > 0)
			{
				runes.merge(runeId, runeAmount, Integer::sum);
			}
		}
		return runes;
	}
}

package shortestpath.leagues;

import java.util.*;
import lombok.Getter;

/**
 * Immutable view of the league facts a {@link LeagueModeState} held at one
 * refresh. {@link LeagueModeState} is the live, per-config holder that
 * {@code refresh()} rewrites on every world hop or login; this snapshot is
 * what a per-refresh {@code RequirementContext} retains, so a requirement
 * chain keeps answering from the facts of the refresh that built it even if
 * a later refresh has already replaced the live state.
 *
 * <p>The read contract mirrors {@link LeagueModeState}'s: outside seasonal
 * mode every region is considered unlocked and no region is blocked, so
 * normal pathfinding is unaffected.
 */
public final class LeagueModeSnapshot
{
	/**
	 * The default snapshot: non-seasonal, not Deadman, no unlocks — the same
	 * facts a freshly constructed or null-source-refreshed
	 * {@link LeagueModeState} reports.
	 */
	public static final LeagueModeSnapshot NON_SEASONAL = new LeagueModeSnapshot(false, false, Set.of());

	@Getter private final boolean seasonal;
	@Getter private final boolean deadman;
	private final Set<LeagueRegion> unlockedRegions;

	public LeagueModeSnapshot(boolean seasonal, boolean deadman, Set<LeagueRegion> unlockedRegions)
	{
		this.seasonal = seasonal;
		this.deadman = deadman;
		this.unlockedRegions = unlockedRegions == null || unlockedRegions.isEmpty()
			? Set.of()
			: Collections.unmodifiableSet(EnumSet.copyOf(unlockedRegions));
	}





	/**
	 * Whether the supplied region is currently traversable. Outside of
	 * seasonal mode every region is considered unlocked.
	 */
	public boolean isUnlocked(LeagueRegion region)
	{
		if (region == null)
		{
			return true;
		}
		if (region.isAlwaysUnlocked())
		{
			return true;
		}
		if (!seasonal)
		{
			return true;
		}
		if (region.isAlwaysBlocked())
		{
			return false;
		}
		return unlockedRegions.contains(region);
	}

	/**
	 * Whether the supplied tile is in the always-blocked region while the
	 * player is on a seasonal world. Returns {@code false} on non-seasonal
	 * worlds so normal pathfinding is unaffected.
	 */
	public boolean isInBlockedRegion(int packedPoint)
	{
		if (!seasonal)
		{
			return false;
		}
		return LeagueRegionChecker.getRegion(packedPoint).isAlwaysBlocked();
	}
}

package shortestpath.leagues;

import java.util.*;
import net.runelite.api.WorldType;
import shortestpath.requirement.PlayerStateSource;

/**
 * Snapshot of the player's Demonic Pacts League state, refreshed once per
 * {@code PathfinderConfig.refresh()} cycle (i.e. on world change, login, or
 * any config-driven recompute).
 *
 * <p>
 * The Pathfinder asks two questions of this object on the hot path:
 * </p>
 * <ul>
 *   <li>{@link #isSeasonal()} — is the player currently on a Leagues world?
 *       When false, all league-specific filtering is bypassed.</li>
 *   <li>{@link #isUnlocked(LeagueRegion)} — has the player unlocked the
 *       supplied region? Always-unlocked regions
 *       ({@link LeagueRegion#isAlwaysUnlocked()}) return {@code true}
 *       regardless of seasonal status; always-blocked regions
 *       ({@link LeagueRegion#isAlwaysBlocked()}) always return {@code false}
 *       when seasonal.</li>
 * </ul>
 *
 * <p>
 * The unlock set is rebuilt from the {@code LEAGUE_AREA_SELECTION_*} varbit
 * slots ({@link #AREA_SELECTION_VARBITS}). Each slot stores a numeric area
 * id matching the wiki's enumeration (mapping defined in
 * {@link #AREA_VARBIT_TO_REGION}):
 * </p>
 * <ul>
 *   <li>Slot 0 ({@code 10662}) — pre-set to Varlamore on a seasonal world.</li>
 *   <li>Slot 1 ({@code 10663}) — Karamja, awarded for free with the player's
 *       first paid pick at 80 tasks.</li>
 *   <li>Slots 2-3 ({@code 10664}/{@code 10665}) — the player's three area
 *       picks at 200/300/450 tasks.</li>
 *   <li>Slots 4-5 ({@code 10666}/{@code 10667}) — reserved by the game for
 *       additional bonus unlocks; we read them defensively.</li>
 * </ul>
 *
 * <p>
 * The mapping is deliberately hard-coded here — these IDs are known not to
 * change during a league season.
 * </p>
 */
public class LeagueModeState
{
	/**
	 * Varbit IDs storing the league area unlocks. The values match
	 * {@code LEAGUE_AREA_SELECTION_0..5} from RuneLite's gameval VarbitID
	 * table. Slot 0 is the auto-set Varlamore slot, slot 1 is the Karamja
	 * free pick, and the remaining slots correspond to the three player
	 * picks at 200/300/450 tasks plus two bonus slots reserved by the game.
	 */
	static final int[] AREA_SELECTION_VARBITS = {
		10662, 10663, 10664, 10665, 10666, 10667,
	};

	/**
	 * Maps the numeric area id stored in a {@code LEAGUE_AREA_SELECTION_*}
	 * varbit to its {@link LeagueRegion}. Numbering was found through trial
	 * and error (id 1 = Misthalin is included for completeness even though
	 * it is never selectable).
	 */
	private static final Map<Integer, LeagueRegion> AREA_VARBIT_TO_REGION;

	static
	{
		AREA_VARBIT_TO_REGION = Map.ofEntries(
			Map.entry(1, LeagueRegion.MISTHALIN),
			Map.entry(2, LeagueRegion.KARAMJA),
			Map.entry(3, LeagueRegion.ASGARNIA),
			Map.entry(4, LeagueRegion.KANDARIN),
			Map.entry(5, LeagueRegion.MORYTANIA),
			Map.entry(6, LeagueRegion.DESERT),
			Map.entry(7, LeagueRegion.TIRANNWN),
			Map.entry(8, LeagueRegion.FREMENNIK),
			Map.entry(11, LeagueRegion.WILDERNESS),
			Map.entry(20, LeagueRegion.KOUREND),
			Map.entry(21, LeagueRegion.VARLAMORE));
	}

	/**
	 * The current facts, replaced wholesale by every {@link #refresh} /
	 * {@link #setForTest}. Held as one immutable object so a search thread
	 * reading through this live state always sees a consistent snapshot —
	 * never torn fields from two overlapping refreshes — and so
	 * {@link #snapshot()} can hand a per-refresh requirement context a frozen
	 * view that later refreshes cannot mutate.
	 */
	private volatile LeagueModeSnapshot current = LeagueModeSnapshot.NON_SEASONAL;

	/**
	 * Re-reads the world type and the area-unlock varbits through the player
	 * state source. Called from {@code PathfinderConfig.refresh()} which
	 * already runs on world change, login, and config edits.
	 *
	 * <p>
	 * On a {@code null} source this resets to a non-seasonal state with no
	 * extra unlocks; this is the safe default because non-seasonal logic
	 * mirrors normal pathfinding.
	 * </p>
	 */
	public void refresh(PlayerStateSource source)
	{
		if (source == null)
		{
			current = LeagueModeSnapshot.NON_SEASONAL;
			return;
		}
		EnumSet<WorldType> worldTypes = source.worldType();
		boolean seasonal = worldTypes != null && worldTypes.contains(WorldType.SEASONAL);
		boolean deadman = worldTypes != null && worldTypes.contains(WorldType.DEADMAN);

		EnumSet<LeagueRegion> next = EnumSet.noneOf(LeagueRegion.class);
		if (seasonal)
		{
			for (int varbitId : AREA_SELECTION_VARBITS)
			{
				addRegionFromSlot(source, varbitId, next);
			}
		}
		current = new LeagueModeSnapshot(seasonal, deadman, next);
	}

	/**
	 * The facts of the last refresh as an immutable value. A per-refresh
	 * requirement context retains this instead of this live object, so its
	 * verdicts cannot track a later refresh's writes.
	 */
	public LeagueModeSnapshot snapshot()
	{
		return current;
	}

	public boolean isSeasonal()
	{
		return current.isSeasonal();
	}

	/**
	 * Whether the player is on a Deadman Mode world ({@link WorldType#DEADMAN};
	 * tournament worlds are flagged DEADMAN too). Tracked here because this
	 * object already owns world-type detection.
	 */
	public boolean isDeadman()
	{
		return current.isDeadman();
	}

	/**
	 * Whether the supplied region is currently traversable. Outside of
	 * seasonal mode every region is considered unlocked.
	 */
	public boolean isUnlocked(LeagueRegion region)
	{
		return current.isUnlocked(region);
	}

	/**
	 * Whether the supplied tile is in the always-blocked region while the
	 * player is on a seasonal world. Returns {@code false} on non-seasonal
	 * worlds so normal pathfinding is unaffected.
	 */
	public boolean isInBlockedRegion(int packedPoint)
	{
		return current.isInBlockedRegion(packedPoint);
	}

	/**
	 * Test hook: forces the seasonal flag and unlock set without touching
	 * the client. The Deadman flag keeps its current value, matching the
	 * pre-snapshot behaviour where this only replaced seasonal state.
	 */
	public void setForTest(boolean seasonal, Set<LeagueRegion> unlocked)
	{
		current = new LeagueModeSnapshot(seasonal, current.isDeadman(), unlocked);
	}

	private static void addRegionFromSlot(PlayerStateSource source, int varbitId, Set<LeagueRegion> out)
	{
		int value = source.varbit(varbitId);
		if (value <= 0)
		{
			return;
		}
		LeagueRegion region = AREA_VARBIT_TO_REGION.get(value);
		if (region != null)
		{
			out.add(region);
		}
	}
}

package shortestpath.leagues;

import java.util.Map;

import shortestpath.WorldPointUtil;
import shortestpath.transport.ResourceLoader;

/**
 * Resolves a packed world point to its {@link LeagueRegion} for the Demonic
 * Pacts League.
 *
 * <p>
 * Mirrors the static-utility shape of
 * {@link shortestpath.pathfinder.WildernessChecker}. The mapping is keyed by
 * OSRS map region id (a 64x64-tile chunk identifier matching
 * {@code WorldPoint.getRegionID()}: {@code (x >> 6) << 8 | (y >> 6)}) and
 * loaded from {@code /leagues/regions.tsv} on first access.
 * </p>
 *
 * <p>
 * Tiles whose region id is absent from the mapping fall back to
 * {@link LeagueRegion#NEUTRAL}. This is deliberate: it covers instances and
 * dynamic regions (POH, raids, dungeon entrances) which are universally
 * accessible during the league regardless of unlocked areas.
 * </p>
 */
public class LeagueRegionChecker
{
	private static volatile Map<Integer, LeagueRegion> regionsById;

	private LeagueRegionChecker()
	{
	}

	/**
	 * Returns the league region containing the supplied packed world point.
	 * Never returns {@code null}; unmapped tiles resolve to
	 * {@link LeagueRegion#NEUTRAL}.
	 */
	public static LeagueRegion getRegion(int packedPoint)
	{
		final int x = WorldPointUtil.unpackWorldX(packedPoint);
		final int y = WorldPointUtil.unpackWorldY(packedPoint);
		final int regionId = ((x >> 6) << 8) | (y >> 6);
		return regions().getOrDefault(regionId, LeagueRegion.NEUTRAL);
	}

	/**
	 * Returns the underlying region-id-to-region map. Lazily initialised on
	 * first call.
	 */
	private static Map<Integer, LeagueRegion> regions()
	{
		Map<Integer, LeagueRegion> snapshot = regionsById;
		if (snapshot == null)
		{
			synchronized (LeagueRegionChecker.class)
			{
				snapshot = regionsById;
				if (snapshot == null)
				{
					snapshot = ResourceLoader.leagueRegions();
					regionsById = snapshot;
				}
			}
		}
		return snapshot;
	}
}

package shortestpath.overlay;

import shortestpath.settings.ConfigKey;
import java.awt.*;
import java.awt.image.BufferedImage;
import java.util.List;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.widgets.Widget;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.*;
import shortestpath.WorldPointUtil;
import shortestpath.pathfinder.*;
import shortestpath.presentation.PathAnnotator;
import shortestpath.scheduler.PathScheduler;
import shortestpath.settings.Settings;

abstract class AbstractHighlightOverlay extends Overlay
{
	// Extra tiles of grace past the recalculation distance: beyond it the route
	// recalculates but the stale path stays on screen while the replacement is
	// being computed, so the nearest step is still the best guide meanwhile.
	private static final int REPLANNING_MARGIN_TILES = 5;

	protected final Client client;
	protected final PathScheduler scheduler;
	protected final PathAnnotator annotator;
	protected final Settings settings;

	protected AbstractHighlightOverlay(Client client, PathScheduler scheduler, PathAnnotator annotator,
		Settings settings)
	{
		this.client = client;
		this.scheduler = scheduler;
		this.annotator = annotator;
		this.settings = settings;
		setPosition(OverlayPosition.DYNAMIC);
		setPriority(Overlay.PRIORITY_LOW);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	/**
	 * The shared highlight pipeline: the subclass gate, the active-search
	 * and path guards, the per-overlay extra gates, the player-path index
	 * bound, then the subclass draw tail. Evaluation order matches the
	 * original trio bodies stage for stage — the extra gates ran after the
	 * path guards and before the path-index bound, and they keep that
	 * placement here.
	 */
	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!enabled())
		{
			return null;
		}

		ActiveSearch search = scheduler.getActiveSearch();
		if (search == null)
		{
			return null;
		}

		List<PathStep> path = search.getPath();
		if (path == null || path.isEmpty())
		{
			return null;
		}

		if (!extraGatesPass())
		{
			return null;
		}

		int pathIndex = getPlayerPathIndex(path);
		if (!pathIndexUsable(pathIndex, path))
		{
			return null;
		}

		return drawHighlights(graphics, path, pathIndex, search);
	}

	/** Whether this overlay's highlight setting is on. */
	protected abstract boolean enabled();

	/**
	 * Per-overlay conjuncts that run after the path guards and before the
	 * path-index bound (bank's widget/open/destination checks, spellbook's
	 * spell-layer widget). Inventory has none.
	 */
	protected boolean extraGatesPass()
	{
		return true;
	}

	/**
	 * The per-overlay path-index bound. The default requires a next step
	 * ({@code pathIndex + 1 < path.size()}) because the draw tail indexes
	 * {@code path.get(pathIndex + 1)}; bank never does, so it overrides
	 * this with the looser {@code pathIndex >= 0}.
	 */
	protected boolean pathIndexUsable(int pathIndex, List<PathStep> path)
	{
		return pathIndex >= 0 && pathIndex + 1 < path.size();
	}

	/** The subclass draw tail: id-set computation plus per-child drawing. */
	protected abstract Dimension drawHighlights(Graphics2D graphics, List<PathStep> path,
		int pathIndex, ActiveSearch search);

	/**
	 * The shared per-widget outline loop: draw the {@code colour} outline on every
	 * non-hidden widget carrying an item id in {@code ids}, minus any id in
	 * {@code skipIds} — the equipped-staff exclusion, where wearing the item already
	 * satisfies the requirement so it is never highlighted. A {@code quantity} of 0
	 * reads the widget's own stack size; a positive value forces it — the equipment
	 * arm pins 1 because worn items are not stacks.
	 */
	static void drawItemOutlines(Graphics2D graphics, ItemManager itemManager, Widget[] widgets,
		Set<Integer> ids, Color colour)
	{
		drawItemOutlines(graphics, itemManager, widgets, ids, null, 0, colour);
	}

	static void drawItemOutlines(Graphics2D graphics, ItemManager itemManager, Widget[] widgets,
		Set<Integer> ids, Set<Integer> skipIds, int quantity, Color colour)
	{
		if (widgets == null)
		{
			return;
		}
		for (Widget item : widgets)
		{
			if (item == null || item.isHidden() || item.getItemId() < 0
				|| !ids.contains(item.getItemId())
				|| (skipIds != null && skipIds.contains(item.getItemId())))
			{
				continue;
			}
			BufferedImage outline = itemManager.getItemOutline(item.getItemId(),
				quantity > 0 ? quantity : item.getItemQuantity(), colour);
			if (outline != null)
			{
				graphics.drawImage(outline, item.getBounds().x, item.getBounds().y, null);
			}
		}
	}

	protected int getPlayerPathIndex(List<PathStep> path)
	{
		if (client.getLocalPlayer() == null)
		{
			return -1;
		}
		int playerLocation = WorldPointUtil.fromLocalInstance(client, client.getLocalPlayer().getLocalLocation());
		return playerPathIndex(path, playerLocation, settings.num(ConfigKey.RECALCULATE_DISTANCE));
	}

	static int playerPathIndex(List<PathStep> path, int playerLocation, int recalculateDistance)
	{
		for (int i = 0; i < path.size(); i++)
		{
			if (path.get(i).getPackedPosition() == playerLocation)
			{
				return i;
			}
		}

		// On an exact-match miss the player may still be close enough to the path that the
		// route has not been recalculated; keep the highlight on the nearest step for as
		// long as the displayed route survives. The strict bound mirrors isNearPath, and
		// steps on other planes (Integer.MAX_VALUE distance) are never candidates.
		int maxDistance = recalculateDistance < 0 ? -1 : recalculateDistance + REPLANNING_MARGIN_TILES;
		int bestIndex = -1;
		int bestDistance = Integer.MAX_VALUE;
		for (int i = 0; i < path.size(); i++)
		{
			int distance = WorldPointUtil.distanceBetween(playerLocation, path.get(i).getPackedPosition());
			if (distance == Integer.MAX_VALUE || (maxDistance >= 0 && distance >= maxDistance))
			{
				continue;
			}
			if (distance < bestDistance)
			{
				bestDistance = distance;
				bestIndex = i;
			}
		}
		return bestIndex;
	}
}

package shortestpath.overlay;

import java.awt.Graphics2D;
import java.awt.geom.*;

/**
 * Draws a small triangular arrowhead at the end of a line segment, rotated to the segment's
 * direction, in the current colour of the graphics context.
 * <p>
 * Adapted from Quest Helper's {@code DirectionArrow.drawLineArrowHead}
 * (Copyright (c) 2021, Zoinkwiz &lt;https://github.com/Zoinkwiz&gt;, BSD 2-Clause licence),
 * as also used by the port-tasks plugin.
 */
public final class ArrowHead
{
	private ArrowHead()
	{
	}

	/**
	 * Fills an arrowhead pointing from (x1, y1) towards (x2, y2), with its tip at (x2, y2).
	 *
	 * @param size length of the arrowhead in pixels (its width is {@code size})
	 */
	public static void draw(Graphics2D graphics, double x1, double y1, double x2, double y2, double size)
	{
		Path2D head = new Path2D.Double();
		head.moveTo(0, 0);
		head.lineTo(-size / 2.0, -size);
		head.lineTo(size / 2.0, -size);
		head.closePath();

		AffineTransform tx = new AffineTransform();
		double angle = Math.atan2(y2 - y1, x2 - x1);
		tx.translate(x2, y2);
		tx.rotate(angle - Math.PI / 2d);

		Graphics2D g = (Graphics2D) graphics.create();
		// Compose (not replace) so the overlay's existing transform/clip stay intact.
		g.transform(tx);
		g.fill(head);
		g.dispose();
	}
}

package shortestpath.overlay;

import shortestpath.settings.ConfigKey;
import com.google.inject.Inject;
import java.awt.*;
import java.util.List;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.game.ItemManager;

import shortestpath.pathfinder.*;
import shortestpath.presentation.*;
import shortestpath.scheduler.PathScheduler;
import shortestpath.settings.Settings;

public class BankItemHighlightOverlay extends AbstractHighlightOverlay
{
	private final ItemManager itemManager;
	// extraGatesPass() fetches the container; drawHighlights reads it in the
	// same render pass, keeping the widget lookup once per frame.
	private Widget bankContainer;

	@Inject
	public BankItemHighlightOverlay(Client client, ItemManager itemManager, Settings settings,
		PathScheduler scheduler, PathAnnotator annotator)
	{
		super(client, scheduler, annotator, settings);
		this.itemManager = itemManager;
	}

	@Override
	protected boolean enabled()
	{
		return settings.bool(ConfigKey.HIGHLIGHT_BANK_PICKUP_ITEMS);
	}

	@Override
	protected boolean extraGatesPass()
	{
		bankContainer = client.getWidget(InterfaceID.Bankmain.ITEMS);
		if (bankContainer == null || bankContainer.isHidden())
		{
			return false;
		}

		if (!annotator.isBankOpen())
		{
			return false;
		}

		return annotator.getDestinations("bank") != null;
	}

	@Override
	protected boolean pathIndexUsable(int pathIndex, List<PathStep> path)
	{
		// Bank never indexes path.get(pathIndex + 1) — it only needs the
		// player to be on the path at all.
		return pathIndex >= 0;
	}

	@Override
	protected Dimension drawHighlights(Graphics2D graphics, List<PathStep> path, int pathIndex,
		ActiveSearch search)
	{
		BankPickupRequirements.BankPickupResult pickup = annotator.getBankPickup(path, pathIndex, search);
		if (pickup == null || pickup.bankItemIds.isEmpty())
		{
			return null;
		}

		// bankContainer was populated by extraGatesPass() earlier in this same
		// render pass — the template always calls extraGatesPass before
		// drawHighlights, so the widget is non-null here (the gate returns
		// false on a null/hidden container).
		Color highlight = settings.get(ConfigKey.COLOUR_BANK_PICKUP_HIGHLIGHT);
		drawItemOutlines(graphics, itemManager, bankContainer.getChildren(), pickup.bankItemIds,
			highlight);

		return null;
	}
}

package shortestpath.overlay;

import com.google.inject.Inject;
import java.awt.*;
import java.util.List;
import net.runelite.api.Client;
import net.runelite.client.ui.overlay.*;
import net.runelite.client.ui.overlay.components.*;
import shortestpath.scheduler.*;
import shortestpath.pathfinder.*;

public class DebugOverlayPanel extends OverlayPanel
{
	private static final int PANEL_WIDTH = 230;
	private static final Color PROBLEM = Color.RED;

	private final Client client;
	private final DebugState debugState;
	private final PathScheduler scheduler;

	@Inject
	public DebugOverlayPanel(Client client, DebugState debugState, PathScheduler scheduler)
	{
		super();
		this.client = client;
		this.debugState = debugState;
		this.scheduler = scheduler;

		setPosition(OverlayPosition.TOP_LEFT);
		panelComponent.setPreferredSize(new Dimension(PANEL_WIDTH, 0));
	}

	private LineComponent makeLine(String left, String right)
	{
		return makeLine(left, right, Color.WHITE);
	}

	private LineComponent makeLine(String left, String right, Color rightColor)
	{
		return LineComponent.builder()
			.left(left)
			.right(right)
			.rightColor(rightColor)
			.build();
	}

	private LineComponent makeHeader(String text)
	{
		return LineComponent.builder()
			.left(text)
			.leftColor(Color.ORANGE)
			.build();
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		List<LayoutableRenderableEntity> components = panelComponent.getChildren();
		DebugState debug = debugState;
		int tick = client.getTickCount();

		components.add(
			TitleComponent.builder()
				.text("Shortest Path Debug")
				.color(Color.ORANGE)
				.build());

		renderSearch(components, debug);
		renderRestart(components, debug, tick);
		renderErrors(components, debug, tick);

		return super.render(graphics);
	}

	private void renderSearch(List<LayoutableRenderableEntity> components, DebugState debug)
	{
		ActiveSearch search = scheduler.getActiveSearch();
		if (search == null)
		{
			components.add(makeHeader("No search"));
			return;
		}

		PathfinderResult result = search.getResult();
		boolean problem = search == debug.getCancelledSearch() || isFailure(result);
		components.add(LineComponent.builder()
			.left(search.backendName() + " \u00b7 " + state(search, result, debug))
			.leftColor(problem ? PROBLEM : Color.ORANGE)
			.build());

		if (result != null)
		{
			components.add(makeLine("Result:", result.getTerminationReason() + ", cost " + result.getPathCost(),
				isFailure(result) ? PROBLEM : Color.WHITE));
			if (result.getMessage() != null)
			{
				components.add(makeLine("Message:", result.getMessage(), PROBLEM));
			}
		}

		List<PathStep> path = search.getPath();
		String tiles = path == null ? "none" : path.size() + " tiles";
				// While recalculating, the shown path is the previous route but the click count is the
		// new search's — suppress it rather than mix the two.
		if (!search.isShowingProvisionalPath())
		{
			tiles += ", " + search.getClickPoints().size() + " clicks";
		}
		components.add(makeLine("Path:", tiles));

		PathfinderStats stats = search.getStats();
		if (stats == null)
		{
			return;
		}
		components.add(makeLine("Time:", PathfinderStats.millis(stats.getElapsedTimeNanos())));
		search.debugStats().forEach((label, text) -> components.add(makeLine("  " + label + ":", text)));
	}

	private void renderRestart(List<LayoutableRenderableEntity> components, DebugState debug, int tick)
	{
		DebugState.Restart restart = debug.getRestart();
		if (restart == null)
		{
			return;
		}
		components.add(makeLine("Restarts:", restart.count + " (last: " + restart.reason + ", "
			+ ago(restart.tick, tick) + ")"));
		String outcome = restart.outcome;
		if (!DebugState.STARTED.equals(outcome))
		{
			components.add(makeLine("Restart outcome:", outcome, PROBLEM));
		}
	}

	private void renderErrors(List<LayoutableRenderableEntity> components, DebugState debug, int tick)
	{
		if (debug.getClientErrorCount() > 0)
		{
			components.add(makeLine("Client error:", error(debug.getClientErrorCount(), debug.getClientError(),
				debug.getClientErrorTick(), tick), PROBLEM));
		}
		if (debug.getSearchErrorCount() > 0)
		{
			components.add(makeLine("Search error:", error(debug.getSearchErrorCount(), debug.getSearchError(),
				debug.getSearchErrorTick(), tick), PROBLEM));
		}
	}

	private static String state(ActiveSearch search, PathfinderResult result, DebugState debug)
	{
		if (search == debug.getCancelledSearch())
		{
			return "cancelled, not replaced";
		}
		if (search.isShowingProvisionalPath())
		{
			return "running, previous route shown";
		}
		if (!search.isDone())
		{
			return "running";
		}
		return isFailure(result) ? "failed" : "done";
	}

	private static boolean isFailure(PathfinderResult result)
	{
		return result != null && result.getTerminationReason() == PathTerminationReason.BACKEND_FAILURE;
	}

	private static String error(int count, String message, int errorTick, int tick)
	{
		return count + "x, last " + ago(errorTick, tick) + ": " + message;
	}

	private static String ago(int then, int now)
	{
		return then < 0 ? "-" : (now - then) + " ticks ago";
	}
}

package shortestpath.overlay;

import shortestpath.settings.ConfigKey;
import com.google.inject.Inject;
import java.awt.*;
import java.util.*;
import java.util.List;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.game.ItemManager;
import shortestpath.pathfinder.*;
import shortestpath.presentation.PathAnnotator;
import shortestpath.scheduler.PathScheduler;
import shortestpath.transport.*;
import shortestpath.requirement.model.*;
import shortestpath.settings.Settings;

public class InventoryHighlightOverlay extends AbstractHighlightOverlay
{
	private static final int[] EQUIPMENT_SLOT_WIDGET_IDS = {
		InterfaceID.Wornitems.SLOT0,
		InterfaceID.Wornitems.SLOT1,
		InterfaceID.Wornitems.SLOT2,
		InterfaceID.Wornitems.SLOT3,
		InterfaceID.Wornitems.SLOT4,
		InterfaceID.Wornitems.SLOT5,
		InterfaceID.Wornitems.SLOT7,
		InterfaceID.Wornitems.SLOT9,
		InterfaceID.Wornitems.SLOT10,
		InterfaceID.Wornitems.SLOT12,
		InterfaceID.Wornitems.SLOT13,
	};

	private final ItemManager itemManager;
	// Fairy-ring scan cache: pathfinder searches hand out immutable path
	// lists, so the last scanned list doubles as the cache key by reference
	// identity. lastFairyRingEdgeIndex is the last edge index whose edge
	// offers a fairy ring; fairyRingItemIds is the union of item
	// requirements those rings carry — the injected staff rule, so a
	// staff-free ring (POH, or every ring with Lumbridge Elite done)
	// contributes nothing.
	private List<PathStep> scannedPath;
	private int lastFairyRingEdgeIndex = -1;
	private Set<Integer> fairyRingItemIds = Set.of();

	@Inject
	public InventoryHighlightOverlay(Client client, ItemManager itemManager, Settings settings,
		PathScheduler scheduler, PathAnnotator annotator)
	{
		super(client, scheduler, annotator, settings);
		this.itemManager = itemManager;
	}

	@Override
	protected boolean enabled()
	{
		return settings.bool(ConfigKey.HIGHLIGHT_INVENTORY_ITEMS);
	}

	@Override
	protected Dimension drawHighlights(Graphics2D graphics, List<PathStep> path, int pathIndex,
		ActiveSearch search)
	{
		Set<Transport> transports = annotator.transportsForEdge(path.get(pathIndex), path.get(pathIndex + 1));
		Set<Integer> itemsToHighlight = new HashSet<>();

		for (Transport transport : transports)
		{
			TransportType type = transport.getType();
			if (!TransportType.TELEPORTATION_ITEM.equals(type)
				&& !TransportType.TELEPORTATION_BOX.equals(type)
				&& !TransportType.FAIRY_RING.equals(type)
				&& !TransportType.QUETZAL_WHISTLE.equals(type))
			{
				continue;
			}
			addRequirementIds(transport.getItemRequirements(), itemsToHighlight);
		}

		// A carried staff satisfies the ring wherever it is, so surface it
		// while a staff-requiring ring remains ahead — not only while
		// standing on the ring edge. The ids ride the ring's own injected
		// requirement; nothing is derived here.
		scanFairyRings(path);
		if (lastFairyRingEdgeIndex >= pathIndex)
		{
			itemsToHighlight.addAll(fairyRingItemIds);
		}

		if (itemsToHighlight.isEmpty())
		{
			return null;
		}

		Color highlight = settings.get(ConfigKey.COLOUR_BANK_PICKUP_HIGHLIGHT);

		// Highlight matching items in the inventory
		Widget inventoryContainer = client.getWidget(InterfaceID.Inventory.ITEMS);
		if (inventoryContainer != null && !inventoryContainer.isHidden())
		{
			drawItemOutlines(graphics, itemManager, inventoryContainer.getChildren(),
				itemsToHighlight, highlight);
		}

		// Highlight matching items in the equipment tab. Equipped items are
		// rendered by child item widgets of the static slot components; the slot
		// widgets themselves never carry an item id. The fairy-staff ids are
		// the skip set — wearing one already satisfies the ring, so it needs
		// no outline — and equipment outlines pin quantity 1 because worn
		// items are not stacks.
		for (int slotWidgetId : EQUIPMENT_SLOT_WIDGET_IDS)
		{
			Widget slot = client.getWidget(slotWidgetId);
			if (slot == null || slot.isHidden())
			{
				continue;
			}
			drawItemOutlines(graphics, itemManager, slot.getChildren(), itemsToHighlight,
				fairyRingItemIds, 1, highlight);
		}

		return null;
	}

	/**
	 * Scans the path once (paths are immutable per search) for fairy-ring
	 * edges, recording the last ring edge index and the union of item
	 * requirement ids those rings carry. The ring's requirements are read
	 * straight off the transport — the injected staff rule — so this stays
	 * a generic read with no fairy-specific item knowledge of its own.
	 */
	private void scanFairyRings(List<PathStep> path)
	{
		if (path == scannedPath)
		{
			return;
		}
		scannedPath = path;
		lastFairyRingEdgeIndex = -1;
		Set<Integer> ids = new HashSet<>();
		for (int i = 0; i + 1 < path.size(); ++i)
		{
			for (Transport transport : annotator.transportsForEdge(path.get(i), path.get(i + 1)))
			{
				if (TransportType.FAIRY_RING.equals(transport.getType()))
				{
					lastFairyRingEdgeIndex = i;
					addRequirementIds(transport.getItemRequirements(), ids);
				}
			}
		}
		fairyRingItemIds = ids;
	}

	private static void addRequirementIds(TransportItems items, Set<Integer> target)
	{
		if (items == null)
		{
			return;
		}
		for (ItemRequirement req : items.getRequirements())
		{
			addItemIds(target, req.getItemIds());
			addItemIds(target, req.getStaffIds());
			addItemIds(target, req.getOffhandIds());
		}
	}

	private static void addItemIds(Set<Integer> target, int[] ids)
	{
		if (ids != null)
		{
			for (int id : ids)
			{
				if (id >= 0)
				{
					target.add(id);
				}
			}
		}
	}
}

package shortestpath.overlay;

import java.util.*;
import java.util.function.IntConsumer;

import shortestpath.PrimitiveIntHashMap;
import shortestpath.pathfinder.*;
import shortestpath.presentation.PathAnnotator;
import shortestpath.transport.Transport;

/**
 * The shared display-transport walk: iterate the annotator's all-display
 * map in occupied-slot order, skip the undefined-origin teleport bucket,
 * resolve the origin's available array (empty when absent), and yield each
 * non-null, non-teleport transport together with its identity availability.
 * <p>
 * The {@code Arrays.asList(availableAtOrigin).contains(b)} read is identity
 * matching — {@link Transport} has no {@code equals} — so the arrays the
 * annotator returned pass through untouched; copying or canonicalizing them
 * would silently break the availability colours. Iterating {@code keys()} on
 * the same map instance the inner {@code getOrDefault} reads preserves the
 * occupied-slot order both arms relied on.
 * <p>
 * Per-overlay origin gates, destination gates, glyph accumulation, and
 * drawing all stay in the {@link TransportVisitor}: the walker owns only the
 * uniform skeleton. {@code beginOrigin} runs once per origin — it is the
 * gate and the slot where a caller computes per-origin values (the scene
 * arm's tile centre, the map arm's projected origin) without projecting
 * twice. {@code endOrigin} runs once per visited origin even when nothing
 * was yielded — the scene arm's explicit colour reset and label draw are
 * unconditional in the original.
 * <p>
 * This package is a leaf: nothing here may reference the plugin type.
 */
final class OverlayDrawing
{
	private OverlayDrawing()
	{
	}

	interface TransportVisitor
	{
		/**
		 * The origin gate plus per-origin preamble, called exactly once per
		 * origin before its transports are walked. Return {@code false} to
		 * skip the origin entirely.
		 */
		boolean beginOrigin(int origin);

		/** Called once per yielded transport. */
		void visit(int origin, Transport transport, boolean available);

		/**
		 * Called once per visited origin after its transports — including
		 * origins that yielded nothing.
		 */
		default void endOrigin(int origin)
		{
		}
	}

	static void forEachDisplayTransport(PathAnnotator annotator, TransportVisitor visitor)
	{
		PrimitiveIntHashMap<Transport[]> allTransports = annotator.getAllDisplayTransports();
		PrimitiveIntHashMap<Transport[]> availableTransports = annotator.getTransports();

		for (int a : allTransports.keys())
		{
			// skip the teleport bucket; then the per-overlay origin gate
			if (a == Transport.UNDEFINED_ORIGIN || !visitor.beginOrigin(a))
			{
				continue;
			}

			Transport[] availableAtOrigin = availableTransports.getOrDefault(a, TransportAvailability.EMPTY_TRANSPORTS);

			for (Transport b : allTransports.getOrDefault(a, TransportAvailability.EMPTY_TRANSPORTS))
			{
				if (b == null || (b.getType() != null && b.getType().isTeleport()))
				{
					continue; // skip teleports
				}

				visitor.visit(a, b, Arrays.asList(availableAtOrigin).contains(b));
			}

			visitor.endOrigin(a);
		}
	}

	/**
	 * The shared {@code " (Exit: …)"} suffix both overlays append to a
	 * transport label when the transport leads into a POH — the tile
	 * overlay's per-transport hint and the world-map tooltip row. Returns
	 * {@code null} when there is no exit info to append, so each caller
	 * keeps its own append target and its own argument order.
	 */
	static String pohExitSuffix(PathAnnotator annotator, int destination, List<PathStep> path,
		int pathIndex)
	{
		String pohExitInfo = annotator.getPohExitInfo(destination, path, pathIndex);
		return pohExitInfo == null ? null : " (Exit: " + pohExitInfo + ")";
	}

	/**
	 * The shared unreached-target pass every path overlay runs after its route
	 * drawing: yield each requested target the returned path does not already end
	 * on, so the caller can mark it (calculating colour, tooltip, tile). The
	 * {@code !path.isEmpty()} guard is part of the contract — no markers render
	 * before a route exists.
	 */
	static void forEachUnreachedTarget(ActiveSearch search, List<PathStep> path, IntConsumer draw)
	{
		for (int target : search.getTargets().points())
		{
			if (!path.isEmpty() && target != path.get(path.size() - 1).getPackedPosition())
			{
				draw.accept(target);
			}
		}
	}
}

package shortestpath.overlay;

import shortestpath.settings.ConfigKey;
import com.google.inject.Inject;
import java.awt.*;
import java.awt.geom.Area;
import java.util.List;
import java.util.Objects;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.client.ui.overlay.*;
import shortestpath.*;
import shortestpath.pathfinder.*;
import shortestpath.presentation.PathAnnotator;
import shortestpath.scheduler.*;
import shortestpath.settings.Settings;
import shortestpath.transport.Transport;
import shortestpath.widgets.WidgetGeometry;

public class PathMapOverlay extends Overlay
{
	private final Client client;
	private final Settings settings;
	private final PathRenderState renderState;
	private final PathScheduler scheduler;
	private final WidgetGeometry geometry;
	private final PathAnnotator annotator;

	@Inject
	private PathMapOverlay(Client client, Settings settings, PathRenderState renderState,
		PathScheduler scheduler, WidgetGeometry geometry, PathAnnotator annotator)
	{
		this.client = client;
		this.settings = settings;
		this.renderState = renderState;
		this.scheduler = scheduler;
		this.geometry = geometry;
		this.annotator = annotator;
		setPosition(OverlayPosition.DYNAMIC);
		setPriority(Overlay.PRIORITY_LOW);
		setLayer(OverlayLayer.MANUAL);
		drawAfterLayer(InterfaceID.Worldmap.MAP_CONTAINER);
	}

	private static final Color COLOR_AVAILABLE = Color.WHITE;
	private static final Color COLOR_UNAVAILABLE = Color.ORANGE;

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!settings.bool(ConfigKey.DRAW_MAP))
		{
			return null;
		}

		if (!geometry.worldMapOpen())
		{
			return null;
		}

		Rectangle worldMapRectangle = Objects.requireNonNull(client.getWidget(InterfaceID.Worldmap.MAP_CONTAINER)).getBounds();
		Area worldMapClipArea = geometry.getWorldMapClipArea(worldMapRectangle);
		graphics.setClip(worldMapClipArea);

		if (settings.bool(ConfigKey.DRAW_COLLISION_MAP))
		{
			graphics.setColor(settings.get(ConfigKey.COLOUR_COLLISION_MAP));
			int mapWorldPoint = geometry.calculateMapPoint(worldMapRectangle.x, worldMapRectangle.y);
			int extentX = WorldPointUtil.unpackWorldX(mapWorldPoint);
			int extentY = WorldPointUtil.unpackWorldY(mapWorldPoint);
			int extentWidth = getWorldMapExtentWidth(worldMapRectangle);
			int extentHeight = getWorldMapExtentHeight(worldMapRectangle);
			final CollisionMap map = annotator.getMap();
			final int z = client.getTopLevelWorldView().getPlane();
			for (int x = extentX; x < (extentX + extentWidth + 1); x++)
			{
				for (int y = extentY - extentHeight; y < (extentY + 1); y++)
				{
					if (map.isBlocked(x, y, z))
					{
						drawOnMap(graphics, WorldPointUtil.packWorldPoint(x, y, z), false, null);
					}
				}
			}
		}

		if (settings.bool(ConfigKey.DRAW_TRANSPORTS))
		{
			OverlayDrawing.forEachDisplayTransport(annotator, new OverlayDrawing.TransportVisitor()
			{
				private Point mapA;

				@Override
				public boolean beginOrigin(int origin)
				{
					mapA = geometry.mapWorldPointToGraphicsPoint(origin);
					return mapA != null && worldMapClipArea.contains(mapA.getX(), mapA.getY());
				}

				@Override
				public void visit(int origin, Transport b, boolean isAvailable)
				{
					Point mapB = geometry.mapWorldPointToGraphicsPoint(b.getDestination());
					if (mapB == null || !worldMapClipArea.contains(mapB.getX(), mapB.getY()))
					{
						return;
					}

					graphics.setColor(isAvailable ? COLOR_AVAILABLE : COLOR_UNAVAILABLE);
					graphics.drawLine(mapA.getX(), mapA.getY(), mapB.getX(), mapB.getY());
				}
			});
		}

		ActiveSearch search = scheduler.getActiveSearch();
		if (search != null)
		{
			Color colour = renderState.getPathColor();
			List<PathStep> path = search.getPath();
			Point cursorPos = client.getMouseCanvasPosition();
			if (renderState.isSailing())
			{
				// On a boat the path sails the boat's headings: a line along each heading it holds, with a small square
				// at the end of each move
				graphics.setColor(renderState.isPathUnreachable() ? renderState.getPathColor() : PathRenderState.SAILING_PATH_COLOUR);
				for (int i = 0; i < path.size(); i++)
				{
					int point = path.get(i).getPackedPosition();
					if (i > 0)
					{
						drawSolidLineOnMap(graphics, path.get(i - 1).getPackedPosition(), point);
					}
					drawSmallSquareOnMap(graphics, point);
				}
			}
			else if (TileStyle.ARROW_LINE.equals(settings.get(ConfigKey.PATH_STYLE)))
			{
				graphics.setColor(colour);
				drawArrowPath(graphics, path);
			}
			else
			{
				for (int i = 0; i < path.size(); i++)
				{
					graphics.setColor(colour);
					int point = path.get(i).getPackedPosition();
					int lastPoint = (i > 0) ? path.get(i - 1).getPackedPosition() : point;
					if (WorldPointUtil.distanceBetween(point, lastPoint) > 1)
					{
						drawOnMap(graphics, lastPoint, point, true, cursorPos);
					}
					drawOnMap(graphics, point, true, cursorPos);
				}
			}
			OverlayDrawing.forEachUnreachedTarget(search, path, target ->
			{
				graphics.setColor(settings.get(ConfigKey.COLOUR_PATH_CALCULATING));
				drawOnMap(graphics, target, true, cursorPos);
			});
		}

		return null;
	}

	/**
	 * Draws the path as a directed polyline: consecutive same-direction walking steps are compressed
	 * into one straight segment, each segment ends in a small arrowhead showing travel direction, and
	 * teleport/transport jumps are dashed. (Arrowhead technique adapted from Quest Helper's
	 * DirectionArrow, see {@link ArrowHead}.)
	 */
	private void drawArrowPath(Graphics2D graphics, List<PathStep> path)
	{
		final Stroke walkStroke = new BasicStroke(2, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND);
		final Stroke jumpStroke = new BasicStroke(1, BasicStroke.CAP_BUTT, BasicStroke.JOIN_BEVEL, 0, new float[]{9}, 0);

		int i = 0;
		while (i < path.size() - 1)
		{
			int from = path.get(i).getPackedPosition();
			int next = path.get(i + 1).getPackedPosition();

			if (WorldPointUtil.distanceBetween(from, next) > 1)
			{
				// Teleport/transport jump: dashed segment.
				drawMapSegment(graphics, from, next, jumpStroke);
				i++;
				continue;
			}

			// Extend the straight walking run while the direction stays the same.
			int dx = WorldPointUtil.unpackWorldX(next) - WorldPointUtil.unpackWorldX(from);
			int dy = WorldPointUtil.unpackWorldY(next) - WorldPointUtil.unpackWorldY(from);
			int j = i + 1;
			while (j < path.size() - 1)
			{
				int a = path.get(j).getPackedPosition();
				int b = path.get(j + 1).getPackedPosition();
				if (WorldPointUtil.distanceBetween(a, b) > 1
					|| WorldPointUtil.unpackWorldX(b) - WorldPointUtil.unpackWorldX(a) != dx
					|| WorldPointUtil.unpackWorldY(b) - WorldPointUtil.unpackWorldY(a) != dy)
				{
					break;
				}
				j++;
			}
			drawMapSegment(graphics, from, path.get(j).getPackedPosition(), walkStroke);
			i = j;
		}
	}

	private void drawMapSegment(Graphics2D graphics, int from, int to, Stroke stroke)
	{
		Point p1 = geometry.mapWorldPointToGraphicsPoint(from);
		Point p2 = geometry.mapWorldPointToGraphicsPoint(to);
		if (p1 == null || p2 == null)
		{
			return;
		}
		int x1 = p1.getX();
		int y1 = p1.getY();
		int x2 = p2.getX();
		int y2 = p2.getY();
		graphics.setStroke(stroke);
		graphics.drawLine(x1, y1, x2, y2);
		// Skip the head on segments too short to fit it (e.g. zoomed far out).
		if (Math.hypot(x2 - x1, y2 - y1) >= 10)
		{
			ArrowHead.draw(graphics, x1, y1, x2, y2, 7);
		}
	}

	private void drawSmallSquareOnMap(Graphics2D graphics, int point)
	{
		Point p = geometry.mapWorldPointToGraphicsPoint(point);
		Point next = geometry.mapWorldPointToGraphicsPoint(WorldPointUtil.dxdy(point, 1, -1));
		if (p == null || next == null)
		{
			return;
		}
		int x = p.getX();
		int y = p.getY();
		int size = Math.max(2, (next.getX() - x) / 2);
		graphics.fillRect(x - size / 2, y - size / 2, size, size);
	}

	private void drawSolidLineOnMap(Graphics2D graphics, int from, int to)
	{
		Point p1 = geometry.mapWorldPointToGraphicsPoint(from);
		Point p2 = geometry.mapWorldPointToGraphicsPoint(to);
		if (p1 == null || p2 == null)
		{
			return;
		}
		graphics.setStroke(new BasicStroke(2));
		graphics.drawLine(p1.getX(), p1.getY(), p2.getX(), p2.getY());
	}

	private void drawOnMap(Graphics2D graphics, int point, boolean checkHover, Point cursorPos)
	{
		drawOnMap(graphics, point, WorldPointUtil.dxdy(point, 1, -1), checkHover, cursorPos);
	}

	private void drawOnMap(Graphics2D graphics, int point, int offsetPoint, boolean checkHover, Point cursorPos)
	{
		Point start = geometry.mapWorldPointToGraphicsPoint(point);
		Point end = geometry.mapWorldPointToGraphicsPoint(offsetPoint);

		if (start == null || end == null)
		{
			return;
		}

		int startX = start.getX();
		int startY = start.getY();
		int endX = end.getX();
		int endY = end.getY();

		int x = startX;
		int y = startY;
		final int width = endX - x;
		final int height = endY - y;
		x -= width / 2;
		y -= height / 2;

		if (WorldPointUtil.distanceBetween(point, offsetPoint) > 1)
		{
			graphics.setStroke(new BasicStroke(1, BasicStroke.CAP_BUTT, BasicStroke.JOIN_BEVEL, 0, new float[]{9}, 0));
			graphics.drawLine(startX, startY, endX, endY);
		}
		else
		{
			if (checkHover && cursorPos != null &&
				cursorPos.getX() >= x && cursorPos.getX() <= (endX - width / 2) &&
				cursorPos.getY() >= y && cursorPos.getY() <= (endY - width / 2))
			{
				graphics.setColor(graphics.getColor().darker());
			}
			graphics.fillRect(x, y, width, height);
		}
	}

	private int getWorldMapExtentWidth(Rectangle baseRectangle)
	{
		return (WorldPointUtil.unpackWorldX(
			geometry.calculateMapPoint(
				baseRectangle.x + baseRectangle.width,
				baseRectangle.y + baseRectangle.height))
			-
			WorldPointUtil.unpackWorldX(
				geometry.calculateMapPoint(
					baseRectangle.x,
					baseRectangle.y)));
	}

	private int getWorldMapExtentHeight(Rectangle baseRectangle)
	{
		return (WorldPointUtil.unpackWorldY(
			geometry.calculateMapPoint(
				baseRectangle.x,
				baseRectangle.y))
			-
			WorldPointUtil.unpackWorldY(
				geometry.calculateMapPoint(
					baseRectangle.x + baseRectangle.width,
					baseRectangle.y + baseRectangle.height)));
	}
}

package shortestpath.overlay;

import shortestpath.settings.ConfigKey;
import com.google.inject.Inject;
import java.awt.*;
import java.util.*;
import java.util.List;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.client.ui.*;
import net.runelite.client.ui.overlay.*;
import shortestpath.WorldPointUtil;
import shortestpath.pathfinder.*;
import shortestpath.presentation.PathAnnotator;
import shortestpath.scheduler.PathScheduler;
import shortestpath.settings.Settings;
import shortestpath.transport.Transport;
import shortestpath.widgets.WidgetGeometry;

public class PathMapTooltipOverlay extends Overlay
{
	private static final int TOOLTIP_OFFSET_HEIGHT = 25;
	private static final int TOOLTIP_OFFSET_WIDTH = 15;
	private static final int TOOLTIP_PADDING_HEIGHT = 1;
	private static final int TOOLTIP_PADDING_WIDTH = 2;
	private static final int TOOLTIP_TEXT_OFFSET_HEIGHT = -2;

	private final Client client;
	private final Settings settings;
	private final PathScheduler scheduler;
	private final WidgetGeometry geometry;
	private final PathAnnotator annotator;

	@Inject
	private PathMapTooltipOverlay(Client client, Settings settings, PathScheduler scheduler,
		WidgetGeometry geometry, PathAnnotator annotator)
	{
		this.client = client;
		this.settings = settings;
		this.scheduler = scheduler;
		this.geometry = geometry;
		this.annotator = annotator;
		setPosition(OverlayPosition.DYNAMIC);
		setPriority(Overlay.PRIORITY_HIGHEST);
		setLayer(OverlayLayer.MANUAL);
		drawAfterInterface(InterfaceID.WORLDMAP);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!settings.bool(ConfigKey.DRAW_MAP) || !geometry.worldMapOpen())
		{
			return null;
		}

		ActiveSearch search = scheduler.getActiveSearch();
		if (search != null)
		{
			List<PathStep> path = search.getPath();
			Point cursorPos = client.getMouseCanvasPosition();
			for (int i = 0; i < path.size(); i++)
			{
				int nextPoint = WorldPointUtil.UNDEFINED;
				if (path.size() > i + 1)
				{
					nextPoint = path.get(i + 1).getPackedPosition();
				}
				if (drawTooltip(graphics, cursorPos, path.get(i).getPackedPosition(), nextPoint, i + 1, path, i))
				{
					return null;
				}
			}
			OverlayDrawing.forEachUnreachedTarget(search, path, target ->
				drawTooltip(graphics, cursorPos, target, WorldPointUtil.UNDEFINED, -1, path, -1));
		}

		return null;
	}

	private boolean drawTooltip(Graphics2D graphics, Point cursorPos, int point, int nextPoint, int n,
		List<PathStep> path, int pathIndex)
	{
		int offsetPoint = WorldPointUtil.dxdy(point, 1, -1);
		Point start = geometry.mapWorldPointToGraphicsPoint(point);
		Point end = geometry.mapWorldPointToGraphicsPoint(offsetPoint);

		if (start == null || end == null)
		{
			return false;
		}

		int startX = start.getX();
		int startY = start.getY();
		int endX = end.getX();
		int endY = end.getY();

		int width = endX - startX;

		if (cursorPos.getX() < (startX - width / 2) || cursorPos.getX() > (endX - width / 2) ||
			cursorPos.getY() < (startY - width / 2) || cursorPos.getY() > (endY - width / 2))
		{
			return false;
		}

		List<String> rows = new ArrayList<>(Arrays.asList("Shortest path:",
			n < 0 ? "Unused target" : ("Step " + n + " of " + path.size())));
		if (nextPoint != WorldPointUtil.UNDEFINED)
		{
			PathStep currentStep = path.get(pathIndex);
			PathStep nextStep = annotator.nextPathStep(path, pathIndex);
			for (Transport transport : annotator.transportsForEdge(currentStep, nextStep))
			{
				String displayInfo = annotator.formatTransportDisplay(transport);
				if (displayInfo != null && !displayInfo.isEmpty())
				{
					// Check if this transport goes to POH - if so, look ahead to find the exit
					// transport
					String pohExitSuffix = OverlayDrawing.pohExitSuffix(annotator, nextPoint, path, pathIndex);
					if (pohExitSuffix != null)
					{
						displayInfo = displayInfo + pohExitSuffix;
					}
					rows.add(displayInfo);
					break;
				}
			}
		}

		graphics.setFont(FontManager.getRunescapeFont());
		FontMetrics fm = graphics.getFontMetrics();
		int tooltipHeight = fm.getHeight();
		int tooltipWidth = 0;
		if (rows.stream().map(fm::stringWidth).max(Integer::compare).isPresent())
		{
			tooltipWidth = rows.stream().map(fm::stringWidth).max(Integer::compareTo).get();
		}
		int clippedHeight = tooltipHeight * rows.size() + TOOLTIP_PADDING_HEIGHT * 2;
		int clippedWidth = tooltipWidth + TOOLTIP_PADDING_WIDTH * 2;

		Rectangle worldMapBounds = Objects.requireNonNull(client.getWidget(InterfaceID.Worldmap.MAP_CONTAINER)).getBounds();
		int worldMapRightBoundary = worldMapBounds.width + worldMapBounds.x;
		int worldMapBottomBoundary = worldMapBounds.height + worldMapBounds.y;

		int drawPointX = startX + TOOLTIP_OFFSET_WIDTH;
		int drawPointY = startY;
		if (drawPointX + clippedWidth > worldMapRightBoundary)
		{
			drawPointX = worldMapRightBoundary - clippedWidth;
		}
		if (drawPointY + clippedHeight > worldMapBottomBoundary)
		{
			drawPointY = startY - clippedHeight;
		}
		drawPointY += TOOLTIP_OFFSET_HEIGHT;

		int tooltipRectX = drawPointX - TOOLTIP_PADDING_WIDTH;
		int tooltipRectY = drawPointY - TOOLTIP_PADDING_HEIGHT;

		graphics.setColor(JagexColors.TOOLTIP_BACKGROUND);
		graphics.fillRect(tooltipRectX, tooltipRectY, clippedWidth, clippedHeight);

		graphics.setColor(JagexColors.TOOLTIP_BORDER);
		graphics.drawRect(tooltipRectX, tooltipRectY, clippedWidth, clippedHeight);

		graphics.setColor(JagexColors.TOOLTIP_TEXT);
		for (int i = 0; i < rows.size(); i++)
		{
			graphics.drawString(rows.get(i), drawPointX, drawPointY + TOOLTIP_TEXT_OFFSET_HEIGHT + (i + 1) * tooltipHeight);
		}

		return true;
	}
}

package shortestpath.overlay;

import shortestpath.settings.ConfigKey;
import com.google.inject.Inject;

import java.awt.*;

import net.runelite.api.*;
import net.runelite.api.Point;
import net.runelite.client.ui.overlay.*;
import shortestpath.WorldPointUtil;
import shortestpath.pathfinder.*;
import shortestpath.scheduler.*;
import shortestpath.settings.Settings;
import shortestpath.widgets.WidgetGeometry;

public class PathMinimapOverlay extends Overlay
{
	private final Client client;
	private final Settings settings;
	private final PathRenderState renderState;
	private final PathScheduler scheduler;
	private final WidgetGeometry geometry;

	@Inject
	private PathMinimapOverlay(Client client, Settings settings, PathRenderState renderState,
		PathScheduler scheduler, WidgetGeometry geometry)
	{
		this.client = client;
		this.settings = settings;
		this.renderState = renderState;
		this.scheduler = scheduler;
		this.geometry = geometry;
		setPosition(OverlayPosition.DYNAMIC);
		setPriority(Overlay.PRIORITY_LOW);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	public static void renderMinimapRect(Client client, Graphics2D graphics, Point center, Color color)
	{
		renderMinimapRect(client, graphics, center, color, 1.0);
	}

	// The scale overloads draw a sailing path's half-size dots
	public static void renderMinimapRect(Client client, Graphics2D graphics, Point center, Color color, double scale)
	{
		double angle = client.getCameraYawTarget() * Perspective.UNIT14;
		double tileSize = client.getMinimapZoom() * scale;
		int x = (int) Math.round(center.getX() - tileSize / 2);
		int y = (int) Math.round(center.getY() - tileSize / 2);
		int width = (int) Math.round(tileSize);
		int height = (int) Math.round(tileSize);
		graphics.setColor(color);
		graphics.rotate(angle, center.getX(), center.getY());
		graphics.fillRect(x, y, width, height);
		graphics.rotate(-angle, center.getX(), center.getY());
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		ActiveSearch search = scheduler.getActiveSearch();
		if (!settings.bool(ConfigKey.DRAW_MINIMAP) || search == null)
		{
			return null;
		}

		Shape minimapClipArea = geometry.getMinimapClipArea();
		if (minimapClipArea == null)
		{
			return null;
		}
		else
		{
			graphics.setClip(minimapClipArea);
		}
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_OFF);

		java.util.List<PathStep> pathPoints = search.getPath();
		// On a boat the path sails the boat's headings, with a point a few tiles apart at the end of each move: half-size
		// blue dots
		boolean sailing = renderState.isSailing();
		Color pathColor = sailing && !renderState.isPathUnreachable()
			? PathRenderState.SAILING_PATH_COLOUR : renderState.getPathColor();
		for (PathStep point : pathPoints)
		{
			int pathPoint = point.getPackedPosition();
			if (WorldPointUtil.unpackWorldPlane(pathPoint) != client.getTopLevelWorldView().getPlane())
			{
				continue;
			}

			drawOnMinimap(graphics, pathPoint, pathColor, sailing ? 0.5 : 1.0);
		}
		OverlayDrawing.forEachUnreachedTarget(search, pathPoints,
			target -> drawOnMinimap(graphics, target, settings.get(ConfigKey.COLOUR_PATH_CALCULATING)));

		return null;
	}

	private void drawOnMinimap(Graphics2D graphics, int location, Color color)
	{
		drawOnMinimap(graphics, location, color, 1.0);
	}

	private void drawOnMinimap(Graphics2D graphics, int location, Color color, double scale)
	{
		ProjectedTiles.eachProjectedTile(client, location, null,
			lp -> Perspective.localToMinimap(client, lp), posOnMinimap ->
			{
				renderMinimapRect(client, graphics, posOnMinimap, color, scale);
				return false;
			});
	}
}

package shortestpath.overlay;

import shortestpath.settings.ConfigKey;
import com.google.inject.Inject;

import java.awt.*;
import java.awt.geom.*;
import java.awt.image.BufferedImage;
import java.util.*;
import java.util.List;

import net.runelite.api.*;
import net.runelite.api.Point;
import net.runelite.api.coords.*;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.*;
import shortestpath.*;
import shortestpath.pathfinder.*;
import shortestpath.poh.PohService;
import shortestpath.presentation.*;
import shortestpath.transport.Transport;
import shortestpath.requirement.TransportEligibility;
import shortestpath.scheduler.*;
import shortestpath.settings.Settings;

public class PathTileOverlay extends Overlay
{
	private static final int TRANSPORT_LABEL_GAP = 3;
	private static final long TRACER_STEP_MS = 200L;
	private static final int TRACER_WINDOW_TILES = 60;
	private static final int SPRITE_STRIDE = 10;
	private static final int SPRITE_ITEM_ID = ItemID.GAUNTLET_ESCAPE_CRYSTAL;
	private final Client client;
	private final ItemManager itemManager;
	private final Settings settings;
	private final PathRenderState renderState;
	private final PathScheduler scheduler;
	private final PathAnnotator annotator;
	private int playerTileLabelOffset = 0;
	private boolean teleportPulseDrawn = false;

	@Inject
	public PathTileOverlay(Client client, ItemManager itemManager, Settings settings,
		PathRenderState renderState, PathScheduler scheduler, PathAnnotator annotator)
	{
		this.client = client;
		this.itemManager = itemManager;
		this.settings = settings;
		this.renderState = renderState;
		this.scheduler = scheduler;
		this.annotator = annotator;
		setPosition(OverlayPosition.DYNAMIC);
		setPriority(Overlay.PRIORITY_LOW);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	private static final Color COLOR_AVAILABLE = Color.WHITE;
	private static final Color COLOR_UNAVAILABLE = Color.ORANGE;
	private static final Color COLOR_CLICK_POINT = new Color(255, 0, 255, 150);

	private void renderTransports(Graphics2D graphics, ActiveSearch search)
	{
		OverlayDrawing.forEachDisplayTransport(annotator, new OverlayDrawing.TransportVisitor()
		{
			private Point ca;
			private boolean drawStart;
			private StringBuilder s;

			@Override
			public boolean beginOrigin(int origin)
			{
				ca = tileCenter(origin);
				if (ca == null)
				{
					return false;
				}
				drawStart = false;
				s = new StringBuilder();
				return true;
			}

			@Override
			public void visit(int origin, Transport b, boolean isAvailable)
			{
				graphics.setColor(isAvailable ? COLOR_AVAILABLE : COLOR_UNAVAILABLE);

				int destination = b.getDestination();
				if (destination == Transport.UNDEFINED_DESTINATION)
				{
					return;
				}
				Point cb = tileCenter(destination);
				if (cb != null)
				{
					graphics.drawLine(ca.getX(), ca.getY(), cb.getX(), cb.getY());
					drawStart = true;
				}
				if (WorldPointUtil.unpackWorldPlane(destination) > WorldPointUtil.unpackWorldPlane(origin))
				{
					s.append("+");
				}
				else if (WorldPointUtil.unpackWorldPlane(destination) < WorldPointUtil.unpackWorldPlane(origin))
				{
					s.append("-");
				}
				else
				{
					s.append("=");
				}
			}

			@Override
			public void endOrigin(int origin)
			{
				if (drawStart)
				{
					drawTile(graphics, origin, settings.get(ConfigKey.COLOUR_TRANSPORTS), -1, true, search);
				}

				graphics.setColor(Color.WHITE);
				graphics.drawString(s.toString(), ca.getX(), ca.getY());
			}
		});
	}

	private void renderCollisionMap(Graphics2D graphics)
	{
		CollisionMap map = annotator.getMap();
		for (Tile[] row : client.getTopLevelWorldView().getScene().getTiles()[client.getTopLevelWorldView().getPlane()])
		{
			for (Tile tile : row)
			{
				if (tile == null)
				{
					continue;
				}

				Polygon tilePolygon = Perspective.getCanvasTilePoly(client, tile.getLocalLocation());

				if (tilePolygon == null)
				{
					continue;
				}

				int location = WorldPointUtil.fromLocalInstance(client, tile.getLocalLocation());
				int x = WorldPointUtil.unpackWorldX(location);
				int y = WorldPointUtil.unpackWorldY(location);
				int z = WorldPointUtil.unpackWorldPlane(location);

				String s = (!map.n(x, y, z) ? "n" : "") +
					(!map.s(x, y, z) ? "s" : "") +
					(!map.e(x, y, z) ? "e" : "") +
					(!map.w(x, y, z) ? "w" : "");

				if (map.isBlocked(x, y, z))
				{
					graphics.setColor(settings.get(ConfigKey.COLOUR_COLLISION_MAP));
					graphics.fill(tilePolygon);
				}
				if (!s.isEmpty() && !s.equals("nsew"))
				{
					graphics.setColor(Color.WHITE);
					int stringX = (int) (tilePolygon.getBounds().getCenterX()
						- graphics.getFontMetrics().getStringBounds(s, graphics).getWidth() / 2);
					int stringY = (int) tilePolygon.getBounds().getCenterY();
					graphics.drawString(s, stringX, stringY);
				}
			}
		}
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		// One volatile read per render pass: the search can be swapped mid-frame,
		// so every decision below keys off this single publication.
		ActiveSearch search = scheduler.getActiveSearch();
		playerTileLabelOffset = 0;
		teleportPulseDrawn = false;

		if (settings.bool(ConfigKey.DRAW_TRANSPORTS))
		{
			renderTransports(graphics, search);
		}

		if (settings.bool(ConfigKey.DRAW_COLLISION_MAP))
		{
			renderCollisionMap(graphics);
		}

		if (settings.bool(ConfigKey.DRAW_TILES) && search != null && search.getPath() != null)
		{
			Color calculating = settings.get(ConfigKey.COLOUR_PATH_CALCULATING);
			Color colorCalculating = new Color(calculating.getRed(), calculating.getGreen(),
				calculating.getBlue(), calculating.getAlpha() / 2);
			Color pathColor = renderState.getPathColor();
			Color color = new Color(
				pathColor.getRed(),
				pathColor.getGreen(),
				pathColor.getBlue(),
				pathColor.getAlpha() / 2);

			List<PathStep> path = search.getPath();
			int counter = 0;
			if (renderState.isSailing())
			{
				// On a boat the path sails the boat's headings: lines along each heading it holds, drawn through the
				// spot within each tile where the boat actually sits
				Color sailingColor = renderState.isPathUnreachable() ? renderState.getPathColor() : PathRenderState.SAILING_PATH_COLOUR;
				for (int i = 1; i < path.size(); i++)
				{
					drawOffsetLine(graphics, path.get(i - 1).getPackedPosition(), path.get(i).getPackedPosition(),
						renderState.getSailingPivotX(), renderState.getSailingPivotY(), sailingColor);
					drawTransportInfo(graphics, path.get(i - 1), path.get(i), path, i - 1, search);
				}
				drawUnreachedTargets(graphics, path, colorCalculating, true, search);
			}
			else if (TileStyle.LINES.equals(settings.get(ConfigKey.PATH_STYLE)) || TileStyle.ARROW_LINE.equals(settings.get(ConfigKey.PATH_STYLE)))
			{
				boolean arrows = TileStyle.ARROW_LINE.equals(settings.get(ConfigKey.PATH_STYLE));
				for (int i = 1; i < path.size(); i++)
				{
					PathStep currentStep = path.get(i - 1);
					PathStep nextStep = path.get(i);
					// Arrowheads only where they carry information: at direction changes and the end.
					boolean head = arrows && (i == path.size() - 1
						|| directionChanges(currentStep.getPackedPosition(), nextStep.getPackedPosition(),
							path.get(i + 1).getPackedPosition()));
					drawLine(graphics, currentStep.getPackedPosition(), nextStep.getPackedPosition(), color,
						1 + counter++, head, search);
					drawTransportInfo(graphics, currentStep, nextStep, path, i - 1, search);
				}
			}
			else if (TileStyle.TURN_MARKERS.equals(settings.get(ConfigKey.PATH_STYLE)))
			{
				// Markers only where the route changes direction, plus both endpoints.
				// The walker skips marker draws inside POH (no collision data, tiles
				// render at wrong positions); the index doubles as the tile counter.
				ProjectedTiles.forEachVisibleStep(this, graphics, path, annotator, colorCalculating, search,
					(steps, i) -> i == 0 || i == steps.size() - 1
						|| directionChanges(steps.get(i - 1).getPackedPosition(),
							steps.get(i).getPackedPosition(), steps.get(i + 1).getPackedPosition()),
					(step, i) ->
					{
						drawTile(graphics, step.getPackedPosition(), color, i, true, search);
						drawTurnMarkerGlyph(graphics, path, i);
					},
					true);
			}
			else if (TileStyle.TRACER.equals(settings.get(ConfigKey.PATH_STYLE)))
			{
				// Faint polyline under the moving marker so the full route stays readable
				// without looking identical to LINES.
				Color tracerLineColour = new Color(color.getRed(), color.getGreen(), color.getBlue(),
					color.getAlpha() / 2);
				for (int i = 1; i < path.size(); i++)
				{
					PathStep currentStep = path.get(i - 1);
					PathStep nextStep = path.get(i);
					drawLine(graphics, currentStep.getPackedPosition(), nextStep.getPackedPosition(), tracerLineColour,
						1 + counter++, false, search);
					drawTransportInfo(graphics, currentStep, nextStep, path, i - 1, search);
				}
				if (!path.isEmpty())
				{
					// One marker walks the path on a wall-clock phase — the overlay repaints
					// every frame, so no tick subscription is needed (the drawTeleportPulse idiom).
					// The window caps the walk to the slice near the player: over a full-length
					// path the marker sits off-screen most of the time on long routes.
					int tracerWindow = Math.min(path.size(), TRACER_WINDOW_TILES);
					int tracerIndex = (int) ((System.currentTimeMillis() / TRACER_STEP_MS) % tracerWindow);
					int tracerPoint = path.get(tracerIndex).getPackedPosition();
					int tracerX = WorldPointUtil.unpackWorldX(tracerPoint);
					int tracerY = WorldPointUtil.unpackWorldY(tracerPoint);
					if (!PohService.isInsidePoh(tracerX, tracerY))
					{
						Point current = tileCenter(tracerPoint);
						if (current != null)
						{
							Color previousColour = graphics.getColor();
							graphics.setColor(pathColor);
							int radius = 6;
							graphics.fillOval(current.getX() - radius, current.getY() - radius, radius * 2, radius * 2);
							if (tracerIndex + 1 < path.size())
							{
								Point next = tileCenter(path.get(tracerIndex + 1).getPackedPosition());
								if (next != null)
								{
									ArrowHead.draw(graphics, current.getX(), current.getY(), next.getX(), next.getY(), 10);
								}
							}
							graphics.setColor(previousColour);
						}
					}
				}
				drawUnreachedTargets(graphics, path, colorCalculating, true, search);
			}
			else if (TileStyle.SPRITE_MARKERS.equals(settings.get(ConfigKey.PATH_STYLE)))
			{
				// Bounded stride — a sprite every SPRITE_STRIDE tiles plus the destination,
				// never one sprite per tile (per-tile sprite density is too heavy).
				// The walker skips sprite draws inside POH, same as the other markers.
				ProjectedTiles.forEachVisibleStep(this, graphics, path, annotator, colorCalculating, search,
					(steps, i) -> i % SPRITE_STRIDE == 0 || i == steps.size() - 1,
					(step, i) ->
					{
						Point p = tileCenter(step.getPackedPosition());
						if (p != null)
						{
							BufferedImage sprite = itemManager.getImage(SPRITE_ITEM_ID);
							if (sprite != null)
							{
								if (i == path.size() - 1)
								{
									// The destination reads as the endpoint: larger sprite plus a ring.
									int dw = sprite.getWidth() * 3 / 2;
									int dh = sprite.getHeight() * 3 / 2;
									graphics.drawImage(sprite, p.getX() - dw / 2, p.getY() - dh / 2, dw, dh, null);
									int radius = Math.max(dw, dh) / 2 + 3;
									Color previousColour = graphics.getColor();
									graphics.setColor(settings.get(ConfigKey.COLOUR_TEXT));
									graphics.drawOval(p.getX() - radius, p.getY() - radius, radius * 2, radius * 2);
									graphics.setColor(previousColour);
								}
								else
								{
									graphics.drawImage(sprite, p.getX() - sprite.getWidth() / 2,
										p.getY() - sprite.getHeight() / 2, null);
								}
							}
							drawCounter(graphics, p.getX(), p.getY(), i, search);
						}
					},
					true);
			}
			else
			{
				// The walker skips tile draws inside POH (no collision data, tiles
				// render at wrong positions); the index doubles as the tile counter.
				boolean showTiles = TileStyle.TILES.equals(settings.get(ConfigKey.PATH_STYLE));
				ProjectedTiles.forEachVisibleStep(this, graphics, path, annotator, colorCalculating, search,
					(steps, i) -> true,
					(step, i) -> drawTile(graphics, step.getPackedPosition(), color, i, showTiles, search),
					showTiles);
			}

			if (renderState.isPathUnreachable() && settings.bool(ConfigKey.SHOW_UNREACHABLE_TEXT))
			{
				playerTileLabelOffset += drawLabelOnPlayerTile(graphics, settings.get(ConfigKey.UNREACHABLE_TEXT), playerTileLabelOffset);
			}
			String missingItems = annotator.getMissingTargetItemsText(search);
			if (missingItems != null)
			{
				playerTileLabelOffset += drawLabelOnPlayerTile(graphics, missingItems, playerTileLabelOffset);
			}
		}

		// Click points without the path are floating marks, so they follow the same drawTiles
		// gate and POH skip as the path tiles.
		if (settings.bool(ConfigKey.DRAW_TILES) && settings.bool(ConfigKey.DRAW_CLICK_POINTS)
			&& search != null && search.isDone() && !search.isShowingProvisionalPath())
		{
			List<PathStep> path = search.getPath();
			for (int index : search.getClickPoints())
			{
				int point = path.get(index).getPackedPosition();
				if (!PohService.isInsidePoh(WorldPointUtil.unpackWorldX(point),
					WorldPointUtil.unpackWorldY(point)))
				{
					drawTile(graphics, point, COLOR_CLICK_POINT, -1, true, search);
				}
			}
		}

		return null;
	}

	private Point tileCenter(int b)
	{
		if (b == WorldPointUtil.UNDEFINED || client == null)
		{
			return null;
		}

		// Map the canonical point into the viewed instance before checking the
		// plane — inside an instance (e.g. a POH) the stored template plane can
		// differ from the instance plane without being on a different floor.
		// The point filter runs pre-projection so an out-of-plane mapped point
		// never reaches toLocalPoint, and the consumer's early exit keeps the
		// first-valid selection.
		final Point[] centre = new Point[1];
		ProjectedTiles.eachProjectedTile(client, b,
			point -> WorldPointUtil.unpackWorldPlane(point) == client.getTopLevelWorldView().getPlane(),
			lp -> Perspective.getCanvasTilePoly(client, lp), poly ->
			{
				int cx = poly.getBounds().x + poly.getBounds().width / 2;
				int cy = poly.getBounds().y + poly.getBounds().height / 2;
				centre[0] = new Point(cx, cy);
				return true;
			});
		return centre[0];
	}

	private void drawTile(Graphics2D graphics, int location, Color color, int counter, boolean draw,
		ActiveSearch search)
	{
		if (client == null)
		{
			return;
		}

		ProjectedTiles.eachProjectedTile(client, location, null,
			lp -> Perspective.getCanvasTilePoly(client, lp), poly ->
			{
				if (draw)
				{
					graphics.setColor(color);
					graphics.fill(poly);
				}

				drawCounter(graphics, poly.getBounds().getCenterX(), poly.getBounds().getCenterY(), counter, search);
				return false;
			});
	}

	void drawUnreachedTargets(Graphics2D graphics, List<PathStep> path, Color colorCalculating, boolean draw,
		ActiveSearch search)
	{
		OverlayDrawing.forEachUnreachedTarget(search, path,
			target -> drawTile(graphics, target, colorCalculating, -1, draw, search));
	}

	private static boolean directionChanges(int previous, int current, int next)
	{
		int dx1 = WorldPointUtil.unpackWorldX(current) - WorldPointUtil.unpackWorldX(previous);
		int dy1 = WorldPointUtil.unpackWorldY(current) - WorldPointUtil.unpackWorldY(previous);
		int dx2 = WorldPointUtil.unpackWorldX(next) - WorldPointUtil.unpackWorldX(current);
		int dy2 = WorldPointUtil.unpackWorldY(next) - WorldPointUtil.unpackWorldY(current);
		return dx1 != dx2 || dy1 != dy2;
	}

	// Turn markers get a glyph inside the fill: an arrowhead along the outgoing
	// segment so the marker reads as "turn this way", a ring for the destination
	// which has no outgoing segment.
	private void drawTurnMarkerGlyph(Graphics2D graphics, List<PathStep> path, int index)
	{
		Point here = tileCenter(path.get(index).getPackedPosition());
		if (here == null)
		{
			return;
		}
		Color previousColour = graphics.getColor();
		graphics.setColor(settings.get(ConfigKey.COLOUR_TEXT));
		if (index + 1 < path.size())
		{
			Point next = tileCenter(path.get(index + 1).getPackedPosition());
			if (next != null)
			{
				ArrowHead.draw(graphics, here.getX(), here.getY(), next.getX(), next.getY(), 8);
			}
		}
		else
		{
			int radius = 5;
			graphics.drawOval(here.getX() - radius, here.getY() - radius, radius * 2, radius * 2);
		}
		graphics.setColor(previousColour);
	}

	private void drawLine(Graphics2D graphics, int startLoc, int endLoc, Color color, int counter, boolean arrowHead,
		ActiveSearch search)
	{
		PrimitiveIntList starts = WorldPointUtil.toLocalInstance(client, startLoc);
		PrimitiveIntList ends = WorldPointUtil.toLocalInstance(client, endLoc);

		if (starts.isEmpty() || ends.isEmpty())
		{
			return;
		}

		int start = starts.get(0);
		int end = ends.get(0);

		final int z = client.getTopLevelWorldView().getPlane();
		if (WorldPointUtil.unpackWorldPlane(start) != z)
		{
			return;
		}

		LocalPoint lpStart = WorldPointUtil.toLocalPoint(client, start);
		LocalPoint lpEnd = WorldPointUtil.toLocalPoint(client, end);

		if (lpStart == null || lpEnd == null)
		{
			return;
		}

		final int startHeight = Perspective.getTileHeight(client, lpStart, z);
		final int endHeight = Perspective.getTileHeight(client, lpEnd, z);

		Point p1 = Perspective.localToCanvas(client, lpStart.getX(), lpStart.getY(), startHeight);
		Point p2 = Perspective.localToCanvas(client, lpEnd.getX(), lpEnd.getY(), endHeight);

		if (p1 == null || p2 == null)
		{
			return;
		}

		Line2D.Double line = new Line2D.Double(p1.getX(), p1.getY(), p2.getX(), p2.getY());

		graphics.setColor(color);
		graphics.setStroke(new BasicStroke(4));
		graphics.draw(line);
		if (arrowHead)
		{
			ArrowHead.draw(graphics, p1.getX(), p1.getY(), p2.getX(), p2.getY(), 12);
		}

		if (counter == 1)
		{
			drawCounter(graphics, p1.getX(), p1.getY(), 0, search);
		}
		drawCounter(graphics, p2.getX(), p2.getY(), counter, search);
	}

	// A line between two tiles, shifted from the tile centres by (offsetX, offsetY) local units
	private void drawOffsetLine(Graphics2D graphics, int startLoc, int endLoc, int offsetX, int offsetY, Color color)
	{
		// In an instance the path is in template coordinates, as for the walking path's lines
		PrimitiveIntList starts = WorldPointUtil.toLocalInstance(client, startLoc);
		PrimitiveIntList ends = WorldPointUtil.toLocalInstance(client, endLoc);
		if (starts.isEmpty() || ends.isEmpty())
		{
			return;
		}

		final int z = client.getTopLevelWorldView().getPlane();
		if (WorldPointUtil.unpackWorldPlane(starts.get(0)) != z)
		{
			return;
		}

		LocalPoint start = WorldPointUtil.toLocalPoint(client, starts.get(0));
		LocalPoint end = WorldPointUtil.toLocalPoint(client, ends.get(0));
		if (start == null || end == null)
		{
			return;
		}
		start = new LocalPoint(start.getX() + offsetX, start.getY() + offsetY, start.getWorldView());
		end = new LocalPoint(end.getX() + offsetX, end.getY() + offsetY, end.getWorldView());

		Point p1 = Perspective.localToCanvas(client, start.getX(), start.getY(), Perspective.getTileHeight(client, start, z));
		Point p2 = Perspective.localToCanvas(client, end.getX(), end.getY(), Perspective.getTileHeight(client, end, z));
		if (p1 == null || p2 == null)
		{
			return;
		}

		graphics.setColor(color);
		graphics.setStroke(new BasicStroke(4));
		graphics.draw(new Line2D.Double(p1.getX(), p1.getY(), p2.getX(), p2.getY()));
	}

	private void drawCounter(Graphics2D graphics, double x, double y, int counter, ActiveSearch search)
	{
		if (counter >= 0 && !TileCounter.DISABLED.equals(settings.get(ConfigKey.SHOW_TILE_COUNTER)))
		{
			int n = settings.num(ConfigKey.TILE_COUNTER_STEP) > 0 ? settings.num(ConfigKey.TILE_COUNTER_STEP) : 1;
			int s = search.getPath().size();
			if ((counter % n != 0) && (s != (counter + 1)))
			{
				return;
			}
			if (TileCounter.REMAINING.equals(settings.get(ConfigKey.SHOW_TILE_COUNTER)))
			{
				counter = s - counter - 1;
			}
			if (n > 1 && counter == 0)
			{
				return;
			}
			String counterText = Integer.toString(counter);
			graphics.setColor(settings.get(ConfigKey.COLOUR_TEXT));
			graphics.drawString(
				counterText,
				(int) (x - graphics.getFontMetrics().getStringBounds(counterText, graphics).getWidth() / 2), (int) y);
		}
	}

	private int drawLabelAtCanvasPoint(Graphics2D graphics, Point point, String text, int verticalOffset)
	{
		if (point == null || text == null || text.isEmpty())
		{
			return 0;
		}

		double height = drawLabel(graphics, point, text, verticalOffset);

		return (int) height + TRANSPORT_LABEL_GAP;
	}

	private int drawLabelAtPackedLocation(Graphics2D graphics, int location, String text, int verticalOffset)
	{
		final int[] offset = {verticalOffset};
		ProjectedTiles.eachProjectedTile(client, location, null,
			lp -> Perspective.localToCanvas(client, lp, client.getTopLevelWorldView().getPlane()), p ->
			{
				offset[0] += drawLabelAtCanvasPoint(graphics, p, text, offset[0]);
				return false;
			});
		return offset[0];
	}

	/**
	 * A pulsing "teleport from here" highlight: diamond rings expanding out from the tile and fading,
	 * looping. Drawn every frame (scene overlays repaint continuously) off wall-clock time, so the motion
	 * stays smooth regardless of game ticks. Anchored to the tile the player casts from — for a
	 * cast-from-anywhere teleport that sits under the player, drawing the eye to "teleport now".
	 */
	private void drawTeleportPulse(Graphics2D graphics, int location)
	{
		ProjectedTiles.eachProjectedTile(client, location, null,
			lp -> Perspective.getCanvasTilePoly(client, lp), poly ->
			{
				if (poly.npoints == 0)
				{
					return false;
				}
				final double cx = poly.getBounds().getCenterX();
				final double cy = poly.getBounds().getCenterY();

				final long period = 1400L;
				final int rings = 2;
				final Color base = settings.get(ConfigKey.COLOUR_TELEPORT_PULSE);
				final Color previousColour = graphics.getColor();
				final Stroke previousStroke = graphics.getStroke();
				graphics.setStroke(new BasicStroke(2.2f));
				for (int r = 0; r < rings; r++)
				{
					// Stagger the two rings by half a period so one is always small/bright while the other
					// is large/faint — a continuous outward pulse.
					double phase = ((System.currentTimeMillis() + (long) (r * period / (double) rings)) % period)
						/ (double) period;
					double scale = 1.0 + phase * 2.6;
					int alpha = (int) Math.round(170 * (1.0 - phase));
					if (alpha <= 0)
					{
						continue;
					}
					Path2D ring = new Path2D.Double();
					for (int v = 0; v < poly.npoints; v++)
					{
						double x = cx + (poly.xpoints[v] - cx) * scale;
						double y = cy + (poly.ypoints[v] - cy) * scale;
						if (v == 0)
						{
							ring.moveTo(x, y);
						}
						else
						{
							ring.lineTo(x, y);
						}
					}
					ring.closePath();
					graphics.setColor(new Color(base.getRed(), base.getGreen(), base.getBlue(), alpha));
					graphics.draw(ring);
				}
				graphics.setColor(previousColour);
				graphics.setStroke(previousStroke);
				return false;
			});
	}

	private double drawLabel(Graphics2D graphics, Point point, String text, int verticalOffset)
	{
		Rectangle2D textBounds = graphics.getFontMetrics().getStringBounds(text, graphics);
		double height = textBounds.getHeight();
		int x = (int) (point.getX() - textBounds.getWidth() / 2);
		int y = (int) (point.getY() - height) - verticalOffset;
		graphics.setColor(Color.BLACK);
		graphics.drawString(text, x + 1, y + 1);
		graphics.setColor(settings.get(ConfigKey.COLOUR_TEXT));
		graphics.drawString(text, x, y);
		return height;
	}

	private int drawLabelOnPlayerTile(Graphics2D graphics, String text, int verticalOffset)
	{
		if (client.getLocalPlayer() == null)
		{
			return 0;
		}

		Point playerPoint = Perspective.localToCanvas(client, client.getLocalPlayer().getLocalLocation(), client.getTopLevelWorldView().getPlane());
		return drawLabelAtCanvasPoint(graphics, playerPoint, text, verticalOffset);
	}

	void drawTransportInfo(Graphics2D graphics, PathStep currentStep, PathStep nextStep, List<PathStep> path,
		int pathIndex, ActiveSearch search)
	{
		int location = currentStep.getPackedPosition();
		int lx = WorldPointUtil.unpackWorldX(location);
		int ly = WorldPointUtil.unpackWorldY(location);
		// Inside an instance the stored template plane can differ from the
		// viewed instance plane without being on a different floor (a POH with
		// a basement shifts its ground floor up a plane), so POH steps skip the
		// plane check here; every draw below re-maps the step through
		// toLocalInstance and plane-checks the mapped point instead.
		if (nextStep == null ||
			(WorldPointUtil.unpackWorldPlane(location) != client.getTopLevelWorldView().getPlane() &&
				!PohService.isInsidePoh(lx, ly)
			))
		{
			return;
		}

		if (drawSailingDisembarkHint(graphics, pathIndex, search))
		{
			return;
		}

		if (renderState.isPathUnreachable() || !search.isDone())
		{
			return;
		}
		int locationEnd = nextStep.getPackedPosition();
		Set<Transport> candidateTransports = annotator.transportsForEdge(currentStep, nextStep);

		drawTeleportPulseOnce(graphics, location, candidateTransports);

		if (!settings.bool(ConfigKey.SHOW_TRANSPORT_INFO))
		{
			return;
		}

		// Workaround for weird pathing inside PoH to instead show info on the player
		// tile
		Player player = client.getLocalPlayer();
		if (player == null)
		{
			return;
		}
		LocalPoint playerLocalPoint = player.getLocalLocation();

		// When inside POH, only show the POH exit info once (not per-transport)
		if (playerAndStepInsidePoh(player, playerLocalPoint, location))
		{
			drawPohExitLabel(graphics, location, path, pathIndex, playerLocalPoint);
			return;
		}

		// Check if this is a bank step and items need to be picked up
		if (drawBankPickupLabel(graphics, location, path, pathIndex, search))
		{
			return;
		}

		drawTransportLabels(graphics, location, locationEnd, path, pathIndex, candidateTransports);
	}

	// Sailing: teleports are suppressed while aboard a boat. When the path is
	// unreachable as a result, show a one-time hint on the player tile.
	private boolean drawSailingDisembarkHint(Graphics2D graphics, int pathIndex, ActiveSearch search)
	{
		if (settings.bool(ConfigKey.SHOW_TRANSPORT_INFO) && pathIndex == 0 && renderState.isOnSailingBoat()
			&& search.isDone() && renderState.isPathUnreachable())
		{
			playerTileLabelOffset = drawLabelOnPlayerTile(graphics,
				"Disembark the boat to resume pathfinding", playerTileLabelOffset);
			return true;
		}
		return false;
	}

	// Teleports ("use this item/spell") get a pulsing highlight on the tile you cast
	// from. Only the first teleport edge of the path pulses — the next "teleport
	// now" moment — and the pulse is independent of the transport info labels.
	private void drawTeleportPulseOnce(Graphics2D graphics, int location, Set<Transport> candidateTransports)
	{
		if (!settings.bool(ConfigKey.SHOW_TELEPORT_PULSE) || teleportPulseDrawn)
		{
			return;
		}
		for (Transport transport : candidateTransports)
		{
			if (transport.getType() != null && transport.getType().isTeleport())
			{
				drawTeleportPulse(graphics, location);
				teleportPulseDrawn = true;
				break;
			}
		}
	}

	private boolean playerAndStepInsidePoh(Player player, LocalPoint playerLocalPoint, int location)
	{
		WorldPoint playerWorldPoint = player.getWorldLocation();
		if (client.getTopLevelWorldView().isInstance())
		{
			playerWorldPoint = WorldPoint.fromLocalInstance(client, playerLocalPoint);
		}
		int playerPackedPoint = WorldPointUtil.packWorldPoint(playerWorldPoint);
		return PohService.isInsidePoh(WorldPointUtil.unpackWorldX(location), WorldPointUtil.unpackWorldY(location))
			&& PohService.isInsidePoh(WorldPointUtil.unpackWorldX(playerPackedPoint),
				WorldPointUtil.unpackWorldY(playerPackedPoint));
	}

	private void drawPohExitLabel(Graphics2D graphics, int location, List<PathStep> path,
		int pathIndex, LocalPoint playerLocalPoint)
	{
		// No floor check here: path steps carry planes from the generic POH
		// template (the landing is modelled at plane 0), while the player maps
		// back at whatever template plane their actual house chunks occupy
		// (e.g. plane 2 for a ground floor) — the two don't correspond, so any
		// plane comparison would suppress the hint in real houses.
		String pohExitInfo = annotator.getPohExitInfo(location, path, pathIndex - 1);

		if (pohExitInfo == null)
		{
			return;
		}
		String text = "Exit: " + pohExitInfo;

		Point p = Perspective.localToCanvas(client, playerLocalPoint, client.getTopLevelWorldView().getPlane());
		if (p == null)
		{
			return;
		}

		drawLabel(graphics, p, text, 0);
	}

	// Returns true when the pickup label suppressed the default transport hints.
	private boolean drawBankPickupLabel(Graphics2D graphics, int location, List<PathStep> path,
		int pathIndex, ActiveSearch search)
	{
		BankPickupRequirements.BankPickupResult bankPickup = annotator.getBankPickup(path, pathIndex, search);
		if (bankPickup == null || bankPickup.phrases.isEmpty())
		{
			return false;
		}

		String pickupText = "Pick up: " + String.join(", ", bankPickup.phrases);
		playerTileLabelOffset = drawLabelAtPackedLocation(graphics, location, pickupText, playerTileLabelOffset);

		// By default, bank pickup info replaces the default transport hint text;
		// enable the option to show both
		return !settings.bool(ConfigKey.SHOW_BANK_PICKUP_INFO);
	}

	// Only show transports the player can currently use; fall back to all if none are usable.
	// A missing snapshot (pre-login or off the client thread) means no filtering —
	// the same "show all" the empty-usable fallback produces anyway.
	private static Collection<Transport> usableTransportsFor(Set<Transport> candidateTransports,
		TransportEligibility eligibility)
	{
		List<Transport> usableTransports = new ArrayList<>();
		if (eligibility != null)
		{
			for (Transport t : candidateTransports)
			{
				if (eligibility.satisfiedByPlayer(t))
				{
					usableTransports.add(t);
				}
			}
		}
		return usableTransports.isEmpty() ? candidateTransports : usableTransports;
	}

	private void drawTransportLabels(Graphics2D graphics, int location, int locationEnd,
		List<PathStep> path, int pathIndex, Set<Transport> candidateTransports)
	{
		for (Transport transport : usableTransportsFor(candidateTransports, annotator.getEligibility()))
		{
			String text = annotator.formatTransportDisplay(transport);
			if (text == null || text.isEmpty())
			{
				continue;
			}

			// Check if this transport goes to POH - if so, look ahead to find the exit
			// transport
			String pohExitSuffix = OverlayDrawing.pohExitSuffix(annotator, locationEnd, path, pathIndex);
			if (pohExitSuffix != null)
			{
				text = text + pohExitSuffix;
			}

			playerTileLabelOffset = drawLabelAtPackedLocation(graphics, location, text, playerTileLabelOffset);
		}
	}
}

package shortestpath.overlay;

import net.runelite.client.ui.overlay.OverlayManager;

/**
 * The plugin's overlay set as one composite: the shell keeps the nine
 * overlay references injected but delegates every lifecycle call here, so
 * the add/remove/debug-toggle idioms each have a single owner. Register
 * order is render order, so the field order below mirrors the order the
 * plugin used to add them in.
 *
 * <p>This package is a leaf: nothing here may reference the plugin type.
 */
public final class PluginOverlays
{
	private final PathTileOverlay pathOverlay;
	private final PathMinimapOverlay pathMinimapOverlay;
	private final PathMapOverlay pathMapOverlay;
	private final PathMapTooltipOverlay pathMapTooltipOverlay;
	private final BankItemHighlightOverlay bankItemHighlightOverlay;
	private final SpellbookHighlightOverlay spellbookHighlightOverlay;
	private final InventoryHighlightOverlay inventoryHighlightOverlay;
	private final ScrollBookHighlightOverlay scrollBookHighlightOverlay;
	private final DebugOverlayPanel debugOverlayPanel;

	public PluginOverlays(
		PathTileOverlay pathOverlay,
		PathMinimapOverlay pathMinimapOverlay,
		PathMapOverlay pathMapOverlay,
		PathMapTooltipOverlay pathMapTooltipOverlay,
		BankItemHighlightOverlay bankItemHighlightOverlay,
		SpellbookHighlightOverlay spellbookHighlightOverlay,
		InventoryHighlightOverlay inventoryHighlightOverlay,
		ScrollBookHighlightOverlay scrollBookHighlightOverlay,
		DebugOverlayPanel debugOverlayPanel)
	{
		this.pathOverlay = pathOverlay;
		this.pathMinimapOverlay = pathMinimapOverlay;
		this.pathMapOverlay = pathMapOverlay;
		this.pathMapTooltipOverlay = pathMapTooltipOverlay;
		this.bankItemHighlightOverlay = bankItemHighlightOverlay;
		this.spellbookHighlightOverlay = spellbookHighlightOverlay;
		this.inventoryHighlightOverlay = inventoryHighlightOverlay;
		this.scrollBookHighlightOverlay = scrollBookHighlightOverlay;
		this.debugOverlayPanel = debugOverlayPanel;
	}

	/**
	 * Adds every overlay in declaration order — register order is render
	 * order — with the debug panel conditional on the visibility flag the
	 * caller resolved from settings.
	 */
	public void register(OverlayManager overlayManager, boolean drawDebug)
	{
		overlayManager.add(pathOverlay);
		overlayManager.add(pathMinimapOverlay);
		overlayManager.add(pathMapOverlay);
		overlayManager.add(pathMapTooltipOverlay);
		overlayManager.add(bankItemHighlightOverlay);
		overlayManager.add(spellbookHighlightOverlay);
		overlayManager.add(inventoryHighlightOverlay);
		overlayManager.add(scrollBookHighlightOverlay);
		if (drawDebug)
		{
			overlayManager.add(debugOverlayPanel);
		}
	}

	/**
	 * Removes all nine overlays unconditionally, matching the plugin's
	 * shut-down semantics — a never-registered debug panel removes as a
	 * no-op.
	 */
	public void unregister(OverlayManager overlayManager)
	{
		overlayManager.remove(pathOverlay);
		overlayManager.remove(pathMinimapOverlay);
		overlayManager.remove(pathMapOverlay);
		overlayManager.remove(pathMapTooltipOverlay);
		overlayManager.remove(bankItemHighlightOverlay);
		overlayManager.remove(spellbookHighlightOverlay);
		overlayManager.remove(inventoryHighlightOverlay);
		overlayManager.remove(scrollBookHighlightOverlay);
		overlayManager.remove(debugOverlayPanel);
	}

	/**
	 * The debug-panel toggle idiom: add iff {@code drawDebug}, else remove.
	 * The single owner of the config-change and profile-change paths.
	 */
	public void syncDebug(OverlayManager overlayManager, boolean drawDebug)
	{
		if (drawDebug)
		{
			overlayManager.add(debugOverlayPanel);
		}
		else
		{
			overlayManager.remove(debugOverlayPanel);
		}
	}
}

package shortestpath.overlay;

import java.awt.*;
import java.util.List;
import java.util.function.*;

import net.runelite.api.Client;
import net.runelite.api.coords.LocalPoint;

import shortestpath.*;
import shortestpath.pathfinder.*;
import shortestpath.poh.PohService;
import shortestpath.presentation.PathAnnotator;

/**
 * The shared packed-point projection walk: map a packed world point through
 * {@link WorldPointUtil#toLocalInstance} (one point, or several inside an
 * instance), convert each mapped point to a {@link LocalPoint}, apply the
 * caller's projector, and hand each non-null projection to the consumer.
 * Iterating every mapped point — not just the first — is the contract the
 * tile fills rely on inside instances.
 * <p>
 * The baked-in skips are: the {@link WorldPointUtil#UNDEFINED} sentinel, a
 * null local point, and a null projection. The sentinel check is a
 * normalization, not a uniform former guard — only {@code drawTile} and
 * {@code tileCenter} tested for it, while {@code drawOnMinimap},
 * {@code drawLabelAtPackedLocation}, and {@code drawTeleportPulse} relied on
 * {@code toLocalPoint(UNDEFINED)} returning {@code null}; hoisting it here is
 * safe because a sentinel can never project. Per-site input guards
 * ({@code client == null}, {@code b == UNDEFINED}) and pre-projection checks
 * like {@code tileCenter}'s plane test stay at the call sites — the optional
 * {@code pointFilter} is the slot that check folds into later. The consumer
 * returning {@code true} stops the walk early ({@code tileCenter}'s
 * first-valid semantics).
 * <p>
 * This package is a leaf: nothing here may reference the plugin type.
 */
final class ProjectedTiles
{
	private ProjectedTiles()
	{
	}

	static <T> void eachProjectedTile(Client client, int packed, IntPredicate pointFilter,
		Function<LocalPoint, T> projector, Predicate<T> consumer)
	{
		PrimitiveIntList points = WorldPointUtil.toLocalInstance(client, packed);
		for (int i = 0; i < points.size(); i++)
		{
			int point = points.get(i);
			if (point == WorldPointUtil.UNDEFINED || (pointFilter != null && !pointFilter.test(point)))
			{
				continue;
			}

			LocalPoint lp = WorldPointUtil.toLocalPoint(client, point);
			if (lp == null)
			{
				continue;
			}

			T result = projector.apply(lp);
			if (result == null)
			{
				continue;
			}

			if (consumer.test(result))
			{
				return;
			}
		}
	}

	/**
	 * The shared per-step walk for the tile-indexed style branches
	 * (TURN_MARKERS / SPRITE_MARKERS / the TILES default): for every path
	 * step the caller's marker predicate decides whether a marker draws —
	 * the POH skip wraps that marker draw only — while the per-step
	 * transport info and the trailing unreached-targets pass run
	 * unconditionally. The loop index doubles as the tile counter
	 * ({@code counter == i} in all three branches, POH-skipped steps
	 * included); the segment-pair styles keep their own
	 * {@code 1 + counter++} loops and never ride this walker.
	 * <p>
	 * Draw state stays on the overlay: the walker yields steps and calls
	 * back into {@link PathTileOverlay#drawTransportInfo} and
	 * {@link PathTileOverlay#drawUnreachedTargets}; per-frame accumulators
	 * and per-style counters remain instance state there.
	 */
	static void forEachVisibleStep(PathTileOverlay overlay, Graphics2D graphics, List<PathStep> path,
		PathAnnotator annotator, Color colorCalculating, ActiveSearch search,
		BiPredicate<List<PathStep>, Integer> markerPredicate,
		BiConsumer<PathStep, Integer> markerDraw, boolean drawUnreached)
	{
		for (int i = 0; i < path.size(); i++)
		{
			PathStep currentStep = path.get(i);
			int pathPoint = currentStep.getPackedPosition();
			if (markerPredicate.test(path, i)
				&& !PohService.isInsidePoh(WorldPointUtil.unpackWorldX(pathPoint),
					WorldPointUtil.unpackWorldY(pathPoint)))
			{
				markerDraw.accept(currentStep, i);
			}
			overlay.drawTransportInfo(graphics, currentStep, annotator.nextPathStep(path, i), path, i, search);
		}
		overlay.drawUnreachedTargets(graphics, path, colorCalculating, drawUnreached, search);
	}
}

package shortestpath.overlay;

import shortestpath.settings.ConfigKey;
