		int start,
		int target,
		boolean reached,
		List<PathStep> pathSteps,
		int closestReachedPoint,
		int pathCost,
		int nodesChecked,
		int transportsChecked,
		long elapsedNanos,
		PathTerminationReason terminationReason,
		String message)
	{
		this(start, target, reached, pathSteps, closestReachedPoint, pathCost, nodesChecked, transportsChecked,
			elapsedNanos, terminationReason, message, null);
	}


}

package shortestpath.pathfinder;

import lombok.Getter;

/**
 * Completed-search counters exposed to the plugin's debug overlay.
 */
public class PathfinderStats
{
	@Getter
	int nodesChecked = 0, transportsChecked = 0;
	private long startNanos, endNanos;
	volatile boolean started = false, ended = false;

	public int getTotalNodesChecked()
	{
		return nodesChecked + transportsChecked;
	}

	public long getElapsedTimeNanos()
	{
		return endNanos - startNanos;
	}

	/** Nanoseconds rendered as a compact milliseconds string for diagnostics. */
	public static String millis(long nanos)
	{
		return String.format("%.2fms", nanos / 1_000_000.0);
	}

	void start()
	{
		started = true;
		nodesChecked = 0;
		transportsChecked = 0;
		startNanos = System.nanoTime();
	}

	void end()
	{
		endNanos = System.nanoTime();
		ended = true;
	}
}

package shortestpath.pathfinder;

import java.util.*;
import java.util.function.IntPredicate;
import shortestpath.WorldPointUtil;

/**
 * The goal rule for a search that knows which tiles some route can reach, so that no goal lies in
 * disconnected space: a sealed pocket, a staff area behind a counter, open sea.
 *
 * <ol>
 *   <li>A walkable, reachable target is its own goal.</li>
 *   <li>Any other target looks for candidates around it, within the unreachable target distance:
 *       the reachable tiles and the tiles a transport lands on, never the player's own tile.</li>
 *   <li>When there are none, the target cannot be reached and the search need not run.</li>
 *   <li>Otherwise its goals are the candidates of the innermost Chebyshev ring that has any. On
 *       the ring touching the target, a reachable tile counts only in the first non-empty tier of:
 *       cardinal tiles that share no wall edge with the target, cardinal tiles behind one (the
 *       target is itself a wall or rock face), diagonal tiles likewise. Transport landings always
 *       count. The search ends at whichever goal is cheapest to reach.</li>
 * </ol>
 */
final class ReachableGoalRule implements GoalRule
{
	private final CollisionMap map;
	private final IntPredicate transportDestination;
	private final IntPredicate reachable;
	private final int start;
	private final int radius;

	/** {@code reachable} is true for the tiles some route can get to. */
	ReachableGoalRule(CollisionMap map, IntPredicate transportDestination, IntPredicate reachable, int start,
		int unreachableDistance)
	{
		this.map = map;
		this.transportDestination = transportDestination;
		this.reachable = reachable;
		this.start = start;
		this.radius = TargetGoals.expansionRadius(unreachableDistance);
	}

	// Rule 1.
	@Override
	public boolean endsOnItself(int target)
	{
		return !TargetGoals.isBlocked(map, target) && reachable.test(target);
	}

	// Rules 2 and 4; an empty set is rule 3.
	@Override
	public Set<Integer> fallbackTiles(int target)
	{
		for (int ring = 1; ring <= radius; ring++)
		{
			final Set<Integer> reachableTiles = new HashSet<>();
			final Set<Integer> landings = new HashSet<>();
			final int[] offsets = TargetGoals.ringOffsets(ring);
			for (int i = 0; i < offsets.length; i += 2)
			{
				final int tile = WorldPointUtil.packWorldPoint(WorldPointUtil.unpackWorldX(target) + offsets[i],
					WorldPointUtil.unpackWorldY(target) + offsets[i + 1], WorldPointUtil.unpackWorldPlane(target));
				if (tile == start)
				{
					continue;
				}
				if (reachable.test(tile))
				{
					reachableTiles.add(tile);
				}
				if (transportDestination.test(tile))
				{
					landings.add(tile);
				}
			}
			final Set<Integer> candidates = ring == 1 ? interactionTier(target, reachableTiles) : reachableTiles;
			candidates.addAll(landings);
			if (!candidates.isEmpty())
			{
				return candidates;
			}
		}
		return Set.of();
	}

	// The first non-empty tier of the tiles touching the target, in the order
	// they can be interacted from: cardinal before diagonal, and open before
	// behind a wall edge.
	private Set<Integer> interactionTier(int target, Set<Integer> adjacent)
	{
		for (boolean diagonal : new boolean[] {false, true})
		{
			for (boolean walled : new boolean[] {false, true})
			{
				final Set<Integer> tier = new HashSet<>();
				for (int tile : adjacent)
				{
					if (isDiagonal(target, tile) == diagonal && isWalled(target, tile) == walled)
					{
						tier.add(tile);
					}
				}
				if (!tier.isEmpty())
				{
					return tier;
				}
			}
		}
		return new HashSet<>();
	}

	private static boolean isDiagonal(int target, int tile)
	{
		return WorldPointUtil.unpackWorldX(tile) != WorldPointUtil.unpackWorldX(target)
			&& WorldPointUtil.unpackWorldY(tile) != WorldPointUtil.unpackWorldY(target);
	}

	private boolean isWalled(int target, int tile)
	{
		return TargetGoals.wallSeparated(map, WorldPointUtil.unpackWorldX(target), WorldPointUtil.unpackWorldY(target),
			WorldPointUtil.unpackWorldX(tile), WorldPointUtil.unpackWorldY(tile), WorldPointUtil.unpackWorldPlane(target));
	}
}

package shortestpath.pathfinder;

import java.util.function.LongSupplier;

/**
 * The calculation cutoff as checked from a search loop.
 *
 * <p>Reading the clock can cost more than a whole search step: over a microsecond on Linux when
 * the kernel uses the HPET clock source instead of the TSC. {@link #expired()} is called for
 * every step but only reads the clock on every {@value #CHECK_INTERVAL}th call, so the cutoff
 * fires at most one interval (well under a millisecond of search) late.
 */
public final class SearchDeadline
{
	static final int CHECK_INTERVAL = 1024;

	private final LongSupplier nanoClock;
	private final long cutoffNanos;
	private long deadline;
	private int unchecked;
	private boolean progressed;
	private boolean expired;

	/** A deadline {@code cutoffMillis} from now; zero expires at the first clock read. */
	public SearchDeadline(long cutoffMillis)
	{
		this(cutoffMillis, System::nanoTime);
	}

	SearchDeadline(long cutoffMillis, LongSupplier nanoClock)
	{
		this.nanoClock = nanoClock;
		this.cutoffNanos = Math.max(0, cutoffMillis) * 1_000_000L;
		this.deadline = nanoClock.getAsLong() + cutoffNanos;
	}

	/**
	 * Restarts the countdown, for cutoffs measured from the last progress rather than from the
	 * start. Takes effect at the next clock read.
	 */
	public void progressed()
	{
		progressed = true;
	}

	/** Whether the cutoff has passed, as of the most recent clock read. */
	public boolean expired()
	{
		if (expired)
			return true;
		if (++unchecked < CHECK_INTERVAL)
			return false;
		unchecked = 0;
		long now = nanoClock.getAsLong();
		if (progressed)
		{
			progressed = false;
			deadline = now + cutoffNanos;
			return false;
		}
		expired = now - deadline > 0 || cutoffNanos == 0;
		return expired;
	}
}

package shortestpath.pathfinder;

import java.io.*;
import java.util.*;
import java.util.zip.*;

import lombok.*;

import static net.runelite.api.Constants.REGION_SIZE;

import shortestpath.Util;
import shortestpath.transport.ResourceLoader;

public class SplitFlagMap
{
	// Per-tile flag layout matching the collision-map dump format: flags 0/1
	// record whether the north/south and east/west edges are open for
	// movement; flags 2/3 mark those edges as structural boundaries written
	// by walls and doors rather than object footprints or tile-level blocks.
	public static final int FLAG_NORTH = 0;
	public static final int FLAG_EAST = 1;
	public static final int FLAG_WALL_NORTH = 2;
	public static final int FLAG_WALL_EAST = 3;
	private static final int FLAG_COUNT = 4;
	private static final int BITS_PER_PLANE = REGION_SIZE * REGION_SIZE * FLAG_COUNT;
	private static final int WORDS_PER_PLANE = BITS_PER_PLANE / Long.SIZE;
	private static final int REGION_MASK = REGION_SIZE - 1;

	@Getter
	private static RegionExtent regionExtents;

	private final byte[] regionMapPlaneCounts;
	// Every region's collision bits are packed into one shared word array instead of a separate
	// FlagMap + BitSet + long[] per region. regionWordOffset gives each region's start word, or -1
	// when the region has no collision data (issue #491).
	private final long[] flags;
	private final int[] regionWordOffset;
	private final int widthInclusive;

	public SplitFlagMap(Map<Integer, byte[]> compressedRegions)
	{
		widthInclusive = regionExtents.getWidth() + 1;
		final int heightInclusive = regionExtents.getHeight() + 1;
		final int regionCount = widthInclusive * heightInclusive;
		regionMapPlaneCounts = new byte[regionCount];
		regionWordOffset = new int[regionCount];
		Arrays.fill(regionWordOffset, -1);

		// First pass: decode each region and reserve it a slice of the shared word array.
		final Map<Integer, long[]> regionWords = new HashMap<>(compressedRegions.size());
		int totalWords = 0;
		for (Map.Entry<Integer, byte[]> entry : compressedRegions.entrySet())
		{
			final int pos = entry.getKey();
			final int index = getIndex(unpackX(pos), unpackY(pos));
			final BitSet bits = BitSet.valueOf(entry.getValue());
			// Same plane-count derivation the old FlagMap used.
			final int planeCount = (bits.size() + BITS_PER_PLANE - 1) / BITS_PER_PLANE;
			regionMapPlaneCounts[index] = (byte) planeCount;
			regionWordOffset[index] = totalWords;
			regionWords.put(index, bits.toLongArray());
			totalWords += planeCount * WORDS_PER_PLANE;
		}

		// Second pass: copy each region's words into its reserved slice (trailing zero words from
		// BitSet.toLongArray are left as the zero-filled remainder of the slice).
		flags = new long[totalWords];
		for (Map.Entry<Integer, long[]> entry : regionWords.entrySet())
		{
			final long[] words = entry.getValue();
			System.arraycopy(words, 0, flags, regionWordOffset[entry.getKey()], words.length);
		}
	}

	public static int unpackX(int position)
	{
		return position & 0xFFFF;
	}

	public static int unpackY(int position)
	{
		return (position >> 16) & 0xFFFF;
	}

	public static int packPosition(int x, int y)
	{
		return (x & 0xFFFF) | ((y & 0xFFFF) << 16);
	}

	public static SplitFlagMap fromResources()
	{
		Map<Integer, byte[]> compressedRegions = new HashMap<>();
		try (ZipInputStream in = new ZipInputStream(ResourceLoader.collisionMap()))
		{
			int minX = Integer.MAX_VALUE;
			int minY = Integer.MAX_VALUE;
			int maxX = 0;
			int maxY = 0;

			ZipEntry entry;
			while ((entry = in.getNextEntry()) != null)
			{
				String[] n = entry.getName().split("_");
				final int x = Integer.parseInt(n[0]);
				final int y = Integer.parseInt(n[1]);
				minX = Math.min(minX, x);
				minY = Math.min(minY, y);
				maxX = Math.max(maxX, x);
				maxY = Math.max(maxY, y);

				compressedRegions.put(SplitFlagMap.packPosition(x, y), Util.readAllBytes(in));
			}

			regionExtents = new RegionExtent(minX, minY, maxX, maxY);
		}
		catch (IOException e)
		{
			throw new UncheckedIOException(e);
		}

		return new SplitFlagMap(compressedRegions);
	}

	public byte getRegionPlaneCounts(int index)
	{
		return regionMapPlaneCounts[index];
	}

	/**
	 * A 64-bit digest of the collision data: the region grid width, then, for every region that has
	 * data in ascending region order, its index, plane count and flag words. It does not depend on
	 * how the regions are laid out in the shared word array, so two maps decoded from the same
	 * regions agree. It is a change detector for derived data such as the routing component layer,
	 * not a cryptographic hash.
	 */
	public long fingerprint()
	{
		long hash = mix(0x243f6a8885a308d3L, widthInclusive);
		for (int index = 0; index < regionWordOffset.length; index++)
		{
			final int wordOffset = regionWordOffset[index];
			if (wordOffset < 0)
			{
				continue;
			}
			final int words = regionMapPlaneCounts[index] * WORDS_PER_PLANE;
			hash = mix(mix(hash, index), words);
			for (int word = 0; word < words; word++)
			{
				hash = mix(hash, flags[wordOffset + word]);
			}
		}
		return hash;
	}

	private static long mix(long hash, long value)
	{
		hash = (hash ^ value) * 0x9e3779b97f4a7c15L;
		return hash ^ (hash >>> 29);
	}

	public boolean get(int x, int y, int z, int flag)
	{
		final int index = getIndex(x / REGION_SIZE, y / REGION_SIZE);
		if (index < 0 || index >= regionWordOffset.length)
		{
			return false;
		}

		final int wordOffset = regionWordOffset[index];
		if (wordOffset < 0 || z < 0 || z >= regionMapPlaneCounts[index])
		{
			return false;
		}

		// SplitFlagMap routes (x, y) to the region that contains it, so the in-region coordinates
		// are simply the low REGION_SIZE bits; this matches the old FlagMap.index arithmetic.
		final int localBit = (z * REGION_SIZE * REGION_SIZE
			+ (y & REGION_MASK) * REGION_SIZE
			+ (x & REGION_MASK)) * FLAG_COUNT + flag;
		return (flags[wordOffset + (localBit >> 6)] >>> (localBit & 63) & 1L) != 0L;
	}

	private int getIndex(int regionX, int regionY)
	{
		return (regionX - regionExtents.getMinX()) + (regionY - regionExtents.getMinY()) * widthInclusive;
	}

	@RequiredArgsConstructor
	@Getter
	public static class RegionExtent
	{
		public final int minX, minY, maxX, maxY;

		public int getWidth()
		{
			return maxX - minX;
		}

		public int getHeight()
		{
			return maxY - minY;
		}
	}
}

package shortestpath.pathfinder;

import java.util.List;
import shortestpath.WorldPointUtil;
import shortestpath.requirement.model.TransportItems;
import lombok.*;

/**
 * A tile a search may end on, with the items the player must hold when they arrive there: a spade
 * for a dig spot, an emote clue's outfit. A target the player picks has no required items; other
 * plugins can add them. Immutable.
 */
@AllArgsConstructor(access = AccessLevel.PRIVATE)
@EqualsAndHashCode
public final class Target
{
	/** The required items of a target that needs none. */
	public static final TransportItems NO_ITEMS = new TransportItems(List.of());

	@Getter private final int point;
	@Getter private final TransportItems requiredItems;

	/** A target at {@code point} that needs no items. */
	public static Target at(int point)
	{
		return new Target(point, NO_ITEMS);
	}

	/** A target at {@code point} that the player must reach holding {@code requiredItems}. */
	public static Target requiring(int point, TransportItems requiredItems)
	{
		if (requiredItems == null)
		{
			throw new NullPointerException("requiredItems");
		}
		return new Target(point, requiredItems);
	}

	/** The packed tile. */


	/** Every item group the player must hold on arrival; {@link #NO_ITEMS} when none. */


	public boolean hasRequiredItems()
	{
		return requiredItems.size() > 0;
	}

	@Override
	public String toString()
	{
		return WorldPointUtil.unpackWorldPoint(point) + (hasRequiredItems() ? " requiring " + requiredItems.size()
			+ " item group(s)" : "");
	}
}

package shortestpath.pathfinder;

import java.util.*;
import java.util.function.IntPredicate;
import shortestpath.WorldPointUtil;
import lombok.Getter;
import lombok.experimental.Accessors;

/**
 * Resolves the requested targets into the tiles a search should terminate on.
 * A walkable target terminates on itself; a blocked target can never produce
 * walk-in edges, so it expands to the nearest fallback tiles within the
 * configured unreachable distance — every walkable tile in the square, or only
 * the tiles on the target's enclosed (interior) side when
 * collisionAwareBlockedTargets is on (issue #640). That is
 * {@link #collisionRule}; a search can resolve its targets with another
 * {@link GoalRule}, which can use the ring and wall helpers here.
 */
public final class TargetGoals
{
	// How many walking steps the enclosure check around a blocked target
	// takes. Must stay short: within a couple of steps a wall still separates
	// the two sides, while further out both sides connect around wall ends.
	private static final int ENCLOSURE_DEPTH = 3;
	// How far out from a blocked target to score walkable candidates. Tiles
	// in the innermost ring holding a sufficiently enclosed candidate become
	// goals, so this bounds the enclosure scan; deeper rings only contribute
	// transport destinations.
	private static final int ENCLOSURE_SCAN_RADIUS = 4;
	// Upper bound for the blocked-target expansion scan. The unreachable distance
	// config allows values up to 20000; scanning a (2r+1)^2 square per blocked
	// target must stay cheap since it runs per request.
	private static final int MAX_GOAL_EXPANSION_RADIUS = 64;

	@Getter @Accessors(fluent = true) private final Set<Integer> goals;
	private final boolean viable;
	private final Map<Integer, Set<Integer>> fallbacks;
	private final Set<Integer> viableTargets;

	private TargetGoals(Set<Integer> goals, boolean viable, Map<Integer, Set<Integer>> fallbacks,
		Set<Integer> viableTargets)
	{
		this.goals = goals;
		this.viable = viable;
		this.fallbacks = fallbacks;
		this.viableTargets = viableTargets;
	}

	/**
	 * The termination set: the requested targets plus, for each blocked target,
	 * the fallback tiles it resolved to.
	 */


	/**
	 * Whether any requested target could possibly terminate a search: non-blocked,
	 * a transport destination, or resolved to at least one walkable nearby tile.
	 * When false no goal can ever be visited, so the search can be skipped.
	 */
	public boolean hasViableGoal()
	{
		return viable;
	}

	/**
	 * The fallback tiles a blocked {@code target} resolved to; empty for a walkable target or one
	 * with no usable tile nearby. The target itself is not included.
	 */
	public Set<Integer> fallbacks(int target)
	{
		return fallbacks.getOrDefault(target, Set.of());
	}

	/** Whether {@code target} on its own could terminate a search, as {@link #hasViableGoal()}. */
	public boolean isViable(int target)
	{
		return viableTargets.contains(target);
	}

	/**
	 * Resolves each of {@code targets} with {@code rule}: a target the search can end on is its own
	 * goal; any other is replaced by its fallback tiles. A target is viable when the search can end
	 * on it, a transport lands on it, or it has fallback tiles.
	 */
	public static TargetGoals resolve(Set<Integer> targets, IntPredicate transportDestination, GoalRule rule)
	{
		Set<Integer> resolvedGoals = targets;
		Map<Integer, Set<Integer>> fallbacks = new HashMap<>();
		Set<Integer> viableTargets = new HashSet<>();
		for (int target : targets)
		{
			if (rule.endsOnItself(target))
			{
				viableTargets.add(target);
				continue;
			}
			// A transport landing on the target can still visit it even when the tile
			// is blocked for walking (e.g. fairy rings).
			if (transportDestination.test(target))
			{
				viableTargets.add(target);
			}
			final Set<Integer> targetGoals = rule.fallbackTiles(target);
			if (!targetGoals.isEmpty())
			{
				if (resolvedGoals == targets)
				{
					resolvedGoals = new HashSet<>(targets);
				}
				resolvedGoals.addAll(targetGoals);
				fallbacks.put(target, targetGoals);
				viableTargets.add(target);
			}
		}
		return new TargetGoals(resolvedGoals, !viableTargets.isEmpty(), fallbacks, viableTargets);
	}

	/**
	 * The rule decided from the collision map alone: a walkable target ends the search itself; a
	 * blocked target falls back as the class describes. The config values are read here, so a rule
	 * built when a search is created can be applied later on the search's own thread.
	 */
	public static GoalRule collisionRule(PathfinderConfig config, int start)
	{
		final CollisionMap map = config.getMap();
		final IntPredicate transportDestination = config::isTransportDestination;
		final int radius = expansionRadius(config.getUnreachableTargetDistance());
		final boolean collisionAware = config.isCollisionAwareBlockedTargets();
		return new GoalRule()
		{
			@Override
			public boolean endsOnItself(int target)
			{
				return !isBlocked(map, target);
			}

			// The target tile is blocked so it can never be walked into. Route to the
			// nearest fallback tiles within the configured unreachable distance
			// instead: walkable tiles, and blocked tiles that a transport can land
			// on (a teleport that lands adjacent to the target still gets close
			// enough). Both modes scan expanding rings and keep only the innermost
			// ring that yields goals, so the path ends on the tiles closest to the
			// target rather than whichever radius tile is cheapest for the player.
			// When collisionAwareBlockedTargets is on, walkable fallback goals are
			// limited to the target's open side, so the path cannot "reach the
			// target" from the wrong side of a wall. Transport destinations stay
			// goals in both modes.
			@Override
			public Set<Integer> fallbackTiles(int target)
			{
				return collisionAware
					? expandingConnectedGoals(map, transportDestination, start, target, radius)
					: expandingRingGoals(map, transportDestination, start, target, radius);
			}
		};
	}

	/**
	 * How far out a rule looks for fallback tiles. The scan is bounded: the config allows huge
	 * distances and goals are resolved per pathfinding request.
	 */
	static int expansionRadius(int unreachableDistance)
	{
		return Math.min(unreachableDistance, MAX_GOAL_EXPANSION_RADIUS);
	}

	static boolean isBlocked(CollisionMap map, int packed)
	{
		return map.isBlocked(WorldPointUtil.unpackWorldX(packed), WorldPointUtil.unpackWorldY(packed),
			WorldPointUtil.unpackWorldPlane(packed));
	}

	// The tiles on Chebyshev ring r as flat (dx, dy) pairs, perimeter order.
	// Generating the perimeter directly keeps ring scans O(r) rather than
	// O(r^2) over the whole square.
	static int[] ringOffsets(int r)
	{
		final int[] offsets = new int[r * 16];
		int i = 0;
		for (int s = -r; s < r; s++)
		{
			offsets[i++] = s;
			offsets[i++] = -r;
			offsets[i++] = r;
			offsets[i++] = s;
			offsets[i++] = -s;
			offsets[i++] = r;
			offsets[i++] = -r;
			offsets[i++] = -s;
		}
		return offsets;
	}

	// Expanding Chebyshev rings around a blocked target: returns the innermost
	// ring that contains any walkable tile or transport destination. Used when
	// collisionAwareBlockedTargets is off, so connectivity is not considered.
	private static Set<Integer> expandingRingGoals(CollisionMap map, IntPredicate transportDestination,
		int start, int target, int radius)
	{
		final int x = WorldPointUtil.unpackWorldX(target);
		final int y = WorldPointUtil.unpackWorldY(target);
		final int z = WorldPointUtil.unpackWorldPlane(target);
		final Set<Integer> goals = new HashSet<>();
		for (int r = 1; r <= radius && goals.isEmpty(); r++)
		{
			final int[] ring = ringOffsets(r);
			// Walkable diagonal tiles on the interaction ring are held back:
			// the target cannot be interacted with from a diagonal tile, so
			// they count only when no cardinally adjacent tile is usable.
			final Set<Integer> diagonals = new HashSet<>();
			for (int i = 0; i < ring.length; i += 2)
			{
				final int nx = x + ring[i];
				final int ny = y + ring[i + 1];
				final int packed = WorldPointUtil.packWorldPoint(nx, ny, z);
				if (r == 1 && nx != x && ny != y && packed != start
					&& !map.isBlocked(nx, ny, z))
				{
					diagonals.add(packed);
					continue;
				}
				addRingGoal(map, transportDestination, start, goals, nx, ny, z);
			}
			if (r == 1 && goals.isEmpty())
			{
				goals.addAll(diagonals);
			}
		}
		return goals;
	}

	private static void addRingGoal(CollisionMap map, IntPredicate transportDestination, int start,
		Set<Integer> goals, int nx, int ny, int nz)
	{
		final int packed = WorldPointUtil.packWorldPoint(nx, ny, nz);
		if (packed == start)
		{
			return;
		}
		if (!map.isBlocked(nx, ny, nz) || transportDestination.test(packed))
		{
			goals.add(packed);
		}
	}

	// A blocked tile's movement flags report every direction blocked, so the
	// target's own edges cannot tell apart a wall and the object's footprint
	// -- but the boundary flags still record which edges carry a wall or
	// door, and neighbours behind one are kept back while open neighbours
	// remain. When every walkable neighbour is behind a boundary edge the
	// target is itself the wall or rock face, and the tiles touching it are
	// the only ones it can be interacted with from. Where several sides
	// remain, tiles on the target's side of a wall (its room or corridor)
	// reach fewer tiles in a few steps than tiles on open ground: the most
	// enclosed candidate of the innermost ring anchors the side, and flooding
	// from it stays inside the same wall-bounded component. Scanning deeper
	// rings matters only for targets hemmed in by other objects, where every
	// adjacent tile lies outside the room and only ring 2+ tiles sit inside
	// it. Transport destinations ignore walls entirely; they are scanned per
	// Chebyshev ring and count as equally near goals.
	private static Set<Integer> expandingConnectedGoals(CollisionMap map, IntPredicate transportDestination,
		int start, int target, int radius)
	{
		final int x = WorldPointUtil.unpackWorldX(target);
		final int y = WorldPointUtil.unpackWorldY(target);
		final int z = WorldPointUtil.unpackWorldPlane(target);
		final int scan = Math.min(radius, ENCLOSURE_SCAN_RADIUS);
		// Walkable candidates in the innermost non-empty ring: {packed, reach}.
		final ArrayList<int[]> candidates = new ArrayList<>();
		// Adjacent tiles behind a boundary edge -- a wall or door rather than
		// the object's own footprint -- may sit on the wrong side of the
		// target, so they never anchor the side the search expands on. They
		// remain eligible as goals: when one shares the anchor's side after
		// all, the boundary is the target's own face -- a wall or rock that
		// can only be interacted with from the tiles touching it.
		final Set<Integer> boundaryFaces = new HashSet<>();
		// The candidate marking the target's side is the most enclosed one
		// of the nearest ring with any candidate at all.
		int anchor = -1;
		int anchorRing = 0;
		int anchorReach = Integer.MAX_VALUE;
		for (int d = 1; d <= scan && anchorRing == 0; d++)
		{
			final int[] ring = ringOffsets(d);
			for (int i = 0; i < ring.length; i += 2)
			{
				final int nx = x + ring[i];
				final int ny = y + ring[i + 1];
				final int packed = WorldPointUtil.packWorldPoint(nx, ny, z);
				// The player's own tile is never a useful goal: ending on
				// the first dequeued node yields an invisible path.
				if (packed == start || map.isBlocked(nx, ny, z))
				{
					continue;
				}
				if (d == 1 && wallSeparated(map, x, y, nx, ny, z))
				{
					boundaryFaces.add(packed);
					continue;
				}
				final int reach = localReach(map, packed);
				candidates.add(new int[] {packed, reach});
				if (reach < anchorReach)
				{
					anchorReach = reach;
					anchor = packed;
				}
			}
			if (!candidates.isEmpty())
			{
				anchorRing = d;
			}
		}
		// Tiles that share the anchor's side of the target's walls. The
		// flood is bounded by the anchor's own ring and does not cross
		// boundary edges. A wall end inside the box is still walked around
		// -- such tiles are legitimately connected, just not usable goals
		// when an adjacent face qualifies first.
		final Set<Integer> sameSide = new HashSet<>();
		if (anchor != -1)
		{
			final ArrayDeque<Integer> queue = new ArrayDeque<>();
			sameSide.add(anchor);
			queue.add(anchor);
			while (!queue.isEmpty())
			{
				final int from = queue.poll();
				final int fx = WorldPointUtil.unpackWorldX(from);
				final int fy = WorldPointUtil.unpackWorldY(from);
				for (int step : map.ordinaryWalkingNeighbors(from))
				{
					final int sx = WorldPointUtil.unpackWorldX(step);
					final int sy = WorldPointUtil.unpackWorldY(step);
					if (Math.max(Math.abs(sx - x), Math.abs(sy - y)) <= anchorRing
						&& !wallSeparated(map, fx, fy, sx, sy, z) && sameSide.add(step))
					{
						queue.add(step);
					}
				}
			}
		}
		final Set<Integer> goals = new HashSet<>();
		// Adjacent tiles that share the anchor's side are the nearest usable
		// goals. Cardinal faces are kept apart from diagonals: nothing can be
		// interacted with from a diagonal tile, so a diagonal only counts when
		// no cardinally adjacent tile is usable at all.
		final Set<Integer> diagonals = new HashSet<>();
		for (int d = 1; d <= radius && goals.isEmpty(); d++)
		{
			if (d == 1)
			{
				for (int face : boundaryFaces)
				{
					if (sameSide.contains(face))
					{
						(isCardinalFace(face, x, y) ? goals : diagonals).add(face);
					}
				}
				if (anchorRing == 1)
				{
					for (int[] candidate : candidates)
					{
						if (sameSide.contains(candidate[0]))
						{
							(isCardinalFace(candidate[0], x, y) ? goals : diagonals)
								.add(candidate[0]);
						}
					}
				}
				if (goals.isEmpty())
				{
					goals.addAll(diagonals);
				}
			}
			else if (d == anchorRing)
			{
				for (int[] candidate : candidates)
				{
					if (sameSide.contains(candidate[0]))
					{
						goals.add(candidate[0]);
					}
				}
			}
			addTransportRingGoals(transportDestination, start, goals, x, y, z, d);
		}
		return goals;
	}

	// Cardinally adjacent to the target: the only direction an object on the
	// target tile can be interacted with from.
	private static boolean isCardinalFace(int packed, int x, int y)
	{
		return WorldPointUtil.unpackWorldX(packed) == x
			|| WorldPointUtil.unpackWorldY(packed) == y;
	}

	// The boundary flag for the edge between two cardinally adjacent tiles
	// is stored once, on the lower tile -- mirroring the movement flags.
	private static boolean wallBetween(CollisionMap map, int ax, int ay, int bx, int by, int z)
	{
		if (bx != ax)
		{
			return map.wallE(Math.min(ax, bx), ay, z);
		}
		return map.wallN(ax, Math.min(ay, by), z);
	}

	// A cardinal neighbour shares exactly one edge with the target; a
	// diagonal neighbour counts as separated only when both flanking
	// cardinal routes to it cross a boundary edge.
	static boolean wallSeparated(CollisionMap map, int x, int y, int nx, int ny, int z)
	{
		final int dx = nx - x;
		final int dy = ny - y;
		if (dx == 0 || dy == 0)
		{
			return wallBetween(map, x, y, nx, ny, z);
		}
		return (wallBetween(map, x, y, x + dx, y, z) || wallBetween(map, x + dx, y, nx, ny, z))
			&& (wallBetween(map, x, y, x, y + dy, z) || wallBetween(map, x, y + dy, nx, ny, z));
	}

	// Counts the distinct tiles reachable from packedPoint within
	// ENCLOSURE_DEPTH ordinary walking steps -- a proxy for how enclosed the
	// tile is. Open ground scores near the geometric maximum; rooms and
	// corridors score lower because walls bound the flood.
	private static int localReach(CollisionMap map, int packedPoint)
	{
		// Each queued entry is the packed tile shifted by its remaining flood
		// depth, so one queue replaces per-depth draining.
		final Set<Integer> seen = new HashSet<>();
		final ArrayDeque<Long> queue = new ArrayDeque<>();
		seen.add(packedPoint);
		queue.add((long) packedPoint << 8 | ENCLOSURE_DEPTH);
		while (!queue.isEmpty())
		{
			final long entry = queue.poll();
			final int depth = (int) (entry & 0xff);
			if (depth == 0)
			{
				continue;
			}
			for (int neighbour : map.ordinaryWalkingNeighbors((int) (entry >> 8)))
			{
				if (seen.add(neighbour))
				{
					queue.add((long) neighbour << 8 | depth - 1);
				}
			}
		}
		return seen.size();
	}

	private static void addTransportRingGoals(IntPredicate transportDestination, int start,
		Set<Integer> goals, int x, int y, int z, int r)
	{
		final int[] ring = ringOffsets(r);
		for (int i = 0; i < ring.length; i += 2)
		{
			final int packed = WorldPointUtil.packWorldPoint(x + ring[i], y + ring[i + 1], z);
			if (packed != start && transportDestination.test(packed))
			{
				goals.add(packed);
			}
		}
	}
}

package shortestpath.pathfinder;

/**
 * Whether the player holds a target's required items, checked once when the search starts.
 */
public enum TargetStatus
{
	/** The inventory and worn items cover the requirement: the target counts in either bank layer. */
	CARRIED,
	/**
	 * The requirement is only covered once the bank's contents are added: the target counts only
	 * after the path has visited a bank.
	 */
	BANK,
	/**
	 * Neither the carried items nor the bank as last seen cover the requirement. A bank not opened
	 * this session counts as empty, as it does for item-gated transports. The target is only used
	 * when no other target can be completed.
	 */
	UNKNOWN
}

package shortestpath.pathfinder;

import java.util.*;
import lombok.*;
import shortestpath.WorldPointUtil;

/**
 * The targets of one route: at most one {@link Target} per tile. A search ends at whichever target
 * is cheapest to reach with that target's items in hand. Immutable.
 */
@EqualsAndHashCode
@ToString
public final class Targets implements Iterable<Target>
{
	public static final Targets NONE = new Targets(Map.of());

	private final Map<Integer, Target> byPoint;

	private Targets(Map<Integer, Target> byPoint)
	{
		this.byPoint = byPoint;
	}

	/** Targets at {@code points} that need no items. */
	public static Targets at(Collection<Integer> points)
	{
		Map<Integer, Target> byPoint = new LinkedHashMap<>();
		for (int point : points)
		{
			byPoint.put(point, Target.at(point));
		}
		return of(byPoint);
	}

	/**
	 * {@code targets} as one set. The same tile twice is only allowed when both ask for the same
	 * items; anything else is ambiguous and throws {@link IllegalArgumentException}.
	 */
	public static Targets of(Collection<Target> targets)
	{
		Map<Integer, Target> byPoint = new LinkedHashMap<>();
		for (Target target : targets)
		{
			Target previous = byPoint.putIfAbsent(target.getPoint(), target);
			if (previous != null && !previous.equals(target))
			{
				throw new IllegalArgumentException("target " + WorldPointUtil.unpackWorldPoint(target.getPoint())
					+ " is given twice with different required items");
			}
		}
		return of(byPoint);
	}

	private static Targets of(Map<Integer, Target> byPoint)
	{
		return byPoint.isEmpty() ? NONE : new Targets(Collections.unmodifiableMap(byPoint));
	}

	/** The packed target tiles. */
	public Set<Integer> points()
	{
		return byPoint.keySet();
	}

	/** The target at {@code point}, or {@code null} when there is none. */
	public Target get(int point)
	{
		return byPoint.get(point);
	}

	public boolean contains(int point)
	{
		return byPoint.containsKey(point);
	}

	public boolean isEmpty()
	{
		return byPoint.isEmpty();
	}

	public int size()
	{
		return byPoint.size();
	}

	/** Whether any target needs items on arrival. */
	public boolean hasRequiredItems()
	{
		for (Target target : byPoint.values())
		{
			if (target.hasRequiredItems())
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * The targets at exactly {@code points}: these targets where they have one, and targets that need
	 * no items elsewhere.
	 */
	public Targets restrictTo(Collection<Integer> points)
	{
		Map<Integer, Target> byPoint = new LinkedHashMap<>();
		for (int point : points)
		{
			byPoint.put(point, this.byPoint.getOrDefault(point, Target.at(point)));
		}
		return of(byPoint);
	}

	/** These targets plus those of {@code more} at tiles these don't already have. */
	public Targets plus(Targets more)
	{
		Map<Integer, Target> byPoint = new LinkedHashMap<>(this.byPoint);
		for (Target target : more)
		{
			byPoint.putIfAbsent(target.getPoint(), target);
		}
		return of(byPoint);
	}

	@Override
	public Iterator<Target> iterator()
	{
		return byPoint.values().iterator();
	}
}

package shortestpath.pathfinder;

import java.util.*;

import shortestpath.*;
import static shortestpath.poh.PohService.*;
import shortestpath.poh.PohService;
import shortestpath.transport.Transport;
import lombok.*;

@AllArgsConstructor(access = AccessLevel.PACKAGE)
public final class TransportAvailability
{
	public static final Transport[] EMPTY_TRANSPORTS = new Transport[0];

	// Transports grouped by origin tile, stored as flat arrays. The per-origin LinkedHashSet/
	// HashMap wrappers used while building are not retained (issue #491). The sets iterate in
	// insertion order, so the emitted arrays follow add() order and pathfinding neighbour
	// expansion is deterministic across JVM runs. Transport has no equals/hashCode, so a plain
	// HashSet would iterate in identity-hash order that varies per run.
	//
	// transportsPacked is the pathfinding view: a transport is reachable from its literal origin
	// tile, and POH transports are additionally reachable from the canonical landing tile.
	// displayTransports is the coarse display view used by overlays and getTransports(): POH origin
	// tiles are collapsed into the landing tile only. The two maps share their Transport[] arrays
	// for every non-POH origin.
	@Getter private final PrimitiveIntHashMap<Transport[]> transportsPacked;
	@Getter private final PrimitiveIntHashMap<Transport[]> displayTransports;
	@Getter private final Transport[] usableTeleports;




	/**
	 * The transports that start at the given origin tile in the display view, or an empty array.
	 */
	public Transport[] getTransportsAt(int origin)
	{
		return displayTransports.getOrDefault(origin, EMPTY_TRANSPORTS);
	}

	/*
	 * Build a TransportAvailability by incrementally adding available transports.
	 */
	static final class Builder
	{
		// Temporary accumulation; converted to flat arrays in build() and not retained afterwards.
		private final Map<Integer, Set<Transport>> transportsByOrigin;
		private final Set<Transport> usableTeleports;
		private final Set<Integer> pohOrigins = new HashSet<>();

		Builder(int expectedTransportCount)
		{
			this.transportsByOrigin = new HashMap<>(expectedTransportCount / 2);
			this.usableTeleports = new LinkedHashSet<>(expectedTransportCount / 20);
		}

		void add(Transport transport)
		{
			if (transport.getOrigin() == WorldPointUtil.UNDEFINED)
			{
				usableTeleports.add(transport);
				return;
			}

			transportsByOrigin.computeIfAbsent(transport.getOrigin(), ignored -> new LinkedHashSet<>()).add(transport);
		}

		void remapPohTransports()
		{
			int pohLanding = WorldPointUtil.packWorldPoint(POH_LANDING_X, POH_LANDING_Y, 0);
			Set<Transport> pohTransports = new LinkedHashSet<>();

			for (Map.Entry<Integer, Set<Transport>> entry : transportsByOrigin.entrySet())
			{
				int origin = entry.getKey();
				int originX = WorldPointUtil.unpackWorldX(origin);
				int originY = WorldPointUtil.unpackWorldY(origin);
				if (PohService.isInsidePoh(originX, originY) && origin != pohLanding)
				{
					pohTransports.addAll(entry.getValue());
					// Kept in the pathfinding view, collapsed out of the display view.
					pohOrigins.add(origin);
				}
			}

			if (!pohTransports.isEmpty())
			{
				transportsByOrigin.computeIfAbsent(pohLanding, ignored -> new LinkedHashSet<>()).addAll(pohTransports);
			}
		}

		TransportAvailability build()
		{
			int expected = Math.max(1, transportsByOrigin.size());
			PrimitiveIntHashMap<Transport[]> packed = new PrimitiveIntHashMap<>(expected);
			PrimitiveIntHashMap<Transport[]> display = new PrimitiveIntHashMap<>(expected);
			for (Map.Entry<Integer, Set<Transport>> entry : transportsByOrigin.entrySet())
			{
				int origin = entry.getKey();
				Transport[] transports = entry.getValue().toArray(EMPTY_TRANSPORTS);
				packed.put(origin, transports);
				if (!pohOrigins.contains(origin))
				{
					display.put(origin, transports);
				}
			}
			return new TransportAvailability(packed, display, usableTeleports.toArray(EMPTY_TRANSPORTS));
		}
	}
}

package shortestpath.pathfinder;

import static net.runelite.api.Constants.REGION_SIZE;

import shortestpath.WorldPointUtil;

public class VisitedTiles
{
	private final SplitFlagMap.RegionExtent regionExtents;
	private final int widthInclusive;

	private final VisitedRegion[] visitedRegionsWithoutBank;
	private final VisitedRegion[] visitedRegionsWithBank;
	private final CollisionMap map;
	// Abstract nodes are visited separately from tile nodes because they represent
	// global search states, not map positions.
	private final boolean[] abstractVisitedWithoutBank = new boolean[AbstractNodeKind.values().length];
	private final boolean[] abstractVisitedWithBank = new boolean[AbstractNodeKind.values().length];
	private final int bankVisitCost;

	public VisitedTiles(CollisionMap map, int bankVisitCost)
	{
		this.map = map;
		this.bankVisitCost = bankVisitCost;
		regionExtents = SplitFlagMap.getRegionExtents();
		widthInclusive = regionExtents.getWidth() + 1;
		final int heightInclusive = regionExtents.getHeight() + 1;

		visitedRegionsWithoutBank = new VisitedRegion[widthInclusive * heightInclusive];
		visitedRegionsWithBank = new VisitedRegion[widthInclusive * heightInclusive];
	}

	public boolean get(int packedPoint, BankVisitState bankVisited)
	{
		final int x = WorldPointUtil.unpackWorldX(packedPoint);
		final int y = WorldPointUtil.unpackWorldY(packedPoint);
		final int plane = WorldPointUtil.unpackWorldPlane(packedPoint);
		return get(x, y, plane, bankVisited);
	}

	public boolean get(int x, int y, int plane, BankVisitState bankVisited)
	{
		VisitedRegion[] visitedRegions = bankVisited == BankVisitState.BANKED
			? visitedRegionsWithBank : visitedRegionsWithoutBank;
		final int regionIndex = getRegionIndex(x / REGION_SIZE, y / REGION_SIZE);
		if (regionIndex < 0 || regionIndex >= visitedRegions.length)
		{
			return true; // Region is out of bounds; report that it's been visited to avoid exploring it
			// further
		}

		final VisitedRegion region = visitedRegions[regionIndex];
		if (region == null)
		{
			return false;
		}

		return region.get(x % REGION_SIZE, y % REGION_SIZE, plane);
	}

	public boolean set(int packedPoint, BankVisitState bankVisited)
	{
		final int x = WorldPointUtil.unpackWorldX(packedPoint);
		final int y = WorldPointUtil.unpackWorldY(packedPoint);
		final int plane = WorldPointUtil.unpackWorldPlane(packedPoint);
		return set(x, y, plane, bankVisited);
	}

	public boolean get(int id, NodeGraph graph)
	{
		if (graph.isTile(id))
		{
			return get(graph.packedPosition(id), graph.bankVisited(id));
		}
		return getAbstract(graph.abstractKind(id), graph.bankVisited(id));
	}

	public boolean getAbstract(AbstractNodeKind abstractKind, BankVisitState bankVisited)
	{
		return bankVisited == BankVisitState.BANKED
			? abstractVisitedWithBank[abstractKind.ordinal()]
			: abstractVisitedWithoutBank[abstractKind.ordinal()];
	}

	public boolean set(int id, NodeGraph graph)
	{
		if (graph.isTile(id))
		{
			return set(graph.packedPosition(id), graph.bankVisited(id));
		}

		final AbstractNodeKind abstractKind = graph.abstractKind(id);
		boolean visited = getAbstract(abstractKind, graph.bankVisited(id));
		if (graph.bankVisited(id) == BankVisitState.BANKED)
		{
			abstractVisitedWithBank[abstractKind.ordinal()] = true;
		}
		// Dominance is only valid when banking is free. A banked arrival pays the configured
		// bank visit cost, so when that cost is positive the banked arrival can be strictly
		// more expensive than a later unbanked arrival at the same state — marking the
		// unbanked bucket would prune the cheaper continuation and lose the better route.
		if (bankVisitCost <= 0 || graph.bankVisited(id) != BankVisitState.BANKED)
		{
			abstractVisitedWithoutBank[abstractKind.ordinal()] = true;
		}
		return !visited;
	}

	public boolean set(int x, int y, int plane, BankVisitState bankVisited)
	{
		final int regionIndex = getRegionIndex(x / REGION_SIZE, y / REGION_SIZE);
		if (regionIndex < 0 || regionIndex >= visitedRegionsWithoutBank.length)
		{
			return false; // Region is out of bounds; report that it's been visited to avoid exploring it
			// further
		}

		if (bankVisited == BankVisitState.BANKED)
		{
			boolean unique = setInRegion(visitedRegionsWithBank, regionIndex, x, y, plane);
			// A banked tile only dominates the equivalent unbanked tile when banking is
			// free: with a positive bank visit cost the banked arrival paid the penalty, so
			// a cheaper unbanked arrival must still be allowed to reach this tile.
			if (bankVisitCost <= 0)
			{
				setInRegion(visitedRegionsWithoutBank, regionIndex, x, y, plane);
			}
			return unique;
		}

		return setInRegion(visitedRegionsWithoutBank, regionIndex, x, y, plane);
	}

	private boolean setInRegion(VisitedRegion[] visitedRegions, int regionIndex, int x, int y, int plane)
	{
		VisitedRegion region = visitedRegions[regionIndex];
		if (region == null)
		{
			region = new VisitedRegion(map.getRegionPlaneCounts(regionIndex));
			visitedRegions[regionIndex] = region;
		}
		return region.set(x % REGION_SIZE, y % REGION_SIZE, plane);
	}

	public void clear()
	{
		for (int i = 0; i < visitedRegionsWithoutBank.length; ++i)
		{
			visitedRegionsWithoutBank[i] = null;
			visitedRegionsWithBank[i] = null;
		}
		for (int i = 0; i < abstractVisitedWithoutBank.length; i++)
		{
			abstractVisitedWithoutBank[i] = false;
			abstractVisitedWithBank[i] = false;
		}
	}

	private int getRegionIndex(int regionX, int regionY)
	{
		return (regionX - regionExtents.minX) + (regionY - regionExtents.minY) * widthInclusive;
	}

	private static class VisitedRegion
	{
		// This assumes a row is at most 64 tiles and fits in a long
		private final long[] planes;
		private final byte planeCount;

		VisitedRegion(byte planeCount)
		{
			this.planeCount = planeCount;
			this.planes = new long[planeCount * REGION_SIZE];
		}

		// Sets a tile as visited in the tile bitset
		// Returns true if the tile is unique and hasn't been seen before or false if it
		// was seen before
		public boolean set(int x, int y, int plane)
		{
			if (plane >= planeCount)
			{
				// Plane is out of bounds; report that it has been visited to avoid further
				// exploration
				return false;
			}
			final int index = y + plane * REGION_SIZE;
			boolean unique = (planes[index] & (1L << x)) == 0;
			planes[index] |= 1L << x;
			return unique;
		}

		public boolean get(int x, int y, int plane)
		{
			if (plane >= planeCount)
			{
				// This check is necessary since we check visited tiles before checking the
				// collision map, e.g. the node
				// at (2816, 3455, 1) will check its neighbour to the north which is in a new
				// region with no plane = 1
				return true;
			}
			return (planes[y + plane * REGION_SIZE] & (1L << x)) != 0;
		}
	}
}

package shortestpath.pathfinder;

import java.util.Set;

import net.runelite.api.coords.WorldArea;
import shortestpath.WorldPointUtil;

public class WildernessChecker
{

	private static final WorldArea WILDERNESS_ABOVE_GROUND = new WorldArea(2944, 3525, 448, 448, 0);
	private static final WorldArea WILDERNESS_UNDERGROUND = new WorldArea(2944, 9918, 518, 458, 0);

	private static final WorldArea FEROX_ENCLAVE_1 = new WorldArea(3123, 3622, 2, 10, 0);
	private static final WorldArea FEROX_ENCLAVE_2 = new WorldArea(3125, 3617, 16, 23, 0);
	private static final WorldArea FEROX_ENCLAVE_3 = new WorldArea(3138, 3636, 18, 10, 0);
	private static final WorldArea FEROX_ENCLAVE_4 = new WorldArea(3141, 3625, 14, 11, 0);
	private static final WorldArea FEROX_ENCLAVE_5 = new WorldArea(3141, 3619, 7, 6, 0);

	private static final WorldArea NOT_WILDERNESS_1 = new WorldArea(2997, 3525, 34, 9, 0);
	private static final WorldArea NOT_WILDERNESS_2 = new WorldArea(3005, 3534, 21, 10, 0);
	private static final WorldArea NOT_WILDERNESS_3 = new WorldArea(3000, 3534, 5, 5, 0);
	private static final WorldArea NOT_WILDERNESS_4 = new WorldArea(3031, 3525, 2, 2, 0);

	private static final WorldArea WILDERNESS_ABOVE_GROUND_LEVEL_20 = new WorldArea(2944, 3680, 448, 448, 0);
	private static final WorldArea WILDERNESS_ABOVE_GROUND_LEVEL_30 = new WorldArea(2944, 3760, 448, 448, 0);
	private static final WorldArea WILDERNESS_UNDERGROUND_LEVEL_20 = new WorldArea(2944, 10075, 518, 301, 0);
	private static final WorldArea WILDERNESS_UNDERGROUND_LEVEL_30 = new WorldArea(2944, 10155, 518, 221, 0);

	public static boolean isInWilderness(int packedPoint)
	{
		return WorldPointUtil.distanceToArea2D(packedPoint, WILDERNESS_ABOVE_GROUND) == 0
			&& WorldPointUtil.distanceToArea2D(packedPoint, FEROX_ENCLAVE_1) != 0
			&& WorldPointUtil.distanceToArea2D(packedPoint, FEROX_ENCLAVE_2) != 0
			&& WorldPointUtil.distanceToArea2D(packedPoint, FEROX_ENCLAVE_3) != 0
			&& WorldPointUtil.distanceToArea2D(packedPoint, FEROX_ENCLAVE_4) != 0
			&& WorldPointUtil.distanceToArea2D(packedPoint, FEROX_ENCLAVE_5) != 0
			&& WorldPointUtil.distanceToArea2D(packedPoint, NOT_WILDERNESS_1) != 0
			&& WorldPointUtil.distanceToArea2D(packedPoint, NOT_WILDERNESS_2) != 0
			&& WorldPointUtil.distanceToArea2D(packedPoint, NOT_WILDERNESS_3) != 0
			&& WorldPointUtil.distanceToArea2D(packedPoint, NOT_WILDERNESS_4) != 0
			|| WorldPointUtil.distanceToArea2D(packedPoint, WILDERNESS_UNDERGROUND) == 0;
	}

	public static boolean isInWilderness(Set<Integer> packedPoints)
	{
		for (int packedPoint : packedPoints)
		{
			if (isInWilderness(packedPoint))
			{
				return true;
			}
		}
		return false;
	}

	public static boolean isInLevel20Wilderness(int packedPoint)
	{
		return WorldPointUtil.distanceToArea2D(packedPoint, WILDERNESS_ABOVE_GROUND_LEVEL_20) == 0
			|| WorldPointUtil.distanceToArea2D(packedPoint, WILDERNESS_UNDERGROUND_LEVEL_20) == 0;
	}

	public static boolean isInLevel30Wilderness(int packedPoint)
	{
		return WorldPointUtil.distanceToArea2D(packedPoint, WILDERNESS_ABOVE_GROUND_LEVEL_30) == 0
			|| WorldPointUtil.distanceToArea2D(packedPoint, WILDERNESS_UNDERGROUND_LEVEL_30) == 0;
	}
}

package shortestpath.pathfinder.astar;

import java.util.*;
import java.util.function.BooleanSupplier;
import lombok.*;
import lombok.experimental.Accessors;
import shortestpath.*;
import shortestpath.pathfinder.*;
import shortestpath.transport.Transport;

/** Correctness-first forward search over tiles, capability hubs, and bank layers. */
public final class AStarForwardSearch
{
	/** A {@code progressed} callback for a search whose caller does not track progress. */
	public static final Runnable NO_PROGRESS = AStarForwardSearch::ignoreProgress;

	private AStarForwardSearch()
	{
	}

	private static void ignoreProgress()
	{
	}

	public static Result search(TargetOverlay target, PreparedHeuristic heuristic, int start)
	{
		return search(target, heuristic, start, () -> false, true, 1, SearchRestrictions.none(), NO_PROGRESS,
			(tile, banked) -> target.isTarget(tile));
	}

	/**
	 * {@code restrictions} applies the same positional gates as legacy's per-edge checks: the
	 * caller decides them per search, while the prepared graph and heuristic stay unchanged —
	 * gating only removes edges, so the heuristic can only under-estimate the distances left.
	 * {@code progressed} runs whenever the closest-reached-tile record improves, the same
	 * moment legacy reports progress for its without-progress cutoff.
	 */
	static Result search(TargetOverlay target, PreparedHeuristic heuristic, int start,
		BooleanSupplier cancelled, boolean optimized, double heuristicWeight, SearchRestrictions restrictions,
		Runnable progressed)
	{
		return search(target, heuristic, start, cancelled, optimized, heuristicWeight, restrictions, progressed,
			target::accepts);
	}

	/**
	 * {@code goal} decides which target states finish the search; it must only accept target
	 * tiles, and leaves the prepared heuristic admissible since it can only accept fewer states.
	 */
	public static Result search(TargetOverlay target, PreparedHeuristic heuristic, int start,
		BooleanSupplier cancelled, boolean optimized, double heuristicWeight, SearchRestrictions restrictions,
		Runnable progressed, GoalTest goal)
	{
		if (target == null || heuristic == null || cancelled == null || restrictions == null || progressed == null
			|| goal == null)
			throw new NullPointerException();
		if (heuristic.overlay() != target) throw new IllegalArgumentException("heuristic belongs to another target overlay");
		validateHeuristicWeight(heuristicWeight);
		SearchCtx ctx = new SearchCtx(target, heuristic, start, optimized, heuristicWeight, restrictions);
		AStarRoute startPath = AStarRoute.of(List.of(new PathStep(start, BankVisitState.CARRIED)), new int[1]);
		Closest closest = new Closest(target);
		if (cancelled.getAsBoolean()) return Result.cancelled(ctx.counters.snapshot(ctx.bestBankCost[0]), startPath);

		int startState = ctx.space.state(start, BankVisitState.CARRIED);
		ctx.updateBestBank(startState, 0);
		int startH = ctx.effectiveHeuristic(startState, 0);
		if (startH != CostArithmetic.INF)
		{
			ctx.best.set(startState, 0);
			ctx.push(startState, 0, priority(0, startH, heuristicWeight), true, PUSH_INITIAL);
		}
		else
		{
			ctx.counters.heuristicUnreachable++;
		}
		if (ctx.capability != TeleportCapability.ALL)
		{
			int hub = hub(ctx.tileStates, ctx.capability, BankVisitState.CARRIED);
			ctx.best.set(hub, 0);
			ctx.push(hub, 0, 0, true, PUSH_GLOBAL);
		}
		ctx.seedGlobals(startState);

		while (ctx.queue.poll())
		{
			if (cancelled.getAsBoolean())
				return Result.cancelled(ctx.counters.snapshot(ctx.bestBankCost[0]), startPath,
					closest.path(ctx, startState, startPath), closest.cost());
			int state = ctx.queue.state(), cost = ctx.queue.cost(), queuedPriority = ctx.queue.priority();
			if (cost != ctx.best.get(state))
	{ ctx.counters.staleEntries++; continue;
	}
			if (state >= ctx.tileStates)
			{
				ctx.relaxGlobalHub(state, cost);
				continue;
			}
			int node = state / 2;
			BankVisitState banked = (state & 1) != 0 ? BankVisitState.BANKED : BankVisitState.CARRIED;
			int tile = ctx.space.tile(node);
			if (ctx.capability != TeleportCapability.ALL)
				ctx.activateGlobal(tile, state, banked, cost);
			int currentH = ctx.effectiveHeuristic(state, cost);
			if (currentH == CostArithmetic.INF) continue;
			int currentPriority = priority(cost, currentH, heuristicWeight);
			if (currentPriority > queuedPriority)
			{
				ctx.push(state, cost, currentPriority, false, PUSH_REKEY);
				ctx.counters.rekeys++;
				continue;
			}
			ctx.counters.statesPopped++;
			if (target.isTarget(tile) && goal.accepts(tile, banked))
				return Result.reached(cost, state, ctx.counters.snapshot(ctx.bestBankCost[0]), ctx.reconstruct(startState, state));
			if (closest.consider(state, tile, cost))
				progressed.run();
			if (ctx.space.isBase(node))
			{
				ctx.walkBase(node, banked, state, cost);
				ctx.addBlockedOrigins(tile, banked, state, cost);
			}
			else
			{
				for (int next : target.collision().ordinaryWalkingNeighbors(tile))
					ctx.relaxWalking(next, banked, state, cost);
				ctx.addBlockedOrigins(tile, banked, state, cost);
			}
			ctx.relaxBank(node, banked, state, cost);
			ctx.relaxLocalTransports(tile, banked, state, cost);
		}
		return Result.unreachable(ctx.counters.snapshot(ctx.bestBankCost[0]), startPath,
			closest.path(ctx, startState, startPath), closest.cost());
	}

	/**
	 * The popped tile nearest to any target, chosen like the legacy pathfinder's closest reachable
	 * tile: minimum squared Euclidean distance, then travelled cost, then x, then y.
	 *
	 * <p>Only popped states compete: a state improved by a rekey after its last pop never wins
	 * the tie-break, which can shift which partial path a cut-off search returns.
	 */
	/**
	 * The transport behind each state a transport edge last improved, keyed by state. Only those
	 * few states have an entry, so a search no longer pays for one slot per reachable tile. An
	 * entry records the cost it set; every later improvement of the state lowers {@code best},
	 * so an entry still applies exactly when its cost equals the state's best cost, and walking
	 * improvements need not touch the map.
	 */
	private static final class TransportWins
	{
		private final PrimitiveIntHashMap<Win> wins = new PrimitiveIntHashMap<>(64);

		void record(int state, Transport transport, int cost)
		{
			if (transport == null) return;
			Win win = wins.get(state);
			if (win == null) wins.put(state, new Win(transport, cost));
			else
			{
				win.transport = transport;
				win.cost = cost;
			}
		}

		/** The transport that reached {@code state} at {@code bestCost}, or null for any other step. */
		Transport at(int state, int bestCost)
		{
			Win win = wins.get(state);
			return win != null && win.cost == bestCost ? win.transport : null;
		}

		private static final class Win
		{
			Transport transport;
			int cost;

			Win(Transport transport, int cost)
			{
				this.transport = transport;
				this.cost = cost;
			}
		}
	}

	private static final class Closest
	{
		private final TargetOverlay target;
		private int state = -1, cost = CostArithmetic.INF, x, y;
		private int distance = Integer.MAX_VALUE;

		Closest(TargetOverlay target)
		{
			this.target = target;
		}

		boolean consider(int state, int tile, int cost)
		{
			int remaining = Integer.MAX_VALUE;
			for (int i = 0; i < target.targetCount(); i++)
				remaining = Math.min(remaining, WorldPointUtil.distanceBetween(target.packedTarget(i), tile,
					WorldPointUtil.EUCLIDEAN_SQUARED_DISTANCE_METRIC));
			int tileX = WorldPointUtil.unpackWorldX(tile), tileY = WorldPointUtil.unpackWorldY(tile);
			if (remaining < distance
				|| (remaining == distance && cost < this.cost)
				|| (remaining == distance && cost == this.cost && tileX < x)
				|| (remaining == distance && cost == this.cost && tileX == x && tileY < y))
			{
				this.state = state;
				this.cost = cost;
				this.distance = remaining;
				this.x = tileX;
				this.y = tileY;
				return true;
			}
			return false;
		}

		AStarRoute path(SearchCtx ctx, int startState, AStarRoute startPath)
		{
			return state < 0 ? startPath : ctx.reconstruct(startState, state);
		}

		int cost()
		{
			return state < 0 ? 0 : cost;
		}
	}

	/**
	 * One search's mutable state: the workspace arrays, queue, counters and the per-query
	 * settings the relax helpers share. A single instance lives for the whole search — the
	 * {@code best}/{@code previous} arrays stay final fields and nothing in the relax loop
	 * allocates — so the helpers stay monomorphic private methods the JIT inlines like the
	 * static methods they replace.
	 */
	private static final class SearchCtx
	{
		final TargetOverlay target;
		final SearchSpace space;
		final PreparedHeuristic heuristic;
		final TeleportCapability capability;
		final AStarMinHeap queue;
		final TransportWins transportWins = new TransportWins();
		final MutableCounters counters;
		final PagedSearchArray best, previous;
		final int[] globalBounds;
		final int[] bestBankCost = {CostArithmetic.INF};
		final boolean restrictedHeuristic, optimized;
		final double heuristicWeight;
		final int tileStates;

		SearchCtx(TargetOverlay target, PreparedHeuristic heuristic, int start, boolean optimized,
			double heuristicWeight, SearchRestrictions restrictions)
		{
			this.target = target;
			this.heuristic = heuristic;
			this.optimized = optimized;
			this.heuristicWeight = heuristicWeight;
			space = SearchSpace.create(target, start, restrictions);
			capability = capabilityAt(start);
			tileStates = space.tileCount * 2;
			int stateCount = tileStates + (capability == TeleportCapability.ALL ? 0 : HUB_STATES);
			best = new PagedSearchArray(stateCount, CostArithmetic.INF);
			previous = new PagedSearchArray(stateCount, 0);
			restrictedHeuristic = capability != TeleportCapability.ALL && hasGlobals(target.account());
			counters = new MutableCounters(capability, !restrictedHeuristic);
			globalBounds = restrictedHeuristic ? computeGlobalBounds() : null;
			queue = new AStarMinHeap(Math.min(stateCount, 32_768));
		}

		private void walkBase(int node, BankVisitState banked, int from, int cost)
		{
			int mask = space.stat.walkingMask(node);
			emit(banked, from, mask, 6, node - 1, cost);
			emit(banked, from, mask, 2, node + 1, cost);
			emit(banked, from, mask, 4, space.stat.southNode(node), cost);
			emit(banked, from, mask, 0, space.stat.northNode(node), cost);
			int south = space.stat.southNode(node), north = space.stat.northNode(node);
			emit(banked, from, mask, 5, south < 0 ? -1 : south - 1, cost);
			emit(banked, from, mask, 3, south < 0 ? -1 : south + 1, cost);
			emit(banked, from, mask, 7, north < 0 ? -1 : north - 1, cost);
			emit(banked, from, mask, 1, north < 0 ? -1 : north + 1, cost);
		}

		private void emit(BankVisitState banked, int from, int mask, int bit, int next, int cost)
		{
			if ((mask & (1 << bit)) != 0 && next >= 0 && next < space.baseCount && space.stepAllowed(from / 2, next))
				relaxState(from, stateForNode(next, banked), cost, 1, null, PUSH_WALKING);
		}

		private void addBlockedOrigins(int tile, BankVisitState banked, int from, int cost)
		{
			CollisionMap collision = target.collision();
			if (collision.isBlocked(WorldPointUtil.unpackWorldX(tile), WorldPointUtil.unpackWorldY(tile), WorldPointUtil.unpackWorldPlane(tile))) return;
			int x = WorldPointUtil.unpackWorldX(tile), y = WorldPointUtil.unpackWorldY(tile), plane = WorldPointUtil.unpackWorldPlane(tile);
			for (int direction = 0; direction < 4; direction++)
			{
				int next = WorldPointUtil.packWorldPoint(x + GameWalkOrder.ORDER_DX[direction],
					y + GameWalkOrder.ORDER_DY[direction], plane);
				if (collision.isBlocked(WorldPointUtil.unpackWorldX(next), WorldPointUtil.unpackWorldY(next), WorldPointUtil.unpackWorldPlane(next)) && space.hasLocalOrigin(next, banked))
					relaxWalking(next, banked, from, cost);
			}
		}

		private void relaxWalking(int tile, BankVisitState banked, int from, int cost)
		{
			int node = space.node(tile);
			if (node >= 0 && space.stepAllowed(from / 2, node))
				relaxState(from, stateForNode(node, banked), cost, 1, null, PUSH_WALKING);
		}

		private void relaxBank(int node, BankVisitState banked, int from, int cost)
		{
			if (banked == BankVisitState.BANKED || !target.account().bankPathEnabled() || !space.isUsableBankNode(node)) return;
			// Every bank charges the same visit cost, so comparing arrival costs with bestBankCost
			// (an arrival cost too) still orders the banks correctly.
			int bankedCost = CostArithmetic.add(cost, target.account().bankVisitCost());
			if (bankedCost == CostArithmetic.INF) return;
			relaxState(from, stateForNode(node, BankVisitState.BANKED), bankedCost, 0, null, PUSH_BANKING);
			// With hubs (a start without every global castable) the banked hub of this tile's
			// capability casts them. Without, they are cast here, as far as this bank tile's own
			// wilderness level allows.
			if (capability == TeleportCapability.ALL)
			{
				TeleportCapability here = capabilityAt(space.tile(node));
				for (int i = 0; i < target.account().globalCount(here, BankVisitState.BANKED); i++)
				{
					int destination = target.account().globalDestination(here, BankVisitState.BANKED, i);
					if (!space.globalAllowed(here, destination)) continue;
					if (!optimized || cost <= bestBankCost[0])
						relaxTransport(from, BankVisitState.BANKED, bankedCost, destination, target.account().globalCost(here, BankVisitState.BANKED, i), target.account().globalTransport(here, BankVisitState.BANKED, i), PUSH_GLOBAL);
					else if (space.node(destination) >= 0)
						counters.bankGlobalSuppressed++;
				}
			}
		}

		private void relaxLocalTransports(int tile, BankVisitState banked, int from, int cost)
		{
			PreparedRoutingAccount.View view = target.account().localView(banked);
			int start = IntArrays.lowerBound(view.origins, tile);
			for (int i = start; i < view.destinations.length && view.origins[i] == tile; i++)
			{
				int node = space.node(view.destinations[i]);
				// Legacy checks the positional gates on a transport's destination node exactly like a
				// walked neighbour (crossing the wilderness ditch is a transport, and must not bypass
				// the avoid-wilderness gate), so apply them to the jump's landing tile.
				if (node < 0 || !space.stepAllowed(from / 2, node)) continue;
				relaxTransport(from, banked, cost, view.destinations[i], view.costs[i], view.transports[i], PUSH_LOCAL);
			}
		}

		private void relaxTransport(int from, BankVisitState banked, int cost, int destination, int stepCost,
			Transport transport, int pushKind)
		{
			counters.transportCandidates++;
			int node = space.node(destination);
			if (node >= 0) relaxState(from, stateForNode(node, banked), cost, stepCost, transport, pushKind);
		}

		private void relaxState(int from, int state, int cost, int stepCost, Transport transport, int pushKind)
		{
			int candidate = CostArithmetic.add(cost, stepCost);
			if (candidate == CostArithmetic.INF) return;
			if (pushKind == PUSH_WALKING) counters.walkingRelaxations++; else counters.transportRelaxations++;
			if (candidate >= best.get(state)) return;
			updateBestBank(state, candidate);
			int h = effectiveHeuristic(state, candidate);
			if (h == CostArithmetic.INF)
	{ counters.heuristicUnreachable++; return;
	}
			boolean newState = best.get(state) == CostArithmetic.INF;
			best.set(state, candidate); previous.set(state, from); transportWins.record(state, transport, candidate);
			push(state, candidate, priority(candidate, h, heuristicWeight), newState, pushKind);
			if (pushKind == PUSH_LOCAL || pushKind == PUSH_GLOBAL) counters.successfulTransportRelaxations++;
		}

		private void seedGlobals(int startState)
		{
			int count = target.account().globalCount(capability, BankVisitState.CARRIED);
			for (int i = 0; i < count; i++)
			{
				counters.transportCandidates++;
				int destination = target.account().globalDestination(capability, BankVisitState.CARRIED, i);
				// This duplicates the start-capability hub: the hub offers these transports again when
				// it pops, but seeding them here starts their states without a hub round-trip.
				if (!space.globalAllowed(capability, destination)) continue;
				int node = space.node(destination);
				if (node < 0) continue;
				int state = stateForNode(node, BankVisitState.CARRIED);
				int cost = target.account().globalCost(capability, BankVisitState.CARRIED, i);
				if (cost < best.get(state))
				{
					updateBestBank(state, cost);
					int h = effectiveHeuristic(state, cost);
					if (h == CostArithmetic.INF)
					{
						counters.heuristicUnreachable++;
						continue;
					}
					best.set(state, cost); previous.set(state, startState);
					transportWins.record(state, target.account().globalTransport(capability, BankVisitState.CARRIED, i), cost);
					push(state, cost, priority(cost, h, heuristicWeight), true, PUSH_GLOBAL);
					counters.successfulTransportRelaxations++;
		}
			}
		}

		private void activateGlobal(int tile, int from, BankVisitState banked, int cost)
		{
			TeleportCapability tileCapability = capabilityAt(tile);
			if (target.account().globalCount(tileCapability, banked) == 0) return;
			int state = hub(tileStates, tileCapability, banked);
			if (cost < best.get(state))
			{
				boolean newState = best.get(state) == CostArithmetic.INF;
				best.set(state, cost); previous.set(state, from);
				push(state, cost, cost, newState, PUSH_GLOBAL);
		}
		}

		private void relaxGlobalHub(int state, int cost)
		{
			TeleportCapability hubCap = hubCapability(tileStates, state);
			BankVisitState banked = ((state - tileStates) & 1) != 0 ? BankVisitState.BANKED : BankVisitState.CARRIED;
			// A hub stands for every tile in its wilderness band, so the capability doubles as the
			// source position legacy checks a global teleport against.
			int count = target.account().globalCount(hubCap, banked);
			for (int i = 0; i < count; i++)
			{
				counters.transportCandidates++;
				int destination = target.account().globalDestination(hubCap, banked, i);
				if (!space.globalAllowed(hubCap, destination)) continue;
				int node = space.node(destination);
				if (node < 0) continue;
				int stepCost = target.account().globalCost(hubCap, banked, i);
				int next = stateForNode(node, banked), candidate = CostArithmetic.add(cost, stepCost);
				if (candidate == CostArithmetic.INF) continue;
				counters.transportRelaxations++;
				if (candidate >= best.get(next)) continue;
				boolean newState = best.get(next) == CostArithmetic.INF;
				best.set(next, candidate); previous.set(next, state);
				transportWins.record(next, target.account().globalTransport(hubCap, banked, i), candidate);
				push(next, candidate, candidate, newState, PUSH_GLOBAL);
				counters.successfulTransportRelaxations++;
			}
		}

		private AStarRoute reconstruct(int start, int terminal)
		{
			ArrayList<PathStep> result = new ArrayList<>();
			int[] costs = new int[16];
			byte[] arrivals = new byte[16];
			int count = 0;
			for (int state = terminal; ; state = previous.get(state))
			{
				if (state >= tileStates) continue;
				if (count == costs.length)
				{
					costs = Arrays.copyOf(costs, count * 2);
					arrivals = Arrays.copyOf(arrivals, count * 2);
				}
				result.add(new PathStep(space.tile(state / 2),
					(state & 1) != 0 ? BankVisitState.BANKED : BankVisitState.CARRIED,
					transportWins.at(state, best.get(state))));
				costs[count] = state == start ? 0 : best.get(state);
				int from = state == start ? start : previous.get(state);
				arrivals[count++] = from < tileStates ? AStarRoute.FROM_STEP
					: AStarRoute.fromHub(hubCapability(tileStates, from));
				if (state == start) break;
			}
			java.util.Collections.reverse(result);
			int[] forwardCosts = new int[count];
			byte[] forwardArrivals = new byte[count];
			for (int i = 0; i < count; i++)
			{
				forwardCosts[i] = costs[count - 1 - i];
				forwardArrivals[i] = arrivals[count - 1 - i];
			}
			return new AStarRoute(result, forwardArrivals, forwardCosts);
		}

		private int heuristicValue(int state)
		{
			int[] page = space.heuristicPage(state);
			int slot = state & SearchSpace.HEURISTIC_PAGE_MASK;
			int cached = page[slot];
			if (cached != 0)
			{
				counters.heuristicCacheHits++;
				return cached == SearchSpace.CACHED_INF ? CostArithmetic.INF : cached - 1;
			}
			int node = state / 2;
			BankVisitState banked = (state & 1) != 0 ? BankVisitState.BANKED : BankVisitState.CARRIED;
			int value = space.isBase(node)
				? heuristic.estimateBaseNode(space.tile(node), banked, space.stat.routingComponent(node))
				: heuristic.estimate(space.tile(node), banked, space.components(node));
			page[slot] = value == CostArithmetic.INF ? SearchSpace.CACHED_INF : value + 1;
			return value;
		}

		private int effectiveHeuristic(int state, int cost)
		{
			BankVisitState banked = (state & 1) != 0 ? BankVisitState.BANKED : BankVisitState.CARRIED;
			int resolved;
			if (banked == BankVisitState.BANKED)
			{
				counters.heuristicEvaluations++;
				resolved = heuristicValue(state);
			}
			else
			{
				int unbanked = heuristicValue(state);
				counters.heuristicEvaluations++;
				if (!optimized || !space.bankGlobalRelevant() || cost <= bestBankCost[0])
					resolved = unbanked;
				else
				{
					int bankedHeuristic = heuristicValue(state | 1);
					counters.heuristicEvaluations++;
					counters.bankDominated++;
					resolved = bankedHeuristic == CostArithmetic.INF ? unbanked : Math.max(unbanked, bankedHeuristic);
				}
			}
			boolean allGlobalsActivated = restrictedHeuristic
				&& best.get(hub(tileStates, TeleportCapability.ALL, banked)) <= cost;
			if (restrictedHeuristic && (capabilityAt(space.tile(state / 2)) != TeleportCapability.ALL
				|| !allGlobalsActivated))
			{
				counters.restrictedHeuristicStates++;
				int restricted = Math.min(resolved, globalBounds[banked == BankVisitState.BANKED ? 1 : 0]);
				// Both infinite: no route from here reaches a target without a global teleport of this
				// layer (h), nor with one (every cast lands where h is infinite), so the state is pruned
				// like any other.
				if (restricted == CostArithmetic.INF) counters.restrictedHeuristicZeroes++;
				return restricted;
			}
			counters.normalHeuristicStates++;
			return resolved;
		}

		private void updateBestBank(int state, int cost)
		{
			if (optimized && (state & 1) == 0 && space.bankGlobalRelevant() && cost < bestBankCost[0]
				&& space.isUsableBankNode(state / 2))
			{
				bestBankCost[0] = cost;
				counters.bestBankUpdates++;
			}
		}

		private void push(int state, int cost, int priority, boolean uniqueState, int kind)
		{
			if (priority == CostArithmetic.INF) return;
			queue.push(priority, cost, state);
			counters.pqPushes++;
			if (kind == PUSH_WALKING) counters.walkingPqPushes++;
			else if (kind == PUSH_LOCAL) counters.localTransportPqPushes++;
			else if (kind == PUSH_GLOBAL) counters.globalPqPushes++;
			else if (kind == PUSH_BANKING) counters.bankingPqPushes++;
			if (queue.size() > counters.maxQueueSize) counters.maxQueueSize = queue.size();
			if (uniqueState) counters.uniqueStatesReached++;
		}

		private int[] computeGlobalBounds()
		{
			int[] result = {CostArithmetic.INF, CostArithmetic.INF};
			for (int layer = 0; layer < 2; layer++)
			{
				BankVisitState banked = layer != 0 ? BankVisitState.BANKED : BankVisitState.CARRIED;
				for (int i = 0; i < target.account().globalCount(banked); i++)
				{
					int node = space.node(target.account().globalDestination(banked, i));
					if (node >= 0)
						result[layer] = Math.min(result[layer], CostArithmetic.add(target.account().globalCost(banked, i),
							heuristicValue(stateForNode(node, banked))));
				}
			}
			return result;
		}
	}

	static int priority(int cost, int heuristic, double weight)
	{
		if (heuristic == CostArithmetic.INF) return CostArithmetic.INF;
		long weighted = Math.round(weight * heuristic);
		return weighted >= CostArithmetic.INF - cost ? CostArithmetic.INF - 1 : cost + (int) weighted;
	}

	static void validateHeuristicWeight(double weight)
	{
		if (!(weight > 0) || !Double.isFinite(weight))
			throw new IllegalArgumentException("heuristic weight must be positive and finite");
	}

	static int stateForNode(int node, BankVisitState banked)
	{
		return SiteGraph.stateId(node, banked);
	}

	private static boolean hasGlobals(PreparedRoutingAccount account)
	{
		// Every capability's globals are among ALL's.
		return account.allowTransports() && (account.globalCount(BankVisitState.CARRIED) != 0
			|| account.globalCount(BankVisitState.BANKED) != 0);
	}

	private static final int PUSH_INITIAL = 0;
	private static final int PUSH_WALKING = 1;
	private static final int PUSH_LOCAL = 2;
	private static final int PUSH_GLOBAL = 3;
	private static final int PUSH_BANKING = 4;
	private static final int PUSH_REKEY = 5;

	private static TeleportCapability capabilityAt(int tile)
	{
		return TeleportCapability.at(tile);
	}
	private static final TeleportCapability[] CAPABILITIES = TeleportCapability.values();
	private static final int HUB_STATES = CAPABILITIES.length * 2;

	/** The hub state casting the globals {@code capability} allows, in one bank layer. */
	private static int hub(int tileStates, TeleportCapability capability, BankVisitState banked)
	{
		return tileStates + capability.ordinal() * 2 + (banked == BankVisitState.BANKED ? 1 : 0);
	}
	private static TeleportCapability hubCapability(int tileStates, int hubState)
	{
		return CAPABILITIES[(hubState - tileStates) / 2];
	}


