	private static final class SearchSpace
	{
		private static final int STATUS_CLEAR = 1;
		private static final int STATUS_WILDERNESS = 2;
		private static final int STATUS_BLOCKED_REGION = 4;

		final RoutingStatic stat; final int[] extraTiles, extraSites; final int[][] extraComponents;
		final int baseCount, tileCount; private final PreparedRoutingAccount account;
		private SearchRestrictions restrictions = SearchRestrictions.none();
		/**
		 * Per-node gate status bits, computed on first ask: entering the wilderness or the blocked
		 * league region is asked about on every walking edge, so the lookups are memoised. Only
		 * allocated while a gate is active.
		 */
		private byte[] gateBits;
		static final int HEURISTIC_PAGE_BITS = 10;
		static final int HEURISTIC_PAGE_MASK = (1 << HEURISTIC_PAGE_BITS) - 1;
		/** Cache encoding of an infinite heuristic; other values are stored plus one, so 0 means absent. */
		static final int CACHED_INF = -1;
		/**
		 * Each tile state's heuristic, filled on first lookup. The heuristic depends only on the
		 * state, but the search asks for it at every improving relaxation, again when the state
		 * pops and for the banked twin of a bank-dominated state. Pages are allocated on first
		 * touch, so a search pays only for the regions it reaches.
		 */
		private int[][] heuristicPages;
		private SearchSpace(RoutingStatic stat, PreparedRoutingAccount account, int[] extraTiles,
			int[][] extraComponents, int[] extraSites)
	{ this.stat = stat; this.account = account; this.extraTiles = extraTiles; this.extraComponents = extraComponents;
		this.extraSites = extraSites; baseCount = stat.searchTileCount(); tileCount = baseCount + extraTiles.length;
	}
		static SearchSpace create(TargetOverlay target, int start, SearchRestrictions restrictions)
		{
			RoutingStatic stat = target.routingStatic(); int[] values = new int[stat.siteCount() + target.targetCount() + 1]; int count = 0;
			for (int site = 0; site < stat.siteCount(); site++) count = add(values, count, stat.siteTile(site), stat);
			for (int i = 0; i < target.targetCount(); i++) count = add(values, count, target.packedTarget(i), stat);
			count = add(values, count, start, stat);
			for (int i = 1; i < count; i++)
	{ int value = values[i], j = i - 1; while (j >= 0 && Integer.compareUnsigned(values[j], value) > 0) values[j + 1] = values[j--]; values[j + 1] = value;
	}
			int extraCount = 0; for (int i = 0; i < count; i++) if (stat.searchIndex(values[i]) < 0) values[extraCount++] = values[i];
			int[] extras = Arrays.copyOf(values, extraCount); int[][] components = new int[extraCount][];
			int[] sites = new int[extraCount];
			for (int i = 0; i < extraCount; i++)
	{ int tile = extras[i], site = stat.siteIndex(tile), targetIndex = target.targetIndex(tile); sites[i] = site;
		components[i] = targetIndex >= 0 ? target.componentsView(targetIndex) : site >= 0 ? stat.siteComponents(site) : stat.attachments(tile, target.collision());
	}
			SearchSpace space = new SearchSpace(stat, target.account(), extras, components, sites);
			space.restrictions = restrictions;
			if (restrictions.anyGate())
			{
				space.gateBits = new byte[space.tileCount];
			}
			return space;
		}
		private static int add(int[] values, int count, int value, RoutingStatic stat)
	{ if (stat.searchIndex(value) >= 0) return count; for (int i = 0; i < count; i++) if (values[i] == value) return count; values[count] = value; return count + 1;
	}
		int node(int tile)
	{ int base = stat.searchIndex(tile); if (base >= 0) return base; int extra = IntArrays.binarySearch(extraTiles, tile); return extra < 0 ? -1 : baseCount + extra;
	}
		int state(int tile, BankVisitState banked)
	{ return stateForNode(node(tile), banked);
	}
		int tile(int node)
	{ return node < baseCount ? stat.searchTile(node) : extraTiles[node - baseCount];
	}
		int[] components(int node)
	{ return extraComponents[node - baseCount];
	}
		int[] heuristicPage(int state)
		{
			if (heuristicPages == null) heuristicPages = new int[((tileCount * 2) >> HEURISTIC_PAGE_BITS) + 1][];
			int index = state >> HEURISTIC_PAGE_BITS;
			int[] page = heuristicPages[index];
			if (page == null)
			{
				page = new int[1 << HEURISTIC_PAGE_BITS];
				heuristicPages[index] = page;
			}
			return page;
		}
		boolean isBase(int node)
	{ return node < baseCount;
	}
		/** A bank in the world (static topology) that this account may use (prepared account). */
		boolean isUsableBankNode(int node)
	{ return isBankNode(node) && account.bankAccessible(tile(node));
	}
		boolean isBankNode(int node)
	{ return node < baseCount ? stat.isBankNode(node) : stat.isBankSite(extraSites[node - baseCount]);
	}
		boolean bankGlobalRelevant()
		{ return account.allowTransports() && account.bankPathEnabled();
		}
		boolean hasLocalOrigin(int tile, BankVisitState banked)
	{ PreparedRoutingAccount.View view = account.localView(banked); int index = IntArrays.lowerBound(view.origins, tile); return index < view.destinations.length && view.origins[index] == tile;
	}
		/** The node's wilderness/blocked-region status bits, computed on first ask. */
		private int gateStatus(int node)
		{
			int value = gateBits[node];
			if (value == 0)
			{
				int tile = tile(node);
				value = STATUS_CLEAR
					| (WildernessChecker.isInWilderness(tile) ? STATUS_WILDERNESS : 0)
					| (restrictions.inBlockedRegion(tile) ? STATUS_BLOCKED_REGION : 0);
				gateBits[node] = (byte) value;
			}
			return value;
		}
		/** Legacy's tile-to-tile gate: a step may not enter the wilderness or the blocked region. */
		boolean stepAllowed(int fromNode, int toNode)
		{
			if (gateBits == null) return true;
			int from = gateStatus(fromNode), to = gateStatus(toNode);
			return restrictions.stepAllowed((from & STATUS_WILDERNESS) != 0, (to & STATUS_WILDERNESS) != 0,
				(from & STATUS_BLOCKED_REGION) != 0, (to & STATUS_BLOCKED_REGION) != 0);
		}
		/** Whether a global cast with {@code capability} (the source band) may land on the tile. */
		boolean globalAllowed(TeleportCapability capability, int destination)
		{
			return restrictions.globalAllowed(capability, destination);
		}
	}
}

package shortestpath.pathfinder.astar;

import java.util.Arrays;
import lombok.Getter;
import lombok.experimental.Accessors;

/** Primitive duplicate-entry min-heap ordered by (priority, cost, state). */
public final class AStarMinHeap
{
	private int[] priorities, costs, states;
	@Getter @Accessors(fluent = true) private int size;
	private int poppedPriority, poppedCost, poppedState;

	public AStarMinHeap(int initialCapacity)
	{
		int capacity = Math.max(1, initialCapacity);
		priorities = new int[capacity];
		costs = new int[capacity];
		states = new int[capacity];
	}

	public boolean isEmpty()
	{
		return size == 0;
	}
	public int priority()
	{
		return poppedPriority;
	}
	public int cost()
	{
		return poppedCost;
	}
	public int state()
	{
		return poppedState;
	}

	public void push(int priority, int cost, int state)
	{
		CostArithmetic.validate(priority);
		CostArithmetic.validate(cost);
		if (priority == CostArithmetic.INF || cost == CostArithmetic.INF)
			throw new IllegalArgumentException("infinite heap entries are not searchable");
		if (size == states.length)
		{
			int capacity = states.length < 1_073_741_824 ? states.length * 2 : Integer.MAX_VALUE;
			priorities = Arrays.copyOf(priorities, capacity);
			costs = Arrays.copyOf(costs, capacity);
			states = Arrays.copyOf(states, capacity);
		}
		priorities[size] = priority;
		costs[size] = cost;
		states[size] = state;
		siftUp(size++);
	}

	public boolean poll()
	{
		if (size == 0)
			return false;
		poppedPriority = priorities[0];
		poppedCost = costs[0];
		poppedState = states[0];
		--size;
		if (size != 0)
		{
			priorities[0] = priorities[size];
			costs[0] = costs[size];
			states[0] = states[size];
			siftDown(0);
		}
		return true;
	}

	private void siftUp(int index)
	{
		int priority = priorities[index], cost = costs[index], state = states[index];
		while (index > 0)
		{
			int parent = (index - 1) >>> 1;
			if (compare(priority, cost, state, priorities[parent], costs[parent], states[parent]) >= 0)
				break;
			priorities[index] = priorities[parent];
			costs[index] = costs[parent];
			states[index] = states[parent];
			index = parent;
		}
		priorities[index] = priority;
		costs[index] = cost;
		states[index] = state;
	}

	private void siftDown(int index)
	{
		int priority = priorities[index], cost = costs[index], state = states[index];
		int half = size >>> 1;
		while (index < half)
		{
			int child = (index << 1) + 1;
			int right = child + 1;
			if (right < size && compare(priorities[right], costs[right], states[right], priorities[child], costs[child], states[child]) < 0)
				child = right;
			if (compare(priority, cost, state, priorities[child], costs[child], states[child]) <= 0)
				break;
			priorities[index] = priorities[child];
			costs[index] = costs[child];
			states[index] = states[child];
			index = child;
		}
		priorities[index] = priority;
		costs[index] = cost;
		states[index] = state;
	}

	private static int compare(int p1, int c1, int s1, int p2, int c2, int s2)
	{
		int result = Integer.compare(p1, p2);
		if (result != 0)
			return result;
		result = Integer.compare(c1, c2);
		return result != 0 ? result : Integer.compare(s1, s2);
	}
}

package shortestpath.pathfinder.astar;

import java.util.List;
import shortestpath.pathfinder.PathStep;
import lombok.Getter;
import lombok.experimental.Accessors;

/**
 * A reconstructed A* route: its steps, plus what the search knew about each of them that the
 * steps alone do not say. A step reached through a global-teleport hub records which hub, since
 * the hub is not a tile and does not appear among the steps; every step records the cost the
 * search reached it at.
 */
public final class AStarRoute
{
	/** The step was reached from the previous step directly: a walk, a bank visit or a transport. */
	public static final byte FROM_STEP = 0;
	/** The first hub arrival; the step is the destination of a teleport cast with capability {@code arrival - 1}. */
	private static final byte FROM_HUB = 1;

	@Getter @Accessors(fluent = true) private final List<PathStep> steps;
	private final byte[] arrivals;
	private final int[] costs;

	AStarRoute(List<PathStep> steps, byte[] arrivals, int[] costs)
	{
		if (arrivals.length != steps.size() || costs.length != steps.size())
			throw new IllegalArgumentException("route metadata does not match its steps");
		this.steps = List.copyOf(steps);
		this.arrivals = arrivals;
		this.costs = costs;
	}

	/** A route of plain steps with no search metadata: every step is reached from the previous one. */
	public static AStarRoute of(List<PathStep> steps, int[] costs)
	{
		return new AStarRoute(steps, new byte[steps.size()], costs.clone());
	}



	public int size()
	{
		return steps.size();
	}

	/** The arrival of a step reached through the hub casting the globals {@code capability} allows. */
	public static byte fromHub(TeleportCapability capability)
	{
		return (byte) (FROM_HUB + capability.ordinal());
	}

	/** The capability of the hub an arrival came through; {@code arrival} must not be {@link #FROM_STEP}. */
	public static TeleportCapability hubCapability(byte arrival)
	{
		return TeleportCapability.values()[arrival - FROM_HUB];
	}

	/** How step {@code index} was reached: {@link #FROM_STEP} or {@link #fromHub one of the hubs}. */
	public byte arrival(int index)
	{
		return arrivals[index];
	}

	/** The cost at which the search reached step {@code index}. */
	public int cost(int index)
	{
		return costs[index];
	}
}

package shortestpath.pathfinder.astar;

import java.util.*;
import lombok.*;
import lombok.experimental.Accessors;
import shortestpath.pathfinder.CollisionMap;

/**
 * Keeps A* routing preparation alive between queries, following the model's lifetimes:
 *
 * <pre>
 * static   RoutingStatic                 owned by the caller
 * account  SiteGraph                     reused while the routing fingerprint is unchanged
 * target   PreparedTarget                reused for the same target set while its SiteGraph and
 *                                        collision map are
 * search   AStarForwardSearch            per query
 * </pre>
 *
 * <p>The account key is the {@link PreparedRoutingAccount#fingerprint() routing fingerprint}
 * rather than object identity, because the plugin recompiles the account before every query even
 * when nothing routing-relevant changed. Changing the graph drops every prepared target.
 *
 * <p>Prepared targets keep the collision map they were built with and the forward search reads
 * it, so they are only reused with that same collision map instance.
 */
public final class AStarRoutingSession
{
	public static final int DEFAULT_TARGET_CAPACITY = 16;

	private final int targetCapacity;
	private final LinkedHashMap<TargetKey, PreparedTarget> targets;
	private SiteGraph graph;
	private CollisionMap targetCollision;

	public AStarRoutingSession()
	{
		this(DEFAULT_TARGET_CAPACITY);
	}

	public AStarRoutingSession(int targetCapacity)
	{
		if (targetCapacity < 1) throw new IllegalArgumentException("target capacity must be positive");
		this.targetCapacity = targetCapacity;
		this.targets = new LinkedHashMap<>(targetCapacity * 2, 0.75f, true);
	}

	/** The account-lifetime graph for {@code account}, rebuilt only when its fingerprint changes. */
	public synchronized Lookup<SiteGraph> graph(RoutingStatic stat, PreparedRoutingAccount account)
	{
		if (stat == null || account == null) throw new NullPointerException();
		if (graph != null && graph.routingStatic() == stat
			&& graph.preparedAccount().fingerprint() == account.fingerprint())
		{
			return new Lookup<>(graph, true);
		}
		graph = new SiteGraph(stat, account);
		targets.clear();
		targetCollision = null;
		return new Lookup<>(graph, false);
	}

	/** The prepared target for {@code packed}, reused while {@code graph} is the session's graph. */
	public Lookup<PreparedTarget> target(SiteGraph graph, CollisionMap collision, int packed)
	{
		return target(graph, collision, new int[] {packed});
	}

	/**
	 * The prepared target for the set {@code packedTargets} (order and duplicates do not matter),
	 * reused while {@code graph} is the session's graph.
	 */
	public synchronized Lookup<PreparedTarget> target(SiteGraph graph, CollisionMap collision, int[] packedTargets)
	{
		return target(graph, collision, new TargetKey(packedTargets, null));
	}

	/** Target identity includes the terminal layers; duplicate coordinates union their masks. */
	public synchronized Lookup<PreparedTarget> target(SiteGraph graph, CollisionMap collision, int[] packedTargets,
		int[] terminalLayers)
	{
		return target(graph, collision, new TargetKey(packedTargets, java.util.Objects.requireNonNull(terminalLayers)));
	}

	private Lookup<PreparedTarget> target(SiteGraph graph, CollisionMap collision, TargetKey key)
	{
		if (graph == null || collision == null) throw new NullPointerException();
		if (graph != this.graph)
			return new Lookup<>(PreparedTarget.prepare(graph, collision, key.states), false);
		if (collision != targetCollision)
		{
			targets.clear();
			targetCollision = collision;
		}
		PreparedTarget cached = targets.get(key);
		if (cached != null) return new Lookup<>(cached, true);
		PreparedTarget prepared = PreparedTarget.prepare(graph, collision, key.states);
		targets.put(key, prepared);
		for (Iterator<Map.Entry<TargetKey, PreparedTarget>> eldest = targets.entrySet().iterator();
			targets.size() > targetCapacity; )
		{
			eldest.next();
			eldest.remove();
		}
		return new Lookup<>(prepared, false);
	}

	/** Drops the prepared targets but keeps the account graph. */
	public synchronized void clearTargets()
	{
		targets.clear();
	}

	/** Drops every cached stage, e.g. when the static routing data is replaced. */
	public synchronized void clear()
	{
		graph = null;
		targets.clear();
		targetCollision = null;
	}

	public synchronized int cachedTargetCount()
	{
		return targets.size();
	}

	/** Unsigned tile coordinates and their two terminal-layer bits, sorted and duplicate-free. */
	@EqualsAndHashCode(onlyExplicitlyIncluded = true)
	private static final class TargetKey
	{
		@EqualsAndHashCode.Include
		private final long[] states;

		TargetKey(int[] packedTargets, int[] terminalLayers)
		{
			states = TargetOverlay.canonicalTargets(packedTargets, terminalLayers);
		}
	}

	/** A cached stage together with whether it was reused rather than built by this call. */
	@Getter
	@Accessors(fluent = true)
	@AllArgsConstructor(access = AccessLevel.PACKAGE)
	public static final class Lookup<T>
	{
		private final T value;
		private final boolean reused;
	}
}

package shortestpath.pathfinder.astar;

import java.util.*;
import java.util.function.IntPredicate;
import lombok.Getter;
import lombok.experimental.Accessors;
import shortestpath.*;
import shortestpath.pathfinder.*;

/**
 * Rewrites the walking legs of an A* route into the tiles the game's own walking takes when the
 * player clicks along them, without changing what the route costs or does.
 * <p>
 * The A* search minimises route cost only. Walking costs one tick in each of the eight
 * directions, so a walking leg usually has many equally cheap realisations, and the search
 * returns whichever its queue order found. The player does not walk tiles, though; they click a
 * tile, and the game runs a breadth-first search over a 128x128 window centred on them,
 * expanding neighbours in the order W, E, S, N, SW, SE, NW, NE, and walks the path traced back
 * from the clicked tile along each tile's first discoverer.
 * <p>
 * Each leg is walked end to end. A breadth-first search from the leg's start, in the game's order,
 * explores only the tiles that can lie on a walk of the leg's length (a tile's distance from the
 * start plus a straight walk to the end must fit), so the path traced back from the end through
 * each tile's first discoverer is the game's own walk to it, whatever detour the A* search took.
 * Every stretch of it is also the game's path between its own two tiles, so the player can click
 * along it. The clicks are placed afterwards: from each tile, the furthest one in a
 * {@link #CLICK_RADIUS minimap click's reach} whose path needs at most {@link #MAX_CHECKPOINTS}
 * checkpoint tiles, which the game would walk only up to the 25th corner. Steps the search's
 * {@link SearchRestrictions} gate off are not taken, since the game does not know those gates and
 * keeping the search's step preserves both the cost and the restriction. A leg no game walk
 * matches in length keeps the search's steps, and so does a step no click realises: the search's
 * own step onto a blocked transport origin, and the game's first step on its way off a blocked
 * tile a transport landed on. Legs keep their length and their first tile, so every other step of
 * the route, and the route's cost, are unchanged.
 * <p>
 * A leg need not end on the tile the search chose. The leg before a global teleport may end on any
 * tile the teleport can be cast from, and the leg before a transport on any origin of the same
 * action (the prepared account's local action class). It ends on the first such tile the game's
 * search discovers at exactly the leg's length, so the cost is unchanged; a qualifying tile nearer
 * than that is never taken, and without one the leg ends on the search's own end tile. Every other leg keeps its end tile: the
 * final destination, a bank visit, or a transport taken straight after banking.
 */
public final class AStarWalkCanonicalizer
{
	/** Roughly the reach of a minimap click, in tiles. */
	static final int CLICK_RADIUS = 35;

	/**
	 * Checkpoint tiles the client keeps for one click's walk: the direction-change corners of
	 * the path plus the destination. A click needing more is walked only up to the 25th
	 * checkpoint and the player stops short, so a click never spans more.
	 */
	private static final int MAX_CHECKPOINTS = 25;

	private static final int UNVISITED = -1;
	// The game's expansion order lives in GameWalkOrder.

	private final CollisionMap map;
	private final PreparedRoutingAccount account;
	private final SearchRestrictions restrictions;

	public AStarWalkCanonicalizer(CollisionMap map, PreparedRoutingAccount account)
	{
		this(map, account, SearchRestrictions.none());
	}

	/**
	 * @param restrictions the search's positional gates: the in-game paths must obey them too, or a
	 * leg could be drawn through tiles the forward search was not allowed to enter
	 */
	public AStarWalkCanonicalizer(CollisionMap map, PreparedRoutingAccount account, SearchRestrictions restrictions)
	{
		this.map = Objects.requireNonNull(map, "map");
		this.account = Objects.requireNonNull(account, "account");
		this.restrictions = Objects.requireNonNull(restrictions, "restrictions");
	}

	/** A rewritten route and the indices of its steps the player clicks to walk it. */
	public static final class Result
	{
		/** The route, as long as the search's and with the same steps outside its walking legs. */
		@Getter @Accessors(fluent = true) private final List<PathStep> path;
		/**
		 * Ascending indices into {@link #path()} of the tiles to click, one per click. Every
		 * index is a real click: the game's own walking path lands on that tile.
		 */
		@Getter @Accessors(fluent = true) private final List<Integer> clickPoints;
		/**
		 * Ascending indices into {@link #path()} of the steps no in-game click realises, such as
		 * onto a blocked transport origin or off a blocked landing; they are not clicks.
		 */
		@Getter @Accessors(fluent = true) private final List<Integer> keptStepIndices;

		Result(List<PathStep> path, List<Integer> clickPoints, List<Integer> keptStepIndices)
		{
			this.path = path;
			this.clickPoints = clickPoints;
			this.keptStepIndices = keptStepIndices;
		}
	}

	public Result canonicalize(AStarRoute route)
	{
		List<PathStep> steps = route.steps();
		int[] legBounds = new int[8];
		IntPredicate[] goals = new IntPredicate[4];
		int legs = 0;
		int legStart = 0;
		for (int i = 1; i <= steps.size(); i++)
		{
			if (i < steps.size() && isWalk(route, i)) continue;
			if (i - 1 > legStart)
			{
				if (legs == goals.length)
				{
					legBounds = Arrays.copyOf(legBounds, 4 * legs);
					goals = Arrays.copyOf(goals, 2 * legs);
				}
				legBounds[2 * legs] = legStart;
				legBounds[2 * legs + 1] = i - 1;
				goals[legs++] = goal(route, i - 1);
			}
			legStart = i;
		}
		return rewrite(steps, Arrays.copyOf(legBounds, 2 * legs), goals);
	}

	/**
	 * Rewrites the walking legs of {@code path}: leg {@code k} runs from step {@code legBounds[2k]}
	 * to step {@code legBounds[2k + 1]}, and its steps are single-tile walking moves. Every leg
	 * keeps its end tile.
	 */
	Result rewrite(List<PathStep> path, int[] legBounds)
	{
		return rewrite(path, legBounds, new IntPredicate[legBounds.length / 2]);
	}

	/** As above, with leg {@code k} free to end on any tile {@code goals[k]} accepts; null keeps its end. */
	private Result rewrite(List<PathStep> path, int[] legBounds, IntPredicate[] goals)
	{
		List<PathStep> rewritten = new ArrayList<>(path);
		List<Integer> clicks = new ArrayList<>();
		List<Integer> kept = new ArrayList<>();
		for (int leg = 0; leg < legBounds.length / 2; leg++)
			rewriteLeg(rewritten, legBounds[2 * leg], legBounds[2 * leg + 1], goals[leg], clicks, kept);
		return new Result(List.copyOf(rewritten), List.copyOf(clicks), List.copyOf(kept));
	}

	/** Whether step {@code index} is a walking move from the previous step, as the A* search walks. */
	private boolean isWalk(AStarRoute route, int index)
	{
		if (route.arrival(index) != AStarRoute.FROM_STEP) return false;
		PathStep from = route.steps().get(index - 1), to = route.steps().get(index);
		// A transport can land one tile away; its edge paid the transport's duration, not a walk
		// tick, so it must not be folded into a walking leg.
		if (to.getTransport() != null) return false;
		if (from.getBankVisitState() != to.getBankVisitState()) return false;
		int a = from.getPackedPosition(), b = to.getPackedPosition();
		int plane = WorldPointUtil.unpackWorldPlane(a);
		if (plane != WorldPointUtil.unpackWorldPlane(b)) return false;
		int ax = WorldPointUtil.unpackWorldX(a), ay = WorldPointUtil.unpackWorldY(a);
		int bx = WorldPointUtil.unpackWorldX(b), by = WorldPointUtil.unpackWorldY(b);
		int dx = bx - ax, dy = by - ay;
		if (Math.max(Math.abs(dx), Math.abs(dy)) != 1) return false;
		if (map.isBlocked(ax, ay, plane))
		{
			for (int next : map.ordinaryWalkingNeighbors(a))
				if (next == b) return true;
			return false;
		}
		int direction = direction(dx, dy);
		if ((map.ordinaryWalkingMask(a) & 1 << GameWalkOrder.ORDER_BITS[direction]) != 0) return true;
		// The A* search also steps onto a blocked transport origin next to it, to take the transport.
		return direction < 4 && map.isBlocked(bx, by, plane) && hasLocalOrigin(b, from.getBankVisitState());
	}

	/**
	 * The tiles the leg ending at step {@code end} may end on instead of there, given the route's
	 * next action; {@code null} when it has to end where it does.
	 */
	private IntPredicate goal(AStarRoute route, int end)
	{
		List<PathStep> steps = route.steps();
		PathStep last = steps.get(end);
		int tile = last.getPackedPosition();
		if (end + 1 == steps.size()) return null;
		byte arrival = route.arrival(end + 1);
		if (arrival != AStarRoute.FROM_STEP)
		{
			// A global teleport: castable anywhere its hub's capability is.
			TeleportCapability capability = AStarRoute.hubCapability(arrival);
			return TeleportCapability.at(tile).allows(capability)
				? other -> TeleportCapability.at(other).allows(capability) : null;
		}
		PathStep next = steps.get(end + 1);
		// A bank visit, or a transport taken with banked items straight after it, stays where it is.
		if (next.getBankVisitState() != last.getBankVisitState()) return null;
		int[] origins = actionOrigins(tile, next.getPackedPosition(), route.cost(end + 1) - route.cost(end),
			last.getBankVisitState());
		return origins == null ? null : other -> contains(origins, other);
	}

	private static boolean contains(int[] values, int value)
	{
		for (int candidate : values)
			if (candidate == value) return true;
		return false;
	}

	/**
	 * The origins of the local transport action from {@code origin} to {@code destination} that cost
	 * {@code cost}, or {@code null} unless exactly one action class matches.
	 */
	private int[] actionOrigins(int origin, int destination, int cost, BankVisitState banked)
	{
		PreparedRoutingAccount.View view = account.localView(banked);
		int actionClass = Integer.MIN_VALUE;
		for (int i = IntArrays.lowerBound(view.origins, origin); i < view.destinations.length && view.origins[i] == origin; i++)
		{
			if (view.destinations[i] != destination || view.costs[i] != cost) continue;
			if (actionClass != Integer.MIN_VALUE && actionClass != view.actionClasses[i]) return null;
			actionClass = view.actionClasses[i];
		}
		if (actionClass == Integer.MIN_VALUE) return null;
		PrimitiveIntList origins = new PrimitiveIntList(4);
		for (int i = 0; i < view.destinations.length; i++)
		{
			if (view.actionClasses[i] != actionClass) continue;
			origins.add(view.origins[i]);
		}
		return origins.column(1, 0);
	}

	private boolean hasLocalOrigin(int tile, BankVisitState banked)
	{
		PreparedRoutingAccount.View view = account.localView(banked);
		int index = IntArrays.lowerBound(view.origins, tile);
		return index < view.destinations.length && view.origins[index] == tile;
	}

	private static int direction(int dx, int dy)
	{
		for (int i = 0; i < 8; i++)
			if (GameWalkOrder.ORDER_DX[i] == dx && GameWalkOrder.ORDER_DY[i] == dy) return i;
		throw new IllegalArgumentException("not a walking move: " + dx + "," + dy);
	}

	/**
	 * Replaces {@code leg[from + 1..to]} by the game's walk, appending the index of each click along
	 * it to {@code clicks} and the index of each step the game does not walk to {@code kept}. A
	 * {@code goal} lets the leg end on another tile than {@code leg[to]}.
	 */
	private void rewriteLeg(List<PathStep> leg, int from, int to, IntPredicate goal, List<Integer> clicks,
		List<Integer> kept)
	{
		BankVisitState banked = leg.get(from).getBankVisitState();
		int start = leg.get(from).getPackedPosition();
		int plane = WorldPointUtil.unpackWorldPlane(start);
		// The search may cross a blocked tile the game's search cannot, so the game's walk to the leg's
		// end would not exist from before it: each side is rewritten on its own around the kept step.
		for (int k = from + 1; k < to; k++)
		{
			int tile = leg.get(k).getPackedPosition();
			if (!map.isBlocked(WorldPointUtil.unpackWorldX(tile), WorldPointUtil.unpackWorldY(tile), plane)) continue;
			if (k - 1 > from) rewriteLeg(leg, from, k - 1, null, clicks, kept);
			kept.add(k);
			rewriteLeg(leg, k, to, goal, clicks, kept);
			return;
		}
		int endTile = leg.get(to).getPackedPosition();
		// The step onto a blocked transport origin is the search's own: the game does not walk it.
		boolean blockedEnd = map.isBlocked(WorldPointUtil.unpackWorldX(endTile), WorldPointUtil.unpackWorldY(endTile), plane);
		int last = blockedEnd ? to - 1 : to;
		if (last > from)
		{
			if (walk(leg, from, last, blockedEnd ? null : goal, banked, plane))
			{
				// A transport may land on a blocked tile: the game walks off it, but is not clicked from it.
				int first = from;
				if (map.isBlocked(WorldPointUtil.unpackWorldX(start), WorldPointUtil.unpackWorldY(start), plane)) kept.add(++first);
				clicksAlong(leg, first, last, clicks);
			}
			else
			{
				// No game walk has the leg's length: the search's own steps stand.
				for (int k = from + 1; k <= last; k++) kept.add(k);
			}
		}
		if (blockedEnd) kept.add(to);
	}

	/**
	 * Walks {@code leg[from..last]} the way the game's search would from its start to its end: a
	 * breadth-first search in the game's order whose first-discoverer path back from the end is the
	 * game's walk. Only tiles that can lie on a walk of the leg's length are explored, so the end
	 * is found at exactly that length or the leg keeps its steps (returns false). With a
	 * {@code goal}, the end is the first tile it accepts that the search discovers at that length.
	 */
	private boolean walk(List<PathStep> leg, int from, int last, IntPredicate goal, BankVisitState banked, int plane)
	{
		int length = last - from;
		int sx = WorldPointUtil.unpackWorldX(leg.get(from).getPackedPosition());
		int sy = WorldPointUtil.unpackWorldY(leg.get(from).getPackedPosition());
		int ex = WorldPointUtil.unpackWorldX(leg.get(last).getPackedPosition());
		int ey = WorldPointUtil.unpackWorldY(leg.get(last).getPackedPosition());
		int side = 2 * length + 1, ox = sx - length, oy = sy - length;
		PagedSearchArray distance = new PagedSearchArray(side * side, UNVISITED);
		PagedSearchArray parent = new PagedSearchArray(side * side, UNVISITED);
		int start = length * side + length, found = -1;
		int[] queue = new int[256];
		int head = 0, tail = 0;
		distance.set(start, 0);
		queue[tail++] = start;
		while (head < tail && found < 0)
		{
			int at = queue[head++];
			int steps = distance.get(at);
			if (steps >= length) break;
			int x = ox + at % side, y = oy + at / side;
			int packed = WorldPointUtil.packWorldPoint(x, y, plane);
			int mask = map.ordinaryWalkingMask(packed);
			// A blocked start is walked off as the A* search does.
			if (at == start)
				for (int next : map.ordinaryWalkingNeighbors(packed))
					mask |= 1 << GameWalkOrder.ORDER_BITS[direction(WorldPointUtil.unpackWorldX(next) - x,
						WorldPointUtil.unpackWorldY(next) - y)];
			for (int i = 0; i < GameWalkOrder.ORDER_BITS.length && found < 0; i++)
			{
				if ((mask & (1 << GameWalkOrder.ORDER_BITS[i])) == 0) continue;
				int nx = x + GameWalkOrder.ORDER_DX[i], ny = y + GameWalkOrder.ORDER_DY[i];
				int next = (ny - oy) * side + nx - ox;
				int nextPacked = WorldPointUtil.packWorldPoint(nx, ny, plane);
				if (distance.get(next) != UNVISITED
					|| goal == null && steps + 1 + Math.max(Math.abs(nx - ex), Math.abs(ny - ey)) > length
					|| !restrictions.stepAllowed(packed, nextPacked))
				{
					continue;
				}
				distance.set(next, steps + 1);
				parent.set(next, at);
				if (goal == null ? nx == ex && ny == ey : steps + 1 == length && goal.test(nextPacked)) found = next;
				if (tail == queue.length) queue = Arrays.copyOf(queue, 2 * tail);
				queue[tail++] = next;
			}
		}
		if (found < 0) found = (ey - oy) * side + ex - ox;
		if (distance.get(found) != length) return false;
		for (int i = last, at = found; i > from; i--, at = parent.get(at))
			leg.set(i, new PathStep(WorldPointUtil.packWorldPoint(ox + at % side, oy + at / side, plane), banked));
		return true;
	}

	/**
	 * Appends the clicks along {@code leg[from..last]}, a walk the game takes: from each tile, the
	 * furthest one within a minimap click's reach whose path needs at most {@link #MAX_CHECKPOINTS}
	 * checkpoint tiles (its direction-change corners plus the destination), or the game would stop
	 * short of the click.
	 */
	private static void clicksAlong(List<PathStep> leg, int from, int last, List<Integer> clicks)
	{
		for (int at = from; at < last; )
		{
			int x = WorldPointUtil.unpackWorldX(leg.get(at).getPackedPosition());
			int y = WorldPointUtil.unpackWorldY(leg.get(at).getPackedPosition());
			int best = at + 1, turns = 0, previousDx = 0, previousDy = 0;
			for (int k = at + 1; k <= last; k++)
			{
				int tx = WorldPointUtil.unpackWorldX(leg.get(k).getPackedPosition());
				int ty = WorldPointUtil.unpackWorldY(leg.get(k).getPackedPosition());
				int dx = tx - WorldPointUtil.unpackWorldX(leg.get(k - 1).getPackedPosition());
				int dy = ty - WorldPointUtil.unpackWorldY(leg.get(k - 1).getPackedPosition());
				if (k > at + 1 && (dx != previousDx || dy != previousDy)) turns++;
				if (turns + 1 > MAX_CHECKPOINTS || (tx - x) * (tx - x) + (ty - y) * (ty - y) > CLICK_RADIUS * CLICK_RADIUS) break;
				previousDx = dx;
				previousDy = dy;
				best = k;
			}
			clicks.add(best);
			at = best;
		}
	}
}

package shortestpath.pathfinder.astar;

import java.io.*;
import java.nio.*;
import java.nio.charset.StandardCharsets;
import java.util.Arrays;
import shortestpath.Util;

/**
 * The collision-derived half of the A* routing data, stored as {@code routing-components.bin}: a
 * routing component id for every walkable tile of the collision map, plus the separator crossings
 * between components.
 *
 * <p>Runs are maximal stretches of consecutive packed tiles that share one routing component id,
 * ascending in unsigned packed order and at most 65,535 tiles long. Ids are numbered from 1 in order
 * of each component's first tile, over all walkable tiles, with the valid separator cuts blocked.
 * Natural components (walking edges only) are not stored: they are the routing components joined
 * through the crossings.
 *
 * <p>Format: the 8-byte magic, then the version as an unsigned base-128 varint (least-significant
 * group first, each in its shortest form and within 32 bits, as are all varints below), then the
 * big-endian 64-bit {@link shortestpath.pathfinder.CollisionMap#fingerprint() fingerprint} of the
 * collision map the layer was generated from, then the run count and the crossing int count as
 * varints; then three columns of run-count varints (run length minus one, the gap from the previous
 * run's end with the first gap measured from 0 in unsigned 32-bit arithmetic, and the routing
 * component id); then the crossings as big-endian 32-bit packed tiles in (from, to) pairs. The
 * fingerprint and the crossings are big-endian, unlike the little-endian {@code routing-cuts.bin}.
 *
 * <p>The reader rejects malformed and truncated files: a wrong magic or version, non-canonical or
 * over-wide varints, counts larger than the bytes left, runs outside the tile range or longer than
 * 65,535 tiles, component ids outside 1..run count, and trailing bytes. It does not check that the
 * crossings are sorted and distinct, that adjacent runs have different ids, or that ids are
 * numbered in first-tile order: the generator produces that shape and the loader does not depend on
 * it. Whether the layer matches the collision map is checked by {@link RoutingStaticLoader} (the
 * fingerprint, then every crossing and reachable tile) and, for the packaged file, by the
 * freshness test.
 */
final class ComponentLayer
{
	static final String RESOURCE = "/routing-components.bin";
	static final byte[] MAGIC = "RSPCOMP\0".getBytes(StandardCharsets.US_ASCII);
	static final int VERSION = 2;

	/** {@link shortestpath.pathfinder.CollisionMap#fingerprint()} of the map the layer was generated from. */
	final long fingerprint;
	final int[] starts;
	final char[] lengths;
	final int[] ids;
	final int[] crossings;

	ComponentLayer(long fingerprint, int[] starts, char[] lengths, int[] ids, int[] crossings)
	{
		this.fingerprint = fingerprint;
		this.starts = starts;
		this.lengths = lengths;
		this.ids = ids;
		this.crossings = crossings;
	}

	static ComponentLayer read(InputStream stream) throws IOException
	{
		if (stream == null) throw new IOException("missing " + RESOURCE);
		ByteBuffer in = ByteBuffer.wrap(Util.readAllBytes(stream));
		try
		{
			byte[] magic = new byte[MAGIC.length];
			in.get(magic);
			if (!Arrays.equals(magic, MAGIC)) throw new IOException("wrong magic in " + RESOURCE);
			int version = varint(in);
			if (version != VERSION) throw new IOException("unsupported version " + version + " of " + RESOURCE);
			long fingerprint = in.getLong();
			int runs = varint(in);
			int crossings = varint(in);
			// Every count is checked against the bytes left before anything is sized from it.
			if (runs < 0 || runs > in.remaining() / 3 || crossings < 0 || (crossings & 1) != 0
				|| (long) crossings * 4 > in.remaining())
				throw new IOException("bad counts in " + RESOURCE);
			ComponentLayer layer = new ComponentLayer(fingerprint, new int[runs], new char[runs], new int[runs],
				new int[crossings]);
			for (int i = 0; i < runs; i++)
			{
				int length = varint(in) + 1;
				if (length < 1 || length > Character.MAX_VALUE) throw new IOException("bad run length in " + RESOURCE);
				layer.lengths[i] = (char) length;
			}
			long end = 0;
			for (int i = 0; i < runs; i++)
			{
				long start = end + Integer.toUnsignedLong(varint(in));
				end = start + layer.lengths[i];
				if (end > 1L << 32) throw new IOException("run " + i + " leaves the tile range of " + RESOURCE);
				layer.starts[i] = (int) start;
			}
			for (int i = 0; i < runs; i++)
			{
				layer.ids[i] = varint(in);
				if (layer.ids[i] < 1 || layer.ids[i] > runs) throw new IOException("bad component id in " + RESOURCE);
			}
			for (int i = 0; i < crossings; i++)
				layer.crossings[i] = in.getInt();
			if (in.hasRemaining()) throw new IOException("trailing bytes in " + RESOURCE);
			return layer;
		}
		catch (BufferUnderflowException error)
		{
			throw new IOException("truncated " + RESOURCE, error);
		}
	}

	private static int varint(ByteBuffer in) throws IOException
	{
		int value = 0;
		for (int shift = 0; shift < 35; shift += 7)
		{
			byte next = in.get();
			if (shift == 28 && (next & 0x70) != 0) throw new IOException("varint above 32 bits in " + RESOURCE);
			value |= (next & 0x7f) << shift;
			if (next >= 0)
			{
				if (next == 0 && shift > 0) throw new IOException("non-canonical varint in " + RESOURCE);
				return value;
			}
		}
		throw new IOException("over-long varint in " + RESOURCE);
	}

	/** The routing component of a tile, or 0 when no run covers it. */
	int component(int tile)
	{
		int low = 0, high = starts.length - 1;
		while (low <= high)
		{
			int middle = (low + high) >>> 1;
			if (Integer.compareUnsigned(tile, starts[middle]) < 0) high = middle - 1;
			else if (Integer.compareUnsigned(tile - starts[middle], lengths[middle]) < 0) return ids[middle];
			else low = middle + 1;
		}
		return 0;
	}
}

package shortestpath.pathfinder.astar;

/**
 * Shared cost arithmetic for the A* pathfinder.
 */
public final class CostArithmetic
{
	public static final int INF = Integer.MAX_VALUE;

	private CostArithmetic()
	{
	}

	public static int validate(int cost)
	{
		if (cost < 0)
		{
			throw new IllegalArgumentException("Cost must not be negative: " + cost);
		}
		return cost;
	}

	public static int add(int left, int right)
	{
		validate(left);
		validate(right);
		if (left == INF || right == INF || left > INF - right)
		{
			return INF;
		}
		return left + right;
	}

	public static int twice(int cost)
	{
		validate(cost);
		return cost == INF || cost > INF / 2 ? INF : cost * 2;
	}

	public static int halve(int cost)
	{
		validate(cost);
		return cost == INF ? INF : cost / 2;
	}
}

package shortestpath.pathfinder.astar;

import java.util.Arrays;
import shortestpath.*;

/**
 * Exact walking distances between the sites of each small routing component.
 *
 * <p>The sparse walking network joins a component's sites by Chebyshev distance, which a winding
 * component (a dungeon corridor, a walled town) can undercut several times over. Reverse labels
 * then make a site at one end look almost as close to the target as one at the other, and the
 * forward search floods everything reachable through transports before the gap is closed. For a
 * component with at most {@link #MAX_SITES} sites this class walks from every site over the
 * component's own tiles and keeps the site-pair distances instead; the network joins those
 * components' sites by them in place of a Steiner tree.
 *
 * <p>Why a walk inside the component is a lower bound: routing components are only left by
 * crossing a cut, whose endpoints are sites, so a walk between two sites either stays in the
 * component or passes through further sites, whose own edges price the rest. Each distance is
 * also kept at least the Chebyshev distance it replaces, and the shorter of the two directions.
 *
 * <p>Larger components (the Wilderness, the open surface) keep their trees: their pair counts grow
 * quadratically, and they wind less. An edge is left out when a path through a third site of the
 * component is no longer, so the network's distances equal the full pair table's.
 */
final class ExactWalks
{
	/** The most sites a component may have for its sites to be joined by exact walks. */
	static final int MAX_SITES = 256;
	private static final int[] DX = {0, 1, 1, 1, 0, -1, -1, -1};
	private static final int[] DY = {1, 1, 0, -1, -1, -1, 0, 1};

	private final boolean[] exact;
	/** Per component: its kept edges as (site, site, distance) triples, or {@code null}. */
	private final int[][] edges;
	private final int edgeCount;

	private ExactWalks(boolean[] exact, int[][] edges, int edgeCount)
	{
		this.exact = exact;
		this.edges = edges;
		this.edgeCount = edgeCount;
	}

	static ExactWalks build(RoutingStatic stat)
	{
		return build(stat, MAX_SITES);
	}

	static ExactWalks build(RoutingStatic stat, int maxSites)
	{
		int componentCount = stat.routingComponentCount();
		boolean[] exact = new boolean[componentCount];
		for (int component = 0; component < componentCount; component++)
		{
			int sites = stat.componentSiteCount(component);
			exact[component] = sites >= 2 && sites <= maxSites;
		}
		int[][] tiles = componentTiles(stat, exact);
		int[] local = new int[stat.searchTileCount()];
		Arrays.fill(local, -1);
		int[][] edges = new int[componentCount][];
		int edgeCount = 0;
		for (int component = 0; component < componentCount; component++)
		{
			if (!exact[component]) continue;
			int[] sites = stat.componentSites(component);
			int[][] distance = pairDistances(stat, sites, tiles[component], local);
			edges[component] = keptEdges(sites, distance);
			edgeCount += edges[component].length / 3;
		}
		return new ExactWalks(exact, edges, edgeCount);
	}

	/** Whether the component's sites are joined by exact walks rather than a Steiner tree. */
	boolean isExact(int component)
	{
		return exact[component];
	}

	/** The component's kept edges as (site, site, distance) triples. */
	int[] edges(int component)
	{
		return edges[component];
	}

	int edgeCount()
	{
		return edgeCount;
	}

	int exactComponentCount()
	{
		int count = 0;
		for (boolean value : exact)
			if (value) count++;
		return count;
	}

	/**
	 * The full site-pair table of one component, indexed like {@link RoutingStatic#componentSites},
	 * with {@link CostArithmetic#INF} for pairs that cannot walk to each other inside it.
	 */
	static int[][] pairDistances(RoutingStatic stat, int component)
	{
		boolean[] only = new boolean[stat.routingComponentCount()];
		only[component] = true;
		int[] local = new int[stat.searchTileCount()];
		Arrays.fill(local, -1);
		return pairDistances(stat, stat.componentSites(component), componentTiles(stat, only)[component], local);
	}

	/** Every chosen component's search tiles, ascending. */
	private static int[][] componentTiles(RoutingStatic stat, boolean[] chosen)
	{
		int[] counts = new int[chosen.length];
		for (int node = 0; node < stat.searchTileCount(); node++)
			if (chosen[stat.routingComponent(node)]) counts[stat.routingComponent(node)]++;
		int[][] tiles = new int[chosen.length][];
		for (int component = 0; component < chosen.length; component++)
			if (chosen[component]) tiles[component] = new int[counts[component]];
		int[] fill = new int[chosen.length];
		for (int node = 0; node < stat.searchTileCount(); node++)
		{
			int component = stat.routingComponent(node);
			if (chosen[component]) tiles[component][fill[component]++] = node;
		}
		return tiles;
	}

	/**
	 * One forward walk from each site over the component's tiles, stopping once every site is
	 * reached. A site off the search tiles (a blocked transport origin) is walked from and to
	 * through its neighbours in the component. {@code local} must be all -1, and is again after.
	 */
	private static int[][] pairDistances(RoutingStatic stat, int[] sites, int[] tiles, int[] local)
	{
		for (int i = 0; i < tiles.length; i++) local[tiles[i]] = i;
		int k = sites.length;
		int[][] ends = new int[k][];
		boolean[] target = new boolean[tiles.length];
		int targetCount = 0;
		for (int i = 0; i < k; i++)
		{
			ends[i] = siteTiles(stat, stat.siteTile(sites[i]), local);
			for (int end : ends[i])
			{
				if (!target[end]) targetCount++;
				target[end] = true;
			}
		}
		int[] distance = new int[tiles.length], seen = new int[tiles.length], queue = new int[tiles.length];
		int[][] walk = new int[k][k];
		for (int i = 0; i < k; i++)
		{
			int mark = i + 1, head = 0, tail = 0, remaining = targetCount;
			for (int end : ends[i])
			{
				if (seen[end] == mark) continue;
				seen[end] = mark;
				distance[end] = 0;
				queue[tail++] = end;
				if (target[end]) remaining--;
			}
			while (head < tail && remaining > 0)
			{
				int current = queue[head++], node = tiles[current];
				int mask = stat.walkingMask(node), next = distance[current] + 1;
				for (int bit = 0; bit < 8; bit++)
				{
					if ((mask & (1 << bit)) == 0) continue;
					int to = stat.walkSuccessor(node, bit);
					if (to < 0 || to >= local.length || local[to] < 0 || seen[local[to]] == mark) continue;
					seen[local[to]] = mark;
					distance[local[to]] = next;
					queue[tail++] = local[to];
					if (target[local[to]]) remaining--;
				}
			}
			for (int j = 0; j < k; j++)
			{
				int best = CostArithmetic.INF;
				for (int end : ends[j])
					if (seen[end] == mark) best = Math.min(best, distance[end]);
				walk[i][j] = best;
			}
		}
		for (int tile : tiles) local[tile] = -1;

		int[][] result = new int[k][k];
		for (int i = 0; i < k; i++)
		{
			for (int j = 0; j < k; j++)
			{
				int best = Math.min(walk[i][j], walk[j][i]);
				result[i][j] = i == j ? 0 : best == CostArithmetic.INF ? best
					: Math.max(best, WorldPointUtil.distanceBetween(stat.siteTile(sites[i]), stat.siteTile(sites[j])));
			}
		}
		return result;
	}

	/** The component tiles a site is walked from and to: its own, else its neighbours'. */
	private static int[] siteTiles(RoutingStatic stat, int packed, int[] local)
	{
		int node = stat.searchIndex(packed);
		if (node >= 0 && local[node] >= 0) return new int[] {local[node]};
		int x = WorldPointUtil.unpackWorldX(packed), y = WorldPointUtil.unpackWorldY(packed);
		int plane = WorldPointUtil.unpackWorldPlane(packed);
		int[] result = new int[8];
		int count = 0;
		for (int bit = 0; bit < 8; bit++)
		{
			int neighbour = stat.searchIndex(WorldPointUtil.packWorldPoint(x + DX[bit], y + DY[bit], plane));
			if (neighbour >= 0 && local[neighbour] >= 0) result[count++] = local[neighbour];
		}
		return Arrays.copyOf(result, count);
	}

	/**
	 * The pairs to keep as edges: every finite pair but those a path through a third site matches.
	 * Distances between distinct sites are positive, so each dropped edge is replaced by strictly
	 * shorter kept ones, and shortest paths over the kept edges equal the table.
	 */
	private static int[] keptEdges(int[] sites, int[][] distance)
	{
		int k = sites.length;
		PrimitiveIntList result = new PrimitiveIntList(3 * k);
		for (int i = 0; i < k; i++)
		{
			for (int j = i + 1; j < k; j++)
			{
				if (distance[i][j] == CostArithmetic.INF) continue;
				boolean redundant = false;
				for (int m = 0; m < k && !redundant; m++)
					redundant = m != i && m != j && CostArithmetic.add(distance[i][m], distance[m][j]) <= distance[i][j];
				if (redundant) continue;
				result.add(sites[i]);
				result.add(sites[j]);
				result.add(distance[i][j]);
			}
		}
		return result.column(1, 0);
	}
}

package shortestpath.pathfinder.astar;

import shortestpath.pathfinder.CollisionMap;

/**
 * The order the game's own walking expands a tile's neighbours — W, E, S, N, SW, SE, NW, NE —
 * as the {@link CollisionMap#ordinaryWalkingMask} bit and step delta of each direction. Used by
 * {@link AStarWalkCanonicalizer}, which would silently disagree with the game if these tables
 * were wrong; its test re-derives them on purpose, to check against an independent copy.
 * Package-private: the arrays are mutable, so they are not exposed to callers.
 */
final class GameWalkOrder
{
	// CollisionMap.ordinaryWalkingMask bits (0-N, 1-NE, 2-E, 3-SE, 4-S, 5-SW, 6-W, 7-NW) in the
	// game's expansion order W, E, S, N, SW, SE, NW, NE; the first four are cardinal.
	static final int[] ORDER_BITS = {6, 2, 4, 0, 5, 3, 7, 1};
	static final int[] ORDER_DX = {-1, 1, 0, 0, -1, 1, -1, 1};
	static final int[] ORDER_DY = {0, 0, -1, 1, -1, -1, 1, 1};

	private GameWalkOrder()
	{
	}
}

package shortestpath.pathfinder.astar;

import shortestpath.pathfinder.BankVisitState;

/**
 * Whether reaching a target tile in a bank layer finishes a search. The prepared target and its
 * heuristic count every target tile in both layers; a search may accept fewer of those states, for
 * a target whose items are only held after a bank visit. Accepting fewer states only removes ways
 * to finish, so the prepared heuristic still never over-estimates and the target can be reused.
 */
@FunctionalInterface
public interface GoalTest
{
	boolean accepts(int tile, BankVisitState banked);
}

package shortestpath.pathfinder.astar;

/** Unsigned-ordered primitive-array lookups shared by the astar structures. */
final class IntArrays
{
	private IntArrays()
	{
	}

	static boolean contains(int[] values, int target)
	{
		return contains(values, 0, values.length, target);
	}

	static boolean contains(int[] values, int start, int end, int target)
	{
		for (int i = start; i < end; i++)
			if (values[i] == target)
				return true;
		return false;
	}

	static int binarySearch(int[] values, int target)
	{
		int low = 0, high = values.length - 1;
		while (low <= high)
		{
			int middle = low + (high - low) / 2;
			int compare = Integer.compareUnsigned(values[middle], target);
			if (compare == 0) return middle;
			if (compare < 0) low = middle + 1;
			else high = middle - 1;
		}
		return -1;
	}

	static int lowerBound(int[] values, int target)
	{
		int low = 0, high = values.length;
		while (low < high)
		{
			int middle = low + (high - low) / 2;
			if (Integer.compareUnsigned(values[middle], target) < 0) low = middle + 1;
			else high = middle;
		}
		return low;
	}
}

package shortestpath.pathfinder.astar;

import java.util.Arrays;

/** Per-search integers, allocating storage only for pages that receive a write. */
final class PagedSearchArray
{
	private static final int PAGE_BITS = 10;
	private static final int PAGE_SIZE = 1 << PAGE_BITS;
	private static final int PAGE_MASK = PAGE_SIZE - 1;
	private final int[][] pages;
	private final int defaultValue;

	PagedSearchArray(int size, int defaultValue)
	{
		pages = new int[(size + PAGE_MASK) >>> PAGE_BITS][];
		this.defaultValue = defaultValue;
	}

	int get(int index)
	{
		int[] page = pages[index >>> PAGE_BITS];
		return page == null ? defaultValue : page[index & PAGE_MASK];
	}

	void set(int index, int value)
	{
		int pageIndex = index >>> PAGE_BITS;
		int[] page = pages[pageIndex];
		if (page == null)
		{
			page = new int[PAGE_SIZE];
			if (defaultValue != 0) Arrays.fill(page, defaultValue);
			pages[pageIndex] = page;
		}
		page[index & PAGE_MASK] = value;
	}
}

package shortestpath.pathfinder.astar;

import java.util.Arrays;
import shortestpath.*;
import shortestpath.pathfinder.*;
import lombok.*;
import lombok.experimental.Accessors;

/** Query-lifetime raw seeds and provenance-reduced exact seed scans. */
@AllArgsConstructor
public final class PreparedHeuristic
{
	private static final int[] EMPTY = new int[0];

	@Getter @Accessors(fluent = true) private final TargetOverlay overlay;
	private final ReverseLabels reverse;
	private final int[][] seedTiles;
	private final int[][] seedLabels;
	private final int[][] generatorTiles;
	private final int[][] generatorLabels;
	@Getter @Accessors(fluent = true) private final long preparationNanos;



	public static PreparedHeuristic prepare(TargetOverlay overlay, ReverseLabels reverse)
	{
		if (reverse == null || reverse.overlay() != overlay)
			throw new IllegalArgumentException("reverse labels belong to another target overlay");
		long started = System.nanoTime();
		int bucketCount = overlay.routingStatic().routingComponentCount() * 2;
		PrimitiveIntList[] raw = new PrimitiveIntList[bucketCount];
		PrimitiveIntList[] reduced = new PrimitiveIntList[bucketCount];
		RoutingStatic stat = overlay.routingStatic();
		SiteGraph graph = overlay.graph();
		for (int site = 0; site < graph.spatialNodeCount(); site++)
		{
			addSite(raw, reduced, reverse, overlay, site, stat.siteTile(site), stat.siteComponents(site),
				BankVisitState.CARRIED);
			addSite(raw, reduced, reverse, overlay, site, stat.siteTile(site), stat.siteComponents(site),
				BankVisitState.BANKED);
		}
		for (int target = 0; target < overlay.targetCount(); target++)
		{
			if (!overlay.synthetic(target))
				continue;
			addSite(raw, reduced, reverse, overlay, overlay.targetNode(target), overlay.packedTarget(target),
				overlay.componentsView(target), BankVisitState.CARRIED);
			addSite(raw, reduced, reverse, overlay, overlay.targetNode(target), overlay.packedTarget(target),
				overlay.componentsView(target), BankVisitState.BANKED);
		}
		int[][] tiles = new int[bucketCount][], labels = new int[bucketCount][];
		int[][] generatorTiles = new int[bucketCount][], generatorLabels = new int[bucketCount][];
		for (int i = 0; i < bucketCount; i++)
		{
			tiles[i] = raw[i] == null ? EMPTY : raw[i].column(2, 0);
			labels[i] = raw[i] == null ? EMPTY : raw[i].column(2, 1);
			generatorTiles[i] = reduced[i] == null ? EMPTY : byId(reduced[i], 1);
			generatorLabels[i] = reduced[i] == null ? EMPTY : byId(reduced[i], 2);
		}
		return new PreparedHeuristic(overlay, reverse, tiles, labels, generatorTiles, generatorLabels,
			System.nanoTime() - started);
	}


	public ReverseLabels reverseLabels()
	{
		return reverse;
	}
	public int seedCount(int component, BankVisitState banked)
	{
		return seedTiles[key(component, banked)].length;
	}
	public int seedTile(int component, BankVisitState banked, int index)
	{
		return seedTiles[key(component, banked)][index];
	}
	public int seedLabel(int component, BankVisitState banked, int index)
	{
		return seedLabels[key(component, banked)][index];
	}
	public int generatorCount(int component, BankVisitState banked)
	{
		return generatorTiles[key(component, banked)].length;
	}
	public int generatorTile(int component, BankVisitState banked, int index)
	{
		return generatorTiles[key(component, banked)][index];
	}
	public int generatorLabel(int component, BankVisitState banked, int index)
	{
		return generatorLabels[key(component, banked)][index];
	}
	public int rawSeedCount()
	{
		return total(seedTiles);
	}
	public int generatorCount()
	{
		return total(generatorTiles);
	}
	public double generatorRatio()
	{
		int raw = rawSeedCount();
		return raw == 0 ? 0 : (double) generatorCount() / raw;
	}


	public int estimate(int packed, BankVisitState banked)
	{
		return estimate(packed, banked, overlay.routingStatic().attachments(packed, overlay.collision()));
	}

	public int estimate(TargetOverlay candidate, int packed, BankVisitState banked)
	{
		candidate.requireCompatible(overlay.graph());
		if (candidate != overlay)
			throw new IllegalArgumentException("heuristic belongs to another target query");
		return estimate(packed, banked);
	}

	/** Evaluate against the collision snapshot used to create the target overlay. */
	public int estimate(CollisionMap collision, int packed, BankVisitState banked)
	{
		if (collision == null)
			throw new NullPointerException("collision");
		return estimate(packed, banked, overlay.routingStatic().attachments(packed, collision));
	}

	public int estimate(int packed, BankVisitState banked, int[] components)
	{
		return estimateTable(packed, banked, components, generatorTiles, generatorLabels, true);
	}

	public int estimateBaseNode(int packed, BankVisitState banked, int component)
	{
		int best = targetLabel(packed, banked);
		int site = overlay.routingStatic().siteIndex(packed);
		if (site >= 0) best = Math.min(best, reverse.label(site, banked));
		return Math.min(best,
			estimateComponent(packed, banked, component, generatorTiles, generatorLabels, true));
	}

	/** Raw seed-scan oracle retained for reduced-generator differential checks. */
	int estimateRaw(int packed, BankVisitState banked, int[] components)
	{
		return estimateTable(packed, banked, components, seedTiles, seedLabels, false);
	}

	int estimateGenerators(int packed, BankVisitState banked, int[] components)
	{
		return estimateTable(packed, banked, components, generatorTiles, generatorLabels, false);
	}

	private int estimateTable(int packed, BankVisitState banked, int[] components, int[][] tiles, int[][] labels,
		boolean fallbackToRaw)
	{
		RoutingStatic stat = overlay.routingStatic();
		int best = targetLabel(packed, banked);
		int site = stat.siteIndex(packed);
		if (site >= 0)
			best = Math.min(best, reverse.label(site, banked));
		for (int component : components)
			best = Math.min(best, estimateComponent(packed, banked, component, tiles, labels, fallbackToRaw));
		return best;
	}

	private int estimateComponent(int packed, BankVisitState banked, int component, int[][] tiles, int[][] labels,
		boolean fallbackToRaw)
	{
		int key = key(component, banked);
		int[] bucketTiles = tiles[key];
		int[] bucketLabels = labels[key];
		if (fallbackToRaw && bucketTiles.length == 0)
		{
			bucketTiles = seedTiles[key];
			bucketLabels = seedLabels[key];
		}
		int best = CostArithmetic.INF;
		for (int i = 0; i < bucketTiles.length; i++)
			best = Math.min(best, CostArithmetic.add(bucketLabels[i],
				WorldPointUtil.distanceBetween(packed, bucketTiles[i])));
		return best;
	}

	private static void addSite(PrimitiveIntList[] raw, PrimitiveIntList[] reduced, ReverseLabels reverse,
		TargetOverlay overlay, int node, int packed, int[] components, BankVisitState banked)
	{
		int state = SiteGraph.stateId(node, banked);
		int distance = reverse.label(node, banked);
		if (distance == CostArithmetic.INF)
			return;
		for (int component : components)
		{
			int key = key(component, banked);
			add(raw, key, packed, distance);
			int origin = reverse.generatorOrigin(state);
			int generatorState = validOrigin(reverse, overlay, node, packed, components, component, state, origin)
				? origin : state;
			int generatorNode = generatorState / 2;
			int generatorTile = overlay.nodeTile(generatorNode);
			int generatorLabel = reverse.label(generatorNode,
				(generatorState & 1) != 0 ? BankVisitState.BANKED : BankVisitState.CARRIED);
			if (reduced[key] == null)
				reduced[key] = new PrimitiveIntList(24);
			PrimitiveIntList triples = reduced[key];
			boolean known = false;
			for (int i = 0; i < triples.size() && !known; i += 3)
				known = triples.get(i) == generatorState;
			if (!known)
			{
				triples.add(generatorState);
				triples.add(generatorTile);
				triples.add(generatorLabel);
			}
		}
	}

	private static boolean validOrigin(ReverseLabels reverse, TargetOverlay overlay, int node, int packed,
		int[] components, int component, int state, int origin)
	{
		if (origin < 0 || (origin & 1) != (state & 1))
			return false;
		int originNode = origin / 2;
		if (originNode >= overlay.graph().spatialNodeCount() && overlay.syntheticTarget(originNode) < 0)
			return false;
		int originTile = overlay.nodeTile(originNode);
		int direct = WorldPointUtil.distanceBetween(originTile, packed);
		if (direct == CostArithmetic.INF)
			return false;
		if (reverse.generatorWeightDoubled(state) == CostArithmetic.INF
			|| reverse.doubledLabel(state) != CostArithmetic.add(reverse.generatorWeightDoubled(state), CostArithmetic.twice(direct)))
			return false;
		int[] originComponents = overlay.nodeComponents(originNode);
		return IntArrays.contains(originComponents, component);
	}

	private int targetLabel(int packed, BankVisitState banked)
	{
		int target = overlay.targetIndex(packed);
		return target < 0 ? CostArithmetic.INF : reverse.targetLabel(target, banked);
	}

	private static int key(int component, BankVisitState banked)
	{
		return component * 2 + (banked == BankVisitState.BANKED ? 1 : 0);
	}

	private static void add(PrimitiveIntList[] raw, int key, int packed, int label)
	{
		if (raw[key] == null)
			raw[key] = new PrimitiveIntList(16);
		raw[key].add(packed);
		raw[key].add(label);
	}

	private static int total(int[][] values)
	{
		int total = 0;
		for (int[] value : values)
			total += value.length;
		return total;
	}

	/** The values at {@code offset} of (id, tile, label) triples, ordered by ascending id. */
	private static int[] byId(PrimitiveIntList triples, int offset)
	{
		long[] keys = new long[triples.size() / 3];
		for (int i = 0; i < keys.length; i++)
			keys[i] = (long) triples.get(3 * i) << 32 | i;
		Arrays.sort(keys);
		int[] out = new int[keys.length];
		for (int i = 0; i < out.length; i++)
			out[i] = triples.get(3 * (int) keys[i] + offset);
		return out;
	}
}

package shortestpath.pathfinder.astar;

import java.util.*;
import java.util.function.ToIntFunction;
import shortestpath.PrimitiveIntHashMap;
import shortestpath.pathfinder.*;
import shortestpath.transport.Transport;
import lombok.*;
import lombok.experimental.Accessors;

/** Immutable account/config snapshot used by the A* graph. */
public final class PreparedRoutingAccount
{
	private static final long FNV_OFFSET = 0xcbf29ce484222325L;
	private static final long FNV_PRIME = 0x100000001b3L;
	private static final TeleportCapability[] CAPABILITIES = TeleportCapability.values();

	@Getter @Accessors(fluent = true) private final boolean allowTransports;
	@Getter @Accessors(fluent = true) private final boolean bankPathEnabled;
	/** Bank tiles this account may use, in unsigned order: a subset of the static bank tiles. */
	private final int[] accessibleBankTiles;
	@Getter @Accessors(fluent = true) private final int bankVisitCost;
	private final View[] local = new View[2];
	/** The global teleports castable with each {@link TeleportCapability}, by ordinal, in each bank layer. */
	private final View[][] global;
	@Getter @Accessors(fluent = true) private final long fingerprint;

	private PreparedRoutingAccount(boolean allowTransports, boolean bankPathEnabled, int[] accessibleBankTiles,
		int bankVisitCost, View[] local, View[][] global)
	{
		this.allowTransports = allowTransports;
		this.bankPathEnabled = bankPathEnabled;
		this.accessibleBankTiles = accessibleBankTiles;
		this.bankVisitCost = bankVisitCost;
		this.local[0] = local[0];
		this.local[1] = local[1];
		this.global = global;
		this.fingerprint = computeFingerprint();
	}

	/**
	 * @param accessibleBankTiles the bank tiles whose requirements this account meets, as resolved by
	 * {@code PathfinderConfig.bankAccessible}; the static data knows every bank, so this decides
	 * which of them may switch a route into the banked layer
	 * @param bankVisitCost what switching into the banked layer costs, as legacy's bank-visit edge
	 * ({@code PathfinderConfig.getBankVisitCost})
	 */
	public static PreparedRoutingAccount compile(TransportAvailability carried, TransportAvailability banked,
		boolean bankPathEnabled, Collection<Integer> accessibleBankTiles, int bankVisitCost,
		boolean allowTransports, ToIntFunction<Transport> additionalCost)
	{
		int[] banks = sortedUnsigned(accessibleBankTiles);
		CostArithmetic.validate(bankVisitCost);
		View[] local = new View[2];
		View[][] global = new View[CAPABILITIES.length][2];
		for (int bankedState = 0; bankedState < 2; bankedState++)
		{
			TransportAvailability availability = bankedState != 0 ? banked : carried;
			local[bankedState] = allowTransports
				? View.local(availability.getTransportsPacked(), additionalCost) : View.empty(true);
			for (TeleportCapability capability : CAPABILITIES)
				global[capability.ordinal()][bankedState] = allowTransports
					? View.global(availability.getUsableTeleports(), additionalCost, capability) : View.empty(false);
		}
		return new PreparedRoutingAccount(allowTransports, bankPathEnabled, banks, bankVisitCost, local, global);
	}

	private static int[] sortedUnsigned(Collection<Integer> tiles)
	{
		int[] result = new int[tiles.size()];
		int size = 0;
		for (int tile : tiles)
			result[size++] = tile ^ Integer.MIN_VALUE;
		Arrays.sort(result);
		int unique = 0;
		for (int i = 0; i < size; i++)
			if (unique == 0 || result[unique - 1] != result[i])
				result[unique++] = result[i];
		for (int i = 0; i < unique; i++)
			result[i] ^= Integer.MIN_VALUE;
		return Arrays.copyOf(result, unique);
	}



	/**
	 * Whether this account may bank at {@code packedTile}. Only meaningful for a tile the static
	 * data marks as a bank; the forward search asks only there, so the binary search stays rare.
	 */
	public boolean bankAccessible(int packedTile)
	{
		return IntArrays.binarySearch(accessibleBankTiles, packedTile) >= 0;
	}
	/** The cost of switching into the banked layer at an accessible bank. */

	/** The global teleports castable outside the wilderness: every global this account has. */
	public int globalCount(BankVisitState banked)
	{
		return globalCount(TeleportCapability.ALL, banked);
	}
	public int globalDestination(BankVisitState banked, int index)
	{
		return globalDestination(TeleportCapability.ALL, banked, index);
	}
	public int globalCost(BankVisitState banked, int index)
	{
		return globalCost(TeleportCapability.ALL, banked, index);
	}
	/** The global teleports castable with {@code capability}. */
	public int globalCount(TeleportCapability capability, BankVisitState banked)
	{
		return globalView(capability, banked).destinations.length;
	}
	public int globalDestination(TeleportCapability capability, BankVisitState banked, int index)
	{
		return globalView(capability, banked).destinations[index];
	}
	public int globalCost(TeleportCapability capability, BankVisitState banked, int index)
	{
		return globalView(capability, banked).costs[index];
	}
	public Transport globalTransport(TeleportCapability capability, BankVisitState banked, int index)
	{
		return globalView(capability, banked).transports[index];
	}

	View localView(BankVisitState banked)
	{
		return view(local, banked);
	}
	View globalView(BankVisitState banked)
	{
		return globalView(TeleportCapability.ALL, banked);
	}
	View globalView(TeleportCapability capability, BankVisitState banked)
	{
		return view(global[capability.ordinal()], banked);
	}

	private static View view(View[] views, BankVisitState banked)
	{
		return views[banked == BankVisitState.BANKED ? 1 : 0];
	}

	private long computeFingerprint()
	{
		long hash = FNV_OFFSET;
		hash = mix(hash, allowTransports ? 1 : 0);
		hash = mix(hash, bankPathEnabled ? 1 : 0);
		hash = u32(hash, bankVisitCost);
		hash = u32(hash, accessibleBankTiles.length);
		for (int tile : accessibleBankTiles)
			hash = u32(hash, tile);
		for (int kind = 0; kind <= CAPABILITIES.length; kind++)
		{
			for (int banked = 0; banked < 2; banked++)
			{
				View view = kind == 0 ? local[banked] : global[kind - 1][banked];
				hash = mix(hash, kind);
				hash = mix(hash, banked);
				for (int i = 0; i < view.destinations.length; i++)
				{
					if (kind == 0)
						hash = u32(hash, view.origins[i]);
					hash = u32(hash, view.destinations[i]);
					hash = u32(hash, view.costs[i]);
					hash = u32(hash, view.types[i]);
					hash = u32(hash, view.maxWilderness[i]);
				}
			}
		}
		return hash;
	}

	private static long u32(long hash, int value)
	{
		for (int shift = 0; shift < 32; shift += 8)
			hash = mix(hash, value >>> shift);
		return hash;
	}

	private static long mix(long hash, int value)
	{
		return (hash ^ (value & 0xffL)) * FNV_PRIME;
	}

	@AllArgsConstructor(access = AccessLevel.PRIVATE)
	static final class View
	{
		final boolean local;
		final int[] origins;
		final int[] destinations;
		final int[] costs;
		final int[] types;
		final int[] maxWilderness;
		final int[] actionClasses;
		/** The transport each row represents; parallel to the other arrays so a search can
		 *  report which transport produced an edge, not just its effect. */
		final Transport[] transports;

		static View empty(boolean local)
		{
			return new View(local, new int[0], new int[0], new int[0], new int[0], new int[0], new int[0],
				new Transport[0]);
		}

		static View local(PrimitiveIntHashMap<Transport[]> map, ToIntFunction<Transport> additionalCost)
		{
			Builder builder = new Builder(true);
			int[] origins = map.keys();
			Arrays.sort(origins);
			for (int origin : origins)
			{
				Transport[] transports = map.getOrDefault(origin, TransportAvailability.EMPTY_TRANSPORTS);
				for (Transport transport : transports)
					builder.add(origin, transport, additionalCost);
			}
			return builder.build();
		}

		static View global(Transport[] transports, ToIntFunction<Transport> additionalCost,
			TeleportCapability capability)
		{
			Builder builder = new Builder(false);
			for (Transport transport : transports)
			{
				if (capability.canCast(transport))
				{
					builder.add(0, transport, additionalCost);
				}
			}
			return builder.build();
		}
	}

	private static final class Builder
	{
		private final boolean local;
		private int size;
		private int[] origins = new int[16];
		private int[] destinations = new int[16];
		private int[] costs = new int[16];
		private int[] types = new int[16];
		private int[] maxWilderness = new int[16];
		private int[] actionClasses = new int[16];
		private Transport[] transports = new Transport[16];
		private final java.util.Map<java.util.List<Object>, Integer> actionClassIds = new java.util.HashMap<>();

		Builder(boolean local)
		{
			this.local = local;
		}

		void add(int origin, Transport transport, ToIntFunction<Transport> additionalCost)
		{
			if (size == destinations.length)
			{
				int capacity = size * 2;
				origins = Arrays.copyOf(origins, capacity);
				destinations = Arrays.copyOf(destinations, capacity);
				costs = Arrays.copyOf(costs, capacity);
				types = Arrays.copyOf(types, capacity);
				maxWilderness = Arrays.copyOf(maxWilderness, capacity);
				actionClasses = Arrays.copyOf(actionClasses, capacity);
				transports = Arrays.copyOf(transports, capacity);
			}
			origins[size] = origin;
			destinations[size] = transport.getDestination();
			costs[size] = CostArithmetic.add(transport.getDuration(), additionalCost.applyAsInt(transport));
			types[size] = transport.getType().ordinal();
			maxWilderness[size] = transport.getMaxWildernessLevel();
			actionClasses[size] = actionClass(transport, costs[size]);
			transports[size] = transport;
			size++;
		}

		private int actionClass(Transport transport, int cost)
		{
			// An action without an object description is never grouped: a class of its own, below zero.
			if (!local || transport.getObjectInfo() == null) return -1 - size;
			java.util.List<Object> key = java.util.Arrays.asList(transport.getType(), transport.getDestination(), cost,
				transport.getMaxWildernessLevel(), transport.getObjectInfo(), transport.getDisplayInfo(),
				transport.isConsumable(), transport.getItemRequirements());
			return actionClassIds.computeIfAbsent(key, k -> actionClassIds.size());
		}

		View build()
		{
			// Origins arrive in signed order but lookups need unsigned order, so plane 2/3 tiles
			// are out of place; an insertion sort was quadratic here.
			Integer[] order = new Integer[size];
			for (int i = 0; i < size; i++)
				order[i] = i;
			Arrays.sort(order, this::compare);
			int[] sortedOrigins = new int[size];
			int[] sortedDestinations = new int[size];
			int[] sortedCosts = new int[size];
			int[] sortedTypes = new int[size];
			int[] sortedMaxWilderness = new int[size];
			int[] sortedActionClasses = new int[size];
			Transport[] sortedTransports = new Transport[size];
			for (int i = 0; i < size; i++)
			{
				int from = order[i];
				sortedOrigins[i] = origins[from];
				sortedDestinations[i] = destinations[from];
				sortedCosts[i] = costs[from];
				sortedTypes[i] = types[from];
				sortedMaxWilderness[i] = maxWilderness[from];
				sortedActionClasses[i] = actionClasses[from];
				sortedTransports[i] = transports[from];
			}
			return new View(local, sortedOrigins, sortedDestinations, sortedCosts, sortedTypes, sortedMaxWilderness,
				sortedActionClasses, sortedTransports);
		}

		private int compare(int left, int right)
		{
			int result = Integer.compareUnsigned(origins[left], origins[right]);
			if (result != 0)
				return result;
			result = Integer.compareUnsigned(destinations[left], destinations[right]);
			if (result != 0)
				return result;
			result = Integer.compare(costs[left], costs[right]);
			if (result != 0)
				return result;
			result = Integer.compare(types[left], types[right]);
			return result != 0 ? result : Integer.compare(maxWilderness[left], maxWilderness[right]);
		}
	}
}

package shortestpath.pathfinder.astar;

import java.util.function.BooleanSupplier;
import shortestpath.pathfinder.CollisionMap;
import lombok.*;
import lombok.experimental.Accessors;

/**
 * Target-lifetime preparation: the target overlay, its reverse labels and the heuristic built
 * from them. None of it depends on the start, so one prepared target serves any number of
 * forward searches for the same account snapshot. With several target tiles, a search ends at
 * whichever target is cheapest to reach.
 */
@AllArgsConstructor
public final class PreparedTarget
{
	@Getter @Accessors(fluent = true) private final TargetOverlay overlay;
	@Getter @Accessors(fluent = true) private final PreparedHeuristic heuristic;
	@Getter @Accessors(fluent = true) private final long reverseSearchNanos;
	@Getter @Accessors(fluent = true) private final long heuristicPrepareNanos;



	public static PreparedTarget prepare(SiteGraph graph, CollisionMap collision, int packed)
	{
		return prepare(graph, collision, new int[] {packed});
	}

	public static PreparedTarget prepare(SiteGraph graph, CollisionMap collision, int[] packedTargets)
	{
		return prepare(new TargetOverlay(graph, collision, packedTargets));
	}

	public static PreparedTarget prepare(SiteGraph graph, CollisionMap collision, int[] packedTargets, int[] terminalLayers)
	{
		return prepare(new TargetOverlay(graph, collision, packedTargets, terminalLayers));
	}

	static PreparedTarget prepare(SiteGraph graph, CollisionMap collision, long[] targets)
	{
		return prepare(new TargetOverlay(graph, collision, targets));
	}

	private static PreparedTarget prepare(TargetOverlay overlay)
	{
		long phaseStarted = System.nanoTime();
		ReverseLabels reverse = ReverseLabels.computeSparse(overlay);
		long reverseSearchNanos = System.nanoTime() - phaseStarted;
		phaseStarted = System.nanoTime();
		PreparedHeuristic heuristic = PreparedHeuristic.prepare(overlay, reverse);
		long heuristicPrepareNanos = System.nanoTime() - phaseStarted;
		return new PreparedTarget(overlay, heuristic, reverseSearchNanos, heuristicPrepareNanos);
	}

	public AStarForwardSearch.Result search(int start, BooleanSupplier cancelled, double heuristicWeight)
	{
		return search(start, cancelled, heuristicWeight, SearchRestrictions.none(), AStarForwardSearch.NO_PROGRESS);
	}

	/**
	 * {@code restrictions} mirrors the positional gates legacy applies per edge; they only remove
	 * edges, so the prepared heuristic stays admissible and this target may be reused.
	 * {@code progressed} runs each time the closest-reached-tile record improves.
	 */
	public AStarForwardSearch.Result search(int start, BooleanSupplier cancelled, double heuristicWeight,
		SearchRestrictions restrictions, Runnable progressed)
	{
		return AStarForwardSearch.search(overlay, heuristic, start, cancelled, true, heuristicWeight,
			restrictions, progressed);
	}

	/**
	 * As {@link #search(int, BooleanSupplier, double, SearchRestrictions, Runnable)}, finishing only
	 * at target states {@code goal} accepts; see {@link GoalTest}.
	 */
	public AStarForwardSearch.Result search(int start, BooleanSupplier cancelled, double heuristicWeight,
		SearchRestrictions restrictions, Runnable progressed, GoalTest goal)
	{
		return AStarForwardSearch.search(overlay, heuristic, start, cancelled, true, heuristicWeight,
			restrictions, progressed, goal);
	}



	/** The target tiles, in unsigned order. */
	public int[] packedTargets()
	{
		return overlay.packedTargets();
	}
	/** Time the reverse relaxed search took when this target was prepared. */

	/** Time the heuristic seed/generator tables took when this target was prepared. */

}

package shortestpath.pathfinder.astar;

import java.util.Arrays;
import shortestpath.pathfinder.BankVisitState;
import lombok.*;
import lombok.experimental.Accessors;

/** Reverse labels in the relaxed graph, computed on the sparse walking network. */
@AllArgsConstructor
public final class ReverseLabels
{
	@Getter @Accessors(fluent = true) private final TargetOverlay overlay;
	private final int[] labels;
	private final int[] generatorOrigins;
	private final int[] generatorWeights;
	private final int settled;
	private final int stale;
	private final int pushes;
	private final int sparseRelaxations;
	private final int explicitRelaxations;
	private final int attachmentRelaxations;
	@Getter @Accessors(fluent = true) private final long elapsedNanos;

	/** Sparse CSR reverse Dijkstra, including internal Steiner states. */
	static ReverseLabels computeSparse(TargetOverlay overlay)
	{
		long started = System.nanoTime();
		SiteGraph graph = overlay.graph();
		RoutingStatic stat = overlay.routingStatic();
		int routingNodes = overlay.queryNodeCount();
		int originalCount = stat.sparseOriginalCount();
		int stateCount = (routingNodes + stat.sparseSteinerCount()) * 2;
		int[] doubled = new int[stateCount];
		int[] origins = new int[stateCount];
		int[] weights = new int[stateCount];
		Arrays.fill(doubled, CostArithmetic.INF);
		Arrays.fill(origins, -1);
		Arrays.fill(weights, CostArithmetic.INF);
		AStarMinHeap queue = new AStarMinHeap(Math.max(16, stateCount));
		int pushes = 0;
		for (int target = 0; target < overlay.targetCount(); target++)
		{
			for (BankVisitState banked : BankVisitState.values())
			{
				if (!overlay.isTerminal(target, banked)) continue;
				int seed = overlay.targetState(target, banked);
				doubled[seed] = 0;
				origins[seed] = seed;
				weights[seed] = 0;
				queue.push(0, 0, seed);
				pushes++;
			}
		}
		int settled = 0, stale = 0;
		int sparseEdges = 0, explicitEdges = 0, attachmentEdges = 0;
		while (queue.poll())
		{
			int state = queue.state(), cost = queue.cost();
			if (cost != doubled[state])
			{
				stale++;
				continue;
			}
			settled++;
			int vertex = state / 2;
			BankVisitState banked = (state & 1) != 0 ? BankVisitState.BANKED : BankVisitState.CARRIED;
			if (vertex < graph.nodeCount())
			{
				for (int edge = graph.reverseEdgeStart(state); edge < graph.reverseEdgeEnd(state); edge++)
				{
					explicitEdges++;
					int edgeCost = CostArithmetic.twice(graph.reverseCost(edge));
					if (relax(doubled, origins, weights, queue, state,
						graph.reverseFromState(edge), edgeCost, graph.reverseStartsGenerator(edge)))
						pushes++;
				}
			}
			if (vertex < originalCount || vertex >= routingNodes)
			{
				int sparseVertex = vertex < originalCount ? vertex : originalCount + vertex - routingNodes;
				for (int edge = stat.sparseOffset(sparseVertex); edge < stat.sparseOffset(sparseVertex + 1); edge++)
				{
					sparseEdges++;
					int destination = sparseNode(routingNodes, originalCount, stat.sparseDestination(edge));
					if (relax(doubled, origins, weights, queue, state, SiteGraph.stateId(destination, banked),
						stat.sparseWeight(edge), false))
						pushes++;
				}
			}
			// Synthetic targets only emit reverse attachments; PreparedHeuristic also estimates
			// non-terminal layers from their component's finite site labels.
			int target = vertex < routingNodes ? overlay.syntheticTarget(vertex) : -1;
			for (int i = 0; target >= 0 && i < overlay.attachmentCount(target); i++)
			{
				attachmentEdges++;
				if (relax(doubled, origins, weights, queue, state,
					SiteGraph.stateId(overlay.attachmentSite(target, i), banked),
					CostArithmetic.twice(overlay.attachmentCost(target, i)), false))
					pushes++;
			}
		}
		int[] labels = new int[routingNodes * 2];
		int[] routingOrigins = new int[routingNodes * 2];
		int[] routingWeights = new int[routingNodes * 2];
		for (int state = 0; state < labels.length; state++)
		{
			labels[state] = CostArithmetic.halve(doubled[state]);
			routingOrigins[state] = origins[state];
			routingWeights[state] = weights[state];
		}
		return new ReverseLabels(overlay, labels, routingOrigins, routingWeights, settled, stale, pushes,
			sparseEdges, explicitEdges, attachmentEdges, System.nanoTime() - started);
	}

	public int label(int node, BankVisitState banked)
	{
		return labels[SiteGraph.stateId(node, banked)];
	}
	public int targetLabel(BankVisitState banked)
	{
		return labels[overlay.targetState(banked)];
	}
	public int targetLabel(int target, BankVisitState banked)
	{
		return labels[overlay.targetState(target, banked)];
	}
	public int stateCount()
	{
		return labels.length;
	}
	public int[] labels()
	{
		return labels.clone();
	}
	public int settledCount()
	{
		return settled;
	}
	public int staleCount()
	{
		return stale;
	}
	public int pushCount()
	{
		return pushes;
	}

	public int sparseRelaxationCount()
	{
		return sparseRelaxations;
	}
	public int explicitRelaxationCount()
	{
		return explicitRelaxations;
	}
	public int attachmentRelaxationCount()
	{
		return attachmentRelaxations;
	}

	int generatorOrigin(int state)
	{
		return generatorOrigins[state];
	}
	int generatorWeightDoubled(int state)
	{
		return generatorWeights[state];
	}
	int doubledLabel(int state)
	{
		return CostArithmetic.twice(labels[state]);
	}

	private static int sparseNode(int routingNodes, int originalCount, int sparseVertex)
	{
		return sparseVertex < originalCount ? sparseVertex : routingNodes + sparseVertex - originalCount;
	}

	private static boolean relax(int[] distances, int[] origins, int[] weights, AStarMinHeap queue, int from,
		int next, int edgeCost, boolean startsGenerator)
	{
		int candidate = CostArithmetic.add(distances[from], edgeCost);
		if (candidate == CostArithmetic.INF || candidate >= distances[next])
			return false;
		distances[next] = candidate;
		if (startsGenerator)
		{
			origins[next] = next;
			weights[next] = candidate;
		}
		else
		{
			origins[next] = origins[from];
			weights[next] = weights[from];
		}
		queue.push(candidate, candidate, next);
		return true;
	}
}

package shortestpath.pathfinder.astar;

import java.io.IOException;
import java.util.*;
import shortestpath.pathfinder.CollisionMap;
import lombok.Getter;
import lombok.experimental.Accessors;

/** Immutable primitive-array representation of the A* backend's static routing data. */
public final class RoutingStatic
{
	private final int[] searchTiles;
	private final TileComponents searchComponents;
	// Zero means absent; other values are distances within the sorted tile array.
	private final char[] northOffsets, southOffsets;
	private final byte[] walkingMasks;
	private final int[] siteTiles, siteComponentOffsets, siteComponentIds;
	@Getter @Accessors(fluent = true) private final int routingComponentCount;
	private final int[] componentSiteOffsets, componentSiteIds, reachableBankTiles;
	private final BitSet reachableBankNodes, reachableBankSites;
	private final int[] crossingFromSite, crossingToSite, crossingCosts;
	@Getter @Accessors(fluent = true) private final int sparseOriginalCount, sparseVertexCount, sparseSteinerCount;
	private final int sparseUndirectedEdgeCount;
	@Getter @Accessors(fluent = true) private final int sparseAdjacencyCount;
	private final int[] sparseOffsets, sparseDestinations, sparseWeights;
	/** Exact site-pair walks of small components, joined into the sparse network; {@code null} if none. */
	private final ExactWalks exactWalks;

	private RoutingStatic(int[] searchTiles, TileComponents searchComponents, byte[] walkingMasks,
		char[] northOffsets, char[] southOffsets, int[] siteTiles, int[] siteComponentOffsets, int[] siteComponentIds,
		int routingComponentCount, int[] componentSiteOffsets, int[] componentSiteIds, int[] reachableBankTiles,
		int[] crossingFromSite, int[] crossingToSite, int[] crossingCosts, int sparseOriginalCount,
		int sparseVertexCount, int sparseSteinerCount, int sparseUndirectedEdgeCount, int sparseAdjacencyCount,
		int[] sparseOffsets, int[] sparseDestinations, int[] sparseWeights, ExactWalks exactWalks)
	{
		this.exactWalks = exactWalks;
		this.searchTiles = searchTiles;
		this.searchComponents = searchComponents;
		this.walkingMasks = walkingMasks;
		this.northOffsets = northOffsets;
		this.southOffsets = southOffsets;
		this.siteTiles = siteTiles;
		this.siteComponentOffsets = siteComponentOffsets;
		this.siteComponentIds = siteComponentIds;
		this.routingComponentCount = routingComponentCount;
		this.componentSiteOffsets = componentSiteOffsets;
		this.componentSiteIds = componentSiteIds;
		this.reachableBankTiles = reachableBankTiles;
		this.reachableBankNodes = new BitSet(searchTiles.length);
		this.reachableBankSites = new BitSet(siteTiles.length);
		for (int tile : reachableBankTiles)
		{
			int node = IntArrays.binarySearch(searchTiles, tile);
			if (node >= 0) reachableBankNodes.set(node);
			int site = IntArrays.binarySearch(siteTiles, tile);
			if (site >= 0) reachableBankSites.set(site);
		}
		this.crossingFromSite = crossingFromSite;
		this.crossingToSite = crossingToSite;
		this.crossingCosts = crossingCosts;
		this.sparseOriginalCount = sparseOriginalCount;
		this.sparseVertexCount = sparseVertexCount;
		this.sparseSteinerCount = sparseSteinerCount;
		this.sparseUndirectedEdgeCount = sparseUndirectedEdgeCount;
		this.sparseAdjacencyCount = sparseAdjacencyCount;
		this.sparseOffsets = sparseOffsets;
		this.sparseDestinations = sparseDestinations;
		this.sparseWeights = sparseWeights;
	}

	/**
	 * Takes exclusive ownership of freshly built arrays and validates them before publication.
	 * Callers must never modify the supplied arrays or expose them to other code after this call.
	 */
	static RoutingStatic takeOwnership(int[] searchTiles, TileComponents searchComponents, byte[] walkingMasks,
		char[] northOffsets, char[] southOffsets, int[] siteTiles, int[] siteComponentOffsets, int[] siteComponentIds,
		int routingComponentCount, int[] componentSiteOffsets, int[] componentSiteIds, int[] reachableBankTiles,
		int[] crossingFromSite, int[] crossingToSite, int[] crossingCosts, int sparseOriginalCount,
		int sparseVertexCount, int sparseSteinerCount, int sparseUndirectedEdgeCount, int sparseAdjacencyCount,
		int[] sparseOffsets, int[] sparseDestinations, int[] sparseWeights) throws IOException
	{
		return takeOwnership(searchTiles, searchComponents, walkingMasks, northOffsets, southOffsets, siteTiles,
			siteComponentOffsets, siteComponentIds, routingComponentCount, componentSiteOffsets, componentSiteIds,
			reachableBankTiles, crossingFromSite, crossingToSite, crossingCosts, sparseOriginalCount, sparseVertexCount,
			sparseSteinerCount, sparseUndirectedEdgeCount, sparseAdjacencyCount, sparseOffsets, sparseDestinations,
			sparseWeights, null);
	}

	/** As above, with the exact walks the sparse network already joins small components by. */
	static RoutingStatic takeOwnership(int[] searchTiles, TileComponents searchComponents, byte[] walkingMasks,
		char[] northOffsets, char[] southOffsets, int[] siteTiles, int[] siteComponentOffsets, int[] siteComponentIds,
		int routingComponentCount, int[] componentSiteOffsets, int[] componentSiteIds, int[] reachableBankTiles,
		int[] crossingFromSite, int[] crossingToSite, int[] crossingCosts, int sparseOriginalCount,
		int sparseVertexCount, int sparseSteinerCount, int sparseUndirectedEdgeCount, int sparseAdjacencyCount,
		int[] sparseOffsets, int[] sparseDestinations, int[] sparseWeights, ExactWalks exactWalks) throws IOException
	{
		RoutingStatic result = new RoutingStatic(searchTiles, searchComponents, walkingMasks,
			northOffsets, southOffsets, siteTiles, siteComponentOffsets,
			siteComponentIds, routingComponentCount, componentSiteOffsets, componentSiteIds,
			reachableBankTiles, crossingFromSite, crossingToSite, crossingCosts,
			sparseOriginalCount, sparseVertexCount, sparseSteinerCount, sparseUndirectedEdgeCount, sparseAdjacencyCount,
			sparseOffsets, sparseDestinations, sparseWeights, exactWalks);
		result.validate();
		return result;
	}

	private void validate() throws IOException
	{
		aligned(searchComponents.length(), searchTiles.length, "search components");
		aligned(walkingMasks.length, searchTiles.length, "walking masks");
		aligned(northOffsets.length, searchTiles.length, "north nodes");
		aligned(southOffsets.length, searchTiles.length, "south nodes");
		ascending(searchTiles, "search tiles");
		ascending(siteTiles, "site tiles");
		ascending(reachableBankTiles, "reachable bank tiles");
		refs(searchComponents, routingComponentCount, "search component");
		nodeOffsets(northOffsets, true);
		nodeOffsets(southOffsets, false);
		csr(siteComponentOffsets, siteComponentIds, siteTiles.length, routingComponentCount, "site components");
		csr(componentSiteOffsets, componentSiteIds, routingComponentCount, siteTiles.length, "component sites");
		for (int tile : reachableBankTiles)
			if (siteIndex(tile) < 0)
				throw new IOException("reachable bank tile is not a static site: " + Integer.toUnsignedString(tile));
		aligned(crossingToSite.length, crossingFromSite.length, "crossing destinations");
		aligned(crossingCosts.length, crossingFromSite.length, "crossing costs");
		for (int i = 0; i < crossingFromSite.length; i++)
		{
			if (crossingFromSite[i] < 0 || crossingFromSite[i] >= siteTiles.length || crossingToSite[i] < 0
				|| crossingToSite[i] >= siteTiles.length)
				throw new IOException("crossing site out of range at index " + i);
			if (crossingFromSite[i] == crossingToSite[i] || crossingCosts[i] < 0)
				throw new IOException("invalid crossing at index " + i);
		}
		if (sparseOriginalCount != siteTiles.length || sparseSteinerCount != sparseVertexCount - sparseOriginalCount
			|| sparseAdjacencyCount != 2L * sparseUndirectedEdgeCount)
			throw new IOException("inconsistent sparse counts");
		csr(sparseOffsets, sparseDestinations, sparseVertexCount, sparseVertexCount, "sparse");
		for (int weight : sparseWeights)
			if (weight < 0)
				throw new IOException("negative sparse weight");
		if (sparseWeights.length != sparseDestinations.length)
			throw new IOException("sparse weight length mismatch");
		validateRelations();
	}

	private static void aligned(int actualLength, int expectedLength, String label) throws IOException
	{
		if (actualLength != expectedLength)
			throw new IOException(label + " length mismatch");
	}

	private static void ascending(int[] values, String label) throws IOException
	{
		for (int i = 1; i < values.length; i++)
			if (Integer.compareUnsigned(values[i - 1], values[i]) >= 0)
				throw new IOException(label + " is not strictly ascending at index " + i);
	}

	private static void refs(TileComponents values, int limit, String label) throws IOException
	{
		for (int i = 0; i < values.length(); i++)
		{
			int component = values.get(i);
			if (component < 0 || component >= limit)
				throw new IOException(label + " out of range");
		}
	}

	private static void nodeOffsets(char[] offsets, boolean north) throws IOException
	{
		for (int i = 0; i < offsets.length; i++)
		{
			int offset = offsets[i];
			int node = north ? i + offset : i - offset;
			if (offset > 32768 || node < 0 || node >= offsets.length)
				throw new IOException("neighbour offset out of range");
		}
	}

	private static void csr(int[] offsets, int[] values, int groups, int limit, String label) throws IOException
	{
		if (offsets.length != groups + 1 || offsets.length == 0 || offsets[0] != 0
			|| offsets[offsets.length - 1] != values.length)
			throw new IOException(label + " offsets are invalid");
		for (int i = 1; i < offsets.length; i++)
			if (offsets[i] < offsets[i - 1])
				throw new IOException(label + " offsets are not monotonic at index " + i);
		for (int value : values)
			if (value < 0 || value >= limit)
				throw new IOException(label + " reference out of range");
	}

	private void validateRelations() throws IOException
	{
		for (int site = 0; site < siteTiles.length; site++)
			for (int p = siteComponentOffsets[site]; p < siteComponentOffsets[site + 1]; p++)
				if (!IntArrays.contains(componentSiteIds, componentSiteOffsets[siteComponentIds[p]],
						componentSiteOffsets[siteComponentIds[p] + 1], site))
					throw new IOException("site/component relation is not reciprocal");
		for (int component = 0; component < routingComponentCount; component++)
			for (int p = componentSiteOffsets[component]; p < componentSiteOffsets[component + 1]; p++)
				if (!IntArrays.contains(siteComponentIds, siteComponentOffsets[componentSiteIds[p]],
						siteComponentOffsets[componentSiteIds[p] + 1], component))
					throw new IOException("component/site relation is not reciprocal");
	}


	public int searchTileCount()
	{
		return searchTiles.length;
	}
	public int siteCount()
	{
		return siteTiles.length;
	}

	public int reachableBankCount()
	{
		return reachableBankTiles.length;
	}
	public int reachableBankTile(int index)
	{
		return reachableBankTiles[index];
	}
	/**
	 * Whether the search tile is a bank in the world. This is account-independent: whether an
	 * account may bank there is {@link PreparedRoutingAccount#bankAccessible(int)}.
	 */
	public boolean isBankNode(int node)
	{
		return reachableBankNodes.get(node);
	}
	/** Whether the site is a bank in the world; see {@link #isBankNode(int)}. */
	public boolean isBankSite(int site)
	{
		return site >= 0 && reachableBankSites.get(site);
	}
	public int crossingCount()
	{
		return crossingFromSite.length;
	}
	public int searchTile(int index)
	{
		return searchTiles[index];
	}
	public int walkingMask(int index)
	{
		return Byte.toUnsignedInt(walkingMasks[index]);
	}
	public int northNode(int index)
	{
		return northOffsets[index] == 0 ? -1 : index + northOffsets[index];
	}
	public int southNode(int index)
	{
		return southOffsets[index] == 0 ? -1 : index - southOffsets[index];
	}
	public int routingComponent(int index)
	{
		return searchComponents.get(index);
	}
	public int siteTile(int index)
	{
		return siteTiles[index];
	}
	public int searchIndex(int packed)
	{
		return IntArrays.binarySearch(searchTiles, packed);
	}
	public int siteIndex(int packed)
	{
		return IntArrays.binarySearch(siteTiles, packed);
	}
	public int[] siteComponents(int site)
	{
		return Arrays.copyOfRange(siteComponentIds, siteComponentOffsets[site], siteComponentOffsets[site + 1]);
	}
	public int componentSiteCount(int component)
	{
		return componentSiteOffsets[component + 1] - componentSiteOffsets[component];
	}

	/** The search tile one walking step from {@code node} along mask bit {@code bit}, or a negative value. */
	int walkSuccessor(int node, int bit)
	{
		int south = southNode(node), north = northNode(node);
		switch (bit)
		{
			case 0: return north;
			case 1: return north < 0 ? -1 : north + 1;
			case 2: return node + 1;
			case 3: return south < 0 ? -1 : south + 1;
			case 4: return south;
			case 5: return south < 0 ? -1 : south - 1;
			case 6: return node - 1;
			default: return north < 0 ? -1 : north - 1;
		}
	}

	/** Exact site-pair walks of small components, or {@code null} when the network has none. */
	ExactWalks exactWalks()
	{
		return exactWalks;
	}

	public int[] componentSites(int component)
	{
		return Arrays.copyOfRange(
			componentSiteIds, componentSiteOffsets[component], componentSiteOffsets[component + 1]);
	}
	public int crossingFromSite(int index)
	{
		return crossingFromSite[index];
	}
	public int crossingToSite(int index)
	{
		return crossingToSite[index];
	}
	public int crossingCost(int index)
	{
		return crossingCosts[index];
	}
	public int sparseOffset(int index)
	{
		return sparseOffsets[index];
	}
	public int sparseDestination(int index)
	{
		return sparseDestinations[index];
	}
	public int sparseWeight(int index)
	{
		return sparseWeights[index];
	}

	public int[] attachments(int packedPoint, CollisionMap collision)
	{
		int index = searchIndex(packedPoint);
		if (index >= 0)
			return new int[] {searchComponents.get(index)};
		int[] result = new int[8];
		int count = 0;
		for (int neighbor : collision.ordinaryWalkingNeighbors(packedPoint))
		{
			int neighborIndex = searchIndex(neighbor);
			if (neighborIndex >= 0 && !IntArrays.contains(result, 0, count, searchComponents.get(neighborIndex)))
				result[count++] = searchComponents.get(neighborIndex);
		}
		Arrays.sort(result, 0, count);
		return Arrays.copyOf(result, count);
	}

}

package shortestpath.pathfinder.astar;

import java.io.*;
import java.util.*;
import lombok.AllArgsConstructor;
import shortestpath.WorldPointUtil;
import shortestpath.pathfinder.CollisionMap;
import shortestpath.transport.Transport;

/**
 * Builds the A* backend's {@link RoutingStatic} from a {@link ComponentLayer} (the routing
 * components of every walkable tile, derived offline from the collision map and the separator
 * cuts), the {@link CollisionMap}, the raw (account-independent) transports and global teleports,
 * and the bank list.
 *
 * <ol>
 *   <li>Natural components: the layer's routing components joined through its crossings.</li>
 *   <li>Structural reachability: natural components reachable from Lumbridge through any
 *       transport or global teleport of any type, seasonal included, regardless of requirements.</li>
 *   <li>Search tiles: every tile of a reachable natural component, with its walking mask, routing
 *       component and north/south neighbour indexes.</li>
 *   <li>Sites (transport endpoints, crossing endpoints and reachable banks), their component
 *       attachments in both directions, and separator crossings.</li>
 *   <li>The sparse walking network over the sites ({@link SparseWalkingNetworkBuilder}).</li>
 * </ol>
 *
 * <p>Routing components are numbered by rank among the candidates: the components attached to a
 * transport endpoint, the seed tile or a crossing endpoint, which is how the numbers of a
 * derivation that only ever saw that land come out. Endpoints of cuts that were dropped when the
 * layer was generated (no longer walking edges, or no longer separating) are not candidates, so on
 * unreachable land the component count and the ids numbered after them can differ from a derivation
 * that treated every cut endpoint as an attachment; routes never do.
 */
public final class RoutingStaticLoader
{
	/** Structural-reachability seed tile (Lumbridge). */
	static final int SEED_TILE = WorldPointUtil.packWorldPoint(3221, 3218, 0);
	/** One full {@code y} unit in the packed encoding (bit 15). */
	private static final int Y_UNIT = 1 << 15;
	/**
	 * Upper bound on the search tiles of one layer. The world has well under ten million walkable
	 * tiles; the bound only keeps a damaged layer from sizing arrays that cannot be allocated.
	 */
	private static final long MAX_SEARCH_TILES = Integer.MAX_VALUE / 16;

	private RoutingStaticLoader()
	{
	}

	/**
	 * Builds the derived {@link RoutingStatic} from the packaged component layer.
	 *
	 * @param collision     authoritative walking-neighbour source.
	 * @param rawTransports the plugin's raw, unfiltered, account-independent transports, keyed by
	 *                      packed origin tile or {@link WorldPointUtil#UNDEFINED} for origin-less
	 *                      (global) transports/teleports. Must include every transport type,
	 *                      seasonal included.
	 * @param bankTiles     the whole bank destination set, with no account filtering.
	 * @throws IOException when the layer is missing, malformed, or does not fit the collision map.
	 */
	public static RoutingStatic build(CollisionMap collision, Map<Integer, Set<Transport>> rawTransports,
		Set<Integer> bankTiles) throws IOException
	{
		try (InputStream stream = bundledLayer())
		{
			return build(collision, rawTransports, bankTiles, stream);
		}
	}

	/** Opens the packaged layer, {@code routing-components.bin}; {@code null} when it is missing. */
	public static InputStream bundledLayer()
	{
		return ComponentLayer.class.getResourceAsStream(ComponentLayer.RESOURCE);
	}

	/**
	 * As above, but reading the layer from {@code layer} (a {@code null} stream is a missing
	 * resource). The stream is not closed. The seam for loading something other than the bundled layer.
	 */
	public static RoutingStatic build(CollisionMap collision, Map<Integer, Set<Transport>> rawTransports,
		Set<Integer> bankTiles, InputStream layer) throws IOException
	{
		return build(collision, rawTransports, bankTiles, ComponentLayer.read(layer), SEED_TILE);
	}

	/** As above, from a given layer and structural reachability seed tile. */
	static RoutingStatic build(CollisionMap collision, Map<Integer, Set<Transport>> rawTransports,
		Set<Integer> bankTiles, ComponentLayer layer, int seedTile) throws IOException
	{
		// The one check that ties the layer to the exact collision data it was generated from. The
		// per-crossing and per-tile checks below only catch some of the ways a layer goes stale.
		long expected = collision.fingerprint();
		if (layer.fingerprint != expected)
			throw new IOException("routing component layer is stale: it was generated for collision data "
				+ String.format("%016x", layer.fingerprint) + " but the loaded collision map is "
				+ String.format("%016x", expected));
		for (int i = 0; i < layer.crossings.length; i += 2)
		{
			int from = layer.crossings[i];
			int to = layer.crossings[i + 1];
			if (layer.component(from) == 0 || layer.component(to) == 0)
				throw new IOException("routing component layer is stale: crossing tile "
					+ (layer.component(from) == 0 ? from : to) + " is not covered");
			int[] neighbors = collision.ordinaryWalkingNeighbors(from);
			if (!IntArrays.contains(neighbors, 0, neighbors.length, to))
				throw new IOException("routing component layer is stale: crossing " + from + " -> " + to
					+ " is not a walking edge");
		}
		int[] natural = naturalComponents(layer);
		boolean[] candidate = new boolean[natural.length];
		boolean[] reachable = structuralReachability(collision, layer, natural, candidate, rawTransports, seedTile);
		for (int tile : layer.crossings) candidate[natural[layer.component(tile)]] = true;

		// Routing components are ranked among the candidates; ranking by reachability would renumber tiles.
		int[] renumbered = new int[natural.length];
		int routingComponentCount = 1;
		for (int id = 1; id < natural.length; id++)
		{
			if (candidate[natural[id]]) renumbered[id] = routingComponentCount++;
		}

		// The reader validates each run alone, so the total is bounded here, before anything is sized from it.
		long total = 0;
		for (int run = 0; run < layer.starts.length; run++)
		{
			if (reachable[natural[layer.ids[run]]]) total += layer.lengths[run];
		}
		if (total > MAX_SEARCH_TILES)
			throw new IOException("routing component layer is stale: " + total + " search tiles");
		int count = (int) total;
		int[] tiles = new int[count];
		byte[] masks = new byte[count];
		TileComponents components = new TileComponents(count, routingComponentCount);
		int next = 0;
		for (int run = 0; run < layer.starts.length; run++)
		{
			if (!reachable[natural[layer.ids[run]]]) continue;
			for (int offset = 0; offset < layer.lengths[run]; offset++)
			{
				int tile = layer.starts[run] + offset;
				byte mask = collision.ordinaryWalkingMask(tile);
				if (mask == 0) throw new IOException("routing component layer is stale: tile " + tile + " is not walkable");
				tiles[next] = tile;
				masks[next] = mask;
				components.set(next++, renumbered[layer.ids[run]]);
			}
		}

		// The tiles ascend in unsigned packed order, so both neighbour indexes come from one sweep each.
		char[] north = new char[count];
		char[] south = new char[count];
		for (int i = 0, n = 0, s = 0; i < count; i++)
		{
			int y = WorldPointUtil.unpackWorldY(tiles[i]);
			if (y != 32767)
			{
				while (n < count && Integer.compareUnsigned(tiles[n], tiles[i] + Y_UNIT) < 0) n++;
				if (n < count && tiles[n] == tiles[i] + Y_UNIT) north[i] = (char) (n - i);
			}
			if (y != 0)
			{
				while (Integer.compareUnsigned(tiles[s], tiles[i] - Y_UNIT) < 0) s++;
				if (tiles[s] == tiles[i] - Y_UNIT) south[i] = (char) (i - s);
			}
		}

		SitesAndAttachments sites = buildSites(rawTransports, bankTiles, layer.crossings, tiles, components, collision,
			routingComponentCount);
		int crossingCount = layer.crossings.length / 2;
		int[] crossingFrom = new int[crossingCount];
		int[] crossingTo = new int[crossingCount];
		int[] crossingCost = new int[crossingCount];
		for (int i = 0; i < crossingCount; i++)
		{
			crossingFrom[i] = IntArrays.binarySearch(sites.siteTiles, layer.crossings[2 * i]);
			crossingTo[i] = IntArrays.binarySearch(sites.siteTiles, layer.crossings[2 * i + 1]);
			crossingCost[i] = 1;
		}

		// The exact walks need the search tiles and sites in their final form, so they walk a
		// first RoutingStatic without a network, and the network is built after them.
		int siteCount = sites.siteTiles.length;
		RoutingStatic walking = RoutingStatic.takeOwnership(tiles, components, masks, north, south, sites.siteTiles,
			sites.siteComponentOffsets, sites.siteComponentIds, routingComponentCount, sites.componentSiteOffsets,
			sites.componentSiteIds, sites.reachableBankTiles, crossingFrom, crossingTo, crossingCost, siteCount,
			siteCount, 0, 0, 0, new int[siteCount + 1], new int[0], new int[0]);
		ExactWalks exactWalks = ExactWalks.build(walking);
		SparseWalkingNetworkBuilder.Result sparse = SparseWalkingNetworkBuilder.build(sites.siteTiles,
			sites.siteComponentOffsets, sites.siteComponentIds, exactWalks);
		return RoutingStatic.takeOwnership(tiles, components, masks, north, south, sites.siteTiles,
			sites.siteComponentOffsets, sites.siteComponentIds, routingComponentCount, sites.componentSiteOffsets,
			sites.componentSiteIds, sites.reachableBankTiles, crossingFrom, crossingTo, crossingCost,
			sparse.originalCount, sparse.vertexCount, sparse.steinerCount, sparse.undirectedEdgeCount,
			sparse.adjacencyCount(), sparse.offsets, sparse.destinations, sparse.weights, exactWalks);
	}

	/**
	 * The natural component (the root routing component id) of every routing component id: the
	 * components the layer's crossings join. Index 0 is unused.
	 */
	static int[] naturalComponents(ComponentLayer layer)
	{
		int componentCount = 1;
		for (int id : layer.ids) componentCount = Math.max(componentCount, id + 1);
		int[] parent = new int[componentCount];
		for (int i = 0; i < componentCount; i++) parent[i] = i;
		for (int i = 0; i < layer.crossings.length; i += 2)
			parent[root(parent, layer.component(layer.crossings[i]))] = root(parent, layer.component(layer.crossings[i + 1]));
		for (int i = 0; i < componentCount; i++) parent[i] = root(parent, i);
		return parent;
	}

	private static int root(int[] parent, int id)
	{
		while (parent[id] != id)
		{
			parent[id] = parent[parent[id]];
			id = parent[id];
		}
		return id;
	}

	// ---- Structural reachability: closure over NATURAL components ----
	// Reachability must use natural, not routing, components: a cut never makes a tile unreachable.
	// The closure is an account-independent overapproximation of the geography routes can use, so it
	// deliberately follows every known transport, seasonal ones included, whatever its requirements.
	// It only prunes components nothing can reach, such as the sea. Whether an account can take a
	// transport is decided later, by PreparedRoutingAccount and the forward search.

	/**
	 * Which natural components are structurally reachable. Every component a transport endpoint or
	 * the seed attaches to is also marked in {@code candidate}.
	 */
	static boolean[] structuralReachability(CollisionMap collision, ComponentLayer layer, int[] natural,
		boolean[] candidate, Map<Integer, Set<Transport>> rawTransports, int seedTile)
	{
		Map<Integer, List<Integer>> edges = new HashMap<>();
		Set<Integer> globalDestinations = new HashSet<>();
		for (Set<Transport> set : rawTransports.values())
		{
			for (Transport transport : set)
			{
				int origin = transport.getOrigin();
				int destination = transport.getDestination();

				// attachmentEdges: every endpoint point of every transport, any type, any origin state.
				int[] originAttachments = origin == WorldPointUtil.UNDEFINED ? new int[0]
					: naturalAttachments(origin, layer, natural, collision);
				int[] destinationAttachments = naturalAttachments(destination, layer, natural, collision);
				addAttachmentClique(edges, originAttachments);
				addAttachmentClique(edges, destinationAttachments);
				for (int component : originAttachments) candidate[component] = true;
				for (int component : destinationAttachments) candidate[component] = true;

				if (origin == WorldPointUtil.UNDEFINED)
				{
					// globalDestinations: global-teleport destinations.
					for (int component : destinationAttachments) globalDestinations.add(component);
				}
				else
				{
					// transportEdges: local transports, directed origin -> destination.
					for (int fromComponent : originAttachments)
					{
						for (int toComponent : destinationAttachments)
							edges.computeIfAbsent(fromComponent, k -> new ArrayList<>()).add(toComponent);
					}
				}
			}
		}

		int[] seedComponents = naturalAttachments(seedTile, layer, natural, collision);
		if (seedComponents.length == 0)
		{
			throw new IllegalStateException(
				"missing structural reachability seed: no natural component attaches to the production seed tile");
		}

		boolean[] reachable = new boolean[natural.length];
		ArrayDeque<Integer> queue = new ArrayDeque<>();
		for (int seed : seedComponents)
		{
			candidate[seed] = true;
			if (!reachable[seed])
			{
				reachable[seed] = true;
				queue.add(seed);
			}
		}
		while (!queue.isEmpty())
		{
			int component = queue.poll();
			for (int next : edges.getOrDefault(component, List.of()))
			{
				if (!reachable[next])
				{
					reachable[next] = true;
					queue.add(next);
				}
			}
			for (int global : globalDestinations)
			{
				if (!reachable[global])
				{
					reachable[global] = true;
					queue.add(global);
				}
			}
		}
		return reachable;
	}

	private static void addAttachmentClique(Map<Integer, List<Integer>> edges, int[] attachments)
	{
		if (attachments.length < 2) return;
		for (int a : attachments)
		{
			for (int b : attachments)
			{
				if (a != b) edges.computeIfAbsent(a, k -> new ArrayList<>()).add(b);
			}
		}
	}

	/**
	 * Natural components a point attaches to: its own component if it is walkable, otherwise
	 * the union of its ordinary walking neighbours' components.
	 */
	private static int[] naturalAttachments(int point, ComponentLayer layer, int[] natural, CollisionMap collision)
	{
		int id = layer.component(point);
		if (id != 0) return new int[] {natural[id]};
		int[] buffer = new int[8];
		int count = 0;
		for (int neighbor : collision.ordinaryWalkingNeighbors(point))
		{
			int neighborId = layer.component(neighbor);
			if (neighborId != 0 && !IntArrays.contains(buffer, 0, count, natural[neighborId]))
				buffer[count++] = natural[neighborId];
		}
		return Arrays.copyOf(buffer, count);
	}

	// ---- Sites and attachments ----

	@AllArgsConstructor
	private static final class SitesAndAttachments
	{
		final int[] siteTiles, siteComponentOffsets, siteComponentIds, componentSiteOffsets, componentSiteIds;
		final int[] reachableBankTiles;
	}

	private static SitesAndAttachments buildSites(Map<Integer, Set<Transport>> rawTransports, Set<Integer> bankTiles,
		int[] crossings, int[] tiles, TileComponents components, CollisionMap collision, int routingComponentCount)
	{
		HashSet<Integer> siteSet = new HashSet<>();
		for (Set<Transport> set : rawTransports.values())
		{
			for (Transport transport : set)
			{
				if (transport.getOrigin() != WorldPointUtil.UNDEFINED) siteSet.add(transport.getOrigin());
				siteSet.add(transport.getDestination());
			}
		}
		for (int tile : crossings) siteSet.add(tile);
		List<Integer> reachableBanks = new ArrayList<>();
		for (int bank : bankTiles)
		{
			if (routingAttachments(bank, tiles, components, collision).length > 0)
			{
				reachableBanks.add(bank);
				siteSet.add(bank);
			}
		}

		int[] siteTiles = toSortedUnsignedArray(siteSet);
		int[] reachableBankTiles = toSortedUnsignedArray(reachableBanks);

		int[] siteComponentOffsets = new int[siteTiles.length + 1];
		int[][] perSite = new int[siteTiles.length][];
		int totalSiteComponentValues = 0;
		for (int i = 0; i < siteTiles.length; i++)
		{
			perSite[i] = routingAttachments(siteTiles[i], tiles, components, collision);
			siteComponentOffsets[i + 1] = siteComponentOffsets[i] + perSite[i].length;
			totalSiteComponentValues += perSite[i].length;
		}
		int[] siteComponentIds = new int[totalSiteComponentValues];
		int cursor = 0;
		for (int[] siteComponents : perSite)
		{
			for (int component : siteComponents) siteComponentIds[cursor++] = component;
		}

		int[] groupCounts = new int[routingComponentCount];
		for (int component : siteComponentIds) groupCounts[component]++;
		int[] componentSiteOffsets = new int[routingComponentCount + 1];
		for (int i = 0; i < routingComponentCount; i++)
			componentSiteOffsets[i + 1] = componentSiteOffsets[i] + groupCounts[i];
		int[] componentSiteIds = new int[componentSiteOffsets[routingComponentCount]];
		int[] fillCursor = Arrays.copyOf(componentSiteOffsets, componentSiteOffsets.length);
		for (int site = 0; site < siteTiles.length; site++)
		{
			for (int p = siteComponentOffsets[site]; p < siteComponentOffsets[site + 1]; p++)
				componentSiteIds[fillCursor[siteComponentIds[p]]++] = site;
		}

		return new SitesAndAttachments(siteTiles, siteComponentOffsets, siteComponentIds, componentSiteOffsets,
			componentSiteIds, reachableBankTiles);
	}

	/**
	 * Routing components a point attaches to, using the final reachability-filtered search tiles:
	 * the tile's own component if it is a search tile, otherwise those of its walking neighbours.
	 * This matches {@link RoutingStatic#attachments} at runtime.
	 */
	private static int[] routingAttachments(int point, int[] tiles, TileComponents components, CollisionMap collision)
	{
		int index = IntArrays.binarySearch(tiles, point);
		if (index >= 0) return new int[] {components.get(index)};
		int[] buffer = new int[8];
		int count = 0;
		for (int neighbor : collision.ordinaryWalkingNeighbors(point))
		{
			int neighborIndex = IntArrays.binarySearch(tiles, neighbor);
			if (neighborIndex >= 0 && !IntArrays.contains(buffer, 0, count, components.get(neighborIndex)))
				buffer[count++] = components.get(neighborIndex);
		}
		Arrays.sort(buffer, 0, count);
		return Arrays.copyOf(buffer, count);
	}

	private static int[] toSortedUnsignedArray(Collection<Integer> values)
	{
		int[] result = new int[values.size()];
		int i = 0;
		for (int value : values) result[i++] = value;
		sortUnsigned(result);
		return result;
	}

	private static void sortUnsigned(int[] values)
	{
		for (int i = 0; i < values.length; i++) values[i] ^= Integer.MIN_VALUE;
		Arrays.sort(values);
		for (int i = 0; i < values.length; i++) values[i] ^= Integer.MIN_VALUE;
	}
}

package shortestpath.pathfinder.astar;

import java.util.function.IntPredicate;
import shortestpath.pathfinder.WildernessChecker;
import lombok.AllArgsConstructor;

/**
 * Per-search positional restrictions applied on top of the prepared graph, mirroring the gates
 * the legacy pathfinder checks while relaxing edges ({@code avoidWilderness} and the league's
 * always-blocked region).
 *
 * <p>They are per-search rather than part of the account identity: the underlying setting can
 * change on every config refresh, and enforcing them removes edges instead of adding any, so
 * the prepared target's heuristic only ever under-estimates the restricted graph's distances and
 * stays admissible. Sessions may therefore reuse prepared accounts, targets and heuristics
 * across searches regardless of these settings.
 */
@AllArgsConstructor
public final class SearchRestrictions
{
	private static final SearchRestrictions NONE = new SearchRestrictions(false, null);

	/** Avoid stepping or teleporting into the wilderness from outside it. */
	private final boolean avoidWilderness;
	/** Whether a tile lies in the league's always-blocked region, or {@code null} when the gate is off. */
	private final IntPredicate blockedRegion;



	/** No gates: every edge the graph offers may be relaxed. */
	public static SearchRestrictions none()
	{
		return NONE;
	}

	/**
	 * @param avoidWilderness bar steps and global teleports that enter the wilderness from
	 *                        outside it; the caller folds in legacy's exemption for a target in
	 *                        the wilderness
	 * @param blockedRegion   tests whether a tile lies in the league's always-blocked region, or
	 *                        {@code null} when the gate is off (a non-seasonal world, or a target
	 *                        inside the blocked region lifting the gate, as in legacy)
	 */
	public static SearchRestrictions of(boolean avoidWilderness, IntPredicate blockedRegion)
	{
		return avoidWilderness || blockedRegion != null ? new SearchRestrictions(avoidWilderness, blockedRegion)
			: NONE;
	}

	/** Whether any gate is active; when false, relaxing an edge never asks for a tile's status. */
	boolean anyGate()
	{
		return avoidWilderness || blockedRegion != null;
	}

	boolean avoidsWilderness()
	{
		return avoidWilderness;
	}

	/** Whether {@code tile} is inside the league's always-blocked region; false when the gate is off. */
	boolean inBlockedRegion(int tile)
	{
		return blockedRegion != null && blockedRegion.test(tile);
	}

	/**
	 * Whether a walking step between adjacent tiles may be relaxed, including the step onto a
	 * blocked transport origin. Like legacy, crossing into the wilderness or the blocked region
	 * is barred while moving inside either area, or out of it, is allowed.
	 */
	public boolean stepAllowed(int fromTile, int toTile)
	{
		if (!anyGate())
		{
			return true;
		}
		return stepAllowed(WildernessChecker.isInWilderness(fromTile), WildernessChecker.isInWilderness(toTile),
			inBlockedRegion(fromTile), inBlockedRegion(toTile));
	}

	boolean stepAllowed(boolean fromWilderness, boolean toWilderness, boolean fromBlocked, boolean toBlocked)
	{
		if (avoidWilderness && !fromWilderness && toWilderness)
		{
			return false;
		}
		return blockedRegion == null || fromBlocked || !toBlocked;
	}

	/**
	 * Whether a global teleport cast with {@code capability} may land on {@code destination}.
	 * {@link TeleportCapability#ALL} means the cast happens outside the wilderness, so a
	 * wilderness landing is barred while avoiding it; a cast from inside the wilderness
	 * (any {@code OVER_*} capability) may land inside it, as in legacy.
	 */
	boolean globalAllowed(TeleportCapability capability, int destination)
	{
		return !avoidWilderness || capability != TeleportCapability.ALL
			|| !WildernessChecker.isInWilderness(destination);
	}
}

package shortestpath.pathfinder.astar;

import java.util.Arrays;
import shortestpath.pathfinder.BankVisitState;
import lombok.Getter;
import lombok.experimental.Accessors;

/** Immutable two-layer account-specific site graph with reverse CSR edges. */
public final class SiteGraph
{
	public enum EdgeKind
	{
		LOCAL,
		BANK_TRANSITION,
		BANK_GLOBAL_ENTRY,
		BANK_GLOBAL_DESTINATION,
		SEPARATOR
	}

	private final RoutingStatic stat;
	private final PreparedRoutingAccount account;
	@Getter @Accessors(fluent = true) private final int nodeCount;
	@Getter @Accessors(fluent = true) private final boolean hasBankedGlobalHub;
	private final int[] reverseOffsets;
	private final int[] reverseFromStates;
	private final int[] reverseCosts;
	private final boolean[] reverseStartsGenerator;
	private final byte[] reverseKinds;

	public SiteGraph(RoutingStatic stat, PreparedRoutingAccount account)
	{
		this.stat = stat;
		this.account = account;
		int spatialCount = stat.siteCount();
		validateEndpoints(account, stat);
		int[] bankSites = bankSites(stat, account);
		int[] globalDestinations = globalDestinations(account, stat);
		hasBankedGlobalHub = account.allowTransports() && account.bankPathEnabled() && bankSites.length != 0
			&& globalDestinations.length != 0;
		nodeCount = spatialCount + (hasBankedGlobalHub ? 1 : 0);

		EdgeBuilder edges = new EdgeBuilder();
		addLocalEdges(edges, account.localView(BankVisitState.CARRIED), BankVisitState.CARRIED, stat);
		addLocalEdges(edges, account.localView(BankVisitState.BANKED), BankVisitState.BANKED, stat);
		if (account.bankPathEnabled())
		{
			for (int bankSite : bankSites)
			{
				edges.add(stateId(bankSite, BankVisitState.CARRIED), stateId(bankSite, BankVisitState.BANKED),
					account.bankVisitCost(), true, EdgeKind.BANK_TRANSITION);
			}
		}
		if (hasBankedGlobalHub)
		{
			int hub = spatialCount;
			for (int bankSite : bankSites)
			{
				edges.add(stateId(bankSite, BankVisitState.CARRIED), stateId(hub, BankVisitState.BANKED),
					account.bankVisitCost(), true, EdgeKind.BANK_GLOBAL_ENTRY);
			}
			for (int destination : globalDestinations)
			{
				int cost = minimumGlobalCost(account.globalView(BankVisitState.BANKED), destination);
				if (cost != CostArithmetic.INF)
				{
					edges.add(stateId(hub, BankVisitState.BANKED), stateId(stat.siteIndex(destination), BankVisitState.BANKED),
						cost, false, EdgeKind.BANK_GLOBAL_DESTINATION);
				}
			}
		}
		for (int i = 0; i < stat.crossingCount(); i++)
		{
			int from = stat.crossingFromSite(i);
			int to = stat.crossingToSite(i);
			int cost = CostArithmetic.validate(stat.crossingCost(i));
			for (BankVisitState banked : BankVisitState.values())
			{
				edges.add(stateId(from, banked), stateId(to, banked), cost, true, EdgeKind.SEPARATOR);
				edges.add(stateId(to, banked), stateId(from, banked), cost, true, EdgeKind.SEPARATOR);
			}
		}
		Csr csr = edges.build(nodeCount * 2);
		reverseOffsets = csr.offsets;
		reverseFromStates = csr.fromStates;
		reverseCosts = csr.costs;
		reverseStartsGenerator = csr.startsGenerator;
		reverseKinds = csr.kinds;
	}

	public static SiteGraph compile(RoutingStatic stat, PreparedRoutingAccount account)
	{
		return new SiteGraph(stat, account);
	}

	public RoutingStatic routingStatic()
	{
		return stat;
	}
	public PreparedRoutingAccount preparedAccount()
	{
		return account;
	}
	public int spatialNodeCount()
	{
		return stat.siteCount();
	}

	public int stateCount()
	{
		return nodeCount * 2;
	}

	public int bankedGlobalHubNode()
	{
		return hasBankedGlobalHub ? stat.siteCount() : -1;
	}
	public int siteTile(int node)
	{
		return stat.siteTile(node);
	}
	public int nodeForTile(int tile)
	{
		return stat.siteIndex(tile);
	}

	public int reverseEdgeCount()
	{
		return reverseFromStates.length;
	}
	public int reverseEdgeStart(int state)
	{
		return reverseOffsets[state];
	}
	public int reverseEdgeEnd(int state)
	{
		return reverseOffsets[state + 1];
	}
	public int reverseFromState(int edge)
	{
		return reverseFromStates[edge];
	}
	public int reverseCost(int edge)
	{
		return reverseCosts[edge];
	}
	public boolean reverseStartsGenerator(int edge)
	{
		return reverseStartsGenerator[edge];
	}
	public EdgeKind reverseKind(int edge)
	{
		return EdgeKind.values()[reverseKinds[edge]];
	}

	public static int stateId(int node, BankVisitState banked)
	{
		if (node < 0)
			throw new IllegalArgumentException("negative site node");
		return node * 2 + (banked == BankVisitState.BANKED ? 1 : 0);
	}

	private static void addLocalEdges(
		EdgeBuilder edges, PreparedRoutingAccount.View view, BankVisitState banked, RoutingStatic stat)
	{
		for (int i = 0; i < view.destinations.length; i++)
		{
			int from = stat.siteIndex(view.origins[i]);
			int to = stat.siteIndex(view.destinations[i]);
			if (view.costs[i] != CostArithmetic.INF)
			{
				edges.add(stateId(from, banked), stateId(to, banked), view.costs[i], true, EdgeKind.LOCAL);
			}
		}
	}

	private static void validateEndpoints(PreparedRoutingAccount account, RoutingStatic stat)
	{
		for (BankVisitState banked : BankVisitState.values())
		{
			PreparedRoutingAccount.View local = account.localView(banked);
			for (int i = 0; i < local.destinations.length; i++)
			{
				requireSite(stat, local.origins[i], "local origin");
				requireSite(stat, local.destinations[i], "local destination");
			}
			PreparedRoutingAccount.View global = account.globalView(banked);
			for (int i = 0; i < global.destinations.length; i++)
				requireSite(stat, global.destinations[i], "global destination");
		}
	}

	private static void requireSite(RoutingStatic stat, int tile, String label)
	{
		if (stat.siteIndex(tile) < 0)
		{
			throw new IllegalStateException(label + " is not a static site: " + Integer.toUnsignedString(tile));
		}
	}

	/** The static bank sites this account may use. */
	private static int[] bankSites(RoutingStatic stat, PreparedRoutingAccount account)
	{
		int[] result = new int[stat.reachableBankCount()];
		int count = 0;
		for (int i = 0; i < result.length; i++)
		{
			int tile = stat.reachableBankTile(i);
			int site = stat.siteIndex(tile);
			if (site < 0)
				throw new IllegalStateException("reachable bank is not a static site");
			if (account.bankAccessible(tile))
				result[count++] = site;
		}
		return Arrays.copyOf(result, count);
	}

	private static int[] globalDestinations(PreparedRoutingAccount account, RoutingStatic stat)
	{
		PreparedRoutingAccount.View view = account.globalView(BankVisitState.BANKED);
		int[] result = new int[view.destinations.length];
		int count = 0;
		for (int i = 0; i < view.destinations.length; i++)
		{
			int destination = view.destinations[i];
			boolean present = false;
			for (int j = 0; j < count; j++)
				present |= result[j] == destination;
			if (!present)
				result[count++] = destination;
		}
		result = Arrays.copyOf(result, count);
		for (int i = 1; i < count; i++)
		{
			int value = result[i];
			int j = i - 1;
			while (j >= 0 && Integer.compareUnsigned(result[j], value) > 0)
			{
				result[j + 1] = result[j--];
			}
			result[j + 1] = value;
		}
		for (int destination : result)
			requireSite(stat, destination, "global destination");
		return result;
	}

	private static int minimumGlobalCost(PreparedRoutingAccount.View view, int destination)
	{
		int minimum = CostArithmetic.INF;
		for (int i = 0; i < view.destinations.length; i++)
		{
			if (view.destinations[i] == destination && view.costs[i] < minimum)
				minimum = view.costs[i];
		}
		return minimum;
	}

	private static final class EdgeBuilder
	{
		private int size;
		private int[] from = new int[64], to = new int[64], costs = new int[64];
		private boolean[] starts = new boolean[64];
		private byte[] kinds = new byte[64];

		void add(int fromState, int toState, int cost, boolean startsGenerator, EdgeKind kind)
		{
			CostArithmetic.validate(cost);
			if (cost == CostArithmetic.INF)
				return;
			if (size == from.length)
			{
				int capacity = size * 2;
				from = Arrays.copyOf(from, capacity);
				to = Arrays.copyOf(to, capacity);
				costs = Arrays.copyOf(costs, capacity);
				starts = Arrays.copyOf(starts, capacity);
				kinds = Arrays.copyOf(kinds, capacity);
			}
			from[size] = fromState;
			to[size] = toState;
			costs[size] = cost;
			starts[size] = startsGenerator;
			kinds[size++] = (byte) kind.ordinal();
		}

		Csr build(int stateCount)
		{
			int[] offsets = new int[stateCount + 1];
			for (int i = 0; i < size; i++)
				offsets[to[i] + 1]++;
			for (int i = 1; i < offsets.length; i++)
				offsets[i] += offsets[i - 1];
			int[] positions = Arrays.copyOfRange(offsets, 1, offsets.length);
			int[] sortedFrom = new int[size], sortedCosts = new int[size];
			boolean[] sortedStarts = new boolean[size];
			byte[] sortedKinds = new byte[size];
			for (int i = 0; i < size; i++)
			{
				int position = --positions[to[i]];
				sortedFrom[position] = from[i];
				sortedCosts[position] = costs[i];
				sortedStarts[position] = starts[i];
				sortedKinds[position] = kinds[i];
			}
			return new Csr(offsets, sortedFrom, sortedCosts, sortedStarts, sortedKinds);
		}
	}

	private static final class Csr
	{
		final int[] offsets, fromStates, costs;
		final boolean[] startsGenerator;
		final byte[] kinds;

		Csr(int[] offsets, int[] fromStates, int[] costs, boolean[] startsGenerator, byte[] kinds)
		{
			this.offsets = offsets;
			this.fromStates = fromStates;
			this.costs = costs;
			this.startsGenerator = startsGenerator;
			this.kinds = kinds;
		}
	}
}

package shortestpath.pathfinder.astar;

import java.util.*;
import shortestpath.*;

/**
 * Builds the sparse same-component walking network used by {@link ReverseLabels#computeSparse}.
 *
 * <p>Within each routing component, walking distance between two sites on the same plane is at
 * least their Chebyshev distance. Instead of connecting every pair of sites, the construction
 * works in rotated Manhattan coordinates {@code a = x + y}, {@code b = x - y}, where Manhattan
 * distance is exactly twice Chebyshev distance, and adds Steiner vertices along balanced
 * coordinate splits so that the shortest path between any two sites equals that distance.
 * Every edge weight is therefore doubled walking distance; {@link ReverseLabels#computeSparse}
 * halves it once at the end.
 */
public final class SparseWalkingNetworkBuilder
{
	private SparseWalkingNetworkBuilder()
	{
	}

	/** Section G in flat, undirected CSR form (adjacencyCount == 2 * undirectedEdgeCount). */
	public static final class Result
	{
		public final int originalCount;
		public final int vertexCount;
		public final int steinerCount;
		public final int undirectedEdgeCount;
		public final int[] offsets;
		public final int[] destinations;
		public final int[] weights;

		private Result(int originalCount, int vertexCount, int steinerCount, int undirectedEdgeCount, int[] offsets,
			int[] destinations, int[] weights)
		{
			this.originalCount = originalCount;
			this.vertexCount = vertexCount;
			this.steinerCount = steinerCount;
			this.undirectedEdgeCount = undirectedEdgeCount;
			this.offsets = offsets;
			this.destinations = destinations;
			this.weights = weights;
		}

		public int adjacencyCount()
		{
			return destinations.length;
		}
	}

	/**
	 * Builds the network from the static sites and their routing-component attachments:
	 *
	 * <ul>
	 *   <li>{@code siteTiles[s]}: packed tile of site {@code s}, ascending.</li>
	 *   <li>{@code siteComponentOffsets}, {@code siteComponentIds}: each site's ascending
	 *       routing-component attachments. A site attached to several components contributes
	 *       one point to each component, all sharing the same site vertex.</li>
	 * </ul>
	 *
	 * <p>Vertices {@code 0..siteTiles.length-1} are the sites, followed by Steiner vertices. A
	 * site with no component attachment is an isolated vertex.
	 *
	 * @param siteTiles              packed tiles, ascending unsigned packed order, one per site
	 * @param siteComponentOffsets   length {@code siteTiles.length + 1}, CSR offsets into {@code siteComponentIds}
	 * @param siteComponentIds       routing-component ids per site, ascending within each site's range
	 * @return the flattened CSR sparse walking network (section G)
	 */
	public static Result build(int[] siteTiles, int[] siteComponentOffsets, int[] siteComponentIds)
	{
		return build(siteTiles, siteComponentOffsets, siteComponentIds, null);
	}

	/**
	 * As {@link #build(int[], int[], int[])}, but each {@link ExactWalks#isExact exact} component's
	 * sites are joined by its exact walking edges instead of a tree.
	 */
	static Result build(int[] siteTiles, int[] siteComponentOffsets, int[] siteComponentIds, ExactWalks exactWalks)
	{
		int originalCount = siteTiles.length;
		int maxComponentId = -1;
		for (int cid : siteComponentIds)
		{
			if (cid > maxComponentId)
			{
				maxComponentId = cid;
			}
		}
		int componentCount = maxComponentId + 1;

		// Bucket sites by component id; only components that own at least one site are processed,
		// in ascending id order.
		int[] bucketCounts = new int[componentCount];
		for (int cid : siteComponentIds)
		{
			bucketCounts[cid]++;
		}
		int[] bucketOffsets = new int[componentCount + 1];
		for (int c = 0; c < componentCount; c++)
		{
			bucketOffsets[c + 1] = bucketOffsets[c] + bucketCounts[c];
		}
		int[] bucketSites = new int[siteComponentIds.length];
		int[] cursor = bucketOffsets.clone();
		for (int site = 0; site < originalCount; site++)
		{
			for (int p = siteComponentOffsets[site]; p < siteComponentOffsets[site + 1]; p++)
			{
				int cid = siteComponentIds[p];
				bucketSites[cursor[cid]++] = site;
			}
		}

		PrimitiveIntList edges = new PrimitiveIntList(48);
		int next = originalCount;
		for (int cid = 0; cid < componentCount; cid++)
		{
			int start = bucketOffsets[cid];
			int end = bucketOffsets[cid + 1];
			int size = end - start;
			if (size == 0)
			{
				continue;
			}
			if (exactWalks != null && exactWalks.isExact(cid))
			{
				// Exact walking edges instead of a tree, doubled like every other weight.
				int[] triples = exactWalks.edges(cid);
				for (int i = 0; i < triples.length; i += 3)
					addEdge(edges, triples[i], triples[i + 1], CostArithmetic.twice(triples[i + 2]));
				continue;
			}
			Point[] points = new Point[size];
			for (int i = 0; i < size; i++)
			{
				int siteIndex = bucketSites[start + i];
				int tile = siteTiles[siteIndex];
				int x = WorldPointUtil.unpackWorldX(tile);
				int y = WorldPointUtil.unpackWorldY(tile);
				points[i] = new Point(siteIndex, x + y, x - y);
			}
			Arrays.sort(points, BY_A_B_ORIGINAL);
			next = buildComponent(next, points, edges);
		}

		int vertexCount = next;
		int steinerCount = vertexCount - originalCount;
		return undirectedAdjacency(originalCount, vertexCount, steinerCount, edges);
	}

	private enum Axis
	{
		A, B
	}

	private static final class Point
	{
		final int original;
		final int a;
		final int b;

		Point(int original, int a, int b)
		{
			this.original = original;
			this.a = a;
			this.b = b;
		}
	}

	private static final Comparator<Point> BY_A_B_ORIGINAL = (x, y) ->
	{
		if (x.a != y.a)
		{
			return Integer.compare(x.a, y.a);
		}
		if (x.b != y.b)
		{
			return Integer.compare(x.b, y.b);
		}
		return Integer.compare(x.original, y.original);
	};

	private static int coordOf(Axis axis, Point p)
	{
		return axis == Axis.A ? p.a : p.b;
	}

	private static int otherCoordOf(Axis axis, Point p)
	{
		return axis == Axis.A ? p.b : p.a;
	}

	private static Comparator<Point> axisComparator(Axis axis)
	{
		return (x, y) ->
		{
			int cx = coordOf(axis, x);
			int cy = coordOf(axis, y);
			if (cx != cy)
			{
				return Integer.compare(cx, cy);
			}
			return BY_A_B_ORIGINAL.compare(x, y);
		};
	}

	/**
	 * Recursively splits one component's points. {@code pts} arrives in inherited order (the
	 * global {@code a,b,original} sort at the top level, or a slice of the parent split's
	 * axis-sorted list below it); that order, not any re-sort here, decides which Steiner vertex
	 * id each point receives in {@link #addProjectionLevel}, keeping numbering deterministic.
	 */
	private static int buildComponent(int next, Point[] pts, PrimitiveIntList edges)
	{
		if (pts.length <= 1)
		{
			return next;
		}
		int a0 = pts[0].a;
		int b0 = pts[0].b;
		boolean allSameA = true;
		boolean allSameB = true;
		for (Point p : pts)
		{
			if (p.a != a0)
			{
				allSameA = false;
			}
			if (p.b != b0)
			{
				allSameB = false;
			}
		}
		if (allSameA && allSameB)
		{
			// Coincident points are chained with zero-weight edges; pts is already sorted by `original`
			// here, since a/b are constant and the inherited order derives from a sort
			// keyed on (axis-or-a-b, a, b, original).
			for (int i = 0; i + 1 < pts.length; i++)
			{
				addEdge(edges, pts[i].original, pts[i + 1].original, 0);
			}
			return next;
		}
		Axis axis = allSameA ? Axis.B : Axis.A;
		return splitOn(axis, next, pts, edges);
	}

	/** Splits {@code pts} at the most balanced gap along {@code axis} and recurses on both halves. */
	private static int splitOn(Axis axis, int next, Point[] pts, PrimitiveIntList edges)
	{
		Point[] sorted = pts.clone();
		Arrays.sort(sorted, axisComparator(axis));
		int split = balancedGapSplit(axis, sorted);
		Point[] left = Arrays.copyOfRange(sorted, 0, split);
		Point[] right = Arrays.copyOfRange(sorted, split, sorted.length);
		int splitCoordinate = Math.floorDiv(
			coordOf(axis, sorted[split - 1]) + coordOf(axis, sorted[split]), 2);
		int afterProjection = addProjectionLevel(axis, splitCoordinate, next, pts, edges);
		int afterLeft = buildComponent(afterProjection, left, edges);
		return buildComponent(afterLeft, right, edges);
	}

	/**
	 * Returns the split index {@code i}: {@code sorted[0..i)} and {@code sorted[i..)} lie on
	 * either side of the chosen gap; the caller
	 * derives the Steiner splitter coordinate from the pair straddling that index.
	 */
	private static int balancedGapSplit(Axis axis, Point[] sorted)
	{
		int n = sorted.length;
		int preferred = n / 2;
		int bestIndex = -1;
		int bestDiff = Integer.MAX_VALUE;
		for (int i = 1; i < n; i++)
		{
			if (coordOf(axis, sorted[i - 1]) < coordOf(axis, sorted[i]))
			{
				int diff = Math.abs(i - preferred);
				if (diff < bestDiff)
				{
					bestDiff = diff;
					bestIndex = i;
				}
			}
		}
		if (bestIndex < 0)
		{
			throw new IllegalStateException("sparse walking split without a strict coordinate gap");
		}
		return bestIndex;
	}

	/**
	 * Allocates one fresh
	 * Steiner vertex per point in {@code pts} (in {@code pts}'s own order), a spoke edge
	 * from each point to its projection vertex, then chains the projections in ascending
	 * order of the other axis coordinate (ties by original site index).
	 */
	private static int addProjectionLevel(Axis axis, int splitCoordinate, int firstProjection, Point[] pts,
		PrimitiveIntList edges)
	{
		int count = pts.length;
		int[] steinerIds = new int[count];
		for (int i = 0; i < count; i++)
		{
			steinerIds[i] = firstProjection + i;
			addEdge(edges, pts[i].original, steinerIds[i], Math.abs(coordOf(axis, pts[i]) - splitCoordinate));
		}
		Integer[] order = new Integer[count];
		for (int i = 0; i < count; i++)
		{
			order[i] = i;
		}
		Arrays.sort(order, (x, y) ->
		{
			int ox = otherCoordOf(axis, pts[x]);
			int oy = otherCoordOf(axis, pts[y]);
			if (ox != oy)
			{
				return Integer.compare(ox, oy);
			}
			return Integer.compare(pts[x].original, pts[y].original);
		});
		for (int i = 0; i + 1 < count; i++)
		{
			int leftIndex = order[i];
			int rightIndex = order[i + 1];
			int weight = Math.abs(otherCoordOf(axis, pts[leftIndex]) - otherCoordOf(axis, pts[rightIndex]));
			addEdge(edges, steinerIds[leftIndex], steinerIds[rightIndex], weight);
		}
		return firstProjection + count;
	}

	/** Appends one (from, to, weight) edge to the interleaved edge list. */
	private static void addEdge(PrimitiveIntList edges, int from, int to, int weight)
	{
		edges.add(from);
		edges.add(to);
		edges.add(weight);
	}

	/**
	 * Materialises both directions of every edge as CSR adjacency. The order of entries within
	 * one vertex's range does not affect any distance.
	 */
	private static Result undirectedAdjacency(int originalCount, int vertexCount, int steinerCount, PrimitiveIntList edges)
	{
		int edgeCount = edges.size() / 3;
		int[] counts = new int[vertexCount];
		for (int i = 0; i < edgeCount; i++)
		{
			counts[edges.get(3 * i)]++;
			counts[edges.get(3 * i + 1)]++;
		}
		int[] offsets = new int[vertexCount + 1];
		for (int v = 0; v < vertexCount; v++)
		{
			offsets[v + 1] = offsets[v] + counts[v];
		}
		int[] destinations = new int[offsets[vertexCount]];
		int[] weights = new int[offsets[vertexCount]];
		int[] cursor = offsets.clone();
		for (int i = 0; i < edgeCount; i++)
		{
			int a = edges.get(3 * i);
			int b = edges.get(3 * i + 1);
			int w = edges.get(3 * i + 2);
			destinations[cursor[a]] = b;
			weights[cursor[a]] = w;
			cursor[a]++;
			destinations[cursor[b]] = a;
			weights[cursor[b]] = w;
			cursor[b]++;
		}
		return new Result(originalCount, vertexCount, steinerCount, edgeCount, offsets, destinations, weights);
	}
}

package shortestpath.pathfinder.astar;

import java.util.Arrays;
import shortestpath.pathfinder.*;
import lombok.*;
import lombok.experimental.Accessors;

/**
 * Query-local target sites and their point-attachment walking edges.
 *
 * <p>An overlay holds one or more target tiles; a search towards it ends at whichever target is
 * cheapest to reach. Targets that are static sites reuse their site node; every other target gets
 * its own synthetic node appended after the account graph's nodes, in target order.
 */
public final class TargetOverlay
{
	@Getter @Accessors(fluent = true) private final SiteGraph graph;
	private final RoutingStatic stat;
	@Getter @Accessors(fluent = true) private final PreparedRoutingAccount account;
	@Getter @Accessors(fluent = true) private final long accountFingerprint;
	@Getter(AccessLevel.PACKAGE) @Accessors(fluent = true) private final CollisionMap collision;
	private final int[] packed;
	private final byte[] terminalLayers;
	private final int[] nodes;
	private final int[][] components;
	private final int[][] attachmentSites;
	private final int[][] attachmentCosts;
	private final int[] syntheticTargets;

	public TargetOverlay(SiteGraph graph, CollisionMap collision, int packed)
	{
		this(graph, collision, new int[] {packed});
	}

	public TargetOverlay(SiteGraph graph, CollisionMap collision, int[] packedTargets)
	{
		this(graph, collision, canonicalTargets(packedTargets, null));
	}

	/** Masks use 1 for carried and 2 for banked; duplicate tiles union their layers. */
	public TargetOverlay(SiteGraph graph, CollisionMap collision, int[] packedTargets, int[] terminalLayers)
	{
		this(graph, collision, canonicalTargets(packedTargets, java.util.Objects.requireNonNull(terminalLayers)));
	}

	TargetOverlay(SiteGraph graph, CollisionMap collision, long[] targets)
	{
		if (graph == null || collision == null)
			throw new NullPointerException();
		this.graph = graph;
		this.stat = graph.routingStatic();
		this.account = graph.preparedAccount();
		this.accountFingerprint = account.fingerprint();
		this.collision = collision;
		this.packed = new int[targets.length];
		this.terminalLayers = new byte[targets.length];
		for (int i = 0; i < targets.length; i++)
		{
			packed[i] = (int) (targets[i] >>> 2);
			this.terminalLayers[i] = (byte) (targets[i] & 3);
		}
		if (packed.length == 0)
			throw new IllegalArgumentException("target overlay needs at least one target");
		int count = packed.length;
		nodes = new int[count];
		components = new int[count][];
		attachmentSites = new int[count][];
		attachmentCosts = new int[count][];
		int[] synthetic = new int[count];
		int syntheticCount = 0;
		for (int target = 0; target < count; target++)
		{
			int existing = graph.nodeForTile(packed[target]);
			if (existing >= 0)
			{
				nodes[target] = existing;
				components[target] = stat.siteComponents(existing);
			}
			else
			{
				nodes[target] = graph.nodeCount() + syntheticCount;
				synthetic[syntheticCount++] = target;
				components[target] = stat.attachments(packed[target], collision);
			}
			attach(target);
		}
		syntheticTargets = Arrays.copyOf(synthetic, syntheticCount);
	}


	public RoutingStatic routingStatic()
	{
		return stat;
	}

	public int queryNodeCount()
	{
		return graph.nodeCount() + syntheticTargets.length;
	}

	public int targetCount()
	{
		return packed.length;
	}
	/** The target tiles, in unsigned order. */
	public int[] packedTargets()
	{
		return packed.clone();
	}
	public int packedTarget(int target)
	{
		return packed[target];
	}
	/** Index of {@code tile} among the targets, or a negative value if it is not a target. */
	public int targetIndex(int tile)
	{
		if (packed.length == 1)
			return packed[0] == tile ? 0 : -1;
		int low = 0, high = packed.length - 1;
		while (low <= high)
		{
			int middle = (low + high) >>> 1, compare = Integer.compareUnsigned(packed[middle], tile);
			if (compare == 0) return middle;
			if (compare < 0) low = middle + 1; else high = middle - 1;
		}
		return -1;
	}
	public boolean isTarget(int tile)
	{
		return targetIndex(tile) >= 0;
	}
	public int targetLayers(int target)
	{
		return terminalLayers[target];
	}
	boolean isTerminal(int target, BankVisitState banked)
	{
		return (terminalLayers[target] & (banked == BankVisitState.BANKED ? 2 : 1)) != 0;
	}
	public boolean accepts(int tile, BankVisitState banked)
	{
		int target = targetIndex(tile);
		return target >= 0 && isTerminal(target, banked);
	}
	public int targetNode(int target)
	{
		return nodes[target];
	}
	public boolean synthetic(int target)
	{
		return nodes[target] >= graph.nodeCount();
	}
	public int[] components(int target)
	{
		return components[target].clone();
	}
	int[] componentsView(int target)
	{
		return components[target];
	}
	public int attachmentCount(int target)
	{
		return attachmentSites[target].length;
	}
	public int attachmentSite(int target, int index)
	{
		return attachmentSites[target][index];
	}
	public int attachmentCost(int target, int index)
	{
		return attachmentCosts[target][index];
	}
	public int targetState(int target, BankVisitState banked)
	{
		return SiteGraph.stateId(nodes[target], banked);
	}

	public int syntheticCount()
	{
		return syntheticTargets.length;
	}
	/** The target index owning synthetic node {@code node}, or a negative value for any other node. */
	int syntheticTarget(int node)
	{
		int index = node - graph.nodeCount();
		return index >= 0 && index < syntheticTargets.length ? syntheticTargets[index] : -1;
	}
	/** Tile of a spatial site node or a synthetic target node. */
	int nodeTile(int node)
	{
		int target = syntheticTarget(node);
		return target >= 0 ? packed[target] : stat.siteTile(node);
	}
	/** Routing components of a spatial site node or a synthetic target node. */
	int[] nodeComponents(int node)
	{
		int target = syntheticTarget(node);
		return target >= 0 ? components[target] : stat.siteComponents(node);
	}

	/** The only target's tile; single-target overlays only. */
	public int packedTarget()
	{
		return packed[single()];
	}
	/** The only target's node; single-target overlays only. */
	public int targetNode()
	{
		return nodes[single()];
	}
	/** Whether the only target is synthetic; single-target overlays only. */
	public boolean synthetic()
	{
		return synthetic(single());
	}
	/** The only target's routing components; single-target overlays only. */
	public int[] components()
	{
		return components(single());
	}
	/** The only target's attachment count; single-target overlays only. */
	public int attachmentCount()
	{
		return attachmentCount(single());
	}
	/** The only target's attachment site; single-target overlays only. */
	public int attachmentSite(int index)
	{
		return attachmentSite(single(), index);
	}
	/** The only target's attachment cost; single-target overlays only. */
	public int attachmentCost(int index)
	{
		return attachmentCost(single(), index);
	}
	/** The only target's state; single-target overlays only. */
	public int targetState(BankVisitState banked)
	{
		return targetState(single(), banked);
	}

	void requireCompatible(SiteGraph candidate)
	{
		if (candidate.routingStatic() != stat || candidate.preparedAccount() != account
			|| candidate.preparedAccount().fingerprint() != accountFingerprint)
		{
			throw new IllegalArgumentException("target overlay belongs to another static/account snapshot");
		}
	}

	private int single()
	{
		if (packed.length != 1)
			throw new IllegalStateException("overlay has " + packed.length + " targets");
		return 0;
	}

	private void attach(int target)
	{
		int[] targetComponents = components[target];
		int capacity = 0;
		for (int component : targetComponents)
			capacity += stat.componentSites(component).length;
		int[] sites = new int[capacity];
		int count = 0;
		for (int component : targetComponents)
		{
			for (int site : stat.componentSites(component))
			{
				if (firstSharedComponent(targetComponents, site) == component)
					sites[count++] = site;
			}
		}
		attachmentSites[target] = Arrays.copyOf(sites, count);
		attachmentCosts[target] = new int[count];
		// Only a synthetic target's attachments enter the reverse search. Walking distances rather
		// than Chebyshev ones keep a target deep in a winding area from looking close to its
		// entrances, which would otherwise make the search flood everything within that slack.
		TargetWalkDistances walk = nodes[target] >= graph.nodeCount()
			? TargetWalkDistances.search(stat, packed[target], targetComponents) : null;
		for (int i = 0; i < count; i++)
		{
			int site = stat.siteTile(attachmentSites[target][i]);
			int chebyshev = distance(packed[target], site);
			attachmentCosts[target][i] = walk == null ? chebyshev : walk.bound(site, chebyshev);
		}
	}

	private int firstSharedComponent(int[] targetComponents, int site)
	{
		for (int component : targetComponents)
		{
			for (int siteComponent : stat.siteComponents(site))
				if (siteComponent == component)
					return component;
		}
		throw new IllegalStateException("target attachment missing shared routing component");
	}

	/** Encodes each unsigned tile followed by its two layer bits; null layers means either. */
	static long[] canonicalTargets(int[] values, int[] layers)
	{
		if (values == null) throw new NullPointerException("targets");
		if (layers != null && values.length != layers.length)
			throw new IllegalArgumentException("one layer mask is required per target");
		long[] sorted = new long[values.length];
		for (int i = 0; i < values.length; i++)
		{
			int mask = layers == null ? 3 : layers[i];
			if (mask < 1 || mask > 3) throw new IllegalArgumentException("target layers must be 1, 2 or 3");
			sorted[i] = Integer.toUnsignedLong(values[i]) << 2 | mask;
		}
		Arrays.sort(sorted);
		int count = 0;
		for (int i = 0; i < sorted.length; i++)
			if (count == 0 || (sorted[count - 1] >>> 2) != (sorted[i] >>> 2))
				sorted[count++] = sorted[i];
			else
				sorted[count - 1] |= sorted[i] & 3;
		return Arrays.copyOf(sorted, count);
	}

	private static int distance(int left, int right)
	{
		return shortestpath.WorldPointUtil.distanceBetween(left, right);
	}
}

package shortestpath.pathfinder.astar;

import java.util.Arrays;
import shortestpath.WorldPointUtil;
import lombok.AllArgsConstructor;

/**
 * Lower bounds on the walking cost from a target's attachment sites to the target, from a bounded
 * breadth-first search backwards over the static walking edges, within the target's routing
 * components.
 *
 * <p>Why a walk inside the components is enough: sites are every transport endpoint, crossing
 * endpoint and bank, and routing components are only left by crossing a cut, whose endpoints are
 * sites. A route's last stretch after its last site is therefore a pure walk inside the target's
 * components, and costs at least the distance found here. A site never reached gets the distance
 * of the search's frontier when it stopped (no closer tile was left unvisited), and every bound
 * is at least the Chebyshev distance the overlay used before.
 */
@AllArgsConstructor
final class TargetWalkDistances
{
	/** Tiles the search may visit per target; larger components get frontier bounds beyond it. */
	static final int TILE_BUDGET = 1 << 16;

	// Bit b of a walking mask steps by (DX[b], DY[b]), as in AStarForwardSearch.walkBase.
	private static final int[] DX = {0, 1, 1, 1, 0, -1, -1, -1};
	private static final int[] DY = {1, 1, 0, -1, -1, -1, 0, 1};

	private final RoutingStatic stat;
	private final int[] components;
	private final NodeDistances distances;
	private final int frontier;



	/** Null when the target is not a static search tile (its attachments keep Chebyshev costs). */
	static TargetWalkDistances search(RoutingStatic stat, int target, int[] components)
	{
		int start = stat.searchIndex(target);
		if (start < 0) return null;
		NodeDistances distances = new NodeDistances(TILE_BUDGET);
		int[] queue = new int[TILE_BUDGET];
		int head = 0, tail = 0;
		distances.put(start, 0);
		queue[tail++] = start;
		int frontier = 0;
		boolean exhausted = true;
		while (head < tail)
		{
			int node = queue[head++];
			int distance = distances.get(node);
			for (int direction = 0; direction < 8; direction++)
			{
				// The neighbour in this direction is a predecessor if it walks back onto this tile,
				// by the same index arithmetic the forward search uses.
				int from = successor(stat, node, direction), bit = (direction + 4) & 7;
				if (from < 0 || from >= stat.searchTileCount()) continue;
				if ((stat.walkingMask(from) & (1 << bit)) == 0 || successor(stat, from, bit) != node) continue;
				if (distances.get(from) >= 0 || !inComponents(stat.routingComponent(from), components)) continue;
				if (tail == TILE_BUDGET)
				{
					exhausted = false;
					break;
				}
				distances.put(from, distance + 1);
				queue[tail++] = from;
			}
			if (!exhausted)
			{
				// Every unvisited tile is at least as far as the tile being expanded.
				frontier = distance;
				break;
			}
			frontier = distance + 1;
		}
		return new TargetWalkDistances(stat, components, distances, frontier);
	}

	/**
	 * A lower bound on walking from {@code site} to the target, never below {@code chebyshev}.
	 * A site off the search tiles (a blocked transport origin) first steps to a neighbour.
	 */
	int bound(int site, int chebyshev)
	{
		int node = stat.searchIndex(site);
		if (node >= 0) return Math.max(chebyshev, distance(node));
		int x = WorldPointUtil.unpackWorldX(site), y = WorldPointUtil.unpackWorldY(site);
		int plane = WorldPointUtil.unpackWorldPlane(site);
		int best = Integer.MAX_VALUE;
		for (int bit = 0; bit < 8; bit++)
		{
			int neighbour = stat.searchIndex(WorldPointUtil.packWorldPoint(x + DX[bit], y + DY[bit], plane));
			if (neighbour >= 0) best = Math.min(best, distance(neighbour));
		}
		return best == Integer.MAX_VALUE ? chebyshev : Math.max(chebyshev, 1 + best);
	}

	private int distance(int node)
	{
		int known = distances.get(node);
		return known >= 0 ? known : frontier;
	}

	private static int successor(RoutingStatic stat, int node, int bit)
	{
		int south = stat.southNode(node), north = stat.northNode(node);
		switch (bit)
		{
			case 0: return north;
			case 1: return north < 0 ? -1 : north + 1;
			case 2: return node + 1;
			case 3: return south < 0 ? -1 : south + 1;
			case 4: return south;
			case 5: return south < 0 ? -1 : south - 1;
			case 6: return node - 1;
			default: return north < 0 ? -1 : north - 1;
		}
	}

	private static boolean inComponents(int component, int[] components)
	{
		for (int value : components)
			if (value == component) return true;
		return false;
	}

	/** Open-addressing node -> distance map sized for the tile budget. */
	private static final class NodeDistances
	{
		private final int[] keys, values;
		private final int mask;

		NodeDistances(int capacity)
		{
			int size = Integer.highestOneBit(capacity * 2 - 1) << 1;
			keys = new int[size];
			values = new int[size];
			Arrays.fill(keys, -1);
			mask = size - 1;
		}

		void put(int key, int value)
		{
			int slot = mix(key) & mask;
			while (keys[slot] != -1 && keys[slot] != key) slot = (slot + 1) & mask;
			keys[slot] = key;
			values[slot] = value;
		}

		int get(int key)
		{
			int slot = mix(key) & mask;
			while (keys[slot] != -1)
			{
				if (keys[slot] == key) return values[slot];
				slot = (slot + 1) & mask;
			}
			return -1;
		}

		private static int mix(int key)
		{
			int h = key * 0x9E3779B9;
			return h ^ (h >>> 16);
		}
	}
}

package shortestpath.pathfinder.astar;

import shortestpath.WorldPointUtil;
import shortestpath.transport.Transport;
import lombok.Getter;
import lombok.experimental.Accessors;

/**
 * Which global teleports the A* backend lets the player cast from a tile, by the tile's
 * wilderness band. These are legacy's global-teleport abstract nodes ({@code AbstractNodeKind}):
 *
 * <pre>
 * OVER_30  level 31+     cast level 31  GLOBAL_TELEPORTS_OVER_30
 * OVER_20  levels 21-30  cast level 30  GLOBAL_TELEPORTS_OVER_20
 * OVER_0   levels 1-20   cast level 20  GLOBAL_TELEPORTS_OVER_0
 * ALL      level 0       cast level 0   GLOBAL_TELEPORTS_NORMAL
 * </pre>
 *
 * A global is castable with a capability when {@link Transport#isUsableAtWildernessLevel} allows
 * the capability's cast level, as in legacy. Cast levels only fall from {@code OVER_30} to
 * {@code ALL}, so each capability can cast everything the one before it can.
 *
 * <p>The bands are {@code WildernessChecker}'s level-30, level-20 and wilderness areas (checked by
 * {@code TeleportCapabilityTest}), on every plane, inlined here because the forward search asks
 * for every state it pops.
 */
public enum TeleportCapability
{
	OVER_30(31), OVER_20(30), OVER_0(20), ALL(0);

	@Getter @Accessors(fluent = true) private final int castLevel;

	TeleportCapability(int castLevel)
	{
		this.castLevel = castLevel;
	}

	/** Whether {@code transport} can be cast as a global teleport in this band. */
	public boolean canCast(Transport transport)
	{
		return transport.isUsableAtWildernessLevel(castLevel);
	}

	/** Whether a tile with this capability may cast everything {@code required} can. */
	boolean allows(TeleportCapability required)
	{
		return castLevel <= required.castLevel;
	}

	/**
	 * {left, bottom, width, height} areas inside the above-ground wilderness area that are not
	 * wilderness: Ferox Enclave and its south edge.
	 */
	static final int[][] NOT_WILDERNESS = {{3123, 3622, 2, 10}, {3125, 3617, 16, 23}, {3138, 3636, 18, 10},
		{3141, 3625, 14, 11}, {3141, 3619, 7, 6}, {2997, 3525, 34, 9}, {3005, 3534, 21, 10}, {3000, 3534, 5, 5},
		{3031, 3525, 2, 2}};

	public static TeleportCapability at(int tile)
	{
		return at(WorldPointUtil.unpackWorldX(tile), WorldPointUtil.unpackWorldY(tile));
	}

	static TeleportCapability at(int x, int y)
	{
		// The wilderness areas and the level 30 and level 20 bands, unrolled; NOT_WILDERNESS cuts out of the first.
		if (x < 2944 || x >= 3462 || y < 3525) return ALL;
		if (y >= 9918)
		{
			if (y >= 10376) return ALL;
			return y >= 10155 ? OVER_30 : y >= 10075 ? OVER_20 : OVER_0;
		}
		if (x >= 3392) return ALL;
		if (y >= 3760 && y < 4208) return OVER_30;
		if (y >= 3680 && y < 4128) return OVER_20;
		if (y >= 3973 || inAny(NOT_WILDERNESS, x, y)) return ALL;
		return OVER_0;
	}

	static boolean inAny(int[][] areas, int x, int y)
	{
		for (int[] area : areas)
			if (inArea(area, x, y)) return true;
		return false;
	}

	static boolean inArea(int[] area, int x, int y)
	{
		return x >= area[0] && x < area[0] + area[2] && y >= area[1] && y < area[1] + area[3];
	}
}

package shortestpath.pathfinder.astar;

/**
 * Per-tile component numbers, using two bytes when the world's component count permits it.
 * Mutable during construction; ownership passes to the read-only RoutingStatic when built.
 */
final class TileComponents
{
	private final char[] compactIds;
	private final int[] wideIds;
	private final int componentCount;

	TileComponents(int tileCount, int componentCount)
	{
		if (componentCount < 0) throw new IllegalArgumentException("negative component count");
		this.componentCount = componentCount;
		compactIds = componentCount <= Character.MAX_VALUE + 1 ? new char[tileCount] : null;
		wideIds = compactIds == null ? new int[tileCount] : null;
	}

	int length()
	{
		return compactIds == null ? wideIds.length : compactIds.length;
	}

	int get(int tile)
	{
		return compactIds == null ? wideIds[tile] : compactIds[tile];
	}

	void set(int tile, int component)
	{
		if (component < 0 || component >= componentCount)
			throw new IllegalArgumentException("component out of range");
		if (compactIds == null) wideIds[tile] = component;
		else compactIds[tile] = (char) component;
	}
}

package shortestpath.pathfinder.sailing;

import java.util.*;
import java.util.concurrent.ConcurrentHashMap;

import static net.runelite.api.Constants.REGION_SIZE;
import net.runelite.api.Perspective;
import shortestpath.pathfinder.*;
import lombok.Getter;
import lombok.experimental.Accessors;

/**
 * The hull of the player's boat, so that a sailing move is only taken if the whole boat fits along it, not just its
 * centre.
 * <p>
 * A boat is a rectangle in its own frame (the game's bounds for its world entity: the raft is 1 by 3 tiles, the skiff
 * 2 by 5 and the sloop 3 by 10, reaching further toward its bow), turned to face its heading, at the spot within its
 * tile where the boat sits. Every move lands whole tiles away, so the boat keeps that spot along the whole route.
 * Holding a heading for a move sweeps the rectangle from where the move starts to where it ends, over the convex hull
 * of the two (the game's rounding can take a move slightly off the boat's axis); the move is only taken if no blocked
 * tile overlaps it. Turning between moves isn't checked. A tile blocks a boat if it's blocked or has a wall on any
 * side. Touching a blocked tile's edge is fine, so a 3-wide sloop lined up exactly fits a 3-wide gap, as players have
 * seen in game.
 * <p>
 * An instance belongs to one search: it caches the shapes it sweeps and the blocked tiles it has looked at.
 */
public final class BoatHull
{
	private static final int HEADINGS = 16;
	// The game's angles: 2048 per turn, 128 per heading
	private static final int ANGLES_PER_HEADING = 2048 / HEADINGS;
	private static final double EPSILON = 1e-6;
	private static final int REGION_SHIFT = Integer.numberOfTrailingZeros(REGION_SIZE);
	private static final int REGION_MASK = REGION_SIZE - 1;
	private static final int PLANES = 4;
	// A shape with no rows, so no tiles count as covered where a move starts
	private static final int[] EMPTY_SHAPE = {0};

	// The rectangle in the boat's own frame, in local units (128 per tile): its centre across and along the boat
	// (the bow is toward negative along) and its size
	private final int boundsX;
	private final int boundsY;
	private final int boundsWidth;
	private final int boundsHeight;
	// Where the boat sits within its tile, in local units from the tile's centre
	private final int pivotX;
	private final int pivotY;

	// Tiles the hull covers, relative to the tile it starts on: {first row, then each row's first and last column}.
	// Concurrent: the search fills it on the pathfinding thread while the client thread's arrival
	// check reads and fills it too (ShortestPathPlugin asks covers() each tick for the live boat)
	private final Map<Long, int[]> shapes = new ConcurrentHashMap<>();
	// How far the hull reaches from the centre of the boat's tile, facing any heading, in tiles
	@Getter @Accessors(fluent = true) private final double reach;
	// Tiles that block a boat, as one bit per tile and one long per row of each region and plane, filled in as the
	// search reaches them
	private final SplitFlagMap.RegionExtent extent;
	private final long[][] blockedRows;

	private BoatHull(int boundsX, int boundsY, int boundsWidth, int boundsHeight, int pivotX, int pivotY)
	{
		this.boundsX = boundsX;
		this.boundsY = boundsY;
		this.boundsWidth = boundsWidth;
		this.boundsHeight = boundsHeight;
		this.pivotX = pivotX;
		this.pivotY = pivotY;
		extent = SplitFlagMap.getRegionExtents();
		blockedRows = new long[(extent.getWidth() + 1) * (extent.getHeight() + 1) * PLANES][];

		double corner = 0;
		for (int across = -1; across <= 1; across += 2)
		{
			for (int along = -1; along <= 1; along += 2)
			{
				corner = Math.max(corner, Math.hypot(boundsX + across * boundsWidth / 2.0, boundsY + along * boundsHeight / 2.0));
			}
		}
		// A local unit more, for the game's rounding when it turns the hull
		reach = (Math.hypot(pivotX, pivotY) + corner + 1) / Perspective.LOCAL_TILE_SIZE;
	}

	/**
	 * @param boundsX      centre of the boat's rectangle across the boat, in local units (128 per tile)
	 * @param boundsY      centre of the rectangle along the boat, in local units; negative is toward the bow
	 * @param boundsWidth  width of the rectangle, in local units
	 * @param boundsHeight length of the rectangle, in local units
	 * @param pivotX       where the boat sits within its tile, in local units from the tile's centre
	 * @param pivotY       where the boat sits within its tile, in local units from the tile's centre
	 * @return the hull, or {@code null} if the bounds are empty
	 */
	public static BoatHull fromBounds(int boundsX, int boundsY, int boundsWidth, int boundsHeight, int pivotX, int pivotY)
	{
		if (boundsWidth <= 0 || boundsHeight <= 0)
		{
			return null;
		}
		return new BoatHull(boundsX, boundsY, boundsWidth, boundsHeight, pivotX, pivotY);
	}

	/**
	 * The hull's corners facing {@code heading}, in order round the rectangle, in tiles from the centre of the tile the
	 * boat is on: {x0, y0, x1, y1, x2, y2, x3, y3}.
	 */
	public double[] outline(int heading)
	{
		// corners() lists them across then along, so swap the last two to go round
		double[] corners = corners(heading * ANGLES_PER_HEADING, 0, 0);
		return new double[]{corners[0], corners[1], corners[2], corners[3], corners[6], corners[7], corners[4], corners[5]};
	}

	/**
	 * How far the hull reaches from the centre of the boat's tile, facing any heading, in tiles.
	 */


	/**
	 * Whether the hull, on a tile facing {@code heading}, covers the tile (dx, dy) tiles from it: overlaps it by more
	 * than touching its edge.
	 */
	public boolean covers(int heading, int dx, int dy)
	{
		int[] shape = shape(heading, 0, 0);
		int row = dy - shape[0];
		return row >= 0 && row < rows(shape) && dx >= shape[1 + 2 * row] && dx <= shape[2 + 2 * row];
	}

	/**
	 * Whether the hull, facing {@code heading}, can sail (dx, dy) tiles from tile (x, y, z) without overlapping a tile
	 * that blocks it anywhere along the way, where it starts and ends included.
	 */
	public boolean canMove(CollisionMap map, int x, int y, int z, int heading, int dx, int dy)
	{
		return canMove(map, x, y, z, heading, dx, dy, false);
	}

	/**
	 * Whether the hull, facing {@code heading}, can sail (dx, dy) tiles from tile (x, y, z) without overlapping a tile
	 * that blocks it anywhere along the way — or only ones it doesn't already cover, when {@code exemptStart} marks
	 * the search's first move: a berthed boat's hull can overlap blocked tiles where it starts (a moored boat may sit
	 * over marked tiles), and like {@link SailingSearch#canSailLine}'s first-tile escape they can't stop it leaving.
	 * Later moves keep the full start check, which also catches the hull turning onto a blocked tile between moves.
	 */
	public boolean canMove(CollisionMap map, int x, int y, int z, int heading, int dx, int dy, boolean exemptStart)
	{
		final int[] shape = shape(heading, dx, dy);
		final int[] start = exemptStart ? shape(heading, 0, 0) : EMPTY_SHAPE;
		for (int row = 0; row < rows(shape); row++)
		{
			final int rowY = shape[0] + row;
			final int lo = shape[1 + 2 * row];
			final int hi = shape[2 + 2 * row];
			final int startRow = rowY - start[0];
			if (startRow < 0 || startRow >= rows(start))
			{
				if (anyBlocked(map, x + lo, x + hi, y + rowY, z))
				{
					return false;
				}
				continue;
			}
			if (anyBlocked(map, x + lo, x + Math.min(hi, start[1 + 2 * startRow] - 1), y + rowY, z)
				|| anyBlocked(map, x + Math.max(lo, start[2 + 2 * startRow] + 1), x + hi, y + rowY, z))
			{
				return false;
			}
		}
		return true;
	}

	/**
	 * Lets go of the shapes and blocked tiles cached during a search, once it's done; they're worked out again if needed.
	 */
	void release()
	{
		shapes.clear();
		Arrays.fill(blockedRows, null);
	}

	private static int rows(int[] shape)
	{
		return (shape.length - 1) / 2;
	}

	// Whether any tile from (x0, y) to (x1, y) blocks the boat
	private boolean anyBlocked(CollisionMap map, int x0, int x1, int y, int z)
	{
		for (int x = x0; x <= x1; )
		{
			int last = Math.min(x1, x | REGION_MASK);
			long[] rows = regionRows(map, x >> REGION_SHIFT, y >> REGION_SHIFT, z);
			if (rows == null)
			{
				return true;
			}
			int lo = x & REGION_MASK;
			long mask = (-1L >>> (63 - ((last & REGION_MASK) - lo))) << lo;
			if ((rows[y & REGION_MASK] & mask) != 0)
			{
				return true;
			}
			x = last + 1;
		}
		return false;
	}

	// The tiles of a region and plane that block a boat, one long per row, or null off the map
	private long[] regionRows(CollisionMap map, int regionX, int regionY, int z)
	{
		if (regionX < extent.getMinX() || regionX > extent.getMaxX() || regionY < extent.getMinY()
			|| regionY > extent.getMaxY() || z < 0 || z >= PLANES)
		{
			return null;
		}
		int index = ((regionX - extent.getMinX()) + (regionY - extent.getMinY()) * (extent.getWidth() + 1)) * PLANES + z;
		long[] rows = blockedRows[index];
		if (rows == null)
		{
			rows = new long[REGION_SIZE];
			final int baseX = regionX << REGION_SHIFT;
			final int baseY = regionY << REGION_SHIFT;
			// Which tiles are blocked, including a border one tile wide around the region
			final int size = REGION_SIZE + 2;
			boolean[] blocked = new boolean[size * size];
			for (int row = 0; row < size; row++)
			{
				for (int column = 0; column < size; column++)
				{
					blocked[row * size + column] = map.isBlocked(baseX + column - 1, baseY + row - 1, z);
				}
			}
			for (int row = 0; row < REGION_SIZE; row++)
			{
				long bits = 0;
				for (int column = 0; column < REGION_SIZE; column++)
				{
					final int x = baseX + column;
					final int y = baseY + row;
					final int i = (row + 1) * size + column + 1;
					// A side that can't be crossed into an open tile has a wall on it
					boolean wall = (!map.n(x, y, z) && !blocked[i + size]) || (!map.s(x, y, z) && !blocked[i - size])
						|| (!map.e(x, y, z) && !blocked[i + 1]) || (!map.w(x, y, z) && !blocked[i - 1]);
					if (blocked[i] || wall)
					{
						bits |= 1L << column;
					}
				}
				rows[row] = bits;
			}
			blockedRows[index] = rows;
		}
		return rows;
	}

	// The tiles the hull overlaps while sailing (dx, dy) tiles facing heading, relative to the tile it starts on
	private int[] shape(int heading, int dx, int dy)
	{
		long key = ((long) heading << 40) | ((long) (dx & 0xFFFFF) << 20) | (dy & 0xFFFFF);
		int[] shape = shapes.get(key);
		if (shape == null)
		{
			shape = rasterize(corners(heading * ANGLES_PER_HEADING, dx, dy));
			shapes.put(key, shape);
		}
		return shape;
	}

	// The hull's corners where it starts and where it ends, in tiles around the start tile's centre:
	// {x0, y0, x1, y1, ...}. They're turned in whole local units with the game's sine table, the way the game
	// turns models, so they're exact and edges that line up with tile edges do so exactly.
	private double[] corners(int angle, int dx, int dy)
	{
		final int cos = Perspective.COSINE[angle];
		final int sin = Perspective.SINE[angle];
		double[] points = new double[16];
		int i = 0;
		for (int end = 0; end <= 1; end++)
		{
			for (int across = -1; across <= 1; across += 2)
			{
				for (int along = -1; along <= 1; along += 2)
				{
					int modelX = boundsX + across * boundsWidth / 2;
					int modelY = boundsY + along * boundsHeight / 2;
					int x = pivotX + end * dx * Perspective.LOCAL_TILE_SIZE + ((modelX * cos + modelY * sin) >> 16);
					int y = pivotY + end * dy * Perspective.LOCAL_TILE_SIZE + ((modelY * cos - modelX * sin) >> 16);
					points[i++] = (double) x / Perspective.LOCAL_TILE_SIZE;
					points[i++] = (double) y / Perspective.LOCAL_TILE_SIZE;
				}
			}
		}
		return points;
	}

	// The tiles a convex shape (the hull of the given points) overlaps by more than touching, as rows
	private static int[] rasterize(double[] points)
	{
		double[] hull = convexHull(points);
		int n = hull.length / 2;
		double minY = Double.MAX_VALUE;
		double maxY = -Double.MAX_VALUE;
		for (int i = 0; i < n; i++)
		{
			minY = Math.min(minY, hull[2 * i + 1]);
			maxY = Math.max(maxY, hull[2 * i + 1]);
		}
		// Tile row r covers y from r - 0.5 to r + 0.5, and column c covers x from c - 0.5 to c + 0.5
		int firstRow = (int) Math.floor(minY - 0.5 + EPSILON) + 1;
		int lastRow = (int) Math.ceil(maxY + 0.5 - EPSILON) - 1;
		int[] columns = new int[2 * Math.max(0, lastRow - firstRow + 1)];
		int rows = 0;
		int shapeFirstRow = firstRow;
		for (int row = firstRow; row <= lastRow; row++)
		{
			double[] range = xRange(hull, n, row - 0.5 + EPSILON, row + 0.5 - EPSILON);
			int first = (int) Math.floor(range[0] - 0.5 + EPSILON) + 1;
			int last = (int) Math.ceil(range[1] + 0.5 - EPSILON) - 1;
			if (first > last)
			{
				// Only the rows at either end can be empty, where the shape barely reaches them
				if (rows == 0)
				{
					shapeFirstRow = row + 1;
				}
				continue;
			}
			columns[2 * rows] = first;
			columns[2 * rows + 1] = last;
			rows++;
		}
		int[] shape = new int[1 + 2 * rows];
		shape[0] = shapeFirstRow;
		System.arraycopy(columns, 0, shape, 1, 2 * rows);
		return shape;
	}

	// The smallest and largest x of a convex polygon between two heights
	private static double[] xRange(double[] polygon, int n, double low, double high)
	{
		double min = Double.MAX_VALUE;
		double max = -Double.MAX_VALUE;
		for (int i = 0; i < n; i++)
		{
			double x1 = polygon[2 * i];
			double y1 = polygon[2 * i + 1];
			double x2 = polygon[2 * ((i + 1) % n)];
			double y2 = polygon[2 * ((i + 1) % n) + 1];
			if (y1 >= low && y1 <= high)
			{
				min = Math.min(min, x1);
				max = Math.max(max, x1);
			}
			for (double level : new double[]{low, high})
			{
				if ((y1 - level) * (y2 - level) < 0)
				{
					double x = x1 + (level - y1) * (x2 - x1) / (y2 - y1);
					min = Math.min(min, x);
					max = Math.max(max, x);
				}
			}
		}
		return new double[]{min, max};
	}

	// Andrew's monotone chain; returns the hull's corners in order as {x0, y0, x1, y1, ...}
	private static double[] convexHull(double[] points)
	{
		int n = points.length / 2;
		Integer[] order = new Integer[n];
		for (int i = 0; i < n; i++)
		{
			order[i] = i;
		}
		Arrays.sort(order, (a, b) -> points[2 * a] != points[2 * b]
			? Double.compare(points[2 * a], points[2 * b]) : Double.compare(points[2 * a + 1], points[2 * b + 1]));
		int[] hull = new int[2 * n + 1];
		int k = 0;
		for (int j = 0; j < n; j++)
		{
			while (k >= 2 && cross(points, hull[k - 2], hull[k - 1], order[j]) <= 0)
			{
				k--;
			}
			hull[k++] = order[j];
		}
		int lower = k + 1;
		for (int j = n - 2; j >= 0; j--)
		{
			while (k >= lower && cross(points, hull[k - 2], hull[k - 1], order[j]) <= 0)
			{
				k--;
			}
			hull[k++] = order[j];
		}
		// The last corner is the first one again
		k--;
		double[] result = new double[2 * k];
		for (int i = 0; i < k; i++)
		{
			result[2 * i] = points[2 * hull[i]];
			result[2 * i + 1] = points[2 * hull[i] + 1];
		}
		return result;
	}

	private static double cross(double[] p, int o, int a, int b)
	{
		return (p[2 * a] - p[2 * o]) * (p[2 * b + 1] - p[2 * o + 1]) - (p[2 * a + 1] - p[2 * o + 1]) * (p[2 * b] - p[2 * o]);
	}
}

package shortestpath.pathfinder.sailing;

import java.util.Arrays;

import net.runelite.api.Perspective;
import lombok.*;
import lombok.experimental.Accessors;

/**
 * The moves the sailing search uses for one boat speed.
 * <p>
 * A boat sails in one of 16 headings, and each tick it moves by that heading's velocity rounded to
 * quarter tiles, so the real direction of a heading depends on the speed: at speed 2, NNE moves 3
 * quarter tiles across and 7 up per tick (23.2 degrees, not 22.5). Holding a heading for 1, 2 or 4
 * ticks always lands a whole number of tiles away, with the boat at the same spot within its tile.
 * Each move here is one heading held for the fewest such ticks, so every leg of a path is a direction
 * the boat can actually sail. The search looks for the shortest route rather than the quickest, so each
 * move costs the distance it sails ({@link #length}).
 * <p>
 * The search uses the boat's base speed for the whole route, since speed boosts are random and
 * temporary; {@link #ESTIMATE} is the fallback when the base speed can't be read.
 */
@AllArgsConstructor
public final class SailingMoves
{
	private static final String[] HEADING_NAMES = {
		"S", "SSW", "SW", "WSW", "W", "WNW", "NW", "NNW", "N", "NNE", "NE", "ENE", "E", "ESE", "SE", "SSE"
	};

	/**
	 * Fallback speed when the boat's base speed can't be read. Straight and diagonal headings go the same
	 * way at every speed; at speed 2 the in-between headings (NNE and so on) are within a couple of degrees
	 * of their direction at the common speeds 2 to 4.
	 */
	public static final double ESTIMATED_SPEED = 2.0;

	/**
	 * The fastest a real boat's base speed can be, in tiles per tick: the common speeds are 2 to 4, and
	 * double the fastest leaves headroom for quicker hulls. A speed above it is a stale or mis-scaled
	 * reading rather than a faster boat — the moves it builds are so long that nothing can sail them —
	 * so the estimate is used instead.
	 */
	public static final double MAX_SPEED = 8.0;

	public static final SailingMoves ESTIMATE = forSpeed(ESTIMATED_SPEED);

	/**
	 * {@link #length} is in thousandths of a tile, so that adding lengths up is exact.
	 */
	public static final int LENGTH_UNITS_PER_TILE = 1000;

	@Getter @Accessors(fluent = true) private final double speed;
	private final int[] dx;
	private final int[] dy;
	private final int[] ticks;
	private final int[] lengths;
	private final int[] headings;
	private final String[] names;



	/**
	 * @param tilesPerTick boat speed, e.g. 1.5 or 2.0; an out-of-range value (including NaN) gives the estimate
	 */
	public static SailingMoves forSpeed(double tilesPerTick)
	{
		if (!(tilesPerTick > 0) || tilesPerTick > MAX_SPEED)
		{
			return ESTIMATE;
		}
		int[] dx = new int[HEADING_NAMES.length];
		int[] dy = new int[HEADING_NAMES.length];
		int[] ticks = new int[HEADING_NAMES.length];
		int[] lengths = new int[HEADING_NAMES.length];
		int[] headings = new int[HEADING_NAMES.length];
		String[] names = new String[HEADING_NAMES.length];
		int count = 0;
		for (int heading = 0; heading < HEADING_NAMES.length; heading++)
		{
			// Headings are 128 angle units apart: 0 is south, 512 west, 1024 north, 1536 east
			int angle = heading * 128;
			int quarterX = quarterTiles(-Perspective.SINE[angle] * tilesPerTick / 512.0);
			int quarterY = quarterTiles(-Perspective.COSINE[angle] * tilesPerTick / 512.0);
			if (quarterX == 0 && quarterY == 0)
			{
				continue;
			}
			// Fewest ticks (1, 2 or 4) after which the boat is a whole number of tiles away
			int k = 1;
			while ((k * quarterX) % 4 != 0 || (k * quarterY) % 4 != 0)
			{
				k *= 2;
			}
			dx[count] = k * quarterX / 4;
			dy[count] = k * quarterY / 4;
			ticks[count] = k;
			// Rounded up, so a route never costs less than its real length and the search's estimate stays a lower bound
			lengths[count] = (int) Math.ceil(Math.hypot(dx[count], dy[count]) * LENGTH_UNITS_PER_TILE);
			headings[count] = heading;
			names[count] = HEADING_NAMES[heading];
			count++;
		}
		if (count == 0)
		{
			// Below about 0.125 tiles per tick every heading rounds to no movement; a garbage or
			// stale base-speed reading must not produce a search that can never move
			return ESTIMATE;
		}
		return new SailingMoves(tilesPerTick, Arrays.copyOf(dx, count), Arrays.copyOf(dy, count),
			Arrays.copyOf(ticks, count), Arrays.copyOf(lengths, count), Arrays.copyOf(headings, count),
			Arrays.copyOf(names, count));
	}

	// The game's velocity along one axis: rounded to local units (128 per tile), then to quarter tiles (32 each)
	private static int quarterTiles(double localUnits)
	{
		double local = Math.signum(localUnits) * Math.round(Math.abs(localUnits));
		return (int) (Math.signum(local) * Math.round(Math.abs(local) / 32.0));
	}



	public int size()
	{
		return dx.length;
	}

	public int dx(int move)
	{
		return dx[move];
	}

	public int dy(int move)
	{
		return dy[move];
	}

	public int ticks(int move)
	{
		return ticks[move];
	}

	/**
	 * The heading the move holds: 0 is south, 4 west, 8 north and 12 east, like the game's orientation divided by 128.
	 */
	public int heading(int move)
	{
		return headings[move];
	}

	public String name(int move)
	{
		return names[move];
	}

	/**
	 * How far the move sails in a straight line, in thousandths of a tile ({@link #LENGTH_UNITS_PER_TILE}), rounded up.
	 */
	public int length(int move)
	{
		return lengths[move];
	}

	/**
	 * The heading of the move that goes (dx, dy) tiles, or -1 if there is none.
	 */
	public int headingOf(int dx, int dy)
	{
		int move = indexOf(dx, dy);
		return move < 0 ? -1 : headings[move];
	}

	/**
	 * Index of the move that goes (dx, dy) tiles, or -1 if there is none.
	 */
	public int indexOf(int dx, int dy)
	{
		for (int i = 0; i < this.dx.length; i++)
		{
			if (this.dx[i] == dx && this.dy[i] == dy)
			{
				return i;
			}
		}
		return -1;
	}
}

package shortestpath.pathfinder.sailing;

import java.util.*;
import java.util.function.IntPredicate;

import lombok.Getter;
import shortestpath.*;
import shortestpath.leagues.LeagueModeState;
import shortestpath.pathfinder.*;

/**
 * The sailing search: a Dijkstra over the boat's 16 headings (see {@link SailingMoves}) that keeps the
 * boat's whole hull clear along every move and arrives once the hull covers a target, rather than on
 * a tile. A self-contained search sharing only the public machinery of {@code pathfinder} (NodeGraph,
 * VisitedTiles, TargetGoals, SplitFlagMap) — it is an {@link ActiveSearch}, not a {@code Pathfinder},
 * so a walking search and a sailing search never share a class.
 */
public class SailingPathfinder implements ActiveSearch
{
	private final Stats stats;
	@Getter
	private final int start;
	// The targets keep their required items so a restart after landing honours them, but a
	// sailing search ignores them: a boat can't visit a bank.
	@Getter
	private final Targets targets;
	// Termination set resolved by TargetGoals: the requested targets plus, for
	// each blocked target, its fallback tiles (issue #640). Resolved at the start
	// of run(), with the rule taken when the search is created.
	private Set<Integer> goals;
	// Whether any requested target could possibly terminate the search: non-blocked,
	// a transport destination, or resolved to at least one walkable nearby tile.
	// When false the search is skipped entirely, since no goal can ever be visited.
	private boolean hasViableGoal;
	private final GoalRule goalRule;
	private final IntPredicate transportDestination;
	private final SailingSearch sailing;
	private final PathfinderConfig config;
	private final CollisionMap map;
	private final boolean targetInWilderness;
	private final boolean targetInBlockedRegion;
	private final Runnable completionCallback;
	// Nodes are stored structure-of-arrays style: each node is an int id into the graph, instead of
	// an object per explored tile. This keeps a whole search to a handful of arrays (issue #491).
	private final NodeGraph graph = new NodeGraph(1 << 14);
	// Capacities should be enough to store all nodes without requiring the queue to grow
	// They were found by checking the max queue size
	private final IntDeque boundary = new IntDeque(4096);
	private final IntMinHeap pending = new IntMinHeap(graph, 256);
	private final VisitedTiles visited;
	// The reusable emission buffer the neighbour enumeration fills; a sailing search emits only
	// weighted tiles into it.
	private final PrimitiveIntList neighbors = new PrimitiveIntList(16);
	@Getter
	private volatile boolean done = false;
	private volatile boolean cancelled = false;
	// Read by the render thread during the search to draw the partial path; written by the worker.
	private volatile int bestLastNode = NodeGraph.NO_NODE;
	// The path the render thread builds progressively while the search runs.
	private List<PathStep> pathSteps = List.of();
	private boolean pathNeedsUpdate = false;
	// Built once on the worker thread when the search finishes, then served to the render thread so
	// it never walks the node chain (which is released) after the search is done.
	private volatile List<PathStep> finalPath = null;
	private volatile int closestReachedPoint = WorldPointUtil.UNDEFINED;
	private volatile int finalPathCost = PathfinderResult.NO_PATH_COST;
	private int bestRemainingDistance = Integer.MAX_VALUE;
	private int bestTravelledDistance = Integer.MAX_VALUE;
	private int bestX = Integer.MAX_VALUE;
	private int bestY = Integer.MAX_VALUE;
	private int reachedTarget = WorldPointUtil.UNDEFINED;
	private PathTerminationReason terminationReason;
	/**
	 * Teleportation transports are updated when this changes.
	 * Can be either:
	 * 0 = all teleports can be used (e.g. Chronicle)
	 * 20 = most teleports can be used (e.g. Varrock Teleport)
	 * 30 = some teleports can be used (e.g. Amulet of Glory)
	 * 31 = no teleports can be used
	 */
	private int wildernessLevel;

	/**
	 * @param moves the boat's moves; required — a walking search is a plain {@code Pathfinder}
	 */
	public SailingPathfinder(PathfinderConfig config, int start, Set<Integer> targets, Runnable completionCallback,
		SailingMoves moves)
	{
		this(config, start, targets, completionCallback, moves, null);
	}

	/**
	 * @param moves the boat's moves; required — a walking search is a plain {@code Pathfinder}
	 * @param boatHull the boat's hull, which must fit along every sailing move, or {@code null} for just its centre
	 */
	public SailingPathfinder(PathfinderConfig config, int start, Set<Integer> targets, Runnable completionCallback,
		SailingMoves moves, BoatHull boatHull)
	{
		this(config, start, targets, completionCallback, moves, boatHull, WorldPointUtil.UNDEFINED);
	}

	/**
	 * @param moves          the boat's moves; required — a walking search is a plain {@code Pathfinder}
	 * @param boatHull       the boat's hull, which must fit along every sailing move, or {@code null} for just its centre
	 * @param sailingHeading the heading the boat is facing where the route starts (0 south, 8 north), or -1 when it
	 *                       isn't known: a target the hull already covers then counts as arrived facing any heading
	 */
	public SailingPathfinder(PathfinderConfig config, int start, Set<Integer> targets, Runnable completionCallback,
		SailingMoves moves, BoatHull boatHull, int sailingHeading)
	{
		this(config, start, Targets.at(targets), completionCallback, moves, boatHull, sailingHeading);
	}

	/** As {@link #SailingPathfinder(PathfinderConfig, int, Set, Runnable, SailingMoves, BoatHull, int)}. */
	public SailingPathfinder(PathfinderConfig config, int start, Targets targets, Runnable completionCallback,
		SailingMoves moves, BoatHull boatHull, int sailingHeading)
	{
		stats = new Stats();
		this.config = config;
		this.map = config.getMap();
		this.start = start;
		this.targets = targets;
		Set<Integer> points = targets.points();
		this.goalRule = TargetGoals.collisionRule(config, start);
		this.transportDestination = config::isTransportDestination;
		this.sailing = new SailingSearch(moves, boatHull, points.stream().mapToInt(Integer::intValue).toArray(),
			new int[0], sailingHeading);
		this.completionCallback = completionCallback;
		visited = new VisitedTiles(map, config.getBankVisitCost());
		targetInWilderness = WildernessChecker.isInWilderness(points);
		targetInBlockedRegion = anyInBlockedRegion(config.getLeagueModeState(), points);
		wildernessLevel = 31;
	}

	/**
	 * The target the boat, on the tile at {@code packedPosition} and facing {@code heading} (one of the
	 * 16 headings, or -1 when unknown), has arrived at — see {@link SailingSearch#arrivedTarget}. Lets
	 * the plugin ask where the live boat is rather than trusting the search's verdict, which says a
	 * route was found, not that the boat sailed it. {@link WorldPointUtil#UNDEFINED} if it hasn't
	 * arrived.
	 */
	public int arrivedTarget(int packedPosition, int heading)
	{
		return sailing.arrivedTarget(packedPosition, heading);
	}

	private static boolean anyInBlockedRegion(LeagueModeState league, Set<Integer> packed)
	{
		if (!league.isSeasonal() || packed == null || packed.isEmpty())
		{
			return false;
		}
		for (Integer point : packed)
		{
			if (league.isInBlockedRegion(point))
			{
				return true;
			}
		}
		return false;
	}

	public void cancel()
	{
		cancelled = true;
	}

	public PathfinderStats getStats()
	{
		if (stats.started && stats.ended)
		{
			return stats;
		}

		// Don't give incomplete results
		return null;
	}

	public List<PathStep> getPath()
	{
		int lastNode = bestLastNode; // For thread safety, read bestLastNode once
		if (lastNode == NodeGraph.NO_NODE)
		{
			List<PathStep> finalised = finalPath;
			return finalised != null ? finalised : pathSteps;
		}

		// Once the search is finished the node graph is released, so serve the pre-built snapshot.
		if (done)
		{
			List<PathStep> finalised = finalPath;
			if (finalised != null)
			{
				return finalised;
			}
		}

		if (pathNeedsUpdate)
		{
			List<PathStep> walked = graph.getPathSteps(lastNode);
			// An empty result means the graph was released mid-walk; keep the last good path.
			if (!walked.isEmpty())
			{
				pathSteps = walked;
				pathNeedsUpdate = false;
			}
		}

		return pathSteps;
	}

	public PathfinderResult getResult()
	{
		PathfinderStats currentStats = getStats();
		if (currentStats == null)
		{
			return null;
		}

		List<PathStep> currentPath = getPath();
		boolean reached = reachedTarget != WorldPointUtil.UNDEFINED;
		int target = reached ? reachedTarget : (targets.isEmpty() ? WorldPointUtil.UNDEFINED : targets.points().iterator().next());
		// getStats() only returns non-null once the search has ended, so the snapshot is set.
		return new PathfinderResult(
			start,
			target,
			reached,
			currentPath,
			closestReachedPoint,
			finalPathCost,
			currentStats.getNodesChecked(),
			currentStats.getTransportsChecked(),
			currentStats.getElapsedTimeNanos(),
			terminationReason
		);
	}

	private void addNeighbors(int node, int nodePacked)
	{
		final int x = WorldPointUtil.unpackWorldX(nodePacked);
		final int y = WorldPointUtil.unpackWorldY(nodePacked);
		final int z = WorldPointUtil.unpackWorldPlane(nodePacked);
		neighbors.clear();
		sailing.addNeighbors(map, neighbors, node, x, y, z, graph.bankVisited(node), visited, graph);
		final int count = neighbors.size();
		for (int i = 0; i < count; i++)
		{
			int neighbor = neighbors.get(i);
			final int neighborPacked = graph.packedPosition(neighbor);
			if (config.avoidWilderness(nodePacked, neighborPacked, targetInWilderness))
			{
				continue;
			}
			if (config.avoidBlockedRegion(nodePacked, neighborPacked, targetInBlockedRegion))
			{
				continue;
			}
			// Every emitted node is a weighted tile: a sailing move crosses its whole span at once, so
			// check its midpoint too, so a leg can't clip a wilderness or league boundary inside its reach
			final int midPacked = WorldPointUtil.packWorldPoint(
				(WorldPointUtil.unpackWorldX(nodePacked) + WorldPointUtil.unpackWorldX(neighborPacked)) / 2,
				(WorldPointUtil.unpackWorldY(nodePacked) + WorldPointUtil.unpackWorldY(neighborPacked)) / 2,
				WorldPointUtil.unpackWorldPlane(nodePacked));
			if (config.avoidWilderness(nodePacked, midPacked, targetInWilderness)
				|| config.avoidWilderness(midPacked, neighborPacked, targetInWilderness)
				|| config.avoidBlockedRegion(nodePacked, midPacked, targetInBlockedRegion)
				|| config.avoidBlockedRegion(midPacked, neighborPacked, targetInBlockedRegion))
			{
				continue;
			}

			pending.add(neighbor);
			// Only now, past the checks above, is the sailing tile queued at this cost, so a move they turn
			// down doesn't stop another route from queuing the tile
			sailing.setQueuedCost(WorldPointUtil.unpackWorldX(neighborPacked), WorldPointUtil.unpackWorldY(neighborPacked),
				WorldPointUtil.unpackWorldPlane(neighborPacked), graph.bankVisited(neighbor), graph.cost(neighbor));
			++stats.nodesChecked;
		}
	}

	/**
	 * Pathfinding to an unreachable target is slightly different from normal pathfinding.
	 * Straight-line movement before diagonal movement is no longer prioritized, because the
	 * original target is moved to the closest reachable tile. To avoid having to move the
	 * original target we instead do the following to favour the closest reachable tile:
	 * - 1) Pick the path with the minimum Euclidean distance (no need to use square root though)
	 * - 2) If a tie occurs, pick the path with minimum travelled distance
	 * - 3) If another tie occurs, pick the path with minimum x-coordinate
	 * - 4) If another tie occurs, pick the path with minimum y-coordinate
	 */
	private boolean updateBestPathWhenUnreachable(int node, int packedPosition)
	{
		boolean update = false;

		final int travelledDistance = graph.cost(node);
		for (int target : targets.points())
		{
			int remainingDistance = WorldPointUtil.distanceBetween(target, packedPosition, WorldPointUtil.EUCLIDEAN_SQUARED_DISTANCE_METRIC);
			int x = WorldPointUtil.unpackWorldX(packedPosition);
			int y = WorldPointUtil.unpackWorldY(packedPosition);
			if ((remainingDistance < bestRemainingDistance) ||
				(remainingDistance == bestRemainingDistance && travelledDistance < bestTravelledDistance) ||
				(remainingDistance == bestRemainingDistance && travelledDistance == bestTravelledDistance && x < bestX) ||
				(remainingDistance == bestRemainingDistance && travelledDistance == bestTravelledDistance && x == bestX && y < bestY))
			{
				bestRemainingDistance = remainingDistance;
				bestTravelledDistance = travelledDistance;
				bestX = x;
				bestY = y;
				bestLastNode = node;
				pathNeedsUpdate = true;
				update = true;
			}
		}

		return update;
	}

	/**
	 * Update wilderness level based on the current node position.
	 */
	private void updateWildernessLevel(int packedPosition)
	{
		if (wildernessLevel > 0)
		{
			// These are overlapping boundaries, so if the node isn't in level 30, it's in 0-29
			// likewise, if the node isn't in level 20, it's in 0-19
			if (wildernessLevel > 30 && !WildernessChecker.isInLevel30Wilderness(packedPosition))
			{
				wildernessLevel = 30;
			}
			if (wildernessLevel > 20 && !WildernessChecker.isInLevel20Wilderness(packedPosition))
			{
				wildernessLevel = 20;
			}
			if (wildernessLevel > 0 && !WildernessChecker.isInWilderness(packedPosition))
			{
				wildernessLevel = 0;
			}
		}
	}

	@Override
	public String backendName()
	{
		return "Sailing";
	}

	/**
	 * Always {@code true}: this search sails the boat's headings.
	 */
	@Override
	public boolean isSailing()
	{
		return true;
	}

	@Override
	public void run()
	{
		stats.start();
		TargetGoals resolved = TargetGoals.resolve(targets.points(), transportDestination, goalRule);
		goals = resolved.goals();
		hasViableGoal = resolved.hasViableGoal();
		sailing.setGoals(goals.stream().mapToInt(Integer::intValue).toArray());
		boundary.addFirst(graph.createStart(start));

		// The cutoff counts time without progress towards the target.
		SearchDeadline deadline = new SearchDeadline(config.getCalculationCutoffMillis());

		// When every target is a blocked tile that no transport lands on and no
		// walkable tile exists within the unreachable distance, no node can ever
		// satisfy the goal set — skip the search instead of exhausting the map.
		// A sailing search still runs: its hull can cover a target the walking
		// goals can't reach, which is what it arrives on rather than the goal set.
		while (!cancelled && (hasViableGoal || !targets.isEmpty())
			&& (!boundary.isEmpty() || !pending.isEmpty()))
		{
			int boundaryHead = boundary.peekFirst();
			int pendingHead = pending.peek();

			int node;
			// On a cost tie the pending heap wins: a queued transport that is strictly
			// cheaper than the walking route must claim its destination before an
			// equal-cost boundary node can expand and emit a competing walking edge.
			if (pendingHead != NodeGraph.NO_NODE
				&& (boundaryHead == NodeGraph.NO_NODE || graph.compareCost(pendingHead) <= graph.cost(boundaryHead)))
			{
				node = pending.poll();

				// Every node in pending is a sailing tile; none of them claimed their
				// destination at enqueue. The first, cheapest, dequeue wins the tile; later
				// queued duplicates for the same tile are dropped here — unless the duplicate
				// is a sailing move that arrives on its own heading, queued for it because the
				// settled heading didn't cover a target.
				int packed = graph.packedPosition(node);
				BankVisitState bank = graph.bankVisited(node);
				if (visited.get(packed, bank)
					&& !(graph.isWeighted(node)
						&& sailing.arrivedTarget(packed, sailing.arrivalHeading(graph, node)) != WorldPointUtil.UNDEFINED))
				{
					continue;
				}
				visited.set(packed, bank);
			}
			else
			{
				node = boundary.pollFirst();
			}
			if (node == NodeGraph.NO_NODE)
			{
				continue;
			}
			// A sailing search explores only tiles: the start node and the weighted tiles its
			// moves emit, so there is no nodeIsTile branch to keep. The walking search's
			// nearest-tile acceptance (shortestAcceptedNode/updateCustomPathWhenUnreachable) is
			// likewise dropped: accepting the first tile near a target could truncate the path
			// before the hull reaches a heading that covers one.
			final int nodePacked = graph.packedPosition(node);
			updateWildernessLevel(nodePacked);

			final int arrivedTarget = sailing.arrivedTarget(nodePacked, sailing.arrivalHeading(graph, node));
			if (goals.contains(nodePacked) || arrivedTarget != WorldPointUtil.UNDEFINED)
			{
				bestLastNode = node;
				// A sailing arrival reports the target the hull covers, which can sit a
				// boat length from the boat's tile rather than on it
				reachedTarget = goals.contains(nodePacked) ? nodePacked : arrivedTarget;
				pathNeedsUpdate = true;
				terminationReason = PathTerminationReason.TARGET_REACHED;
				break;
			}

			// Unreachable sailing routes still draw toward the target; isPathUnreachable
			// reads result.isReached()
			if (updateBestPathWhenUnreachable(node, nodePacked))
			{
				deadline.progressed();
			}

			if (deadline.expired())
			{
				terminationReason = PathTerminationReason.CUTOFF_REACHED;
				break;
			}

			addNeighbors(node, nodePacked);
		}

		if (cancelled)
		{
			terminationReason = PathTerminationReason.CANCELLED;
		}
		else if (terminationReason == null)
		{
			terminationReason = PathTerminationReason.SEARCH_EXHAUSTED;
		}

		// Materialise the final path and closest reached tile on the worker thread, publish them,
		// then release the large node graph. Once done is set the render thread serves finalPath
		// and never touches the released graph, so this is race-free with progressive rendering.
		int lastNode = bestLastNode;
		if (lastNode != NodeGraph.NO_NODE)
		{
			finalPath = graph.getPathSteps(lastNode);
			closestReachedPoint = graph.getClosestTilePosition(lastNode);
			finalPathCost = graph.cost(lastNode);
		}
		else
		{
			finalPath = pathSteps;
			closestReachedPoint = start;
			finalPathCost = PathfinderResult.NO_PATH_COST;
		}

		done = !cancelled;

		boundary.clear();
		visited.clear();
		pending.clear();
		graph.release();
		sailing.release();

		stats.end(); // Include cleanup in stats to get the total cost of pathfinding

		if (completionCallback != null)
		{
			completionCallback.run();
		}
	}

	// PathfinderStats' counters are package-private in pathfinder, so this keeps its own: the
	// nodes it checked (a sailing search never checks transports, so getTransportsChecked()
	// inherits the base's constant 0) and its own start/end clock.
	private static final class Stats extends PathfinderStats
	{
		@Getter private int nodesChecked;
		private long startNanos, endNanos;
		private volatile boolean started, ended;

		void start()
		{
			started = true;
			nodesChecked = 0;
			startNanos = System.nanoTime();
		}

		void end()
		{
			endNanos = System.nanoTime();
			ended = true;
		}

		@Override
		public int getTotalNodesChecked()
		{
			return nodesChecked;
		}

		@Override
		public long getElapsedTimeNanos()
		{
			return endNanos - startNanos;
		}
	}
}

package shortestpath.pathfinder.sailing;

import java.util.Arrays;

import static net.runelite.api.Constants.REGION_SIZE;
import shortestpath.*;
import shortestpath.pathfinder.*;

/**
 * One sailing search's moves, boat, targets and when it counts as arriving (see {@link SailingPathfinder}).
 * <p>
 * With the boat's hull, the path arrives once a target tile is inside the hull, where the path ends and facing the way
 * it sailed there. Without one, moves land whole tiles away, often several at a time, so a boat can't stop on every
 * tile: at speed 2 every move goes an even number of tiles across and up together, so half of all tiles are out of
 * reach. The path then arrives once the boat is on a target or next to it.
 * <p>
 * It also remembers the cheapest cost each tile has been queued at, so that a tile is only queued again when a route
 * reaches it for less — or, with a hull, when a costlier move would arrive on a heading none has tried: a dearer one
 * would only be dequeued once the tile is done.
 */
final class SailingSearch
{
	private static final int REGION_SHIFT = Integer.numberOfTrailingZeros(REGION_SIZE);
	private static final int REGION_MASK = REGION_SIZE - 1;
	private static final int PLANES = 4;
	private static final int HEADINGS = 16;
	// Sailing moves cost the distance they sail (SailingMoves.length), plus a thousandth of a tile per change of
	// heading, so that of the routes that are equally short the one with the fewest, longest legs wins.
	private static final int SAILING_COST_PER_TURN = 1;

	final SailingMoves moves;
	/** The boat's hull, or {@code null} to keep only the boat's centre clear. */
	final BoatHull hull;
	private final int[] targets;
	// The targets plus their fallback tiles: the search can also end by landing on one of them. Set when the
	// search runs, once its goals are resolved
	private int[] goals;
	// The heading the boat is facing where the route starts, or -1 when that isn't known: the start node has no
	// move to face, so without it a target under the hull counts as arrived facing any heading — even one the
	// boat, berthed, isn't pointing
	private final int initialHeading;
	// How far from a target the boat's tile can be while arriving, in tiles: next to it diagonally, or with a hull, as
	// far as the hull reaches plus half a tile's diagonal
	private final double arrivalReach;
	private final SplitFlagMap.RegionExtent extent;
	// The cheapest cost each tile has been queued at, without and with a bank visited, as one array per region and plane,
	// made as the search reaches them
	private final int[][][] queuedCosts = new int[2][][];
	// Which moves have already been queued into each tile at a cost that doesn't beat the tile's cheapest, as a bitmask.
	// A tile's cheapest route may face a way its hull doesn't cover a target in, so a costlier move that would arrive is
	// still queued — once per move
	private final int[][][] queuedArrivals = new int[2][][];

	SailingSearch(SailingMoves moves, BoatHull hull, int[] targets, int[] goals)
	{
		this(moves, hull, targets, goals, WorldPointUtil.UNDEFINED);
	}

	SailingSearch(SailingMoves moves, BoatHull hull, int[] targets, int[] goals, int initialHeading)
	{
		this.moves = moves;
		this.hull = hull;
		this.targets = targets;
		this.goals = goals;
		this.initialHeading = initialHeading;
		arrivalReach = hull == null ? Math.sqrt(2) : hull.reach() + Math.sqrt(2) / 2;
		extent = SplitFlagMap.getRegionExtents();
		int regions = (extent.getWidth() + 1) * (extent.getHeight() + 1) * PLANES;
		queuedCosts[0] = new int[regions][];
		queuedCosts[1] = new int[regions][];
		queuedArrivals[0] = new int[regions][];
		queuedArrivals[1] = new int[regions][];
	}

	/** Sets the goal tiles the estimate aims for, once the search has resolved them. */
	void setGoals(int[] goals)
	{
		this.goals = goals;
	}

	/**
	 * The heading the boat faces on {@code node}: the way the move that reached it sailed, or the heading it was
	 * facing where the route began on the start node, which no move reached. -1 means unknown, which lets
	 * {@link #arrivedTarget} try every heading.
	 */
	int arrivalHeading(NodeGraph graph, int node)
	{
		int heading = sailingArrivalHeading(graph, node, moves);
		return heading < 0 ? initialHeading : heading;
	}

	// The heading of the sailing move that reached node, or -1 if it wasn't reached by one (such as the search's
	// start, which faces the boat's own heading instead — see SailingSearch.arrivalHeading).
	// The move is stored on the node rather than recovered from its displacement, which different headings can share
	// at low speeds
	private static int sailingArrivalHeading(NodeGraph graph, int node, SailingMoves moves)
	{
		int move = graph.moveIndex(node);
		return move < 0 ? -1 : moves.heading(move);
	}

	/**
	 * The target the boat, on the tile at {@code packedPosition} and facing {@code heading}, has arrived at: its hull
	 * covers it, facing any heading if {@code heading} is -1 (unknown); or without a hull, it's on a target or next to
	 * it. {@link WorldPointUtil#UNDEFINED} if it hasn't arrived.
	 */
	int arrivedTarget(int packedPosition, int heading)
	{
		for (int target : targets)
		{
			if (hull == null)
			{
				if (WorldPointUtil.distanceBetween(target, packedPosition) <= 1)
				{
					return target;
				}
				continue;
			}
			if (WorldPointUtil.unpackWorldPlane(target) != WorldPointUtil.unpackWorldPlane(packedPosition))
			{
				continue;
			}
			int dx = WorldPointUtil.unpackWorldX(target) - WorldPointUtil.unpackWorldX(packedPosition);
			int dy = WorldPointUtil.unpackWorldY(target) - WorldPointUtil.unpackWorldY(packedPosition);
			for (int facing = heading < 0 ? 0 : heading; facing < (heading < 0 ? HEADINGS : heading + 1); facing++)
			{
				if (hull.covers(facing, dx, dy))
				{
					return target;
				}
			}
		}
		return WorldPointUtil.UNDEFINED;
	}

	/**
	 * A lower bound on the distance left from tile (x, y), in the units of {@link SailingMoves#length}: the nearest
	 * straight-line distance to a goal tile — which the boat has to land on — or to a target less how far from it the
	 * boat can arrive. Rounded down, so it never overestimates.
	 */
	int estimate(int x, int y)
	{
		// Landing on a goal tile ends the search exactly; a target only needs the boat within
		// arrival reach of it
		double tilesLeft = Double.MAX_VALUE;
		for (int goal : goals)
		{
			long dx = WorldPointUtil.unpackWorldX(goal) - x;
			long dy = WorldPointUtil.unpackWorldY(goal) - y;
			tilesLeft = Math.min(tilesLeft, Math.sqrt(dx * dx + dy * dy));
		}
		for (int target : targets)
		{
			long dx = WorldPointUtil.unpackWorldX(target) - x;
			long dy = WorldPointUtil.unpackWorldY(target) - y;
			tilesLeft = Math.min(tilesLeft, Math.sqrt(dx * dx + dy * dy) - arrivalReach);
		}
		if (tilesLeft == Double.MAX_VALUE)
		{
			return 0;
		}
		return (int) (SailingMoves.LENGTH_UNITS_PER_TILE * Math.max(0, tilesLeft));
	}

	/**
	 * The cheapest cost tile (x, y, z) has been queued at so far, or {@link Integer#MAX_VALUE} if it hasn't been; 0 if it's
	 * off the map, so it never is.
	 */
	int queuedCost(int x, int y, int z, BankVisitState bankVisited)
	{
		int region = regionIndex(x, y, z);
		if (region < 0)
		{
			return 0;
		}
		int[] costs = queuedCosts[bankVisited == BankVisitState.BANKED ? 1 : 0][region];
		return costs == null ? Integer.MAX_VALUE : costs[tileIndex(x, y)];
	}

	/**
	 * Notes that tile (x, y, z) is queued at {@code cost}; only lowers the noted cost, so it stays the
	 * cheapest the tile has been queued at (see {@link #queuedCost}).
	 */
	void setQueuedCost(int x, int y, int z, BankVisitState bankVisited, int cost)
	{
		int region = regionIndex(x, y, z);
		int[][] byRegion = queuedCosts[bankVisited == BankVisitState.BANKED ? 1 : 0];
		if (byRegion[region] == null)
		{
			byRegion[region] = new int[REGION_SIZE * REGION_SIZE];
			Arrays.fill(byRegion[region], Integer.MAX_VALUE);
		}
		int index = tileIndex(x, y);
		byRegion[region][index] = Math.min(byRegion[region][index], cost);
	}

	/**
	 * Lets a move reaching tile (x, y, z) at a cost that doesn't beat its cheapest queue anyway when the
	 * boat would arrive on the move's heading — the tile's cheapest route may face a way its hull doesn't
	 * cover a target in. Marks the move queued, so each move is let through once. Only for hull searches:
	 * without a hull arrival doesn't depend on facing.
	 *
	 * @return whether the move should be queued despite its cost
	 */
	boolean queueArrival(int packedPosition, int move, int x, int y, int z, BankVisitState bankVisited)
	{
		if (hull == null || arrivedTarget(packedPosition, moves.heading(move)) == WorldPointUtil.UNDEFINED)
		{
			return false;
		}
		int region = regionIndex(x, y, z);
		if (region < 0)
		{
			return false;
		}
		int[][] byRegion = queuedArrivals[bankVisited == BankVisitState.BANKED ? 1 : 0];
		int[] arrivals = byRegion[region];
		if (arrivals == null)
		{
			arrivals = new int[REGION_SIZE * REGION_SIZE];
			byRegion[region] = arrivals;
		}
		int index = tileIndex(x, y);
		int bit = 1 << move;
		if ((arrivals[index] & bit) != 0)
		{
			return false;
		}
		arrivals[index] |= bit;
		return true;
	}

	/**
	 * Lets go of the costs noted per tile, and the hull's caches, once the search is done.
	 */
	void release()
	{
		Arrays.fill(queuedCosts[0], null);
		Arrays.fill(queuedCosts[1], null);
		Arrays.fill(queuedArrivals[0], null);
		Arrays.fill(queuedArrivals[1], null);
		if (hull != null)
		{
			hull.release();
		}
	}

	// Sailing moves are different lengths, so they are queued by cost on the pending heap like transports rather than
	// the FIFO boundary queue, which is only ordered for unit-cost walking edges: each costs the distance it sails, so
	// the search finds the shortest route rather than the quickest. A tile is only queued again if a route reaches it
	// for less, since a dearer one would only be dequeued once the tile is done — or, with a hull, if a dearer move
	// would arrive on a heading none has tried, since the cheapest route's facing may not cover a target. The cost
	// check comes first, which costs less than the line or hull check. With a hull, the whole boat must fit along the
	// move, which also keeps its centre clear.
	void addNeighbors(CollisionMap map, PrimitiveIntList out, int node, int x, int y, int z, BankVisitState bankVisited,
		VisitedTiles visited, NodeGraph graph)
	{
		// The boat faces the way it sailed into the node — or, on the start node, the way it's pointing, so
		// carrying straight on isn't a turn but putting about first is
		final int arrivalHeading = arrivalHeading(graph, node);
		// The first move gets the hull's berthed-tile escape: a boat can sit over tiles it then sails off
		final boolean firstMove = graph.moveIndex(node) < 0;
		final int costSoFar = graph.cost(node);
		for (int i = 0; i < moves.size(); i++)
		{
			final int dx = moves.dx(i);
			final int dy = moves.dy(i);
			final int neighborPacked = WorldPointUtil.packWorldPoint(x + dx, y + dy, z);
			final int cost = moves.length(i) + (arrivalHeading >= 0 && arrivalHeading != moves.heading(i) ? SAILING_COST_PER_TURN : 0);
			if (visited.get(neighborPacked, bankVisited)
				|| (costSoFar + cost >= queuedCost(x + dx, y + dy, z, bankVisited)
					&& !queueArrival(neighborPacked, i, x + dx, y + dy, z, bankVisited))
				|| !(hull == null ? canSailLine(map, x, y, z, dx, dy)
					: hull.canMove(map, x, y, z, moves.heading(i), dx, dy, firstMove)))
			{
				continue;
			}
			out.add(graph.createWeightedTile(neighborPacked, node, cost, estimate(x + dx, y + dy), bankVisited, i));
		}
	}

	/**
	 * Whether a straight sailing move from tile (x, y, z) by (dx, dy) tiles only crosses open tiles: every tile the
	 * line between the tile centres passes through must be one walking step from the previous one, so a move never
	 * passes over a blocked tile (such as the blocked strip along coastlines). Where the line passes exactly through a
	 * tile corner, both ways around the corner must be open.
	 */
	public static boolean canSailLine(CollisionMap map, int x, int y, int z, int dx, int dy)
	{
		final int nx = Math.abs(dx);
		final int ny = Math.abs(dy);
		final int sx = Integer.signum(dx);
		final int sy = Integer.signum(dy);
		// From a blocked tile, such as one a moored boat sits on, any open tile next to it can be entered, as when
		// walking. Every tile after the first is entered through an open side, so it isn't blocked either.
		boolean fromBlocked = map.isBlocked(x, y, z);
		int cx = x;
		int cy = y;
		int ix = 0;
		int iy = 0;
		while (ix < nx || iy < ny)
		{
			// Compares where the line crosses the next vertical and horizontal tile edges
			long decision = (long) (1 + 2 * ix) * ny - (long) (1 + 2 * iy) * nx;
			if (decision == 0)
			{
				if (!canCross(map, cx, cy, z, sx, 0, fromBlocked) || !canCross(map, cx + sx, cy, z, 0, sy, false)
					|| !canCross(map, cx, cy, z, 0, sy, fromBlocked) || !canCross(map, cx, cy + sy, z, sx, 0, false))
				{
					return false;
				}
				cx += sx;
				cy += sy;
				ix++;
				iy++;
			}
			else if (decision < 0)
			{
				if (!canCross(map, cx, cy, z, sx, 0, fromBlocked))
				{
					return false;
				}
				cx += sx;
				ix++;
			}
			else
			{
				if (!canCross(map, cx, cy, z, 0, sy, fromBlocked))
				{
					return false;
				}
				cy += sy;
				iy++;
			}
			fromBlocked = false;
		}
		return true;
	}

	// Whether a boat can cross from tile (x, y, z) into the tile next to it (ex, ey) away, one of which is 0: through
	// the open side between them, or from a blocked tile into any open one
	private static boolean canCross(CollisionMap map, int x, int y, int z, int ex, int ey, boolean fromBlocked)
	{
		if (fromBlocked)
		{
			return !map.isBlocked(x + ex, y + ey, z);
		}
		if (ey == 0)
		{
			return ex < 0 ? map.w(x, y, z) : map.e(x, y, z);
		}
		return ey < 0 ? map.s(x, y, z) : map.n(x, y, z);
	}

	// Index of the region and plane holding tile (x, y, z), or -1 if it's off the map
	private int regionIndex(int x, int y, int z)
	{
		int regionX = (x >> REGION_SHIFT) - extent.getMinX();
		int regionY = (y >> REGION_SHIFT) - extent.getMinY();
		if (regionX < 0 || regionY < 0 || regionX > extent.getWidth() || regionY > extent.getHeight() || z < 0 || z >= PLANES)
		{
			return -1;
		}
		return (regionX + regionY * (extent.getWidth() + 1)) * PLANES + z;
	}

	private static int tileIndex(int x, int y)
	{
		return ((y & REGION_MASK) << REGION_SHIFT) | (x & REGION_MASK);
	}
}

