/**
 * The single public boundary for POH (Player Owned House) domain behavior:
 * geometry (the POH bounds and the canonical landing tile), transport
 * destination remapping, feature enablement, and portal nexus keybinds.
 * <p>
 * This class owns the geometry contract verbatim — the bounds and landing
 * constants plus the inclusive-bounds {@link #isInsidePoh} predicate that
 * every POH geometry read crosses. The pure domain functions are statics so
 * they are reachable from construction-time and static-init call sites (the
 * transport load path remaps destinations before any service instance could
 * be injected). The portal nexus keybind machinery is instance state: it
 * persists through {@link ConfigManager} (RSProfile) and so needs injection
 * plus a detached-test seam. POH exit-info display — the label composition
 * over the exit transports — lives on the presentation annotator; this
 * service exposes only the narrow reads it consumes ({@link #apply} for
 * nexus-keybind label rewriting and the {@link #isInsidePoh} bounds
 * predicate).
 */
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class PohService
{
	// POH (Player Owned House) bounds for detecting when path goes through POH
	// Note: POH_MIN_X is 1856 to exclude the Daddy's Home miniquest area
	private static final int POH_MIN_X = 1856;
	private static final int POH_MAX_X = 2047;
	private static final int POH_MIN_Y = 7040;
	private static final int POH_MAX_Y = 7111;
	// Co-ordinates for Basic theme landing tile
	public static final int POH_LANDING_X = 1858;
	public static final int POH_LANDING_Y = 7051;

	/**
	 * Checks if the given coordinates are inside the POH (Player Owned House) area.
	 *
	 * @param x The world X coordinate
	 * @param y The world Y coordinate
	 * @return true if inside POH, false otherwise
	 */
	public static boolean isInsidePoh(int x, int y)
	{
		return x >= POH_MIN_X && x <= POH_MAX_X && y >= POH_MIN_Y && y <= POH_MAX_Y;
	}

	/**
	 * Remaps POH transport destinations to the house landing tile.
	 * Transports that arrive inside the POH (e.g., fairy ring DIQ, spirit tree "Your house")
	 * are remapped so chaining with other POH transports is possible.
	 * Called once at load time since Transport objects in allTransports are shared references.
	 */
	public static void remapPohDestinations(Map<Integer, Set<Transport>> transports)
	{
		int pohLanding = WorldPointUtil.packWorldPoint(POH_LANDING_X, POH_LANDING_Y, 0);
		for (Set<Transport> transportSet : transports.values())
		{
			for (Transport transport : transportSet)
			{
				int destination = transport.getDestination();
				int destX = WorldPointUtil.unpackWorldX(destination);
				int destY = WorldPointUtil.unpackWorldY(destination);
				if (destination != pohLanding && isInsidePoh(destX, destY))
				{
					transport.setDestination(pohLanding);
				}
			}
		}
	}

	public static boolean isNexusPortalEnabled(Set<PohNexusPortal> enabledPortals, String displayInfo)
	{
		PohNexusPortal portal = PohNexusPortal.fromDisplayInfo(displayInfo);
		return portal == null || enabledPortals.contains(portal);
	}

	public static boolean isMountedItemEnabled(Set<PohMountedItem> enabledItems, String objectInfo)
	{
		PohMountedItem item = PohMountedItem.fromObjectInfo(objectInfo);
		return item == null || enabledItems.contains(item);
	}

	/**
	 * Checks if a TELEPORTATION_BOX transport should be used based on POH settings.
	 * Handles jewellery box tiers and mounted items.
	 */
	public static boolean jewelleryBoxSatisfied(JewelleryBoxTier tier, Set<PohMountedItem> enabledItems, Transport transport)
	{
		String objectInfo = transport.getObjectInfo();
		if (objectInfo == null)
		{
			return false;
		}

		PohMountedItem mountedItem = PohMountedItem.fromObjectInfo(objectInfo);
		if (mountedItem != null)
		{
			// If mounted glory and ornate jewellery box is enabled, skip the glory
			// because the ornate box already covers all 4 destinations with correct prefixes
			if (PohMountedItem.GLORY.equals(mountedItem) && JewelleryBoxTier.ORNATE.equals(tier))
			{
				return false;
			}
			return isMountedItemEnabled(enabledItems, objectInfo);
		}

		// Filter jewellery boxes by tier
		if (JewelleryBoxTier.NONE.equals(tier))
		{
			return false;
		}

		// Basic box (37492): destinations 1-9
		if (objectInfo.contains("Basic Jewellery Box 37492"))
		{
			return true; // All tiers include basic
		}

		// Fancy box (37501): destinations A-J
		if (objectInfo.contains("Fancy Jewellery Box 37501"))
		{
			return JewelleryBoxTier.FANCY.equals(tier) ||
				JewelleryBoxTier.ORNATE.equals(tier);
		}

		// Ornate box (37520): destinations K-R
		if (objectInfo.contains("Ornate Jewellery Box 37520"))
		{
			return JewelleryBoxTier.ORNATE.equals(tier);
		}

		return false;
	}

	/**
	 * Per-type POH variant enablement: each POH-capable transport type reads
	 * its own toggle, and a nexus portal checks the enabled-portal set.
	 * Transports without a POH variant pass.
	 */
	public static boolean variantEnabled(Transport transport, boolean usePohFairyRing,
		boolean usePohSpiritTree, boolean usePohObelisk, Set<PohNexusPortal> enabledPortals)
	{
		TransportType type = transport.getType();

		// POH fairy ring
		if (TransportType.FAIRY_RING.equals(type))
		{
			return usePohFairyRing;
		}
		// POH spirit tree
		if (TransportType.SPIRIT_TREE.equals(type))
		{
			return usePohSpiritTree;
		}
		// POH obelisk
		if (TransportType.WILDERNESS_OBELISK.equals(type))
		{
			return usePohObelisk;
		}
		if (TransportType.TELEPORTATION_PORTAL_POH.equals(type))
		{
			return isNexusPortalEnabled(enabledPortals, transport.getDisplayInfo());
		}

		return true;
	}

	/*
	 * Live Portal Nexus Teleport Menu keys. Slot order is player-configurable, so
	 * keybinds are read from the teleport dialog whenever it is built rather than
	 * assumed from the default destination list.
	 *
	 * Only lines carrying an explicit "key : name" prefix produce a mapping.
	 * Lines whose key hint is rendered as a sprite carry no readable prefix, and
	 * lines the game does not key at all render no hint; neither can be assigned
	 * a key from their position — other plugins (e.g. Better Teleport Menu) can
	 * rebind or strip keys, so a position-derived key may not exist in game.
	 */
	public static final int TELENEXUS_CREATE_TELELINE = 2675;

	// The dialog takes a few client ticks to populate its lines, so the
	// open arm retries the read up to this many times.
	private static final int NEXUS_DIALOG_REFRESH_ATTEMPTS = 10;

	// In-game labels look like "<col=ffffff>1 : Harmony Island" (space before the colon).
	private static final Pattern KEYED_LINE = Pattern.compile("^([1-9A-Za-z]|F(?:[1-9]|1[0-2]))\\s*:\\s*(.+)$");
	private static final Pattern PARENTHETICAL = Pattern.compile("\\(([^()]*)\\)");
	private static final String SERIAL_VERSION = "2";
	private static Map<String, String> nameAliases()
	{
		Map<String, String> aliases = new HashMap<>();
		try
		{
			Util.each("/poh-name-aliases.tsv", (line, c) -> aliases.put(c[0], c[1]));
		}
		catch (Exception e)
		{
			throw new IllegalStateException("failed to load poh-name-aliases.tsv", e);
		}
		return Map.copyOf(aliases);
	}

	private static final Map<String, String> NAME_ALIASES = nameAliases();
	static final String CONFIG_KEY = "portalNexusKeybinds";

	private final ConfigManager configManager;
	private final RefreshCoordinator coordinator;
	private final GameWidgets gameWidgets;
	private volatile Map<String, String> keysByNormalizedName = Map.of();
	private String lastSaved = "";
	private boolean dirty;

	/**
	 * Detached-coordinator seam for tests that exercise persistence without
	 * asserting declares — the declare no-ops on the missing coordinator.
	 */
	PohService(ConfigManager configManager)
	{
		this(configManager, null, null);
	}

	/**
	 * Reads the current keybind map from the open Portal Nexus dialog and
	 * declares the resulting fact to the coordinator. Returns whether at
	 * least one mapping was found — the dialog-retry predicate consumes the
	 * signal as "something parsed", so an identical re-read still answers
	 * {@code true} even when its fact carries no effects.
	 */
	public boolean refreshFromDialog()
	{
		if (gameWidgets == null)
		{
			return false;
		}
		PohChange change = refreshFromTeleportMenu();
		if (change == null)
		{
			change = refreshFromConfigurationSlots();
		}
		declare(change);
		return change != null;
	}

	public String apply(String displayInfo)
	{
		Map<String, String> keys = keysByNormalizedName;
		if (displayInfo == null || displayInfo.isEmpty() || keys.isEmpty())
		{
			return displayInfo;
		}

		String base = stripKeyPrefix(displayInfo);
		String key = keys.get(normalize(base));
		if (key == null)
		{
			return base;
		}
		return key + ": " + base;
	}

	/**
	 * Marks that the teleport menu is (re)building. The dialog is authoritative
	 * for its hotkeys: keys are relearned from its lines and widget text on
	 * every open, so cached mappings for slots the player unassigned must be
	 * dropped before the new build is observed.
	 */
	public void dialogOpened()
	{
		boolean changed = !keysByNormalizedName.isEmpty();
		keysByNormalizedName = Map.of();
		dirty = true;
		declare(new PohChange("dialogOpen", changed ? Set.of(Effect.DISPLAY_ONLY) : Set.of()));
	}

	/**
	 * Schedules the nexus-dialog refresh retries on the client thread: each
	 * tick re-reads whichever nexus interface is still open until
	 * {@link #refreshFromDialog()} reports a populated read or the attempt
	 * cap is reached. {@code clientThread} is a parameter, not an injected
	 * field — the shell passes its own reference in, and detached service
	 * instances never reach this method.
	 */
	public void nexusDialogOpened(ClientThread clientThread)
	{
		final int[] attempts = {0};
		clientThread.invokeLater(() ->
		{
			attempts[0]++;
			boolean dialogOpen = gameWidgets != null
				&& (gameWidgets.isWidgetOpen(InterfaceID.TelenexusTeleport.UNIVERSE)
					|| gameWidgets.isWidgetOpen(InterfaceID.Telenexus.UNIVERSE));
			if (!dialogOpen)
			{
				return attempts[0] >= NEXUS_DIALOG_REFRESH_ATTEMPTS;
			}
			boolean changed = refreshFromDialog();
			return changed || attempts[0] >= NEXUS_DIALOG_REFRESH_ATTEMPTS;
		});
	}

	/**
	 * Records one teleport menu line as it is created by the client and
	 * declares the learned-keybind fact to the coordinator. Only an
	 * explicit "key : name" prefix in the line text produces a mapping; a
	 * line without a prefix carries no keybind information and is ignored.
	 */
	public void putFromDialogLine(String rawText)
	{
		String cleaned = rawText == null ? "" : Text.removeTags(rawText).trim();
		Matcher matcher = KEYED_LINE.matcher(cleaned);
		if (!matcher.matches())
		{
			return;
		}
		Map<String, String> learned = new HashMap<>(keysByNormalizedName);
		putMapping(learned, matcher.group(2), matcher.group(1).toUpperCase(Locale.ROOT));
		keysByNormalizedName = learned;
		dirty = true;
		declare(new PohChange("dialogLine", Set.of(Effect.DISPLAY_ONLY)));
	}

	/**
	 * Reloads the persisted keybind map for the active profile. A profile load
	 * always declares a {@code DISPLAY_ONLY} fact once storage was consulted —
	 * the map it republished may differ from the previous account's — and
	 * declares nothing when running detached (no ConfigManager).
	 */
	public void loadFromProfile()
	{
		dirty = false;
		keysByNormalizedName = Map.of();
		lastSaved = "";
		if (configManager == null)
		{
			return;
		}
		String stored = configManager.getRSProfileConfiguration(Settings.CONFIG_GROUP, CONFIG_KEY);
		Map<String, String> loaded = new HashMap<>();
		deserialize(stored, loaded);
		keysByNormalizedName = loaded;
		lastSaved = serialize(loaded);
		declare(new PohChange("profile", Set.of(Effect.DISPLAY_ONLY)));
	}

	public void persistIfDirty()
	{
		if (!dirty)
		{
			return;
		}
		dirty = false;
		saveToProfile();
	}

	/**
	 * Hands an admitted fact to the refresh coordinator. Detached
	 * instances (built with a null coordinator) carry none, so the declare
	 * no-ops there; a null fact declares nothing, mirroring the return-null
	 * convention the shell's mapper used to guard.
	 */
	private void declare(PohChange change)
	{
		if (change != null && coordinator != null)
		{
			coordinator.pohChanged(change);
		}
	}

	PohChange refreshFromTeleportMenu()
	{
		Map<String, String> parsed = new HashMap<>();
		// Primary labels are TEXT1; diary/alternate names (GE, Seers, Yanille) are EXTRAS.
		collectKeyedTexts(gameWidgets.selfAndChildTexts(InterfaceID.TelenexusTeleport.TEXT1), parsed);
		collectKeyedTexts(gameWidgets.selfAndChildTexts(InterfaceID.TelenexusTeleport.EXTRAS), parsed);
		return replaceIfPresent(parsed);
	}

	PohChange refreshFromConfigurationSlots()
	{
		List<String> names = new ArrayList<>();
		collectSlotNames(gameWidgets.selfAndChildTexts(InterfaceID.Telenexus.SLOTTED_LIST), names);
		if (names.isEmpty())
		{
			collectSlotNames(gameWidgets.selfAndChildTexts(InterfaceID.Telenexus.ROWS2), names);
		}
		return replaceIfPresent(parseSlotLabels(names));
	}

	static String stripKeyPrefix(String displayInfo)
	{
		Matcher matcher = KEYED_LINE.matcher(displayInfo);
		if (matcher.matches())
		{
			return matcher.group(2);
		}
		return displayInfo;
	}

	static String normalize(String name)
	{
		String stripped = Text.removeTags(name).toLowerCase(Locale.ROOT).trim();
		if (stripped.startsWith("respawn"))
		{
			return "respawn";
		}

		stripped = stripped.replace("portal", " ");
		stripped = stripped.replace("teleport to", " ");
		stripped = stripped.replace("the ", " ");
		stripped = stripped.replaceAll("\\([^)]*\\)", " ");
		stripped = stripped.replaceAll("[^a-z0-9]+", " ").trim().replaceAll(" +", " ");

		return NAME_ALIASES.getOrDefault(stripped, stripped);
	}

	PohChange replaceIfPresent(Map<String, String> parsed)
	{
		if (parsed.isEmpty())
		{
			return null;
		}
		Map<String, String> current = keysByNormalizedName;
		if (current.isEmpty() || parsed.size() >= current.size())
		{
			Set<Effect> effects = current.equals(parsed)
				? Set.of()
				: Set.of(Effect.DISPLAY_ONLY);
			keysByNormalizedName = Map.copyOf(parsed);
			dirty = false;
			saveToProfile();
			return new PohChange("dialog", effects);
		}

		// A partially-built dialog can contain only some rows. Keep cached keys for
		// destinations that are not in this snapshot and do not persist a shrink.
		boolean changed = false;
		for (Map.Entry<String, String> entry : parsed.entrySet())
		{
			if (!entry.getValue().equals(current.get(entry.getKey())))
			{
				changed = true;
				break;
			}
		}
		Map<String, String> merged = new HashMap<>(current);
		merged.putAll(parsed);
		keysByNormalizedName = merged;
		return new PohChange("dialog", changed ? Set.of(Effect.DISPLAY_ONLY) : Set.of());
	}

	static Map<String, String> parseSlotLabels(List<String> names)
	{
		Map<String, String> parsed = new HashMap<>();
		if (names == null || names.isEmpty())
		{
			return parsed;
		}

		for (String name : names)
		{
			parseKeyedText(name, parsed);
		}
		return parsed;
	}

	static String serialize(Map<String, String> keys)
	{
		if (keys.isEmpty())
		{
			return "";
		}
		List<String> names = new ArrayList<>(keys.keySet());
		Collections.sort(names);
		StringBuilder sb = new StringBuilder(SERIAL_VERSION);
		for (String name : names)
		{
			if (sb.length() > 0)
			{
				sb.append('|');
			}
			sb.append(name).append('=').append(keys.get(name));
		}
		return sb.toString();
	}

	static void deserialize(String stored, Map<String, String> keys)
	{
		if (stored == null || stored.isEmpty())
		{
			return;
		}
		String[] entries = stored.split("\\|");
		// Entries persisted by older versions could contain keys derived from
		// line position rather than an observed binding, and cannot be told
		// apart from real ones; they are relearned from the dialog on next open.
		if (!SERIAL_VERSION.equals(entries[0]))
		{
			return;
		}
		for (int i = 1; i < entries.length; i++)
		{
			String entry = entries[i];
			int split = entry.indexOf('=');
			if (split <= 0 || split == entry.length() - 1)
			{
				continue;
			}
			String name = entry.substring(0, split);
			String key = entry.substring(split + 1).toUpperCase(Locale.ROOT);
			if (key.matches("[1-9A-Z]|F(?:[1-9]|1[0-2])"))
			{
				keys.put(name, key);
			}
		}
	}

	private void saveToProfile()
	{
		Map<String, String> keys = keysByNormalizedName;
		if (configManager == null || keys.isEmpty())
		{
			return;
		}
		String serialized = serialize(keys);
		if (serialized.equals(lastSaved))
		{
			return;
		}
		lastSaved = serialized;
		configManager.setRSProfileConfiguration(Settings.CONFIG_GROUP, CONFIG_KEY, serialized);
	}

	private static void collectKeyedTexts(List<String> texts, Map<String, String> parsed)
	{
		for (String text : texts)
		{
			parseKeyedText(text, parsed);
		}
	}

	private static void collectSlotNames(List<String> texts, List<String> names)
	{
		for (String text : texts)
		{
			collectSlotName(text, names);
		}
	}

	private static void collectSlotName(String rawText, List<String> names)
	{
		if (rawText == null || rawText.isEmpty())
		{
			return;
		}
		String cleaned = Text.removeTags(rawText).trim();
		if (cleaned.isEmpty() || "Slots".equalsIgnoreCase(cleaned) || "Available".equalsIgnoreCase(cleaned))
		{
			return;
		}
		Matcher matcher = KEYED_LINE.matcher(cleaned);
		if (!normalize(matcher.matches() ? matcher.group(2) : cleaned).isEmpty() && !names.contains(cleaned))
		{
			names.add(cleaned);
		}
	}

	private static void parseKeyedText(String rawText, Map<String, String> parsed)
	{
		if (rawText == null || rawText.isEmpty())
		{
			return;
		}
		Matcher matcher = KEYED_LINE.matcher(Text.removeTags(rawText).trim());
		if (matcher.matches())
		{
			putMapping(parsed, matcher.group(2), matcher.group(1).toUpperCase(Locale.ROOT));
		}
	}

	private static void putMapping(Map<String, String> parsed, String destinationName, String key)
	{
		putNormalized(parsed, destinationName, key);

		// "Frozen Waste Plateau (Ghorrock)" must also match TSV "Ghorrock Portal".
		Matcher matcher = PARENTHETICAL.matcher(destinationName);
		while (matcher.find())
		{
			putNormalized(parsed, matcher.group(1), key);
		}
		int split = destinationName.indexOf('(');
		if (split > 0)
		{
			putNormalized(parsed, destinationName.substring(0, split), key);
		}
	}

	private static void putNormalized(Map<String, String> parsed, String destinationName, String key)
	{
		String normalized = normalize(destinationName);
		if (!normalized.isEmpty())
		{
			parsed.put(normalized, key);
		}
	}

}

package shortestpath.presentation;

import java.util.*;
import java.util.stream.Collectors;
import net.runelite.api.*;
import shortestpath.pathfinder.*;
import shortestpath.requirement.model.TransportItems;

/**
 * Determines what items need to be picked up from the bank for a given path.
 * Multiple transports that connect the same edge are treated as alternatives (OR):
 * if the player can satisfy any one of them, no pickup is needed; otherwise the
 * alternatives the bank can fully supply are shown joined by "or".
 * All item evaluation comes from the {@link TransportEligibility} snapshot captured
 * at refresh time — the same evaluation the pathfinder used — keyed by the transport
 * recorded on each path step rather than re-derived here.
 */
@SuppressWarnings("unused") // Only static methods are used, incorrectly flagged
public final class BankPickupRequirements
{

	/** Combined result of a bank pickup computation: display phrases and item IDs for highlighting. */
	public static class BankPickupResult
	{
		public final List<String> phrases;
		public final Set<Integer> bankItemIds;

		BankPickupResult(List<String> phrases, Set<Integer> bankItemIds)
		{
			this.phrases = phrases;
			this.bankItemIds = bankItemIds;
		}

		/**
		 * Formats a raw {@link BankPickupAnalysis} for display: each group of
		 * alternative pickup maps becomes one phrase joined by " or ", with
		 * identical phrases collapsed (two edges can ask for the same items).
		 */
		public static BankPickupResult format(Client client, BankPickupAnalysis analysis)
		{
			if (analysis == null)
			{
				return null;
			}
			List<String> phrases = new ArrayList<>(new LinkedHashSet<>(
				analysis.pickupAlternatives.stream()
					.map(alternatives -> alternatives.stream()
						.map(items -> formatPickups(client, items))
						.collect(Collectors.joining(" or ")))
					.collect(Collectors.toList())));
			return new BankPickupResult(phrases, analysis.bankItemIds);
		}

		/**
		 * Computes the bank pickup requirements for a given bank step in the path.
		 * Returns both the human-readable pickup phrases (for display) and the item IDs
		 * (for bank slot highlighting) in a single pass over the remaining path.
		 *
		 * @param client           The game client
		 * @param bank             The bank ItemContainer — only null-checked to gate
		 *                         "a bank is open"; the bank contents themselves come
		 *                         from the eligibility snapshot
		 * @param pathfinderConfig The pathfinder config for bank-aware transport lookups
		 * @param bankLocations    Set of bank location coordinates
		 * @param path             The current path
		 * @param pathIndex        The current step index in the path
		 * @return BankPickupResult with phrases and item IDs, or an empty result if not at a bank step
		 */
		public static BankPickupResult compute(
			Client client,
			ItemContainer bank,
			PathfinderConfig pathfinderConfig,
			Set<Integer> bankLocations,
			List<PathStep> path,
			int pathIndex)
		{
			return compute(client, bank, pathfinderConfig, bankLocations, path, pathIndex, null);
		}

		/**
		 * As {@link #compute(Client, ItemContainer, PathfinderConfig, Set, List, int)}, also
		 * listing {@code targetItems} — the items the path's target needs on arrival — at the
		 * bank step where the path visits the bank.
		 */
		public static BankPickupResult compute(
			Client client,
			ItemContainer bank,
			PathfinderConfig pathfinderConfig,
			Set<Integer> bankLocations,
			List<PathStep> path,
			int pathIndex,
			TransportItems targetItems)
		{
			return format(client, BankPickupAnalysis.analyze(
				bank, pathfinderConfig, bankLocations, path, pathIndex, targetItems));
		}
	}

	/**
	 * Formats a pickup map (item id to quantity) as a comma-separated, human-readable string.
	 */
	static String formatPickups(Client client, Map<Integer, Long> pickups)
	{
		List<String> parts = new ArrayList<>(pickups.size());
		for (Map.Entry<Integer, Long> entry : pickups.entrySet())
		{
			int itemId = entry.getKey();
			long qty = entry.getValue();
			// A detached item-state service passes no client —
			// degrade to the placeholder name rather than throwing.
			String itemName = client == null ? null : client.getItemDefinition(itemId).getName();
			if (itemName == null || itemName.isEmpty() || "null".equals(itemName))
			{
				itemName = "Unknown item";
			}
			boolean isCurrency = TransportItems.CURRENCIES.contains(itemId);
			if (isCurrency)
			{
				if (qty > 1)
				{
					itemName += " (" + String.format("%,d", qty) + ")";
				}
			}
			else
			{
				itemName = qty + " " + itemName;
			}
			parts.add(itemName);
		}
		return String.join(", ", parts);
	}
}

package shortestpath.presentation;

import java.util.*;

import javax.inject.*;

import lombok.RequiredArgsConstructor;

import net.runelite.api.*;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;

import shortestpath.*;
import shortestpath.items.ItemStateService;
import shortestpath.pathfinder.*;
import shortestpath.poh.PohService;
import shortestpath.presentation.BankPickupRequirements.BankPickupResult;
import shortestpath.requirement.TransportEligibility;
import shortestpath.requirement.model.ItemRequirement;
import shortestpath.transport.*;

/**
 * The presentation leaf: owns the shared edge-annotation and display
 * surface that the protocol serializers, the overlays, and the fairy-ring
 * panel all read — per-edge transport reconstruction, transport label
 * rewriting, POH exit display, the fairy-ring scroll block, and the
 * coarse display facades over the attached {@link PathfinderConfig}.
 * <p>
 * This package is a leaf: nothing here may reference the plugin type.
 * The engine config is late-bound by {@link #attach(PathfinderConfig)}
 * because the shell still constructs it in {@code startUp} and Guice
 * cannot inject it. A detached annotator — one built without its
 * collaborators or never attached — answers every display read with its
 * empty/no-op arm rather than throwing.
 */
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class PathAnnotator
{
	/**
	 * Ordered {@code objInfo.contains} matcher → label-prefix pairs for the
	 * teleportation-box arm of {@link #getPohExitInfo}; the first match wins,
	 * and an unmatched (or absent) object info falls back to
	 * {@link #OBJINFO_FALLBACK_LABEL}. Package-visible so the label table is
	 * test-pinned.
	 */
	static final List<List<String>> OBJINFO_LABELS = List.of(
		List.of("Amulet of Glory", "Mounted Glory: "),
		List.of("Mythical cape", "Mythical Cape: "),
		List.of("Xeric's Talisman", "Xeric's Talisman: "),
		List.of("Digsite", "Digsite Pendant: "));
	static final String OBJINFO_FALLBACK_LABEL = "Jewelry Box: ";

	/**
	 * Label prefix per exit-transport type for {@link #getPohExitInfo}; a
	 * type absent from the map (including a null type) passes its display
	 * info through unprefixed, and the teleportation box takes the
	 * {@link #OBJINFO_LABELS} arm instead. The fairy-ring entry's missing
	 * colon is upstream display text, not a typo.
	 */
	static final Map<TransportType, String> EXIT_PREFIX = Map.of(
		TransportType.TELEPORTATION_PORTAL_POH, "Nexus: ",
		TransportType.FAIRY_RING, "Fairy Ring ",
		TransportType.SPIRIT_TREE, "Spirit Tree: ",
		TransportType.WILDERNESS_OBELISK, "Obelisk: ");

	private final Client client;
	private final PohService pohService;
	private final ItemStateService itemState;

	/**
	 * Late-bound by {@link #attach(PathfinderConfig)}: the shell still owns
	 * {@link PathfinderConfig} construction, so it cannot ride the
	 * constructor.
	 */
	private PathfinderConfig pathfinderConfig;

	private boolean fairyRingPanelOpen = false;
	// The missing-items label of missingItemsSearch, built on the client thread when first drawn.
	private ActiveSearch missingItemsSearch;
	private String missingItemsText;

	PathAnnotator(PohService pohService, ItemStateService itemState)
	{
		this(null, pohService, itemState);
	}

	/**
	 * Hands over the engine config the shell constructed in {@code startUp}.
	 * Every config-backed read resolves through this attachment; reads made
	 * before it lands take the detached arm.
	 */
	public void attach(PathfinderConfig pathfinderConfig)
	{
		this.pathfinderConfig = pathfinderConfig;
	}

	/**
	 * The label naming the items the displayed route's target needs but the player was not found to
	 * hold, or {@code null} when nothing is missing. Built once per search, on the client thread.
	 */
	public String getMissingTargetItemsText(ActiveSearch search)
	{
		if (search != missingItemsSearch)
		{
			missingItemsSearch = search;
			missingItemsText = null;
		}
		PathfinderResult result = search == null ? null : search.getResult();
		if (missingItemsText == null && result != null)
		{
			Arrival arrival = result.getArrival();
			List<ItemRequirement> missing = arrival == null ? List.of() : arrival.getMissingItems();
			missingItemsText = missing.isEmpty() ? "" : missingItemsLabel(missing);
		}
		return missingItemsText == null || missingItemsText.isEmpty() ? null : missingItemsText;
	}

	/** "Not found in inventory or bank: Spade, Rope or Knife", one entry per missing item group. */
	private String missingItemsLabel(List<ItemRequirement> missing)
	{
		List<String> groups = new ArrayList<>(missing.size());
		for (ItemRequirement group : missing)
		{
			List<String> names = new ArrayList<>();
			for (ItemRequirement.Branch branch : group.getBranches())
			{
				for (int id : branch.getItemIds())
				{
					// Requirement ids come from other plugins' messages; an invalid or renamed
					// id may resolve to no name rather than crash every rendered frame.
					ItemComposition def = client.getItemDefinition(id);
					String name = def == null ? null : def.getName();
					names.add(name == null || name.isEmpty() || "null".equals(name) ? "Item " + id : name);
				}
			}
			groups.add(String.join(" or ", names));
		}
		return "Not found in inventory or bank: " + String.join(", ", groups)
			+ (pathfinderConfig.getHeldItems().isBankSeen() ? "" : " (bank not checked)");
	}

	/**
	 * This reconstructs the candidate transports for a rendered path edge from the current path state.
	 * <p>
	 * The important detail is that path display logic is edge-based, not node-based:
	 * - origin position comes from currentStep
	 * - destination position comes from nextStep
	 * - the applicable transport set may depend on whether the edge transitions into banked state
	 * <p>
	 * That last point is the awkward one. Banking is not represented as its own explicit path edge;
	 * instead the "becomes banked" state change is conflated into the movement/transport edge that
	 * reaches the banked destination step. As a result, callers cannot safely resolve transports from
	 * a single PathStep alone: using only currentStep can miss bank-gated transports, while using only
	 * nextStep loses the origin tile of the edge. This helper therefore takes both steps and resolves
	 * transports for the edge between them.
	 * <p>
	 * When the destination step carries the transport the search actually chose (steps built by
	 * {@link NodeGraph#getPathSteps} do), that transport is the answer and this function returns
	 * it directly as a singleton — reconstruction is only a fallback for identity-less steps
	 * (e.g. steps built via the two-argument {@link PathStep} constructor). The destination-based
	 * fallback remains inherently ambiguous when multiple valid transports share the same
	 * origin/destination pair under the same edge state.
	 * <p>
	 * Note that the fallback also performs filtering by the transport target, so callers of this
	 * function can directly iterate over the returned transports.
	 */
	public Set<Transport> transportsForEdge(PathStep currentStep, PathStep nextStep)
	{
		if (currentStep == null || nextStep == null)
		{
			return Set.of();
		}
		// The step knows which transport produced the edge into it: no reconstruction needed.
		if (nextStep.getTransport() != null)
		{
			return Set.of(nextStep.getTransport());
		}
		if (pathfinderConfig == null)
		{
			// Detached (un-attached or built without collaborators) annotator — no engine config
			// to reconstruct the edge against.
			return Set.of();
		}
		BankVisitState bankVisitState =
			currentStep.getBankVisitState() == BankVisitState.BANKED
				|| nextStep.getBankVisitState() == BankVisitState.BANKED
				? BankVisitState.BANKED : BankVisitState.CARRIED;
		// Get the transports which start from the position of starting step.
		Set<Transport> stepTransports = new HashSet<>(Arrays.asList(
			pathfinderConfig.getTransportsPacked(bankVisitState)
				.getOrDefault(currentStep.getPackedPosition(), TransportAvailability.EMPTY_TRANSPORTS)));
		// Add the teleports, which might be used from anywhere.
		stepTransports.addAll(Arrays.asList(pathfinderConfig.getUsableTeleports(bankVisitState)));
		// Remove transports which do not target the correct location.
		stepTransports.removeIf(transport -> transport.getDestination() != nextStep.getPackedPosition());
		// Remove teleports that share destinations with a local transport type on this edge.
		// For example, if the path uses a QUETZAL (local) transport, suppress QUETZAL_WHISTLE hints.
		// Also suppress them when the edge distance is within the shared type's radius threshold,
		// which occurs when the path is simply walking to a landing site (not teleporting to it).
		Set<TransportType> localTypes = EnumSet.noneOf(TransportType.class);
		for (Transport t : stepTransports)
		{
			if (t.getOrigin() != Transport.UNDEFINED_ORIGIN && t.getType() != null)
			{
				localTypes.add(t.getType());
			}
		}
		int edgeDistance = WorldPointUtil.distanceBetween2D(currentStep.getPackedPosition(), nextStep.getPackedPosition());
		stepTransports.removeIf(t ->
		{
			if (t.getOrigin() != Transport.UNDEFINED_ORIGIN || t.getType() == null)
			{
				return false; // keep local transports
			}
			if (edgeDistance <= 1)
			{
				// A single-tile edge is a walked step, so the path did not teleport
				// here: the destination tile is just a teleport landing site the
				// path passes through or ends at, and the teleport hint is noise.
				return true;
			}
			TransportType sharedType = t.getType().sharesDestinationsWith();
			if (sharedType == null)
			{
				return false; // not a shared-destination teleport, keep it
			}
			// Suppress if a local transport of the shared type is present on this edge (Issue 1),
			// or if the edge is within the shared type's radius threshold, meaning the path is
			// walking to the landing site rather than teleporting there (Issue 2).
			return localTypes.contains(sharedType)
				|| (sharedType.getRadiusThreshold() != null && edgeDistance <= sharedType.getRadiusThreshold());
		});
		return stepTransports;
	}

	public PathStep nextPathStep(List<PathStep> path, int index)
	{
		if (path == null || index < 0 || index + 1 >= path.size())
		{
			return null;
		}
		return path.get(index + 1);
	}

	public String formatTransportDisplay(Transport transport)
	{
		String info = transport.getDisplayInfo();
		if (info == null || info.isEmpty())
		{
			return info;
		}
		if (TransportType.TELEPORTATION_PORTAL_POH.equals(transport.getType()))
		{
			return pohService == null ? info : pohService.apply(info);
		}
		return info;
	}

	/**
	 * Checks if the destination is inside POH and looks ahead in the path to find the exit transport.
	 * If the immediate exit leads to a fairy ring or other notable transport shortly after,
	 * that information is included instead.
	 *
	 * @param destination  The destination point to check
	 * @param path         The full path
	 * @param currentIndex The current index in the path. The overlay passes
	 *                     {@code pathIndex - 1} so the scan starts at the
	 *                     current edge; {@code -1} therefore means "scan
	 *                     from the first path edge", which is where a
	 *                     first-edge exit (e.g. a global teleport out of
	 *                     the house) is found.
	 * @return The display info of the POH exit transport, or null if not applicable
	 */
	public String getPohExitInfo(int destination, List<PathStep> path, int currentIndex)
	{
		if (path == null || currentIndex < -1)
		{
			return null;
		}

		int destX = WorldPointUtil.unpackWorldX(destination);
		int destY = WorldPointUtil.unpackWorldY(destination);

		// Check if destination is inside POH
		if (!PohService.isInsidePoh(destX, destY))
		{
			return null;
		}

		String immediateExitInfo = null;

		// Look ahead in the path to find the next transport that exits POH
		for (int i = currentIndex + 1; i < path.size() - 1; i++)
		{
			int stepLocation = path.get(i).getPackedPosition();
			int nextLocation = path.get(i + 1).getPackedPosition();

			int stepX = WorldPointUtil.unpackWorldX(stepLocation);
			int stepY = WorldPointUtil.unpackWorldY(stepLocation);
			int nextX = WorldPointUtil.unpackWorldX(nextLocation);
			int nextY = WorldPointUtil.unpackWorldY(nextLocation);

			// Check if this step is inside POH but next step is outside (exit transport)
			boolean stepInsidePoh = PohService.isInsidePoh(stepX, stepY);
			boolean nextInsidePoh = PohService.isInsidePoh(nextX, nextY);

			if (stepInsidePoh && !nextInsidePoh)
			{
				// Found the exit transport - get its display info using bank-aware lookup
				PathStep currentStep = path.get(i);
				PathStep nextStep = path.get(i + 1);
				for (Transport transport : transportsForEdge(currentStep, nextStep))
				{
					String exitInfo = formatTransportDisplay(transport);
					if (exitInfo != null && !exitInfo.isEmpty())
					{
						TransportType exitType = transport.getType();
						if (TransportType.TELEPORTATION_BOX.equals(exitType))
						{
							String objInfo = transport.getObjectInfo();
							String label = OBJINFO_FALLBACK_LABEL;
							if (objInfo != null)
							{
								for (List<String> pair : OBJINFO_LABELS)
								{
									if (objInfo.contains(pair.get(0)))
									{
										label = pair.get(1);
										break;
									}
								}
							}
							immediateExitInfo = label + exitInfo;
						}
						else
						{
							String prefix = exitType == null ? null : EXIT_PREFIX.get(exitType);
							immediateExitInfo = prefix == null ? exitInfo : prefix + exitInfo;
						}
					}
					break;
				}
				break;
			}

			// If we've left POH without finding a transport, stop looking
			if (!stepInsidePoh)
			{
				break;
			}
		}

		return immediateExitInfo;
	}

	public CollisionMap getMap()
	{
		return pathfinderConfig == null ? null : pathfinderConfig.getMap();
	}

	/**
	 * WARNING: This is a legacy wrapper for coarse display-oriented callers only.
	 * <p>
	 * It collapses banked/unbanked transport availability into a single view via
	 * PathfinderConfig.getTransports(), which is not valid for path-state-sensitive logic.
	 * <p>
	 * Do not use this for reasoning about which transports are available at a specific
	 * step of a path. Use PathfinderConfig.getTransportAvailability(BankVisitState) and the
	 * path's PathStep state instead.
	 */
	public PrimitiveIntHashMap<Transport[]> getTransports()
	{
		return pathfinderConfig == null ? null : pathfinderConfig.getTransports();
	}

	/**
	 * Every loaded transport grouped by origin for display, including transports the
	 * player cannot currently use. Same layout as {@link #getTransports()}.
	 */
	public PrimitiveIntHashMap<Transport[]> getAllDisplayTransports()
	{
		return pathfinderConfig == null ? null : pathfinderConfig.getAllDisplayTransports();
	}

	public TransportEligibility getEligibility()
	{
		return pathfinderConfig == null ? null : pathfinderConfig.getEligibility();
	}

	/**
	 * The bank-pickup projection for the active path — owned and cached by
	 * the engine config; this facade bridges the attached config in.
	 */
	public BankPickupResult getBankPickup(List<PathStep> path, int pathIndex, ActiveSearch search)
	{
		return pathfinderConfig == null
			? null
			: BankPickupResult.format(client, pathfinderConfig.getBankPickup(path, pathIndex, search));
	}

	public Set<Integer> getDestinations(String destinationType)
	{
		return pathfinderConfig == null ? null : pathfinderConfig.getDestinations(destinationType);
	}

	public boolean hasDestination(String destinationType)
	{
		return pathfinderConfig != null && pathfinderConfig.hasDestination(destinationType);
	}

	public boolean isBankOpen()
	{
		return itemState != null && itemState.getBank() != null;
	}

	/**
	 * The widget-loaded fairy-ring arm: the log panel counts as open only
	 * while a path is displayed; the flag gates the per-tick scroll.
	 */
	public void widgetLoaded(int groupId, ActiveSearch pathfinder)
	{
		if (pathfinder != null && groupId == InterfaceID.FAIRYRINGS_LOG)
		{
			fairyRingPanelOpen = true;
		}
	}

	/**
	 * The widget-closed fairy-ring arm: the log panel no longer shows.
	 */
	public void widgetClosed(int groupId)
	{
		if (groupId == InterfaceID.FAIRYRINGS_LOG)
		{
			fairyRingPanelOpen = false;
		}
	}

	/**
	 * The post-client-tick fairy-ring arm: while the panel is open and a
	 * path is displayed, scroll it to the ring code the path uses.
	 */
	public void postClientTick(ActiveSearch pathfinder)
	{
		if (fairyRingPanelOpen && pathfinder != null)
		{
			scrollFairyRingPanel(pathfinder);
		}
	}

	private void scrollFairyRingPanel(ActiveSearch pathfinder)
	{
		List<PathStep> path;

		if (client == null || pathfinder == null
			|| (path = pathfinder.getPath()) == null)
		{
			return;
		}

		String fairyRingCode = null;

		for (int i = 1; i < path.size(); i++)
		{
			PathStep currentStep = path.get(i - 1);
			PathStep nextStep = path.get(i);
			for (Transport transport : transportsForEdge(currentStep, nextStep))
			{
				if (TransportType.FAIRY_RING.equals(transport.getType()))
				{
					fairyRingCode = transport.getDisplayInfo();
				}
			}
		}
		if (fairyRingCode == null)
		{
			return;
		}

		Widget codeWidget = null;

		Widget favesPanel = client.getWidget(InterfaceID.FairyringsLog.FAVES);
		if (favesPanel != null)
		{
			for (Widget widget : favesPanel.getStaticChildren())
			{
				if (widget != null)
				{
					String widgetText = widget.getText();
					if ((fairyRingCode.equals(widgetText)
						|| ("(Shortest Path) " + fairyRingCode).equals(widgetText)))
					{
						codeWidget = widget;
						break;
					}
				}
			}
		}

		Widget contentsList = client.getWidget(InterfaceID.FairyringsLog.CONTENTS);
		if (contentsList != null && codeWidget == null)
		{
			for (Widget widget : contentsList.getDynamicChildren())
			{
				if (widget != null)
				{
					String widgetText = widget.getText();
					if ((fairyRingCode.equals(widgetText)
						|| ("(Shortest Path) " + fairyRingCode).equals(widgetText)))
					{
						codeWidget = widget;
						break;
					}
				}
			}
		}

		if (codeWidget == null)
		{
			return;
		}

		codeWidget.setTextColor(0x00FF00);
		String codeWidgetText = codeWidget.getText();
		if (codeWidgetText != null && !codeWidgetText.contains("(Shortest Path)"))
		{
			codeWidget.setText("(Shortest Path) " + codeWidgetText);
		}

		if (contentsList == null)
		{
			return;
		}

		int panelScrollY = Math.min(
			codeWidget.getRelativeY(),
			contentsList.getScrollHeight() - contentsList.getHeight()
		);

		contentsList.setScrollY(panelScrollY);
		contentsList.revalidateScroll();

		client.runScript(
			ScriptID.UPDATE_SCROLLBAR,
			InterfaceID.FairyringsLog.SCROLLBAR,
			InterfaceID.FairyringsLog.CONTENTS,
			panelScrollY
		);
	}
}

package shortestpath.requirement;

import java.util.*;
import net.runelite.api.*;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.DBTableID;
import shortestpath.requirement.model.*;
import net.runelite.api.widgets.WidgetModalMode;
import shortestpath.items.OwnedItems;
import lombok.AllArgsConstructor;
import lombok.extern.slf4j.Slf4j;

/**
 * The {@link Client}-backed {@link PlayerStateSource} and the only client
 * reader on the requirement capture path. Every getter checks
 * {@link #checkOnClientThread()} first, so an off-thread capture read throws
 * {@link IllegalStateException} instead of racing the client — the refresh
 * path used to no-op silently in that situation, which made a missed caller
 * indistinguishable from a correct one. {@link #isOnClientThread()} is the
 * same comparison without the throw, for the eligibility envelope's
 * stale-snapshot contract.
 */
@AllArgsConstructor
@Slf4j
public final class ClientPlayerStateSource implements PlayerStateSource
{
	// [proc,get_music_varp](int)(int): takes a one-based MUSICMULTI index, returns that varp's current value.
	public static final int GET_MUSIC_VARP = 7305;

	private final Client client;


	@Override
	public GameState gameState()
	{
		checkOnClientThread();
		return client.getGameState();
	}

	@Override
	public int varbit(int varbitId)
	{
		checkOnClientThread();
		return client.getVarbitValue(varbitId);
	}

	@Override
	public int varp(int varpId)
	{
		checkOnClientThread();
		return client.getVarpValue(varpId);
	}

	@Override
	public int boostedSkillLevel(Skill skill)
	{
		checkOnClientThread();
		return client.getBoostedSkillLevel(skill);
	}

	@Override
	public int realSkillLevel(Skill skill)
	{
		checkOnClientThread();
		return client.getRealSkillLevel(skill);
	}

	@Override
	public int totalLevel()
	{
		checkOnClientThread();
		return client.getTotalLevel();
	}

	@Override
	public QuestState questState(Quest quest)
	{
		checkOnClientThread();
		return quest.getState(client);
	}

	@Override
	public MusicTracks musicTracks()
	{
		checkOnClientThread();
		int unlocked = 0;
		int required = 0;
		List<String> lockedTracks = new ArrayList<>();
		Map<Integer, Integer> varpValues = new HashMap<>();
		for (int row : client.getDBTableRows(DBTableID.Music.ID))
		{
			// Holiday is an event ID; -1 means the track is not tied to a holiday.
			if ((Integer) client.getDBTableField(row, DBTableID.Music.COL_RELEASE_TYPE, 0)[0] == 0 ||
				(Integer) client.getDBTableField(row, DBTableID.Music.COL_HIDDEN, 0)[0] != 0 ||
				(Integer) client.getDBTableField(row, DBTableID.Music.COL_HOLIDAY, 0)[0] != -1)
			{
				continue;
			}
			required++;
			if ((Integer) client.getDBTableField(row, DBTableID.Music.COL_AUTOMATIC_UNLOCK, 0)[0] != 0)
			{
				unlocked++;
				continue;
			}
			// One-based MUSICMULTI index, passed to get_music_varp
			int varpIndex = (Integer) client.getDBTableField(row, DBTableID.Music.COL_VARIABLE, 0)[0];
			int bit = (Integer) client.getDBTableField(row, DBTableID.Music.COL_VARIABLE, 1)[0];
			boolean isUnlocked = false;
			if (varpIndex >= 1 && bit >= 0 && bit < Integer.SIZE)
			{
				Integer varpValue = varpValues.get(varpIndex);
				if (varpValue == null)
				{
					client.runScript(GET_MUSIC_VARP, varpIndex);
					varpValue = client.getIntStack()[0];
					varpValues.put(varpIndex, varpValue);
				}
				isUnlocked = (varpValue & (1 << bit)) != 0;
			}
			if (isUnlocked)
			{
				unlocked++;
			}
			else if (log.isDebugEnabled())
			{
				Object[] name = client.getDBTableField(row, DBTableID.Music.COL_DISPLAYNAME, 0);
				lockedTracks.add(name.length > 0 ? String.valueOf(name[0]) : "row " + row);
			}
		}
		log.debug("Music cape: {} required tracks locked ({} unlocked / {} required): {}",
			required - unlocked, unlocked, required, lockedTracks);
		if (required == 0)
		{
			log.debug("Music cape: no required track data available; teleport remains unavailable");
			required = SkillLevels.MAX_LEVEL;
		}
		return new MusicTracks(unlocked, required);
	}

	@Override
	public int maximumQuestPoints()
	{
		checkOnClientThread();
		return client.getDBTableRows(DBTableID.Quest.ID).stream()
			.filter(row -> (Integer) client.getDBTableField(
				row,
				DBTableID.Quest.COL_RELEASE_TYPE,
				0
			)[0] != 0)
			.mapToInt(row -> (Integer) client.getDBTableField(
				row,
				DBTableID.Quest.COL_QUESTPOINTS_OVERRIDE,
				0
			)[0])
			.sum();
	}

	@Override
	public WorldPoint localPlayerWorldLocation()
	{
		checkOnClientThread();
		Player localPlayer = client.getLocalPlayer();
		return localPlayer == null ? null : localPlayer.getWorldLocation();
	}

	@Override
	public boolean modalWidgetOpen()
	{
		checkOnClientThread();
		return modalWidgetOpen(client);
	}

	/**
	 * Whether a modal widget is currently open. Varbit updates are not
	 * transmitted while one is, so {@code FARMING_TRANSMIT_*} reads return
	 * whatever was last received — which can be the value of the other patch
	 * sharing the region-scoped slot. Callers must skip sampling while this
	 * returns true rather than record a cross-contaminated value.
	 * (Same guard as FarmingTracker.updateData.)
	 */
	public static boolean modalWidgetOpen(Client client)
	{
		HashTable<WidgetNode> componentTable = client.getComponentTable();
		if (componentTable == null)
		{
			return false;
		}
		for (WidgetNode widgetNode : componentTable)
		{
			if (widgetNode.getModalMode() != WidgetModalMode.NON_MODAL)
			{
				return true;
			}
		}
		return false;
	}

	@Override
	public ItemContainer itemContainer(int inventoryId)
	{
		checkOnClientThread();
		return client.getItemContainer(inventoryId);
	}

	@Override
	public Map<Integer, Integer> runePouchContents()
	{
		checkOnClientThread();
		return OwnedItems.runePouchContents(client);
	}

	@Override
	public void addRunePouchContents(Map<Integer, Integer> owned)
	{
		checkOnClientThread();
		OwnedItems.addRunePouchContents(client, owned);
	}

	@Override
	public EnumSet<WorldType> worldType()
	{
		checkOnClientThread();
		return client.getWorldType();
	}

	@Override
	public void checkOnClientThread()
	{
		if (!isOnClientThread())
		{
			throw new IllegalStateException(
				"Player-state reads must run on the client thread; route the caller through the client thread");
		}
	}

	@Override
	public boolean isOnClientThread()
	{
		return Thread.currentThread().equals(client.getClientThread());
	}
}

package shortestpath.requirement;

import java.util.*;
import net.runelite.api.*;
import net.runelite.api.coords.WorldPoint;
import shortestpath.requirement.model.MusicTracks;

/**
 * The player-state reads the requirement capture path performs, exposed
 * behind an interface so capture runs against an injectable source rather
 * than the {@code Client} directly. Every read corresponds 1:1 to a call the
 * refresh path used to make on the client: login state, varbits and
 * varplayers, boosted and real skill levels, total and combat level, quest
 * state, the quest-points database maximum, the local player's world
 * location, modal-widget state, inventory/worn item containers, rune-pouch
 * contents and the league world type.
 *
 * <p>Thread contract: capture reads are only valid on the client thread.
 * Every state getter is expected to call {@link #checkOnClientThread()}
 * first and throw {@link IllegalStateException} off the client thread — an
 * off-thread capture previously raced the client and silently skipped the
 * refresh, so it now fails loudly instead. {@link #isOnClientThread()} is
 * the non-throwing predicate for callers that may legitimately run off the
 * client thread and need a stale-read envelope instead of a crash.
 *
 * <p>The sole production implementation is {@link ClientPlayerStateSource};
 * tests may supply map-backed fakes that answer from fixed values and treat
 * the thread checks as satisfied.
 */
public interface PlayerStateSource
{
	/**
	 * The client's login state; capture gates on {@link GameState#LOGGED_IN}.
	 */
	GameState gameState();

	/**
	 * The current value of one varbit.
	 */
	int varbit(int varbitId);

	/**
	 * The current value of one varplayer.
	 */
	int varp(int varpId);

	/**
	 * The boosted (effective) level of one skill.
	 */
	int boostedSkillLevel(Skill skill);

	/**
	 * The real (unboosted) level of one skill.
	 */
	int realSkillLevel(Skill skill);

	/**
	 * The player's total level.
	 */
	int totalLevel();

	/**
	 * The player's combat level, derived from the real skill levels through
	 * the shared {@link #computeCombatLevel} formula so every source computes
	 * it identically.
	 */
	default int combatLevel()
	{
		return computeCombatLevel(
			realSkillLevel(Skill.ATTACK),
			realSkillLevel(Skill.STRENGTH),
			realSkillLevel(Skill.DEFENCE),
			realSkillLevel(Skill.HITPOINTS),
			realSkillLevel(Skill.MAGIC),
			realSkillLevel(Skill.RANGED),
			realSkillLevel(Skill.PRAYER));
	}

	/**
	 * The state of one quest as the source reports it.
	 */
	QuestState questState(Quest quest);

	/**
	 * The maximum attainable quest points, summed over the released quest
	 * rows of the quest-points database table.
	 */
	int maximumQuestPoints();

	/** The player's unlocked and required non-holiday music track counts. */
	MusicTracks musicTracks();

	/**
	 * The local player's world location, or {@code null} when the player or
	 * its location is unavailable. Feeds in-region spirit-tree sampling.
	 */
	WorldPoint localPlayerWorldLocation();

	/**
	 * Whether a modal widget is open; varbits are not transmitted while one
	 * is, so live patch sampling must be skipped.
	 */
	boolean modalWidgetOpen();

	/**
	 * One item container by inventory id (inventory/worn).
	 */
	ItemContainer itemContainer(int inventoryId);

	/**
	 * The runes inside the rune pouch as rune id to amount, read from the
	 * pouch varbits (current wherever the pouch is, including the bank).
	 */
	Map<Integer, Integer> runePouchContents();

	/**
	 * Adds the runes in the rune pouch to {@code owned} when it already holds
	 * a rune pouch.
	 */
	void addRunePouchContents(Map<Integer, Integer> owned);

	/**
	 * The world types of the world the player is on (seasonal/deadman league
	 * detection).
	 */
	EnumSet<WorldType> worldType();

	/**
	 * Throws {@link IllegalStateException} when the calling thread is not the
	 * client thread. Every state getter calls this first, so an off-thread
	 * capture fails loudly instead of racing the client.
	 */
	void checkOnClientThread();

	/**
	 * Whether the calling thread is the client thread. Non-throwing: the
	 * eligibility envelope uses it to return a stale snapshot off-thread
	 * rather than fail.
	 */
	boolean isOnClientThread();

	/**
	 * Pure combat-level formula, shared by every source implementation.
	 */
	static int computeCombatLevel(int attack, int strength, int defence, int hitpoints, int magic, int ranged, int prayer)
	{
		// Integer division is intentional here — it matches the OSRS floor(x/2) steps in the formula.
		double base = 0.25 * (defence + hitpoints + Math.floorDiv(prayer, 2));
		double melee = (13 * (attack + strength)) / 40.0;
		double range = (13 * (3 * Math.floorDiv(ranged, 2))) / 40.0;
		double mage = (13 * (3 * Math.floorDiv(magic, 2))) / 40.0;
		return (int) Math.floor(base + Math.max(Math.max(melee, range), Math.max(melee, mage)));
	}
}

package shortestpath.requirement;

import java.util.*;
import lombok.Getter;
import net.runelite.api.*;
import net.runelite.api.gameval.*;
import shortestpath.leagues.*;
import shortestpath.requirement.model.*;
import shortestpath.transport.Transport;

/**
 * Immutable snapshot of every fact the requirement checks need about the player,
 * captured once per refresh on the client thread. What goes in here is state the
 * game or config asserts about the player: boosted skill levels (with total,
 * combat and quest points in the trailing indices, the same layout
 * {@code PathfinderConfig} fills), quest states, varbit and varplayer values, the
 * owned-item pools inside {@link TransportEligibility} (carried, bank-path, bank,
 * banked rune pouch and the fairy-ring staff rule), declared unlocks, the
 * respawn declaration, sailing-boat state, a frozen league-mode snapshot and
 * the planted spirit trees observed so far.
 *
 * <p>User routing policy stays out of the snapshot and is applied by the
 * settings filter instead: transport-type enablement, POH toggles, the
 * teleportation-item mode and the currency threshold. The blocked-item
 * restrictions are policy too — they say which items the user refuses to
 * route through, not what the player owns — so they never enter the snapshot.
 *
 * <p>{@link #capture} is the single entry point: it reads the player only
 * through a {@link PlayerStateSource} (whose getters throw off the client
 * thread) and quest states only through the {@link RequirementHooks} seam so
 * test overrides keep feeding the snapshot. Called from
 * {@code PathfinderConfig.refreshTransports} after
 * {@code refreshSpiritTreeAvailability()} has settled the planted-tree set, so
 * the whole refresh shares one consistent view of the player.
 */
public final class RequirementContext
{
	@Getter
	private final long evaluationTimeMinutes;
	@Getter private final SkillLevels boostedSkillLevelsAndMore;
	@Getter
	private final int currentMaxQuestPoints;
	@Getter
	private final int currentMaxMusicTracks;
	@Getter
	private final Map<Quest, QuestState> questStates;
	@Getter
	private final Map<Integer, Integer> varbitValues;
	@Getter
	private final Map<Integer, Integer> varPlayerValues;
	@Getter
	private final TransportEligibility eligibility;
	@Getter
	private final Set<Unlock> unlocks;
	@Getter
	private final boolean respawnPrifddinas;
	@Getter
	private final boolean isOnSailingBoat;
	/**
	 * The league facts frozen at capture time. Retaining a
	 * {@link LeagueModeSnapshot} rather than the live {@link LeagueModeState}
	 * keeps this context from tracking a later refresh's in-place writes.
	 */
	@Getter
	private final LeagueModeSnapshot leagueModeSnapshot;
	@Getter
	private final Set<String> availableSpiritTrees;

	public RequirementContext(
		long evaluationTimeMinutes,
		int[] boostedSkillLevelsAndMore,
		int currentMaxQuestPoints,
		int currentMaxMusicTracks,
		Map<Quest, QuestState> questStates,
		Map<Integer, Integer> varbitValues,
		Map<Integer, Integer> varPlayerValues,
		TransportEligibility eligibility,
		Set<Unlock> unlocks,
		boolean respawnPrifddinas,
		boolean isOnSailingBoat,
		LeagueModeState leagueModeState,
		Set<String> availableSpiritTrees)
	{
		this.evaluationTimeMinutes = evaluationTimeMinutes;
		this.boostedSkillLevelsAndMore = SkillLevels.of(boostedSkillLevelsAndMore);
		this.currentMaxQuestPoints = currentMaxQuestPoints;
		this.currentMaxMusicTracks = currentMaxMusicTracks;
		this.questStates = Map.copyOf(questStates);
		this.varbitValues = Map.copyOf(varbitValues);
		this.varPlayerValues = Map.copyOf(varPlayerValues);
		this.eligibility = eligibility;
		this.unlocks = Set.copyOf(unlocks);
		this.respawnPrifddinas = respawnPrifddinas;
		this.isOnSailingBoat = isOnSailingBoat;
		this.leagueModeSnapshot = leagueModeState == null
			? LeagueModeSnapshot.NON_SEASONAL
			: leagueModeState.snapshot();
		this.availableSpiritTrees = availableSpiritTrees == null
			? null
			: Set.copyOf(availableSpiritTrees);
	}

	/**
	 * Captures the immutable snapshot the requirement checks read this
	 * refresh. All player-state reads go through {@code source} (loud off the
	 * client thread) and quest states go through {@code hooks} so the
	 * protected override seam keeps feeding the snapshot. Declared var and
	 * quest ids from both the transports and the bank requirements land in
	 * the same maps — a var or quest missing from them fails closed when the
	 * shared evaluator looks it up. {@code balloonLogBasketDestinations}
	 * forwards the packed destinations of the balloon routes whose log basket
	 * the player declared stocked into the eligibility snapshot.
	 */
	public static RequirementContext capture(
		PlayerStateSource source,
		RequirementHooks hooks,
		RoutingPolicy policy,
		long evaluationTimeMinutes,
		Collection<Transport> transports,
		Map<Integer, DestinationRequirements> bankRequirements,
		ItemContainer bank,
		Set<Unlock> unlocks,
		boolean respawnPrifddinas,
		LeagueModeState leagueModeState,
		Set<String> availableSpiritTrees,
		Set<Integer> balloonLogBasketDestinations)
	{
		int[] boostedSkillLevelsAndMore = new int[SkillLevels.LENGTH];
		boolean onSailingBoat = source.varbit(VarbitID.SAILING_BOARDED_BOAT) != 0;
		int i = 0;
		for (; i < Skill.values().length; i++)
		{
			boostedSkillLevelsAndMore[i] = source.boostedSkillLevel(Skill.values()[i]);
		}
		// The Herblore transport requirement (Mastering Mixology) checks the base level.
		boostedSkillLevelsAndMore[Skill.HERBLORE.ordinal()] = source.realSkillLevel(Skill.HERBLORE);
		boostedSkillLevelsAndMore[i++] = source.totalLevel(); // skill total level
		boostedSkillLevelsAndMore[i++] = source.combatLevel(); // combat level
		boostedSkillLevelsAndMore[i++] = source.varp(VarPlayerID.QP); // quest points

		int currentMaxQuestPoints = source.maximumQuestPoints();
		MusicTracks music = source.musicTracks();
		boostedSkillLevelsAndMore[i] = music.getUnlocked();

		TransportEligibility eligibilitySnapshot = TransportEligibility.collect(source, bank,
			policy.teleportationItemSetting(), policy.currencyThreshold(), policy.includeBankPath(),
			unlocks, balloonLogBasketDestinations);

		Map<Quest, QuestState> capturedQuestStates = new HashMap<>();
		Map<Integer, Integer> capturedVarbitValues = new HashMap<>();
		Map<Integer, Integer> capturedVarPlayerValues = new HashMap<>();
		Set<Quest> refreshedQuests = new HashSet<>();
		for (Transport transport : transports)
		{
			captureQuestStates(hooks, transport.getQuests(), refreshedQuests, capturedQuestStates);
			for (VarRequirement varRequirement : transport.getVarRequirements())
			{
				if (varRequirement.isVarbit())
				{
					capturedVarbitValues.put(varRequirement.getId(), source.varbit(varRequirement.getId()));
				}
				else
				{
					capturedVarPlayerValues.put(varRequirement.getId(), source.varp(varRequirement.getId()));
				}
			}
		}

		// Bank destinations can carry quest and var ids that no transport
		// declares; they must land in the same snapshot, because a var or
		// quest missing from these maps fails closed when the shared
		// evaluator looks it up.
		for (DestinationRequirements destinationRequirements : bankRequirements.values())
		{
			captureQuestStates(hooks, destinationRequirements.getQuests(), refreshedQuests, capturedQuestStates);
			for (VarRequirement varRequirement : destinationRequirements.getVarbits())
			{
				capturedVarbitValues.put(varRequirement.getId(), source.varbit(varRequirement.getId()));
			}
			for (VarRequirement varRequirement : destinationRequirements.getVarPlayers())
			{
				capturedVarPlayerValues.put(varRequirement.getId(), source.varp(varRequirement.getId()));
			}
		}

		return new RequirementContext(evaluationTimeMinutes, boostedSkillLevelsAndMore,
			currentMaxQuestPoints, music.getRequired(), capturedQuestStates, capturedVarbitValues, capturedVarPlayerValues,
			eligibilitySnapshot, unlocks, respawnPrifddinas, onSailingBoat,
			leagueModeState, availableSpiritTrees);
	}

	/**
	 * Captures each quest's state through the {@code hooks} seam, skipping
	 * quests already captured this refresh and tolerating a hook that
	 * returns null or throws {@link NullPointerException} for a quest it
	 * cannot answer. Any other exception propagates — an unexpected hook
	 * failure should fail the refresh loudly, not silently drop the quest.
	 */
	private static void captureQuestStates(RequirementHooks hooks, Collection<Quest> quests,
		Set<Quest> refreshedQuests, Map<Quest, QuestState> capturedQuestStates)
	{
		for (Quest quest : quests)
		{
			if (!refreshedQuests.add(quest))
			{
				continue;
			}
			try
			{
				QuestState state = hooks.getQuestState(quest);
				if (state != null)
				{
					capturedQuestStates.put(quest, state);
				}
			}
			catch (NullPointerException ignored)
			{
			}
		}
	}

}

package shortestpath.requirement;

import java.util.*;
import net.runelite.api.*;
import shortestpath.requirement.model.VarRequirement;

/**
 * The overridable seams the requirement gate chain reads through. The chain
 * never consults {@code PathfinderConfig} or the client directly; instead it
 * calls these hooks for every check a test or the dashboard harness may
 * bypass. {@code PathfinderConfig} supplies the implementation through a
 * private adapter that dispatches {@link #varChecks} on the
 * {@link VarRequirement.VarType} kind to its own keyed
 * {@code varbitChecks}/{@code varPlayerChecks} methods, so overrides such as
 * {@code TestPathfinderConfig}'s bypass flags keep changing transport and
 * bank-destination verdicts after the extraction.
 *
 * <p>Failure polarity contract: {@code varChecks} returns {@code true} when
 * a check FAILED — the same polarity the {@code PathfinderConfig} methods
 * and every existing override use. Do not invert it.
 */
public interface RequirementHooks
{
	/**
	 * The state of one quest as the hook sees it this refresh.
	 */
	QuestState getQuestState(Quest quest);

	/**
	 * Whether any requirement of the given {@link VarRequirement.VarType}
	 * kind in the collection fails against the supplied values — the map the
	 * calling chain captured into its context, so a stale chain always
	 * evaluates its own refresh's snapshot rather than whatever a newer
	 * refresh wrote. Only requirements whose
	 * {@link VarRequirement#getVarType()} equals {@code kind} are evaluated;
	 * the other var family is invisible to the call. Returns {@code true}
	 * when a check FAILED.
	 */
	boolean varChecks(Collection<VarRequirement> requirements,
		Map<Integer, Integer> values, long evaluationTimeMinutes,
		VarRequirement.VarType kind);
}

package shortestpath.requirement;

import java.util.*;

import net.runelite.api.*;
import net.runelite.api.gameval.ItemID;

import shortestpath.WorldPointUtil;
import shortestpath.leagues.*;
import shortestpath.pathfinder.BankVisitState;
import shortestpath.poh.PohService;
import shortestpath.requirement.model.*;
import shortestpath.transport.*;

/**
 * The ordered gate chain deciding which transports can run this refresh.
 * Each named gate answers one rejection question and returns its
 * {@link RejectionReason}; {@link #check} evaluates them in the fixed order
 * below and returns the first non-{@code NONE} verdict, so the chain is the
 * single definition of transport admissibility. A transport passing every
 * gate is offered to the eligibility pools.
 *
 * <p>Boundary rule: facts the game or the config declares about the player —
 * skill levels, quest states, var values, owned items, declared unlocks,
 * respawn, sailing and league state, planted spirit trees — are read from
 * the {@link RequirementContext} snapshot captured once per refresh. Routing
 * policy — transport-type enablement, POH toggles, the teleportation-item
 * mode, jewellery-box tier and mounted items — is read from the immutable
 * {@link RoutingPolicy} snapshot taken at the same moment. Gates reach the
 * overridable quest/var seams through {@link RequirementHooks} and never
 * consult {@code PathfinderConfig} or the {@code Client} directly; client
 * state is only read while the context snapshot is built.
 *
 * <p>One instance is created per refresh, bound to that refresh's context
 * and policy, so a verdict can never mix facts from different refreshes.
 */
public final class Requirements
{
	/**
	 * Item ids that only exist on Deadman Mode worlds ({@code WorldType.DEADMAN}).
	 * Transports requiring them are filtered out on every other world type,
	 * regardless of the teleportation-item setting.
	 */
	private static final Set<Integer> DEADMAN_ONLY_ITEM_IDS = Set.of(
		ItemID.MAGIC_ROCK_OF_FAIRIES);

	/**
	 * Respawn landing tiles used by the Respawn Teleport spell and the POH respawn portal.
	 * Every respawn except Prifddinas exposes an {@code *_SPAWN} varbit; when Prifddinas is
	 * the active respawn all of them read 0, which is the same signature as the Lumbridge
	 * default, so both landings are gated on the declared respawn in config instead.
	 */
	private static final int LUMBRIDGE_RESPAWN = WorldPointUtil.packWorldPoint(3221, 3218, 0);
	private static final int PRIFDDINAS_RESPAWN = WorldPointUtil.packWorldPoint(3265, 6077, 0);

	private final RequirementContext context;
	private final RoutingPolicy policy;
	private final RequirementHooks hooks;
	// The per-refresh instance pins the snapshot's skill levels once; the
	// immutable value needs no defensive copy per transport.
	private final SkillLevels boostedSkillLevelsAndMore;

	public Requirements(RequirementContext context, RoutingPolicy policy, RequirementHooks hooks)
	{
		this.context = context;
		this.policy = policy;
		this.hooks = hooks;
		this.boostedSkillLevelsAndMore = context.getBoostedSkillLevelsAndMore();
	}

	/**
	 * Whether the transport may run this refresh — {@code true} when every
	 * gate passed ({@link RejectionReason#NONE}). The boolean adapter lets
	 * callers outside this package consume the verdict without naming the
	 * enum.
	 */
	public boolean usable(Transport transport)
	{
		return check(transport) == RejectionReason.NONE;
	}

	/**
	 * Whether the bank-destination requirement set is satisfied by this
	 * refresh's snapshot — the bank-side counterpart of {@link #usable}.
	 */
	public boolean satisfied(DestinationRequirements requirements)
	{
		return check(requirements) == RejectionReason.NONE;
	}

	/**
	 * Evaluates the gates in their fixed order and returns the first
	 * rejection, or {@link RejectionReason#NONE} when every gate passes.
	 * The order is part of the contract — later gates assume the earlier
	 * ones passed. The composite is two halves: {@link #gates} runs the
	 * named requirement gates, then {@link #itemRequirement} consults the
	 * eligibility snapshot's item pools last.
	 */
	RejectionReason check(Transport transport)
	{
		RejectionReason reason = gates(transport);
		if (reason == RejectionReason.NONE) reason = itemRequirement(transport);
		return reason;
	}

	/**
	 * The named requirement gates — every gate before the item-pool
	 * evaluation — in the same fixed order {@link #check} applies.
	 * {@code refreshTransports} calls this directly (it lives in another
	 * package, hence {@code public}) so the two item pools can each be
	 * evaluated once by the loop itself; a non-{@code NONE} verdict skips
	 * the transport before any pool is consulted.
	 */
	public RejectionReason gates(Transport transport)
	{
		RejectionReason reason = sailing(transport);
		if (reason == RejectionReason.NONE) reason = pohDisabled(transport);
		if (reason == RejectionReason.NONE) reason = leagueRegion(transport);
		if (reason == RejectionReason.NONE) reason = typeDisabled(transport);
		if (reason == RejectionReason.NONE) reason = pohVariant(transport);
		if (reason == RejectionReason.NONE) reason = teleportationItem(transport);
		if (reason == RejectionReason.NONE) reason = respawn(transport);
		if (reason == RejectionReason.NONE) reason = unlockGate(transport);
		if (reason == RejectionReason.NONE) reason = jewelleryBoxTier(transport);
		if (reason == RejectionReason.NONE) reason = skillLevel(transport);
		if (reason == RejectionReason.NONE) reason = quest(transport);
		if (reason == RejectionReason.NONE) reason = varbit(transport);
		if (reason == RejectionReason.NONE) reason = varplayer(transport);
		if (reason == RejectionReason.NONE) reason = plantedSpiritTree(transport);
		return reason;
	}

	/**
	 * Bank-destination admissibility: a {@link DestinationRequirements} is
	 * satisfied when its skill, quest, varbit and varplayer sets pass the
	 * same checks the transport gates above run. An empty requirement is
	 * always satisfied.
	 *
	 * <p>Bank evaluation intentionally reads this refresh's captured
	 * context values and routes through the shared overridable hooks
	 * ({@link RequirementHooks#varChecks} dispatched per var kind,
	 * the quest map the {@link RequirementHooks#getQuestState} hook feeds)
	 * instead of querying the client per tile as it used to. A bank tile and
	 * a transport can therefore never disagree about the same requirement
	 * inside one refresh, and test bypasses cover bank requirements too.
	 */
	RejectionReason check(DestinationRequirements requirements)
	{
		if (requirements == null || requirements.isEmpty())
		{
			return RejectionReason.NONE;
		}
		RejectionReason reason = skillLevel(requirements.getSkillLevels());
		if (reason == RejectionReason.NONE && !completedQuests(requirements.getQuests()))
		{
			reason = RejectionReason.QUEST;
		}
		if (reason == RejectionReason.NONE
			&& hooks.varChecks(requirements.getVarbits(), context.getVarbitValues(),
				context.getEvaluationTimeMinutes(), VarRequirement.VarType.VARBIT))
		{
			reason = RejectionReason.VARBIT;
		}
		if (reason == RejectionReason.NONE
			&& hooks.varChecks(requirements.getVarPlayers(), context.getVarPlayerValues(),
				context.getEvaluationTimeMinutes(), VarRequirement.VarType.VARPLAYER))
		{
			reason = RejectionReason.VARPLAYER;
		}
		return reason;
	}

	// Sailing: suppress teleports while the player is aboard a boat.
	// We don't model sailing navigation, so teleporting away mid-ocean would produce
	// confusing suggestions. Pathfinding resumes normally after disembarking.
	private RejectionReason sailing(Transport transport)
	{
		if (context.isOnSailingBoat() && transport.getType().isTeleport())
		{
			return RejectionReason.SAILING;
		}
		return RejectionReason.NONE;
	}

	// Master POH gate - if POH is disabled, reject all POH transports
	private RejectionReason pohDisabled(Transport transport)
	{
		if (!policy.usePoh())
		{
			int[] endpoints = unpackEndpoints(transport);
			if (PohService.isInsidePoh(endpoints[0], endpoints[1])
				|| PohService.isInsidePoh(endpoints[2], endpoints[3]))
			{
				return RejectionReason.POH_DISABLED;
			}
		}
		return RejectionReason.NONE;
	}

	// League region gate: in seasonal mode, drop transports that touch the
	// always-blocked region or a region the player has not unlocked.
	private RejectionReason leagueRegion(Transport transport)
	{
		if (!isTransportRegionAllowed(transport))
		{
			return RejectionReason.LEAGUE_REGION;
		}
		return RejectionReason.NONE;
	}

	/**
	 * Whether both endpoints of the supplied transport are in unlocked
	 * regions for the current league state. Always-unlocked tiles
	 * (NEUTRAL, Varlamore, Karamja) pass through unchanged on any world.
	 *
	 * <p>If the transport declares a {@link Transport#getRegionOverride()
	 * region override}, it replaces the chunk-classifier result for the
	 * destination endpoint. Used for shortcuts whose destination chunk
	 * sits in a different region than the wiki classifies the shortcut
	 * under (e.g. Trollheim Wilderness climb — destination chunk is
	 * Wilderness, but the shortcut is wiki-listed as Asgarnia).
	 */
	private boolean isTransportRegionAllowed(Transport transport)
	{
		LeagueModeSnapshot leagueMode = context.getLeagueModeSnapshot();
		if (!leagueMode.isSeasonal())
		{
			return true;
		}
		LeagueRegion origin = LeagueRegionChecker.getRegion(transport.getOrigin());
		if (!leagueMode.isUnlocked(origin))
		{
			return false;
		}
		LeagueRegion destination = transport.getRegionOverride() != null
			? transport.getRegionOverride()
			: LeagueRegionChecker.getRegion(transport.getDestination());
		return leagueMode.isUnlocked(destination);
	}

	// Check if transport type is enabled in config
	private RejectionReason typeDisabled(Transport transport)
	{
		if (!policy.isTransportTypeEnabled(transport.getType()))
		{
			return RejectionReason.TYPE_DISABLED;
		}
		return RejectionReason.NONE;
	}

	// Handle POH variants for types that have them
	private RejectionReason pohVariant(Transport transport)
	{
		int[] endpoints = unpackEndpoints(transport);

		if (!PohService.isInsidePoh(endpoints[0], endpoints[1])
			&& !PohService.isInsidePoh(endpoints[2], endpoints[3]))
		{
			return RejectionReason.NONE; // Not a POH transport
		}

		return PohService.variantEnabled(transport, policy.usePohFairyRing(),
			policy.usePohSpiritTree(), policy.usePohObelisk(), policy.enabledPohNexusPortals())
			? RejectionReason.NONE : RejectionReason.POH_VARIANT;
	}

	// Handle special cases for teleportation items and seasonal transports
	private RejectionReason teleportationItem(Transport transport)
	{
		TransportType type = transport.getType();
		if (!TeleportRestriction.isItemTeleportType(type))
		{
			// The injected fairy-staff requirement is player-restrictable like an
			// item teleport's own items: a bare blocked id covering every
			// Dramen/Lunar staff variant disables the ring.
			if (TransportType.FAIRY_RING.equals(type)
				&& transport.getItemRequirements() != null
				&& !transport.getItemRequirements().survivesBlockedItems(policy.blockedItemIds()))
			{
				return RejectionReason.BLOCKED_ITEM;
			}
			return RejectionReason.NONE; // Not a teleportation item type
		}

		LeagueModeSnapshot leagueMode = context.getLeagueModeSnapshot();
		// Seasonal transports only exist on seasonal worlds; a lingering config
		// toggle must not leak them into normal worlds.
		if (TransportType.SEASONAL_TRANSPORTS.equals(type) && !leagueMode.isSeasonal())
		{
			return RejectionReason.SEASONAL_WORLD;
		}

		// Mode-locked items (e.g. the Deadman-only Trinket of fairies) can never
		// be obtained on other world types, even when the ALL/UNLOCKED settings
		// bypass the inventory check.
		if (!leagueMode.isDeadman() && requiresModeLockedItem(transport, DEADMAN_ONLY_ITEM_IDS))
		{
			return RejectionReason.DEADMAN_ITEM;
		}

		// Player-declared per-item restrictions drop the transport from the
		// candidate set: the modes below can bypass item evaluation entirely,
		// so the restriction gate runs here, before eligibility is consulted.
		TransportItems itemRequirements = transport.getItemRequirements();
		if (itemRequirements != null && !itemRequirements.survivesBlockedItems(policy.blockedItemIds()))
		{
			return RejectionReason.BLOCKED_ITEM;
		}

		// Destination-scoped option restrictions: a rep@dest block kills the
		// transport only when every satisfying branch resolves to the blocked
		// destination — a sibling option of the same family, a cross-family
		// branch and a non-family item all keep it routable.
		Map<Integer, Set<Integer>> blockedOptionDests = policy.blockedOptionDests();
		if (itemRequirements != null && !blockedOptionDests.isEmpty()
			&& !itemRequirements.survivesOptionBlocks(transport.getDestination(),
				TeleportRestriction.representativeIndex(), blockedOptionDests))
		{
			return RejectionReason.BLOCKED_ITEM;
		}

		// BYPASS and EVALUATE_ITEMS both pass this gate — deferral to the item
		// pools lands at the itemRequirement gate below, which re-dispatches
		// through the eligibility snapshot.
		return TeleportationItemPolicy.verdict(
			policy.teleportationItemSetting(), transport.isConsumable())
				== TeleportationItemPolicy.Verdict.REJECT
			? RejectionReason.TELEPORT_MODE
			: RejectionReason.NONE;
	}



	// Respawn rows for Prifddinas (and the colliding Lumbridge default) are
	// gated on the declared respawn in config, not on varbits
	private RejectionReason respawn(Transport transport)
	{
		if (!checkRespawnGate(transport))
		{
			return RejectionReason.RESPAWN_DECLARED;
		}
		return RejectionReason.NONE;
	}

	/**
	 * Gates respawn-destination transports on the declared respawn in config.
	 * When the active respawn is Prifddinas every {@code *_SPAWN} varbit reads 0,
	 * which is indistinguishable from the Lumbridge default, so the config option
	 * resolves the ambiguity in both directions.
	 */
	private boolean checkRespawnGate(Transport transport)
	{
		if (!transport.hasDisplayInfo("Respawn") && !transport.hasDisplayInfo("Ring of returning:"))
		{
			return true;
		}
		// Ring of returning lands on different tiles from the spell and POH portal.
		int destination = transport.getDestination();
		if (destination == PRIFDDINAS_RESPAWN || transport.hasDisplayInfo("Ring of returning: Prifddinas"))
		{
			return context.isRespawnPrifddinas();
		}
		if (destination == LUMBRIDGE_RESPAWN || transport.hasDisplayInfo("Ring of returning: Lumbridge"))
		{
			return !context.isRespawnPrifddinas();
		}
		return true;
	}

	// Pure-unlock requirements are gated on the declared unlock set here,
	// ahead of the item evaluation in the eligibility snapshot — teleportation-item
	// modes can skip that evaluation entirely and must still honour the gate
	private RejectionReason unlockGate(Transport transport)
	{
		if (!checkUnlockGates(transport))
		{
			return RejectionReason.UNLOCK_GATE;
		}
		return RejectionReason.NONE;
	}

	/**
	 * Gates transports carrying a pure-unlock item requirement (every OR branch
	 * of the requirement is an unlock token) on the declared unlock set. Item
	 * pools can never satisfy such a requirement, and item evaluation is not the
	 * only path a transport can take to be counted usable — teleportation-item
	 * modes skip it entirely — so the gate is checked here for every transport.
	 */
	private boolean checkUnlockGates(Transport transport)
	{
		Set<Unlock> unlocks = context.getUnlocks();
		// The POH Honour teleportation box has no Items column to carry the
		// unlock term, so it is gated here by its display info, the same
		// singleton pattern as checkRespawnGate.
		if (TransportType.TELEPORTATION_BOX.equals(transport.getType())
			&& transport.hasDisplayInfo("Honour")
			&& !unlocks.contains(Unlock.XERICS_HONOUR))
		{
			return false;
		}
		TransportItems itemRequirements = transport.getItemRequirements();
		if (itemRequirements == null)
		{
			return true;
		}
		for (ItemRequirement requirement : itemRequirements.getRequirements())
		{
			if (!requirement.isPureUnlock())
			{
				continue;
			}
			boolean declared = false;
			for (ItemRequirement.Branch branch : requirement.getBranches())
			{
				if (unlocks.contains(branch.getUnlock()))
				{
					declared = true;
					break;
				}
			}
			if (!declared)
			{
				return false;
			}
		}
		return true;
	}

	// Handle jewellery box tier filtering
	private RejectionReason jewelleryBoxTier(Transport transport)
	{
		if (TransportType.TELEPORTATION_BOX.equals(transport.getType())
			&& !PohService.jewelleryBoxSatisfied(policy.pohJewelleryBoxTier(), policy.enabledPohMountedItems(), transport))
		{
			return RejectionReason.JEWELLERY_BOX_TIER;
		}
		return RejectionReason.NONE;
	}

	private RejectionReason skillLevel(Transport transport)
	{
		return skillLevel(transport.getSkillLevels());
	}

	private RejectionReason skillLevel(SkillLevels requiredLevels)
	{
		// In leagues some skills are disabled so the max total level is lower than
		// the standard maximum. Holding the item (e.g. Max cape) already proves the
		// player is maxed for the available skills, so skip the total-level check.
		LeagueModeSnapshot leagueMode = context.getLeagueModeSnapshot();
		return boostedSkillLevelsAndMore.missingRequirement(requiredLevels,
			leagueMode.isSeasonal(), context.getCurrentMaxQuestPoints(), context.getCurrentMaxMusicTracks());
	}

	private RejectionReason quest(Transport transport)
	{
		if (transport.isQuestLocked() && !completedQuests(transport.getQuests()))
		{
			return RejectionReason.QUEST;
		}
		return RejectionReason.NONE;
	}

	private boolean completedQuests(Collection<Quest> quests)
	{
		Map<Quest, QuestState> questStates = context.getQuestStates();
		for (Quest quest : quests)
		{
			if (!QuestState.FINISHED.equals(questStates.getOrDefault(quest, QuestState.NOT_STARTED)))
			{
				return false;
			}
		}
		return true;
	}

	private RejectionReason varbit(Transport transport)
	{
		if (hooks.varChecks(transport.getVarRequirements(), context.getVarbitValues(),
			context.getEvaluationTimeMinutes(), VarRequirement.VarType.VARBIT))
		{
			return RejectionReason.VARBIT;
		}
		return RejectionReason.NONE;
	}

	private RejectionReason varplayer(Transport transport)
	{
		if (hooks.varChecks(transport.getVarRequirements(), context.getVarPlayerValues(),
			context.getEvaluationTimeMinutes(), VarRequirement.VarType.VARPLAYER))
		{
			return RejectionReason.VARPLAYER;
		}
		return RejectionReason.NONE;
	}

	private RejectionReason plantedSpiritTree(Transport transport)
	{
		TransportType type = transport.getType();
		if (TransportType.SPIRIT_TREE.equals(type) || TransportType.SEASONAL_TRANSPORTS.equals(type)
			|| TransportType.TELEPORTATION_ITEM.equals(type))
		{
			if (!checkPlantedSpiritTrees(transport))
			{
				return RejectionReason.PLANTED_SPIRIT_TREE;
			}
		}
		return RejectionReason.NONE;
	}

	private boolean checkPlantedSpiritTrees(Transport transport)
	{
		int[] endpoints = unpackEndpoints(transport);

		// Check planted spirit tree origins (travel FROM a planted tree)
		if (isUnavailablePlantedSpiritTree(endpoints[0], endpoints[1]))
		{
			return false;
		}

		// Check planted spirit tree destinations (travel TO a planted tree)
		return !isUnavailablePlantedSpiritTree(endpoints[2], endpoints[3]);
	}

	/**
	 * Whether the tile is a planted spirit-tree patch whose tree the player
	 * cannot currently use: {@code false} when the tile is not a patch at
	 * all, {@code true} when no availability observation exists yet (the
	 * unresolved case) or when the patch is absent from the available set.
	 * Callers negate this to get "allowed".
	 */
	private boolean isUnavailablePlantedSpiritTree(int x, int y)
	{
		String treeName = SpiritTreePatches.patchNameForTile(x, y);
		if (treeName == null)
		{
			return false;
		}
		Set<String> availableSpiritTrees = context.getAvailableSpiritTrees();
		if (availableSpiritTrees == null)
		{
			return true;
		}
		return !availableSpiritTrees.contains(treeName);
	}

	// The item OR-lists evaluate against the context's item pools; the
	// transport is rejected only when neither path state can satisfy them.
	private RejectionReason itemRequirement(Transport transport)
	{
		TransportEligibility eligibility = context.getEligibility();
		if (!eligibility.usable(transport, BankVisitState.CARRIED) && !eligibility.usable(transport, BankVisitState.BANKED))
		{
			return RejectionReason.ITEM_REQUIREMENT;
		}
		return RejectionReason.NONE;
	}

	/**
	 * Whether the transport has an item requirement that can only be satisfied
	 * by mode-locked items — every alternative in some requirement branch is in
	 * {@code modeLockedItemIds}. A branch that also lists a normal item keeps
	 * the transport usable on every world.
	 */
	private static boolean requiresModeLockedItem(Transport transport, Set<Integer> modeLockedItemIds)
	{
		TransportItems itemRequirements = transport.getItemRequirements();
		if (itemRequirements == null)
		{
			return false;
		}
		for (int[] alternatives : itemRequirements.getItems())
		{
			boolean allLocked = alternatives.length > 0;
			for (int itemId : alternatives)
			{
				if (!modeLockedItemIds.contains(itemId))
				{
					allLocked = false;
					break;
				}
			}
			if (allLocked)
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * The four unpacked endpoint coordinates every spatial gate reads:
	 * {@code {originX, originY, destX, destY}} in that order.
	 */
	private static int[] unpackEndpoints(Transport transport)
	{
		return new int[]{
			WorldPointUtil.unpackWorldX(transport.getOrigin()),
			WorldPointUtil.unpackWorldY(transport.getOrigin()),
			WorldPointUtil.unpackWorldX(transport.getDestination()),
			WorldPointUtil.unpackWorldY(transport.getDestination())
		};
	}
}

package shortestpath.requirement;

import java.util.*;
import shortestpath.poh.*;
import shortestpath.settings.TeleportationItem;
import shortestpath.transport.TransportType;
import lombok.Getter;
import lombok.experimental.Accessors;

/**
 * Immutable snapshot of the user routing settings the requirement gates read,
 * captured once per refresh. What goes in here is routing policy — which
 * transport types are enabled (including the quest/varbit-derived
 * {@code disableUnless} overrides, so the snapshot is taken only after those
 * derivations ran), the POH master and variant toggles, the enabled nexus
 * portals and mounted items, the jewellery-box tier, the teleportation-item
 * mode, the currency threshold, whether bank paths are included, and the
 * player-declared blocked teleport items with their destination-scoped
 * restriction blocks. Facts the
 * game or config asserts about the player — skill levels, quest states, var
 * values, owned items, declared unlocks, respawn, sailing and league state,
 * planted spirit trees — are state, not policy, and live on
 * {@link RequirementContext} instead.
 *
 * <p>Every collection is copied and frozen at construction, so mutating
 * config after the snapshot is built cannot change the verdicts of a gate
 * chain already holding it.
 */
public final class RoutingPolicy
{
	private final EnumSet<TransportType> enabledTypes;
	@Getter @Accessors(fluent = true) private final TeleportationItem teleportationItemSetting;
	@Getter @Accessors(fluent = true) private final boolean usePoh;
	@Getter @Accessors(fluent = true) private final boolean usePohFairyRing;
	@Getter @Accessors(fluent = true) private final boolean usePohSpiritTree;
	@Getter @Accessors(fluent = true) private final boolean usePohObelisk;
	@Getter @Accessors(fluent = true) private final Set<PohNexusPortal> enabledPohNexusPortals;
	@Getter @Accessors(fluent = true) private final Set<PohMountedItem> enabledPohMountedItems;
	@Getter @Accessors(fluent = true) private final JewelleryBoxTier pohJewelleryBoxTier;
	@Getter @Accessors(fluent = true) private final int currencyThreshold;
	@Getter @Accessors(fluent = true) private final boolean includeBankPath;
	/**
	 * Item ids the player excluded from routing via the hidden
	 * {@code blockedTeleportItems} CSV — a candidate-set filter, not a fact
	 * about what the player owns, so it lives on the policy side.
	 */
	@Getter @Accessors(fluent = true) private final Set<Integer> blockedItemIds;
	/**
	 * Destination-scoped restriction blocks parsed from the {@code rep@dest}
	 * records of {@code blockedTeleportItems}: a family's representative
	 * (display) item id to the packed destinations the player excluded for
	 * it. Inner destination sets are frozen at construction, matching the
	 * snapshot rule every other collection follows.
	 */
	@Getter @Accessors(fluent = true) private final Map<Integer, Set<Integer>> blockedOptionDests;

	public RoutingPolicy(
		Set<TransportType> enabledTypes,
		TeleportationItem teleportationItemSetting,
		boolean usePoh,
		boolean usePohFairyRing,
		boolean usePohSpiritTree,
		boolean usePohObelisk,
		Set<PohNexusPortal> enabledPohNexusPortals,
		Set<PohMountedItem> enabledPohMountedItems,
		JewelleryBoxTier pohJewelleryBoxTier,
		int currencyThreshold,
		boolean includeBankPath,
		Set<Integer> blockedItemIds,
		Map<Integer, Set<Integer>> blockedOptionDests)
	{
		this.enabledTypes = enabledTypes.isEmpty()
			? EnumSet.noneOf(TransportType.class)
			: EnumSet.copyOf(enabledTypes);
		this.teleportationItemSetting = teleportationItemSetting;
		this.usePoh = usePoh;
		this.usePohFairyRing = usePohFairyRing;
		this.usePohSpiritTree = usePohSpiritTree;
		this.usePohObelisk = usePohObelisk;
		this.enabledPohNexusPortals = Set.copyOf(enabledPohNexusPortals);
		this.enabledPohMountedItems = Set.copyOf(enabledPohMountedItems);
		this.pohJewelleryBoxTier = pohJewelleryBoxTier;
		this.currencyThreshold = currencyThreshold;
		this.includeBankPath = includeBankPath;
		this.blockedItemIds = Set.copyOf(blockedItemIds);
		// Inner sets are copied too — a mutable set handed out through the
		// outer map would defeat the freeze every other collection gets.
		Map<Integer, Set<Integer>> optionDests = new HashMap<>();
		for (Map.Entry<Integer, Set<Integer>> entry : blockedOptionDests.entrySet())
		{
			optionDests.put(entry.getKey(), Set.copyOf(entry.getValue()));
		}
		this.blockedOptionDests = Map.copyOf(optionDests);
	}

	/**
	 * Whether the transport type was enabled at snapshot time, after the
	 * {@code disableUnless} derivations. The enabled set itself is
	 * never handed out, so there is no live mutable reference to leak.
	 */
	public boolean isTransportTypeEnabled(TransportType type)
	{
		return enabledTypes.contains(type);
	}
}

package shortestpath.requirement;

import java.util.*;

import shortestpath.Util;

/**
 * Static metadata for the five plantable spirit tree patches (Port Sarim,
 * Etceteria, Brimhaven, Hosidius, Farming Guild) — the single source for
 * patch metadata: the region-scoped {@code FARMING_TRANSMIT_*} varbit to
 * sample and the tile bounds (inclusive) used to gate planted-tree
 * transports. Bounds must stay inside the patch's own region or the varbit
 * would not describe the tiles they cover.
 */
public final class SpiritTreePatches
{
	private SpiritTreePatches()
	{
	}

	// patch name -> {regionID, varbitID, x1, y1, x2, y2}
	private static final Map<String, int[]> PATCHES;
	private static final Map<Integer, String> PATCH_BY_REGION;

	static
	{
		Map<String, int[]> patches = new LinkedHashMap<>();
		try
		{
			Util.each("/spirit-tree-patches.tsv", (line, c) ->
				patches.put(c[0], new int[]{Integer.parseInt(c[1]), Integer.parseInt(c[2]),
					Integer.parseInt(c[3]), Integer.parseInt(c[4]), Integer.parseInt(c[5]), Integer.parseInt(c[6])}));
		}
		catch (Exception e)
		{
			throw new IllegalStateException("failed to load spirit-tree-patches.tsv", e);
		}
		PATCHES = Collections.unmodifiableMap(patches);

		Map<Integer, String> byRegion = new LinkedHashMap<>();
		for (Map.Entry<String, int[]> entry : patches.entrySet())
		{
			byRegion.put(entry.getValue()[0], entry.getKey());
		}
		PATCH_BY_REGION = Collections.unmodifiableMap(byRegion);
	}

	public static Set<String> patchNames()
	{
		return PATCHES.keySet();
	}

	public static boolean isPatch(String patchName)
	{
		return PATCHES.containsKey(patchName);
	}

	public static String patchNameForRegion(int regionId)
	{
		return PATCH_BY_REGION.get(regionId);
	}

	public static int regionForPatch(String patchName)
	{
		int[] entry = PATCHES.get(patchName);
		return entry == null ? -1 : entry[0];
	}

	public static int varbitForPatch(String patchName)
	{
		int[] entry = PATCHES.get(patchName);
		return entry == null ? -1 : entry[1];
	}

	/**
	 * Returns the planted spirit tree patch whose bounds contain the tile,
	 * or null when the tile is outside every patch. Used to gate planted-tree
	 * transport origins and destinations against the observed tree set.
	 */
	public static String patchNameForTile(int x, int y)
	{
		for (Map.Entry<String, int[]> entry : PATCHES.entrySet())
		{
			int[] patch = entry.getValue();
			if (x >= patch[2] && x <= patch[4] && y >= patch[3] && y <= patch[5])
			{
				return entry.getKey();
			}
		}
		return null;
	}
}

package shortestpath.requirement;

import java.util.*;

import lombok.*;
import lombok.experimental.Accessors;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.gameval.ItemID;
import shortestpath.*;
import shortestpath.transport.*;
import shortestpath.transport.parser.TransportRecord;

/**
 * Per-item teleport restriction support: the family map the config panel's
 * restriction checklist groups by, plus the CSV contract shared by the hidden
 * {@code blockedTeleportItems} config key.
 *
 * <p>
 * The '#'-category headers in {@code teleportation_items.tsv} are comments that
 * {@link shortestpath.transport.parser.TsvParser} skips at runtime, so the
 * grouping is materialized as its own bundled resource
 * ({@code /transports/teleport_restrictions.tsv}) generated by
 * {@code scripts/generate_teleport_restrictions.py}. Every numeric item id in
 * the source TSV belongs to exactly one family; {@code teleportation_boxes.tsv}
 * carries no {@code Items} column and is out of scope for id-keyed blocking.
 * </p>
 *
 * <p>
 * CSV contract: a comma-separated list where a bare {@code id} record blocks
 * the item and an {@code id:N} record sets a per-item threshold override of N
 * tiles. Unknown or malformed entries are skipped with a warning — user- or
 * profile-authored CSV must never break {@code refresh()} or panel
 * construction. Empty string means "no restrictions" (the default).
 * </p>
 */
@Slf4j
public final class TeleportRestriction
{
	private TeleportRestriction()
	{
	}

	/**
	 * The transport types whose item requirements are player-restrictable:
	 * per-item blocks and threshold overrides only consult these. Other types
	 * (boats, agility shortcuts, POH teleports, …) keep item requirements as
	 * pure inventory constraints.
	 */
	public static boolean isItemTeleportType(TransportType type)
	{
		return TransportType.TELEPORTATION_ITEM.equals(type)
			|| TransportType.SEASONAL_TRANSPORTS.equals(type)
			|| TransportType.QUETZAL_WHISTLE.equals(type);
	}

	/**
	 * A named group of teleportation item ids. {@code displayItemId} is the
	 * family's representative item (used for the checklist row icon);
	 * {@code memberItemIds} is the sorted set of raw item ids the family
	 * covers; {@code memberLabels} maps each member id to the display label
	 * harvested from the source TSV's {@code Display info} prefixes — the
	 * variant-match surface for checklist search.
	 */
	@Getter
	@Accessors(fluent = true)
	@AllArgsConstructor
	public static final class Family
	{
		private final String name;
		private final int displayItemId;
		private final Set<Integer> memberItemIds;
		private final Map<Integer, String> memberLabels;
		/**
		 * The family's distinct teleport destinations as a packed-destination
		 * → label map in first-seen order. Labels come straight from the
		 * source TSV's {@code Display info} cells (the tail after the first
		 * {@code ':'}, or the whole cell when it carries no {@code ':'}) —
		 * the checkbox's display string is data, so a bad label is repaired
		 * in {@code teleportation_items.tsv}, not in code. A family whose
		 * serving rows all reach one destination yields a single entry.
		 */
		private final Map<Integer, String> options;

		public Family(String name, int displayItemId, Set<Integer> memberItemIds,
			Map<Integer, String> memberLabels)
		{
			this(name, displayItemId, memberItemIds, memberLabels, Collections.emptyMap());
		}
	}

	/**
	 * The option derivation's two products: the per-family option maps the
	 * panel renders (canonical destination → label) and the rep →
	 * member-destination → group-destinations expansion index that resolves
	 * {@code rep@dest} records back to whole option groups. Both are derived
	 * in the same pass so they can never disagree about group membership.
	 */
	@AllArgsConstructor(access = AccessLevel.PACKAGE)
	private static final class DerivedOptions
	{
		private final List<ResourceLoader.RestrictionFamilyRow> rows;
		private final List<Map<Integer, String>> options;
		private final Map<Integer, Map<Integer, Set<Integer>>> expansion;
	}

	private static volatile DerivedOptions derivedOptionsHolder;

	private static DerivedOptions derivedOptions()
	{
		DerivedOptions derived = derivedOptionsHolder;
		if (derived == null)
		{
			synchronized (TeleportRestriction.class)
			{
				derived = derivedOptionsHolder;
				if (derived == null)
				{
					derived = deriveOptions(ResourceLoader.families());
					derivedOptionsHolder = derived;
				}
			}
		}
		return derived;
	}

	/**
	 * Loads the bundled family map through {@link ResourceLoader} — the loader
	 * owns the resource read and the row idiom; this entry point maps its raw
	 * rows onto the panel-facing {@link Family} model. Malformed rows are
	 * skipped with a warning (the checklist degrades to fewer rows rather than
	 * crashing); an absent or malformed {@code memberLabels} column degrades
	 * to an empty map for that family, and a missing resource degrades to an
	 * empty list — panel construction must not crash on packaging gaps.
	 */
	public static List<Family> loadFamilies()
	{
		DerivedOptions derived = derivedOptions();
		List<Family> families = new ArrayList<>(derived.rows.size());
		for (int i = 0; i < derived.rows.size(); i++)
		{
			ResourceLoader.RestrictionFamilyRow row = derived.rows.get(i);
			families.add(new Family(row.name(), row.displayItemId(),
				row.memberItemIds(), row.memberLabels(), derived.options.get(i)));
		}
		return Collections.unmodifiableList(families);
	}

	/**
	 * Every family the restriction checklist lists: the generated
	 * {@link #loadFamilies()} rows plus the code-defined families for item
	 * requirements that exist only as injected requirements. The generated
	 * map keeps its invariant — every member id traces to a
	 * {@code teleportation_items.tsv} {@code Items} cell — while the
	 * checklist surface additionally covers ids no TSV row can own.
	 */
	public static List<Family> checklistFamilies()
	{
		List<Family> families = new ArrayList<>(loadFamilies());
		families.add(fairyStaffFamily());
		return Collections.unmodifiableList(families);
	}

	/**
	 * The code-defined family for the fairy-ring staff rule. Fairy
	 * rings carry the Dramen/Lunar staff as a real item requirement
	 * synthesized at availability build (see
	 * {@link TransportEligibility#wrapFairyRingStaff}), so no
	 * {@code teleportation_items.tsv} family owns the staff ids — yet the
	 * ids restrict exactly like an item family's: a bare blocked id
	 * covering every satisfying variant disables the rings. Member ids
	 * come from the same {@link ItemVariations} name the injection reads,
	 * so the family and the requirement can never drift. The family
	 * exposes no destination options — no TSV row serves it.
	 */
	public static Family fairyStaffFamily()
	{
		Set<Integer> members = new TreeSet<>();
		Map<Integer, String> labels = new HashMap<>();
		for (int id : ItemVariations.fromName("DRAMEN_STAFF").getIds())
		{
			members.add(id);
			labels.put(id,
				id == ItemID.DRAMEN_STAFF ? "Dramen staff" : "Lunar staff");
		}
		return new Family("Fairy staves", ItemID.DRAMEN_STAFF,
			Collections.unmodifiableSet(members),
			Collections.unmodifiableMap(labels));
	}

	/**
	 * Derives each family's label-keyed option map in one pass over the
	 * bundled {@code teleportation_items.tsv} records, alongside the
	 * rep → destination → option-group expansion index. A record SERVES
	 * every family index its {@code Items} cell contributes a member id to —
	 * a cross-family OR row lands the same destination option in each family
	 * it serves.
	 *
	 * <p>
	 * Option identity is the in-game teleport name: every serving record's
	 * {@code Display info} tail (after the first {@code ':'}; the whole cell
	 * when it carries none; the raw coordinates when the cell is blank) names
	 * the option its {@code Destination} joins. Rows sharing a label collapse
	 * into one option covering all their destinations — varbit- and
	 * skill-gated tile variants of a single menu entry. A destination claimed
	 * by an earlier label never joins a later group: a conflicting label for
	 * an already-seen destination keeps the first label and warns, and a
	 * label left with no destination yields no option. The map key is the
	 * group's canonical (first-seen) destination so {@code rep@dest} records
	 * keep their tile-shaped second half.
	 * </p>
	 */
	private static DerivedOptions deriveOptions(
		List<ResourceLoader.RestrictionFamilyRow> rows)
	{
		Map<Integer, Integer> memberToFamily = new HashMap<>();
		for (int i = 0; i < rows.size(); i++)
		{
			for (int memberId : rows.get(i).memberItemIds())
			{
				Integer previous = memberToFamily.putIfAbsent(memberId, i);
				if (previous != null && !previous.equals(i))
				{
					log.warn("Item id {} claimed by families '{}' and '{}' — '{}' serves it",
						memberId, rows.get(previous).name(), rows.get(i).name(),
						rows.get(previous).name());
				}
			}
		}

		// family index -> option label -> the ordered group of destinations
		// that label claims (first-seen label order); family index ->
		// destination -> owning label (one tile, one option).
		List<Map<String, LinkedHashSet<Integer>>> labelGroups = new ArrayList<>(rows.size());
		List<Map<Integer, String>> claimed = new ArrayList<>(rows.size());
		for (int i = 0; i < rows.size(); i++)
		{
			labelGroups.add(new LinkedHashMap<>());
			claimed.add(new HashMap<>());
		}

		if (!memberToFamily.isEmpty())
		{
			for (TransportRecord record : ResourceLoader.teleportationItemRecords())
			{
				Set<Integer> served = servedFamilyIndexes(record.getItems(), memberToFamily);
				if (served.isEmpty())
				{
					continue;
				}

				int[] destination = parseDestination(record.getDestination());
				if (destination == null)
				{
					log.warn("Skipping teleportation_items row with unparseable Destination '{}'",
						record.getDestination());
					continue;
				}

				int packedDest =
					WorldPointUtil.packWorldPoint(destination[0], destination[1], destination[2]);
				String label = optionLabel(record.getDisplayInfo(), destination);

				for (int familyIdx : served)
				{
					String owner = claimed.get(familyIdx).get(packedDest);
					if (owner != null)
					{
						if (!owner.equals(label))
						{
							log.warn("Conflicting option label for family '{}' destination {} "
								+ "('{}' vs '{}') — keeping the first",
								rows.get(familyIdx).name(), record.getDestination(),
								owner, label);
						}
						continue;
					}
					claimed.get(familyIdx).put(packedDest, label);
					labelGroups.get(familyIdx)
						.computeIfAbsent(label, k -> new LinkedHashSet<>())
						.add(packedDest);
				}
			}
		}

		List<Map<Integer, String>> options = new ArrayList<>(rows.size());
		Map<Integer, Map<Integer, Set<Integer>>> expansion = new HashMap<>();
		for (int i = 0; i < rows.size(); i++)
		{
			Map<Integer, String> familyOptions = new LinkedHashMap<>();
			Map<Integer, Set<Integer>> destToGroup = new HashMap<>();
			for (Map.Entry<String, LinkedHashSet<Integer>> group : labelGroups.get(i).entrySet())
			{
				Set<Integer> groupDests = Collections.unmodifiableSet(group.getValue());
				// The canonical destination is the group's first-seen tile —
				// the key rep@dest records store and expand through.
				familyOptions.put(group.getValue().iterator().next(), group.getKey());
				for (int dest : group.getValue())
				{
					destToGroup.put(dest, groupDests);
				}
			}
			options.add(Collections.unmodifiableMap(familyOptions));
			if (!destToGroup.isEmpty())
			{
				expansion.put(rows.get(i).displayItemId(),
					Collections.unmodifiableMap(destToGroup));
			}
		}

		return new DerivedOptions(rows, Collections.unmodifiableList(options),
			Collections.unmodifiableMap(expansion));
	}

	/**
	 * The family indexes a record's {@code Items} cell serves: every operand's
	 * digit item id is looked up in the member index. Mirrors the
	 * ItemRequirementParser operand grammar in miniature — spaces stripped,
	 * {@code &&}/{@code ||} normalized, operands split on {@code &}/{@code |},
	 * the {@code NAME} side of {@code NAME=qty} taken, {@code UNLOCK_}
	 * prefixes skipped. Non-digit operands warn and skip rather than throw —
	 * this scan never breaks on data.
	 */
	private static Set<Integer> servedFamilyIndexes(String itemsCell,
		Map<Integer, Integer> memberToFamily)
	{
		Set<Integer> served = new LinkedHashSet<>();
		if (itemsCell == null || itemsCell.isEmpty())
		{
			return served;
		}

		String normalized = itemsCell.replace(" ", "")
			.replace("&&", "&")
			.replace("||", "|");
		for (String operand : normalized.split("[&|]"))
		{
			if (operand.isEmpty())
			{
				continue;
			}
			int eq = operand.indexOf('=');
			String name = eq >= 0 ? operand.substring(0, eq) : operand;
			if (name.startsWith("UNLOCK_"))
			{
				continue;
			}
			try
			{
				Integer familyIdx = memberToFamily.get(Integer.parseInt(name));
				if (familyIdx != null)
				{
					served.add(familyIdx);
				}
			}
			catch (NumberFormatException e)
			{
				log.warn("Skipping non-item operand '{}' in Items cell '{}'", name, itemsCell);
			}
		}
		return served;
	}

	/**
	 * Parses a {@code "x y z"} destination cell to its three coordinates;
	 * {@code null} when the cell is missing, blank, or not exactly three
	 * integers.
	 */
	private static int[] parseDestination(String cell)
	{
		if (cell == null || cell.isBlank())
		{
			return null;
		}
		String[] parts = cell.trim().split("\\s+");
		if (parts.length != 3)
		{
			return null;
		}
		try
		{
			return new int[]{
				Integer.parseInt(parts[0]),
				Integer.parseInt(parts[1]),
				Integer.parseInt(parts[2])};
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}

	/**
	 * The GUI label for one serving row: the {@code Display info} tail after
	 * the first {@code ':'}, the whole trimmed cell when it carries none, or
	 * the raw {@code "x, y, z"} coordinates when the cell (or its tail) is
	 * blank.
	 */
	private static String optionLabel(String displayInfo, int[] destination)
	{
		if (displayInfo != null)
		{
			int colon = displayInfo.indexOf(':');
			String label = colon >= 0
				? displayInfo.substring(colon + 1).trim()
				: displayInfo.trim();
			if (!label.isEmpty())
			{
				return label;
			}
		}
		return destination[0] + ", " + destination[1] + ", " + destination[2];
	}

	/**
	 * Parses the {@code blockedTeleportItems} CSV into a blocked-id set and a
	 * per-item threshold map, discarding any {@code rep@dest} option-block
	 * records. Delegates to the three-output overload so the panel keeps
	 * compiling on the two-output call until the option UI lands.
	 */
	public static void parseBlocked(String csv, Set<Integer> blockedOut, Map<Integer, Integer> thresholdOut)
	{
		parseBlocked(csv, blockedOut, thresholdOut, new HashMap<>());
	}

	/**
	 * Parses the {@code blockedTeleportItems} CSV into a blocked-id set, a
	 * per-item threshold map and a per-family destination-block map.
	 * {@code id} records add to {@code blockedOut}; {@code id:N} records
	 * merge into {@code thresholdOut} keeping the max N per id;
	 * {@code repId@packedDest} records merge into {@code optionBlocksOut} —
	 * the rep id is the family's {@code displayItemId}, so the panel and the
	 * engine share one key space. Malformed entries are skipped with a
	 * warning; this method never throws on user-authored input.
	 */
	public static void parseBlocked(String csv, Set<Integer> blockedOut,
		Map<Integer, Integer> thresholdOut, Map<Integer, Set<Integer>> optionBlocksOut)
	{
		if (csv == null || csv.isBlank())
		{
			return;
		}

		for (String rawEntry : csv.split(","))
		{
			String entry = rawEntry.trim();
			if (entry.isEmpty())
			{
				continue;
			}

			try
			{
				int at = entry.indexOf('@');
				if (at >= 0)
				{
					// Destination-scoped option block: rep@packedDest. Entries
					// never legitimately contain '@' elsewhere — require
					// exactly two int-parseable parts. The rep is an item id
					// and cannot be negative; the destination can — packed
					// world points at plane >= 2 set the sign bit.
					String[] parts = entry.split("@", -1);
					if (parts.length != 2)
					{
						throw new NumberFormatException("expected rep@dest");
					}
					int rep = Integer.parseInt(parts[0].trim());
					int dest = Integer.parseInt(parts[1].trim());
					if (rep < 0)
					{
						throw new NumberFormatException("negative rep id");
					}
					optionBlocksOut.computeIfAbsent(rep, k -> new HashSet<>()).add(dest);
					continue;
				}

				int colon = entry.indexOf(':');
				if (colon < 0)
				{
					int id = Integer.parseInt(entry);
					if (id < 0)
					{
						throw new NumberFormatException("negative id");
					}
					blockedOut.add(id);
				}
				else
				{
					int id = Integer.parseInt(entry.substring(0, colon).trim());
					int threshold = Integer.parseInt(entry.substring(colon + 1).trim());
					if (id < 0 || threshold < 0)
					{
						throw new NumberFormatException("negative id or threshold");
					}
					thresholdOut.merge(id, threshold, Math::max);
				}
			}
			catch (NumberFormatException e)
			{
				log.warn("Skipping malformed blockedTeleportItems entry: {}", entry);
			}
		}
	}

	/**
	 * Serializes a blocked-id set and threshold map back to the CSV contract,
	 * dropping any option blocks. Delegates to the three-input overload.
	 */
	public static String toCsv(Set<Integer> blocked, Map<Integer, Integer> thresholds)
	{
		return toCsv(blocked, thresholds, Map.of());
	}

	/**
	 * Serializes a blocked-id set, threshold map and option-block map back to
	 * the CSV contract: sorted blocked ids first, then sorted {@code id:N}
	 * threshold records, then {@code rep@dest} records sorted by rep then
	 * destination. Empty (or null) inputs produce {@code ""}.
	 */
	public static String toCsv(Set<Integer> blocked, Map<Integer, Integer> thresholds,
		Map<Integer, Set<Integer>> optionBlocks)
	{
		StringBuilder sb = new StringBuilder();

		if (blocked != null)
		{
			List<Integer> ids = new ArrayList<>(blocked);
			Collections.sort(ids);
			for (int id : ids)
			{
				if (sb.length() > 0)
				{
					sb.append(',');
				}
				sb.append(id);
			}
		}

		if (thresholds != null)
		{
			List<Integer> ids = new ArrayList<>(thresholds.keySet());
			Collections.sort(ids);
			for (int id : ids)
			{
				if (sb.length() > 0)
				{
					sb.append(',');
				}
				sb.append(id).append(':').append(thresholds.get(id));
			}
		}

		if (optionBlocks != null)
		{
			List<Integer> reps = new ArrayList<>(optionBlocks.keySet());
			Collections.sort(reps);
			for (int rep : reps)
			{
				List<Integer> dests = new ArrayList<>(optionBlocks.get(rep));
				Collections.sort(dests);
				for (int dest : dests)
				{
					if (sb.length() > 0)
					{
						sb.append(',');
					}
					sb.append(rep).append('@').append(dest);
				}
			}
		}

		return sb.toString();
	}

	/**
	 * The lazily-built memberId → representative (displayItemId) index over
	 * {@link #loadFamilies()}, published through a volatile reference and
	 * built once inside a synchronized holder — the families are static
	 * bundled resources, so one immutable index serves every caller. Two
	 * families claiming the same member id must not happen; if the data ever
	 * drifts there the first family written wins and a warning is logged.
	 */
	private static volatile Map<Integer, Integer> representativeIndexHolder;

	public static Map<Integer, Integer> representativeIndex()
	{
		Map<Integer, Integer> index = representativeIndexHolder;
		if (index == null)
		{
			synchronized (TeleportRestriction.class)
			{
				index = representativeIndexHolder;
				if (index == null)
				{
					index = buildRepresentativeIndex();
					representativeIndexHolder = index;
				}
			}
		}
		return index;
	}

	private static Map<Integer, Integer> buildRepresentativeIndex()
	{
		Map<Integer, Integer> index = new HashMap<>();
		for (Family family : loadFamilies())
		{
			for (int memberId : family.memberItemIds())
			{
				Integer previous = index.putIfAbsent(memberId, family.displayItemId());
				if (previous != null && previous != family.displayItemId())
				{
					log.warn("Item id {} claimed by multiple restriction families "
						+ "('{}' wins)", memberId, family.name());
				}
			}
		}
		return Collections.unmodifiableMap(index);
	}

	/**
	 * The rep → member-destination → option-group-destinations expansion
	 * index derived alongside {@link #loadFamilies()}' option groups. A
	 * {@code rep@dest} record names one option by its canonical destination,
	 * but any member destination resolves to the same group, so a stale
	 * record still blocks the whole option. Unmodifiable; representatives
	 * with no option rows are absent.
	 */
	public static Map<Integer, Map<Integer, Set<Integer>>> optionExpansionIndex()
	{
		return derivedOptions().expansion;
	}

	/**
	 * Maps every recorded destination in {@code optionBlocks} through
	 * {@link #optionExpansionIndex()}, unioning each destination's option
	 * group — one record suppresses every tile variant of the option it
	 * names. Destinations absent from the index pass through as literal
	 * blocked tiles, so a stale {@code blockedTeleportItems} row degrades to
	 * its written destination rather than silently widening. The returned
	 * sets are fresh copies; callers may freeze or mutate them independently
	 * of the index.
	 */
	public static Map<Integer, Set<Integer>> expandOptionDests(
		Map<Integer, Set<Integer>> optionBlocks)
	{
		Map<Integer, Map<Integer, Set<Integer>>> index = optionExpansionIndex();
		Map<Integer, Set<Integer>> expanded = new HashMap<>();
		for (Map.Entry<Integer, Set<Integer>> entry : optionBlocks.entrySet())
		{
			Map<Integer, Set<Integer>> repIndex = index.get(entry.getKey());
			Set<Integer> dests = new LinkedHashSet<>();
			for (int dest : entry.getValue())
			{
				Set<Integer> group = repIndex == null ? null : repIndex.get(dest);
				if (group == null)
				{
					dests.add(dest);
				}
				else
				{
					dests.addAll(group);
				}
			}
			expanded.put(entry.getKey(), dests);
		}
		return expanded;
	}
}

package shortestpath.requirement;

import shortestpath.settings.TeleportationItem;

/**
 * The single source for what a {@link TeleportationItem} mode means: given the
 * configured mode and whether the transport consumes its item, {@link #verdict}
 * answers the nine-mode truth table both the requirement chain
 * ({@link Requirements#check}) and the eligibility snapshot
 * ({@link TransportEligibility#usable}) used to encode as twin switches.
 *
 * <p>Boundary: this class answers ONLY the mode × consumable dispatch (and the
 * bank-path axis — see the class's {@code includesBank}). The gates that run
 * before the mode dispatch — the seasonal-world, Deadman-item, per-item and
 * per-option restriction checks — stay {@code Requirements}-side; they are not
 * mode semantics. The verdict is deliberately NOT a {@link RejectionReason}:
 * deferring to item evaluation is not a rejection, and a defer value in the
 * gate vocabulary would force every {@code switch}/{@code equals} that reads
 * reasons to handle a verdict that can never be returned.
 */
public final class TeleportationItemPolicy
{
	private TeleportationItemPolicy()
	{
	}

	/**
	 * The mode × consumable verdict: what the teleportation-item setting does
	 * to a single item-teleport transport before its item requirements are
	 * consulted.
	 */
	public enum Verdict
	{
		/**
		 * The item pools are never consulted — the mode admits the transport
		 * outright. {@code ALL} and {@code UNLOCKED} bypass every transport;
		 * for {@code UNLOCKED} ownership is implied by the unlock check, so
		 * items are never evaluated. The {@code *_NON_CONSUMABLE} bypass modes
		 * land here for non-consumable transports only.
		 */
		BYPASS,

		/**
		 * Defer to {@link shortestpath.requirement.model.TransportItems#isSatisfiedBy}
		 * pool evaluation — neither a rejection nor a bypass. Callers fall
		 * through to the pool check; they must never treat this verdict as
		 * {@code true}, or the inventory modes would resurrect transports the
		 * pools would reject.
		 */
		EVALUATE_ITEMS,

		/**
		 * The mode refuses this transport outright: {@code NONE} always, and
		 * every {@code *_NON_CONSUMABLE} mode on a consumable transport.
		 */
		REJECT
	}

	/**
	 * The verdict for one transport under the configured mode. The truth table
	 * (previously encoded identically in {@code Requirements.teleportationItem}
	 * and {@code TransportEligibility.usable}):
	 * {@code NONE} rejects; {@code ALL} and {@code UNLOCKED} bypass; the
	 * {@code INVENTORY*} modes defer to the pools; and every
	 * {@code *_NON_CONSUMABLE} mode rejects a consumable transport while
	 * behaving like its unrestricted counterpart on a non-consumable one.
	 */
	public static Verdict verdict(TeleportationItem mode, boolean consumable)
	{
		switch (mode)
		{
			case NONE:
				return Verdict.REJECT;
			case ALL:
			case UNLOCKED:
				return Verdict.BYPASS;
			case ALL_NON_CONSUMABLE:
			case UNLOCKED_NON_CONSUMABLE:
				return consumable ? Verdict.REJECT : Verdict.BYPASS;
			case INVENTORY:
			case INVENTORY_AND_BANK:
				return Verdict.EVALUATE_ITEMS;
			case INVENTORY_NON_CONSUMABLE:
			case INVENTORY_AND_BANK_NON_CONSUMABLE:
				return consumable ? Verdict.REJECT : Verdict.EVALUATE_ITEMS;
			default:
				// A mode added to the enum lands here until a row is added
				// above — pool evaluation is the fail-closed default, and the
				// mode-matrix completeness guard catches the missing cell.
				return Verdict.EVALUATE_ITEMS;
		}
	}

	/**
	 * Whether the mode's bank-path pool includes the bank contents — the
	 * second axis of mode semantics, single-sourced with the verdict table
	 * above it. Only the {@code INVENTORY_AND_BANK*} modes collect the bank
	 * into the pool banked transports are evaluated against.
	 */
	public static boolean includesBank(TeleportationItem mode)
	{
		return TeleportationItem.INVENTORY_AND_BANK.equals(mode)
			|| TeleportationItem.INVENTORY_AND_BANK_NON_CONSUMABLE.equals(mode);
	}
}

package shortestpath.requirement;

import java.util.*;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.*;
import shortestpath.ItemVariations;
import shortestpath.items.OwnedItems;
import shortestpath.pathfinder.*;
import shortestpath.requirement.model.*;
import shortestpath.settings.TeleportationItem;
import shortestpath.transport.*;
import lombok.Getter;
import lombok.experimental.Accessors;

/**
 * Immutable snapshot of everything transport item-requirement evaluation needs, captured
 * once per refresh on the client thread. One snapshot answers every layer's question so
 * they can no longer diverge:
 * <ul>
 * <li>{@link #usable} — the pathfinding verdict over the carried pool ({@code banked}
 * false) or the bank-path pool ({@code banked} true), honouring the teleportation-item
 * setting, the fairy-ring staff rule and the currency threshold.</li>
 * <li>{@link #satisfiedByPlayer} — the carried-pool-only check the overlays use, with no
 * currency threshold (the player already owns the items, so none would be spent).</li>
 * <li>{@link #bankPickupPlan} and {@link #targetPickupPlan} — the items the bank must
 * supply for one transport or target, plus the bank item ids to highlight.</li>
 * </ul>
 *
 * <p>The pools are fixed at construction: {@code carriedItems} is inventory + worn +
 * rune pouch in hand, {@code bankPathItems} additionally contains the bank contents when
 * bank paths are enabled (otherwise it is the carried pool), {@code bankHas} is the raw
 * bank contents and {@code bankPouchRunes} the runes inside a banked rune pouch.
 *
 * <p>Pickup witnesses are resolved in a canonical order shared by phrase and highlight:
 * the banked rune pouch first (when taken); then, per requirement the carried pool does
 * not satisfy, topping up a variant the player already carries across all OR branches in
 * declaration order; else the OR branches in declaration order with the pure
 * (first-listed) variant preferred; else staff ids, then offhand ids. The displayed item
 * id is the carried variant when topping up, else the chosen branch's first
 * (canonical) id.
 */
public final class TransportEligibility
{
	/**
	 * Fairy-ring staff requirement: a Dramen/Lunar staff, unless the Lumbridge Elite
	 * diary is complete. This is the single representation of that rule.
	 */
	private static final TransportItems DRAMEN_STAFF = new TransportItems(
		new int[][]{null},
		new int[][]{ItemVariations.fromName("DRAMEN_STAFF").getIds()},
		new int[][]{null},
		new int[]{1});

	private final Map<Integer, Integer> carriedItems;
	private final Map<Integer, Integer> bankPathItems;
	private final Map<Integer, Integer> bankHas;
	private final int bankPouchId;
	private final Map<Integer, Integer> bankPouchRunes;
	private final boolean fairyRingStaffRequired;
	private final TeleportationItem teleportationItemSetting;
	private final int currencyThreshold;
	private final Set<Unlock> unlocks;
	/**
	 * Packed destinations of the balloon routes whose log basket the player
	 * declared stocked — the destinations a {@link TransportType#HOT_AIR_BALLOON}
	 * transport may land on to be granted {@link Unlock#BALLOON_LOG_BASKET}.
	 */
	private final Set<Integer> balloonLogBasketDestinations;
	/**
	 * {@link #unlocks} plus {@link Unlock#BALLOON_LOG_BASKET} — precomputed
	 * once so {@link #unlocksFor} hands out the same immutable set to every
	 * eligible balloon transport instead of allocating per call.
	 */
	private final Set<Unlock> unlocksWithBalloonBasket;
	@Getter @Accessors(fluent = true) private final HeldItems heldItems;

	public TransportEligibility(
		Map<Integer, Integer> carriedItems,
		Map<Integer, Integer> bankPathItems,
		Map<Integer, Integer> bankHas,
		int bankPouchId,
		Map<Integer, Integer> bankPouchRunes,
		boolean fairyRingStaffRequired,
		TeleportationItem teleportationItemSetting,
		int currencyThreshold,
		Set<Unlock> unlocks,
		boolean bankSeen,
		Set<Integer> balloonLogBasketDestinations)
	{
		this.carriedItems = Map.copyOf(carriedItems);
		this.bankPathItems = Map.copyOf(bankPathItems);
		this.bankHas = Map.copyOf(bankHas);
		this.bankPouchId = bankPouchId;
		this.bankPouchRunes = Map.copyOf(bankPouchRunes);
		this.fairyRingStaffRequired = fairyRingStaffRequired;
		this.teleportationItemSetting = teleportationItemSetting;
		this.currencyThreshold = currencyThreshold;
		this.unlocks = Set.copyOf(unlocks);
		this.balloonLogBasketDestinations = Set.copyOf(balloonLogBasketDestinations);
		Set<Unlock> withBasket = EnumSet.noneOf(Unlock.class);
		withBasket.addAll(unlocks);
		withBasket.add(Unlock.BALLOON_LOG_BASKET);
		this.unlocksWithBalloonBasket = Collections.unmodifiableSet(withBasket);
		// What the player holds is a projection of this same collection: the carried
		// pool, plus the bank contents and a banked pouch's runes once the bank has
		// been seen — the one item snapshot also answers the target-status question.
		Map<Integer, Integer> carriedAndBanked = new HashMap<>(carriedItems);
		bankHas.forEach((itemId, quantity) -> carriedAndBanked.merge(itemId, quantity, Integer::sum));
		bankPouchRunes.forEach((itemId, quantity) -> carriedAndBanked.merge(itemId, quantity, Integer::sum));
		this.heldItems = new HeldItems(carriedItems, carriedAndBanked, bankSeen);
	}

	/**
	 * Builds a snapshot whose bank-path pool is the carried pool merged with the bank
	 * contents, with no fairy-ring staff requirement, a {@link TeleportationItem#NONE}
	 * setting, no currency threshold and no declared unlocks.
	 */
	public static TransportEligibility forPlayerAndBank(
		Map<Integer, Integer> playerItems,
		Map<Integer, Integer> bankHas,
		int bankPouchId,
		Map<Integer, Integer> bankPouchRunes)
	{
		Map<Integer, Integer> bankPathItems = new HashMap<>(playerItems);
		bankHas.forEach((itemId, quantity) -> bankPathItems.merge(itemId, quantity, Integer::sum));
		return new TransportEligibility(playerItems, bankPathItems, bankHas, bankPouchId, bankPouchRunes,
			false, TeleportationItem.NONE, Integer.MAX_VALUE, Set.of(), true, Set.of());
	}

	/**
	 * Captures the client state both the pathfinding verdicts and the bank-pickup plans
	 * read: the carried pool (inventory + worn + rune pouch in hand), the bank-path pool
	 * (which adds the bank contents when bank paths are enabled), the bank contents
	 * themselves, the runes inside a banked rune pouch, the fairy-ring staff gate and
	 * the currency threshold. {@code balloonLogBasketDestinations} additionally
	 * captures the packed destinations of the balloon routes whose log basket the
	 * player declared stocked. Shared by
	 * {@link RequirementContext#capture RequirementContext.capture}
	 * and the lazy {@code PathfinderConfig#getEligibility()} rebuild so exactly one
	 * collection path exists.
	 */
	public static TransportEligibility collect(
		PlayerStateSource source,
		ItemContainer bank,
		TeleportationItem teleportationItemSetting,
		int currencyThreshold,
		boolean includeBankPath,
		Set<Unlock> unlocks,
		Set<Integer> balloonLogBasketDestinations)
	{
		Map<Integer, Integer> carriedItems = collectItems(source, bank,
			teleportationItemSetting, true, true, false, true);
		Map<Integer, Integer> bankPathItems = includeBankPath
			? collectItems(source, bank, teleportationItemSetting, true, true, true, true)
			: carriedItems;
		Map<Integer, Integer> bankHas = new HashMap<>();
		OwnedItems.addContainer(bankHas, bank);
		int bankPouchId = -1;
		for (int pouchId : OwnedItems.RUNE_POUCHES)
		{
			if (bankHas.containsKey(pouchId))
			{
				bankPouchId = pouchId;
				break;
			}
		}
		Map<Integer, Integer> bankPouchRunes = bankPouchId == -1
			? Map.of()
			: source.runePouchContents();
		boolean fairyRingStaffRequired =
			source.varbit(VarbitID.LUMBRIDGE_DIARY_ELITE_COMPLETE) != 1;
		return new TransportEligibility(carriedItems, bankPathItems, bankHas, bankPouchId, bankPouchRunes,
			fairyRingStaffRequired, teleportationItemSetting, currencyThreshold,
			unlocks, bank != null, balloonLogBasketDestinations);
	}

	/**
	 * Item id to quantity over the selected containers, summed across containers.
	 */
	private static Map<Integer, Integer> collectItems(
		PlayerStateSource source,
		ItemContainer bank,
		TeleportationItem teleportationItemSetting,
		boolean checkInventory,
		boolean checkEquipment,
		boolean checkBank,
		boolean checkRunePouch)
	{
		Map<Integer, Integer> itemsAndQuantities = new HashMap<>(28 + 11 + 500);

		if (checkInventory)
		{
			OwnedItems.addContainer(itemsAndQuantities, source.itemContainer(InventoryID.INV));
		}

		if (checkEquipment)
		{
			OwnedItems.addContainer(itemsAndQuantities, source.itemContainer(InventoryID.WORN));
		}

		if (checkBank
			&& TeleportationItemPolicy.includesBank(teleportationItemSetting))
		{
			OwnedItems.addContainer(itemsAndQuantities, bank);
		}

		if (checkRunePouch)
		{
			source.addRunePouchContents(itemsAndQuantities);
		}

		return itemsAndQuantities;
	}

	/**
	 * What the player held when this snapshot was captured — carried items, those plus the
	 * last-seen bank, and whether the bank has been opened this session. The searches read
	 * it to decide each target's {@code TargetStatus}; it is derived from the same pools
	 * the eligibility verdicts use, so both can never observe different item state.
	 */


	/**
	 * The unlocks one transport's requirements are evaluated with: the declared
	 * unlocks, plus {@link Unlock#BALLOON_LOG_BASKET} when the transport is a
	 * hot-air balloon whose destination basket the player declared stocked.
	 * The grant is destination-scoped — only balloon rows carry the
	 * {@code UNLOCK_BALLOON_LOG_BASKET} token, so nothing else can consume it,
	 * and a balloon route whose destination is not configured still demands
	 * its specific log.
	 */
	private Set<Unlock> unlocksFor(Transport transport)
	{
		return TransportType.HOT_AIR_BALLOON.equals(transport.getType())
			&& balloonLogBasketDestinations.contains(transport.getDestination())
			? unlocksWithBalloonBasket
			: unlocks;
	}

	/** Injects the staff requirement for every fairy ring unless Lumbridge Elite is complete. */
	public Transport wrapFairyRingStaff(Transport transport)
	{
		if (!fairyRingStaffRequired || !TransportType.FAIRY_RING.equals(transport.getType()))
		{
			return transport;
		}
		return transport.withItemRequirements(
			TransportItems.merge(transport.getItemRequirements(), DRAMEN_STAFF));
	}

	/**
	 * Whether the transport's item requirements are met by the carried pool
	 * ({@link BankVisitState#CARRIED}) or the bank-path pool ({@link BankVisitState#BANKED}).
	 * Teleportation item transports are first bypassed or blocked by the
	 * teleportation-item setting; everything else defers to
	 * {@link TransportItems#isSatisfiedBy} at the configured currency threshold.
	 * Fairy rings reaching this point already carry the injected staff
	 * requirement — see {@link #wrapFairyRingStaff}.
	 */
	public boolean usable(Transport transport, BankVisitState banked)
	{
		// Mirror the requirement chain's teleportation-item gate: the shared
		// policy verdict bypasses the pools or rejects outright, and
		// EVALUATE_ITEMS falls through to pool evaluation below.
		if (TeleportRestriction.isItemTeleportType(transport.getType()))
		{
			switch (TeleportationItemPolicy.verdict(teleportationItemSetting, transport.isConsumable()))
			{
				case BYPASS:
					return true;
				case REJECT:
					return false;
				default:
					break;
			}
		}

		Map<Integer, Integer> ownedItems = banked == BankVisitState.BANKED ? bankPathItems : carriedItems;

		TransportItems transportItems = transport.getItemRequirements();
		return transportItems == null
			|| transportItems.isSatisfiedBy(ownedItems, TransportItems.CURRENCIES, currencyThreshold,
				unlocksFor(transport));
	}

	/**
	 * Whether the carried pool alone meets the transport's item requirements, ignoring
	 * the currency threshold — the player already owns the items, so nothing is spent.
	 */
	public boolean satisfiedByPlayer(Transport transport)
	{
		TransportItems transportItems = transport.getItemRequirements();
		return transportItems == null
			|| transportItems.isSatisfiedBy(carriedItems, TransportItems.CURRENCIES, Integer.MAX_VALUE,
				unlocksFor(transport));
	}

	/**
	 * The items to pick up from the bank for one transport and the bank item ids to
	 * highlight. {@link BankPickupPlan#items} is {@code null} when the bank cannot fully
	 * supply the transport; the highlight ids are still populated with whatever relevant
	 * items the bank does hold.
	 */
	public BankPickupPlan bankPickupPlan(Transport transport)
	{
		Map<Integer, Long> items = new LinkedHashMap<>();
		Set<Integer> bankItemIds = new HashSet<>();
		if (transport.getItemRequirements() == null)
		{
			return new BankPickupPlan(items, bankItemIds);
		}

		// Prefer the bank rune pouch over individual runes. This avoids surfacing
		// combination rune variants (mist, dust, etc.) when the pouch already covers
		// the requirement.
		Set<Unlock> transportUnlocks = unlocksFor(transport);
		Map<Integer, Integer> carried = carriedWithBankPouch(transport, carriedItems, bankHas, bankPouchRunes,
			transportUnlocks);
		if (carried != carriedItems)
		{
			items.put(bankPouchId, 1L);
			bankItemIds.add(bankPouchId);
		}

		boolean fullySupplied = true;
		for (ItemRequirement req : transport.getItemRequirements().getRequirements())
		{
			if (playerSatisfies(req, carried, transportUnlocks))
			{
				continue;
			}

			// Highlight every bank item that covers part of the shortfall: all item
			// variants of each OR branch at that branch's quantity, plus any covering
			// staff or offhand the bank holds.
			for (ItemRequirement.Branch branch : req.getBranches())
			{
				addCovering(branch.getItemIds(), pickupQuantity(branch), carried, bankHas, bankItemIds);
			}
			addCovering(req.getStaffIds(), 1, Map.of(), bankHas, bankItemIds);
			addCovering(req.getOffhandIds(), 1, Map.of(), bankHas, bankItemIds);

			if (!fullySupplied)
			{
				continue; // pickup resolution already failed; keep scanning for ids only
			}

			// Resolve the pickup under the canonical witness order. First top up a
			// variant the player already carries, across all OR branches, which saves a
			// slot, then fall back to the branches in declaration order (pure item
			// variant first within each branch). The displayed item id is the carried
			// variant when topping up, else the chosen branch's canonical id.
			ItemRequirement.Branch chosen = null;
			int foundId = -1;
			for (ItemRequirement.Branch branch : req.getBranches())
			{
				foundId = findCarriedCovering(branch.getItemIds(), pickupQuantity(branch), carried, bankHas);
				if (foundId != -1)
				{
					chosen = branch;
					break;
				}
			}
			if (chosen == null)
			{
				for (ItemRequirement.Branch branch : req.getBranches())
				{
					foundId = findCovering(branch.getItemIds(), pickupQuantity(branch), carried, bankHas);
					if (foundId != -1)
					{
						chosen = branch;
						break;
					}
				}
			}
			if (chosen != null)
			{
				int carriedQty = carried.getOrDefault(foundId, 0);
				int displayId = carriedQty > 0 ? foundId : chosen.getItemIds()[0];
				items.merge(displayId, (long) (pickupQuantity(chosen) - carriedQty), Long::sum);
				continue;
			}
			foundId = findCovering(req.getStaffIds(), 1, Map.of(), bankHas);
			if (foundId == -1)
			{
				foundId = findCovering(req.getOffhandIds(), 1, Map.of(), bankHas);
			}
			if (foundId == -1)
			{
				fullySupplied = false; // bank can't satisfy this requirement
				continue;
			}
			items.merge(foundId, 1L, Long::sum);
		}
		return new BankPickupPlan(fullySupplied ? items : null, bankItemIds);
	}

	/**
	 * The pickup plan for a target's required items: {@link BankPickupPlan#items} holds one
	 * entry per item group the player doesn't already carry, keyed by the first bank-covering
	 * item id of the covering OR branch and valued at the shortfall quantity; each entry is a
	 * separate display phrase. {@link BankPickupPlan#bankItemIds} collects every covering bank
	 * item across all branches. Item groups the player carries and groups the bank cannot
	 * cover contribute nothing.
	 */
	public BankPickupPlan targetPickupPlan(TransportItems targetItems)
	{
		Map<Integer, Long> items = new LinkedHashMap<>();
		Set<Integer> bankItemIds = new HashSet<>();
		for (ItemRequirement group : targetItems.getRequirements())
		{
			boolean carried = false;
			for (ItemRequirement.Branch branch : group.getBranches())
			{
				carried |= findCovering(branch.getItemIds(), branch.getQuantity(), carriedItems, Map.of()) != -1;
			}
			if (carried)
			{
				continue;
			}
			boolean phrased = false;
			for (ItemRequirement.Branch branch : group.getBranches())
			{
				int foundId = findCovering(branch.getItemIds(), branch.getQuantity(), carriedItems, bankHas);
				if (foundId == -1)
				{
					continue;
				}
				addCovering(branch.getItemIds(), branch.getQuantity(), carriedItems, bankHas, bankItemIds);
				if (!phrased)
				{
					items.put(foundId, (long) branch.getQuantity() - carriedItems.getOrDefault(foundId, 0));
					phrased = true;
				}
			}
		}
		return new BankPickupPlan(items, bankItemIds);
	}

	/**
	 * The result of {@link #bankPickupPlan} or {@link #targetPickupPlan}:
	 * the pickup items (id to quantity; {@code null} when the
	 * bank cannot fully supply the transport) and the bank item ids to highlight.
	 */
	public static final class BankPickupPlan
	{
		public final Map<Integer, Long> items;
		public final Set<Integer> bankItemIds;

		private BankPickupPlan(Map<Integer, Long> items, Set<Integer> bankItemIds)
		{
			this.items = items;
			this.bankItemIds = bankItemIds;
		}
	}

	/**
	 * Returns true if the player already meets this requirement on its own, with enough of
	 * one item variant of any OR branch at that branch's quantity, or with a staff or
	 * offhand that substitutes for it. An unlock branch is met by declaring its unlock;
	 * it can never be covered by items, so it never contributes a pickup.
	 */
	private static boolean playerSatisfies(ItemRequirement req, Map<Integer, Integer> playerHas,
		Set<Unlock> unlocks)
	{
		for (ItemRequirement.Branch branch : req.getBranches())
		{
			if (branch.getUnlock() != null)
			{
				if (unlocks.contains(branch.getUnlock()))
				{
					return true;
				}
				continue;
			}
			if (findCovering(branch.getItemIds(), pickupQuantity(branch), Map.of(), playerHas) != -1)
			{
				return true;
			}
		}
		return findCovering(req.getStaffIds(), 1, Map.of(), playerHas) != -1
			|| findCovering(req.getOffhandIds(), 1, Map.of(), playerHas) != -1;
	}

	/**
	 * Returns true if {@code source} holds enough of {@code id} to make up what {@code carried}
	 * lacks of {@code requiredQty}.
	 */
	private static boolean covers(int id, int requiredQty, Map<Integer, Integer> carried, Map<Integer, Integer> source)
	{
		return source.getOrDefault(id, 0) >= requiredQty - carried.getOrDefault(id, 0);
	}

	/**
	 * Returns the first ID in {@code itemIds} that {@code source} {@link #covers covers}, or -1 if none does.
	 * Item variations list the pure item first, so it is preferred over combination variants.
	 */
	private static int findCovering(int[] itemIds, int requiredQty, Map<Integer, Integer> carried, Map<Integer, Integer> source)
	{
		if (itemIds == null)
		{
			return -1;
		}
		for (int id : itemIds)
		{
			if (covers(id, requiredQty, carried, source))
			{
				return id;
			}
		}
		return -1;
	}

	/**
	 * Returns the first ID in {@code itemIds} that the player already carries some of and that
	 * {@code source} {@link #covers covers}, or -1 if none does.
	 */
	private static int findCarriedCovering(int[] itemIds, int requiredQty, Map<Integer, Integer> carried,
		Map<Integer, Integer> source)
	{
		if (itemIds == null)
		{
			return -1;
		}
		for (int id : itemIds)
		{
			if (carried.getOrDefault(id, 0) > 0 && covers(id, requiredQty, carried, source))
			{
				return id;
			}
		}
		return -1;
	}

	/**
	 * Adds every ID in {@code itemIds} that {@code source} {@link #covers covers} to {@code out}.
	 */
	private static void addCovering(int[] itemIds, int requiredQty, Map<Integer, Integer> carried,
		Map<Integer, Integer> source, Set<Integer> out)
	{
		if (itemIds == null)
		{
			return;
		}
		for (int id : itemIds)
		{
			if (covers(id, requiredQty, carried, source))
			{
				out.add(id);
			}
		}
	}

	/**
	 * Returns the quantity an OR branch asks for: the branch quantity when that is
	 * positive, otherwise 1.
	 */
	private static int pickupQuantity(ItemRequirement.Branch branch)
	{
		return branch.getQuantity() > 0 ? branch.getQuantity() : 1;
	}

	/**
	 * Returns what the player carries plus the bank rune pouch's runes, if the pouch is taken.
	 * The pouch is taken when, for at least one requirement the player doesn't already meet,
	 * either the pouch alone covers the shortfall of any OR branch at that branch's quantity,
	 * or loose bank items alone cover the shortfall of no OR branch but the pouch and loose
	 * bank items together cover the shortfall of one of them (counted per item ID, never
	 * across variants).
	 * Otherwise the pouch is not taken and {@code playerHas} itself is returned.
	 */
	private static Map<Integer, Integer> carriedWithBankPouch(Transport transport,
		Map<Integer, Integer> playerHas,
		Map<Integer, Integer> bankHas,
		Map<Integer, Integer> bankPouchRunes,
		Set<Unlock> unlocks)
	{
		// Pouch runes plus loose bank items, per item ID.
		Map<Integer, Integer> pouchAndBank = new HashMap<>(bankHas);
		bankPouchRunes.forEach((runeId, amount) -> pouchAndBank.merge(runeId, amount, Integer::sum));
		for (ItemRequirement req : transport.getItemRequirements().getRequirements())
		{
			if (playerSatisfies(req, playerHas, unlocks))
			{
				continue;
			}
			boolean pouchAlone = false;
			boolean looseAlone = false;
			boolean combined = false;
			for (ItemRequirement.Branch branch : req.getBranches())
			{
				int qty = pickupQuantity(branch);
				pouchAlone = pouchAlone || findCovering(branch.getItemIds(), qty, playerHas, bankPouchRunes) != -1;
				looseAlone = looseAlone || findCovering(branch.getItemIds(), qty, playerHas, bankHas) != -1;
				combined = combined || findCovering(branch.getItemIds(), qty, playerHas, pouchAndBank) != -1;
			}
			if (pouchAlone || (!looseAlone && combined))
			{
				Map<Integer, Integer> carried = new HashMap<>(playerHas);
				bankPouchRunes.forEach((runeId, amount) -> carried.merge(runeId, amount, Integer::sum));
				return carried;
			}
		}
		return playerHas;
	}
}

package shortestpath.requirement.model;

import java.util.*;
import lombok.Getter;
import net.runelite.api.Quest;

/**
 * Optional access requirements for a destination tile (e.g. bank booths). Empty requirements mean
 * the destination is always usable when reached.
 */
public final class DestinationRequirements
{
	/**
	 * All-zero skill array; no skill requirements.
	 */
	public static final DestinationRequirements EMPTY = new DestinationRequirements();

	@Getter
	private final SkillLevels skillLevels;
	@Getter
	private final Set<Quest> quests;
	@Getter
	private final Set<VarRequirement> varbits;
	@Getter
	private final Set<VarRequirement> varPlayers;

	private DestinationRequirements()
	{
		this.skillLevels = SkillLevels.NONE;
		this.quests = Collections.emptySet();
		this.varbits = Collections.emptySet();
		this.varPlayers = Collections.emptySet();
	}

	public DestinationRequirements(
		SkillLevels skillLevels,
		Set<Quest> quests,
		Set<VarRequirement> varbits,
		Set<VarRequirement> varPlayers)
	{
		this.skillLevels = skillLevels != null ? skillLevels : SkillLevels.NONE;
		this.quests = quests != null ? quests : Collections.emptySet();
		this.varbits = varbits != null ? varbits : Collections.emptySet();
		this.varPlayers = varPlayers != null ? varPlayers : Collections.emptySet();
	}

	/**
	 * @return a merged requirement when the same tile appears on multiple rows (max skills, union sets).
	 */
	public static DestinationRequirements merge(DestinationRequirements a, DestinationRequirements b)
	{
		if (a == null || a.isEmpty())
		{
			return b != null ? b : EMPTY;
		}
		if (b == null || b.isEmpty())
		{
			return a;
		}
		SkillLevels skills = SkillLevels.merge(a.skillLevels, b.skillLevels);
		Set<Quest> q = new HashSet<>(a.quests);
		q.addAll(b.quests);
		Set<VarRequirement> vb = new HashSet<>(a.varbits);
		vb.addAll(b.varbits);
		Set<VarRequirement> vp = new HashSet<>(a.varPlayers);
		vp.addAll(b.varPlayers);
		return new DestinationRequirements(skills, q, vb, vp);
	}

	public boolean isEmpty()
	{
		if (!quests.isEmpty())
		{
			return false;
		}
		if (!varbits.isEmpty() || !varPlayers.isEmpty())
		{
			return false;
		}
		return skillLevels.isEmpty();
	}
}

package shortestpath.requirement.model;

import java.util.*;

import lombok.*;
import shortestpath.Util;

/**
 * Represents an item requirement with its variations and quantity.
 * For example: AIR_RUNE=3 where AIR_RUNE can be substituted by DUST_RUNE,
 * SMOKE_RUNE, etc.
 * OR alternatives are kept as separate {@link Branch branches} with their own
 * quantities, for example SHANTAY_PASS=1|COINS=5 is satisfied by one Shantay
 * pass or by 5 coins.
 */
@Getter
@EqualsAndHashCode(onlyExplicitlyIncluded = true)
public final class ItemRequirement
{
	/**
	 * One {@code NAME=quantity} alternative of an OR group. Its itemIds are
	 * that item's variation ids.
	 */
	@Getter
	@EqualsAndHashCode
	public static final class Branch
	{
		private final int[] itemIds;
		private final int[] staffIds;
		private final int[] offhandIds;
		private final int quantity;
		/**
		 * The declared unlock this branch references, or {@code null} for a
		 * regular item branch. An unlock branch carries no item ids, so its
		 * {@link #itemIds} is always {@code null}.
		 */
		private final Unlock unlock;

		public Branch(int[] itemIds, int[] staffIds, int[] offhandIds, int quantity)
		{
			this(itemIds, staffIds, offhandIds, quantity, null);
		}

		public Branch(int[] itemIds, int[] staffIds, int[] offhandIds, int quantity, Unlock unlock)
		{
			this.itemIds = itemIds == null ? null : itemIds.clone();
			this.staffIds = staffIds == null ? null : staffIds.clone();
			this.offhandIds = offhandIds == null ? null : offhandIds.clone();
			this.quantity = quantity;
			this.unlock = unlock;
		}

		// The array fields are shared requirement data; hand out copies so a
		// stray write through a getter cannot corrupt it for every config.

		public int[] getItemIds()
		{
			return itemIds == null ? null : itemIds.clone();
		}

		public int[] getStaffIds()
		{
			return staffIds == null ? null : staffIds.clone();
		}

		public int[] getOffhandIds()
		{
			return offhandIds == null ? null : offhandIds.clone();
		}

		/**
		 * An unlock-only branch carries no item ids and can only be satisfied
		 * by declaring its unlock; no item can ever cover it.
		 */
		public boolean isUnlockOnly()
		{
			return itemIds == null && unlock != null;
		}

		/**
		 * Any unblocked item, staff or offhand id keeps the branch alive; a
		 * branch carrying no ids at all — an unlock alternative — can never
		 * be blocked.
		 */
		public boolean hasUnblockedId(Set<Integer> blockedIds)
		{
			boolean hasIds = false;
			for (int[] ids : new int[][]{itemIds, staffIds, offhandIds})
			{
				if (ids == null)
				{
					continue;
				}
				for (int itemId : ids)
				{
					hasIds = true;
					if (!blockedIds.contains(itemId))
					{
						return true;
					}
				}
			}
			return !hasIds;
		}

		/**
		 * Any item id that is not option-blocked at {@code packedDest} keeps
		 * the branch alive: an id whose representative lookup is negative is
		 * not a family member and can never be option-blocked; a member id
		 * survives when its representative's blocked set lacks this
		 * destination. Staff and offhand ids do not participate — they are
		 * substitutes, not the family's served items. A branch carrying no
		 * item ids at all — an unlock alternative — can never be blocked.
		 */
		public boolean hasUnblockedOptionId(int packedDest, Map<Integer, Integer> repIndex,
			Map<Integer, Set<Integer>> blockedDests)
		{
			boolean hasIds = false;
			if (itemIds != null)
			{
				for (int itemId : itemIds)
				{
					hasIds = true;
					Integer rep = repIndex.get(itemId);
					if (rep == null)
					{
						return true;
					}
					Set<Integer> dests = blockedDests.get(rep);
					if (dests == null || !dests.contains(packedDest))
					{
						return true;
					}
				}
			}
			return !hasIds;
		}
	}

	/**
	 * The OR alternatives of this requirement, in declaration order, each with
	 * its own quantity. A requirement without OR alternatives has one branch.
	 */
	@EqualsAndHashCode.Include
	private final List<Branch> branches;

	/**
	 * The item IDs that satisfy this requirement (variations of every OR branch)
	 */
	private final int[] itemIds;

	/**
	 * Staff IDs that can substitute runes for this requirement
	 */
	private final int[] staffIds;

	/**
	 * Offhand IDs that can substitute for this requirement
	 */
	private final int[] offhandIds;

	/**
	 * The largest quantity any branch requires; kept for callers that predate
	 * per-branch quantities (e.g. external report tooling). OR branches can
	 * need different quantities, so satisfaction logic must use
	 * {@link #getBranches()}.
	 */
	private final int quantity;

	public ItemRequirement(int[] itemIds, int[] staffIds, int[] offhandIds, int quantity)
	{
		this(List.of(new Branch(itemIds, staffIds, offhandIds, quantity)));
	}

	public ItemRequirement(List<Branch> branches)
	{
		if (branches == null || branches.isEmpty())
		{
			throw new IllegalArgumentException("An item requirement needs at least one branch");
		}
		this.branches = List.copyOf(branches);
		int maxQuantity = -1;
		int[][] itemIdArrays = new int[this.branches.size()][];
		int[][] staffIdArrays = new int[this.branches.size()][];
		int[][] offhandIdArrays = new int[this.branches.size()][];
		for (int i = 0; i < this.branches.size(); i++)
		{
			Branch branch = this.branches.get(i);
			itemIdArrays[i] = branch.getItemIds();
			staffIdArrays[i] = branch.getStaffIds();
			offhandIdArrays[i] = branch.getOffhandIds();
			maxQuantity = Math.max(maxQuantity, branch.getQuantity());
		}
		if (this.branches.size() == 1)
		{
			Branch only = this.branches.get(0);
			this.itemIds = only.getItemIds();
			this.staffIds = only.getStaffIds();
			this.offhandIds = only.getOffhandIds();
		}
		else
		{
			this.itemIds = Util.concatenate(itemIdArrays);
			this.staffIds = Util.concatenate(staffIdArrays);
			this.offhandIds = Util.concatenate(offhandIdArrays);
		}
		this.quantity = maxQuantity;
	}

	// The array fields are the requirement's own state; hand out copies so a
	// stray write through a getter cannot corrupt shared requirement data.

	public int[] getItemIds()
	{
		return itemIds == null ? null : itemIds.clone();
	}

	public int[] getStaffIds()
	{
		return staffIds == null ? null : staffIds.clone();
	}

	public int[] getOffhandIds()
	{
		return offhandIds == null ? null : offhandIds.clone();
	}

	/**
	 * A pure-unlock requirement consists only of unlock branches: it is
	 * satisfied by declaring any one of them and can never be covered by
	 * items, staves or offhands. Item evaluation is not the only gate for
	 * such requirements, since teleportation-item modes can skip item
	 * evaluation entirely.
	 */
	public boolean isPureUnlock()
	{
		for (Branch branch : branches)
		{
			if (!branch.isUnlockOnly())
			{
				return false;
			}
		}
		return true;
	}

	/**
	 * Whether this requirement keeps at least one OR alternative once the
	 * player-blocked item ids are removed: a branch survives on any unblocked
	 * item, staff or offhand id, and a branch carrying no ids at all — an
	 * unlock alternative — can never be blocked. This is a structural property
	 * of the requirement, independent of what the player owns.
	 */
	public boolean hasUnblockedAlternative(Set<Integer> blockedIds)
	{
		for (Branch branch : branches)
		{
			if (branch.hasUnblockedId(blockedIds))
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Whether this requirement keeps at least one OR alternative that is not
	 * option-blocked at {@code packedDest}: a branch survives on an item id
	 * whose family representative lookup is negative (a non-family item can
	 * never be option-blocked) or whose representative's blocked-destination
	 * set does not contain {@code packedDest}. Staff and offhand substitutes
	 * do not participate — they carry ids from unrelated items. Structural
	 * like {@link #hasUnblockedAlternative}, independent of what the player
	 * owns.
	 */
	public boolean hasUnoptionBlockedAlternative(int packedDest,
		Map<Integer, Integer> repIndex, Map<Integer, Set<Integer>> blockedDests)
	{
		for (Branch branch : branches)
		{
			if (branch.hasUnblockedOptionId(packedDest, repIndex, blockedDests))
			{
				return true;
			}
		}
		return false;
	}
}

