package shortestpath.requirement.model;

import java.util.Arrays;
import net.runelite.api.Skill;
import shortestpath.requirement.RejectionReason;
import lombok.*;

/**
 * Immutable skill-level set in the extended-index layout: one slot per
 * {@link Skill} ordinal plus four trailing slots for total level, combat
 * level, quest points and music unlocks. The same type carries requirement data (what a
 * transport or bank tile demands) and player data (what the refresh
 * snapshot captured), so the two sides can never disagree about the
 * layout. The backing array is the TSV wire contract and never escapes
 * this type.
 */
@AllArgsConstructor
@EqualsAndHashCode
public final class SkillLevels
{
	/**
	 * The {@code Max} cell sentinel: a requirement parsed as "Max" resolves
	 * per index through {@link #maximumLevel} instead of naming a fixed
	 * cap. Deliberately not a level — the trailing slots cap differently.
	 */
	public static final int MAX_LEVEL = Integer.MAX_VALUE;

	public static final int LENGTH = Skill.values().length + 4;
	public static final int TOTAL_LEVEL_INDEX = Skill.values().length;
	public static final int COMBAT_LEVEL_INDEX = Skill.values().length + 1;
	public static final int QUEST_POINTS_INDEX = Skill.values().length + 2;
	public static final int MUSIC_TRACKS_INDEX = Skill.values().length + 3;

	private static final int MAX_SKILL_LEVEL = 99;
	private static final int MAX_COMBAT_LEVEL = 126;

	/**
	 * The shared all-zero set. Most transports declare no skills, so they
	 * all point at this instance rather than each allocating an array.
	 */
	public static final SkillLevels NONE = new SkillLevels(new int[LENGTH]);

	private final int[] levels;

	/**
	 * Wraps a raw extended-index array into an immutable set. The input is
	 * cloned — later mutation of the source cannot move the value — and
	 * normalised to {@link #LENGTH} (short input zero-pads the tail, which
	 * is how a shorter requirement set declares nothing for the missing
	 * indices). Null and all-zero input compact onto {@link #NONE}, so
	 * requirement-free callers share one instance.
	 */
	public static SkillLevels of(int[] levels)
	{
		if (levels == null)
		{
			return NONE;
		}
		int[] copy = new int[LENGTH];
		boolean any = false;
		for (int i = 0; i < levels.length; i++)
		{
			if (i < LENGTH)
			{
				copy[i] = levels[i];
			}
			if (levels[i] != 0)
			{
				any = true;
			}
		}
		return any ? new SkillLevels(copy) : NONE;
	}

	public int get(int index)
	{
		return levels[index];
	}

	public int get(Skill skill)
	{
		return levels[skill.ordinal()];
	}

	public int totalLevel()
	{
		return levels[TOTAL_LEVEL_INDEX];
	}

	public int combatLevel()
	{
		return levels[COMBAT_LEVEL_INDEX];
	}

	public int length()
	{
		return levels.length;
	}

	/**
	 * Debug-only copy of the backing array; the internal array never
	 * escapes — hot paths read through {@link #get(int)}.
	 */
	public int[] toArray()
	{
		return levels.clone();
	}

	/**
	 * Whether every slot reads zero — the no-requirement / nothing-captured
	 * shape.
	 */
	public boolean isEmpty()
	{
		for (int level : levels)
		{
			if (level != 0)
			{
				return false;
			}
		}
		return true;
	}

	/**
	 * Elementwise maximum of two requirement sets; the empty arm hands back
	 * the other side without allocating.
	 */
	public static SkillLevels merge(SkillLevels a, SkillLevels b)
	{
		if (a == null || a.isEmpty())
		{
			return b != null ? b : NONE;
		}
		if (b == null || b.isEmpty())
		{
			return a;
		}
		int[] merged = new int[LENGTH];
		for (int i = 0; i < LENGTH; i++)
		{
			merged[i] = Math.max(a.levels[i], b.levels[i]);
		}
		return new SkillLevels(merged);
	}

	/**
	 * The level a {@code Max} requirement resolves to at the given index:
	 * 99 for the skill ordinals, the all-99 total, 126 for combat, the
	 * refresh-state quest-point and music caps for their slots, and the sentinel
	 * itself anywhere else (an index outside the layout declares no cap).
	 * The quest and music caps arrive as parameters because they change
	 * between refreshes — constants here would go stale.
	 */
	public static int maximumLevel(int index, int currentMaxQuestPoints, int currentMaxMusicTracks)
	{
		if (index < TOTAL_LEVEL_INDEX)
		{
			return MAX_SKILL_LEVEL;
		}
		if (index == TOTAL_LEVEL_INDEX)
		{
			return MAX_SKILL_LEVEL * Skill.values().length;
		}
		if (index == COMBAT_LEVEL_INDEX)
		{
			return MAX_COMBAT_LEVEL;
		}
		if (index == QUEST_POINTS_INDEX)
		{
			return currentMaxQuestPoints;
		}
		if (index == MUSIC_TRACKS_INDEX)
		{
			return currentMaxMusicTracks;
		}
		return MAX_LEVEL;
	}

	/**
	 * The skill gate: the first requirement this set fails, or
	 * {@link RejectionReason#NONE} when every slot is met. Iterates this
	 * (player) set; in seasonal leagues the total-level slot is skipped
	 * because some skills are disabled and the reachable total is lower —
	 * holding the item (e.g. Max cape) already proves the player is maxed
	 * for the available skills. A requirement slot reading
	 * {@link #MAX_LEVEL} resolves through {@link #maximumLevel} per index.
	 * Runs allocation-free on the check path.
	 */
	public RejectionReason missingRequirement(SkillLevels required, boolean skipTotalLevel,
		int currentMaxQuestPoints, int currentMaxMusicTracks)
	{
		if (required == null)
		{
			return RejectionReason.NONE;
		}
		for (int i = 0; i < levels.length; i++)
		{
			if (skipTotalLevel && i == TOTAL_LEVEL_INDEX)
			{
				continue;
			}
			int level = levels[i];
			// A shorter requirement set declares no level for the missing
			// indices — read 0 rather than throwing.
			int requiredLevel = i < required.levels.length ? required.levels[i] : 0;
			if (requiredLevel == MAX_LEVEL)
			{
				requiredLevel = maximumLevel(i, currentMaxQuestPoints, currentMaxMusicTracks);
			}
			if (level < requiredLevel)
			{
				return RejectionReason.SKILL_LEVEL;
			}
		}
		return RejectionReason.NONE;
	}

	@Override
	public String toString()
	{
		return Arrays.toString(levels);
	}
}

package shortestpath.requirement.model;

import java.util.*;

import lombok.*;
import net.runelite.api.gameval.ItemID;

/**
 * Represents all item requirements for a transport.
 * All requirements must be satisfied.
 */
@Getter
@EqualsAndHashCode
public final class TransportItems
{
	/**
	 * Item ids treated as spendable currency by {@link #isSatisfiedBy}: a branch priced
	 * in one of these counts only when the price is within the configured currency
	 * threshold.
	 */
	public static final Set<Integer> CURRENCIES = Set.of(
		ItemID.COINS, ItemID.VILLAGE_TRADE_STICKS, ItemID.ECTOTOKEN, ItemID.WARGUILD_TOKENS);

	private final List<ItemRequirement> requirements;

	public TransportItems(List<ItemRequirement> requirements)
	{
		this.requirements = List.copyOf(requirements);
	}

	/**
	 * Creates TransportItems from legacy array format for backwards compatibility.
	 */
	public TransportItems(int[][] items, int[][] staves, int[][] offhands, int[] quantities)
	{
		List<ItemRequirement> reqs = new ArrayList<>();
		for (int i = 0; i < items.length; i++)
		{
			reqs.add(new ItemRequirement(
				items[i],
				staves != null && i < staves.length ? staves[i] : new int[0],
				offhands != null && i < offhands.length ? offhands[i] : new int[0],
				quantities[i]));
		}
		this.requirements = Collections.unmodifiableList(reqs);
	}

	/**
	 * Whether every ANDed requirement retains an unblocked OR alternative —
	 * the transport-set gate for player-declared per-item restrictions. A
	 * transport drops out of consideration only when some requirement's last
	 * alternative is blocked; blocking one variant of an OR group leaves the
	 * rest routable. Satisfaction and ownership are separate questions
	 * answered by {@link #isSatisfiedBy}.
	 */
	public boolean survivesBlockedItems(Set<Integer> blockedIds)
	{
		if (blockedIds.isEmpty())
		{
			return true;
		}
		for (ItemRequirement req : requirements)
		{
			if (!req.hasUnblockedAlternative(blockedIds))
			{
				return false;
			}
		}
		return true;
	}

	/**
	 * Whether every ANDed requirement retains an OR branch that is not
	 * option-blocked at {@code packedDest} — the destination-scoped sibling
	 * of {@link #survivesBlockedItems}. An empty {@code blockedDests} map
	 * means nothing is option-blocked anywhere; otherwise every requirement
	 * must keep at least one branch whose item ids do not all resolve to a
	 * blocked (representative, destination) pair.
	 */
	public boolean survivesOptionBlocks(int packedDest,
		Map<Integer, Integer> repIndex, Map<Integer, Set<Integer>> blockedDests)
	{
		if (blockedDests.isEmpty())
		{
			return true;
		}
		for (ItemRequirement req : requirements)
		{
			if (!req.hasUnoptionBlockedAlternative(packedDest, repIndex, blockedDests))
			{
				return false;
			}
		}
		return true;
	}

	/**
	 * Merges two TransportItems, combining all requirements from both.
	 * If either is null, returns the other.
	 */
	public static TransportItems merge(TransportItems first, TransportItems second)
	{
		if (first == null)
		{
			return second;
		}
		if (second == null)
		{
			return first;
		}
		List<ItemRequirement> merged = new ArrayList<>();
		merged.addAll(first.requirements);
		merged.addAll(second.requirements);
		return new TransportItems(merged);
	}

	/**
	 * Gets the number of item requirements.
	 */
	public int size()
	{
		return requirements.size();
	}

	/**
	 * Returns whether the player can satisfy every item requirement at once.
	 *
	 * <p>Runes (and other counted items) are applied first, then at most one offhand
	 * (tome), then at most one staff. Combination staves may cover multiple leftover
	 * rune types because the same item id appears in more than one staff list. Two
	 * different staves cannot be used together.
	 */
	public boolean isSatisfiedBy(Map<Integer, Integer> itemCounts, Set<Integer> currencies, int currencyThreshold)
	{
		return isSatisfiedBy(itemCounts, currencies, currencyThreshold, Set.of());
	}

	/**
	 * As {@link #isSatisfiedBy(Map, Set, int)}, with an additional set of
	 * player-declared {@link Unlock unlocks}. An unlock branch of an OR group
	 * is satisfied when its unlock is declared; it never relieves item terms
	 * of other branches and is never covered by items, staves or offhands.
	 */
	public boolean isSatisfiedBy(Map<Integer, Integer> itemCounts, Set<Integer> currencies, int currencyThreshold, Set<Unlock> unlocks)
	{
		if (requirements.isEmpty())
		{
			return true;
		}

		List<ItemRequirement> leftover = new ArrayList<>();
		boolean usedOffhand = false;
		for (ItemRequirement req : requirements)
		{
			Boolean itemsResult = satisfiedByItems(req, itemCounts, currencies, currencyThreshold, unlocks);
			if (itemsResult == null)
			{
				return false;
			}
			if (itemsResult)
			{
				continue;
			}
			if (!usedOffhand && hasOwnedOffhand(req, itemCounts))
			{
				usedOffhand = true;
				continue;
			}
			leftover.add(req);
		}

		if (leftover.isEmpty())
		{
			return true;
		}
		return existsOneStaffCovering(leftover, itemCounts);
	}

	/**
	 * {@code true} if counted items pay this requirement through any OR branch at that
	 * branch's quantity, {@code false} if not, {@code null} if the player has the items
	 * but every covering branch exceeds the currency threshold. A satisfied branch wins
	 * over a blocked one, whatever their order.
	 */
	private static Boolean satisfiedByItems(
		ItemRequirement req,
		Map<Integer, Integer> itemCounts,
		Set<Integer> currencies,
		int currencyThreshold,
		Set<Unlock> unlocks)
	{
		boolean blocked = false;
		for (ItemRequirement.Branch branch : req.getBranches())
		{
			Unlock unlock = branch.getUnlock();
			if (unlock != null)
			{
				if (unlocks.contains(unlock))
				{
					return true;
				}
				continue;
			}

			int[] itemIds = branch.getItemIds();
			if (itemIds == null)
			{
				continue;
			}
			for (int itemId : itemIds)
			{
				if (!hasQuantity(itemCounts, itemId, branch.getQuantity(), false))
				{
					continue;
				}
				if (currencies != null && currencies.contains(itemId) && branch.getQuantity() > currencyThreshold)
				{
					blocked = true;
					break;
				}
				return true;
			}
		}
		return blocked ? null : false;
	}

	/**
	 * {@code true} when any OR branch has an owned offhand id at that branch's quantity.
	 */
	private static boolean hasOwnedOffhand(ItemRequirement req, Map<Integer, Integer> itemCounts)
	{
		for (ItemRequirement.Branch branch : req.getBranches())
		{
			if (hasOwnedSubstitute(branch.getOffhandIds(), itemCounts, branch.getQuantity(), true))
			{
				return true;
			}
		}
		return false;
	}

	private static boolean existsOneStaffCovering(List<ItemRequirement> leftover, Map<Integer, Integer> itemCounts)
	{
		Set<Integer> candidates = null;
		for (ItemRequirement req : leftover)
		{
			Set<Integer> ownedStaves = new HashSet<>();
			for (ItemRequirement.Branch branch : req.getBranches())
			{
				ownedStaves.addAll(ownedIds(branch.getStaffIds(), itemCounts, branch.getQuantity(), true));
			}
			if (ownedStaves.isEmpty())
			{
				return false;
			}
			if (candidates == null)
			{
				candidates = ownedStaves;
			}
			else
			{
				candidates.retainAll(ownedStaves);
			}
			if (candidates.isEmpty())
			{
				return false;
			}
		}
		return true;
	}

	private static boolean hasOwnedSubstitute(int[] ids, Map<Integer, Integer> itemCounts, int requiredQuantity, boolean unlimited)
	{
		return !ownedIds(ids, itemCounts, requiredQuantity, unlimited).isEmpty();
	}

	private static Set<Integer> ownedIds(int[] ids, Map<Integer, Integer> itemCounts, int requiredQuantity, boolean unlimited)
	{
		if (ids == null || ids.length == 0)
		{
			return Set.of();
		}
		Set<Integer> owned = new HashSet<>();
		for (int itemId : ids)
		{
			if (hasQuantity(itemCounts, itemId, requiredQuantity, unlimited))
			{
				owned.add(itemId);
			}
		}
		return owned;
	}

	private static boolean hasQuantity(Map<Integer, Integer> itemCounts, int itemId, int requiredQuantity, boolean unlimited)
	{
		int quantity = itemCounts.getOrDefault(itemId, 0);
		if (unlimited)
		{
			return requiredQuantity > 0 && quantity >= 1 || requiredQuantity == 0 && quantity == 0;
		}
		return requiredQuantity > 0 && quantity >= requiredQuantity || requiredQuantity == 0 && quantity == 0;
	}

	// Legacy getters for backwards compatibility. They emit one row per OR
	// branch, in requirement order and then branch order; a requirement
	// without OR alternatives still gives one row. Use size() or
	// getRequirements() to count AND groups.
	private int branchCount()
	{
		int n = 0;
		for (ItemRequirement req : requirements)
		{
			n += req.getBranches().size();
		}
		return n;
	}

	public int[][] getItems()
	{
		int[][] items = new int[branchCount()][];
		int i = 0;
		for (ItemRequirement req : requirements)
		{
			for (ItemRequirement.Branch branch : req.getBranches())
			{
				// Unlock-only branches carry no item ids; emit an empty array so
				// consumers iterating alternatives never dereference a null.
				int[] itemIds = branch.getItemIds();
				items[i++] = itemIds == null ? new int[0] : itemIds;
			}
		}
		return items;
	}

	public int[][] getStaves()
	{
		int[][] staves = new int[branchCount()][];
		int i = 0;
		for (ItemRequirement req : requirements)
		{
			for (ItemRequirement.Branch branch : req.getBranches())
			{
				staves[i++] = branch.getStaffIds();
			}
		}
		return staves;
	}

	public int[][] getOffhands()
	{
		int[][] offhands = new int[branchCount()][];
		int i = 0;
		for (ItemRequirement req : requirements)
		{
			for (ItemRequirement.Branch branch : req.getBranches())
			{
				offhands[i++] = branch.getOffhandIds();
			}
		}
		return offhands;
	}

	public int[] getQuantities()
	{
		int[] quantities = new int[branchCount()];
		int i = 0;
		for (ItemRequirement req : requirements)
		{
			for (ItemRequirement.Branch branch : req.getBranches())
			{
				quantities[i++] = branch.getQuantity();
			}
		}
		return quantities;
	}

	private String toString(int[][] array)
	{
		StringBuilder text = new StringBuilder();
		for (int[] inner : array)
		{
			text.append((text.length() == 0) ? "" : ", ").append(Arrays.toString(inner));
		}
		return "[" + text + "]";
	}

	@Override
	public String toString()
	{
		return "[" +
			toString(getItems()) + ", " +
			toString(getStaves()) + ", " +
			toString(getOffhands()) + ", " +
			Arrays.toString(getQuantities()) + "]";
	}
}

package shortestpath.requirement.model;

/**
 * Detected or player-declared unlock states,
 * referenced by {@code UNLOCK_<NAME>=1} tokens in transport Items cells.
 * An unlock branch satisfies a requirement through account state alone: it never
 * contributes items and is never covered by inventory, staff or offhand ids.
 * An unlock alternative inside an OR group acts as a relief
 * ({@code AXE=1|UNLOCK_CANOE_AXE=1}), while an ANDed pure-unlock requirement
 * acts as a gate ({@code 13393=1&UNLOCK_XERICS_HONOUR=1}).
 */
public enum Unlock
{
	/**
	 * An axe stored at a canoe station, usable instead of a carried axe.
	 */
	CANOE_AXE,

	/**
	 * Dragontooth Island free passage, paying no ecto-token toll.
	 */
	DRAGONTOOTH,

	/**
	 * Xeric's Honour, unlocking the talisman teleports.
	 */
	XERICS_HONOUR,

	/**
	 * Free hardwood grove entry, detected from Karamja elite diary completion.
	 */
	KARAMJA_ELITE,

	/**
	 * Permanent access to Mor Ul Rek's inner city after showing a fire cape.
	 */
	MOR_UL_REK,

	/**
	 * Logs deposited in a balloon route's destination basket, which the pilot
	 * consumes per destination (regular, oak, willow, yew or magic). The
	 * stored stack is not exposed to the client, so the player declares it
	 * per route through the {@code balloonLogBasketRoutes} config set — the
	 * unlock is granted only to a transport whose destination is one of the
	 * selected routes, never globally.
	 */
	BALLOON_LOG_BASKET,
	;

	private static final String TOKEN_PREFIX = "UNLOCK_";

	/**
	 * Resolves an {@code UNLOCK_<NAME>} token to its unlock, or {@code null}
	 * when the token does not name a known unlock. Callers that accept the
	 * token class must fail loudly on {@code null} so that a typo'd unlock
	 * name can never silently drop a requirement.
	 */
	public static Unlock fromName(String name)
	{
		if (name == null || !name.startsWith(TOKEN_PREFIX))
		{
			return null;
		}
		try
		{
			return Unlock.valueOf(name.substring(TOKEN_PREFIX.length()));
		}
		catch (IllegalArgumentException e)
		{
			return null;
		}
	}
}

package shortestpath.requirement.model;

import lombok.Getter;

/**
 * The type of comparison to perform when checking a variable requirement.
 */
@Getter
public enum VarCheckType
{
	BIT_SET("&"),
	COOLDOWN_MINUTES("@"),
	EQUAL("="),
	GREATER(">"),
	SMALLER("<");

	private final String code;

	VarCheckType(String code)
	{
		this.code = code;
	}
}

package shortestpath.requirement.model;

import java.util.Map;

import lombok.*;

/**
 * Represents a variable-based requirement for a transport.
 * This can be either a varbit or a varplayer requirement.
 *
 * <p>
 * Consolidates the previously separate TransportVarbit and TransportVarPlayer
 * classes which had identical logic.
 * </p>
 */
@AllArgsConstructor
@Getter
@EqualsAndHashCode
public final class VarRequirement
{

	private final VarType varType;
	private final int id;
	private final int value;
	private final VarCheckType checkType;

	/**
	 * Checks if this requirement is satisfied given the current variable values.
	 *
	 * @param values A map of variable IDs to their current values
	 * @param currentTimeMinutes current game time in minutes
	 * @return true if the requirement is satisfied
	 */
	public boolean check(Map<Integer, Integer> values, long currentTimeMinutes)
	{
		Integer currentValue = values.get(id);
		if (currentValue == null)
		{
			return false;
		}
		return checkValue(currentValue, currentTimeMinutes);
	}

	/**
	 * Same logic as {@link #check(Map, long)} but with the variable value already resolved (e.g. from the client).
	 *
	 * @param currentTimeMinutes current game time in minutes
	 */
	public boolean checkValue(int currentValue, long currentTimeMinutes)
	{
		switch (checkType)
		{
			case EQUAL:
				return currentValue == value;
			case GREATER:
				return currentValue > value;
			case SMALLER:
				return currentValue < value;
			case BIT_SET:
				return (currentValue & value) > 0;
			case COOLDOWN_MINUTES:
				return (currentTimeMinutes - (long) currentValue) > value;
			default:
				return false;
		}
	}

	public boolean isVarbit()
	{
		return varType == VarType.VARBIT;
	}

	public boolean isVarPlayer()
	{
		return varType == VarType.VARPLAYER;
	}

	@Override
	public String toString()
	{
		return varType + "[" + id + " " + checkType.getCode() + " " + value + "]";
	}

	/**
	 * The type of variable this requirement checks.
	 */
	public enum VarType
	{
		VARBIT,
		VARPLAYER
	}
}

package shortestpath.sailing;

import java.util.*;

import lombok.Getter;

import shortestpath.settings.Effect;

/**
 * An immutable fact describing a single sailing-state change: the input that
 * changed (keyed as {@code "varbit:<id>"} for one of the four sailing varbits)
 * and the {@link Effect}s it triggers. Produced by {@link SailingService};
 * the shell reads the effect set to decide which follow-up actions to run
 * rather than re-deriving them from the event.
 *
 * <p>Sailing only ever emits {@link Effect#ROUTE_INVALIDATING}: ordinary boat
 * movement — position, pivot, heading — is filtered out before a fact is
 * minted, so a declared fact always means "the route's sailing inputs
 * changed" and never merely "the boat moved".
 */
@Getter
public final class SailingChange
{
	private final String key;
	private final Set<Effect> effects;

	SailingChange(String key, Set<Effect> effects)
	{
		this.key = Objects.requireNonNull(key);
		this.effects = Set.copyOf(effects);
	}
}

package shortestpath.sailing;

import java.util.Set;

import javax.inject.*;

import lombok.*;

import net.runelite.api.*;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.gameval.VarbitID;
import shortestpath.WorldPointUtil;
import shortestpath.requirement.*;
import shortestpath.scheduler.RefreshCoordinator;
import shortestpath.settings.Effect;

/**
 * Owns the plugin's sailing state observed at refresh time: the boarded-boat
 * varbit, the side-panel speed varbits, and the boarded boat's entity-graph
 * facts (hull bounds and config id, packed boat point, in-tile pivot, target
 * orientation). {@link #refresh(PlayerStateSource)} captures all of it once
 * per engine refresh on the client thread and publishes a single immutable
 * {@link SailingState} through a volatile holder, so readers on other threads
 * never observe a torn snapshot.
 *
 * <p>The producer contract mirrors the other domain services: capture happens
 * at refresh, and change facts are minted at observation points and declared
 * to the injected {@link RefreshCoordinator} — {@link #onVarbitChanged} is
 * the observation arm, re-capturing on the four sailing varbit events and
 * declaring a {@link SailingChange} only when the route-relevant fields
 * moved. Capture only ever reads; nothing here writes back to the
 * engine.
 */
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class SailingService
{
	private final Client client;
	private final RefreshCoordinator coordinator;

	/**
	 * The last published snapshot — {@link SailingState#EMPTY} until the first
	 * refresh, so {@link #getState()} never returns null. Written solely
	 * through {@link #publish} as a single volatile write of an immutable
	 * value; readers on the render and pathfinder threads see whole
	 * snapshots, never a torn field mix.
	 */
	@Getter private volatile SailingState state = SailingState.EMPTY;

	/**
	 * Republishes {@link SailingState#EMPTY}. The service is a singleton on
	 * the plugin injector, which RuneLite reuses across shutDown/startUp
	 * cycles, so the shell calls this on shutdown to keep one session's
	 * snapshot from feeding the next enable before its first refresh
	 * publishes.
	 */
	public void reset()
	{
		publish(SailingState.EMPTY);
	}

	/**
	 * Captures the sailing inputs into one immutable snapshot and publishes
	 * it. The varbit side reads all four sailing varbits whenever the source
	 * reports {@link GameState#LOGGED_IN} — deliberately not gated on the
	 * aboard flag, since the side-panel reads are unconditional today —
	 * and clears to zero otherwise, matching the existing reset. The entity
	 * side resolves the boat, its hull bounds, packed point, in-tile pivot
	 * and target orientation through the {@link WorldPointUtil} statics; it
	 * runs only while the source reports {@link GameState#LOGGED_IN}, since
	 * nothing reads the entity fields logged out and the world-view graph
	 * can be mid-rebuild on the far side of a hop. A null client (detached
	 * instance), a null local player, or a top-level world view collapses
	 * it to the no-boat values.
	 * <p>
	 * Client thread only, called from the engine's refresh.
	 */
	public void refresh(PlayerStateSource source)
	{
		source.checkOnClientThread();

		boolean loggedIn = GameState.LOGGED_IN.equals(source.gameState());
		boolean aboard = loggedIn && source.varbit(VarbitID.SAILING_BOARDED_BOAT) != 0;
		int baseSpeed = loggedIn ? source.varbit(VarbitID.SAILING_SIDEPANEL_BOAT_BASESPEED) : 0;
		int speedCap = loggedIn ? source.varbit(VarbitID.SAILING_SIDEPANEL_BOAT_SPEEDCAP) : 0;
		int acceleration = loggedIn ? source.varbit(VarbitID.SAILING_SIDEPANEL_BOAT_ACCELERATION) : 0;

		Player localPlayer = !loggedIn || client == null ? null : client.getLocalPlayer();
		WorldEntity boat = localPlayer == null ? null : WorldPointUtil.boat(client, localPlayer);
		LocalPoint boatLp = localPlayer == null ? null : WorldPointUtil.boatLocation(client, localPlayer);
		WorldEntityConfig bounds = boat == null ? null : boat.getConfig();

		boolean hasBoat = boat != null;
		boolean hasBounds = bounds != null;
		int boundsX = hasBounds ? bounds.getBoundsX() : 0;
		int boundsY = hasBounds ? bounds.getBoundsY() : 0;
		int boundsWidth = hasBounds ? bounds.getBoundsWidth() : 0;
		int boundsHeight = hasBounds ? bounds.getBoundsHeight() : 0;
		int hullConfigId = hasBounds ? bounds.getId() : -1;
		int boatPoint = boatLp == null ? WorldPointUtil.UNDEFINED
			: WorldPointUtil.fromLocalInstance(client, boatLp);
		// The game anchors a sailing search at the boat's tile centre; the pivot
		// is the boat's offset from it in local units (128ths of a tile).
		int pivotX = boatLp == null ? 0
			: (boatLp.getX() & (Perspective.LOCAL_TILE_SIZE - 1)) - Perspective.LOCAL_HALF_TILE_SIZE;
		int pivotY = boatLp == null ? 0
			: (boatLp.getY() & (Perspective.LOCAL_TILE_SIZE - 1)) - Perspective.LOCAL_HALF_TILE_SIZE;
		int heading = boat == null ? -1 : boat.getTargetOrientation();

		publish(new SailingState(aboard, baseSpeed, speedCap, acceleration,
			hasBoat, hasBounds, boundsX, boundsY, boundsWidth, boundsHeight,
			hullConfigId, boatPoint, pivotX, pivotY, heading));
	}

	/**
	 * Consumes a varbit event: one of the four sailing varbits re-captures
	 * and publishes a fresh snapshot, then declares a {@link SailingChange}
	 * carrying {@link Effect#ROUTE_INVALIDATING} when the new state differs
	 * on any route-relevant field — boarding or disembarking changes whether
	 * the shown route is sail-able at all, and a hull or speed change alters
	 * what the route costs. Any other varbit is not sailing state and
	 * declares nothing. Positional boat movement is not material — the diff
	 * only flags changes the route consumes (aboard, the hull bounds, and
	 * base speed), so a boat sliding across its tile or a side-panel stat
	 * nothing routes on publishes freely without restarting the search.
	 * <p>
	 * Client thread only — the shell's varbit events arrive there.
	 */
	public void onVarbitChanged(int varbitId)
	{
		if (client == null)
		{
			return;
		}
		if (varbitId != VarbitID.SAILING_BOARDED_BOAT
			&& varbitId != VarbitID.SAILING_SIDEPANEL_BOAT_BASESPEED
			&& varbitId != VarbitID.SAILING_SIDEPANEL_BOAT_SPEEDCAP
			&& varbitId != VarbitID.SAILING_SIDEPANEL_BOAT_ACCELERATION)
		{
			return;
		}

		SailingState previous = state;
		refresh(new ClientPlayerStateSource(client));
		SailingChange change = previous.materiallyEquals(state)
			? null
			: new SailingChange("varbit:" + varbitId, Set.of(Effect.ROUTE_INVALIDATING));
		declare(change);
	}

	/**
	 * Hands an admitted fact to the refresh coordinator. Detached
	 * instances (built with a null coordinator) carry none, so the declare
	 * no-ops there; a null fact declares nothing, mirroring the return-null
	 * convention the shell's mapper used to guard.
	 */
	private void declare(SailingChange change)
	{
		if (change != null && coordinator != null)
		{
			coordinator.sailingChanged(change);
		}
	}

	/**
	 * Single-point publication of the captured snapshot: one volatile write
	 * of an immutable {@link SailingState}, so a reader on another thread can
	 * never observe a half-built state.
	 */
	private void publish(SailingState snapshot)
	{
		state = snapshot;
	}
}

package shortestpath.sailing;

import lombok.Getter;
import lombok.experimental.Accessors;

import shortestpath.WorldPointUtil;

/**
 * One immutable snapshot of the plugin's sailing state, captured on the client
 * thread and published as a single volatile reference so readers on other
 * threads never observe a torn mix of fields from different refreshes. The
 * varbit side carries the boarded-boat flag and the raw side-panel speed
 * values (in the game's own units); the entity side carries the boarded
 * boat's hull bounds, hull config id, packed world point, in-tile pivot, and
 * target orientation. Deliberately primitives only — no {@code Client},
 * {@code WorldEntity}, {@code LocalPoint}, or hull-type references — so the
 * sailing package never couples to the entity graph or the search engine.
 */
@Getter
public final class SailingState
{
	/**
	 * The never-refreshed snapshot: not aboard, no boat, no bounds, every
	 * numeric field at its documented empty value ({@code boatPoint} =
	 * {@link WorldPointUtil#UNDEFINED}, {@code hullConfigId} = -1,
	 * {@code heading} = -1, the rest 0).
	 */
	public static final SailingState EMPTY = new SailingState(
		false, 0, 0, 0, false, false, 0, 0, 0, 0, -1, WorldPointUtil.UNDEFINED, 0, 0, -1);

	/** Whether the boarded-boat varbit reported the player on a boat. */
	private final boolean aboard;
	/** Raw {@code SAILING_SIDEPANEL_BOAT_BASESPEED} varbit value, in 1/128ths of a tile per tick. */
	private final int baseSpeed;
	/** Raw {@code SAILING_SIDEPANEL_BOAT_SPEEDCAP} varbit value. */
	private final int speedCap;
	/** Raw {@code SAILING_SIDEPANEL_BOAT_ACCELERATION} varbit value. */
	private final int acceleration;
	/** Whether the entity-graph boat lookup resolved (the boat is in the scene). */
	@Getter @Accessors(fluent = true)
	private final boolean hasBoat;
	/** Whether the boat's entity config (hull bounds) resolved. */
	@Getter @Accessors(fluent = true)
	private final boolean hasBounds;
	private final int boundsX;
	private final int boundsY;
	private final int boundsWidth;
	private final int boundsHeight;
	/** The boat entity's config id, or -1 when no config resolved. */
	private final int hullConfigId;
	/** Packed world point of the boat's location, or {@link WorldPointUtil#UNDEFINED} when there is none. */
	private final int boatPoint;
	/** The boat's position within its tile in local units, signed from the tile centre; 0 when there is no boat point. */
	private final int pivotX;
	private final int pivotY;
	/** The boat's target orientation, or -1 when there is no boat. */
	private final int heading;

	SailingState(boolean aboard, int baseSpeed, int speedCap, int acceleration,
		boolean hasBoat, boolean hasBounds,
		int boundsX, int boundsY, int boundsWidth, int boundsHeight,
		int hullConfigId, int boatPoint, int pivotX, int pivotY, int heading)
	{
		this.aboard = aboard;
		this.baseSpeed = baseSpeed;
		this.speedCap = speedCap;
		this.acceleration = acceleration;
		this.hasBoat = hasBoat;
		this.hasBounds = hasBounds;
		this.boundsX = boundsX;
		this.boundsY = boundsY;
		this.boundsWidth = boundsWidth;
		this.boundsHeight = boundsHeight;
		this.hullConfigId = hullConfigId;
		this.boatPoint = boatPoint;
		this.pivotX = pivotX;
		this.pivotY = pivotY;
		this.heading = heading;
	}

	/**
	 * Whether two snapshots differ on a field the route actually consumes:
	 * {@code aboard} gates the sailing dispatch, the boat/bounds presence
	 * flags and the bounds feed the hull every move must fit, and
	 * {@code baseSpeed} prices the sailing moves. Positional fields
	 * ({@code boatPoint}, {@code pivotX}, {@code pivotY}, {@code heading})
	 * are deliberately excluded — ordinary boat movement never changes a
	 * route's sailing inputs — and so are the captured-but-unconsumed
	 * fields ({@code speedCap}, {@code acceleration},
	 * {@code hullConfigId}): the snapshot keeps them for fidelity, but no
	 * consumer reads them, so a diff there must never mint a change fact
	 * that would restart a search.
	 */
	boolean materiallyEquals(SailingState other)
	{
		return other != null
			&& aboard == other.aboard
			&& hasBoat == other.hasBoat
			&& hasBounds == other.hasBounds
			&& boundsX == other.boundsX
			&& boundsY == other.boundsY
			&& boundsWidth == other.boundsWidth
			&& boundsHeight == other.boundsHeight
			&& baseSpeed == other.baseSpeed;
	}
}

package shortestpath.scheduler;

import javax.inject.*;
import lombok.Getter;
import shortestpath.pathfinder.ActiveSearch;

/**
 * What the plugin last tried to do, for the debug overlay: the last restart attempt and its
 * outcome, which search is current, and the last errors. It records attempts as well as results,
 * so a restart that failed on the client thread is visible rather than leaving a stale route
 * behind silently. Written by the plugin, read when rendering.
 */
@Getter
@Singleton
public final class DebugState
{
	private static final int MAX_MESSAGE_LENGTH = 60;
	public static final String STARTED = "started";

	/**
	 * One restart attempt: a request plus the outcome it eventually got. Kept as a single
	 * immutable snapshot so the render thread never reads a torn reason/tick/outcome mix.
	 */
	public static final class Restart
	{
		public final int count;
		public final String reason;
		public final int tick;
		public final String outcome;

		private Restart(int count, String reason, int tick, String outcome)
		{
			this.count = count;
			this.reason = reason;
			this.tick = tick;
			this.outcome = outcome;
		}

		private Restart withOutcome(String newOutcome)
		{
			return new Restart(count, reason, tick, newOutcome);
		}
	}

	// Last restart attempt
	private volatile Restart restart;
	private int restartCount;

	// Current search
	private volatile ActiveSearch search;
	private volatile ActiveSearch cancelledSearch;

	// Errors
	private volatile int clientErrorCount;
	private volatile String clientError;
	private volatile int clientErrorTick = -1;
	private volatile int searchErrorCount;
	private volatile String searchError;
	private volatile int searchErrorTick = -1;

	@Inject
	public DebugState()
	{
	}

	void restartRequested(String reason, int tick)
	{
		restart = new Restart(++restartCount, reason, tick, "pending");
	}

	void restartOutcome(String outcome)
	{
		Restart current = restart;
		if (current != null)
		{
			restart = current.withOutcome(outcome);
		}
	}

	void searchCancelled(ActiveSearch cancelled)
	{
		cancelledSearch = cancelled;
	}

	void searchStarted(ActiveSearch started)
	{
		search = started;
		restartOutcome(STARTED);
	}

	void clientError(Throwable error, int tick)
	{
		clientErrorCount++;
		clientError = describe(error);
		clientErrorTick = tick;
	}

	void searchError(Throwable error, int tick)
	{
		searchErrorCount++;
		searchError = describe(error);
		searchErrorTick = tick;
	}

	static String describe(Throwable error)
	{
		String text = error.getClass().getSimpleName()
			+ (error.getMessage() == null ? "" : ": " + error.getMessage());
		return text.length() <= MAX_MESSAGE_LENGTH ? text : text.substring(0, MAX_MESSAGE_LENGTH - 3) + "...";
	}
}

package shortestpath.scheduler;

import shortestpath.settings.ConfigKey;
import java.awt.Color;
import java.util.List;

import javax.inject.*;

import lombok.RequiredArgsConstructor;

import shortestpath.WorldPointUtil;
import shortestpath.pathfinder.*;
import shortestpath.sailing.SailingService;
import shortestpath.settings.Settings;

/**
 * The render-side read seam over the scheduler's published state: which
 * search is drawing, whether it sails, where the boat's in-tile pivot sits,
 * and whether the player is aboard. Read-only — every value is a volatile
 * field or a published immutable snapshot, so a per-frame read on the render
 * thread never blocks and never observes a torn mix. This is the overlays'
 * presentation contract; it currently carries the sailing surface.
 */
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public final class PathRenderState
{
	/**
	 * The colour of the path while on a boat, which sails the boat's
	 * headings. Moved here off the plugin shell; the RGB is unchanged.
	 */
	public static final Color SAILING_PATH_COLOUR = new Color(0, 120, 255);

	private final PathScheduler scheduler;
	private final SailingService sailing;
	private final Settings settings;

	/**
	 * Whether the active search sails a boat's headings rather than walking
	 * (see {@link ActiveSearch#isSailing}), so it has a point at the end of
	 * each move and is drawn as lines along its headings.
	 */
	public boolean isSailing()
	{
		ActiveSearch search = scheduler.getActiveSearch();
		return search != null && search.isSailing();
	}

	/**
	 * The boat's in-tile pivot X for the current sailing dispatch, in local
	 * units signed from the tile centre. This is the value written when the
	 * sailing search was dispatched — it matches what that search drew.
	 */
	public int getSailingPivotX()
	{
		return scheduler.getSailingPivotX();
	}

	/**
	 * The boat's in-tile pivot Y for the current sailing dispatch, in local
	 * units signed from the tile centre. This is the value written when the
	 * sailing search was dispatched — it matches what that search drew.
	 */
	public int getSailingPivotY()
	{
		return scheduler.getSailingPivotY();
	}

	/**
	 * Whether the last published sailing snapshot reports the player aboard
	 * a boat — the read behind the disembark hint.
	 */
	public boolean isOnSailingBoat()
	{
		return sailing.getState().isAboard();
	}

	/**
	 * Whether the finished search's path counts as unreachable — the verdict
	 * behind the unreachable-path colour. A walking path measures the
	 * closest target's distance from the path end against the configured
	 * threshold; a sailing path trusts the search's own reached verdict,
	 * since the hull covering the target is what arrival means there.
	 */
	public boolean isPathUnreachable()
	{
		ActiveSearch pathfinder = scheduler.getActiveSearch();
		if (pathfinder == null || !pathfinder.isDone())
		{
			return false;
		}

		List<PathStep> path = pathfinder.getPath();
		if (path == null || pathfinder.getTargets().isEmpty())
		{
			return false;
		}

		// A sailing path arrives once the boat's hull covers the target, with the boat's own tile up to a boat length
		// from it, so the search says whether it got there
		if (pathfinder.isSailing())
		{
			PathfinderResult result = pathfinder.getResult();
			return result != null && !result.isReached();
		}

		// A finished search can produce an empty path when no goal tile could ever be
		// reached (e.g. a blocked target); measure the distance from the start then.
		int endPoint = path.isEmpty() ? pathfinder.getStart()
			: path.get(path.size() - 1).getPackedPosition();
		int closestTargetDistance = Integer.MAX_VALUE;
		for (int target : pathfinder.getTargets().points())
		{
			closestTargetDistance = Math.min(closestTargetDistance, WorldPointUtil.distanceBetween(target, endPoint));
		}

		return closestTargetDistance > settings.num(ConfigKey.UNREACHABLE_TARGET_DISTANCE_THRESHOLD);
	}

	/**
	 * The path colour the overlays draw: calculating while the search runs,
	 * unreachable when the finished path falls short of the target, normal
	 * otherwise.
	 */
	public Color getPathColor()
	{
		ActiveSearch pathfinder = scheduler.getActiveSearch();
		if (pathfinder == null || !pathfinder.isDone())
		{
			return settings.get(ConfigKey.COLOUR_PATH_CALCULATING);
		}

		List<PathStep> path = pathfinder.getPath();
		if (path == null || path.isEmpty() || pathfinder.getTargets().isEmpty())
		{
			return settings.get(ConfigKey.COLOUR_PATH);
		}

		if (isPathUnreachable())
		{
			return settings.get(ConfigKey.COLOUR_PATH_UNREACHABLE);
		}

		return settings.get(ConfigKey.COLOUR_PATH);
	}
}

package shortestpath.scheduler;

import shortestpath.settings.ConfigKey;
import com.google.common.util.concurrent.ThreadFactoryBuilder;
import java.awt.image.BufferedImage;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.Supplier;
import javax.inject.*;
import lombok.*;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.ui.overlay.worldmap.*;
import net.runelite.client.util.ImageUtil;
import shortestpath.settings.Settings;
import shortestpath.WorldPointUtil;
import shortestpath.pathfinder.*;
import shortestpath.pathfinder.sailing.*;
import shortestpath.pathfinder.astar.AStarRoutingSession;
import shortestpath.sailing.*;

/**
 * Owns the plugin's pathfinding concurrency: the single-worker executor, the mutex that pairs
 * the displayed search with its future and the queued queries, the deferred-tick work queue,
 * and the target/start marker state. The plugin shell forwards user and plugin-message intents
 * here and answers callers through the narrow {@link QueryResponder} seam. This package is a
 * leaf: nothing here may reference the plugin type.
 */
@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class PathScheduler
{
	private static final BufferedImage MARKER_IMAGE = ImageUtil.loadImageResource(PathScheduler.class, "/shortestpath/marker.png");
	private final List<Integer> pendingTasks = new ArrayList<>(3);
	private final Object pathfinderMutex = new Object();

	private final Client client;
	private final ClientThread clientThread;
	private final Settings settings;
	private final WorldMapPointManager worldMapPointManager;
	private final DebugState debugState;

	// Late-bound by attach(): the shell still owns PathfinderConfig construction and the
	// plugin-message surface, so they cannot ride the constructor. The sailing service
	// joins them for the same reason — injecting it here would close the
	// SailingService -> RefreshCoordinator -> PathScheduler Guice cycle.
	private PathfinderConfig pathfinderConfig;
	private SailingService sailing;
	private QueryResponder responder;

	private WorldMapPoint marker;
	private int lastLocation = WorldPointUtil.packWorldPoint(0, 0, 0);
	private ExecutorService pathfindingExecutor = Executors.newSingleThreadExecutor();
	private Future<?> pathfinderFuture;
	// Queries in flight or still queued, guarded by pathfinderMutex. Used both to answer callers
	// whose query never ran and to know whether a search is reading the transport availability.
	private final Map<ActiveSearch, QueryTask> queries = new LinkedHashMap<>();
	// Volatile because the render thread reads it (through getActiveSearch() and friends)
	// while restarts write it on the client thread under pathfinderMutex.
	private volatile ActiveSearch pathfinder;
	private AStarRoutingStaticProvider aStarRoutingStatic;
	private final AStarRoutingSession aStarRoutingSession = new AStarRoutingSession();
	@Getter(AccessLevel.PACKAGE) private boolean startPointSet = false;
	// Where the boat sat within its tile when the sailing search started, in local units from the tile centre
	@Getter private volatile int sailingPivotX;
	@Getter private volatile int sailingPivotY;

	/**
	 * Binds the shell-owned pieces the scheduler needs: the pathfinder config the shell builds in
	 * startUp, the sailing service, and the plugin-message responder. Called
	 * before anything can elicit a search.
	 */
	public void attach(PathfinderConfig pathfinderConfig, SailingService sailing, QueryResponder responder)
	{
		this.pathfinderConfig = pathfinderConfig;
		this.sailing = sailing;
		this.responder = responder;
	}

	void restart(String reason, int start, Targets ends, boolean canReviveFiltered)
	{
		debugState.restartRequested(reason, client.getTickCount());
		List<PathStep> previousPath;
		Targets previousTargets;
		synchronized (pathfinderMutex)
		{
			previousPath = pathfinder == null ? null : pathfinder.getPath();
			previousTargets = pathfinder == null ? null : pathfinder.getTargets();
			if (pathfinder != null)
			{
				pathfinder.cancel();
				// pathfinderFuture is null when a submit threw before the
				// assignment (e.g. executor shutting down mid-restart).
				if (pathfinderFuture != null)
				{
					pathfinderFuture.cancel(true);
				}
				debugState.searchCancelled(pathfinder);
			}
			// The displayed path wins over pending queries: it refreshes the transport
			// availability, which a running query would otherwise read mid-search, and queued
			// queries would delay it on the shared single thread.
			cancelQueries("CANCELLED");

			ensurePathfindingExecutor();
		}

		clientThread.invokeLater(() ->
		{
			try
			{
				startPathfinding(start, ends, canReviveFiltered, previousPath, previousTargets);
			}
			catch (RuntimeException error)
			{
				debugState.clientError(error, client.getTickCount());
				debugState.restartOutcome("failed: " + DebugState.describe(error));
				throw error;
			}
		});
	}

	private void startPathfinding(int start, Targets requestedEnds, boolean canReviveFiltered,
		List<PathStep> previousPath, Targets previousTargets)
	{
		pathfinderConfig.refresh();
		Targets ends = pathfinderConfig.filterLocations(requestedEnds, canReviveFiltered);
		synchronized (pathfinderMutex)
		{
			if (ends.isEmpty())
			{
				debugState.restartOutcome("no targets left after filtering");
				setTarget(WorldPointUtil.UNDEFINED);
			}
			else
			{
				// The boarded-boat varbit can lag the world entity (stale across a teleport or
				// login), so only sail when the boat is actually in the scene — otherwise the
				// search would sail its headings across land
				if (pathfinderConfig.isSailingMoves() && sailing.getState().hasBoat())
				{
					pathfinder = sailingPathfinder(start, ends);
				}
				else
				{
					try
					{
						AStarPathfinder aStar = new AStarPathfinder(pathfinderConfig, aStarRoutingStatic(),
							aStarRoutingSession, start, ends, responder::postPluginMessages);
						// Recalculating towards the same targets: keep the old route drawn until
						// the new one is ready.
						if (ends.equals(previousTargets))
							aStar.showUntilDone(previousPath);
						pathfinder = aStar;
					}
					catch (RuntimeException error)
					{
						debugState.clientError(error, client.getTickCount());
						pathfinder = AStarPathfinder.failed(start, ends, responder::postPluginMessages, error);
					}
				}
				ActiveSearch search = pathfinder;
				debugState.searchStarted(search);
				pathfinderFuture = pathfindingExecutor.submit(() ->
				{
					try
					{
						search.run();
					}
					catch (RuntimeException error)
					{
						debugState.searchError(error, client.getTickCount());
						throw error;
					}
				});
			}
		}
	}

	/**
	 * On a boat, a search that sails the boat's 16 headings at its base speed instead of walking. It starts from the
	 * boat's exact tile and remembers where the boat sits within it: every sailing move lands whole tiles away, so the
	 * boat stays at that spot at each turn of the path. The boat's whole hull, from its bounds, must fit along every move
	 * there.
	 */
	private SailingPathfinder sailingPathfinder(int start, Targets ends)
	{
		int sailingStart = start;
		sailingPivotX = 0;
		sailingPivotY = 0;
		SailingState state = sailing.getState();
		if (state.getBoatPoint() != WorldPointUtil.UNDEFINED && !startPointSet)
		{
			sailingStart = state.getBoatPoint();
			sailingPivotX = state.getPivotX();
			sailingPivotY = state.getPivotY();
		}
		BoatHull hull = !state.hasBounds() ? null : BoatHull.fromBounds(state.getBoundsX(), state.getBoundsY(),
			state.getBoundsWidth(), state.getBoundsHeight(), sailingPivotX, sailingPivotY);
		// The heading the boat faces where the route starts, as one of the 16 headings 128 angle units
		// apart: a target under its hull only counts as reached facing that way — berthed, the boat hasn't
		// arrived at a target astern of it. The target orientation pairs with the target tile the route
		// starts from
		int sailingHeading = state.getHeading() < 0 ? WorldPointUtil.UNDEFINED
			: Math.floorMod((state.getHeading() + 64) / 128, 16);
		return new SailingPathfinder(pathfinderConfig, sailingStart, ends, responder::postPluginMessages,
			SailingMoves.forSpeed(pathfinderConfig.getSailingSpeed()), hull, sailingHeading);
	}

	private void ensurePathfindingExecutor()
	{
		synchronized (pathfinderMutex)
		{
			if (pathfindingExecutor == null)
			{
				ThreadFactory shortestPathNaming = new ThreadFactoryBuilder().setNameFormat("shortest-path-%d").build();
				pathfindingExecutor = Executors.newSingleThreadExecutor(shortestPathNaming);
			}
		}
	}

	private AStarRoutingStaticProvider aStarRoutingStatic()
	{
		synchronized (pathfinderMutex)
		{
			if (aStarRoutingStatic == null)
				aStarRoutingStatic = new AStarRoutingStaticProvider(pathfinderConfig::getMap);
			return aStarRoutingStatic;
		}
	}

	/**
	 * Builds the A* backend's static routing data in the background, so the first route does
	 * not pay for it. The build runs on the pathfinding thread, so a search submitted
	 * meanwhile simply queues behind it; a failed build is remembered by the provider and
	 * reported by that search.
	 */
	public void prepareBackend()
	{
		if (pathfinderConfig == null)
		{
			return;
		}
		AStarRoutingStaticProvider provider = aStarRoutingStatic();
		ensurePathfindingExecutor();
		synchronized (pathfinderMutex)
		{
			pathfindingExecutor.submit(() ->
			{
				try
				{
					provider.get();
				}
				catch (RuntimeException error)
				{
					log.warn("Failed to build A* routing data", error);
				}
			});
		}
	}

	void restart(String reason, int start, Targets ends)
	{
		restart(reason, start, ends, true);
	}

	boolean isNearPath(int location)
	{
		List<PathStep> path;
		// The previous route is only on screen until its recalculation finishes; the player is
		// expected to be off it, so it must not trigger yet another recalculation.
		if (pathfinder.isShowingProvisionalPath())
		{
			return true;
		}
		boolean sameLocation = lastLocation == location;
		lastLocation = location;
		if (pathfinder == null || (path = pathfinder.getPath()) == null || path.isEmpty() ||
			settings.num(ConfigKey.RECALCULATE_DISTANCE) < 0 || sameLocation)
		{
			return true;
		}

		for (PathStep pathStep : path)
		{
			if (WorldPointUtil.distanceBetween(location, pathStep.getPackedPosition()) < settings.num(ConfigKey.RECALCULATE_DISTANCE))
			{
				return true;
			}
		}

		// A sailing path has a point at the end of each move, up to a dozen tiles apart, so the boat can be between them
		if (isSailing())
		{
			for (int i = 1; i < path.size(); i++)
			{
				if (distanceToLine(location, path.get(i - 1).getPackedPosition(), path.get(i).getPackedPosition())
					< settings.num(ConfigKey.RECALCULATE_DISTANCE))
				{
					return true;
				}
			}
		}

		return false;
	}

	// How far a point is from the closest point on the straight line between two others, in tiles counted like
	// WorldPointUtil#distanceBetween, or Integer.MAX_VALUE on another plane
	private static int distanceToLine(int point, int from, int to)
	{
		if (WorldPointUtil.unpackWorldPlane(point) != WorldPointUtil.unpackWorldPlane(from))
		{
			return Integer.MAX_VALUE;
		}
		final double px = WorldPointUtil.unpackWorldX(point);
		final double py = WorldPointUtil.unpackWorldY(point);
		final double ax = WorldPointUtil.unpackWorldX(from);
		final double ay = WorldPointUtil.unpackWorldY(from);
		final double dx = WorldPointUtil.unpackWorldX(to) - ax;
		final double dy = WorldPointUtil.unpackWorldY(to) - ay;
		final double lengthSquared = dx * dx + dy * dy;
		final double t = lengthSquared == 0 ? 0 : Math.max(0, Math.min(1, ((px - ax) * dx + (py - ay) * dy) / lengthSquared));
		return (int) Math.round(Math.max(Math.abs(px - (ax + t * dx)), Math.abs(py - (ay + t * dy))));
	}

	private boolean isSailing()
	{
		return pathfinder != null && pathfinder.isSailing();
	}

	/**
	 * Finds a path for another plugin without touching the displayed one, and answers with a
	 * {@code result} plugin message carrying the caller's {@code id}.
	 *
	 * <p>Queries share the single pathfinding thread with the displayed path, so the two never
	 * search at the same time. The transport availability is only refreshed when no search is
	 * queued or running, since a search reads it while it runs; otherwise the query uses what the
	 * previous search was started with. A new displayed path cancels pending queries, so a query
	 * never runs concurrently with a refresh triggered by {@code restart} either.
	 */
	public void queryPath(Object id, int start, Targets targets)
	{
		clientThread.invokeLater(() ->
		{
			synchronized (pathfinderMutex)
			{
				if (pathfindingExecutor == null)
				{
					responder.postQueryFailure(id, "SHUTDOWN");
					return;
				}
				if (queries.isEmpty() && (pathfinder == null || pathfinder.isDone()))
				{
					pathfinderConfig.refresh();
				}
				// The plugin's only engine serves external callers too: queries run on the
				// same A* backend as the displayed path and reuse its session cache.
				ActiveSearch query = querySearch(start, targets);
				QueryTask task = new QueryTask(id);
				queries.put(query, task);
				task.future = pathfindingExecutor.submit(() -> runQuery(query, task));
			}
		});
	}

	/**
	 * The engine a plugin-message query runs. A constructor failure still owes the caller a
	 * result, so it becomes a finished {@code failed()} search carrying BACKEND_FAILURE
	 * rather than an uncaught exception thrown across the client-thread hop.
	 */
	private ActiveSearch querySearch(int start, Targets targets)
	{
		try
		{
			return new AStarPathfinder(pathfinderConfig, aStarRoutingStatic(), aStarRoutingSession,
				start, targets, null);
		}
		catch (RuntimeException error)
		{
			return AStarPathfinder.failed(start, targets, null, error);
		}
	}

	private void runQuery(ActiveSearch query, QueryTask task)
	{
		try
		{
			query.run();
			responder.postQueryResult(task.id, query);
		}
		catch (RuntimeException | Error e)
		{
			responder.postQueryFailure(task.id, "ERROR");
			throw e;
		}
		finally
		{
			synchronized (pathfinderMutex)
			{
				queries.remove(query);
			}
		}
	}

	/**
	 * Cancels every pending query while holding {@link #pathfinderMutex}. Queries still in the
	 * executor queue are dequeued and answered here since their runnable will never execute;
	 * queries already running are signalled and answer for themselves once they stop.
	 */
	private void cancelQueries(String reason)
	{
		for (Iterator<Map.Entry<ActiveSearch, QueryTask>> it = queries.entrySet().iterator(); it.hasNext();)
		{
			Map.Entry<ActiveSearch, QueryTask> entry = it.next();
			QueryTask task = entry.getValue();
			if (task.future != null && task.future.cancel(false))
			{
				it.remove();
				responder.postQueryFailure(task.id, reason);
			}
			else
			{
				entry.getKey().cancel();
			}
		}
	}

	/**
	 * Cancels pending queries and tears the executor down for plugin shutdown. The executor is
	 * nulled rather than left stopped so a late restart lazily recreates it.
	 */
	public void shutdown()
	{
		synchronized (pathfinderMutex)
		{
			cancelQueries("SHUTDOWN");
			if (pathfindingExecutor != null)
			{
				pathfindingExecutor.shutdownNow();
				pathfindingExecutor = null;
			}
		}
	}

	/**
	 * Queues a config refresh to run on a later client tick, after the triggering state change
	 * has fully settled. No-ops before {@code startUp} attaches the config — the pre-init
	 * guard lives here so callers may declare events unconditionally.
	 */
	void deferRefresh(int tick)
	{
		if (pathfinderConfig == null)
		{
			return;
		}
		pendingTasks.add(tick);
	}

	/**
	 * Runs each pending task whose tick has arrived, in submission order.
	 */
	void drainDueTasks(int tick)
	{
		for (int i = 0; i < pendingTasks.size(); i++)
		{
			if (tick >= pendingTasks.get(i))
			{
				pendingTasks.remove(i--);
				pathfinderConfig.refresh();
			}
		}
	}

	/**
	 * Marks the eligibility snapshot stale; the next config refresh rebuilds it.
	 */
	void invalidateEligibility()
	{
		pathfinderConfig.invalidateEligibility();
	}

	public void setTarget(int target)
	{
		setTarget(target, false);
	}

	public void setTarget(int target, boolean append)
	{
		Set<Integer> targets = new HashSet<>();
		if (target != WorldPointUtil.UNDEFINED)
		{
			targets.add(target);
		}
		setTargets(targets, append);
	}

	public void setTargets(Set<Integer> targets, boolean append)
	{
		if (targets == null || targets.isEmpty())
		{
			synchronized (pathfinderMutex)
			{
				if (pathfinder != null)
				{
					pathfinder.cancel();
				}
				pathfinder = null;
			}

			worldMapPointManager.removeIf(x -> x == marker);
			marker = null;
			startPointSet = false;
		}
		else
		{
			Player localPlayer = client.getLocalPlayer();
			if (!startPointSet && localPlayer == null)
			{
				return;
			}
			worldMapPointManager.removeIf(x -> x == marker);
			if (targets.size() == 1)
			{
				marker = new WorldMapPoint(WorldPointUtil.unpackWorldPoint(targets.iterator().next()), MARKER_IMAGE);
				marker.setName("Target");
				marker.setTarget(marker.getWorldPoint());
				marker.setJumpOnClick(true);
				worldMapPointManager.add(marker);
			}

			// fromLocalInstance needs a live player; during a world hop it is
			// null, so fall back to the running search's start and bail when
			// there is nothing to anchor to.
			int start;
			if (localPlayer != null)
			{
				start = WorldPointUtil.fromLocalInstance(client, localPlayer);
				lastLocation = start;
			}
			else if (startPointSet && pathfinder != null)
			{
				start = pathfinder.getStart();
			}
			else
			{
				return;
			}
			if (startPointSet && pathfinder != null)
			{
				start = pathfinder.getStart();
			}
			// Targets the player picks need no items; adding one keeps the items of those already set.
			Targets destinations = Targets.at(targets);
			if (pathfinder != null && append)
			{
				destinations = pathfinder.getTargets().plus(destinations);
			}
			restart(append ? "add target" : "set target", start, destinations, append);
		}
	}

	public void setStart(int start)
	{
		if (pathfinder == null)
		{
			return;
		}
		startPointSet = true;
		restart("set start", start, pathfinder.getTargets());
	}

	public ActiveSearch getActiveSearch()
	{
		return pathfinder;
	}

	/**
	 * Runs {@code action} while holding the scheduler mutex, for shell callers that must pair
	 * their own state writes with the search snapshot.
	 */
	public <T> T withSchedulerLock(Supplier<T> action)
	{
		synchronized (pathfinderMutex)
		{
			return action.get();
		}
	}

	/**
	 * {@link #withSchedulerLock(Supplier)} for bodies that have nothing to return; the same
	 * monitor guards both overloads.
	 */
	public void withSchedulerLock(Runnable action)
	{
		withSchedulerLock(() ->
		{
			action.run();
			return null;
		});
	}
}

package shortestpath.scheduler;

import shortestpath.pathfinder.ActiveSearch;

/**
 * How the scheduler talks back to the plugin-message surface: a query finished, a query was
 * refused, or the deferred plugin-message queue should be flushed. The plugin implements this
 * narrow seam; the scheduler never sees the plugin-message payload types itself.
 */
public interface QueryResponder
{
	void postQueryResult(Object id, ActiveSearch query);

	void postQueryFailure(Object id, String reason);

	void postPluginMessages();
}

package shortestpath.scheduler;

import java.util.concurrent.Future;

/**
 * A query that has been submitted to the executor: the caller's {@code id} plus the task's
 * future, so it can be answered or cancelled when the displayed path or plugin shutdown
 * takes precedence.
 */
class QueryTask
{
	final Object id;
	Future<?> future;

	QueryTask(Object id)
	{
		this.id = id;
	}
}

package shortestpath.scheduler;

import java.util.*;
import javax.inject.*;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.GameState;
import shortestpath.settings.*;
import shortestpath.WorldPointUtil;
import shortestpath.items.ItemChange;
import shortestpath.pathfinder.*;
import shortestpath.pathfinder.sailing.SailingPathfinder;
import shortestpath.poh.PohChange;
import shortestpath.sailing.SailingChange;
import shortestpath.spirittree.TreeChange;

/**
 * Owns the "state changed, so what recomputes" policy: producer-declared change
 * facts and client events arrive on the typed channels below and are mapped to
 * scheduler verbs. This is the scheduler's sole policy caller — the verbs it
 * invokes are package-private so the rule is compiler-enforced. The
 * coordinator holds no lock; every channel runs on the client thread where the
 * shell's event handlers ran before it, and the only state it carries is the
 * game-state transition memory that moved with the login gate.
 */
@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class RefreshCoordinator
{
	/**
	 * The restart reasons the tree channel reproduces, keyed by the
	 * {@link TreeChange} key. {@code "varbit:<patch>"} keys match by prefix in
	 * {@link #treeRestartReason}, not by this map.
	 */
	private static final Map<String, String> TREE_RESTART_REASONS = Map.of(
		"profile", "profile change",
		"menu", "spirit trees");

	/**
	 * The log labels the POH channel reproduces, keyed by the {@link PohChange}
	 * key. The channel is log-only — the labels feed the debug/warn lines, not
	 * restarts.
	 */
	private static final Map<String, String> POH_LOG_LABELS = Map.of(
		"profile", "profile load",
		"dialog", "nexus dialog",
		"dialogLine", "nexus dialog line");

	private final PathScheduler scheduler;
	private final Settings settings;

	// The login transition memory for gameStateChanged's three-state gate.
	private GameState lastGameState = null;
	private GameState lastLastGameState = null;

	/**
	 * Maps an item-state change fact to its follow-up actions: the declared
	 * {@link Effect#ELIGIBILITY_STALE} effect lazily rebuilds the eligibility
	 * snapshot. {@code null} facts admit nothing and map to no action.
	 */
	public void itemsChanged(ItemChange change)
	{
		if (change != null && change.getEffects().contains(Effect.ELIGIBILITY_STALE))
		{
			scheduler.invalidateEligibility();
		}
	}

	/**
	 * Maps a spirit-tree change fact to its follow-up actions: the declared
	 * {@link Effect#ROUTE_INVALIDATING} effect restarts pathfinding with the
	 * running search's own start and targets. {@code null} facts admit nothing
	 * and map to no action, and with no search running the declare is a no-op.
	 */
	public void treeSetChanged(TreeChange change)
	{
		if (change != null
			&& change.getEffects().contains(Effect.ROUTE_INVALIDATING)
			&& scheduler.getActiveSearch() != null)
		{
			ActiveSearch pathfinder = scheduler.getActiveSearch();
			scheduler.restart(treeRestartReason(change.getKey()), pathfinder.getStart(), pathfinder.getTargets());
		}
	}

	/**
	 * Maps a sailing-state change fact to its follow-up actions: boarding,
	 * disembarking, or a hull/speed change invalidates the shown route, so
	 * the declared {@link Effect#ROUTE_INVALIDATING} effect restarts
	 * pathfinding with the running search's own start and targets. {@code
	 * null} facts admit nothing and map to no action, and with no search
	 * running the declare is a no-op.
	 */
	public void sailingChanged(SailingChange change)
	{
		if (change != null
			&& change.getEffects().contains(Effect.ROUTE_INVALIDATING)
			&& scheduler.getActiveSearch() != null)
		{
			// A boat-state change is not an off-route drift, so the
			// cancelInstead config does not gate this channel — the restart
			// mapping mirrors treeSetChanged exactly.
			ActiveSearch pathfinder = scheduler.getActiveSearch();
			scheduler.restart(sailingRestartReason(change.getKey()), pathfinder.getStart(), pathfinder.getTargets());
		}
	}

	/**
	 * Maps a POH change fact to its follow-up actions. {@link
	 * Effect#DISPLAY_ONLY} carries no action — the keybind map is read lazily
	 * by the display path, which sees it hot by reference — so it is logged and
	 * nothing else runs; any other effect violates the service contract and is
	 * surfaced rather than silently swallowed.
	 */
	public void pohChanged(PohChange change)
	{
		if (change == null || change.getEffects().isEmpty())
		{
			return;
		}
		String why = POH_LOG_LABELS.getOrDefault(change.getKey(), change.getKey());
		for (Effect effect : change.getEffects())
		{
			if (Effect.DISPLAY_ONLY.equals(effect))
			{
				log.debug("POH display refresh: {}", why);
			}
			else
			{
				log.warn("Unhandled POH change effect {} ({})", effect, why);
			}
		}
	}

	/**
	 * Maps a config change fact to its follow-up actions: a routing-input
	 * change restarts the running search. The debug-overlay side effect stays
	 * with the shell, which owns the overlay manager; {@link
	 * Effect#DISPLAY_ONLY} maps to no action.
	 */
	public void configChanged(ConfigChange change)
	{
		Set<Effect> effects = change.getEffects();

		// A routing input changed; rerun pathfinding
		if (effects.contains(Effect.ROUTE_INVALIDATING) && scheduler.getActiveSearch() != null)
		{
			ActiveSearch pathfinder = scheduler.getActiveSearch();
			scheduler.restart("config: " + change.getKey(), pathfinder.getStart(), pathfinder.getTargets());
		}
	}

	/**
	 * A config-profile switch: warms the backend again and restarts the
	 * running search, if any. Returns whether a search was restarted so the
	 * shell can queue its no-search config refresh fallback itself.
	 */
	public boolean profileChanged()
	{
		scheduler.prepareBackend();
		ActiveSearch pathfinder = scheduler.getActiveSearch();
		if (pathfinder == null)
		{
			return false;
		}
		scheduler.restart("configuration profile change", pathfinder.getStart(), pathfinder.getTargets());
		return true;
	}

	/**
	 * A world hop queues a config refresh for the next client tick, once the
	 * new world's type (e.g. seasonal) has settled and league-mode
	 * auto-detection can re-resolve.
	 */
	public void worldChanged(int tick)
	{
		scheduler.deferRefresh(tick + 1);
	}

	/**
	 * A {@code LOGGING_IN} → {@code LOADING} → {@code LOGGED_IN} login
	 * transition warms the backend and queues a config refresh for the next
	 * client tick, once the fresh profile's state is readable — the statics
	 * build needs resources that only exist after login. Other transitions
	 * only update the transition memory.
	 */
	public void gameStateChanged(GameState state, int tick)
	{
		GameState previousGameState = lastGameState;
		GameState previousPreviousGameState = lastLastGameState;
		lastLastGameState = lastGameState;
		lastGameState = state;

		if (!GameState.LOGGING_IN.equals(previousPreviousGameState)
			|| !GameState.LOADING.equals(previousGameState)
			|| !GameState.LOGGED_IN.equals(lastGameState))
		{
			return;
		}

		scheduler.prepareBackend();
		scheduler.deferRefresh(tick + 1);
	}

	/**
	 * Runs the deferred-work queue at the tick's drain position. The spirit-tree
	 * observation and the off-route decision occupy their own positions in the
	 * shell's tick sequence, before and after this call respectively.
	 */
	public void gameTick(int tick)
	{
		scheduler.drainDueTasks(tick);
	}

	/**
	 * The tick's off-route decision: when the player reaches a target tile the
	 * path is cleared, and when the player strays too far from the displayed
	 * route the search either clears or restarts from the current position,
	 * per config. With no running search there is nothing to guard — the shell
	 * already declined the tick, and the re-read below keeps that no-op exact.
	 */
	public void offRouteTick(int tick, int currentLocation, int boatLocation, int boatHeading)
	{
		ActiveSearch pathfinder = scheduler.getActiveSearch();
		if (pathfinder == null)
		{
			return;
		}

		// A sailing path arrives once the boat's hull covers a target, which can leave the boat's own
		// tile farther than the reached distance on long hulls — check the live boat rather than the
		// player's tile, and not the search's verdict: that says a route was found, not that it sailed
		// there. The reached-distance check below still runs for goal-tile arrivals and disembarking.
		if (pathfinder.isSailing() && settings.num(ConfigKey.FINISH_DISTANCE) >= 0
			&& boatLocation != WorldPointUtil.UNDEFINED && boatHeading != WorldPointUtil.UNDEFINED
			&& ((SailingPathfinder) pathfinder).arrivedTarget(boatLocation, boatHeading) != WorldPointUtil.UNDEFINED)
		{
			scheduler.setTarget(WorldPointUtil.UNDEFINED);
			return;
		}

		for (int target : pathfinder.getTargets().points())
		{
			if (WorldPointUtil.distanceBetween(currentLocation, target) < settings.num(ConfigKey.FINISH_DISTANCE))
			{
				scheduler.setTarget(WorldPointUtil.UNDEFINED);
				return;
			}
		}

		if (!scheduler.isStartPointSet() && !scheduler.isNearPath(currentLocation))
		{
			if (settings.bool(ConfigKey.CANCEL_INSTEAD))
			{
				scheduler.setTarget(WorldPointUtil.UNDEFINED);
				return;
			}
			scheduler.restart("off route", currentLocation, pathfinder.getTargets());
		}
	}

	/**
	 * A plugin message asking for a path to {@code targets} from {@code start}.
	 * An empty target set re-uses the running search's targets — the
	 * recompute-on-same-targets restart the message surface relies on.
	 */
	public void targetRequest(int start, Targets targets)
	{
		ActiveSearch pathfinder = scheduler.getActiveSearch();
		boolean useOld = targets.isEmpty() && pathfinder != null;
		scheduler.restart("plugin message", start, useOld ? pathfinder.getTargets() : targets, useOld);
	}

	/**
	 * The restart reason for a spirit-tree fact: the literal the shell used to
	 * supply at the declare site, derived from the fact's key so the debug
	 * panel's restart log keeps its familiar text.
	 */
	private static String treeRestartReason(String key)
	{
		if (key.startsWith("varbit:"))
		{
			return "spirit tree varbit";
		}
		return TREE_RESTART_REASONS.getOrDefault(key, key);
	}

	/**
	 * The restart reason for a sailing fact: the literal the debug panel's
	 * restart log is read against, derived from the fact's key so the log
	 * keeps its familiar text.
	 */
	private static String sailingRestartReason(String key)
	{
		if (key.startsWith("varbit:"))
		{
			return "sailing varbit";
		}
		return key;
	}
}

package shortestpath.settings;

import java.util.Set;

import lombok.Getter;

/**
 * An immutable fact describing a single config change: the key that changed
 * and the {@link Effect}s it triggers. Produced by
 * {@link Settings#onConfigChanged}; the shell reads the effect set to decide
 * which follow-up actions to run rather than re-deriving them from the key.
 */
@Getter
public final class ConfigChange
{
	private final String key;
	private final Set<Effect> effects;

	ConfigChange(String key, Set<Effect> effects)
	{
		this.key = key;
		this.effects = Set.copyOf(effects);
	}
}

package shortestpath.settings;

import java.util.*;

import lombok.*;
import lombok.experimental.Accessors;
import shortestpath.Util;

/**
 * Display metadata for the hidden config keys — the {@code name},
 * {@code description} and {@code @Range} bounds that used to live in the
 * deleted {@code @ConfigItem} annotations, moved to
 * {@code config-items.tsv} (key, name, description, min, max).
 */
public final class ConfigItems
{
	/**
	 * The display record {@link Settings#item} returns; accessor names match
	 * {@code ConfigItem}'s so the panel reads the same fields either way.
	 */
	@AllArgsConstructor
	public static final class Meta
	{
		final String key;
		@Getter @Accessors(fluent = true) final String name;
		@Getter @Accessors(fluent = true) final String description;
		/** The {@code @Range} lower bound, or {@code null} when unbounded. */
		@Getter @Accessors(fluent = true) final Integer min;
		/** The {@code @Range} upper bound, or {@code null} when unbounded. */
		@Getter @Accessors(fluent = true) final Integer max;
	}

	private static final Map<String, Meta> META = load();

	public static Meta of(String key)
	{
		return META.get(key);
	}

	private static Map<String, Meta> load()
	{
		Map<String, Meta> meta = new HashMap<>();
		try
		{
			// '#' rows absent in config-items.tsv — skip-set widened to the shared reader's
			Util.each("/config-items.tsv", (line, cols) ->
			{
				String key = cols[0];
				String name = cols.length > 1 ? cols[1] : "";
				String description = cols.length > 2 ? cols[2] : "";
				Integer min = cols.length > 3 && !cols[3].isEmpty() ? Integer.valueOf(cols[3]) : null;
				Integer max = cols.length > 4 && !cols[4].isEmpty() ? Integer.valueOf(cols[4]) : null;
				meta.put(key, new Meta(key, name, description, min, max));
			});
		}
		catch (Exception e)
		{
			throw new IllegalStateException("failed to load config-items.tsv", e);
		}
		return meta;
	}
}

