	USE_HOT_AIR_BALLOONS,
	USE_MAGIC_CARPETS,
	USE_MAGIC_MUSHTREES,
	USE_MINECARTS,
	USE_QUETZALS,
	USE_SPIRIT_TREES,
	USE_TELEPORTATION_ITEMS,
	USE_TELEPORTATION_LEVERS,
	USE_TELEPORTATION_PORTALS,
	USE_TELEPORTATION_SPELLS,
	USE_TELEPORTATION_SPELLS_HOME,
	USE_TELEPORTATION_MINIGAMES,
	USE_WILDERNESS_OBELISKS,
	USE_SEASONAL_TRANSPORTS,
	RESPAWN_PRIFDDINAS,
	UNLOCK_CANOE_AXE,
	UNLOCK_XERICS_HONOUR,
	UNLOCK_DRAGONTOOTH_PASSAGE,
	UNLOCK_MOR_UL_REK,
	INCLUDE_BANK_PATH,
	CURRENCY_THRESHOLD,
	CANCEL_INSTEAD,
	RECALCULATE_DISTANCE,
	FINISH_DISTANCE,
	UNREACHABLE_TARGET_DISTANCE_THRESHOLD,
	SHOW_UNREACHABLE_TEXT,
	SHOW_TILE_COUNTER,
	TILE_COUNTER_STEP,
	CALCULATION_CUTOFF,
	A_STAR_HEURISTIC_WEIGHT,
	COLLISION_AWARE_BLOCKED_TARGETS,
	USE_SAILING_MOVES,
	SHOW_TRANSPORT_INFO,
	SHOW_BANK_PICKUP_INFO,
	HIGHLIGHT_BANK_PICKUP_ITEMS,
	HIGHLIGHT_SPELLBOOK_SPELLS,
	HIGHLIGHT_INVENTORY_ITEMS,
	USE_POH,
	USE_POH_FAIRY_RING,
	USE_POH_SPIRIT_TREE,
	USE_TELEPORTATION_PORTALS_POH,
	POH_NEXUS_PORTALS,
	POH_JEWELLERY_BOX_TIER,
	POH_MOUNTED_ITEMS,
	USE_POH_MOUNTED_ITEMS,
	USE_POH_OBELISK,
	COST_AGILITY_SHORTCUTS,
	COST_GRAPPLE_SHORTCUTS,
	COST_BOATS,
	COST_CANOES,
	COST_CHARTER_SHIPS,
	COST_SHIPS,
	COST_FAIRY_RINGS,
	COST_GNOME_GLIDERS,
	COST_HOT_AIR_BALLOONS,
	COST_MAGIC_CARPETS,
	COST_MAGIC_MUSHTREES,
	COST_MINECARTS,
	COST_QUETZALS,
	COST_QUETZAL_WHISTLE,
	COST_SPIRIT_TREES,
	COST_NON_CONSUMABLE_TELEPORTATION_ITEMS,
	COST_CONSUMABLE_TELEPORTATION_ITEMS,
	COST_TELEPORTATION_BOXES,
	COST_TELEPORTATION_LEVERS,
	COST_TELEPORTATION_PORTALS,
	COST_TELEPORTATION_SPELLS,
	COST_TELEPORTATION_SPELLS_HOME,
	COST_TELEPORTATION_MINIGAMES,
	COST_WILDERNESS_OBELISKS,
	COST_SEASONAL_TRANSPORTS,
	COST_BANK_VISIT,
	DRAW_MAP,
	DRAW_MINIMAP,
	DRAW_TILES,
	DRAW_CLICK_POINTS,
	PATH_STYLE,
	SHOW_TELEPORT_PULSE,
	COLOUR_PATH,
	COLOUR_PATH_CALCULATING,
	COLOUR_PATH_UNREACHABLE,
	COLOUR_TRANSPORTS,
	COLOUR_COLLISION_MAP,
	COLOUR_TEXT,
	COLOUR_TELEPORT_PULSE,
	COLOUR_BANK_PICKUP_HIGHLIGHT,
	DRAW_TRANSPORTS,
	DRAW_COLLISION_MAP,
	DRAW_DEBUG_PANEL,
	POST_TRANSPORTS,
	UNREACHABLE_TEXT,
	BUILT_TELEPORTATION_BOXES,
	BUILT_TELEPORTATION_PORTALS_POH,
	BLOCKED_TELEPORT_ITEMS,
	UNLOCK_BALLOON_LOG_BASKET,
	BALLOON_LOG_BASKET_ROUTES;

	private final String key;
	private final Class<?> type;
	private final Class<? extends Enum> element;
	private final Object def;
	/** The boolean key a {@code flag:} set default follows, or null. */
	@Getter(lombok.AccessLevel.NONE)
	private final String flagKey;
	private final Set<Effect> effects;

	@SuppressWarnings({"unchecked", "rawtypes"})
	ConfigKey()
	{
		String[] cols = Rows.BY_NAME.get(name());
		if (cols == null)
		{
			throw new IllegalStateException("no config-keys.tsv row for " + name());
		}
		key = cols[1];
		type = Rows.TYPES.get(cols[2]);
		element = cols[3].isEmpty() ? null : Rows.ELEMENTS.get(cols[3]);
		if (type == null || (type == Set.class) != (element != null))
		{
			throw new IllegalStateException("bad type for " + name());
		}
		String def = cols[4];
		flagKey = def.startsWith("flag:") ? def.substring("flag:".length()) : null;
		if (flagKey != null || type == String.class)
		{
			this.def = flagKey != null ? null : def;
		}
		else if (type == Boolean.class)
		{
			this.def = Boolean.valueOf(def);
		}
		else if (type == Integer.class)
		{
			this.def = Integer.valueOf(def);
		}
		else if (type == Color.class)
		{
			this.def = ColorUtil.fromHex(def);
		}
		else
		{
			this.def = Enum.valueOf((Class) type, def);
		}
		Set<Effect> effects = EnumSet.noneOf(Effect.class);
		for (String effect : cols[5].split(","))
		{
			effects.add(Effect.valueOf(effect));
		}
		this.effects = Collections.unmodifiableSet(effects);
	}

	public static ConfigKey forKey(String key)
	{
		return Rows.NAMES.containsKey(key) ? valueOf(Rows.NAMES.get(key)) : null;
	}

	/** The value stored for this key, or null when it was never written or does not parse. */
	Object read(ConfigManager configManager)
	{
		return type == Set.class
			? parseSet(configManager.getConfiguration(Settings.CONFIG_GROUP, key), element)
			: configManager.getConfiguration(Settings.CONFIG_GROUP, key, type);
	}

	/** {@code value} if it has this key's type (enum keys also take their display name), otherwise null. */
	Object coerce(Object value)
	{
		if (value instanceof String && type.isEnum())
		{
			for (Object constant : type.getEnumConstants())
			{
				if (constant.toString().equals(value))
				{
					return constant;
				}
			}
		}
		return type.isInstance(value) ? value : null;
	}

	/** The boolean key a {@code flag:} set default follows, or null. */
	public ConfigKey getFlag()
	{
		return flagKey == null ? null : forKey(flagKey);
	}

	@SuppressWarnings({"unchecked", "rawtypes"})
	Set<?> flagDefault(boolean on)
	{
		return on ? EnumSet.allOf(element) : EnumSet.noneOf(element);
	}

	/** Parses the {@code ["A", "B"]} form a stored enum set takes; null when unset or malformed. */
	@SuppressWarnings({"unchecked", "rawtypes"})
	public static Set<?> parseSet(String stored, Class<? extends Enum> element)
	{
		if (stored == null || !stored.trim().startsWith("[") || !stored.trim().endsWith("]"))
		{
			return null;
		}
		String inner = stored.trim();
		inner = inner.substring(1, inner.length() - 1).trim();
		EnumSet out = EnumSet.noneOf(element);
		if (inner.isEmpty())
		{
			return out;
		}
		try
		{
			for (String token : inner.split(","))
			{
				token = token.trim();
				if (token.length() < 2 || token.charAt(0) != '"' || token.charAt(token.length() - 1) != '"')
				{
					return null;
				}
				out.add(Enum.valueOf(element, token.substring(1, token.length() - 1)));
			}
		}
		catch (RuntimeException e)
		{
			return null;
		}
		return out;
	}

	private static final class Rows
	{
		private static final Map<String, String[]> BY_NAME = new HashMap<>();
		/** Persisted key name to enum constant name. */
		private static final Map<String, String> NAMES = new HashMap<>();
		private static final Map<String, Class<?>> TYPES = Map.of(
			"boolean", Boolean.class,
			"int", Integer.class,
			"String", String.class,
			"Color", Color.class,
			"Set", Set.class,
			"TeleportationItem", TeleportationItem.class,
			"TileCounter", TileCounter.class,
			"TileStyle", TileStyle.class,
			"JewelleryBoxTier", JewelleryBoxTier.class);
		private static final Map<String, Class<? extends Enum>> ELEMENTS = Map.of(
			"PohNexusPortal", PohNexusPortal.class,
			"PohMountedItem", PohMountedItem.class,
			"BalloonRoute", BalloonRoute.class);

		static
		{
			try
			{
				Util.each("/config-keys.tsv", (line, cols) ->
				{
					if (cols.length != 6 || BY_NAME.put(cols[0], cols) != null || NAMES.put(cols[1], cols[0]) != null)
					{
						throw new IllegalStateException("bad config-keys.tsv row: " + line);
					}
				});
			}
			catch (Exception e)
			{
				throw new IllegalStateException("failed to load config-keys.tsv", e);
			}
		}
	}
}

package shortestpath.settings;

/**
 * The consequences an observed change carries for the plugin shell — whether
 * the change came from a config key (via {@link ConfigChange}) or from a
 * producer observing game state (via the item-state change facts). A change
 * fact carries the set of effects it triggers; the shell decides how to act
 * on them.
 */
public enum Effect
{
	/** The running search can no longer be trusted; pathfinding must restart. */
	ROUTE_INVALIDATING,
	/** The debug overlay panel must be added to or removed from the overlay manager. */
	SIDE_EFFECT_DEBUG_OVERLAY,
	/** No shell side effect; a running search continues. */
	DISPLAY_ONLY,
	/** The eligibility snapshot is stale; the engine rebuilds it lazily. */
	ELIGIBILITY_STALE
}

package shortestpath.settings;

/**
 * Stored values for {@link Settings#wrap}, which has no {@code ConfigManager}:
 * test stub configs implement this.
 */
public interface KeyedValues
{
	/** The typed stored value for {@code keyName}, or null when it was never written. */
	Object value(String keyName);
}

package shortestpath.settings;

import java.util.*;
import java.util.concurrent.*;
import java.util.function.Function;

import javax.inject.*;
import javax.swing.SwingUtilities;

import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.*;
import net.runelite.client.events.ConfigChanged;
import shortestpath.ShortestPathConfig;

/**
 * Reads and writes the plugin's settings. A key's value is, in order: the
 * override another plugin sent through the plugin-message API (when it has
 * the key's type), the stored value, then the key's default.
 *
 * <p>The sidebar panel edits stored values with {@link #write} and shows them
 * with {@link #configured}, which ignores overrides.
 *
 * <p>This package is a leaf: it must not reference the plugin class.
 */
@Singleton
@Slf4j
public class Settings
{
	public static final String CONFIG_GROUP = "shortestpath";

	private final ConfigManager configManager;
	/** A key's stored value, or null when it was never written. */
	private final Function<ConfigKey, Object> stored;
	/** Stored values read since the last config change; overlays read settings every frame. */
	private final Map<ConfigKey, Optional<Object>> cache = new ConcurrentHashMap<>();
	private final Map<String, ConfigItemDescriptor> itemDescriptors = new HashMap<>();
	/** The overrides as received, unknown keys included, so they can be echoed back. */
	@Getter
	private volatile Map<String, Object> overrides = Map.of();
	private final Map<String, List<Runnable>> listeners = new ConcurrentHashMap<>();
	private final Map<String, Thread> writeInFlight = new ConcurrentHashMap<>();

	@Inject
	public Settings(ConfigManager configManager, ShortestPathConfig config)
	{
		this.configManager = configManager;
		this.stored = key -> cache.computeIfAbsent(key, k -> Optional.ofNullable(k.read(configManager))).orElse(null);
		ConfigDescriptor descriptor = configManager.getConfigDescriptor(config);
		for (ConfigItemDescriptor item : descriptor == null ? List.<ConfigItemDescriptor>of() : descriptor.getItems())
		{
			itemDescriptors.putIfAbsent(item.key(), item);
		}
	}

	private Settings(ConfigManager configManager, Function<ConfigKey, Object> stored)
	{
		this.configManager = configManager;
		this.stored = stored;
	}

	/**
	 * Settings for tests: stored values come from {@code config} when it is a
	 * {@link KeyedValues}, otherwise every key reads its default. Writes go to
	 * {@code configManager}, which may be null.
	 */
	public static Settings wrap(ConfigManager configManager, ShortestPathConfig config)
	{
		return new Settings(configManager, config instanceof KeyedValues
			? key -> ((KeyedValues) config).value(key.getKey())
			: key -> null);
	}

	public static Settings wrap(ShortestPathConfig config)
	{
		return wrap(null, config);
	}

	/** The value routing and drawing use: override, else stored, else default. */
	@SuppressWarnings("unchecked")
	public <T> T get(ConfigKey key)
	{
		Object value = key.coerce(overrides.get(key.getKey()));
		return (T) (value != null ? value : storedOrDefault(key, true));
	}

	public boolean bool(ConfigKey key)
	{
		return Boolean.TRUE.equals(get(key));
	}

	public int num(ConfigKey key)
	{
		Object value = get(key);
		return value instanceof Number ? ((Number) value).intValue() : 0;
	}

	/** The value the player configured, ignoring overrides: stored, else default. */
	@SuppressWarnings("unchecked")
	public <T> T configured(String key)
	{
		ConfigKey row = ConfigKey.forKey(key);
		if (row == null)
		{
			throw new IllegalArgumentException("unknown config key: " + key);
		}
		return (T) storedOrDefault(row, false);
	}

	private Object storedOrDefault(ConfigKey key, boolean withOverrides)
	{
		Object value = stored.apply(key);
		if (value != null)
		{
			return value;
		}
		ConfigKey flag = key.getFlag();
		if (flag == null)
		{
			return key.getDef();
		}
		return key.flagDefault(withOverrides ? bool(flag) : Boolean.TRUE.equals(storedOrDefault(flag, false)));
	}

	public void applyOverrides(Map<String, Object> payload)
	{
		if (payload != null && !payload.isEmpty())
		{
			overrides = Collections.unmodifiableMap(new HashMap<>(payload));
		}
	}

	public void clearOverrides()
	{
		overrides = Map.of();
	}

	/** Panel metadata for a key: the bundled {@code config-items.tsv} row, else the {@code @ConfigItem}. */
	public ConfigItems.Meta item(String key)
	{
		ConfigItems.Meta meta = ConfigItems.of(key);
		ConfigItemDescriptor descriptor = itemDescriptors.get(key);
		if (meta != null || descriptor == null)
		{
			return meta;
		}
		Range range = descriptor.getRange();
		return new ConfigItems.Meta(key, descriptor.getItem().name(), descriptor.getItem().description(),
			range == null ? null : range.min(), range == null ? null : range.max());
	}

	/**
	 * Stores a value and runs the key's listeners now. The {@link ConfigChanged}
	 * echo of this write does not run them a second time.
	 */
	public void write(String key, Object value)
	{
		if (configManager == null)
		{
			throw new UnsupportedOperationException("settings without a config manager cannot write");
		}
		writeInFlight.put(key, Thread.currentThread());
		try
		{
			configManager.setConfiguration(CONFIG_GROUP, key, value);
			cache.clear();
			fireListeners(key);
		}
		finally
		{
			writeInFlight.remove(key);
		}
	}

	/** Runs {@code listener} whenever {@code key} changes; the returned runnable unregisters it. */
	public Runnable listen(String key, Runnable listener)
	{
		listeners.compute(key, (k, keyed) ->
		{
			keyed = keyed != null ? keyed : new CopyOnWriteArrayList<>();
			keyed.add(listener);
			return keyed;
		});
		return () -> listeners.computeIfPresent(key, (k, keyed) ->
		{
			keyed.remove(listener);
			return keyed.isEmpty() ? null : keyed;
		});
	}

	void fireListeners(String key)
	{
		for (Runnable listener : listeners.getOrDefault(key, List.of()))
		{
			try
			{
				listener.run();
			}
			catch (RuntimeException e)
			{
				log.warn("settings listener for key {} threw; continuing with remaining listeners", key, e);
			}
		}
	}

	/** The change a config event makes, or null when it is for another plugin. */
	public ConfigChange onConfigChanged(ConfigChanged event)
	{
		if (event == null || !CONFIG_GROUP.equals(event.getGroup()))
		{
			return null;
		}
		cache.clear();
		String key = event.getKey();
		if (writeInFlight.get(key) != Thread.currentThread() && listeners.containsKey(key))
		{
			SwingUtilities.invokeLater(() -> fireListeners(key));
		}
		ConfigKey row = ConfigKey.forKey(key);
		return new ConfigChange(key, row == null ? Set.of() : row.getEffects());
	}
}

