package shortestpath.spirittree;

import java.util.*;

/**
 * Parsed contents of one spirit tree travel menu: every patch row the
 * menu showed ({@link #listed}) and the subset usable right now
 * ({@link #available} — a greyed row means planted but not usable).
 */
final class SpiritTreeMenuSnapshot
{
	final Set<String> listed = new HashSet<>();
	final Set<String> available = new HashSet<>();
}

package shortestpath.spirittree;

import java.util.*;
import java.util.regex.*;
import javax.inject.*;
import lombok.*;
import net.runelite.api.*;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.client.util.Text;
import net.runelite.client.config.ConfigManager;
import shortestpath.requirement.*;
import shortestpath.scheduler.RefreshCoordinator;
import shortestpath.settings.Effect;
import shortestpath.widgets.GameWidgets;

/**
 * Per-account availability state for the five plantable spirit tree patches
 * (Port Sarim, Etceteria, Brimhaven, Hosidius, Farming Guild). Detection is a
 * union of three sources:
 * <ul>
 *   <li>in-region {@code FARMING_TRANSMIT_*} varbit samples — authoritative, but
 *       only while the player stands in the patch's region: those varbits are
 *       region-scoped scratch slots shared between patches (A serves Port Sarim
 *       and Farming Guild, B serves Etceteria and Brimhaven), so reading them
 *       for any other region would corrupt a different patch's state.</li>
 *   <li>the spirit tree travel menu parse — authoritative for the patches it
 *       lists (a greyed row means planted but not usable).</li>
 *   <li>RSProfile-persisted observations, so discovered trees stay routable
 *       across client restarts.</li>
 * </ul>
 * A stale positive is worse than a miss for a router, so any authoritative
 * observation that reports a patch cleared, diseased, dead, or not grown
 * evicts the persisted travelable entry for that patch.
 */
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class SpiritTreeService
{
	/**
	 * The persisted config group — mirrors the {@code @ConfigGroup} value on
	 * {@link shortestpath.ShortestPathConfig}. Kept as a literal so this leaf
	 * package neither reads annotations reflectively nor references the plugin
	 * class; a divergence would surface as every persisted read/write missing
	 * its namespace.
	 */
	private static final String CONFIG_GROUP = "shortestpath";
	private static final String CONFIG_KEY_PREFIX = "spiritTree.";

	private static final Pattern SPIRIT_TREE_LABEL_PATTERN_MENU = Pattern.compile("<col=735a28>(.+)</col>: (<col=5f5f5f>)?(.+)");
	private static final Pattern SPIRIT_TREE_LABEL_PATTERN_MENU_NEW = Pattern.compile("<col=ffffff>(.+)</col>: (<col=5f5f5f>)?(.+)");

	// Patch metadata (region-scoped varbit + tile bounds) lives on the
	// requirement side in SpiritTreePatches — this service reads it through
	// the one-way spirittree -> requirement edge.

	private final ConfigManager configManager;
	private final Client client;
	private final RefreshCoordinator coordinator;
	private final GameWidgets gameWidgets;
	// patch name -> last observed availability value (20 = grown and
	// travelable). Published as immutable snapshots (copy-on-write writes)
	// so readers on any thread can never iterate a half-mutated map.
	private volatile Map<String, Integer> observedValues = Map.of();
	private volatile Map<String, Integer> lastPersistedValues = Map.of();
	private boolean dirty;
	// Player region seen on the previous game tick (and at which tick), and
	// the region considered settled for transmit-slot sampling.
	private int lastPlayerRegionID = -1;
	private int lastPlayerRegionTick = -1;
	private int settledRegionID = -1;

	/**
	 * The resolved travelable-tree set as last published. Tri-state by
	 * contract: {@code null} while no detection source has produced an
	 * observation (consumers stay conservative), an empty set when every
	 * observed patch reported unusable, and the resolved names otherwise.
	 * The returned set is immutable — publication is a single volatile
	 * write; the engine's capture step reads it through
	 * {@code getAvailableSpiritTrees()}.
	 */
	@Getter private volatile Set<String> availableSpiritTrees;

	/**
	 * Detached-widgets seam for tests that exercise the service without the
	 * menu scrape — the menu read no-ops on the missing service.
	 */
	SpiritTreeService(ConfigManager configManager, Client client,
		RefreshCoordinator coordinator)
	{
		this(configManager, client, coordinator, null);
	}

	/**
	 * Detached-coordinator seam for tests that exercise the service's state
	 * and persistence without asserting declares — the declare no-ops on the
	 * missing coordinator.
	 */
	SpiritTreeService(ConfigManager configManager, Client client)
	{
		this(configManager, client, null, null);
	}

	static boolean spiritTreeTravelable(int varbitValue)
	{
		// Matches PatchImplementation.SPIRIT_TREE: 0-7 weeds, 8-19 growing,
		// 21-31 diseased, 32-43 dead, 44 grown but check-health-only,
		// 45-63 weeds. Only exactly 20 is a grown, travelable tree.
		return varbitValue == 20;
	}

	/**
	 * Records the player's region for this game tick. The
	 * {@code FARMING_TRANSMIT_*} slots are repopulated for the new region
	 * after a region change, so a read taken on the entry tick can still
	 * carry the previous region's patch values. Sampling is only allowed
	 * once the same region has been seen on two consecutive ticks —
	 * {@link #isRegionSettled(int)}. Pass -1 when the player location is
	 * unknown; any gap (region change, loading tick, logout) un-settles.
	 * (Same region-stability guard as TimeTrackingPlugin.onGameTick.)
	 */
	void notePlayerRegion(int regionID, int tickCount)
	{
		settledRegionID = regionID != -1
			&& regionID == lastPlayerRegionID
			&& tickCount == lastPlayerRegionTick + 1
			? regionID : -1;
		lastPlayerRegionID = regionID;
		lastPlayerRegionTick = tickCount;
	}

	/**
	 * Whether the given region has been the player's region for at least two
	 * consecutive recorded ticks — i.e. a {@code FARMING_TRANSMIT_*} read for
	 * that region can no longer be a stale leftover from the previous region.
	 */
	boolean isRegionSettled(int regionID)
	{
		return regionID != -1 && settledRegionID == regionID;
	}

	static String configKey(String patchName)
	{
		if (!SpiritTreePatches.isPatch(patchName))
		{
			return null;
		}
		return CONFIG_KEY_PREFIX + SpiritTreePatches.regionForPatch(patchName)
			+ "." + SpiritTreePatches.varbitForPatch(patchName);
	}

	/**
	 * Persisted value shape, mirroring the FarmingTracker:
	 * {@code "<value>:<unixtime>"}.
	 */
	static String serializeObserved(int value, long unixTimeSeconds)
	{
		return value + ":" + unixTimeSeconds;
	}

	/**
	 * Strict inverse of {@link #serializeObserved}: returns the stored value,
	 * or null for anything malformed — persisted config is untrusted input.
	 */
	static Integer parseStoredValue(String stored)
	{
		if (stored == null || stored.isEmpty())
		{
			return null;
		}
		int split = stored.indexOf(':');
		if (split <= 0 || split == stored.length() - 1)
		{
			return null;
		}
		String valueText = stored.substring(0, split);
		String timeText = stored.substring(split + 1);
		if (timeText.indexOf(':') >= 0)
		{
			return null;
		}
		try
		{
			int value = Integer.parseInt(valueText);
			Long.parseLong(timeText);
			return value;
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}

	/**
	 * Applies an in-region varbit sample for one patch. The caller must only
	 * call this while the player is inside the patch's mapped region — the
	 * varbits are region-scoped and mean different patches elsewhere.
	 * Returns a route-invalidating fact when the resolved set of travelable
	 * trees changed, null otherwise.
	 */
	TreeChange applyVarbitSample(String patchName, int varbitValue)
	{
		if (!SpiritTreePatches.isPatch(patchName))
		{
			return null;
		}
		boolean before = isTravelable(patchName);
		Integer previous = observedValues.get(patchName);
		if (previous == null || previous.intValue() != varbitValue)
		{
			Map<String, Integer> next = new HashMap<>(observedValues);
			next.put(patchName, varbitValue);
			observedValues = Collections.unmodifiableMap(next);
			dirty = true;
		}
		return isTravelable(patchName) != before
			? new TreeChange("varbit:" + patchName, Set.of(Effect.ROUTE_INVALIDATING))
			: null;
	}

	/**
	 * Applies a travel-menu parse. The menu is authoritative for the patches it
	 * lists (greyed or not); patches it does not list keep their existing
	 * state — a partial snapshot never shrinks unvisited entries.
	 * Returns a route-invalidating fact when the resolved set of travelable
	 * trees changed, null otherwise.
	 */
	TreeChange applyMenuSnapshot(Set<String> listedTreeNames, Set<String> availableTreeNames)
	{
		if (listedTreeNames == null || availableTreeNames == null)
		{
			return null;
		}
		boolean changed = false;
		for (String name : listedTreeNames)
		{
			if (!SpiritTreePatches.isPatch(name))
			{
				continue;
			}
			changed |= applyVarbitSample(name, availableTreeNames.contains(name) ? 20 : 0) != null;
		}
		return changed
			? new TreeChange("menu", Set.of(Effect.ROUTE_INVALIDATING))
			: null;
	}

	/**
	 * The union of all detection sources: planted patches currently known to be
	 * grown and usable. Empty when nothing observed is travelable.
	 */
	public Set<String> getTravelableTrees()
	{
		Set<String> trees = new HashSet<>();
		for (Map.Entry<String, Integer> entry : observedValues.entrySet())
		{
			if (spiritTreeTravelable(entry.getValue()))
			{
				trees.add(entry.getKey());
			}
		}
		return trees;
	}

	/**
	 * Same as {@link #getTravelableTrees} but null while no detection source has
	 * produced any observation — lets the consumer stay conservative
	 * ("never checked") instead of asserting an empty set.
	 */
	public Set<String> getTravelableTreesOrNull()
	{
		return observedValues.isEmpty() ? null : getTravelableTrees();
	}

	/**
	 * Seeds the published set for harnesses and tests — the detached refresh
	 * arm merges live samples into it. Never called in production. The set
	 * is defensively copied like {@link #publish} does, so a caller mutating
	 * its argument later cannot silently change published state.
	 */
	public void setAvailableSpiritTreesForTest(Set<String> trees)
	{
		this.availableSpiritTrees = trees == null ? null : Set.copyOf(trees);
	}

	/**
	 * Resolves the effective travelable set from every detection source — a
	 * live in-region {@code FARMING_TRANSMIT_*} varbit sample, recorded
	 * observations (RSProfile persistence + menu union), or — when the
	 * service runs detached (no config manager: tests, dashboard harness)
	 * — the live sample merged into the published set alone. An empty
	 * resolved set means every observed patch reported unusable and blocks
	 * planted-tree transports honestly; the unresolved {@code null} is kept
	 * while no source has produced any observation.
	 * <p>
	 * Client thread only, called from the engine's transport refresh.
	 */
	public void refreshAvailability(PlayerStateSource source)
	{
		String inRegionPatch = null;
		WorldPoint worldLocation = source.localPlayerWorldLocation();
		// Varbits are not transmitted while a modal widget is open; skip the
		// live sample (but not the patch-state resolution below) rather than
		// attribute a stale shared-slot value to the wrong patch. On the
		// region-entry tick the slot can likewise still carry the previous
		// region's values, so a tracked service samples only once the region
		// has settled; a detached service has no settled record to gate on.
		if (worldLocation != null && !source.modalWidgetOpen()
			&& (configManager == null
				|| isRegionSettled(worldLocation.getRegionID())))
		{
			inRegionPatch = SpiritTreePatches.patchNameForRegion(worldLocation.getRegionID());
		}

		if (configManager != null)
		{
			if (inRegionPatch != null)
			{
				// In-region sample is authoritative for this patch — a non-20
				// read evicts any stale persisted or menu-derived positive.
				applyVarbitSample(inRegionPatch,
					source.varbit(SpiritTreePatches.varbitForPatch(inRegionPatch)));
			}
			Set<String> resolved = getTravelableTreesOrNull();
			if (resolved != null)
			{
				publish(resolved);
			}
		}
		else if (inRegionPatch != null)
		{
			int varbitValue = source.varbit(SpiritTreePatches.varbitForPatch(inRegionPatch));
			Set<String> resolved = availableSpiritTrees == null
				? new HashSet<>() : new HashSet<>(availableSpiritTrees);
			if (spiritTreeTravelable(varbitValue))
			{
				resolved.add(inRegionPatch);
			}
			else
			{
				resolved.remove(inRegionPatch);
			}
			publish(resolved);
		}
	}

	/**
	 * Per-tick driver: notes the player's region, samples the in-region
	 * patch varbit once the region has settled, flushes persistence, and
	 * declares a route-invalidating fact to the coordinator when the
	 * resolved set changed.
	 */
	public void onGameTick()
	{
		if (client == null)
		{
			return;
		}

		Player localPlayer = client.getLocalPlayer();
		WorldPoint worldLocation = localPlayer == null ? null : localPlayer.getWorldLocation();
		int playerRegion = worldLocation == null ? -1 : worldLocation.getRegionID();
		notePlayerRegion(playerRegion, client.getTickCount());
		TreeChange change = null;
		if (localPlayer != null
			// Varbits are not transmitted while a modal widget is open; a stale
			// read of the shared slot could carry another patch's value.
			&& !ClientPlayerStateSource.modalWidgetOpen(client)
			// On the region-entry tick the slot can still carry the previous
			// region's values; only sample once the region has settled.
			&& isRegionSettled(playerRegion))
		{
			// The FARMING_TRANSMIT_* varbits are region-scoped scratch slots, so
			// a planted spirit tree's varbit is only meaningful while standing in
			// that patch's region. Sample only on a region match.
			String spiritTreePatch = SpiritTreePatches.patchNameForRegion(playerRegion);
			if (spiritTreePatch != null)
			{
				change = applyVarbitSample(spiritTreePatch,
					client.getVarbitValue(SpiritTreePatches.varbitForPatch(spiritTreePatch)));
				if (change != null)
				{
					publish(getTravelableTrees());
				}
			}
		}

		// Persist after the same-tick sample so a fresh observation is written
		// on this tick rather than waiting for the next one.
		persistIfDirty();

		declare(change);
	}

	/**
	 * Scrapes a freshly opened spirit tree travel menu and applies the
	 * listed/available snapshot. Declares a route-invalidating fact to the
	 * coordinator when the resolved set changed; unrelated menus and
	 * unchanged parses declare nothing.
	 */
	public void onMenuOpened(boolean useNewMenu)
	{
		// Referencing
		// https://github.com/trs/runelite-teleport-maps/blob/e006270494500ab8e4826903b377bb945ca9fc96/src/main/java/com/mjhylkema/TeleportMaps/components/adventureLog/SpiritTreeMap.java#L141

		if (gameWidgets == null)
		{
			return;
		}

		List<String> texts = useNewMenu
			? gameWidgets.childTexts(InterfaceID.MENU_NEW, 9)
			: gameWidgets.childTexts(InterfaceID.MENU, 3);
		if (texts.isEmpty())
		{
			return;
		}

		// Tree Gnome Village is always the first row and always available, so an
		// exact content match identifies the spirit tree menu. Interface group
		// MENU is a shared container (other MISCB_IF users load on the same
		// group), and this parse now runs on every load, so a loose check could
		// persist a false observation from an unrelated interface.
		String expectedFirstRow =
			(useNewMenu ? "<col=ffffff>1</col>: " : "<col=735a28>1</col>: ") + "Tree Gnome Village";
		if (!expectedFirstRow.equals(texts.get(0)))
		{
			return;
		}

		SpiritTreeMenuSnapshot snapshot = parseSpiritTreeMenuRows(texts, useNewMenu);

		// The menu is authoritative for the patches it lists; persisted and
		// in-region-varbit observations fill the patches the menu never covered.
		TreeChange change = applyMenuSnapshot(snapshot.listed, snapshot.available);
		if (change != null)
		{
			publish(getTravelableTrees());
		}
		declare(change);
	}

	/**
	 * Parses the ordered row texts of a spirit tree menu container into the
	 * listed/available patch-name sets. Package-private for tests.
	 */
	static SpiritTreeMenuSnapshot parseSpiritTreeMenuRows(List<String> texts, boolean useNewMenu)
	{
		Pattern pattern = useNewMenu ? SPIRIT_TREE_LABEL_PATTERN_MENU_NEW : SPIRIT_TREE_LABEL_PATTERN_MENU;
		SpiritTreeMenuSnapshot snapshot = new SpiritTreeMenuSnapshot();

		for (String text : texts)
		{
			if (text == null)
			{
				continue;
			}
			Matcher matcher = pattern.matcher(text);
			if (!matcher.matches())
			{
				continue;
			}

			// Group 3 is spirit tree name; a greyed row can leave markup on it
			// (e.g. "Port Sarim</col>"), which would miss the patch table and
			// silently drop the row's eviction signal — strip tags before use.
			String name = Text.removeTags(matcher.group(3)).trim();
			snapshot.listed.add(name);

			// Group 2 is the disabled color tag; if present, the tree is unavailable
			if (matcher.group(2) != null)
			{
				continue;
			}

			snapshot.available.add(name);
		}

		return snapshot;
	}

	/**
	 * Reloads the persisted observations for the active profile. A profile
	 * reload always re-resolves state, so the declared fact is
	 * unconditional, matching the unconditional restart the shell used to
	 * apply.
	 */
	public void loadFromProfile()
	{
		dirty = false;
		// Build the replacement maps locally and publish them as one
		// assignment each — a concurrent reader sees the old or the new
		// snapshot, never a cleared or half-repopulated map.
		Map<String, Integer> observed = new HashMap<>();
		Map<String, Integer> persisted = new HashMap<>();
		if (configManager != null)
		{
			for (String patchName : SpiritTreePatches.patchNames())
			{
				String stored = configManager.getRSProfileConfiguration(
					CONFIG_GROUP, configKey(patchName));
				Integer value = parseStoredValue(stored);
				if (value != null)
				{
					observed.put(patchName, value);
					persisted.put(patchName, value);
				}
			}
		}
		observedValues = Map.copyOf(observed);
		lastPersistedValues = Map.copyOf(persisted);
		// A profile reload always re-resolves state — the declared fact is
		// unconditional, matching the shell's unconditional restart today.
		publish(getTravelableTreesOrNull());
		declare(new TreeChange("profile", Set.of(Effect.ROUTE_INVALIDATING)));
	}

	public void persistIfDirty()
	{
		if (!dirty)
		{
			return;
		}
		dirty = false;
		if (configManager == null)
		{
			return;
		}
		long now = System.currentTimeMillis() / 1000L;
		Map<String, Integer> persisted = new HashMap<>(lastPersistedValues);
		for (Map.Entry<String, Integer> entry : observedValues.entrySet())
		{
			Integer last = persisted.get(entry.getKey());
			if (spiritTreeTravelable(entry.getValue()))
			{
				if (last != null && last.equals(entry.getValue()))
				{
					continue;
				}
				configManager.setRSProfileConfiguration(CONFIG_GROUP,
					configKey(entry.getKey()), serializeObserved(entry.getValue(), now));
				persisted.put(entry.getKey(), entry.getValue());
			}
			else if (last != null)
			{
				// An absent key means "never observed", so a non-travelable
				// observation removes the entry — including a legacy "0:<ts>"
				// residue — rather than leaving a dead value on the profile.
				// lastPersistedValues holds no marker for an absent key, so a
				// repeat non-travelable flush does not unset twice.
				configManager.unsetRSProfileConfiguration(CONFIG_GROUP,
					configKey(entry.getKey()));
				persisted.remove(entry.getKey());
			}
		}
		lastPersistedValues = Map.copyOf(persisted);
	}

	/**
	 * Hands an admitted fact to the refresh coordinator. Detached
	 * instances (built with a null coordinator) carry none, so the declare
	 * no-ops there; a null fact declares nothing, mirroring the return-null
	 * convention the shell's mapper used to guard.
	 */
	private void declare(TreeChange change)
	{
		if (change != null && coordinator != null)
		{
			coordinator.treeSetChanged(change);
		}
	}

	/**
	 * Single-point publication of the resolved set: one volatile write of an
	 * immutable copy, so a reader on the pathfinder thread can never observe
	 * a half-built set. {@code null} publishes the unresolved state verbatim.
	 */
	private void publish(Set<String> resolved)
	{
		availableSpiritTrees = resolved == null ? null : Set.copyOf(resolved);
	}

	private boolean isTravelable(String patchName)
	{
		Integer value = observedValues.get(patchName);
		return value != null && spiritTreeTravelable(value);
	}
}

package shortestpath.spirittree;

import java.util.*;

import lombok.Getter;

import shortestpath.settings.Effect;

/**
 * An immutable fact describing a single spirit-tree state change: the input
 * that changed (keyed as {@code "varbit:<patch>"} for an in-region sample,
 * {@code "menu"} for a travel-menu parse, or {@code "profile"} for an
 * RSProfile reload) and the {@link Effect}s it triggers. Produced by
 * {@link SpiritTreeService}; the shell reads the effect set to decide which
 * follow-up actions to run rather than re-deriving them from the event.
 *
 * <p>Spirit trees only ever emit {@link Effect#ROUTE_INVALIDATING}: a changed
 * tree set can invalidate a running path but never alters item or quest
 * eligibility, so {@code ELIGIBILITY_STALE} is never present.
 */
@Getter
public final class TreeChange
{
	private final String key;
	private final Set<Effect> effects;

	TreeChange(String key, Set<Effect> effects)
	{
		this.key = Objects.requireNonNull(key);
		this.effects = Set.copyOf(effects);
	}
}

package shortestpath.transport;

import shortestpath.WorldPointUtil;
import lombok.Getter;

/**
 * The six hot-air-balloon destination routes — one constant per destination
 * row of {@code hot_air_balloons.tsv} (the {@code Use Basket} departure rows
 * carry no destination and are not routes). The player's log-basket state is
 * declared per route through the {@code balloonLogBasketRoutes} config set:
 * selecting a route means its basket is stocked, which satisfies the
 * {@code UNLOCK_BALLOON_LOG_BASKET} OR-branch on that row and waives the
 * route's log item — unselected routes still demand their specific log.
 */
public enum BalloonRoute
{
	ENTRANA("Entrana", 2808, 3354, 0, 1511, "logs"),
	TAVERLEY("Taverley", 2941, 3420, 0, 1511, "logs"),
	CRAFTING_GUILD("Crafting Guild", 2923, 3302, 0, 1521, "oak logs"),
	VARROCK("Varrock", 3299, 3482, 0, 1519, "willow logs"),
	CASTLE_WARS("Castle Wars", 2459, 3110, 0, 1515, "yew logs"),
	GRAND_TREE("Grand Tree", 2478, 3456, 0, 1513, "magic logs"),
	;

	@Getter private final String label;
	@Getter private final int packedDestination;
	@Getter private final int logItemId;
	@Getter private final String logLabel;

	BalloonRoute(String label, int x, int y, int plane, int logItemId, String logLabel)
	{
		this.label = label;
		this.packedDestination = WorldPointUtil.packWorldPoint(x, y, plane);
		this.logItemId = logItemId;
		this.logLabel = logLabel;
	}

	/**
	 * The destination tile this route lands on, packed the same way the TSV
	 * row's Destination column is.
	 */


	/**
	 * The destination name as the TSV row's Display info cell writes it.
	 */


	/**
	 * The item id of the log this route's basket consumes.
	 */


	/**
	 * The lowercase display name of that log ("oak logs").
	 */


	/**
	 * The per-route checkbox text, e.g. {@code "Grand Tree (magic logs)"}.
	 */
	public String displayLabel()
	{
		return label + " (" + logLabel + ")";
	}

	@Override
	public String toString()
	{
		return displayLabel();
	}
}

package shortestpath.transport;

import java.util.*;
import net.runelite.api.Quest;
import shortestpath.requirement.model.*;

/**
 * Load-scoped deduplication pools for transport requirement objects and display strings (issue
 * #491). Identical requirements and labels are extremely common across the permuted transport rows,
 * so a single canonical instance is shared. The interner is local to a {@code
 * ResourceLoader.transports()} call and discarded afterwards, so the pools themselves are never
 * retained.
 */
final class LoadInterner
{
	private final Map<TransportItems, TransportItems> items = new HashMap<>();
	private final Map<VarRequirement, VarRequirement> vars = new HashMap<>();
	private final Map<Set<VarRequirement>, Set<VarRequirement>> varSets = new HashMap<>();
	private final Map<Set<Quest>, Set<Quest>> questSets = new HashMap<>();
	private final Map<String, String> strings = new HashMap<>();

	TransportItems intern(TransportItems value)
	{
		return value == null ? null : items.computeIfAbsent(value, v -> v);
	}

	VarRequirement intern(VarRequirement value)
	{
		return vars.computeIfAbsent(value, v -> v);
	}

	Set<VarRequirement> internVarSet(Set<VarRequirement> value)
	{
		return varSets.computeIfAbsent(value, v -> v);
	}

	Set<Quest> internQuestSet(Set<Quest> value)
	{
		return questSets.computeIfAbsent(value, v -> v);
	}

	String internString(String value)
	{
		return value == null ? null : strings.computeIfAbsent(value, v -> v);
	}
}

package shortestpath.transport;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

import lombok.*;
import lombok.experimental.Accessors;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Quest;
import shortestpath.*;
import shortestpath.leagues.LeagueRegion;
import shortestpath.requirement.model.*;
import shortestpath.transport.parser.*;

/**
 * The single typed resource-loading path for the plugin's bundled data.
 * <p>
 * Every classpath resource the plugin reads is anchored on this class and
 * exposed through one typed static entry point per resource. Each entry point
 * owns its resource's domain mapping <em>and its failure policy</em> — the
 * policies are not uniform: transports fail fast (NPE on a missing resource,
 * {@code RuntimeException} on {@link IOException}), league regions degrade to
 * an empty map with a warning, and the collision map hands the caller a raw
 * stream so the zip walk keeps its own failure posture. These postures are
 * behaviour; they are preserved verbatim from the incumbent readers.
 * <p>
 * The class is a loader, not a universal TSV iterator — per-resource row
 * idioms that diverge from {@link TsvParser} stay as private methods here
 * rather than being normalized.
 */
@Slf4j
public final class ResourceLoader
{
	private static final TsvParser tsvParser = new TsvParser();
	private static final FieldParser<SkillLevels> SKILL_PARSER = new SkillRequirementParser();
	private static final FieldParser<Set<Quest>> QUEST_PARSER = new QuestParser();
	private static final FieldParser<Set<VarRequirement>> VARBIT_PARSER = VarRequirementParser.forVarbits();
	private static final FieldParser<Set<VarRequirement>> VARPLAYER_PARSER = VarRequirementParser.forVarPlayers();
	private static final String DELIM_COLUMN = "\t";
	private static final String PREFIX_COMMENT = "#";
	private static final String FILE_EXTENSION = ".";
	private static final String DELIM_PATH = "/";
	private static final String DELIM = " ";
	private static final String LEAGUE_REGIONS_PATH = "/leagues/regions.tsv";
	private static final String FAMILY_RESOURCE = "/transports/teleport_restrictions.tsv";
	private static final String TELEPORTATION_ITEMS_RESOURCE = "/transports/teleportation_items.tsv";

	private ResourceLoader()
	{
	}

	private static void addTransports(
		Map<Integer, Set<Transport>> transports, String path, TransportType transportType,
		int radiusThreshold)
	{
		try
		{
			String s = Util.resourceString(path);
			addTransportsFromContents(transports, s, transportType, radiusThreshold);
		}
		catch (IOException e)
		{
			throw new RuntimeException(e);
		}
	}

	public static void addTransportsFromContents(
		Map<Integer, Set<Transport>> transports,
		String contents,
		TransportType transportType,
		int radiusThreshold)
	{
		List<TransportRecord> records = tsvParser.parse(contents);

		Set<Transport> newTransports = new LinkedHashSet<>();
		for (TransportRecord record : records)
		{
			Transport transport = new Transport(record, transportType);
			newTransports.add(transport);
		}

		/*
		 * A transport with origin A and destination B is one-way and must
		 * be duplicated as origin B and destination A to become two-way.
		 * Example: key-locked doors
		 *
		 * A transport with origin A and a missing destination is one-way,
		 * but can go from origin A to all destinations with a missing origin.
		 * Example: fairy ring AIQ -> <blank>
		 *
		 * A transport with a missing origin and destination B is one-way,
		 * but can go from all origins with a missing destination to destination B.
		 * Example: fairy ring <blank> -> AIQ
		 *
		 * Identical transports from origin A to destination A are skipped, and
		 * non-identical transports from origin A to destination A can be skipped
		 * by specifying a radius threshold to ignore almost identical coordinates.
		 * Example: fairy ring AIQ -> AIQ
		 */
		Set<Transport> transportOrigins = new LinkedHashSet<>();
		Set<Transport> transportDestinations = new LinkedHashSet<>();
		for (Transport transport : newTransports)
		{
			int origin = transport.getOrigin();
			int destination = transport.getDestination();
			// Logic to determine ordinary transport vs teleport vs permutation (e.g. fairy
			// ring)
			if ((origin == Transport.UNDEFINED_ORIGIN && destination == Transport.UNDEFINED_DESTINATION)
				|| (origin == Transport.LOCATION_PERMUTATION && destination == Transport.LOCATION_PERMUTATION))
			{
				continue;
			}
			else if (origin != Transport.LOCATION_PERMUTATION && origin != Transport.UNDEFINED_ORIGIN
				&& destination == Transport.LOCATION_PERMUTATION)
			{
				transportOrigins.add(transport);
			}
			else if (origin == Transport.LOCATION_PERMUTATION && destination != Transport.UNDEFINED_DESTINATION)
			{
				transportDestinations.add(transport);
			}
			if (origin != Transport.LOCATION_PERMUTATION
				&& destination != Transport.UNDEFINED_DESTINATION && destination != Transport.LOCATION_PERMUTATION
				&& (origin == Transport.UNDEFINED_ORIGIN || origin != destination))
			{
				transports.computeIfAbsent(origin, k -> new LinkedHashSet<>()).add(transport);
			}
		}
		for (Transport origin : transportOrigins)
		{
			for (Transport destination : transportDestinations)
			{
				// The radius threshold prevents transport permutations from including (almost)
				// same origin and destination
				if (WorldPointUtil.distanceBetween2D(origin.getOrigin(), destination.getDestination()) > radiusThreshold)
				{
					Transport combined = new Transport(origin, destination);
					transports
						.computeIfAbsent(origin.getOrigin(), k -> new LinkedHashSet<>())
						.add(combined);
				}
			}
		}
	}

	/**
	 * Loads every bundled transport TSV (one per {@link TransportType} with a
	 * resource path) and returns the origin-keyed transport map with
	 * requirement interning applied. A missing resource throws
	 * {@link NullPointerException}; an {@link IOException} is wrapped in
	 * {@link RuntimeException}.
	 */
	public static HashMap<Integer, Set<Transport>> transports()
	{
		HashMap<Integer, Set<Transport>> transports = new HashMap<>();

		for (TransportType type : TransportType.values())
		{
			if (type.hasResourcePath())
			{
				addTransports(transports, type.getResourcePath(), type,
					type.hasRadiusThreshold() ? type.getRadiusThreshold() : 0);
			}
		}

		internRequirements(transports);

		return transports;
	}

	/**
	 * Loads a predefined subset of destination categories from bundled TSV resources.
	 *
	 * @return a map from destination category key to a set of packed world point integers.
	 */
	public static Map<String, Set<Integer>> destinations()
	{
		Map<String, Set<Integer>> destinations = new HashMap<>(10);
		addDestinations(destinations, "/destinations/game_features/altar.tsv");
		addDestinations(destinations, "/destinations/game_features/bank.tsv");
		addDestinations(destinations, "/destinations/training/anvil.tsv");
		addDestinations(destinations, "/destinations/shopping/apothecary.tsv");
		return destinations;
	}

	/**
	 * Parses a TSV resource of destination coordinates and merges them into the provided map.
	 * The key in the destination map is derived from the directory component immediately preceding the file
	 * name (e.g., {@code /destinations/game_features/bank.tsv -> bank}).
	 *
	 * @param destinations accumulator map of category key to a set of packed world point integers.
	 * @param path         classpath resource path to a TSV file beginning with a header line.
	 * @throws RuntimeException wrapping {@link IOException} if the resource cannot be read.
	 */
	private static void addDestinations(Map<String, Set<Integer>> destinations, String path)
	{
		try
		{
			String s = Util.resourceString(path);
			parseDestinations(destinations, path, s);
		}
		catch (IOException e)
		{
			throw new RuntimeException(e);
		}
	}

	/**
	 * Content seam for the destinations row idiom: header-aware with
	 * duplicate-header accumulation and drop-arity field splitting, kept
	 * verbatim from the incumbent reader. Package-private for tests.
	 */
	static void parseDestinations(Map<String, Set<Integer>> destinations, String path, String contents)
	{
		Scanner scanner = new Scanner(contents);

		// Header line is the first line in the file and will start with either '#' or
		// '# '
		String[] headers = parse_header_line(scanner);

		String[] parts = path.replace(FILE_EXTENSION, DELIM_PATH).split(DELIM_PATH);
		String entry = parts[parts.length - 2];

		while (scanner.hasNextLine())
		{
			String line = scanner.nextLine();

			if (line.startsWith(PREFIX_COMMENT) || line.isBlank())
			{
				continue;
			}

			String[] fields = line.split(DELIM_COLUMN);
			Map<String, List<String>> fieldMap = new HashMap<>();
			for (int i = 0; i < headers.length; i++)
			{
				if (i < fields.length)
				{
					List<String> values = fieldMap.getOrDefault(headers[i], new ArrayList<>());
					values.add(fields[i]);
					fieldMap.put(headers[i], values);
				}
			}
			for (String field : fieldMap.keySet())
			{
				if ("Destination".equals(field))
				{
					for (String value : fieldMap.get(field))
					{
						try
						{
							String[] destinationArray = value.split(DELIM);
							if (destinationArray.length == 3)
							{
								Set<Integer> entryDestinations = destinations.getOrDefault(entry, new HashSet<>());
								entryDestinations.add(WorldPointUtil.packWorldPoint(
									Integer.parseInt(destinationArray[0]),
									Integer.parseInt(destinationArray[1]),
									Integer.parseInt(destinationArray[2])));
								destinations.put(entry, entryDestinations);
							}
						}
						catch (NumberFormatException e)
						{
							log.error("Invalid destination coordinate", e);
						}
					}
				}
			}
		}
		scanner.close();
	}

	private static String[] parse_header_line(Scanner scanner)
	{
		String headerLine = scanner.nextLine();
		headerLine = headerLine.startsWith(PREFIX_COMMENT + " ")
			? headerLine.replace(PREFIX_COMMENT + " ", PREFIX_COMMENT)
			: headerLine;
		headerLine = headerLine.startsWith(PREFIX_COMMENT) ? headerLine.replace(PREFIX_COMMENT, "") : headerLine;
		return headerLine.split(DELIM_COLUMN);
	}

	/**
	 * Per-packed-point requirements for bank tiles, parsed from {@code bank.tsv} columns
	 * Skills, Quests, Varbits, and VarPlayers (same TSV format as transports).
	 * Tiles with no requirement rows behave as {@link DestinationRequirements#EMPTY}.
	 */
	public static Map<Integer, DestinationRequirements> bankRequirements()
	{
		final String path = "/destinations/game_features/bank.tsv";
		try
		{
			String s = Util.resourceString(path);
			return parseBankRequirements(s);
		}
		catch (IOException e)
		{
			throw new RuntimeException(e);
		}
	}

	/**
	 * Content seam for the bank-requirements row idiom: keep-arity field
	 * splitting with trimmed headers, kept verbatim from the incumbent
	 * reader. Package-private for tests.
	 */
	static Map<Integer, DestinationRequirements> parseBankRequirements(String contents)
	{
		Map<Integer, DestinationRequirements> requirements = new HashMap<>();
		final String DELIM_COLUMN = "\t";
		final String PREFIX_COMMENT = "#";
		final String DELIM = " ";

		try (Scanner scanner = new Scanner(contents))
		{
			String[] headers = parse_header_line(scanner);
			for (int i = 0; i < headers.length; i++)
			{
				headers[i] = headers[i].trim();
			}

			int destCol = indexOf(headers, "Destination");
			int skillsCol = indexOf(headers, "Skills");
			int questsCol = indexOf(headers, "Quests");
			int varbitsCol = indexOf(headers, "Varbits");
			int varPlayersCol = indexOf(headers, "VarPlayers");
			if (destCol < 0)
			{
				return requirements;
			}

			while (scanner.hasNextLine())
			{
				String line = scanner.nextLine();
				if (line.startsWith(PREFIX_COMMENT) || line.isBlank())
				{
					continue;
				}
				String[] fields = line.split(DELIM_COLUMN, -1);
				if (fields.length <= destCol)
				{
					continue;
				}
				String destField = fields[destCol].trim();
				String[] destinationArray = destField.split(DELIM);
				if (destinationArray.length != 3)
				{
					continue;
				}
				int packed;
				try
				{
					packed = WorldPointUtil.packWorldPoint(
						Integer.parseInt(destinationArray[0]),
						Integer.parseInt(destinationArray[1]),
						Integer.parseInt(destinationArray[2]));
				}
				catch (NumberFormatException e)
				{
					log.error("Invalid destination coordinate in bank.tsv", e);
					continue;
				}

				String skillsStr = fieldAt(fields, skillsCol);
				String questsStr = fieldAt(fields, questsCol);
				String varbitsStr = fieldAt(fields, varbitsCol);
				String varPlayersStr = fieldAt(fields, varPlayersCol);

				SkillLevels skillLevels = skillsCol >= 0 ? SKILL_PARSER.parse(blankToNull(skillsStr)) : SkillLevels.NONE;
				Set<Quest> quests = questsCol >= 0 ? QUEST_PARSER.parse(blankToNull(questsStr)) : Set.of();
				Set<VarRequirement> varbits = varbitsCol >= 0 ? VARBIT_PARSER.parse(blankToNull(varbitsStr)) : Set.of();
				Set<VarRequirement> varPlayers = varPlayersCol >= 0 ? VARPLAYER_PARSER.parse(blankToNull(varPlayersStr)) : Set.of();

				DestinationRequirements rowReq = new DestinationRequirements(skillLevels, quests, varbits, varPlayers);
				requirements.merge(packed, rowReq, DestinationRequirements::merge);
			}
		}
		return requirements;
	}

	private static int indexOf(String[] headers, String name)
	{
		for (int i = 0; i < headers.length; i++)
		{
			if (name.equals(headers[i]))
			{
				return i;
			}
		}
		return -1;
	}

	private static String fieldAt(String[] fields, int col)
	{
		if (col < 0 || col >= fields.length)
		{
			return "";
		}
		return fields[col];
	}

	private static String blankToNull(String s)
	{
		return s == null || s.isBlank() ? null : s;
	}

	/**
	 * Loads the league region mapping from {@code /leagues/regions.tsv}. A
	 * missing resource or a read failure degrades to an empty map (every tile
	 * resolves to {@link LeagueRegion#NEUTRAL} downstream) rather than
	 * crashing — the incumbent posture.
	 */
	public static Map<Integer, LeagueRegion> leagueRegions()
	{
		try (InputStream in = ResourceLoader.class.getResourceAsStream(LEAGUE_REGIONS_PATH))
		{
			if (in == null)
			{
				log.warn("League regions resource not found at {}; defaulting all tiles to NEUTRAL", LEAGUE_REGIONS_PATH);
				return new HashMap<>();
			}
			String body = new String(Util.readAllBytes(Objects.requireNonNull(in)), StandardCharsets.UTF_8);
			return parseLeagueRegions(body);
		}
		catch (IOException e)
		{
			log.error("Failed to load league regions from {}", LEAGUE_REGIONS_PATH, e);
			return new HashMap<>();
		}
	}

	/**
	 * Content seam for the league-regions row grammar: two-column
	 * whitespace-split rows keyed by region id, non-header and
	 * non-numeric/unknown rows warn-and-skip. Kept verbatim from the
	 * incumbent reader.
	 */
	public static Map<Integer, LeagueRegion> parseLeagueRegions(String tsv)
	{
		Map<Integer, LeagueRegion> result = new HashMap<>();
		if (tsv == null || tsv.isEmpty())
		{
			return result;
		}
		int lineNumber = 0;
		for (String rawLine : tsv.split("\\R"))
		{
			lineNumber++;
			String line = rawLine.trim();
			if (line.isEmpty() || line.startsWith("#"))
			{
				continue;
			}
			String[] parts = line.split("\\s+", 2);
			if (parts.length != 2)
			{
				log.warn("Skipping malformed league regions row {}: '{}'", lineNumber, rawLine);
				continue;
			}
			final int regionId;
			try
			{
				regionId = Integer.parseInt(parts[0]);
			}
			catch (NumberFormatException e)
			{
				log.warn("Skipping league regions row {} with non-numeric region id '{}'", lineNumber, parts[0]);
				continue;
			}
			final LeagueRegion region;
			try
			{
				region = LeagueRegion.valueOf(parts[1]);
			}
			catch (IllegalArgumentException e)
			{
				log.warn("Skipping league regions row {} with unknown region '{}'", lineNumber, parts[1]);
				continue;
			}
			result.put(regionId, region);
		}
		return result;
	}

	/**
	 * A raw parsed row of the bundled teleport-restriction family map. The
	 * loader owns the resource read and row idiom; the caller maps rows onto
	 * its own model ({@link shortestpath.requirement.TeleportRestriction.Family}).
	 */
	@Getter
	@Accessors(fluent = true)
	@AllArgsConstructor
	public static final class RestrictionFamilyRow
	{
		private final String name;
		private final int displayItemId;
		private final Set<Integer> memberItemIds;
		private final Map<Integer, String> memberLabels;
	}

	/**
	 * Loads the bundled teleport-restriction family map from
	 * {@code /transports/teleport_restrictions.tsv}. A missing resource
	 * degrades to an empty list — panel construction must not crash on
	 * packaging gaps; an {@link IOException} is wrapped in
	 * {@link RuntimeException}.
	 */
	public static List<RestrictionFamilyRow> families()
	{
		final String contents;
		try
		{
			InputStream stream = ResourceLoader.class.getResourceAsStream(FAMILY_RESOURCE);
			if (stream == null)
			{
				log.warn("Teleport restriction family resource {} is missing — degrading to no rows",
					FAMILY_RESOURCE);
				return Collections.emptyList();
			}
			contents = new String(Util.readAllBytes(stream), StandardCharsets.UTF_8);
		}
		catch (IOException e)
		{
			throw new RuntimeException(e);
		}
		return parseFamilies(contents);
	}

	/**
	 * Loads the raw records of {@code /transports/teleportation_items.tsv}
	 * through the shared {@link TsvParser} — the same resource
	 * {@link TransportType#TELEPORTATION_ITEM} loads its transports from.
	 * Records stay raw field maps; domain mapping is the caller's job (same
	 * division as {@link #families()}/{@link #parseFamilies}). A missing
	 * resource degrades to an empty list with a warning; an
	 * {@link IOException} is wrapped in {@link RuntimeException}.
	 */
	public static List<TransportRecord> teleportationItemRecords()
	{
		final String contents;
		try
		{
			InputStream stream =
				ResourceLoader.class.getResourceAsStream(TELEPORTATION_ITEMS_RESOURCE);
			if (stream == null)
			{
				log.warn("Teleportation items resource {} is missing — degrading to no records",
					TELEPORTATION_ITEMS_RESOURCE);
				return Collections.emptyList();
			}
			contents = new String(Util.readAllBytes(stream), StandardCharsets.UTF_8);
		}
		catch (IOException e)
		{
			throw new RuntimeException(e);
		}
		return tsvParser.parse(contents);
	}

	/**
	 * Content seam for the teleport-restriction row idiom: positional
	 * keep-arity field splitting with '#' comment rows skipped, malformed
	 * rows warn-and-skip, and an absent or malformed memberLabels column
	 * degrades to an empty map for that family. Kept verbatim from the
	 * incumbent reader. Package-private for tests.
	 */
	static List<RestrictionFamilyRow> parseFamilies(String contents)
	{
		List<RestrictionFamilyRow> families = new ArrayList<>();
		for (String line : contents.split("\\R"))
		{
			if (line.startsWith(PREFIX_COMMENT) || line.isBlank())
			{
				continue;
			}

			String[] fields = line.split(DELIM_COLUMN, -1);
			if (fields.length < 3)
			{
				log.warn("Skipping malformed teleport_restrictions row ({} columns): {}", fields.length, line);
				continue;
			}

			String name = fields[0].trim();
			if (name.isEmpty())
			{
				log.warn("Skipping teleport_restrictions row with empty family name");
				continue;
			}

			try
			{
				int displayItemId = Integer.parseInt(fields[1].trim());
				Set<Integer> memberItemIds = parseIdSet(fields[2]);
				Map<Integer, String> memberLabels =
					fields.length > 3 ? parseMemberLabels(fields[3]) : Collections.emptyMap();
				families.add(new RestrictionFamilyRow(name, displayItemId,
					Collections.unmodifiableSet(memberItemIds),
					Collections.unmodifiableMap(memberLabels)));
			}
			catch (NumberFormatException e)
			{
				log.warn("Skipping malformed teleport_restrictions row: {}", line);
			}
		}

		return Collections.unmodifiableList(families);
	}

	private static Set<Integer> parseIdSet(String column)
	{
		Set<Integer> ids = new LinkedHashSet<>();
		for (String token : column.split(","))
		{
			String trimmed = token.trim();
			if (!trimmed.isEmpty())
			{
				ids.add(Integer.parseInt(trimmed));
			}
		}
		return ids;
	}

	private static Map<Integer, String> parseMemberLabels(String column)
	{
		Map<Integer, String> labels = new LinkedHashMap<>();
		for (String entry : column.split(","))
		{
			String trimmed = entry.trim();
			if (trimmed.isEmpty())
			{
				continue;
			}

			int eq = trimmed.indexOf('=');
			if (eq < 0)
			{
				log.warn("Skipping malformed memberLabels entry: {}", trimmed);
				continue;
			}

			try
			{
				labels.put(Integer.parseInt(trimmed.substring(0, eq)), trimmed.substring(eq + 1));
			}
			catch (NumberFormatException e)
			{
				log.warn("Skipping malformed memberLabels entry: {}", trimmed);
			}
		}
		return labels;
	}

	/**
	 * Returns a caller-owned stream over {@code /collision-map.zip}. A missing
	 * resource throws {@link NullPointerException}; read failures surface to
	 * the caller (the zip walk wraps them in {@link java.io.UncheckedIOException}).
	 * The caller is responsible for closing the stream.
	 */
	public static InputStream collisionMap()
	{
		return Objects.requireNonNull(ResourceLoader.class.getResourceAsStream("/collision-map.zip"));
	}

	/**
	 * Deduplicates the requirement objects shared across the loaded transports, so identical
	 * {@code TransportItems}/{@code VarRequirement} requirements point at one shared instance
	 * instead of a per-transport copy (issue #491). The interning pools are local and discarded
	 * once loading finishes.
	 */
	private static void internRequirements(Map<Integer, Set<Transport>> transports)
	{
		LoadInterner interner = new LoadInterner();
		Set<Transport> visited = Collections.newSetFromMap(new IdentityHashMap<>());
		for (Set<Transport> set : transports.values())
		{
			for (Transport transport : set)
			{
				if (visited.add(transport))
				{
					transport.internRequirements(interner);
				}
			}
		}
	}
}

package shortestpath.transport;

import java.util.*;

import lombok.*;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Quest;
import shortestpath.WorldPointUtil;
import shortestpath.leagues.LeagueRegion;
import shortestpath.transport.parser.*;
import shortestpath.requirement.model.*;

/**
 * This class represents a travel point between two WorldPoints.
 */
@Slf4j
public class Transport
{
	public static final int UNDEFINED_ORIGIN = WorldPointUtil.UNDEFINED;
	public static final int UNDEFINED_DESTINATION = WorldPointUtil.UNDEFINED;
	/**
	 * A location placeholder different from null to use for permutation transports
	 */
	public static final int LOCATION_PERMUTATION = WorldPointUtil.packWorldPoint(-1, -1, 1);
	/**
	 * The skill levels, total level, combat level and quest points required to use
	 * this transport. Most transports require no skills, so they point at the shared
	 * {@link SkillLevels#NONE} singleton instead of each allocating their own copy
	 * (issue #491).
	 */
	@Getter
	private SkillLevels skillLevels = SkillLevels.NONE;
	/**
	 * Variable requirements (varbits and varplayers) for the transport to be valid.
	 * All must pass.
	 */
	// Defaults to a shared immutable empty set; only transports that actually declare var
	// requirements pay for a real Set. Most transports declare none, so this avoids ~one
	// HashSet (+ its HashMap) per transport (issue #491).
	@Getter
	private Set<VarRequirement> varRequirements = Collections.emptySet();
	/**
	 * The starting point of this transport
	 */
	@Getter
	private int origin = UNDEFINED_ORIGIN;
	/**
	 * The ending point of this transport
	 */
	@Setter
	@Getter
	private int destination = UNDEFINED_DESTINATION;

	/**
	 * The quests required to use this transport
	 */
	// Shared immutable empty set by default; see varRequirements above.
	@Getter
	private Set<Quest> quests = Collections.emptySet();
	/**
	 * The item requirements to use this transport
	 */
	@Getter
	private TransportItems itemRequirements;
	/**
	 * The type of transport
	 */
	@Getter
	private TransportType type;
	/**
	 * The travel waiting time in number of ticks
	 */
	@Getter
	private int duration;
	/**
	 * Info to display for this transport. For spirit trees, fairy rings,
	 * and others, this is the destination option to pick.
	 */
	@Getter
	private String displayInfo = null;
	/**
	 * If this is an item transport, this tracks if it is consumable (as opposed to
	 * having infinite uses)
	 */
	@Getter
	private boolean isConsumable = false;
	/**
	 * The maximum wilderness level that the transport can be used in
	 */
	@Getter
	private int maxWildernessLevel = -1;
	/**
	 * Object information for this transport
	 */
	@Getter
	private String objectInfo = null;
	/**
	 * Per-transport seasonal-league region override. When set, the league-mode
	 * region gate ({@code PathfinderConfig#isTransportRegionAllowed}) uses
	 * this region for the destination chunk instead of the result of
	 * {@code LeagueRegionChecker#getRegion(destination)}. Used for shortcuts
	 * whose destination tile sits in a chunk that the wiki classifies under
	 * a different region (e.g. Trollheim Wilderness climb — destination chunk
	 * is Wilderness, but the wiki lists the shortcut under Asgarnia).
	 */
	@Getter
	private LeagueRegion regionOverride = null;

	/**
	 * Creates a new transport from an origin-only transport
	 * and a destination-only transport, and merges requirements
	 */
	Transport(Transport origin, Transport destination)
	{
		TransportBuilder builder = new TransportBuilder()
			.origin(origin.origin)
			.destination(destination.destination)
			.type(origin.type)
			.startSkillLevels(origin.skillLevels)
			.startSkillLevels(destination.skillLevels)
			.quests(origin.quests)
			.quests(destination.quests)
			.itemRequirements(TransportItems.merge(origin.itemRequirements, destination.itemRequirements))
			.duration(Math.max(origin.duration, destination.duration))
			.displayInfo(destination.displayInfo)
			.isConsumable(origin.isConsumable || destination.isConsumable)
			.maxWildernessLevel(Math.max(origin.maxWildernessLevel, destination.maxWildernessLevel))
			.objectInfo(origin.objectInfo)
			.varRequirements(origin.varRequirements)
			.varRequirements(destination.varRequirements)
			.regionOverride(destination.regionOverride != null ? destination.regionOverride : origin.regionOverride);

		Transport builtTransport = builder.build();
		copyFrom(builtTransport);
	}

	Transport(TransportRecord record, TransportType transportType)
	{
		TransportBuilder builder = new TransportBuilder();
		builder.type(transportType);

		// Origin/Destination use hasKey because empty string means LOCATION_PERMUTATION
		if (record.hasKey(TransportRecord.Fields.ORIGIN))
		{
			builder.origin(record.getOrigin());
		}
		if (record.hasKey(TransportRecord.Fields.DESTINATION))
		{
			builder.destination(record.getDestination());
		}
		if (record.has(TransportRecord.Fields.SKILLS))
		{
			builder.skillLevels(record.getSkills());
		}
		if (record.has(TransportRecord.Fields.ITEMS))
		{
			builder.itemRequirements(record.getItems());
		}
		if (record.has(TransportRecord.Fields.QUESTS))
		{
			builder.quests(record.getQuests());
		}
		if (record.has(TransportRecord.Fields.DURATION))
		{
			builder.duration(record.getDuration());
		}
		if (record.has(TransportRecord.Fields.DISPLAY_INFO))
		{
			builder.displayInfo(record.getDisplayInfo());
		}
		if (record.has(TransportRecord.Fields.CONSUMABLE))
		{
			builder.isConsumable(record.getConsumable());
		}
		if (record.has(TransportRecord.Fields.WILDERNESS_LEVEL))
		{
			builder.maxWildernessLevel(record.getWildernessLevel());
		}
		if (record.has(TransportRecord.Fields.OBJECT_INFO))
		{
			builder.objectInfo(record.getObjectInfo());
		}
		if (record.has(TransportRecord.Fields.VARBITS))
		{
			builder.varbits(record.getVarbits());
		}
		if (record.has(TransportRecord.Fields.VAR_PLAYERS))
		{
			builder.varPlayers(record.getVarPlayers());
		}
		if (record.has(TransportRecord.Fields.REGION_OVERRIDE))
		{
			builder.regionOverride(record.getRegionOverride());
		}

		Transport builtTransport = builder.build();
		copyFrom(builtTransport);
	}

	private void copyFrom(Transport t)
	{
		this.origin = t.origin;
		this.destination = t.destination;
		this.skillLevels = t.skillLevels;
		this.quests = t.quests;
		this.itemRequirements = t.itemRequirements;
		this.type = t.type;
		this.duration = t.duration;
		this.displayInfo = t.displayInfo;
		this.isConsumable = t.isConsumable;
		this.maxWildernessLevel = t.maxWildernessLevel;
		this.objectInfo = t.objectInfo;
		this.varRequirements = t.varRequirements;
		this.regionOverride = t.regionOverride;
	}

	private Transport()
	{
	}

	/**
	 * A copy of this transport with a different item-requirement set. Used to
	 * inject requirements derived at availability-build time — such as the
	 * fairy-ring staff rule — onto the offered transport without mutating the
	 * shared loaded instance every refresh iterates.
	 */
	public Transport withItemRequirements(TransportItems items)
	{
		Transport copy = new Transport();
		copy.copyFrom(this);
		copy.itemRequirements = items;
		return copy;
	}

	/**
	 * Hands back a shared immutable empty set when the builder accumulated nothing, so empty
	 * requirement sets do not allocate a {@code HashSet}/{@code HashMap} per transport. A non-empty
	 * builder set is handed over directly (the single-use builder is discarded afterwards).
	 */
	private static <T> Set<T> compact(Set<T> set)
	{
		return set.isEmpty() ? Collections.emptySet() : set;
	}

	/**
	 * Quest requirements are keyed on the {@link Quest} enum, so a non-empty set is stored as a
	 * compact {@link EnumSet} (a single bitmask object) rather than a HashSet plus its HashMap and
	 * per-element nodes (issue #491). The empty case keeps the shared immutable empty set.
	 */
	private static Set<Quest> compactQuests(Set<Quest> quests)
	{
		return quests.isEmpty() ? Collections.emptySet() : EnumSet.copyOf(quests);
	}

	/**
	 * Load-time flyweight: replaces this transport's requirement objects with shared canonical
	 * instances from the supplied pools, so transports with identical item or var requirements share
	 * one {@code TransportItems}/{@code VarRequirement} instance (and the int[] arrays inside them)
	 * rather than each holding a distinct copy (issue #491). Identical requirements are extremely
	 * common across the permuted transport rows. The pools are local to loading and discarded after.
	 */
	void internRequirements(LoadInterner interner)
	{
		itemRequirements = interner.intern(itemRequirements);
		displayInfo = interner.internString(displayInfo);
		objectInfo = interner.internString(objectInfo);
		if (!varRequirements.isEmpty())
		{
			Set<VarRequirement> interned = new HashSet<>(varRequirements.size() * 2);
			for (VarRequirement requirement : varRequirements)
			{
				interned.add(interner.intern(requirement));
			}
			// Transports with identical var requirements (very common across permutations) share one
			// read-only Set instead of each keeping a copy.
			varRequirements = interner.internVarSet(interned);
		}
		if (!quests.isEmpty())
		{
			quests = interner.internQuestSet(quests);
		}
	}

	@Override
	public String toString()
	{
		return ("(" +
			WorldPointUtil.unpackWorldX(origin) + ", " +
			WorldPointUtil.unpackWorldY(origin) + ", " +
			WorldPointUtil.unpackWorldPlane(origin) + ") to (" +
			WorldPointUtil.unpackWorldX(destination) + ", " +
			WorldPointUtil.unpackWorldY(destination) + ", " +
			WorldPointUtil.unpackWorldPlane(destination) + ")");
	}

	/**
	 * Whether the transport has one or more quest requirements
	 */
	public boolean isQuestLocked()
	{
		return !quests.isEmpty();
	}

	/**
	 * Whether this transport's display info contains the given substring.
	 * Returns false if displayInfo is null.
	 */
	public boolean hasDisplayInfo(String substring)
	{
		return displayInfo != null && displayInfo.contains(substring);
	}

	/**
	 * Whether this transport can be used at the given wilderness level.
	 */
	public boolean isUsableAtWildernessLevel(int wildernessLevel)
	{
		return !type.isTeleport() || wildernessLevel <= maxWildernessLevel;
	}

	public static class TransportBuilder
	{
		private final int[] skillLevels = new int[SkillLevels.LENGTH];
		private final Set<VarRequirement> varRequirements = new HashSet<>();
		private final FieldParser<SkillLevels> skillParser = new SkillRequirementParser();
		private final FieldParser<TransportItems> itemParser = new ItemRequirementParser();
		private final FieldParser<Set<Quest>> questParser = new QuestParser();
		private final VarRequirementParser varbitParser = VarRequirementParser.forVarbits();
		private final VarRequirementParser varPlayerParser = VarRequirementParser.forVarPlayers();
		private final FieldParser<Integer> worldPointParser = new WorldPointParser();
		private final Set<Quest> quests = new HashSet<>();
		private int origin = UNDEFINED_ORIGIN;
		private int destination = UNDEFINED_DESTINATION;
		private TransportItems itemRequirements;
		private TransportType type;
		private int duration;
		private String displayInfo = null;
		private boolean isConsumable = false;
		private int maxWildernessLevel = -1;
		private String objectInfo = null;
		private LeagueRegion regionOverride = null;

		public TransportBuilder origin(int origin)
		{
			this.origin = origin;
			return this;
		}

		public TransportBuilder origin(String value)
		{
			this.origin = worldPointParser.parse(value);
			return this;
		}

		public TransportBuilder destination(int destination)
		{
			this.destination = destination;
			return this;
		}

		public TransportBuilder destination(String value)
		{
			this.destination = worldPointParser.parse(value);
			return this;
		}

		public TransportBuilder skillLevels(String value)
		{
			SkillLevels parsedSkills = skillParser.parse(value);
			for (int i = 0; i < skillLevels.length; i++)
			{
				if (parsedSkills.get(i) > 0)
				{
					skillLevels[i] = parsedSkills.get(i);
				}
			}
			return this;
		}

		public TransportBuilder startSkillLevels(SkillLevels otherSkillLevels)
		{
			for (int i = 0; i < skillLevels.length; i++)
			{
				this.skillLevels[i] = Math.max(this.skillLevels[i], otherSkillLevels.get(i));
			}
			return this;
		}

		public TransportBuilder quests(Set<Quest> quests)
		{
			this.quests.addAll(quests);
			return this;
		}

		public TransportBuilder quests(String value)
		{
			this.quests.addAll(questParser.parse(value));
			return this;
		}

		public TransportBuilder itemRequirements(TransportItems itemRequirements)
		{
			this.itemRequirements = itemRequirements;
			return this;
		}

		public TransportBuilder itemRequirements(String value)
		{
			this.itemRequirements = itemParser.parse(value);
			return this;
		}

		public TransportBuilder type(TransportType type)
		{
			this.type = type;
			return this;
		}

		public TransportBuilder duration(int duration)
		{
			this.duration = Math.max(this.duration, duration);
			return this;
		}

		public TransportBuilder duration(String value)
		{
			if (value != null && !value.isEmpty())
			{
				try
				{
					this.duration = Integer.parseInt(value);
				}
				catch (NumberFormatException e)
				{
					log.error("Invalid tick duration: {}", value);
				}
			}
			return this;
		}

		public TransportBuilder displayInfo(String displayInfo)
		{
			this.displayInfo = displayInfo;
			return this;
		}

		public TransportBuilder isConsumable(boolean isConsumable)
		{
			this.isConsumable |= isConsumable;
			return this;
		}

		public TransportBuilder isConsumable(String value)
		{
			this.isConsumable = "T".equals(value) || "yes".equalsIgnoreCase(value);
			return this;
		}

		public TransportBuilder maxWildernessLevel(int maxWildernessLevel)
		{
			this.maxWildernessLevel = Math.max(this.maxWildernessLevel, maxWildernessLevel);
			return this;
		}

		public TransportBuilder maxWildernessLevel(String value)
		{
			if (value != null && !value.isEmpty())
			{
				try
				{
					this.maxWildernessLevel = Integer.parseInt(value);
				}
				catch (NumberFormatException e)
				{
					log.error("Invalid wilderness level: {}", value);
				}
			}
			return this;
		}

		public TransportBuilder objectInfo(String objectInfo)
		{
			this.objectInfo = objectInfo;
			return this;
		}

		public TransportBuilder regionOverride(LeagueRegion regionOverride)
		{
			if (regionOverride != null)
			{
				this.regionOverride = regionOverride;
			}
			return this;
		}

		public TransportBuilder regionOverride(String value)
		{
			if (value != null && !value.isEmpty())
			{
				try
				{
					this.regionOverride = LeagueRegion.valueOf(value.trim().toUpperCase());
				}
				catch (IllegalArgumentException e)
				{
					log.error("Invalid region override: {}", value);
				}
			}
			return this;
		}

		public TransportBuilder varRequirements(Set<VarRequirement> requirements)
		{
			this.varRequirements.addAll(requirements);
			return this;
		}

		public TransportBuilder varbits(String value)
		{
			this.varRequirements.addAll(varbitParser.parse(value));
			return this;
		}

		public TransportBuilder varPlayers(String value)
		{
			this.varRequirements.addAll(varPlayerParser.parse(value));
			return this;
		}

		public Transport build()
		{
			Transport transport = new Transport();
			transport.origin = this.origin;
			transport.destination = this.destination;
			transport.skillLevels = SkillLevels.of(this.skillLevels);
			transport.quests = compactQuests(this.quests);
			transport.itemRequirements = this.itemRequirements;
			transport.type = this.type;
			transport.duration = this.duration;
			transport.displayInfo = this.displayInfo;
			transport.isConsumable = this.isConsumable;
			transport.maxWildernessLevel = this.maxWildernessLevel;
			transport.objectInfo = this.objectInfo;
			transport.varRequirements = compact(this.varRequirements);
			transport.regionOverride = this.regionOverride;

			// Post-build validation/refinement
			if (transport.type != null && transport.type.isTeleport())
			{
				transport.duration = Math.max(transport.duration, 1);
			}

			if (transport.type != null)
			{
				transport.type = transport.type.refine(transport.skillLevels);
			}

			return transport;
		}
	}
}

package shortestpath.transport;

import java.util.*;

import lombok.*;
import net.runelite.api.Skill;
import shortestpath.Util;
import shortestpath.requirement.model.SkillLevels;

@Getter
public enum TransportType
{
	TRANSPORT,
	AGILITY_SHORTCUT
		{
			@Override
			public TransportType refine(SkillLevels skillLevels)
			{
				if (skillLevels.get(Skill.RANGED) > 1 || skillLevels.get(Skill.STRENGTH) > 1)
				{
					return GRAPPLE_SHORTCUT;
				}
				return this;
			}
		},
	GRAPPLE_SHORTCUT,
	BOAT,
	CANOE,
	CHARTER_SHIP,
	SHIP,
	FAIRY_RING,
	GNOME_GLIDER,
	HOT_AIR_BALLOON,
	MAGIC_CARPET,
	MAGIC_MUSHTREE,
	MINECART,
	QUETZAL,
	QUETZAL_WHISTLE,
	SEASONAL_TRANSPORTS,
	SPIRIT_TREE,
	TELEPORTATION_BOX,
	TELEPORTATION_ITEM,
	TELEPORTATION_LEVER,
	TELEPORTATION_MINIGAME,
	TELEPORTATION_PORTAL,
	TELEPORTATION_PORTAL_POH,
	TELEPORTATION_SPELL,
	TELEPORTATION_SPELL_HOME,
	WILDERNESS_OBELISK,
	;

	static
	{
		// The ctor fails loudly on a constant with no TSV row; these passes
		// fail loudly on a row naming no constant and on a shares-with
		// column naming a constant that does not exist.
		for (String name : Rows.BY_NAME.keySet())
		{
			valueOf(name);
		}
		for (TransportType type : values())
		{
			if (type.sharedTypeName != null)
			{
				valueOf(type.sharedTypeName);
			}
		}
	}

	private final String resourcePath;
	private final String enabledKey;
	private final String costKey;
	private final Integer radiusThreshold;
	/**
	 * The {@code teleport} column; read through {@link #isTeleport()}.
	 * Levers, portals and wilderness obelisks are considered transports
	 * and not teleports because they have a pre-defined origin and no
	 * wilderness level limit.
	 */
	private final boolean teleport;
	/**
	 * The enum name of the {@link #sharesDestinationsWith()} pairing,
	 * stored as a name because the paired constant is not reliably
	 * constructed yet while rows initialise; resolved at call time.
	 */
	@Getter(AccessLevel.NONE)
	private final String sharedTypeName;
	/** The {@code differential-cost-key} column; read through {@link #differentialCostKey()}. */
	@Getter(AccessLevel.NONE)
	private final String differentialCostKey;

	/**
	 * Row backed by a {@code transport-types.tsv} line: every data column
	 * resolves out of {@link Rows}. Fails loudly on a missing row or a
	 * malformed literal; the enum's static block fails loudly on surplus
	 * rows and unresolvable shares-with names.
	 */
	TransportType()
	{
		String[] cols = Rows.BY_NAME.get(name());
		if (cols == null)
		{
			throw new IllegalStateException("no transport-types.tsv row for " + name());
		}
		this.resourcePath = emptyToNull(cols[1]);
		this.enabledKey = emptyToNull(cols[2]);
		this.costKey = emptyToNull(cols[3]);
		this.radiusThreshold = parseRadius(name(), cols[4]);
		this.teleport = parseTeleport(name(), cols[5]);
		this.sharedTypeName = emptyToNull(cols[6]);
		this.differentialCostKey = emptyToNull(cols[7]);
	}

	/** Column count every {@code transport-types.tsv} line must carry. */
	private static final int ROW_COLUMNS = 8;

	static String emptyToNull(String token)
	{
		return token.isEmpty() ? null : token;
	}

	static Integer parseRadius(String name, String token)
	{
		if (token.isEmpty())
		{
			return null;
		}
		try
		{
			return Integer.valueOf(token);
		}
		catch (NumberFormatException e)
		{
			throw new IllegalStateException("unparseable radius threshold '" + token + "' for " + name, e);
		}
	}

	/**
	 * The {@code teleport} column parsed strictly: an empty or
	 * {@code false} cell is a transport, {@code true} is a teleport, and
	 * anything else throws — a silently wrong flag would change
	 * wilderness routing behaviour without failing the load.
	 */
	static boolean parseTeleport(String name, String token)
	{
		if (token.isEmpty() || "false".equals(token))
		{
			return false;
		}
		if ("true".equals(token))
		{
			return true;
		}
		throw new IllegalStateException("unparseable teleport flag '" + token + "' for " + name);
	}

	/**
	 * Load a {@code transport-types.tsv}-shaped resource into its
	 * name-keyed row map — the same shape {@link Rows} binds at class
	 * init. Package-visible so the TSV test can exercise the load's loud
	 * posture against fixture resources.
	 */
	static Map<String, String[]> loadRows(String path)
	{
		Map<String, String[]> rows = new HashMap<>();
		try
		{
			Util.each(path, (line, cols) ->
			{
				if (cols.length != ROW_COLUMNS)
				{
					throw new IllegalStateException("malformed transport-types.tsv row: " + line);
				}
				if (rows.put(cols[0], cols) != null)
				{
					throw new IllegalStateException("duplicate transport-types.tsv row: " + cols[0]);
				}
			});
		}
		catch (Exception e)
		{
			throw new IllegalStateException("failed to load " + path.substring(1), e);
		}
		return Collections.unmodifiableMap(rows);
	}

	/**
	 * Row table loaded from the bundled {@code transport-types.tsv} — a
	 * nested holder so the load happens on first constant construction;
	 * the enum's own static initializers would run too late (after every
	 * constant is already built).
	 */
	private static final class Rows
	{
		private static final Map<String, String[]> BY_NAME = loadRows("/transport-types.tsv");
	}

	public boolean hasResourcePath()
	{
		return resourcePath != null;
	}

	public boolean hasRadiusThreshold()
	{
