/**
 * Owns the plugin's widget and viewport geometry: the world-map point
 * conversions that turn canvas coordinates into packed world points, the
 * world-map open guard and drawable clip area the map overlays draw
 * through, the minimap clip area the overlays and the menu code draw
 * through, and the last-opened menu position the selection read resolves
 * against. The clip
 * area and the two mask sprites it is built from are cached and invalidated
 * together whenever the minimap widget's bounds change — the self-assigning
 * bounds check is the single invalidation point.
 * <p>
 * This package is a leaf: nothing here may reference the plugin type.
 */
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class WidgetGeometry
{
	private final Client client;
	private final SpriteManager spriteManager;

	private Point lastMenuOpenedPoint;
	private Shape minimapClipFixed;
	private Shape minimapClipResizeable;
	private BufferedImage minimapSpriteFixed;
	private BufferedImage minimapSpriteResizeable;
	private Rectangle minimapRectangle = new Rectangle();

	/**
	 * Detached-sprite seam for tests that exercise only the map reads —
	 * the clip arms need a sprite manager, so callers probing the minimap
	 * caches wire the full constructor.
	 */
	WidgetGeometry(Client client)
	{
		this(client, null);
	}

	/**
	 * Records where the canvas sat when a menu opened — the single write
	 * path for the point {@link #getSelectedWorldPoint()} resolves against.
	 * The shell's {@code MenuOpened} forwarder supplies the mouse canvas
	 * position.
	 */
	public void menuOpened(Point menuPoint)
	{
		lastMenuOpenedPoint = menuPoint;
	}

	public int getSelectedWorldPoint()
	{
		if (client == null)
		{
			return WorldPointUtil.UNDEFINED;
		}
		if (client.getWidget(InterfaceID.Worldmap.MAP_CONTAINER) == null)
		{
			if (client.getTopLevelWorldView().getSelectedSceneTile() != null)
			{
				return WorldPointUtil.fromLocalInstance(client, client.getTopLevelWorldView().getSelectedSceneTile().getLocalLocation());
			}
		}
		else
		{
			Point menuPoint = lastMenuOpenedPoint;
			return client.isMenuOpen() && menuPoint != null
				? calculateMapPoint(menuPoint.getX(), menuPoint.getY())
				: calculateMapPoint(client.getMouseCanvasPosition().getX(), client.getMouseCanvasPosition().getY());
		}
		return WorldPointUtil.UNDEFINED;
	}

	public int calculateMapPoint(int pointX, int pointY)
	{
		if (client == null)
		{
			return WorldPointUtil.UNDEFINED;
		}
		WorldMap worldMap = client.getWorldMap();
		float zoom = worldMap.getWorldMapZoom();
		int mapPoint = WorldPointUtil.packWorldPoint(worldMap.getWorldMapPosition().getX(), worldMap.getWorldMapPosition().getY(), 0);
		int middleX = mapWorldPointToGraphicsPointX(mapPoint);
		int middleY = mapWorldPointToGraphicsPointY(mapPoint);

		if (pointX == Integer.MIN_VALUE || pointY == Integer.MIN_VALUE ||
			middleX == Integer.MIN_VALUE || middleY == Integer.MIN_VALUE)
		{
			return WorldPointUtil.UNDEFINED;
		}

		final int dx = (int) ((pointX - middleX) / zoom);
		final int dy = (int) ((-(pointY - middleY)) / zoom);

		return WorldPointUtil.dxdy(mapPoint, dx, dy);
	}

	public int mapWorldPointToGraphicsPointX(int packedWorldPoint)
	{
		if (client == null)
		{
			return Integer.MIN_VALUE;
		}
		WorldMap worldMap = client.getWorldMap();

		float pixelsPerTile = worldMap.getWorldMapZoom();

		Widget map = client.getWidget(InterfaceID.Worldmap.MAP_CONTAINER);
		if (map != null)
		{
			Rectangle worldMapRect = map.getBounds();

			int widthInTiles = (int) Math.ceil(worldMapRect.getWidth() / pixelsPerTile);

			Point worldMapPosition = worldMap.getWorldMapPosition();

			int xTileOffset = WorldPointUtil.unpackWorldX(packedWorldPoint) + widthInTiles / 2 - worldMapPosition.getX();

			int xGraphDiff = ((int) (xTileOffset * pixelsPerTile));
			xGraphDiff += (int) (pixelsPerTile - Math.ceil(pixelsPerTile / 2));
			xGraphDiff += (int) worldMapRect.getX();

			return xGraphDiff;
		}
		return Integer.MIN_VALUE;
	}

	public int mapWorldPointToGraphicsPointY(int packedWorldPoint)
	{
		if (client == null)
		{
			return Integer.MIN_VALUE;
		}
		WorldMap worldMap = client.getWorldMap();

		float pixelsPerTile = worldMap.getWorldMapZoom();

		Widget map = client.getWidget(InterfaceID.Worldmap.MAP_CONTAINER);
		if (map != null)
		{
			Rectangle worldMapRect = map.getBounds();

			int heightInTiles = (int) Math.ceil(worldMapRect.getHeight() / pixelsPerTile);

			Point worldMapPosition = worldMap.getWorldMapPosition();

			int yTileMax = worldMapPosition.getY() - heightInTiles / 2;
			int yTileOffset = (yTileMax - WorldPointUtil.unpackWorldY(packedWorldPoint) - 1) * -1;

			int yGraphDiff = (int) (yTileOffset * pixelsPerTile);
			yGraphDiff -= (int) (pixelsPerTile - Math.ceil(pixelsPerTile / 2));
			yGraphDiff = worldMapRect.height - yGraphDiff;
			yGraphDiff += (int) worldMapRect.getY();

			return yGraphDiff;
		}
		return Integer.MIN_VALUE;
	}

	/**
	 * The world-map gate shared by the map overlays: the map is open — and
	 * its projections and clip are meaningful — exactly while the
	 * MAP_CONTAINER widget exists. A detached instance answers false.
	 */
	public boolean worldMapOpen()
	{
		return client != null && client.getWidget(InterfaceID.Worldmap.MAP_CONTAINER) != null;
	}

	/**
	 * Both axes of the world-map projection in one read: {@code null} when
	 * either axis collapses to {@code Integer.MIN_VALUE} (no client, or the
	 * world map is closed), so paired consumers check a single {@code null}
	 * instead of two sentinels.
	 */
	public Point mapWorldPointToGraphicsPoint(int packedWorldPoint)
	{
		int x = mapWorldPointToGraphicsPointX(packedWorldPoint);
		int y = mapWorldPointToGraphicsPointY(packedWorldPoint);
		if (x == Integer.MIN_VALUE || y == Integer.MIN_VALUE)
		{
			return null;
		}
		return new Point(x, y);
	}

	/**
	 * The drawable area of the world map: {@code baseRectangle} minus the
	 * overview panel and surface selector while they are open. The overlay
	 * still owns the {@code setClip} call — it deliberately never restores
	 * the clip. A detached instance yields the base rectangle's area.
	 */
	public Area getWorldMapClipArea(Rectangle baseRectangle)
	{
		if (client == null)
		{
			return new Area(baseRectangle);
		}
		final Widget overview = client.getWidget(InterfaceID.Worldmap.OVERVIEW_CONTAINER);
		final Widget surfaceSelector = client.getWidget(InterfaceID.Worldmap.MAPLIST_BOX_GRAPHIC0);

		Area clipArea = new Area(baseRectangle);

		if (overview != null && !overview.isHidden())
		{
			clipArea.subtract(new Area(overview.getBounds()));
		}

		if (surfaceSelector != null && !surfaceSelector.isHidden())
		{
			clipArea.subtract(new Area(surfaceSelector.getBounds()));
		}

		return clipArea;
	}

	private Widget getMinimapDrawWidget()
	{
		if (client == null)
		{
			return null;
		}
		if (client.isResized())
		{
			if (client.getVarbitValue(VarbitID.RESIZABLE_STONE_ARRANGEMENT) == 1)
			{
				return client.getWidget(InterfaceID.ToplevelPreEoc.MINIMAP);
			}
			return client.getWidget(InterfaceID.ToplevelOsrsStretch.MINIMAP);
		}
		return client.getWidget(InterfaceID.Toplevel.MINIMAP);
	}

	private Shape getMinimapClipAreaSimple()
	{
		Widget minimapDrawArea = getMinimapDrawWidget();

		if (minimapDrawArea == null || minimapDrawArea.isHidden())
		{
			return null;
		}

		Rectangle bounds = minimapDrawArea.getBounds();

		return new Ellipse2D.Double(bounds.getX(), bounds.getY(), bounds.getWidth(), bounds.getHeight());
	}

	public Shape getMinimapClipArea()
	{
		Widget minimapWidget = getMinimapDrawWidget();

		if (minimapWidget == null || minimapWidget.isHidden() || !minimapRectangle.equals(minimapRectangle = minimapWidget.getBounds()))
		{
			minimapClipFixed = null;
			minimapClipResizeable = null;
			minimapSpriteFixed = null;
			minimapSpriteResizeable = null;
		}

		if (minimapWidget == null || minimapWidget.isHidden())
		{
			return null;
		}

		if (client.isResized())
		{
			if (minimapClipResizeable != null)
			{
				return minimapClipResizeable;
			}
			if (minimapSpriteResizeable == null)
			{
				minimapSpriteResizeable = spriteManager.getSprite(SpriteID.RESIZE_MAP_MASK, 0);
			}
			if (minimapSpriteResizeable != null)
			{
				minimapClipResizeable = bufferedImageToPolygon(minimapSpriteResizeable);
				return minimapClipResizeable;
			}
			return getMinimapClipAreaSimple();
		}
		if (minimapClipFixed != null)
		{
			return minimapClipFixed;
		}
		if (minimapSpriteFixed == null)
		{
			minimapSpriteFixed = spriteManager.getSprite(SpriteID.FIXED_MAP_MASK, 0);
		}
		if (minimapSpriteFixed != null)
		{
			minimapClipFixed = bufferedImageToPolygon(minimapSpriteFixed);
			return minimapClipFixed;
		}
		return getMinimapClipAreaSimple();
	}

	private Polygon bufferedImageToPolygon(BufferedImage image)
	{
		Color outsideColour = null;
		Color previousColour;
		final int width = image.getWidth();
		final int height = image.getHeight();
		List<java.awt.Point> points = new ArrayList<>();
		for (int y = 0; y < height; y++)
		{
			previousColour = outsideColour;
			for (int x = 0; x < width; x++)
			{
				int rgb = image.getRGB(x, y);
				int a = (rgb & 0xff000000) >>> 24;
				int r = (rgb & 0x00ff0000) >> 16;
				int g = (rgb & 0x0000ff00) >> 8;
				int b = (rgb & 0x000000ff);
				Color colour = new Color(r, g, b, a);
				if (x == 0 && y == 0)
				{
					outsideColour = colour;
					previousColour = colour;
				}
				if (!colour.equals(outsideColour) && previousColour.equals(outsideColour))
				{
					points.add(new java.awt.Point(x, y));
				}
				if ((colour.equals(outsideColour) || x == (width - 1)) && !previousColour.equals(outsideColour))
				{
					points.add(0, new java.awt.Point(x, y));
				}
				previousColour = colour;
			}
		}
		int offsetX = minimapRectangle.x;
		int offsetY = minimapRectangle.y;
		Polygon polygon = new Polygon();
		for (java.awt.Point point : points)
		{
			polygon.addPoint(point.x + offsetX, point.y + offsetY);
		}
		return polygon;
	}
}

package shortestpath;

import net.runelite.client.game.AgilityShortcut;
import org.junit.Test;
import shortestpath.transport.Transport;
import shortestpath.pathfinder.TestWorldData;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * This test checks every AgilityShortcut enum constant against the list of all transports
 * in the resource files, to ensure that our list is complete.
 * <p>
 * This test should only fail when a new AgilityShortcut enum constant is added
 * without a corresponding entry in the TSV file.
 * <p>
 * There are some known exceptions where an AgilityShortcut cannot be matched to a TSV entry,
 * for example when the Object ID changes as the result of "unlocking" the shortcut via a quest.
 * These exceptions can be added to the {@link #createExcludedIds()} method. Use this sparingly.
 */
public class AgilityShortcutTest
{
	private static final Pattern OBJECT_ID_PATTERN = Pattern.compile("\\d+");

	/**
	 * IDs that are known exceptions and cannot be matched to TSV entries.
	 * These typically represent shortcuts that change based on quest completion or other game state.
	 */
	private static final Set<Integer> EXCLUDED_OBJECT_IDS = createExcludedIds();

	private static Set<Integer> createExcludedIds()
	{
		Set<Integer> excluded = new HashSet<>();

		// These two IDs represent the same shortcut before and after a step in the 'Making Friends with My Arm' quest
		// See: https://oldschool.runescape.wiki/w/Broken_fence_(Weiss)
		excluded.add(46815);
		excluded.add(46817);

		// somehow not found in tsv
		excluded.add(23644);

		// somehow not found in tsv
		excluded.add(11948);

		// Somehow not found in tsv
		excluded.add(23568);
		excluded.add(23569);

		// The rocks in the rock cab cave is not found because the coordinate is one off. but this is where you land
		excluded.add(31697);

		return excluded;
	}

	@Test
	public void everyEnumHasTsvEntry()
	{
		Map<Integer, Set<Transport>> allTransports = TestWorldData.rawTransports();
		TransportData transportData = extractTransportData(allTransports);

		List<String> missingShortcuts = findMissingShortcuts(transportData);

		if (!missingShortcuts.isEmpty())
		{
			String errorMessage = String.join("\n", missingShortcuts);
			System.out.println("WARNING: Missing TSV entries for the following AgilityShortcut enum constants:\n" + errorMessage);
			// Non-breaking: only warn so the build does not fail when new shortcuts are added.
			// This keeps the test suite green while still surfacing the missing entries in stdout.
		}
	}

	/**
	 * Extracts coordinate and object ID data from all transports.
	 */
	private TransportData extractTransportData(Map<Integer, Set<Transport>> allTransports)
	{
		Set<String> coordinates = new HashSet<>();
		Set<Integer> objectIds = new HashSet<>();

		for (Set<Transport> transportSet : allTransports.values())
		{
			for (Transport transport : transportSet)
			{
				addCoordinatesFromTransport(transport, coordinates);
				addObjectIdsFromTransport(transport, objectIds);
			}
		}

		return new TransportData(coordinates, objectIds);
	}

	/**
	 * Adds origin and destination coordinates from a transport to the coordinate set.
	 */
	private void addCoordinatesFromTransport(Transport transport, Set<String> coordinates)
	{
		addCoordinateIfValid(transport.getOrigin(), coordinates);
		addCoordinateIfValid(transport.getDestination(), coordinates);
	}

	/**
	 * Adds a coordinate to the set if it's valid (not undefined or a permutation).
	 */
	private void addCoordinateIfValid(int packedCoordinate, Set<String> coordinates)
	{
		if (packedCoordinate != Transport.UNDEFINED_ORIGIN &&
			packedCoordinate != Transport.UNDEFINED_DESTINATION &&
			packedCoordinate != Transport.LOCATION_PERMUTATION)
		{
			String coordinate = formatCoordinate(packedCoordinate);
			coordinates.add(coordinate);
		}
	}

	/**
	 * Formats a packed coordinate as "x y plane".
	 */
	private String formatCoordinate(int packed)
	{
		int x = WorldPointUtil.unpackWorldX(packed);
		int y = WorldPointUtil.unpackWorldY(packed);
		int plane = WorldPointUtil.unpackWorldPlane(packed);
		return x + " " + y + " " + plane;
	}

	/**
	 * Extracts object IDs from the transport's object info string.
	 */
	private void addObjectIdsFromTransport(Transport transport, Set<Integer> objectIds)
	{
		String objectInfo = transport.getObjectInfo();
		if (objectInfo == null || objectInfo.isEmpty())
		{
			return;
		}

		Matcher matcher = OBJECT_ID_PATTERN.matcher(objectInfo);
		while (matcher.find())
		{
			try
			{
				objectIds.add(Integer.parseInt(matcher.group()));
			}
			catch (NumberFormatException ignored)
			{
				// Skip invalid numbers
			}
		}
	}

	/**
	 * Finds all AgilityShortcut enum constants that don't have matching TSV entries.
	 */
	private List<String> findMissingShortcuts(TransportData transportData)
	{
		List<String> missing = new ArrayList<>();

		for (AgilityShortcut shortcut : AgilityShortcut.values())
		{
			if (!isShortcutMatched(shortcut, transportData))
			{
				missing.add(shortcut.name() + " - " + shortcut.getLevel() + " - " + shortcut.getWorldLocation());
			}
		}

		return missing;
	}

	/**
	 * Checks if an AgilityShortcut matches any entry in the transport data.
	 */
	private boolean isShortcutMatched(AgilityShortcut shortcut, TransportData transportData)
	{
		// Check by world location
		if (isMatchedByLocation(shortcut, transportData.coordinates))
		{
			return true;
		}

		// Check by obstacle IDs
		return isMatchedByObstacleIds(shortcut, transportData.objectIds);
	}

	/**
	 * Checks if the shortcut's world location matches any coordinate in the transport data.
	 */
	private boolean isMatchedByLocation(AgilityShortcut shortcut, Set<String> coordinates)
	{
		if (shortcut.getWorldLocation() == null)
		{
			return false;
		}

		String coordinate = shortcut.getWorldLocation().getX() + " "
							+ shortcut.getWorldLocation().getY() + " "
							+ shortcut.getWorldLocation().getPlane();

		return coordinates.contains(coordinate);
	}

	/**
	 * Checks if any of the shortcut's obstacle IDs match object IDs in the transport data.
	 * Returns true if any non-excluded ID matches, or if all IDs are excluded.
	 */
	private boolean isMatchedByObstacleIds(AgilityShortcut shortcut, Set<Integer> objectIds)
	{
		if (shortcut.getObstacleIds() == null)
		{
			return false;
		}

		boolean hasExcludedId = false;
		for (int obstacleId : shortcut.getObstacleIds())
		{
			if (EXCLUDED_OBJECT_IDS.contains(obstacleId))
			{
				System.out.println("Skipping excluded ID " + obstacleId + " for " + shortcut.name());
				hasExcludedId = true;
				continue;
			}

			if (objectIds.contains(obstacleId))
			{
				return true;
			}
		}

		// If all IDs were excluded, consider it matched to avoid false failures
		return hasExcludedId;
	}

	/**
	 * Holds coordinate and object ID data extracted from transports.
	 */
	private static class TransportData
	{
		final Set<String> coordinates;
		final Set<Integer> objectIds;

		TransportData(Set<String> coordinates, Set<Integer> objectIds)
		{
			this.coordinates = coordinates;
			this.objectIds = objectIds;
		}
	}
}

package shortestpath;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import java.util.regex.Pattern;
import org.junit.Assert;
import org.junit.Test;
import shortestpath.transport.ResourceLoader;

/**
 * Loader-fidelity and format lint for the four destination TSV resources
 * consumed by {@link ResourceLoader#destinations()}.
 *
 * The destination TSV parse in {@link ResourceLoader} degrades silently: a row whose
 * {@code Destination} cell is not a three-part {@code x y z} coordinate is
 * skipped with at most a {@code log.error}, and a dropped resource produces a
 * missing or empty category with no failure. These tests assert the loaded
 * map's category shape, that every committed row's {@code Destination} cell is
 * a concrete three-part numeric coordinate, that every such coordinate
 * actually lands in the loaded set, and that headers carry the documented
 * destination columns.
 */
public class DestinationDataLintTest
{
	/**
	 * The exact resource paths {@link ResourceLoader#destinations()}
	 * loads, explicitly listed so a change to the consumed set is deliberate.
	 */
	private static final String[] DESTINATION_RESOURCES = {
		"/destinations/game_features/altar.tsv",
		"/destinations/game_features/bank.tsv",
		"/destinations/training/anvil.tsv",
		"/destinations/shopping/apothecary.tsv",
	};

	private static final Set<String> EXPECTED_CATEGORIES = new HashSet<>(Arrays.asList(
		"altar", "bank", "anvil", "apothecary"));

	/**
	 * Columns documented for destination TSVs: the coordinate cell plus the
	 * requirement/info columns {@link ResourceLoader} reads.
	 */
	private static final Set<String> DOCUMENTED_COLUMNS = new HashSet<>(Arrays.asList(
		"Destination", "Info", "Skills", "Quests", "Varbits", "VarPlayers"));

	private static final Pattern CONCRETE_POINT = Pattern.compile("^\\d+ \\d+ \\d+$");

	private static String readResource(String path) throws IOException
	{
		return new String(
			Util.readAllBytes(Objects.requireNonNull(ShortestPathPlugin.class.getResourceAsStream(path))),
			StandardCharsets.UTF_8);
	}

	/**
	 * The category key the destination TSV parse derives from a
	 * resource path: the path component immediately preceding the file
	 * extension (e.g. {@code /destinations/game_features/bank.tsv -> bank}).
	 */
	private static String categoryKey(String path)
	{
		String[] parts = path.replace(".", "/").split("/");
		return parts[parts.length - 2];
	}

	private static String[] headers(String contents)
	{
		String headerLine = contents.split("\n", -1)[0];
		if (headerLine.endsWith("\r"))
		{
			headerLine = headerLine.substring(0, headerLine.length() - 1);
		}
		if (headerLine.startsWith("# "))
		{
			headerLine = headerLine.substring(2);
		}
		else if (headerLine.startsWith("#"))
		{
			headerLine = headerLine.substring(1);
		}
		return headerLine.split("\t");
	}

	private static int columnIndex(String[] headers, String name)
	{
		for (int i = 0; i < headers.length; i++)
		{
			if (name.equals(headers[i]))
			{
				return i;
			}
		}
		return -1;
	}

	/**
	 * Data rows of a destination file the way the destination TSV parse
	 * sees them: lines after the header, comments and blanks skipped, split on
	 * tabs (trailing empty cells dropped, matching the loader's split).
	 */
	private static List<String[]> dataRows(String contents, List<Integer> lineNumbers)
	{
		String[] lines = contents.split("\n", -1);
		List<String[]> rows = new ArrayList<>();
		for (int i = 1; i < lines.length; i++)
		{
			String line = lines[i];
			if (line.endsWith("\r"))
			{
				line = line.substring(0, line.length() - 1);
			}
			if (line.startsWith("#") || line.isBlank())
			{
				continue;
			}
			rows.add(line.split("\t"));
			lineNumbers.add(i + 1);
		}
		return rows;
	}

	private static void report(List<String> failures, String checkName)
	{
		if (!failures.isEmpty())
		{
			StringBuilder message = new StringBuilder();
			message.append(String.format("%s found %d problem(s):\n", checkName, failures.size()));
			for (String failure : failures)
			{
				message.append("  ").append(failure).append('\n');
			}
			Assert.fail(message.toString());
		}
	}

	/**
	 * Loader fidelity: {@link ResourceLoader#destinations()} must return
	 * exactly the four consumed categories, each non-empty, and every
	 * concrete {@code Destination} cell in every committed row must land in
	 * its category's set. A resource that fails to load or a row the loader
	 * silently skips shows up here as a missing/empty category or a missing
	 * packed point.
	 */
	@Test
	public void testLoadAllFromResourcesProducesEveryRow() throws IOException
	{
		List<String> failures = new ArrayList<>();

		Map<String, Set<Integer>> destinations = ResourceLoader.destinations();
		Assert.assertEquals(
			"destinations() categories differ from the consumed resource set",
			EXPECTED_CATEGORIES, destinations.keySet());

		for (String path : DESTINATION_RESOURCES)
		{
			String category = categoryKey(path);
			Set<Integer> loaded = destinations.get(category);
			if (loaded == null || loaded.isEmpty())
			{
				failures.add(String.format(
					"%s: category '%s' is missing or empty after destinations()",
					path, category));
				continue;
			}

			String contents = readResource(path);
			String[] headers = headers(contents);
			int destinationIdx = columnIndex(headers, "Destination");
			if (destinationIdx < 0)
			{
				failures.add(path + ": header carries no Destination column");
				continue;
			}

			List<Integer> lineNumbers = new ArrayList<>();
			List<String[]> rows = dataRows(contents, lineNumbers);
			for (int i = 0; i < rows.size(); i++)
			{
				String cell = destinationIdx < rows.get(i).length ? rows.get(i)[destinationIdx] : "";
				if (!CONCRETE_POINT.matcher(cell).matches())
				{
					// Malformed cells are reported by
					// testDestinationCellsAreThreePartNumeric; skip them here.
					continue;
				}
				String[] parts = cell.split(" ");
				int packed = WorldPointUtil.packWorldPoint(
					Integer.parseInt(parts[0]),
					Integer.parseInt(parts[1]),
					Integer.parseInt(parts[2]));
				if (!loaded.contains(packed))
				{
					failures.add(String.format(
						"%s:%d: concrete destination '%s' is absent from the loaded '%s' set",
						path, lineNumbers.get(i), cell, category));
				}
			}
		}

		report(failures, "testLoadAllFromResourcesProducesEveryRow");
	}

	/**
	 * Row-shape fidelity: every non-comment row's {@code Destination} cell
	 * must be a three-part numeric {@code x y z} coordinate. The loader
	 * log-and-skips malformed cells, so a bad row is a test failure naming
	 * file+line rather than a silently dropped destination.
	 */
	@Test
	public void testDestinationCellsAreThreePartNumeric() throws IOException
	{
		List<String> failures = new ArrayList<>();

		for (String path : DESTINATION_RESOURCES)
		{
			String contents = readResource(path);
			String[] headers = headers(contents);
			int destinationIdx = columnIndex(headers, "Destination");
			if (destinationIdx < 0)
			{
				failures.add(path + ": header carries no Destination column");
				continue;
			}

			List<Integer> lineNumbers = new ArrayList<>();
			List<String[]> rows = dataRows(contents, lineNumbers);
			for (int i = 0; i < rows.size(); i++)
			{
				String cell = destinationIdx < rows.get(i).length ? rows.get(i)[destinationIdx] : "";
				if (!CONCRETE_POINT.matcher(cell).matches())
				{
					failures.add(String.format(
						"%s:%d: Destination cell '%s' is not a three-part numeric coordinate",
						path, lineNumbers.get(i), cell));
				}
			}
		}

		report(failures, "testDestinationCellsAreThreePartNumeric");
	}

	/**
	 * Header coverage: each file's header row must carry the {@code
	 * Destination} column and use only documented destination columns.
	 */
	@Test
	public void testHeadersCarryDestinationColumn() throws IOException
	{
		List<String> failures = new ArrayList<>();

		for (String path : DESTINATION_RESOURCES)
		{
			String[] headers = headers(readResource(path));
			boolean hasDestination = false;
			for (String header : headers)
			{
				if ("Destination".equals(header))
				{
					hasDestination = true;
				}
				else if (!DOCUMENTED_COLUMNS.contains(header))
				{
					failures.add(String.format(
						"%s: header cell '%s' is not a documented destination column",
						path, header));
				}
			}
			if (!hasDestination)
			{
				failures.add(path + ": header carries no Destination column");
			}
		}

		report(failures, "testHeadersCarryDestinationColumn");
	}
}

package shortestpath;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import javax.swing.JLabel;

import org.junit.Test;

/**
 * Lock semantics of {@link ExpandableSurface}: a lock (disabled expander)
 * landing on an open surface collapses it rather than leaving it stuck
 * open behind a dead chevron.
 */
public class ExpandableSurfaceTest
{
	private static ExpandableSurface surface()
	{
		ExpandableSurface surface = new ExpandableSurface(null)
		{
			@Override
			public JLabel getNameLabel()
			{
				return new JLabel("test");
			}
		};
		surface.newExpander();
		return surface;
	}

	@Test
	public void searchExpandsAnEnabledSurface()
	{
		ExpandableSurface surface = surface();
		surface.setSearchExpanded();
		assertTrue(surface.isDetailOpen());
		assertTrue(surface.detail.isVisible());
		surface.clearSearchExpanded();
		assertFalse(surface.isDetailOpen());
	}

	/**
	 * Pins the deliberate current behaviour (see
	 * {@code ShortestPathPanelLayoutTest.memberLabelSearchExpandsTheGroup}):
	 * a member-label search reveals the control even inside a master-off
	 * (disabled) group.
	 */
	@Test
	public void searchStillRevealsAMemberInsideALockedSurface()
	{
		ExpandableSurface surface = surface();
		surface.expander.setEnabled(false);
		surface.setSearchExpanded();
		assertTrue(surface.isDetailOpen());
	}

	@Test
	public void lockingAnOpenSurfaceCollapsesIt()
	{
		ExpandableSurface surface = surface();
		surface.setDetailOpen(true);
		assertTrue(surface.isDetailOpen());
		surface.expander.setEnabled(false);
		assertFalse("a lock must not leave the detail stuck open", surface.isDetailOpen());
		assertFalse(surface.detail.isVisible());
		// unlocking does not reopen it; the user owns that
		surface.expander.setEnabled(true);
		assertFalse(surface.isDetailOpen());
	}

	@Test
	public void lockingASearchOpenedSurfaceCollapsesAndDropsSearchOwnership()
	{
		ExpandableSurface surface = surface();
		surface.setSearchExpanded();
		surface.expander.setEnabled(false);
		assertFalse(surface.isDetailOpen());
		surface.expander.setEnabled(true);
		surface.clearSearchExpanded();
		assertFalse(surface.isDetailOpen());
	}
}

package shortestpath;

import ch.qos.logback.classic.Logger;
import ch.qos.logback.classic.spi.ILoggingEvent;
import ch.qos.logback.core.read.ListAppender;
import java.util.ArrayList;
import java.util.List;
import java.util.stream.Collectors;
import org.junit.rules.ExternalResource;
import org.slf4j.LoggerFactory;

/**
 * Captures the log output of the named loggers for the duration of a test and keeps it off the
 * console. Tests that feed malformed input on purpose exercise the loaders' warn/error paths; with
 * this rule those expected lines are collected here (and can be asserted on) instead of showing up
 * as WARN/ERROR noise in the build output.
 *
 * A name may be a class's logger or a package prefix; events of child loggers reach the appender
 * because logback propagates them up the logger hierarchy.
 */
public final class LogCapture extends ExternalResource
{
	private final String[] loggerNames;
	private final List<Logger> loggers = new ArrayList<>();
	private final List<Boolean> additive = new ArrayList<>();
	private final ListAppender<ILoggingEvent> appender = new ListAppender<>();

	public LogCapture(String... loggerNames)
	{
		this.loggerNames = loggerNames;
	}

	@Override
	protected void before()
	{
		appender.start();
		for (String name : loggerNames)
		{
			Logger logger = (Logger) LoggerFactory.getLogger(name);
			loggers.add(logger);
			additive.add(logger.isAdditive());
			logger.addAppender(appender);
			logger.setAdditive(false);
		}
	}

	@Override
	protected void after()
	{
		for (int i = 0; i < loggers.size(); i++)
		{
			loggers.get(i).detachAppender(appender);
			loggers.get(i).setAdditive(additive.get(i));
		}
		appender.stop();
		loggers.clear();
		additive.clear();
	}

	/** Formatted messages captured so far, in order. */
	public List<String> messages()
	{
		return appender.list.stream().map(ILoggingEvent::getFormattedMessage).collect(Collectors.toList());
	}

	public void clear()
	{
		appender.list.clear();
	}
}

package shortestpath;

import net.runelite.api.Quest;
import net.runelite.api.Skill;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import shortestpath.transport.Transport;
import shortestpath.transport.ResourceLoader;
import shortestpath.transport.TransportType;
import shortestpath.requirement.model.SkillLevels;
import shortestpath.requirement.model.TransportItems;

import java.util.HashMap;
import java.util.Map;
import java.util.Set;

/**
 * Unit tests for the Observatory Grapple Shortcut transport.
 * Tests the transport at coordinates 2449 3155 0 to 2444 3165 0 with requirements:
 * - 23 Agility
 * - CROSSBOW=1
 * - MITH_GRAPPLE=1
 * - Observatory Quest
 */
public class ObservatoryGrappleShortcutTest
{

	private Map<Integer, Set<Transport>> transports;
	private static final String TRANSPORT_DATA =
		"# Origin\tDestination\tmenuOption menuTarget objectID\tSkills\tItems\tVarbits\tVarPlayers\tDuration\tQuests\n" +
		"2449 3155 0\t2444 3165 0\tGrapple Rocks 31850\t23 Agility\tCROSSBOW=1&MITH_GRAPPLE=1\t\t\t\tObservatory Quest\n";

	@Before
	public void setUp()
	{
		transports = new HashMap<>();
		ResourceLoader.addTransportsFromContents(transports, TRANSPORT_DATA, TransportType.GRAPPLE_SHORTCUT, 0);
	}

	private Transport getTransport()
	{
		int origin = WorldPointUtil.packWorldPoint(2449, 3155, 0);
		Set<Transport> transportSet = transports.get(origin);
		Assert.assertNotNull("Transport set should exist for origin", transportSet);
		Assert.assertEquals("Should have exactly one transport", 1, transportSet.size());
		return transportSet.iterator().next();
	}

	/**
	 * Scenario 1: Verify that the transport has the correct 23 Agility requirement
	 */
	@Test
	public void testHasAgilityRequirement()
	{
		Transport transport = getTransport();

		int agilityLevel = transport.getSkillLevels().get(Skill.AGILITY);
		Assert.assertEquals("Transport should require 23 Agility", 23, agilityLevel);
	}

	/**
	 * Scenario 2: Verify that the transport requires a crossbow item
	 */
	@Test
	public void testHasCrossbowRequirement()
	{
		Transport transport = getTransport();

		TransportItems items = transport.getItemRequirements();
		Assert.assertNotNull("Transport should have item requirements", items);

		int[][] requiredItems = items.getItems();
		int[] quantities = items.getQuantities();

		Assert.assertEquals("Should have two item requirements (CROSSBOW and MITH_GRAPPLE)", 2, requiredItems.length);

		// Find the crossbow requirement
		boolean foundCrossbow = false;
		for (int i = 0; i < requiredItems.length; i++)
		{
			int[] itemGroup = requiredItems[i];
			// Check if this group contains any crossbow variant
			// The CROSSBOW ItemVariation should expand to multiple crossbow types
			if (itemGroup.length > 1)
			{
				// Crossbows have multiple variants
				foundCrossbow = true;
				Assert.assertEquals("Crossbow quantity should be 1", 1, quantities[i]);
				break;
			}
		}

		Assert.assertTrue("Transport should require a crossbow", foundCrossbow);
	}

	/**
	 * Scenario 3: Verify that the transport requires a mithril grapple item
	 */
	@Test
	public void testHasMithrilGrappleRequirement()
	{
		Transport transport = getTransport();

		TransportItems items = transport.getItemRequirements();
		Assert.assertNotNull("Transport should have item requirements", items);

		int[][] requiredItems = items.getItems();
		int[] quantities = items.getQuantities();

		Assert.assertEquals("Should have two item requirements (CROSSBOW and MITH_GRAPPLE)", 2, requiredItems.length);

		// Find the mithril grapple requirement
		boolean foundMithGrapple = false;
		for (int i = 0; i < requiredItems.length; i++)
		{
			int[] itemGroup = requiredItems[i];
			// MITH_GRAPPLE should be a single item (ItemID.XBOWS_GRAPPLE_TIP_BOLT_MITHRIL_ROPE)
			if (itemGroup.length == 1)
			{
				foundMithGrapple = true;
				Assert.assertEquals("Mithril grapple quantity should be 1", 1, quantities[i]);
				break;
			}
		}

		Assert.assertTrue("Transport should require a mithril grapple", foundMithGrapple);
	}

	/**
	 * Scenario 4: Verify that the transport requires Observatory Quest completion
	 */
	@Test
	public void testHasObservatoryQuestRequirement()
	{
		Transport transport = getTransport();

		Set<Quest> quests = transport.getQuests();
		Assert.assertNotNull("Transport should have quest requirements", quests);
		Assert.assertEquals("Should have exactly one quest requirement", 1, quests.size());
		Assert.assertTrue("Should require Observatory Quest", quests.contains(Quest.OBSERVATORY_QUEST));
		Assert.assertTrue("Transport should be quest locked", transport.isQuestLocked());
	}

	/**
	 * Scenario 5: Verify that other skill levels are not required (should be 0)
	 */
	@Test
	public void testNoOtherSkillRequirements()
	{
		Transport transport = getTransport();

		SkillLevels skillLevels = transport.getSkillLevels();

		// Check all skills except Agility should be 0
		for (Skill skill : Skill.values())
		{
			if (skill != Skill.AGILITY)
			{
				int level = skillLevels.get(skill);
				Assert.assertEquals("Skill " + skill.getName() + " should not be required", 0, level);
			}
		}

		// Check total level, combat level, and quest points (the +3 tail)
		Assert.assertEquals("Total level should not be required", 0, skillLevels.get(SkillLevels.TOTAL_LEVEL_INDEX));
		Assert.assertEquals("Combat level should not be required", 0, skillLevels.get(SkillLevels.COMBAT_LEVEL_INDEX));
		Assert.assertEquals("Quest points should not be required", 0, skillLevels.get(SkillLevels.QUEST_POINTS_INDEX));
	}

	/**
	 * Scenario 6: Verify the transport has correct origin and destination coordinates
	 */
	@Test
	public void testTransportCoordinates()
	{
		Transport transport = getTransport();

		int expectedOrigin = WorldPointUtil.packWorldPoint(2449, 3155, 0);
		int expectedDestination = WorldPointUtil.packWorldPoint(2444, 3165, 0);

		Assert.assertEquals("Origin should be 2449 3155 0", expectedOrigin, transport.getOrigin());
		Assert.assertEquals("Destination should be 2444 3165 0", expectedDestination, transport.getDestination());

		// Verify unpacked coordinates
		Assert.assertEquals("Origin X should be 2449", 2449, WorldPointUtil.unpackWorldX(transport.getOrigin()));
		Assert.assertEquals("Origin Y should be 3155", 3155, WorldPointUtil.unpackWorldY(transport.getOrigin()));
		Assert.assertEquals("Origin plane should be 0", 0, WorldPointUtil.unpackWorldPlane(transport.getOrigin()));

		Assert.assertEquals("Destination X should be 2444", 2444, WorldPointUtil.unpackWorldX(transport.getDestination()));
		Assert.assertEquals("Destination Y should be 3165", 3165, WorldPointUtil.unpackWorldY(transport.getDestination()));
		Assert.assertEquals("Destination plane should be 0", 0, WorldPointUtil.unpackWorldPlane(transport.getDestination()));
	}

	/**
	 * Bonus Scenario: Verify the transport has correct object information
	 */
	@Test
	public void testObjectInformation()
	{
		Transport transport = getTransport();

		String objectInfo = transport.getObjectInfo();
		Assert.assertNotNull("Transport should have object info", objectInfo);
		Assert.assertEquals("Object info should match", "Grapple Rocks 31850", objectInfo);
	}

	/**
	 * Bonus Scenario: Verify the transport type is GRAPPLE_SHORTCUT
	 */
	@Test
	public void testTransportType()
	{
		Transport transport = getTransport();

		Assert.assertEquals("Transport type should be GRAPPLE_SHORTCUT",
			TransportType.GRAPPLE_SHORTCUT, transport.getType());
	}
}

package shortestpath;

import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.Mockito.doAnswer;
import static org.mockito.Mockito.doReturn;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import java.lang.reflect.Field;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.BlockingQueue;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.LinkedBlockingQueue;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.TimeoutException;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.BooleanSupplier;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.Skill;
import net.runelite.api.gameval.DBTableID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.events.PluginMessage;
import net.runelite.client.ui.overlay.worldmap.WorldMapPointManager;
import shortestpath.pathfinder.ActiveSearch;
import shortestpath.pathfinder.TestPathfinderConfig;
import shortestpath.pathfinder.TestWorldData;
import shortestpath.settings.TeleportationItem;

/**
 * Drives a real {@link ShortestPathPlugin} through its public plugin-message API, the way another
 * plugin does: messages go in through {@code onPluginMessage}, and the plugin's own messages are
 * captured from the event bus. The game client is mocked, with an inventory, worn items and a bank
 * the test sets; the pathfinder runs on the real map and transport data.
 *
 * <p>The client thread runs work immediately on the calling thread, and the test thread is the
 * client thread, so every refresh and restart happens synchronously; only searches run on the
 * plugin's pathfinding thread.
 */
final class PluginApiHarness implements AutoCloseable
{
	private static final long TIMEOUT_SECONDS = 60;
	private static final AtomicInteger IDS = new AtomicInteger();

	final ShortestPathPlugin plugin = new ShortestPathPlugin();
	private shortestpath.scheduler.PathScheduler scheduler;
	private shortestpath.presentation.PathAnnotator annotator;
	final Settings settings = new Settings();
	private final Client client = mock(Client.class);
	private final ItemContainer inventory = mock(ItemContainer.class);
	private final ItemContainer worn = mock(ItemContainer.class);
	private final BlockingQueue<PluginMessage> posted = new LinkedBlockingQueue<>();
	private final TestPathfinderConfig pathfinderConfig;
	private shortestpath.items.ItemStateService itemState;

	/** Plugin settings with the values the tests change. */
	static final class Settings extends TestShortestPathConfig
	{
		boolean includeBankPath;
		int costBankVisit;
		TeleportationItem teleportationItems = TeleportationItem.NONE;
		int calculationCutoff = 50;

		@Override
		public Object value(String keyName)
		{
			switch (keyName)
			{
				case "includeBankPath":
					return includeBankPath;
				case "costBankVisit":
					return costBankVisit;
				case "useTeleportationItems":
					return teleportationItems;
				case "calculationCutoff":
					return calculationCutoff;
				default:
					return super.value(keyName);
			}
		}
	}

	PluginApiHarness()
	{
		Thread clientThreadOwner = Thread.currentThread();
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getClientThread()).thenReturn(clientThreadOwner);
		when(client.getDBTableRows(DBTableID.Quest.ID)).thenReturn(List.of());
		when(client.getBoostedSkillLevel(any(Skill.class))).thenReturn(99);
		when(client.getRealSkillLevel(any(Skill.class))).thenReturn(99);
		doReturn(inventory).when(client).getItemContainer(InventoryID.INV);
		doReturn(worn).when(client).getItemContainer(InventoryID.WORN);
		doAnswer(call ->
		{
			ItemComposition item = mock(ItemComposition.class);
			when(item.getName()).thenReturn("Item " + call.getArgument(0));
			return item;
		}).when(client).getItemDefinition(anyInt());
		carry();
		wear();

		ClientThread clientThread = mock(ClientThread.class);
		doAnswer(call ->
		{
			((Runnable) call.getArgument(0)).run();
			return null;
		}).when(clientThread).invokeLater(any(Runnable.class));
		doAnswer(call -> ((BooleanSupplier) call.getArgument(0)).getAsBoolean())
			.when(clientThread).invokeLater(any(BooleanSupplier.class));

		EventBus eventBus = mock(EventBus.class);
		doAnswer(call ->
		{
			Object event = call.getArgument(0);
			if (event instanceof PluginMessage)
			{
				posted.add((PluginMessage) event);
			}
			return null;
		}).when(eventBus).post(any());

		pathfinderConfig = new TestPathfinderConfig(client, settings);
		shortestpath.settings.Settings settingsService = shortestpath.settings.Settings.wrap(settings);
		set("client", client);
		set("clientThread", clientThread);
		set("config", settings);
		set("settings", settingsService);
		shortestpath.poh.PohService pohService = shortestpath.poh.PohTestServices.forTesting();
		set("pohService", pohService);
		set("pathfinderConfig", pathfinderConfig);
		// The harness builds the plugin without DI, so the scheduler, the refresh
		// coordinator and the attach-time bindings are seeded the same way the
		// shell's startUp wires them. The world map point manager moved into the
		// scheduler with the marker machinery, and the item-state service declares
		// its change facts straight to the coordinator.
		scheduler = new shortestpath.scheduler.PathScheduler(client, clientThread, settingsService,
			mock(WorldMapPointManager.class), new shortestpath.scheduler.DebugState());
		shortestpath.scheduler.RefreshCoordinator coordinator =
			new shortestpath.scheduler.RefreshCoordinator(scheduler, settingsService);
		itemState = shortestpath.items.ItemStateTestServices.forTesting(coordinator);
		shortestpath.sailing.SailingService sailing =
			shortestpath.sailing.SailingTestServices.forTesting(client, coordinator);
		pathfinderConfig.setItemStateService(itemState);
		pathfinderConfig.setSailingService(sailing);
		set("itemState", itemState);
		set("sailing", sailing);
		annotator =
			shortestpath.presentation.PathAnnotatorTestServices.forTesting(client, pohService, itemState);
		annotator.attach(pathfinderConfig);
		set("annotator", annotator);
		shortestpath.api.PluginMessageHandler apiHandler =
			new shortestpath.api.PluginMessageHandler(client, clientThread, eventBus, scheduler,
				coordinator, settingsService, annotator);
		set("apiHandler", apiHandler);
		scheduler.attach(pathfinderConfig, sailing, apiHandler);
		set("scheduler", scheduler);
		set("coordinator", coordinator);
		// The A* backend's static data takes seconds to build, so the harness injects the
		// provider that already memoized it for the whole JVM rather than building its own.
		set("aStarRoutingStatic", TestWorldData.routingStaticProvider());
	}

	private void set(String name, Object value)
	{
		try
		{
			Field field = ShortestPathPlugin.class.getDeclaredField(name);
			field.setAccessible(true);
			field.set(plugin, value);
		}
		catch (NoSuchFieldException e)
		{
			// Fields the pathfinding machinery move relocated onto the scheduler.
			try
			{
				Field field = shortestpath.scheduler.PathScheduler.class.getDeclaredField(name);
				field.setAccessible(true);
				field.set(scheduler, value);
			}
			catch (ReflectiveOperationException e2)
			{
				throw new AssertionError(e2);
			}
		}
		catch (ReflectiveOperationException e)
		{
			throw new AssertionError(e);
		}
	}

	/** Sets the inventory, as alternating item id and quantity. */
	PluginApiHarness carry(int... idsAndQuantities)
	{
		doReturn(items(idsAndQuantities)).when(inventory).getItems();
		return this;
	}

	/** Sets the worn items, as alternating item id and quantity. */
	PluginApiHarness wear(int... idsAndQuantities)
	{
		doReturn(items(idsAndQuantities)).when(worn).getItems();
		return this;
	}

	/** Sets the bank as seen this session, as alternating item id and quantity. */
	PluginApiHarness bank(int... idsAndQuantities)
	{
		ItemContainer bank = mock(ItemContainer.class);
		doReturn(items(idsAndQuantities)).when(bank).getItems();
		itemState.noteBankContainer(bank);
		return this;
	}

	/** Forgets the bank, as before it is first opened in a session. */
	PluginApiHarness bankNotSeen()
	{
		itemState.noteBankContainer(null);
		return this;
	}

	private static Item[] items(int... idsAndQuantities)
	{
		Item[] items = new Item[idsAndQuantities.length / 2];
		for (int i = 0; i < items.length; i++)
		{
			items[i] = new Item(idsAndQuantities[2 * i], idsAndQuantities[2 * i + 1]);
		}
		return items;
	}

	void send(String name, Map<String, Object> data)
	{
		plugin.onPluginMessage(new PluginMessage(ShortestPathPlugin.CONFIG_GROUP, name, data));
	}

	/** Sends a {@code path} message and waits for the displayed search it starts to finish. */
	ActiveSearch path(Object start, Object target)
	{
		Map<String, Object> data = new HashMap<>();
		if (start != null)
		{
			data.put("start", start);
		}
		if (target != null)
		{
			data.put("target", target);
		}
		ActiveSearch before = scheduler.getActiveSearch();
		send("path", data);
		ActiveSearch search = scheduler.getActiveSearch();
		if (search == null || search == before)
		{
			return search;
		}
		awaitDone(search);
		return search;
	}

	void awaitDone(ActiveSearch search)
	{
		long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(TIMEOUT_SECONDS);
		while (!search.isDone() || search.getResult() == null)
		{
			if (System.nanoTime() > deadline)
			{
				throw new AssertionError("the displayed search did not finish");
			}
			Thread.onSpinWait();
		}
	}

	/** Sends a {@code query} message and waits for its {@code result}. */
	Map<String, Object> query(Object start, Object target)
	{
		Object id = "query-" + IDS.incrementAndGet();
		Map<String, Object> data = new HashMap<>();
		data.put("id", id);
		data.put("start", start);
		data.put("target", target);
		send("query", data);
		Map<String, Object> result = awaitReply("result", id);
		awaitPathfindingThreadIdle();
		return result;
	}

	/**
	 * Waits for the pathfinding thread to finish its current task. The plugin forgets a finished
	 * query just after posting its result, and refreshes the player's items for the next query only
	 * once no query is left. In the client the result reaches the caller a frame later, but here it
	 * arrives at once, so a test that changes items and queries again must wait for that clean-up.
	 */
	private void awaitPathfindingThreadIdle()
	{
		try
		{
			Runnable nothing = () ->
			{
			};
			((ExecutorService) get("pathfindingExecutor")).submit(nothing).get(TIMEOUT_SECONDS, TimeUnit.SECONDS);
		}
		catch (InterruptedException e)
		{
			Thread.currentThread().interrupt();
			throw new AssertionError(e);
		}
		catch (ExecutionException | TimeoutException e)
		{
			throw new AssertionError(e);
		}
	}

	/** Sends a {@code getTarget} message and returns the {@code currentTarget} reply. */
	Map<String, Object> currentTarget()
	{
		Object id = "target-" + IDS.incrementAndGet();
		Map<String, Object> data = new HashMap<>();
		data.put("id", id);
		send("getTarget", data);
		return awaitReply("currentTarget", id);
	}

	private Map<String, Object> awaitReply(String name, Object id)
	{
		List<PluginMessage> skipped = new ArrayList<>();
		try
		{
			long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(TIMEOUT_SECONDS);
			while (true)
			{
				PluginMessage message = posted.poll(deadline - System.nanoTime(), TimeUnit.NANOSECONDS);
				if (message == null)
				{
					throw new AssertionError("no " + name + " message for " + id);
				}
				if (name.equals(message.getName()) && id.equals(message.getData().get("id")))
				{
					return message.getData();
				}
				skipped.add(message);
			}
		}
		catch (InterruptedException e)
		{
			Thread.currentThread().interrupt();
			throw new AssertionError(e);
		}
		finally
		{
			posted.addAll(skipped);
		}
	}

	/** The missing-items label the displayed path draws on the player's tile, or null. */
	String missingItemsLabel()
	{
		return annotator.getMissingTargetItemsText(scheduler.getActiveSearch());
	}

	/** The search currently displayed by the plugin, as the scheduler reports it. */
	ActiveSearch activeSearch()
	{
		return scheduler.getActiveSearch();
	}

	/** The bank-pickup projection for the shown path, as the annotator reports it. */
	shortestpath.presentation.BankPickupRequirements.BankPickupResult bankPickup(
		List<shortestpath.pathfinder.PathStep> path, int index, ActiveSearch search)
	{
		return ((shortestpath.presentation.PathAnnotator) get("annotator"))
			.getBankPickup(path, index, search);
	}

	@Override
	public void close()
	{
		send("clear", new HashMap<>());
		((ExecutorService) get("pathfindingExecutor")).shutdownNow();
	}

	private Object get(String name)
	{
		try
		{
			Field field = ShortestPathPlugin.class.getDeclaredField(name);
			field.setAccessible(true);
			return field.get(plugin);
		}
		catch (NoSuchFieldException e)
		{
			try
			{
				Field field = shortestpath.scheduler.PathScheduler.class.getDeclaredField(name);
				field.setAccessible(true);
				return field.get(scheduler);
			}
			catch (ReflectiveOperationException e2)
			{
				throw new AssertionError(e2);
			}
		}
		catch (ReflectiveOperationException e)
		{
			throw new AssertionError(e);
		}
	}
}

