package shortestpath.overlay;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.geom.Path2D;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.List;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;
import org.junit.Test;

/**
 * Self-pins for the recording delegate: the transcript records call order with
 * inherited draw state, {@code create()} children write into the same
 * transcript (the ArrowHead tunnel), and font metrics delegate for real.
 */
public class RecordingGraphics2DTest
{
	private static RecordingGraphics2D recorder(List<String> transcript)
	{
		BufferedImage image = new BufferedImage(64, 64, BufferedImage.TYPE_INT_ARGB);
		return new RecordingGraphics2D(image.createGraphics(), transcript);
	}

	@Test
	public void recordsCallOrderWithInheritedState()
	{
		List<String> transcript = new ArrayList<>();
		Graphics2D g = recorder(transcript);
		g.setColor(Color.RED);
		g.setStroke(new BasicStroke(4));
		g.setClip(2, 3, 20, 20);
		g.drawLine(1, 2, 3, 4);
		g.drawString("hi", 5, 6);
		g.dispose();

		assertEquals(6, transcript.size());
		assertTrue(transcript.get(0).startsWith("setColor rgb(255,0,0) a=255"));
		assertTrue(transcript.get(1).startsWith("setStroke BasicStroke(w=4.0)"));
		assertTrue(transcript.get(2).startsWith("setClip 2,3 20x20"));
		// Inherited state is captured at call time: the draw carries the
		// colour/stroke/clip the callee saw.
		String line = transcript.get(3);
		assertTrue(line.startsWith("drawLine 1,2->3,4"));
		assertTrue(line.contains("color=rgb(255,0,0) a=255"));
		assertTrue(line.contains("stroke=BasicStroke(w=4.0)"));
		assertTrue(line.contains("clip=Rect("));
		assertTrue(transcript.get(4).startsWith("drawString \"hi\" @5,6"));
		assertEquals("dispose | color=rgb(255,0,0) a=255 stroke=BasicStroke(w=4.0) clip=Rect(2.0,3.0 20.0x20.0)",
			transcript.get(5));
	}

	@Test
	public void createdChildrenShareTheTranscript()
	{
		// ArrowHead.draw's graphics.create()/dispose() draws must land in the
		// log — a raw-delegate child would lose them.
		List<String> transcript = new ArrayList<>();
		Graphics2D g = recorder(transcript);
		Graphics2D child = (Graphics2D) g.create();
		child.fill(new Rectangle(1, 1, 4, 4));
		child.dispose();

		assertEquals(3, transcript.size());
		assertTrue(transcript.get(0).startsWith("create"));
		assertTrue(transcript.get(1).startsWith("fill Rect("));
		assertTrue(transcript.get(2).startsWith("dispose"));
	}

	@Test
	public void fontMetricsAreReal()
	{
		List<String> transcript = new ArrayList<>();
		Graphics2D g = recorder(transcript);
		// drawCounter/drawLabel centre on getStringBounds — fake metrics would
		// poison the golden's coordinates.
		double width = g.getFontMetrics().getStringBounds("counter", g).getWidth();
		assertTrue("real font metrics give a positive width", width > 0);
	}

	@Test
	public void shapeStringificationRoundsToOneDecimal()
	{
		// The mask point for wall-clock-phased args: segment signature stays exact.
		Path2D path = new Path2D.Double();
		path.moveTo(1.234, 5.678);
		path.lineTo(9.999, 0.001);
		path.closePath();
		assertEquals("Path2D(M L Z)", RecordingGraphics2D.shape(path));
	}

	@Test
	public void goldenCompareFailsOnDrift()
	{
		// compareOrRegen must detect a mismatch — a comparator that can't fail
		// is no oracle. Point it at a missing scenario and demand the failure
		// message names it (regen path is exercised end-to-end by the
		// transcript suite's recorded goldens).
		try
		{
			TranscriptGolden.compareOrRegen("definitely-not-a-real-scenario", List.of("x"));
			fail("missing golden must fail");
		}
		catch (AssertionError expected)
		{
			assertTrue(expected.getMessage().contains("definitely-not-a-real-scenario"));
		}
	}
}

package shortestpath.overlay;

import java.io.IOException;
import java.io.InputStream;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

import org.junit.Assert;

/**
 * Golden-transcript compare/regenerate helper for the overlay draw-call tests.
 *
 * <p>Each scenario's expected transcript lives at
 * {@code src/test/resources/overlay-transcripts/<scenario>.txt}, loaded through
 * the test classpath (the Gradle {@code java} plugin puts
 * {@code src/test/resources} on it — no build file change needed). One line
 * per recorded call; the comparison is a line diff that reports the first
 * mismatch with its line number so a drift reads immediately.
 *
 * <p>Regeneration is gated on the {@code TRANSCRIPT_REGEN} environment
 * variable — an env var rather than a {@code -D} flag because Gradle test JVMs
 * do not inherit CLI system properties without a {@code systemProperty} line
 * in {@code build.gradle}, which stays untouched:
 *
 * <pre>TRANSCRIPT_REGEN=1 ./gradlew -p shortest-path test --tests '*OverlayTranscriptTest*'</pre>
 *
 * Only the values {@code 1} and {@code true} opt in — a stray
 * {@code TRANSCRIPT_REGEN} set to anything else is ignored with a stderr
 * note, and the suite compares normally. When regen is active a banner and
 * every rewritten file go to stderr so the run cannot read as an ordinary
 * green pass: nothing is compared while regenerating.
 *
 * Regen is for deliberate draw changes only — the goldens are the
 * consolidation oracle, so a regen that masks accidental drift voids it.
 * The write goes to the source tree (the Gradle test working directory is the
 * {@code shortest-path} project dir), then a clean re-run compares.
 */
final class TranscriptGolden
{
	private static final String RESOURCE_DIR = "overlay-transcripts";
	private static final boolean REGEN = regenRequested();
	private static boolean regenAnnounced;
	/**
	 * The {@code @x,y} coordinate pair a {@code drawString} record carries
	 * — the last such pair on the line, pinned by the {@code | state}
	 * suffix or end-of-line so a coordinate-shaped substring inside the
	 * quoted text cannot be mistaken for it.
	 */
	private static final Pattern DRAW_STRING_COORDS =
		Pattern.compile(" @(-?\\d+(?:\\.\\d+)?),(-?\\d+(?:\\.\\d+)?)(?= \\| |$)");
	/**
	 * Cross-platform slack on {@code drawString} coordinates. The
	 * transcript harness renders with the graphics' default logical font,
	 * whose physical face differs between macOS and Linux: centred labels
	 * land ~10px off horizontally ({@code getStringBounds().getWidth()}),
	 * and the baseline sits ~1px lower ({@code textBounds.getHeight()} is
	 * a pixel shorter). The goldens were recorded on macOS. Both drifts
	 * are font-metric only — the text and draw state stay byte-exact, and
	 * fixed-position drawStrings (canvas-anchored counters) differ by 0,
	 * so the tolerances forfeit nothing on deterministic output while a
	 * real anchoring change shifts coordinates by far more than the
	 * slack. y gets the tighter bound: label line spacing is ~17px, so
	 * 8px still catches a dropped or reordered line.
	 */
	private static final double DRAW_STRING_X_TOLERANCE = 32.0;
	private static final double DRAW_STRING_Y_TOLERANCE = 8.0;

	private TranscriptGolden()
	{
	}

	private static boolean regenRequested()
	{
		String value = System.getenv("TRANSCRIPT_REGEN");
		if (value == null)
		{
			return false;
		}
		if ("1".equals(value) || "true".equalsIgnoreCase(value))
		{
			return true;
		}
		// A set-but-unrecognized value must not vacuate the oracle.
		System.err.println("TRANSCRIPT_REGEN=" + value + " ignored — regeneration"
			+ " requires TRANSCRIPT_REGEN=1; comparing against goldens normally");
		return false;
	}

	static void compareOrRegen(String scenario, List<String> transcript)
	{
		String body = String.join("\n", transcript) + "\n";
		if (REGEN)
		{
			if (!regenAnnounced)
			{
				regenAnnounced = true;
				System.err.println("TRANSCRIPT_REGEN active — rewriting goldens,"
					+ " nothing is being compared");
			}
			regen(scenario, body);
			System.err.println("  rewrote " + scenario + ".txt");
			return;
		}
		String expected = read(scenario);
		String[] expectedLines = expected.split("\n", -1);
		String[] actualLines = body.split("\n", -1);
		for (int i = 0; i < Math.max(expectedLines.length, actualLines.length); i++)
		{
			String e = i < expectedLines.length ? expectedLines[i] : "<missing>";
			String a = i < actualLines.length ? actualLines[i] : "<missing>";
			if (!linesEqual(e, a))
			{
				Assert.fail(scenario + " transcript drift at line " + (i + 1)
					+ "\n  expected: " + e + "\n  actual:   " + a
					+ "\n(regenerate with TRANSCRIPT_REGEN=1 only for a deliberate draw change)");
			}
		}
	}

	/**
	 * One transcript line against the golden's — byte-exact except on
	 * {@code drawString} lines, where the coordinates absorb
	 * cross-platform font-metric drift within
	 * {@link #DRAW_STRING_X_TOLERANCE} / {@link #DRAW_STRING_Y_TOLERANCE}.
	 * The quoted text and the whole {@code | color/stroke/clip} suffix
	 * stay exact.
	 */
	private static boolean linesEqual(String expected, String actual)
	{
		if (expected.equals(actual))
		{
			return true;
		}
		if (!expected.startsWith("drawString") || !actual.startsWith("drawString"))
		{
			return false;
		}
		String[] e = splitDrawString(expected);
		String[] a = splitDrawString(actual);
		if (e == null || a == null || !e[0].equals(a[0]) || !e[3].equals(a[3]))
		{
			return false;
		}
		return Math.abs(Double.parseDouble(e[1]) - Double.parseDouble(a[1]))
				<= DRAW_STRING_X_TOLERANCE
			&& Math.abs(Double.parseDouble(e[2]) - Double.parseDouble(a[2]))
				<= DRAW_STRING_Y_TOLERANCE;
	}

	/**
	 * Splits a {@code drawString} line into the text through the {@code @}
	 * sign, the x and y coordinates, and the draw-state suffix.
	 * {@code null} when the line carries no pinned coordinate pair —
	 * such lines never tolerate an inexact match.
	 */
	private static String[] splitDrawString(String line)
	{
		Matcher m = DRAW_STRING_COORDS.matcher(line);
		if (!m.find())
		{
			return null;
		}
		return new String[]{
			line.substring(0, m.start()),
			m.group(1),
			m.group(2),
			line.substring(m.end())
		};
	}

	private static String read(String scenario)
	{
		String name = RESOURCE_DIR + "/" + scenario + ".txt";
		try (InputStream in = TranscriptGolden.class.getClassLoader().getResourceAsStream(name))
		{
			if (in == null)
			{
				Assert.fail("missing golden " + name + " — record it with TRANSCRIPT_REGEN=1");
			}
			return new String(in.readAllBytes(), StandardCharsets.UTF_8);
		}
		catch (IOException e)
		{
			throw new UncheckedIOException(e);
		}
	}

	private static void regen(String scenario, String body)
	{
		Path out = Paths.get("src/test/resources", RESOURCE_DIR, scenario + ".txt");
		try
		{
			Files.createDirectories(out.getParent());
			Files.write(out, body.getBytes(StandardCharsets.UTF_8));
		}
		catch (IOException e)
		{
			throw new UncheckedIOException(e);
		}
	}
}

package shortestpath.pathfinder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.doReturn;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import java.util.EnumSet;
import java.util.List;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;
import net.runelite.api.gameval.DBTableID;
import net.runelite.api.gameval.InventoryID;
import org.junit.BeforeClass;
import org.junit.Test;
import shortestpath.TestShortestPathConfig;
import shortestpath.settings.TeleportationItem;
import shortestpath.WorldPointUtil;
import shortestpath.leagues.LeagueRegion;
import shortestpath.pathfinder.astar.RoutingStatic;

/**
 * A* honours {@code avoidWilderness} and the league's always-blocked region like legacy:
 * nothing may enter the gated area on foot, and a global teleport cast outside the wilderness
 * cannot land inside. The same exemptions apply in both backends: starting inside the gated area
 * may still leave it, and a target inside it lifts the gate entirely.
 */
public class AStarAvoidWildernessParityTest
{
	private static final int LUMBRIDGE = WorldPointUtil.packWorldPoint(3222, 3218, 0);
	private static final int VARROCK = WorldPointUtil.packWorldPoint(3210, 3424, 0);
	/** A safe pocket surrounded by wilderness: on foot it can only be entered through it. */
	private static final int FEROX_ENCLAVE = WorldPointUtil.packWorldPoint(3141, 3630, 0);
	private static final int CHAOS_TEMPLE = WorldPointUtil.packWorldPoint(3231, 3608, 0);
	/** Level-27 wilderness (benchmark early/quest-natural-0006's start). */
	private static final int START_WILDERNESS = WorldPointUtil.packWorldPoint(3051, 3736, 0);
	/** Asgarnia, away from the league's always-blocked Misthalin. */
	private static final int FALADOR = WorldPointUtil.packWorldPoint(2965, 3337, 0);
	/** Deep desert camp: from Falador unreachable without crossing Misthalin or a desert
	 *  transport with item requirements a bare inventory cannot meet. */
	private static final int BEDABIN = WorldPointUtil.packWorldPoint(3181, 3135, 0);
	/** Desert border town: unlocked even while Misthalin is, so transports there stay usable. */
	private static final int AL_KHARID = WorldPointUtil.packWorldPoint(3292, 3184, 0);

	private static RoutingStatic routingStatic;

	@BeforeClass
	public static void buildRoutingStatic()
	{
		routingStatic = TestWorldData.routingStatic();
	}

	@Test
	public void wildernessCannotBeEnteredOnFootWhileAvoidingIt()
	{
		// Every walking route to Ferox crosses the wilderness; with no teleports enabled both
		// backends must give up.
		PathfinderConfig config = config(true, false);
		PathfinderResult legacy = legacy(config, LUMBRIDGE, FEROX_ENCLAVE);
		AStarPathfinder aStar = aStar(config, LUMBRIDGE, FEROX_ENCLAVE);
		assertFalse("legacy reached Ferox without entering the wilderness", legacy.isReached());
		assertFalse("aStar entered the wilderness while avoiding it", aStar.getResult().isReached());

		// Without the gate the same search walks straight through, and pays the same as legacy.
		config = config(false, false);
		legacy = legacy(config, LUMBRIDGE, FEROX_ENCLAVE);
		aStar = aStar(config, LUMBRIDGE, FEROX_ENCLAVE);
		assertTrue(legacy.isReached());
		assertTrue(aStar.getResult().isReached());
		assertEquals(legacy.getPathCost(), aStar.getResult().getPathCost());

		// The route crosses the Wilderness Ditch by transport; the landing step must report
		// which transport produced it, not just the tile it landed on.
		assertTrue("the ditch hop does not report its transport",
			aStar.getResult().getPathSteps().stream().anyMatch(
				s -> s.getTransport() != null && s.getTransport().getDestination() == s.getPackedPosition()));
	}

	@Test
	public void wildernessTargetLiftsTheGateLikeLegacy()
	{
		// A target inside the wilderness exempts the search: entering it is the point.
		PathfinderConfig config = config(true, true);
		PathfinderResult legacy = legacy(config, LUMBRIDGE, CHAOS_TEMPLE);
		AStarPathfinder aStar = aStar(config, LUMBRIDGE, CHAOS_TEMPLE);
		assertTrue(legacy.isReached());
		assertTrue(aStar.getResult().isReached());
		assertEquals(legacy.getPathCost(), aStar.getResult().getPathCost());
	}

	@Test
	public void startingInWildernessMayLeaveWhileAvoidingIt()
	{
		// The gate only bars entering the wilderness, not walking out of it.
		PathfinderConfig config = config(true, true);
		PathfinderResult legacy = legacy(config, START_WILDERNESS, LUMBRIDGE);
		AStarPathfinder aStar = aStar(config, START_WILDERNESS, LUMBRIDGE);
		assertTrue(legacy.isReached());
		assertTrue(aStar.getResult().isReached());
		assertEquals(legacy.getPathCost(), aStar.getResult().getPathCost());
	}

	@Test
	public void ordinaryRoutesNeverTouchTheWildernessWhileAvoidingIt()
	{
		PathfinderConfig config = config(true, true);
		PathfinderResult legacy = legacy(config, LUMBRIDGE, VARROCK);
		AStarPathfinder aStar = aStar(config, LUMBRIDGE, VARROCK);
		assertTrue(legacy.isReached());
		assertTrue(aStar.getResult().isReached());
		for (PathStep step : aStar.getPath())
		{
			assertFalse("route enters the wilderness", WildernessChecker.isInWilderness(step.getPackedPosition()));
		}
		assertEquals(legacy.getPathCost(), aStar.getResult().getPathCost());
	}

	@Test
	public void leagueBlockedRegionIsGatedLikeLegacy()
	{
		// Falador to the Bedabin camp cannot be routed while Misthalin is the always-blocked
		// region: the walk crosses Misthalin and the desert transports need items this account
		// does not carry, so both backends must give up.
		PathfinderConfig config = config(false, false);
		config.getLeagueModeState().setForTest(true, EnumSet.complementOf(EnumSet.of(LeagueRegion.MISTHALIN)));
		PathfinderResult legacy = legacy(config, FALADOR, BEDABIN);
		AStarPathfinder aStar = aStar(config, FALADOR, BEDABIN);
		assertFalse("legacy walked into the blocked region", legacy.isReached());
		assertFalse("aStar entered the blocked region", aStar.getResult().isReached());

		// Transports landing in an unlocked region are unaffected: Lumbridge to Al Kharid
		// crosses the Misthalin/desert gate inside Misthalin-free destination tiles.
		legacy = legacy(config, LUMBRIDGE, AL_KHARID);
		aStar = aStar(config, LUMBRIDGE, AL_KHARID);
		assertTrue(legacy.isReached());
		assertTrue(aStar.getResult().isReached());
		assertEquals(legacy.getPathCost(), aStar.getResult().getPathCost());

		// A target inside the blocked region lifts the gate, as in legacy.
		legacy = legacy(config, FALADOR, LUMBRIDGE);
		aStar = aStar(config, FALADOR, LUMBRIDGE);
		assertTrue(legacy.isReached());
		assertTrue(aStar.getResult().isReached());
		assertEquals(legacy.getPathCost(), aStar.getResult().getPathCost());
	}

	private static PathfinderResult legacy(PathfinderConfig config, int start, int target)
	{
		Pathfinder pathfinder = new Pathfinder(config, start, Set.of(target));
		pathfinder.run();
		return pathfinder.getResult();
	}

	private static AStarPathfinder aStar(PathfinderConfig config, int start, int target)
	{
		AStarPathfinder pathfinder = new AStarPathfinder(config, routingStatic, null, start,
			Set.of(target), null, 1);
		pathfinder.run();
		return pathfinder;
	}

	/** A maxed account with no items and, optionally, wilderness obelisks and minigame teleports. */
	private static PathfinderConfig config(boolean avoidWilderness, boolean teleports)
	{
		Client client = mock(Client.class);
		TestShortestPathConfig settings = new TestShortestPathConfig();
		ItemContainer empty = mock(ItemContainer.class);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getClientThread()).thenReturn(Thread.currentThread());
		when(client.getDBTableRows(DBTableID.Quest.ID)).thenReturn(List.of());
		when(client.getBoostedSkillLevel(any(Skill.class))).thenReturn(99);
		doReturn(new Item[0]).when(empty).getItems();
		doReturn(empty).when(client).getItemContainer(InventoryID.INV);
		doReturn(empty).when(client).getItemContainer(InventoryID.WORN);
		settings.set("calculationCutoff", 500);
		settings.set("currencyThreshold", 10000000);
		settings.set("useTeleportationItems", TeleportationItem.NONE);
		settings.set("avoidWilderness", avoidWilderness);
		settings.set("useWildernessObelisks", teleports);
		settings.set("useTeleportationMinigames", teleports);

		PathfinderConfig config = new TestPathfinderConfig(client, settings, QuestState.FINISHED, true, true);
		config.refresh();
		return config;
	}
}

package shortestpath.pathfinder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.doReturn;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import java.util.List;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;
import net.runelite.api.gameval.DBTableID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import org.junit.BeforeClass;
import org.junit.Test;
import shortestpath.TestShortestPathConfig;
import shortestpath.settings.TeleportationItem;
import shortestpath.WorldPointUtil;
import shortestpath.pathfinder.astar.AStarRoutingSession;
import shortestpath.pathfinder.astar.PreparedRoutingAccount;
import shortestpath.pathfinder.astar.RoutingStatic;

/**
 * A* must bank only where {@link PathfinderConfig#bankAccessible(int)} allows, like legacy.
 *
 * <p>The Farming Guild bank needs 85 Farming (bank.tsv); nothing else in the data is gated at 85
 * Farming, so 84 and 85 differ only in whether that bank is usable. The only teleport is a banked
 * camulet, so a route that banks at the guild is cheaper than one that walks to another bank.
 */
public class AStarBankAccessParityTest
{
	private static final int FARMING_GUILD_BANK = WorldPointUtil.packWorldPoint(1248, 3758, 0);
	private static final int START = WorldPointUtil.packWorldPoint(1249, 3752, 0);
	private static final int ENAKHRAS_TEMPLE = WorldPointUtil.packWorldPoint(3105, 9315, 0);
	private static final int BANK_VISIT_COST = 5;

	private static RoutingStatic routingStatic;

	@BeforeClass
	public static void buildRoutingStatic()
	{
		routingStatic = TestWorldData.routingStatic();
	}

	@Test
	public void preparedAccountsShareStaticBanksButDifferInAccess()
	{
		PreparedRoutingAccount without = config(84).prepareAStarRoutingAccount(true);
		PreparedRoutingAccount with = config(85).prepareAStarRoutingAccount(true);

		assertTrue("the static data knows the bank", isStaticBank(FARMING_GUILD_BANK));
		assertFalse(without.bankAccessible(FARMING_GUILD_BANK));
		assertTrue(with.bankAccessible(FARMING_GUILD_BANK));
		assertNotEquals("bank access is part of the account identity", without.fingerprint(), with.fingerprint());
	}

	@Test
	public void inaccessibleBankIsNotUsedAndMatchesLegacy()
	{
		PathfinderConfig config = config(84);
		assertFalse(config.bankAccessible(FARMING_GUILD_BANK));

		PathfinderResult legacy = legacy(config);
		AStarPathfinder aStar = aStar(config, null);

		assertTrue(legacy.isReached());
		assertTrue(aStar.getResult().isReached());
		assertFalse("aStar banked at the Farming Guild without 85 Farming", banksAt(aStar.getPath(), FARMING_GUILD_BANK));
		assertEquals(legacy.getPathCost(), aStar.getResult().getPathCost());
	}

	@Test
	public void accessibleBankIsUsedAndMatchesLegacy()
	{
		PathfinderConfig config = config(85);
		assertTrue(config.bankAccessible(FARMING_GUILD_BANK));

		PathfinderResult legacy = legacy(config);
		AStarPathfinder aStar = aStar(config, null);

		assertTrue(legacy.isReached());
		assertTrue(aStar.getResult().isReached());
		assertTrue("aStar should bank at the Farming Guild", banksAt(aStar.getPath(), FARMING_GUILD_BANK));
		assertEquals(legacy.getPathCost(), aStar.getResult().getPathCost());
		assertTrue("banking at the guild should be cheaper than walking to another bank",
			aStar.getResult().getPathCost() < aStar(config(84), null).getResult().getPathCost());
	}

	@Test
	public void bankVisitCostIsChargedLikeLegacy()
	{
		for (int farmingLevel : new int[] {84, 85})
		{
			PathfinderConfig free = config(farmingLevel, 0);
			PathfinderConfig costed = config(farmingLevel, BANK_VISIT_COST);
			PathfinderResult legacy = legacy(costed);
			AStarPathfinder aStar = aStar(costed, null);

			assertTrue(aStar.getResult().isReached());
			assertEquals("Farming " + farmingLevel, legacy.getPathCost(), aStar.getResult().getPathCost());
			assertTrue(aStar.getPath().stream().anyMatch(step -> step.getBankVisitState() == BankVisitState.BANKED));
			assertEquals("the route still banks, so it pays the visit once",
				aStar(free, null).getResult().getPathCost() + BANK_VISIT_COST, aStar.getResult().getPathCost());
		}
	}

	@Test
	public void sessionDoesNotReuseStaleBankAccess()
	{
		AStarRoutingSession session = new AStarRoutingSession();
		int withCost = aStar(config(85), session).getResult().getPathCost();

		AStarPathfinder without = aStar(config(84), session);
		assertFalse("the account graph must be rebuilt when bank access changes", without.isGraphReused());
		assertFalse(banksAt(without.getPath(), FARMING_GUILD_BANK));
		assertEquals(legacy(config(84)).getPathCost(), without.getResult().getPathCost());

		AStarPathfinder with = aStar(config(85), session);
		assertFalse(with.isGraphReused());
		assertEquals(withCost, with.getResult().getPathCost());
		assertTrue(aStar(config(85), session).isGraphReused());

		AStarPathfinder costed = aStar(config(85, BANK_VISIT_COST), session);
		assertFalse("the account graph must be rebuilt when the bank visit cost changes", costed.isGraphReused());
		assertEquals(withCost + BANK_VISIT_COST, costed.getResult().getPathCost());
	}

	private static boolean isStaticBank(int tile)
	{
		for (int i = 0; i < routingStatic.reachableBankCount(); i++)
			if (routingStatic.reachableBankTile(i) == tile) return true;
		return false;
	}

	private static boolean banksAt(List<PathStep> path, int tile)
	{
		for (int i = 1; i < path.size(); i++)
		{
			if (path.get(i - 1).getBankVisitState() != BankVisitState.BANKED && path.get(i).getBankVisitState() == BankVisitState.BANKED)
				return path.get(i - 1).getPackedPosition() == tile || path.get(i).getPackedPosition() == tile;
		}
		return false;
	}

	private static PathfinderResult legacy(PathfinderConfig config)
	{
		Pathfinder pathfinder = new Pathfinder(config, START, Set.of(ENAKHRAS_TEMPLE));
		pathfinder.run();
		return pathfinder.getResult();
	}

	private static AStarPathfinder aStar(PathfinderConfig config, AStarRoutingSession session)
	{
		AStarPathfinder pathfinder = new AStarPathfinder(config, routingStatic, session, START,
			Set.of(ENAKHRAS_TEMPLE), null, 1);
		pathfinder.run();
		return pathfinder;
	}

	private static PathfinderConfig config(int farmingLevel)
	{
		return config(farmingLevel, 0);
	}

	/** A logged-in account with 99 in every skill except Farming and a camulet in the bank. */
	private static PathfinderConfig config(int farmingLevel, int bankVisitCost)
	{
		Client client = mock(Client.class);
		TestShortestPathConfig settings = new TestShortestPathConfig();
		ItemContainer empty = mock(ItemContainer.class);
		ItemContainer bank = mock(ItemContainer.class);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getClientThread()).thenReturn(Thread.currentThread());
		when(client.getDBTableRows(DBTableID.Quest.ID)).thenReturn(List.of());
		when(client.getBoostedSkillLevel(any(Skill.class))).thenReturn(99);
		when(client.getBoostedSkillLevel(Skill.FARMING)).thenReturn(farmingLevel);
		doReturn(new Item[0]).when(empty).getItems();
		doReturn(empty).when(client).getItemContainer(InventoryID.INV);
		doReturn(empty).when(client).getItemContainer(InventoryID.WORN);
		doReturn(new Item[] {new Item(ItemID.CAMULET, 1)}).when(bank).getItems();
		settings.set("calculationCutoff", 500);
		settings.set("currencyThreshold", 10000000);
		settings.set("useTeleportationItems", TeleportationItem.INVENTORY_AND_BANK);
		settings.set("costBankVisit", bankVisitCost);

		PathfinderConfig config = new TestPathfinderConfig(client, settings, QuestState.FINISHED, true, true);
		shortestpath.items.ItemStateService itemState = shortestpath.items.ItemStateTestServices.forTesting();
		config.setItemStateService(itemState);
		itemState.noteBankContainer(bank);
		config.refresh();
		return config;
	}
}

package shortestpath.pathfinder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.util.HashMap;
import java.util.Map;
import java.util.function.BooleanSupplier;
import org.junit.Test;
import shortestpath.pathfinder.astar.CostArithmetic;
import shortestpath.pathfinder.astar.AStarForwardSearch;
import shortestpath.pathfinder.astar.PreparedHeuristic;
import shortestpath.pathfinder.astar.PreparedRoutingAccount;
import shortestpath.pathfinder.astar.ReverseLabelsOracle;
import shortestpath.pathfinder.astar.RoutingStatic;
import shortestpath.pathfinder.astar.RoutingStaticTestFixture;
import shortestpath.pathfinder.astar.SearchRestrictions;
import shortestpath.pathfinder.astar.SiteGraph;
import shortestpath.pathfinder.astar.TargetOverlay;
import shortestpath.transport.Transport;
import shortestpath.transport.TransportType;

public class AStarForwardSearchTest
{
	@Test
	public void walksLocallyAndKeepsTheTerminalState()
		throws Exception
	{
		RoutingStatic stat = RoutingStaticTestFixture.createT4Walking();
		PreparedRoutingAccount account = account();
		TargetOverlay target = target(stat, account, RoutingStaticTestFixture.C, neighbours());

		AStarForwardSearch.Result result = search(target, RoutingStaticTestFixture.A);

		assertTrue(result.reached());
		assertFalse(result.cancelled());
		assertEquals(2, result.cost());
		assertTrue((result.terminalState() & 1) == 0);
		assertTrue(result.counters().walkingRelaxations() > 0);
	}

	@Test
	public void usesThePostBankLayerAndLocalTransport()
		throws Exception
	{
		RoutingStatic stat = RoutingStaticTestFixture.create();
		PreparedRoutingAccount account = account(null,
			local(RoutingStaticTestFixture.BANK, RoutingStaticTestFixture.D, 1), true);
		TargetOverlay target = target(stat, account, RoutingStaticTestFixture.D,
			neighbours(RoutingStaticTestFixture.A, RoutingStaticTestFixture.BANK));

		AStarForwardSearch.Result result = search(target, RoutingStaticTestFixture.A);

		assertTrue(result.reached());
		assertEquals(2, result.cost());
		assertTrue((result.terminalState() & 1) != 0);
		assertTrue(result.counters().transportRelaxations() > 0);
	}

	@Test
	public void entersABlockedLocalTransportOrigin()
		throws Exception
	{
		RoutingStatic stat = RoutingStaticTestFixture.create();
		PreparedRoutingAccount account = account(local(RoutingStaticTestFixture.BANK,
			RoutingStaticTestFixture.D, 1));
		TargetOverlay target = target(stat, account, RoutingStaticTestFixture.D, neighbours(),
			RoutingStaticTestFixture.BANK);

		AStarForwardSearch.Result result = search(target, RoutingStaticTestFixture.A);

		assertTrue(result.reached());
		assertEquals(2, result.cost());
	}

	@Test
	public void staleEntriesAndUnreachableHeuristicPrunesAreSafe()
		throws Exception
	{
		RoutingStatic stat = RoutingStaticTestFixture.create();
		PreparedRoutingAccount account = account(
			local(RoutingStaticTestFixture.A, RoutingStaticTestFixture.C, 5),
			local(RoutingStaticTestFixture.BANK, RoutingStaticTestFixture.C, 1));
		TargetOverlay target = target(stat, account, RoutingStaticTestFixture.D,
			neighbours(RoutingStaticTestFixture.A, RoutingStaticTestFixture.BANK,
				RoutingStaticTestFixture.BANK, RoutingStaticTestFixture.C));

		AStarForwardSearch.Result result = search(target, RoutingStaticTestFixture.A);

		assertFalse(result.reached());
		assertEquals(CostArithmetic.INF, result.cost());
		assertTrue(result.counters().staleEntries() > 0);
	}

	@Test
	public void cancellationDoesNotPublishACompletedRoute()
		throws Exception
	{
		RoutingStatic stat = RoutingStaticTestFixture.create();
		PreparedRoutingAccount account = account();
		TargetOverlay target = target(stat, account, RoutingStaticTestFixture.D,
			neighbours(RoutingStaticTestFixture.A, RoutingStaticTestFixture.BANK));
		BooleanSupplier cancelled = () -> true;

		AStarForwardSearch.Result result = AStarForwardSearch.search(target,
			PreparedHeuristic.prepare(target, ReverseLabelsOracle.compute(target)), RoutingStaticTestFixture.A, cancelled, true, 1, SearchRestrictions.none(), AStarForwardSearch.NO_PROGRESS, (tile, banked) -> target.isTarget(tile));

		assertTrue(result.cancelled());
		assertFalse(result.reached());
		assertEquals(CostArithmetic.INF, result.cost());
	}

	private static AStarForwardSearch.Result search(TargetOverlay target, int start)
	{
		PreparedHeuristic heuristic = PreparedHeuristic.prepare(target, ReverseLabelsOracle.compute(target));
		return AStarForwardSearch.search(target, heuristic, start);
	}

	private static TargetOverlay target(RoutingStatic stat, PreparedRoutingAccount account, int target,
		Map<Integer, int[]> neighbours)
	{
		return target(stat, account, target, neighbours, -1);
	}

	private static TargetOverlay target(RoutingStatic stat, PreparedRoutingAccount account, int target,
		Map<Integer, int[]> neighbours, int blocked)
	{
		SiteGraph graph = new SiteGraph(stat, account);
		return new TargetOverlay(graph, collision(neighbours, blocked), target);
	}

	private static CollisionMap collision(Map<Integer, int[]> neighbours)
	{
		return collision(neighbours, -1);
	}

	private static CollisionMap collision(Map<Integer, int[]> neighbours, int blocked)
	{
		return new CollisionMap(null)
		{
			@Override
			public int[] ordinaryWalkingNeighbors(int packedPoint)
			{
				int[] values = neighbours.get(packedPoint);
				return values == null ? new int[0] : values.clone();
			}

			@Override
			public boolean isBlocked(int x, int y, int z)
			{
				return shortestpath.WorldPointUtil.packWorldPoint(x, y, z) == blocked;
			}
		};
	}

	private static Map<Integer, int[]> neighbours(int... values)
	{
		Map<Integer, int[]> result = new HashMap<>();
		for (int i = 0; i < values.length; i += 2)
			result.put(values[i], new int[] {values[i + 1]});
		return result;
	}

	private static PreparedRoutingAccount account(Transport... carried)
	{
		return account(carried, new Transport[0], false);
	}

	private static PreparedRoutingAccount account(Transport carried, Transport banked, boolean bankPath)
	{
		return account(carried == null ? new Transport[0] : new Transport[] {carried},
			banked == null ? new Transport[0] : new Transport[] {banked}, bankPath);
	}

	private static PreparedRoutingAccount account(Transport[] carried, Transport[] banked, boolean bankPath)
	{
		return PreparedRoutingAccount.compile(availability(carried), availability(banked), bankPath,
			java.util.Set.of(RoutingStaticTestFixture.BANK, RoutingStaticTestFixture.T3_B), 0, true, ignored -> 0);
	}

	private static TransportAvailability availability(Transport[] transports)
	{
		TransportAvailability.Builder builder = new TransportAvailability.Builder(transports.length);
		for (Transport transport : transports)
			builder.add(transport);
		return builder.build();
	}

	private static Transport local(int origin, int destination, int duration)
	{
		return new Transport.TransportBuilder().origin(origin).destination(destination)
			.type(TransportType.TRANSPORT).duration(duration).build();
	}
}

package shortestpath.pathfinder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.api.gameval.ItemID;
import org.junit.Before;
import org.junit.Test;
import shortestpath.pathfinder.astar.AStarRoutingSession;
import shortestpath.pathfinder.astar.PreparedRoutingAccount;
import shortestpath.pathfinder.astar.RoutingStatic;
import shortestpath.pathfinder.astar.RoutingStaticTestFixture;

/** Exercises resolved goal layers through the plugin adapter, including snapping and arrival. */
public class AStarGoalLayersTest
{
	private static final int START = RoutingStaticTestFixture.A;
	private static final int BANK = RoutingStaticTestFixture.BANK;
	private static final int FALLBACK = RoutingStaticTestFixture.C;
	private static final int BLOCKED = RoutingStaticTestFixture.D;
	private static final HeldItems CARRIED = new HeldItems(Map.of(ItemID.SPADE, 1), Map.of(ItemID.SPADE, 1), true);
	private static final HeldItems BANKED = new HeldItems(Map.of(), Map.of(ItemID.SPADE, 1), true);
	private PathfinderConfig config;
	private RoutingStatic stat;

	@Before
	public void world() throws Exception
	{
		stat = RoutingStaticTestFixture.createT4Walking();
		CollisionMap collision = mock(CollisionMap.class);
		when(collision.isBlocked(anyInt(), anyInt(), anyInt())).thenReturn(true);
		for (int x = 1000; x <= 1002; x++) when(collision.isBlocked(x, 1000, 0)).thenReturn(false);
		when(collision.ordinaryWalkingNeighbors(anyInt())).thenReturn(new int[0]);
		when(collision.ordinaryWalkingNeighbors(START)).thenReturn(new int[] {BANK});
		when(collision.ordinaryWalkingNeighbors(BANK)).thenReturn(new int[] {START, FALLBACK});
		when(collision.ordinaryWalkingNeighbors(FALLBACK)).thenReturn(new int[] {BANK});
		when(collision.ordinaryWalkingNeighbors(BLOCKED)).thenReturn(new int[] {FALLBACK});
		when(collision.ordinaryWalkingMask(START)).thenReturn((byte) 4);
		when(collision.ordinaryWalkingMask(BANK)).thenReturn((byte) 68);
		when(collision.ordinaryWalkingMask(FALLBACK)).thenReturn((byte) 64);
		config = mock(PathfinderConfig.class);
		when(config.getMap()).thenReturn(collision);
		when(config.isCollisionAwareBlockedTargets()).thenReturn(true);
		when(config.getUnreachableTargetDistance()).thenReturn(1);
		bankAccess(true);
	}

	@Test
	public void bankedFallbackRequiresABankAndPreservesArrival()
	{
		PathfinderResult result = search(BANKED, new AStarRoutingSession()).getResult();
		assertEquals(PathTerminationReason.TARGET_REACHED, result.getTerminationReason());
		assertEquals(7, result.getPathCost());
		assertEquals(FALLBACK, result.getClosestReachedPoint());
		assertEquals(BLOCKED, result.getArrival().getTarget().getPoint());
		assertEquals(TargetStatus.BANK, result.getArrival().getStatus());
		assertEquals(BankVisitState.BANKED,
			result.getPathSteps().get(result.getPathSteps().size() - 1).getBankVisitState());
	}

	@Test
	public void bankedFallbackWithoutAnAccessibleBankSkipsTheTileSearch()
	{
		bankAccess(false);
		PathfinderResult result = search(BANKED, new AStarRoutingSession()).getResult();
		assertEquals(PathTerminationReason.SEARCH_EXHAUSTED, result.getTerminationReason());
		assertEquals(0, result.getNodesChecked());
	}

	@Test
	public void unknownItemsStillRouteToFallbackAndReportMissingItems()
	{
		PathfinderResult result = search(HeldItems.NONE, new AStarRoutingSession()).getResult();
		assertTrue(result.isReached());
		assertEquals(2, result.getPathCost());
		assertEquals(TargetStatus.UNKNOWN, result.getArrival().getStatus());
		assertEquals(TargetsTest.items(ItemID.SPADE).getRequirements(), result.getArrival().getMissingItems());
	}

	@Test
	public void heldItemChangesReuseTheGraphButKeepSeparateTargetPreparations()
	{
		AStarRoutingSession session = new AStarRoutingSession();
		AStarPathfinder first = search(CARRIED, session);
		assertFalse(first.isTargetReused());
		assertEquals(2, first.getResult().getPathCost());
		assertEquals(TargetStatus.CARRIED, first.getResult().getArrival().getStatus());
		assertTrue(search(CARRIED, session).isTargetReused());
		AStarPathfinder banked = search(BANKED, session);
		assertTrue(banked.isGraphReused());
		assertFalse(banked.isTargetReused());
		assertEquals(7, banked.getResult().getPathCost());
		assertTrue(search(BANKED, session).isTargetReused());
		assertTrue(search(CARRIED, session).isTargetReused());
		assertEquals(2, session.cachedTargetCount());
	}

	private void bankAccess(boolean accessible)
	{
		PreparedRoutingAccount account = PreparedRoutingAccount.compile(TransportAvailabilityFixture.of(),
			TransportAvailabilityFixture.of(), true, accessible ? Set.of(BANK) : Set.of(), 5, true, ignored -> 0);
		when(config.prepareAStarRoutingAccount(true, false)).thenReturn(account);
		when(config.prepareAStarRoutingAccount(true, true)).thenReturn(account);
	}

	private AStarPathfinder search(HeldItems items, AStarRoutingSession session)
	{
		when(config.getHeldItems()).thenReturn(items);
		Targets targets = Targets.of(List.of(Target.requiring(BLOCKED, TargetsTest.items(ItemID.SPADE))));
		AStarPathfinder pathfinder = new AStarPathfinder(config, () -> stat, session, START, targets, null, 1);
		pathfinder.run();
		return pathfinder;
	}
}

package shortestpath.pathfinder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.when;

import java.util.ArrayDeque;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import org.junit.Before;
import org.junit.BeforeClass;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;
import shortestpath.TestShortestPathConfig;
import shortestpath.WorldPointUtil;
import shortestpath.settings.TeleportationItem;
import shortestpath.pathfinder.astar.RoutingStatic;

/**
 * Issue #640 coverage for the A* backend: it terminates on the goal set
 * {@link TargetGoals} resolves from the requested targets, so a blocked target
 * ends the search on a walkable fallback tile on the target's side of any
 * wall instead of exhausting the map.
 */
@RunWith(MockitoJUnitRunner.class)
public class AStarPathfinderBlockedTargetTest
{
	private static RoutingStatic routingStatic;

	@Mock
	Client client;
	private TestShortestPathConfig config = new TestShortestPathConfig();
	private PathfinderConfig pathfinderConfig;

	@BeforeClass
	public static void buildRoutingStatic()
	{
		routingStatic = TestWorldData.routingStatic();
	}

	@Before
	public void before()
	{
		config.set("calculationCutoff", 30);
		config.set("collisionAwareBlockedTargets", true);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getBoostedSkillLevel(any(Skill.class))).thenReturn(99);
		when(client.getClientThread()).thenReturn(Thread.currentThread());
		config.set("useTeleportationItems", TeleportationItem.NONE);
	}

	private void setup(int unreachableDistance)
	{
		config.set("unreachableTargetDistanceThreshold", unreachableDistance);
		pathfinderConfig = new TestPathfinderConfig(client, config, net.runelite.api.QuestState.FINISHED, true, true);
		pathfinderConfig.refresh();
	}

	private AStarPathfinder search(int start, Set<Integer> targets)
	{
		AStarPathfinder pathfinder = new AStarPathfinder(pathfinderConfig, routingStatic,
			start, targets, null);
		pathfinder.run();
		return pathfinder;
	}

	// The same connectivity oracle PathfinderTest uses: every tile walk-connected
	// to the target within the radius, regardless of walls or footprints.
	private static Set<Integer> connectedTilesOracle(CollisionMap map, int target, int radius)
	{
		Set<Integer> connected = new HashSet<>();
		ArrayDeque<Integer> queue = new ArrayDeque<>();
		connected.add(target);
		queue.add(target);
		while (!queue.isEmpty())
		{
			int current = queue.poll();
			for (int neighbour : map.ordinaryWalkingNeighbors(current))
			{
				if (connected.contains(neighbour)
					|| WorldPointUtil.distanceBetween(target, neighbour) > radius)
				{
					continue;
				}
				connected.add(neighbour);
				queue.add(neighbour);
			}
		}
		connected.remove(target);
		return connected;
	}

	private static int end(PathfinderResult result)
	{
		List<PathStep> steps = result.getPathSteps();
		return steps.get(steps.size() - 1).getPackedPosition();
	}

	@Test
	public void blockedTargetExpandsToWalkableNeighbours()
	{
		setup(2);
		CollisionMap map = pathfinderConfig.getMap();
		int start = WorldPointUtil.packWorldPoint(3222, 3218, 0);
		int blockedTarget = WorldPointUtil.packWorldPoint(3203, 3178, 0);
		assertTrue("test requires a blocked target tile", map.isBlocked(3203, 3178, 0));

		AStarPathfinder pathfinder = search(start, Set.of(blockedTarget));
		PathfinderResult result = pathfinder.getResult();
		assertNotNull(result);
		assertTrue("expected a fallback tile near the blocked target", result.isReached());
		assertEquals(PathTerminationReason.TARGET_REACHED, result.getTerminationReason());
		int end = end(result);
		assertFalse("path must end on a walkable tile", map.isBlocked(
			WorldPointUtil.unpackWorldX(end), WorldPointUtil.unpackWorldY(end),
			WorldPointUtil.unpackWorldPlane(end)));
		assertTrue("path must end within the unreachable distance",
			WorldPointUtil.distanceBetween(end, blockedTarget) <= 2);
	}

	@Test
	public void fullyBlockedTargetShortCircuitsSearch()
	{
		// (2114, 5506) sits inside a fully blocked 5x5: no walkable tile within
		// the unreachable distance and no transport lands on it, so the aStar
		// search must skip the map walk exactly like the legacy one.
		setup(2);
		CollisionMap map = pathfinderConfig.getMap();
		int start = WorldPointUtil.packWorldPoint(3222, 3218, 0);
		int blockedTarget = WorldPointUtil.packWorldPoint(2114, 5506, 0);
		assertTrue("test requires a blocked target tile", map.isBlocked(2114, 5506, 0));
		assertFalse("test requires that no transport lands on the target",
			pathfinderConfig.isTransportDestination(blockedTarget));

		AStarPathfinder pathfinder = search(start, Set.of(blockedTarget));
		PathfinderResult result = pathfinder.getResult();
		assertNotNull(result);
		assertFalse(result.isReached());
		assertEquals(PathTerminationReason.SEARCH_EXHAUSTED, result.getTerminationReason());
		assertEquals("a hopeless target must not explore any tile", 0, result.getNodesChecked());
	}

	@Test
	public void blockedTargetDoesNotSuppressOtherTargets()
	{
		setup(2);
		int start = WorldPointUtil.packWorldPoint(3222, 3218, 0);
		int blockedTarget = WorldPointUtil.packWorldPoint(2114, 5506, 0);
		int reachableTarget = WorldPointUtil.packWorldPoint(3213, 3428, 0);

		AStarPathfinder pathfinder = search(start, Set.of(blockedTarget, reachableTarget));
		PathfinderResult result = pathfinder.getResult();
		assertNotNull(result);
		assertTrue("the viable target should still be reached", result.isReached());
		assertEquals(PathTerminationReason.TARGET_REACHED, result.getTerminationReason());
		assertEquals(reachableTarget, end(result));
	}

	@Test
	public void blockedTargetExpansionStaysOnTargetSideOfWalls()
	{
		// Same Varrock wall fixture as the legacy test: (3258, 3351) is a blocked
		// wall segment whose expansion square covers walkable tiles on the far
		// side of the wall; the path must end on the target's connected side.
		final int radius = 6;
		setup(radius);
		CollisionMap map = pathfinderConfig.getMap();
		int start = WorldPointUtil.packWorldPoint(3258, 3341, 0);
		int blockedTarget = WorldPointUtil.packWorldPoint(3258, 3351, 0);
		assertTrue("test requires a blocked target tile", map.isBlocked(3258, 3351, 0));
		assertFalse("test requires a walkable start tile", map.isBlocked(3258, 3341, 0));
		Set<Integer> connected = connectedTilesOracle(map, blockedTarget, radius);
		assertFalse("test requires at least one connected fallback goal", connected.isEmpty());

		AStarPathfinder pathfinder = search(start, Set.of(blockedTarget));
		PathfinderResult result = pathfinder.getResult();
		assertNotNull(result);
		assertTrue(result.isReached());
		assertEquals(PathTerminationReason.TARGET_REACHED, result.getTerminationReason());
		int end = end(result);
		assertFalse("path must end on a walkable tile", map.isBlocked(
			WorldPointUtil.unpackWorldX(end), WorldPointUtil.unpackWorldY(end),
			WorldPointUtil.unpackWorldPlane(end)));
		assertTrue("end tile must be walk-connected to the target (same side of the wall)",
			connected.contains(end));
	}

	@Test
	public void blockedTargetDoesNotTerminateOnStartTile()
	{
		// The player's own tile is excluded from the goal set: the search must
		// not terminate on the first popped state and draw an invisible path.
		final int radius = 6;
		setup(radius);
		CollisionMap map = pathfinderConfig.getMap();
		int start = WorldPointUtil.packWorldPoint(3256, 3345, 0);
		int blockedTarget = WorldPointUtil.packWorldPoint(3258, 3351, 0);
		Set<Integer> connected = connectedTilesOracle(map, blockedTarget, radius);
		assertTrue("test requires the start tile to be a connected fallback goal",
			connected.contains(start));

		AStarPathfinder pathfinder = search(start, Set.of(blockedTarget));
		PathfinderResult result = pathfinder.getResult();
		assertNotNull(result);
		assertTrue(result.isReached());
		List<PathStep> steps = result.getPathSteps();
		assertTrue("a path of a single start tile is meaningless to draw", steps.size() > 1);
		assertNotEquals("the search must not terminate on the start tile", start, end(result));
	}

	@Test
	public void blockedTargetExpansionOffIgnoresConnectivity()
	{
		// With collisionAwareBlockedTargets off the innermost walkable ring is
		// the goal set: the Port Sarim jetty target's ring 1 holds only tiles on
		// the far side, which legacy mode accepts and aware mode rejects.
		final int radius = 6;
		config.set("collisionAwareBlockedTargets", false);
		setup(radius);
		CollisionMap map = pathfinderConfig.getMap();
		int start = WorldPointUtil.packWorldPoint(3200, 3330, 0);
		int blockedTarget = WorldPointUtil.packWorldPoint(3200, 3340, 0);
		assertTrue("test requires a blocked target tile", map.isBlocked(3200, 3340, 0));
		Set<Integer> connected = connectedTilesOracle(map, blockedTarget, radius);

		AStarPathfinder pathfinder = search(start, Set.of(blockedTarget));
		PathfinderResult result = pathfinder.getResult();
		assertNotNull(result);
		assertTrue("expected the ring scan to find a fallback goal", result.isReached());
		int end = end(result);
		assertTrue("path must end within the unreachable distance",
			WorldPointUtil.distanceBetween(end, blockedTarget) <= radius);
		assertFalse("off mode must accept a tile not connected to the target",
			connected.contains(end));
	}

	@Test
	public void blockedWallFaceTargetEndsOnAdjacentFace()
	{
		// Same Lovakengj blast-mine fixture as the legacy test: the rock at
		// (1504, 3859) is the wall object itself, so every walkable neighbour
		// lies behind one of its boundary edges. They must still resolve as
		// goals -- the cardinally adjacent face specifically -- rather than
		// expanding to the pocket behind the wall's west end.
		setup(6);
		CollisionMap map = pathfinderConfig.getMap();
		int start = WorldPointUtil.packWorldPoint(1504, 3866, 0);
		int blockedTarget = WorldPointUtil.packWorldPoint(1504, 3859, 0);
		assertTrue("test requires a blocked target tile", map.isBlocked(1504, 3859, 0));
		assertTrue("test requires the north edge to be a wall boundary",
			map.wallN(1504, 3859, 0));
		assertFalse("test requires a walkable start tile", map.isBlocked(1504, 3866, 0));

		AStarPathfinder pathfinder = search(start, Set.of(blockedTarget));
		PathfinderResult result = pathfinder.getResult();
		assertNotNull(result);
		assertTrue(result.isReached());
		assertEquals(PathTerminationReason.TARGET_REACHED, result.getTerminationReason());
		assertEquals("the rock face is only usable from its cardinal neighbour",
			WorldPointUtil.packWorldPoint(1504, 3860, 0), end(result));
	}

	// A blocked target must snap to a tile the player can use: one cardinally
	// adjacent to it, reached for no more than the route to goodTile, a tile
	// adjacent to the target on the side the player approaches from.
	private void assertSnapsNoWorseThan(int start, int target, int goodTile)
	{
		CollisionMap map = pathfinderConfig.getMap();
		assertTrue("test requires a blocked target tile", map.isBlocked(
			WorldPointUtil.unpackWorldX(target), WorldPointUtil.unpackWorldY(target),
			WorldPointUtil.unpackWorldPlane(target)));
		PathfinderResult good = search(start, Set.of(goodTile)).getResult();
		assertNotNull(good);
		assertTrue("test requires the good tile to be reachable", good.isReached());

		PathfinderResult snapped = search(start, Set.of(target)).getResult();
		assertNotNull(snapped);
		assertTrue("the blocked target must snap to a reachable tile, not to one the player cannot get to",
			snapped.isReached());
		assertTrue("snapped route ends on " + WorldPointUtil.unpackWorldPoint(end(snapped))
				+ " at cost " + snapped.getPathCost() + "; " + WorldPointUtil.unpackWorldPoint(goodTile)
				+ " costs " + good.getPathCost(),
			snapped.getPathCost() <= good.getPathCost());
		int end = end(snapped);
		int dx = Math.abs(WorldPointUtil.unpackWorldX(end) - WorldPointUtil.unpackWorldX(target));
		int dy = Math.abs(WorldPointUtil.unpackWorldY(end) - WorldPointUtil.unpackWorldY(target));
		assertEquals("snapped route must end cardinally adjacent to the target, not on "
			+ WorldPointUtil.unpackWorldPoint(end), 1, dx + dy);
	}

	@Test
	public void bankBoothSnapsToPlayerSideOfCounter()
	{
		// Draynor bank booth: the tile behind the counter is the most enclosed
		// candidate, so it anchors the side and the search can never reach it.
		setup(2);
		assertSnapsNoWorseThan(WorldPointUtil.packWorldPoint(3093, 3245, 0),
			WorldPointUtil.packWorldPoint(3091, 3242, 0), WorldPointUtil.packWorldPoint(3092, 3242, 0));
	}

	@Test
	public void bankBoothSnapsToPlayerSideOfBoothRow()
	{
		// Varrock East bank: same failure with the booths in a row along y=3419.
		setup(2);
		assertSnapsNoWorseThan(WorldPointUtil.packWorldPoint(3251, 3421, 0),
			WorldPointUtil.packWorldPoint(3251, 3419, 0), WorldPointUtil.packWorldPoint(3251, 3420, 0));
	}

	@Test
	public void barPumpsSnapToCustomerSideOfBar()
	{
		// Rising Sun Inn, Falador: the bar pumps snap behind the bar.
		setup(2);
		assertSnapsNoWorseThan(WorldPointUtil.packWorldPoint(2965, 3380, 0),
			WorldPointUtil.packWorldPoint(2955, 3374, 0), WorldPointUtil.packWorldPoint(2956, 3374, 0));
	}

	@Test
	public void treeDoesNotSnapIntoFencedPocket()
	{
		// Seers' Village 2x2 tree (2734, 3479): the tile north of it is a small
		// fenced pocket, the most enclosed candidate, and unreachable.
		setup(2);
		assertSnapsNoWorseThan(WorldPointUtil.packWorldPoint(2725, 3485, 0),
			WorldPointUtil.packWorldPoint(2735, 3480, 0), WorldPointUtil.packWorldPoint(2736, 3480, 0));
	}

	@Test
	public void wallTargetSnapsToNearSide()
	{
		// Diagonal wall south-east of Lumbridge castle: the enclosed far side
		// wins, so the route walks round through two doors instead of stopping
		// on the open tile north of the wall.
		setup(2);
		assertSnapsNoWorseThan(WorldPointUtil.packWorldPoint(3222, 3218, 0),
			WorldPointUtil.packWorldPoint(3224, 3206, 0), WorldPointUtil.packWorldPoint(3224, 3207, 0));
	}

	@Test
	public void disconnectedTargetShortCircuitsSearch()
	{
		// Open sea off Draynor is walkable in the collision map but no route
		// reaches it, nor any tile within the unreachable distance: the search
		// must give up without exploring the map.
		setup(2);
		CollisionMap map = pathfinderConfig.getMap();
		int start = WorldPointUtil.packWorldPoint(3093, 3245, 0);
		int target = WorldPointUtil.packWorldPoint(3074, 3221, 0);
		assertFalse("test requires a walkable target tile", map.isBlocked(3074, 3221, 0));

		PathfinderResult result = search(start, Set.of(target)).getResult();
		assertNotNull(result);
		assertFalse(result.isReached());
		assertEquals(PathTerminationReason.SEARCH_EXHAUSTED, result.getTerminationReason());
		assertEquals("an unreachable target must not explore any tile", 0, result.getNodesChecked());
	}
}

package shortestpath.pathfinder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.util.List;
import org.junit.Test;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;
import static org.mockito.ArgumentMatchers.anyInt;
import shortestpath.pathfinder.astar.AStarForwardSearch;
import shortestpath.pathfinder.astar.PreparedHeuristic;
import shortestpath.pathfinder.astar.PreparedRoutingAccount;
import shortestpath.pathfinder.astar.ReverseLabelsOracle;
import shortestpath.pathfinder.astar.RoutingStatic;
import shortestpath.pathfinder.astar.RoutingStaticTestFixture;
import shortestpath.pathfinder.astar.SearchRestrictions;
import shortestpath.pathfinder.astar.SiteGraph;
import shortestpath.pathfinder.astar.TargetOverlay;
import shortestpath.transport.Transport;
import shortestpath.transport.TransportType;

public class AStarPathfinderTest
{
	@Test
	public void blockedTargetDoesNotKeepAnUnreachableSnappedGoalHeuristicFinite() throws Exception
	{
		AStarPathfinder search = blockedTargetSearch();
		search.run();

		assertEquals(PathTerminationReason.SEARCH_EXHAUSTED, search.getResult().getTerminationReason());
		assertEquals("the disconnected snapped goal must be rejected before expanding tiles",
			0, search.getResult().getNodesChecked());
	}

	@Test
	public void blockedTransportLandingRemainsAHeuristicSeed() throws Exception
	{
		CollisionMap collision = mock(CollisionMap.class);
		when(collision.isBlocked(anyInt(), anyInt(), anyInt())).thenReturn(true);
		when(collision.ordinaryWalkingNeighbors(anyInt())).thenReturn(new int[0]);
		PathfinderConfig config = mock(PathfinderConfig.class);
		when(config.getMap()).thenReturn(collision);
		when(config.isTransportDestination(RoutingStaticTestFixture.D)).thenReturn(true);
		when(config.prepareAStarRoutingAccount(true, false))
			.thenReturn(account(global(RoutingStaticTestFixture.D, 2), new Transport[0], false));
		AStarPathfinder search = new AStarPathfinder(config, RoutingStaticTestFixture.create(), null,
			RoutingStaticTestFixture.A, java.util.Set.of(RoutingStaticTestFixture.D), null, 1);
		search.run();

		assertTrue(search.getResult().getMessage(), search.getResult().isReached());
		assertEquals(RoutingStaticTestFixture.D,
			search.getPath().get(search.getPath().size() - 1).getPackedPosition());
	}

	private static AStarPathfinder blockedTargetSearch() throws Exception
	{
		int start = RoutingStaticTestFixture.T3_SEARCH_0;
		int snapped = RoutingStaticTestFixture.T3_SEARCH_1;
		int blocked = RoutingStaticTestFixture.T3_TARGET;
		CollisionMap collision = mock(CollisionMap.class);
		when(collision.isBlocked(anyInt(), anyInt(), anyInt())).thenReturn(true);
		when(collision.isBlocked(1001, 1000, 0)).thenReturn(false);
		when(collision.isBlocked(1001, 1002, 0)).thenReturn(false);
		when(collision.ordinaryWalkingNeighbors(anyInt())).thenReturn(new int[0]);
		// The blocked tile attaches to both components, but neither can walk into it.
		when(collision.ordinaryWalkingNeighbors(blocked)).thenReturn(new int[] {start, snapped});
		PathfinderConfig config = mock(PathfinderConfig.class);
		when(config.getMap()).thenReturn(collision);
		when(config.isCollisionAwareBlockedTargets()).thenReturn(true);
		when(config.getUnreachableTargetDistance()).thenReturn(1);
		when(config.prepareAStarRoutingAccount(true, false))
			.thenReturn(account());
		return new AStarPathfinder(config, RoutingStaticTestFixture.createT3(), null, start,
			java.util.Set.of(blocked), null, 1);
	}

	@Test
	public void sourceGlobalReconstructsAnExactTransportPath()
		throws Exception
	{
		RoutingStatic stat = RoutingStaticTestFixture.create();
		PreparedRoutingAccount account = account(global(RoutingStaticTestFixture.D, 2), new Transport[0], false);
		TargetOverlay target = target(stat, account, RoutingStaticTestFixture.D);

		AStarForwardSearch.Result result = search(target, RoutingStaticTestFixture.A);

		assertTrue(result.reached());
		assertEquals(2, result.cost());
		assertEquals(2, result.path().size());
		assertEquals(RoutingStaticTestFixture.A, result.path().get(0).getPackedPosition());
		assertEquals(RoutingStaticTestFixture.D, result.path().get(1).getPackedPosition());
		assertTrue(result.counters().heuristicEvaluations() > 0);
	}

	@Test
	public void globalsUseSearchNodesRatherThanSiteIndices()
		throws Exception
	{
		RoutingStatic stat = RoutingStaticTestFixture.createT3();
		PreparedRoutingAccount account = account(global(RoutingStaticTestFixture.T3_B, 2),
			new Transport[0], false);
		TargetOverlay target = target(stat, account, RoutingStaticTestFixture.T3_B);

		AStarForwardSearch.Result result = search(target, RoutingStaticTestFixture.T3_A);

		assertTrue(result.reached());
		assertEquals(2, result.cost());
		assertEquals(RoutingStaticTestFixture.T3_B,
			result.path().get(result.path().size() - 1).getPackedPosition());
	}

	@Test
	public void bankTransitionKeepsThePostBankLayerAndUsesBankedGlobal()
		throws Exception
	{
		RoutingStatic stat = RoutingStaticTestFixture.create();
		PreparedRoutingAccount account = account(
			local(RoutingStaticTestFixture.A, RoutingStaticTestFixture.BANK, 1),
			new Transport[] {global(RoutingStaticTestFixture.D, 3)}, true);
		TargetOverlay target = target(stat, account, RoutingStaticTestFixture.D);

		AStarForwardSearch.Result result = search(target, RoutingStaticTestFixture.A);

		assertTrue(result.reached());
		assertEquals(4, result.cost());
		assertEquals(3, result.path().size());
		assertTrue(result.path().get(2).getBankVisitState() == BankVisitState.BANKED);
		assertEquals(RoutingStaticTestFixture.D, result.path().get(2).getPackedPosition());
	}

	@Test
	public void inaccessibleBankIsNotEnteredEvenThoughTheStaticDataHasIt()
		throws Exception
	{
		RoutingStatic stat = RoutingStaticTestFixture.create();
		PreparedRoutingAccount account = account(
			new Transport[] {local(RoutingStaticTestFixture.A, RoutingStaticTestFixture.BANK, 1)},
			new Transport[] {global(RoutingStaticTestFixture.D, 3)}, true, java.util.Set.of());
		TargetOverlay target = target(stat, account, RoutingStaticTestFixture.D);

		AStarForwardSearch.Result result = search(target, RoutingStaticTestFixture.A);

		assertFalse("only the banked teleport reaches D, and this account cannot bank", result.reached());
		assertFalse(result.path().stream().anyMatch(step -> step.getBankVisitState() == BankVisitState.BANKED));
	}

	@Test
	public void bankVisitCostIsChargedAndCanMakeBankingNotWorthIt()
		throws Exception
	{
		RoutingStatic stat = RoutingStaticTestFixture.create();
		Transport[] carried = {local(RoutingStaticTestFixture.A, RoutingStaticTestFixture.BANK, 1),
			local(RoutingStaticTestFixture.A, RoutingStaticTestFixture.D, 10)};
		Transport[] banked = {global(RoutingStaticTestFixture.D, 3)};

		AStarForwardSearch.Result cheapVisit = search(target(stat, account(carried, banked, true,
			java.util.Set.of(RoutingStaticTestFixture.BANK), 5), RoutingStaticTestFixture.D), RoutingStaticTestFixture.A);
		AStarForwardSearch.Result dearVisit = search(target(stat, account(carried, banked, true,
			java.util.Set.of(RoutingStaticTestFixture.BANK), 20), RoutingStaticTestFixture.D), RoutingStaticTestFixture.A);

		assertEquals("walk 1 + visit 5 + banked teleport 3", 9, cheapVisit.cost());
		assertTrue(cheapVisit.path().stream().anyMatch(step -> step.getBankVisitState() == BankVisitState.BANKED));
		assertEquals("the direct transport beats 1 + 20 + 3", 10, dearVisit.cost());
		assertFalse(dearVisit.path().stream().anyMatch(step -> step.getBankVisitState() == BankVisitState.BANKED));
	}

	@Test
	public void disabledBankPathIgnoresAnAccessibleBank()
		throws Exception
	{
		RoutingStatic stat = RoutingStaticTestFixture.create();
		PreparedRoutingAccount account = account(
			new Transport[] {local(RoutingStaticTestFixture.A, RoutingStaticTestFixture.BANK, 1)},
			new Transport[] {global(RoutingStaticTestFixture.D, 3)}, false,
			java.util.Set.of(RoutingStaticTestFixture.BANK));
		TargetOverlay target = target(stat, account, RoutingStaticTestFixture.D);

		AStarForwardSearch.Result result = search(target, RoutingStaticTestFixture.A);

		assertTrue(account.bankAccessible(RoutingStaticTestFixture.BANK));
		assertFalse(result.reached());
		assertFalse(result.path().stream().anyMatch(step -> step.getBankVisitState() == BankVisitState.BANKED));
	}

	@Test
	public void cancellationDoesNotPublishACompletedAStarRoute()
		throws Exception
	{
		RoutingStatic stat = RoutingStaticTestFixture.create();
		PreparedRoutingAccount account = account();
		TargetOverlay target = target(stat, account, RoutingStaticTestFixture.D);

		AStarForwardSearch.Result result = AStarForwardSearch.search(target,
			PreparedHeuristic.prepare(target, ReverseLabelsOracle.compute(target)), RoutingStaticTestFixture.A, () -> true, true, 1, SearchRestrictions.none(), AStarForwardSearch.NO_PROGRESS, (tile, banked) -> target.isTarget(tile));

		assertTrue(result.cancelled());
		assertFalse(result.reached());
		assertEquals(1, result.path().size());
		assertEquals(RoutingStaticTestFixture.A, result.path().get(0).getPackedPosition());
	}

	@Test
	public void previousRouteIsShownUntilTheSearchCompletes()
		throws Exception
	{
		List<PathStep> previous = List.of(new PathStep(RoutingStaticTestFixture.C, BankVisitState.CARRIED),
			new PathStep(RoutingStaticTestFixture.D, BankVisitState.CARRIED));
		AStarPathfinder search = pathfinder(0);
		search.showUntilDone(previous);

		assertTrue(search.isShowingProvisionalPath());
		assertEquals(previous, search.getPath());
		search.run();

		assertFalse(search.isShowingProvisionalPath());
		assertTrue(search.getResult().isReached());
		assertEquals(RoutingStaticTestFixture.D, search.getPath().get(search.getPath().size() - 1).getPackedPosition());
		assertEquals(RoutingStaticTestFixture.A, search.getPath().get(0).getPackedPosition());
	}

	@Test
	public void cancelledSearchKeepsShowingThePreviousRoute()
		throws Exception
	{
		List<PathStep> previous = List.of(new PathStep(RoutingStaticTestFixture.C, BankVisitState.CARRIED),
			new PathStep(RoutingStaticTestFixture.D, BankVisitState.CARRIED));
		AStarPathfinder search = pathfinder(0);
		search.showUntilDone(previous);
		search.cancel();

		search.run();

		assertTrue(search.isShowingProvisionalPath());
		assertEquals(previous, search.getPath());
	}

	@Test
	public void trivialPreviousRouteIsNotShown()
		throws Exception
	{
		AStarPathfinder search = pathfinder(0);
		search.showUntilDone(List.of(new PathStep(RoutingStaticTestFixture.C, BankVisitState.CARRIED)));

		assertFalse(search.isShowingProvisionalPath());
		assertEquals(1, search.getPath().size());
	}

	private static AStarPathfinder pathfinder(long cutoffMillis) throws Exception
	{
		RoutingStatic stat = RoutingStaticTestFixture.create();
		PathfinderConfig config = mock(PathfinderConfig.class);
		CollisionMap collision = emptyCollision();
		when(config.getMap()).thenReturn(collision);
		when(config.prepareAStarRoutingAccount(true, false))
			.thenReturn(account(global(RoutingStaticTestFixture.D, 2), new Transport[0], false));
		when(config.getCalculationCutoffMillis()).thenReturn(cutoffMillis);
		return new AStarPathfinder(config, stat, null, RoutingStaticTestFixture.A,
			java.util.Set.of(RoutingStaticTestFixture.D), null, 1);
	}

	private static AStarForwardSearch.Result search(TargetOverlay target, int start)
	{
		return AStarForwardSearch.search(target, PreparedHeuristic.prepare(target, ReverseLabelsOracle.compute(target)), start);
	}

	private static TargetOverlay target(RoutingStatic stat, PreparedRoutingAccount account, int target)
	{
		return new TargetOverlay(new SiteGraph(stat, account), emptyCollision(), target);
	}

	private static CollisionMap emptyCollision()
	{
		return new CollisionMap(null)
		{
			@Override public int[] ordinaryWalkingNeighbors(int packedPoint)
	{ return new int[0];
	}
			@Override public boolean isBlocked(int x, int y, int z)
	{ return false;
	}
		};
	}

	private static PreparedRoutingAccount account()
	{
		return account(new Transport[0], new Transport[0], false);
	}

	private static PreparedRoutingAccount account(Transport carried, Transport[] banked, boolean bankPath)
	{
		return account(new Transport[] {carried}, banked, bankPath);
	}

	private static PreparedRoutingAccount account(Transport[] carried, Transport[] banked, boolean bankPath)
	{
		return account(carried, banked, bankPath,
			java.util.Set.of(RoutingStaticTestFixture.BANK, RoutingStaticTestFixture.T3_B));
	}

	private static PreparedRoutingAccount account(Transport[] carried, Transport[] banked, boolean bankPath,
		java.util.Set<Integer> accessibleBanks)
	{
		return account(carried, banked, bankPath, accessibleBanks, 0);
	}

	private static PreparedRoutingAccount account(Transport[] carried, Transport[] banked, boolean bankPath,
		java.util.Set<Integer> accessibleBanks, int bankVisitCost)
	{
		return PreparedRoutingAccount.compile(availability(carried), availability(banked), bankPath,
			accessibleBanks, bankVisitCost, true, ignored -> 0);
	}

	private static TransportAvailability availability(Transport... transports)
	{
		TransportAvailability.Builder builder = new TransportAvailability.Builder(transports.length);
		for (Transport transport : transports) builder.add(transport);
		return builder.build();
	}

	private static Transport local(int origin, int destination, int duration)
	{
		return new Transport.TransportBuilder().origin(origin).destination(destination)
			.type(TransportType.TRANSPORT).duration(duration).build();
	}

	private static Transport global(int destination, int duration)
	{
		return new Transport.TransportBuilder().destination(destination)
			.type(TransportType.TELEPORTATION_ITEM).duration(duration).maxWildernessLevel(0).build();
	}
}

package shortestpath.pathfinder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.util.concurrent.atomic.AtomicInteger;
import org.junit.Test;
import shortestpath.pathfinder.astar.RoutingStatic;

public class AStarRoutingStaticProviderTest
{
	/** A collision map in which nothing is walkable, so the bundled layer cannot fit it. */
	private static final class EmptyCollisionMap extends CollisionMap
	{
		EmptyCollisionMap()
		{
			super(null);
		}

		@Override
		public long fingerprint()
		{
			return 0;
		}

		@Override
		public byte ordinaryWalkingMask(int packedPoint)
		{
			return 0;
		}

		@Override
		public int[] ordinaryWalkingNeighbors(int packedPoint)
		{
			return new int[0];
		}

		@Override
		public boolean isBlocked(int x, int y, int z)
		{
			return true;
		}
	}

	@Test
	public void aLayerThatDoesNotFitTheCollisionMapFailsOnceAndStaysFailed()
	{
		AtomicInteger suppliedMaps = new AtomicInteger();
		AStarRoutingStaticProvider provider = new AStarRoutingStaticProvider(() ->
		{
			suppliedMaps.incrementAndGet();
			return new EmptyCollisionMap();
		});

		IllegalStateException first = null;
		try
		{
			provider.get();
			fail("a layer that disagrees with the collision map must not load");
		}
		catch (IllegalStateException expected)
		{
			first = expected;
		}
		assertTrue(first.getCause() instanceof IOException);
		assertNotNull(first.getCause().getMessage());
		assertTrue(first.getCause().getMessage(), first.getCause().getMessage().contains("stale"));

		try
		{
			provider.get();
			fail("the failure is remembered");
		}
		catch (IllegalStateException second)
		{
			assertSame(first, second);
		}
		assertEquals(1, suppliedMaps.get());
	}

	private static IllegalStateException failureOf(AStarRoutingStaticProvider provider)
	{
		try
		{
			provider.get();
		}
		catch (IllegalStateException expected)
		{
			return expected;
		}
		throw new AssertionError("the provider loaded a layer it must refuse");
	}

	private static void assertRemembered(AStarRoutingStaticProvider provider, IllegalStateException first,
		AtomicInteger suppliedMaps)
	{
		assertSame(first, failureOf(provider));
		assertEquals(1, suppliedMaps.get());
	}

	@Test
	public void aMissingLayerFailsOnceAndStaysFailed()
	{
		AtomicInteger suppliedMaps = new AtomicInteger();
		AStarRoutingStaticProvider provider = new AStarRoutingStaticProvider(() ->
		{
			suppliedMaps.incrementAndGet();
			return new EmptyCollisionMap();
		}, () -> null);

		IllegalStateException first = failureOf(provider);

		assertTrue(first.getCause() instanceof IOException);
		assertTrue(first.getCause().getMessage(), first.getCause().getMessage().contains("missing"));
		assertRemembered(provider, first, suppliedMaps);
	}

	@Test
	public void aCorruptLayerFailsOnceAndStaysFailed()
	{
		AtomicInteger suppliedMaps = new AtomicInteger();
		AStarRoutingStaticProvider provider = new AStarRoutingStaticProvider(() ->
		{
			suppliedMaps.incrementAndGet();
			return new EmptyCollisionMap();
		}, () -> new ByteArrayInputStream(new byte[] {1, 2, 3}));

		IllegalStateException first = failureOf(provider);

		assertTrue(first.getCause() instanceof IOException);
		assertTrue(first.getCause().getMessage(), first.getCause().getMessage().contains("routing-components.bin"));
		assertRemembered(provider, first, suppliedMaps);
	}

	@Test
	public void aFailingCollisionSupplierFailsOnceAndStaysFailed()
	{
		AtomicInteger suppliedMaps = new AtomicInteger();
		AStarRoutingStaticProvider provider = new AStarRoutingStaticProvider(() ->
		{
			suppliedMaps.incrementAndGet();
			throw new IllegalStateException("collision map not loaded");
		});

		IllegalStateException first = failureOf(provider);

		assertEquals("collision map not loaded", first.getMessage());
		assertRemembered(provider, first, suppliedMaps);
	}

	@Test
	public void theBundledLayerLoadsAgainstTheBundledMapAndIsLoadedOnce() throws Exception
	{
		AtomicInteger suppliedMaps = new AtomicInteger();
		AStarRoutingStaticProvider provider = new AStarRoutingStaticProvider(() ->
		{
			suppliedMaps.incrementAndGet();
			return new CollisionMap(SplitFlagMap.fromResources());
		});

		RoutingStatic first = provider.get();

		assertTrue(first.searchTileCount() > 0);
		assertSame(first, provider.get());
		assertEquals(1, suppliedMaps.get());
	}
}

package shortestpath.pathfinder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.doReturn;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import java.util.List;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;
import net.runelite.api.gameval.DBTableID;
import net.runelite.api.gameval.InventoryID;
import org.junit.BeforeClass;
import org.junit.Test;
import shortestpath.TestShortestPathConfig;
import shortestpath.settings.TeleportationItem;
import shortestpath.WorldPointUtil;
import shortestpath.pathfinder.astar.RoutingStatic;

/**
 * A* casts a global teleport only where its own wilderness limit allows, like legacy.
 *
 * <p>From the level-27 obelisk (benchmark early/quest-natural-0006's start), the cheapest obelisk
 * lands at level 13 (3156,3620). The Fishing Trawler Minigame Teleport is limited to level 0, so it
 * may only be cast after leaving the wilderness, for example into Ferox Enclave a few tiles north.
 */
public class AStarWildernessTeleportParityTest
{
	private static final int START = WorldPointUtil.packWorldPoint(3051, 3736, 0);
	private static final int FISHING_TRAWLER = WorldPointUtil.packWorldPoint(2658, 3157, 0);

	private static RoutingStatic routingStatic;

	@BeforeClass
	public static void buildRoutingStatic()
	{
		routingStatic = TestWorldData.routingStatic();
	}

	@Test
	public void levelZeroTeleportIsOnlyCastOutsideTheWildernessLikeLegacy()
	{
		PathfinderConfig config = config();
		Pathfinder legacy = new Pathfinder(config, START, Set.of(FISHING_TRAWLER));
		legacy.run();
		AStarPathfinder aStar = new AStarPathfinder(config, routingStatic, null, START, Set.of(FISHING_TRAWLER),
			null, 1);
		aStar.run();

		assertTrue(legacy.getResult().isReached());
		assertTrue(aStar.getResult().isReached());
		List<PathStep> path = aStar.getPath();
		int castFrom = path.get(path.size() - 2).getPackedPosition();
		assertFalse("cast from wilderness tile " + WorldPointUtil.unpackWorldX(castFrom) + ","
			+ WorldPointUtil.unpackWorldY(castFrom), WildernessChecker.isInWilderness(castFrom));
		assertEquals(legacy.getResult().getPathCost(), aStar.getResult().getPathCost());
	}

	/** Every quest and skill, no items; wilderness obelisks and minigame teleports only. */
	private static PathfinderConfig config()
	{
		Client client = mock(Client.class);
		TestShortestPathConfig settings = new TestShortestPathConfig();
		ItemContainer empty = mock(ItemContainer.class);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getClientThread()).thenReturn(Thread.currentThread());
		when(client.getDBTableRows(DBTableID.Quest.ID)).thenReturn(List.of());
		when(client.getBoostedSkillLevel(any(Skill.class))).thenReturn(99);
		doReturn(new Item[0]).when(empty).getItems();
		doReturn(empty).when(client).getItemContainer(InventoryID.INV);
		doReturn(empty).when(client).getItemContainer(InventoryID.WORN);
		settings.set("calculationCutoff", 500);
		settings.set("currencyThreshold", 10000000);
		settings.set("useTeleportationItems", TeleportationItem.NONE);
		settings.set("useWildernessObelisks", true);
		settings.set("useTeleportationMinigames", true);

		PathfinderConfig config = new TestPathfinderConfig(client, settings, QuestState.FINISHED, true, true);
		config.refresh();
		return config;
	}
}

