public class ReverseLabelsTest
{
	@Test
	public void targetAttachmentsWalkingPlanesAndHeuristicContext() throws Exception
	{
		RoutingStatic stat = RoutingStaticTestFixture.createT3();
		SiteGraph graph = new SiteGraph(stat, emptyAccount());
		TargetOverlay target = new TargetOverlay(graph,
			collision(RoutingStaticTestFixture.T3_TARGET, RoutingStaticTestFixture.T3_SEARCH_0,
				RoutingStaticTestFixture.T3_SEARCH_1),
			RoutingStaticTestFixture.T3_TARGET);

		assertTrue(target.synthetic());
		assertArrayEquals(new int[] {0, 1}, target.components());
		assertEquals(graph.nodeCount() + 1, target.queryNodeCount());
		assertEquals(5, target.attachmentCount());
		ReverseLabels reverse = ReverseLabelsOracle.compute(target);
		assertEquals(0, reverse.targetLabel(BankVisitState.CARRIED));
		assertEquals(1, reverse.label(graph.nodeForTile(RoutingStaticTestFixture.T3_A), BankVisitState.CARRIED));
		assertEquals(1, reverse.label(graph.nodeForTile(RoutingStaticTestFixture.T3_C), BankVisitState.CARRIED));
		assertEquals(CostArithmetic.INF, reverse.label(graph.nodeForTile(RoutingStaticTestFixture.T3_D), BankVisitState.CARRIED));

		PreparedHeuristic heuristic = PreparedHeuristic.prepare(target, reverse);
		assertEquals(0, heuristic.estimate(RoutingStaticTestFixture.T3_TARGET, BankVisitState.CARRIED));
		assertEquals(1, heuristic.estimate(RoutingStaticTestFixture.T3_SEARCH_0, BankVisitState.CARRIED));
		assertEquals(1, heuristic.estimate(RoutingStaticTestFixture.T3_SEARCH_0, BankVisitState.CARRIED, new int[] {0}));
		assertEquals(CostArithmetic.INF, heuristic.estimate(20000, BankVisitState.CARRIED, new int[0]));
	}

	@Test
	public void staticTargetAndDirectedReverseTransport() throws Exception
	{
		RoutingStatic stat = RoutingStaticTestFixture.createT3();
		PreparedRoutingAccount account =
			account(local(RoutingStaticTestFixture.T3_B, RoutingStaticTestFixture.T3_D, 7));
		SiteGraph graph = new SiteGraph(stat, account);
		TargetOverlay staticTarget =
			new TargetOverlay(graph, collision(RoutingStaticTestFixture.T3_D), RoutingStaticTestFixture.T3_D);
		assertTrue(!staticTarget.synthetic());
		assertEquals(graph.nodeForTile(RoutingStaticTestFixture.T3_D), staticTarget.targetNode());
		ReverseLabels reverse = ReverseLabelsOracle.compute(staticTarget);
		assertEquals(7, reverse.label(graph.nodeForTile(RoutingStaticTestFixture.T3_B), BankVisitState.CARRIED));

		TargetOverlay reverseDirection =
			new TargetOverlay(graph, collision(RoutingStaticTestFixture.T3_B), RoutingStaticTestFixture.T3_B);
		reverse = ReverseLabelsOracle.compute(reverseDirection);
		assertEquals(CostArithmetic.INF, reverse.label(graph.nodeForTile(RoutingStaticTestFixture.T3_D), BankVisitState.CARRIED));
	}

	@Test
	public void bankLayersGlobalHubAndStaleEntries() throws Exception
	{
		RoutingStatic stat = RoutingStaticTestFixture.createT3();
		PreparedRoutingAccount account = account(local(RoutingStaticTestFixture.T3_B, RoutingStaticTestFixture.T3_D, 7),
			local(RoutingStaticTestFixture.T3_A, RoutingStaticTestFixture.T3_D, 10),
			local(RoutingStaticTestFixture.T3_A, RoutingStaticTestFixture.T3_B, 1));
		SiteGraph graph = new SiteGraph(stat, account);
		ReverseLabels stale = ReverseLabelsOracle.compute(
			new TargetOverlay(graph, collision(RoutingStaticTestFixture.T3_D), RoutingStaticTestFixture.T3_D));
		assertEquals(8, stale.label(graph.nodeForTile(RoutingStaticTestFixture.T3_A), BankVisitState.CARRIED));
		assertTrue(stale.staleCount() > 0);

		PreparedRoutingAccount bankAccount =
			account(new Transport[] {local(RoutingStaticTestFixture.T3_B, RoutingStaticTestFixture.T3_D, 9)},
				new Transport[] {local(RoutingStaticTestFixture.T3_B, RoutingStaticTestFixture.T3_D, 20),
					global(RoutingStaticTestFixture.T3_D, 6)},
				true);
		SiteGraph bankGraph = new SiteGraph(stat, bankAccount);
		assertTrue(bankGraph.hasBankedGlobalHub());
		TargetOverlay target =
			new TargetOverlay(bankGraph, collision(RoutingStaticTestFixture.T3_D), RoutingStaticTestFixture.T3_D);
		ReverseLabels reverse = ReverseLabelsOracle.compute(target);
		int bank = bankGraph.nodeForTile(RoutingStaticTestFixture.T3_B);
		assertEquals(6, reverse.label(bank, BankVisitState.CARRIED));
		assertEquals(20, reverse.label(bank, BankVisitState.BANKED));
		assertEquals(6, reverse.label(bankGraph.bankedGlobalHubNode(), BankVisitState.BANKED));
		assertEquals(CostArithmetic.INF, reverse.label(bankGraph.bankedGlobalHubNode(), BankVisitState.CARRIED));
	}

	@Test
	public void heapOrderAndIdentityMismatch() throws Exception
	{
		AStarMinHeap heap = new AStarMinHeap(1);
		heap.push(1, 1, 2);
		heap.push(1, 1, 1);
		heap.push(3, 3, 0);
		heap.push(1, 2, 0);
		assertEquals(1, heap.poll() ? heap.state() : -1);
		assertEquals(2, heap.poll() ? heap.state() : -1);
		assertEquals(0, heap.poll() ? heap.state() : -1);
		assertEquals(0, heap.poll() ? heap.state() : -1);
		assertTrue(!heap.poll());

		RoutingStatic stat = RoutingStaticTestFixture.createT3();
		SiteGraph graph = new SiteGraph(stat, emptyAccount());
		TargetOverlay first =
			new TargetOverlay(graph, collision(RoutingStaticTestFixture.T3_TARGET), RoutingStaticTestFixture.T3_TARGET);
		PreparedHeuristic heuristic = PreparedHeuristic.prepare(first, ReverseLabelsOracle.compute(first));
		TargetOverlay otherTarget =
			new TargetOverlay(new SiteGraph(RoutingStaticTestFixture.createT3(), emptyAccount()),
				collision(RoutingStaticTestFixture.T3_TARGET), RoutingStaticTestFixture.T3_TARGET);
		try
		{
			heuristic.estimate(otherTarget, RoutingStaticTestFixture.T3_TARGET, BankVisitState.CARRIED);
			fail("another static snapshot must be rejected");
		}
		catch (IllegalArgumentException expected)
		{
		}
	}

	@Test
	public void reverseLabelsMatchSimpleRelaxationOracle() throws Exception
	{
		RoutingStatic stat = RoutingStaticTestFixture.createT3();
		PreparedRoutingAccount account = account(
			new Transport[] {local(RoutingStaticTestFixture.T3_B, RoutingStaticTestFixture.T3_D, 9)},
			new Transport[] {local(RoutingStaticTestFixture.T3_A, RoutingStaticTestFixture.T3_B, 2),
				global(RoutingStaticTestFixture.T3_D, 6)},
			true);
		SiteGraph graph = new SiteGraph(stat, account);
		TargetOverlay target = new TargetOverlay(graph,
			collision(RoutingStaticTestFixture.T3_TARGET, RoutingStaticTestFixture.T3_SEARCH_0,
				RoutingStaticTestFixture.T3_SEARCH_1),
			RoutingStaticTestFixture.T3_TARGET);

		assertArrayEquals(simpleLabels(target), ReverseLabelsOracle.compute(target).labels());
	}

	private static int[] simpleLabels(TargetOverlay target)
	{
		SiteGraph graph = target.graph();
		RoutingStatic stat = target.routingStatic();
		int[] labels = new int[target.queryNodeCount() * 2];
		Arrays.fill(labels, CostArithmetic.INF);
		labels[target.targetState(BankVisitState.CARRIED)] = 0;
		labels[target.targetState(BankVisitState.BANKED)] = 0;
		boolean changed;
		do
		{
			changed = false;
			for (int state = 0; state < graph.stateCount(); state++)
			{
				for (int edge = graph.reverseEdgeStart(state); edge < graph.reverseEdgeEnd(state); edge++)
				{
					changed |= relax(labels, graph.reverseFromState(edge), labels[state], graph.reverseCost(edge));
				}
			}
			for (BankVisitState banked : BankVisitState.values())
			{
				for (int from = 0; from < graph.spatialNodeCount(); from++)
				{
					for (int to = 0; to < graph.spatialNodeCount(); to++)
					{
						if (from != to && sharesComponent(stat.siteComponents(from), stat.siteComponents(to)))
						{
							changed |= relax(labels, SiteGraph.stateId(from, banked),
								labels[SiteGraph.stateId(to, banked)],
								shortestpath.WorldPointUtil.distanceBetween(stat.siteTile(from), stat.siteTile(to)));
						}
					}
					if (target.synthetic() && sharesComponent(stat.siteComponents(from), target.components()))
					{
						int siteState = SiteGraph.stateId(from, banked);
						int targetState = target.targetState(banked);
						int distance = shortestpath.WorldPointUtil.distanceBetween(
							stat.siteTile(from), target.packedTarget());
						changed |= relax(labels, siteState, labels[targetState], distance);
						changed |= relax(labels, targetState, labels[siteState], distance);
					}
				}
			}
		}
		while (changed);
		return labels;
	}

	private static boolean relax(int[] labels, int state, int base, int edge)
	{
		int candidate = CostArithmetic.add(base, edge);
		if (candidate >= labels[state])
		{
			return false;
		}
		labels[state] = candidate;
		return true;
	}

	private static boolean sharesComponent(int[] left, int[] right)
	{
		for (int a : left)
		{
			for (int b : right)
			{
				if (a == b)
				{
					return true;
				}
			}
		}
		return false;
	}

	private static PreparedRoutingAccount emptyAccount()
	{
		return account(new Transport[0], new Transport[0], false);
	}

	private static PreparedRoutingAccount account(Transport... carried)
	{
		return account(carried, new Transport[0], false);
	}

	private static PreparedRoutingAccount account(Transport[] carried, Transport[] banked, boolean bankPath)
	{
		return PreparedRoutingAccount.compile(
			availability(carried), availability(banked), bankPath,
			java.util.Set.of(RoutingStaticTestFixture.BANK, RoutingStaticTestFixture.T3_B), 0, true, ignored -> 0);
	}

	private static TransportAvailability availability(Transport[] transports)
	{
		TransportAvailability.Builder builder = new TransportAvailability.Builder(transports.length);
		for (Transport transport : transports)
			builder.add(transport);
		return builder.build();
	}

	private static Transport local(int origin, int destination, int duration)
	{
		return new Transport.TransportBuilder()
			.origin(origin)
			.destination(destination)
			.type(TransportType.TRANSPORT)
			.duration(duration)
			.build();
	}

	private static Transport global(int destination, int duration)
	{
		return new Transport.TransportBuilder()
			.destination(destination)
			.type(TransportType.TELEPORTATION_ITEM)
			.duration(duration)
			.maxWildernessLevel(0)
			.build();
	}

	private static CollisionMap collision(int target, int... neighbors)
	{
		return new CollisionMap(null)
		{
			@Override
			public int[] ordinaryWalkingNeighbors(int packedPoint)
			{
				return packedPoint == target ? neighbors.clone() : new int[0];
			}
		};
	}
}

package shortestpath.pathfinder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

public class SearchDeadlineTest
{
	private static final long MS = 1_000_000L;

	/** A clock that only moves when told to and counts how often it is read. */
	private static final class FakeClock
	{
		long now = 5_000 * MS;
		int reads;

		long read()
		{
			reads++;
			return now;
		}
	}

	@Test
	public void readsTheClockOncePerCheckInterval()
	{
		FakeClock clock = new FakeClock();
		SearchDeadline deadline = new SearchDeadline(100, clock::read);
		clock.reads = 0;

		for (int i = 0; i < SearchDeadline.CHECK_INTERVAL * 5; i++)
			assertFalse(deadline.expired());

		assertEquals(5, clock.reads);
	}

	@Test
	public void expiresAtTheFirstClockReadAfterTheCutoff()
	{
		FakeClock clock = new FakeClock();
		SearchDeadline deadline = new SearchDeadline(100, clock::read);
		clock.now += 101 * MS;

		for (int i = 1; i < SearchDeadline.CHECK_INTERVAL; i++)
			assertFalse(deadline.expired());

		assertTrue(deadline.expired());
		assertTrue(deadline.expired());
	}

	@Test
	public void doesNotExpireExactlyAtTheCutoff()
	{
		FakeClock clock = new FakeClock();
		SearchDeadline deadline = new SearchDeadline(100, clock::read);
		clock.now += 100 * MS;

		assertFalse(checkInterval(deadline));
		clock.now += 1;
		assertTrue(checkInterval(deadline));
	}

	@Test
	public void progressRestartsTheCountdownAtTheNextClockRead()
	{
		FakeClock clock = new FakeClock();
		SearchDeadline deadline = new SearchDeadline(100, clock::read);
		clock.now += 90 * MS;
		deadline.progressed();

		assertFalse(checkInterval(deadline));
		clock.now += 95 * MS;
		assertFalse(checkInterval(deadline));
		clock.now += 10 * MS;
		assertTrue(checkInterval(deadline));
	}

	@Test
	public void zeroCutoffExpiresAtTheFirstClockRead()
	{
		FakeClock clock = new FakeClock();
		SearchDeadline deadline = new SearchDeadline(0, clock::read);

		assertTrue(checkInterval(deadline));
	}

	/** Runs one full check interval and returns the result of the call that read the clock. */
	private static boolean checkInterval(SearchDeadline deadline)
	{
		for (int i = 1; i < SearchDeadline.CHECK_INTERVAL; i++)
			deadline.expired();
		return deadline.expired();
	}
}

package shortestpath.pathfinder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.doReturn;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import java.util.List;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;
import net.runelite.api.gameval.DBTableID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import org.junit.BeforeClass;
import org.junit.Test;
import shortestpath.settings.TeleportationItem;
import shortestpath.TestShortestPathConfig;
import shortestpath.WorldPointUtil;
import shortestpath.pathfinder.astar.RoutingStatic;

/**
 * Both searches routing to targets that need a spade, on the real map, from the Lumbridge Castle
 * courtyard. {@link #NEAR} is 19 to walk to, or 61 through the castle's top-floor bank;
 * {@link #FARTHER} is 39 to walk to.
 */
public class TargetItemsSearchTest
{
	private static final int START = WorldPointUtil.packWorldPoint(3222, 3218, 0);
	private static final int NEAR = WorldPointUtil.packWorldPoint(3240, 3225, 0);
	private static final int FARTHER = WorldPointUtil.packWorldPoint(3260, 3230, 0);

	private static RoutingStatic routingStatic;

	@BeforeClass
	public static void buildRoutingStatic()
	{
		routingStatic = TestWorldData.routingStatic();
	}

	private static Target spadeAt(int point)
	{
		return Target.requiring(point, TargetsTest.items(ItemID.SPADE));
	}

	/** A logged-in player carrying {@code carried} with {@code banked} in the bank. */
	private static PathfinderConfig config(Item[] carried, Item[] banked)
	{
		Client client = mock(Client.class);
		ItemContainer inventory = mock(ItemContainer.class);
		ItemContainer worn = mock(ItemContainer.class);
		ItemContainer bank = mock(ItemContainer.class);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getClientThread()).thenReturn(Thread.currentThread());
		when(client.getDBTableRows(DBTableID.Quest.ID)).thenReturn(List.of());
		when(client.getBoostedSkillLevel(any(Skill.class))).thenReturn(99);
		doReturn(carried).when(inventory).getItems();
		doReturn(new Item[0]).when(worn).getItems();
		doReturn(banked).when(bank).getItems();
		doReturn(inventory).when(client).getItemContainer(InventoryID.INV);
		doReturn(worn).when(client).getItemContainer(InventoryID.WORN);
		TestShortestPathConfig settings = new TestShortestPathConfig();
		settings.setUseTeleportationItemsValue(TeleportationItem.NONE);
		settings.setCalculationCutoffValue(50);

		PathfinderConfig config = new TestPathfinderConfig(client, settings, QuestState.FINISHED, true, true);
		shortestpath.items.ItemStateService itemState = shortestpath.items.ItemStateTestServices.forTesting();
		config.setItemStateService(itemState);
		itemState.noteBankContainer(bank);
		config.refresh();
		return config;
	}

	private static Item[] spade()
	{
		return new Item[] {new Item(ItemID.SPADE, 1)};
	}

	private static PathfinderResult legacy(PathfinderConfig config, Target... targets)
	{
		Pathfinder pathfinder = new Pathfinder(config, START, Targets.of(List.of(targets)));
		pathfinder.run();
		return pathfinder.getResult();
	}

	private static PathfinderResult aStar(PathfinderConfig config, Target... targets)
	{
		AStarPathfinder pathfinder = new AStarPathfinder(config, () -> routingStatic, null, START,
			Targets.of(List.of(targets)), null, 1);
		pathfinder.run();
		return pathfinder.getResult();
	}

	private static boolean banked(PathfinderResult result)
	{
		List<PathStep> path = result.getPathSteps();
		return path.get(path.size() - 1).getBankVisitState() == BankVisitState.BANKED;
	}

	@Test
	public void carriedItemsRouteDirectly()
	{
		PathfinderConfig config = config(spade(), spade());
		for (PathfinderResult result : List.of(legacy(config, spadeAt(NEAR)), aStar(config, spadeAt(NEAR))))
		{
			assertEquals(19, result.getPathCost());
			assertFalse(banked(result));
			assertEquals(TargetStatus.CARRIED, result.getArrival().getStatus());
		}
	}

	@Test
	public void bankedItemsRouteThroughABankAtTheSameCostInBothSearches()
	{
		PathfinderConfig config = config(new Item[0], spade());
		assertFalse("bank visits are off in the settings", config.isBankPathEnabled());
		for (PathfinderResult result : List.of(legacy(config, spadeAt(NEAR)), aStar(config, spadeAt(NEAR))))
		{
			assertTrue(result.isReached());
			assertEquals(61, result.getPathCost());
			assertTrue(banked(result));
			assertEquals(NEAR, result.getArrival().getTarget().getPoint());
			assertEquals(TargetStatus.BANK, result.getArrival().getStatus());
		}
	}

	@Test
	public void fartherTargetWinsOverACloserOneThatNeedsABankTrip()
	{
		PathfinderConfig config = config(new Item[0], spade());
		for (PathfinderResult result : List.of(legacy(config, spadeAt(NEAR), Target.at(FARTHER)),
			aStar(config, spadeAt(NEAR), Target.at(FARTHER))))
		{
			assertEquals(FARTHER, result.getArrival().getTarget().getPoint());
			assertFalse(banked(result));
		}
	}

	@Test
	public void itemsNotFoundRouteDirectlyAndAreReported()
	{
		PathfinderConfig config = config(new Item[0], new Item[0]);
		for (PathfinderResult result : List.of(legacy(config, spadeAt(NEAR)), aStar(config, spadeAt(NEAR))))
		{
			assertEquals(19, result.getPathCost());
			assertEquals(TargetStatus.UNKNOWN, result.getArrival().getStatus());
			assertEquals(TargetsTest.items(ItemID.SPADE).getRequirements(), result.getArrival().getMissingItems());
		}
	}
}

package shortestpath.pathfinder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

import java.util.List;
import java.util.Set;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;
import shortestpath.requirement.model.ItemRequirement;
import shortestpath.requirement.model.TransportItems;

public class TargetsTest
{
	private static final int A = 1;
	private static final int B = 2;
	private static final int C = 3;

	static TransportItems items(int... ids)
	{
		List<ItemRequirement> groups = new java.util.ArrayList<>();
		for (int id : ids)
		{
			groups.add(new ItemRequirement(new int[] {id}, new int[0], new int[0], 1));
		}
		return new TransportItems(groups);
	}

	@Test
	public void pointsMakeTargetsWithoutItems()
	{
		Targets targets = Targets.at(List.of(A, B));
		assertEquals(Set.of(A, B), targets.points());
		assertFalse(targets.hasRequiredItems());
		assertEquals(Target.at(A), targets.get(A));
		assertEquals(Target.at(A).hashCode(), targets.get(A).hashCode());
		assertSame(Targets.NONE, Targets.at(List.of()));
	}

	@Test
	public void sameTileTwiceIsFineWhenItAsksForTheSameItems()
	{
		Targets targets = Targets.of(List.of(Target.requiring(A, items(ItemID.SPADE)),
			Target.requiring(A, items(ItemID.SPADE))));
		assertEquals(1, targets.size());
		assertTrue(targets.hasRequiredItems());
	}

	@Test(expected = IllegalArgumentException.class)
	public void sameTileTwiceWithDifferentItemsIsAmbiguous()
	{
		Targets.of(List.of(Target.requiring(A, items(ItemID.SPADE)), Target.at(A)));
	}

	@Test
	public void restrictingKeepsItemsAndAddsPlainTargets()
	{
		Target spade = Target.requiring(A, items(ItemID.SPADE));
		Targets restricted = Targets.of(List.of(spade, Target.at(B))).restrictTo(List.of(A, C));
		assertEquals(Set.of(A, C), restricted.points());
		assertEquals(spade, restricted.get(A));
		assertEquals(Target.at(C), restricted.get(C));
	}

	@Test
	public void plusKeepsTheTargetsAlreadyThere()
	{
		Target spade = Target.requiring(A, items(ItemID.SPADE));
		Targets added = Targets.of(List.of(spade)).plus(Targets.at(List.of(A, B)));
		assertEquals(spade, added.get(A));
		assertEquals(Target.at(B), added.get(B));
	}

	@Test
	public void equalTargetsAreEqualWhateverTheirOrder()
	{
		assertEquals(Targets.at(List.of(A, B)), Targets.at(List.of(B, A)));
		assertEquals(Targets.at(List.of(A, B)).hashCode(), Targets.at(List.of(B, A)).hashCode());
		assertFalse(Targets.at(List.of(A)).equals(Targets.of(List.of(Target.requiring(A, items(ItemID.SPADE))))));
	}
}

package shortestpath.pathfinder;

import net.runelite.api.Client;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import java.util.Collection;
import java.util.Map;
import shortestpath.ShortestPathConfig;
import shortestpath.transport.Transport;
import shortestpath.requirement.model.VarRequirement;

// This subclass is used to provide mocked implementations of methods from the normal
// PathfinderConfig. CRUCIAL: Not implemented via Mockito as these methods are called
// many times in the inner pathfinding loop.
//
// In particular, at the moment you can provide default values for:
//  * getQuestState: Whether all quests are completed or not started.
//  * varbitChecks: Ignore any varbitChecks.
//  * varPlayerChecks: Ignore any varPlayerChecks.
// Other methods are delegated to a normal PathfinderConfig.
public class TestPathfinderConfig extends PathfinderConfig
{
	private final QuestState questState;
	private final boolean bypassVarbitChecks;
	private final boolean bypassVarPlayerChecks;

	public TestPathfinderConfig(Client client, ShortestPathConfig config)
	{
		this(client, config, QuestState.FINISHED, true, true);
	}

	public TestPathfinderConfig(Client client, ShortestPathConfig config, QuestState questState,
		boolean bypassVarbitChecks, boolean bypassVarPlayerChecks)
	{
		super(client, config,
			TestWorldData.map(),
			TestWorldData.transports(),
			TestWorldData.destinations(),
			TestWorldData.filteredDestinations(),
			TestWorldData.bankRequirements());
		this.questState = questState;
		this.bypassVarbitChecks = bypassVarbitChecks;
		this.bypassVarPlayerChecks = bypassVarPlayerChecks;
	}

	@Override
	public QuestState getQuestState(Quest quest)
	{
		return questState;
	}

	@Override
	public boolean varbitChecks(Collection<VarRequirement> requirements, long evaluationTimeMinutes)
	{
		return !bypassVarbitChecks && super.varbitChecks(requirements, evaluationTimeMinutes);
	}

	@Override
	public boolean varbitChecks(Collection<VarRequirement> requirements,
		Map<Integer, Integer> values, long evaluationTimeMinutes)
	{
		return !bypassVarbitChecks && super.varbitChecks(requirements, values, evaluationTimeMinutes);
	}

	@Override
	public boolean varPlayerChecks(Collection<VarRequirement> requirements, long evaluationTimeMinutes)
	{
		return !bypassVarPlayerChecks && super.varPlayerChecks(requirements, evaluationTimeMinutes);
	}

	@Override
	public boolean varPlayerChecks(Collection<VarRequirement> requirements,
		Map<Integer, Integer> values, long evaluationTimeMinutes)
	{
		return !bypassVarPlayerChecks && super.varPlayerChecks(requirements, values, evaluationTimeMinutes);
	}

	/**
	 * Builds a real {@link TransportAvailability} holding the given transports. Mockito's
	 * default mock maker cannot mock the final class, so tests that need availability
	 * lookups go through this instead.
	 */
	public static TransportAvailability availabilityOf(Transport... transports)
	{
		TransportAvailability.Builder builder = new TransportAvailability.Builder(transports.length);
		for (Transport transport : transports)
		{
			builder.add(transport);
		}
		builder.remapPohTransports();
		return builder.build();
	}
}

package shortestpath.pathfinder;

import java.util.Map;
import java.util.Set;
import shortestpath.poh.PohService;
import shortestpath.pathfinder.astar.RoutingCuts;
import shortestpath.pathfinder.astar.RoutingStatic;
import shortestpath.requirement.model.DestinationRequirements;
import shortestpath.transport.ResourceLoader;
import shortestpath.transport.Transport;

/**
 * The plugin's world data, loaded lazily once per JVM and shared by every test that works on
 * real map/transport data. Each kind lives in its own Initialization-on-Demand holder, so a test
 * touching only {@link #map()} never pays for the transport load or the routing-static build.
 *
 * <p><b>Read-only contract:</b> every returned map/set/object is shared JVM state — callers must
 * never mutate it. {@link PohService#remapPohDestinations} rewrites {@link Transport} objects in
 * place, so it is applied exactly once, inside the holder that produces the remapped view; a test
 * that needs to mutate (or re-remap) loads fresh via {@link ResourceLoader} or copies.
 * {@link SplitFlagMap#fromResources()} rewrites the static {@code regionExtents} as a side
 * effect, which is another reason the map loads through one holder instead of per test class.
 *
 * <p><b>Two transport views:</b> {@link #transports()} is the POH-remapped view the pathfinder
 * tests expect; {@link #rawTransports()} is the unremapped parse the lint/fidelity data-regression
 * tests assert against. Never feed the remapped view to a lint test — its assertions would
 * silently see rewritten destinations.
 *
 * <p><b>Kinds:</b> {@link #map()}, {@link #transports()}, {@link #rawTransports()},
 * {@link #destinations()}, {@link #filteredDestinations()}, {@link #bankRequirements()},
 * {@link #routingCuts()}, {@link #routingStatic()} (the ~4s full-world A* build, memoized through
 * the same provider the production code uses).
 *
 * <p><b>Deliberate bypasses:</b> tests that exist to guard the data files themselves keep their
 * own loads and must not be migrated here — TransportDataLintTest, DestinationDataLintTest,
 * ResourceLoaderTest, ResourceLoaderFidelityTest, TransportCountingTest, SeaReachabilityTest,
 * RoutingStaticBuilderRealDataTest, RoutingCutsTest — because sharing one parse would narrow the
 * regression surface they deliberately re-execute.
 *
 * <p>This class is compiled into the tooling composite build via a fileTree source share, so it
 * must stay Mockito-free and RuneLite-client-agnostic: main-tree types only.
 */
public final class TestWorldData
{
	private TestWorldData()
	{
	}

	private static final class CollisionData
	{
		static final SplitFlagMap DATA = SplitFlagMap.fromResources();
	}

	private static final class Transports
	{
		static final Map<Integer, Set<Transport>> REMAPPED = load();

		private static Map<Integer, Set<Transport>> load()
		{
			Map<Integer, Set<Transport>> transports = ResourceLoader.transports();
			PohService.remapPohDestinations(transports);
			return transports;
		}
	}

	private static final class RawTransports
	{
		static final Map<Integer, Set<Transport>> ALL = ResourceLoader.transports();
	}

	private static final class Destinations
	{
		static final Map<String, Set<Integer>> ALL = ResourceLoader.destinations();
	}

	private static final class FilteredDestinations
	{
		static final Map<String, Set<Integer>> ALL = PathfinderConfig.filterDestinations(
			Destinations.ALL);
	}

	private static final class BankRequirements
	{
		static final Map<Integer, DestinationRequirements> ALL = ResourceLoader.bankRequirements();
	}

	private static final class Cuts
	{
		static final RoutingCuts ALL = RoutingCuts.loadFromResources();
	}

	private static final class AStarStatic
	{
		static final AStarRoutingStaticProvider PROVIDER = new AStarRoutingStaticProvider(
			() -> new CollisionMap(CollisionData.DATA));
		static final RoutingStatic STATIC = PROVIDER.get();
	}

	/** The collision map, decompressed once per JVM. */
	public static SplitFlagMap map()
	{
		return CollisionData.DATA;
	}

	/** Transports with POH destinations remapped — the view pathfinder tests expect. */
	public static Map<Integer, Set<Transport>> transports()
	{
		return Transports.REMAPPED;
	}

	/** Transports as parsed, without the POH remap — for lint/fidelity assertions. */
	public static Map<Integer, Set<Transport>> rawTransports()
	{
		return RawTransports.ALL;
	}

	/** All destinations as parsed. */
	public static Map<String, Set<Integer>> destinations()
	{
		return Destinations.ALL;
	}

	/** Destinations after the config's availability filter. */
	public static Map<String, Set<Integer>> filteredDestinations()
	{
		return FilteredDestinations.ALL;
	}

	/** Per-tile bank requirements for pickup-aware routing. */
	public static Map<Integer, DestinationRequirements> bankRequirements()
	{
		return BankRequirements.ALL;
	}

	/** The A* routing-cut table parsed once per JVM. */
	public static RoutingCuts routingCuts()
	{
		return Cuts.ALL;
	}

	/** The full-world A* routing static, built once per JVM and shared across tests. */
	public static RoutingStatic routingStatic()
	{
		return AStarStatic.STATIC;
	}

	/**
	 * The provider that built {@link #routingStatic()}. Injection points typed as the provider —
	 * the plugin scheduler's {@code aStarRoutingStatic} field — share this instance so their
	 * {@code get()} returns the already-built static instead of paying a second world build.
	 */
	public static AStarRoutingStaticProvider routingStaticProvider()
	{
		return AStarStatic.PROVIDER;
	}
}

