		assertEquals(describe(steps(0, 33, 0, 34, 0, 35)), describe(result.path().subList(33, 36)));
		assertEquals(gamePath(grid, pack(4, 0), pack(0, 35)), tiles(result.path(), 0, 35));
		assertEquals(List.of(34, 35), result.clickPoints());
