		assertEquals(1, result.counters().heuristicUnreachable());
	}

	@Test
	public void carriedStartCanReachTheBankAndReturnToItsOwnTargetTile()
	{
		PreparedTarget target = prepare(new int[] {TARGET}, new int[] {2}, true, 5);
		assertEquals(7, target.heuristic().estimate(TARGET, BankVisitState.CARRIED));
		for (double weight : new double[] {1, 1.5})
		{
			AStarForwardSearch.Result result = target.search(TARGET, () -> false, weight);
			assertTrue(result.reached());
			assertEquals(7, result.cost());
			assertTrue(result.path().stream().anyMatch(step -> step.getPackedPosition() == BANK
				&& step.getBankVisitState() == BankVisitState.BANKED));
			assertEquals(BankVisitState.BANKED, result.path().get(result.path().size() - 1).getBankVisitState());
		}
	}

	@Test
	public void eitherLayerGoalSeedsBothLayersAndNeedsNoBank()
	{
		PreparedTarget target = prepare(new int[] {TARGET}, new int[] {3}, true, 5);
		for (BankVisitState layer : BankVisitState.values())
			assertEquals(0, target.heuristic().reverseLabels().targetLabel(layer));
		AStarForwardSearch.Result result = target.search(START, () -> false, 1);
		assertTrue(result.reached());
		assertEquals(2, result.cost());
		assertTrue(result.path().stream().allMatch(step -> step.getBankVisitState() == BankVisitState.CARRIED));
	}

	@Test
	public void mixedTargetsChooseTheCheapestValidLayer()
	{
		for (int bankCost : new int[] {1, 5})
		{
			PreparedTarget target = prepare(new int[] {TARGET, FAR}, new int[] {2, 3}, true, bankCost);
			ReverseLabels labels = target.heuristic().reverseLabels();
			assertEquals(0, labels.targetLabel(0, BankVisitState.BANKED));
			assertTrue(labels.targetLabel(0, BankVisitState.CARRIED) != 0);
			assertEquals(0, labels.targetLabel(1, BankVisitState.CARRIED));
			AStarForwardSearch.Result result = target.search(START, () -> false, 1);
			assertTrue(result.reached());
			assertEquals(bankCost == 1 ? 3 : 5, result.cost());
			assertEquals(bankCost == 1 ? TARGET : FAR,
				result.path().get(result.path().size() - 1).getPackedPosition());
		}
	}

	@Test
	public void sparseCliqueAndReducedSeedScansAgreeForAsymmetricLayers()
	{
		for (boolean accessible : new boolean[] {false, true})
		{
			for (int[] masks : new int[][] {{2}, {2, 3}, {1, 2}})
			{
				int[] tiles = masks.length == 1 ? new int[] {TARGET} : new int[] {TARGET, FAR};
				TargetOverlay overlay = prepare(tiles, masks, accessible, 5).overlay();
				ReverseLabels sparse = ReverseLabels.computeSparse(overlay);
				ReverseLabels clique = ReverseLabelsOracle.computeClique(overlay);
				assertArrayEquals(clique.labels(), sparse.labels());
				PreparedHeuristic heuristic = PreparedHeuristic.prepare(overlay, sparse);
				for (int node = 0; node < stat.searchTileCount(); node++)
				{
					for (BankVisitState layer : BankVisitState.values())
					{
						int packed = stat.searchTile(node);
						int[] components = {stat.routingComponent(node)};
						assertEquals(heuristic.estimateRaw(packed, layer, components),
							heuristic.estimate(packed, layer, components));
					}
				}
			}
		}
	}

	private PreparedTarget prepare(int[] tiles, int[] masks, boolean accessible, int bankCost)
	{
		PreparedRoutingAccount account = PreparedRoutingAccount.compile(TransportAvailabilityFixture.of(),
			TransportAvailabilityFixture.of(), true, accessible ? Set.of(BANK) : Set.of(), bankCost, true, ignored -> 0);
		return PreparedTarget.prepare(new SiteGraph(stat, account), collision, tiles, masks);
	}

	private static int tile(int x)
	{
		return WorldPointUtil.packWorldPoint(x, 10, 0);
	}
}

package shortestpath.pathfinder.astar;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.util.Arrays;
import java.util.Set;
import org.junit.Test;
import shortestpath.WorldPointUtil;

/** The component layer's format: round trip, tile lookup, determinism and every rejection. */
public class ComponentLayerTest
{
	private static int tile(int x, int y, int plane)
	{
		return WorldPointUtil.packWorldPoint(x, y, plane);
	}

	/** Has the sign bit and every byte position set, so a reader that drops or reorders bytes shows. */
	private static final long FINGERPRINT = 0x8123456789abcdefL;

	/** Runs on planes 0 and 3, a gap above 2^31, a maximal run and three crossings. */
	private static ComponentLayer layer()
	{
		int first = tile(10, 10, 0);
		int second = first + 3;
		int upper = tile(20, 30, 3);
		int last = upper + 1 + 5;
		return new ComponentLayer(FINGERPRINT, new int[] {first, second, upper, last}, new char[] {3, 65535, 1, 2},
			new int[] {1, 2, 3, 1}, new int[] {first, second, second + 1, upper, upper, last});
	}

	/** Builds a layer file by hand, for shapes the writer refuses to produce. */
	private static final class Encoder
	{
		private final ByteArrayOutputStream out = new ByteArrayOutputStream();

		Encoder()
		{
			out.write(ComponentLayer.MAGIC, 0, ComponentLayer.MAGIC.length);
		}

		Encoder varint(long value)
		{
			for (; (value & ~0x7fL) != 0; value >>>= 7) out.write((int) (value & 0x7f) | 0x80);
			out.write((int) value);
			return this;
		}

		Encoder raw(int... bytes)
		{
			for (int value : bytes) out.write(value);
			return this;
		}

		Encoder fingerprint(long value)
		{
			for (int shift = 56; shift >= 0; shift -= 8) out.write((int) (value >>> shift));
			return this;
		}

		Encoder tile(int tile)
		{
			return raw(tile >>> 24, tile >>> 16, tile >>> 8, tile);
		}

		byte[] bytes()
		{
			return out.toByteArray();
		}
	}

	private static Encoder header(long runs, long crossings)
	{
		return new Encoder().varint(ComponentLayer.VERSION).fingerprint(FINGERPRINT).varint(runs).varint(crossings);
	}

	private static ComponentLayer read(byte[] bytes) throws IOException
	{
		return ComponentLayer.read(new ByteArrayInputStream(bytes));
	}

	private static IOException rejected(byte[] bytes)
	{
		try
		{
			read(bytes);
		}
		catch (IOException expected)
		{
			assertNotNull(expected.getMessage());
			return expected;
		}
		throw new AssertionError("a malformed layer was accepted");
	}

	private static void assertRejectedWith(String part, byte[] bytes)
	{
		String message = rejected(bytes).getMessage();
		assertTrue(message, message.contains(ComponentLayer.RESOURCE) && message.contains(part));
	}

	@Test
	public void roundTripKeepsEveryColumn() throws Exception
	{
		ComponentLayer expected = layer();
		ComponentLayer actual = read(ComponentLayerWriter.write(expected));

		assertEquals(FINGERPRINT, actual.fingerprint);
		assertArrayEquals(expected.starts, actual.starts);
		assertArrayEquals(expected.lengths, actual.lengths);
		assertArrayEquals(expected.ids, actual.ids);
		assertArrayEquals(expected.crossings, actual.crossings);
		int gap = actual.starts[2] - (actual.starts[1] + actual.lengths[1]);
		assertTrue("gap " + Integer.toUnsignedString(gap), Integer.compareUnsigned(gap, Integer.MIN_VALUE) > 0);
	}

	@Test
	public void emptyLayerRoundTrips() throws Exception
	{
		ComponentLayer actual = read(ComponentLayerWriter.write(new ComponentLayer(0, new int[0], new char[0], new int[0],
			new int[0])));

		assertEquals(0, actual.starts.length);
		assertEquals(0, actual.component(tile(10, 10, 0)));
	}

	@Test
	public void componentFindsRunsAndMissesGaps() throws Exception
	{
		ComponentLayer layer = read(ComponentLayerWriter.write(layer()));
		int first = layer.starts[0], second = layer.starts[1], upper = layer.starts[2], last = layer.starts[3];

		assertEquals(1, layer.component(first));
		assertEquals(1, layer.component(first + 2));
		assertEquals(0, layer.component(first - 1));
		assertEquals(2, layer.component(second));
		assertEquals(2, layer.component(second + 65534));
		assertEquals(0, layer.component(second + 65535));
		assertEquals(3, layer.component(upper));
		assertEquals(0, layer.component(upper + 1));
		assertEquals(1, layer.component(last));
		assertEquals(1, layer.component(last + 1));
		assertEquals(0, layer.component(last + 2));
		assertEquals(0, layer.component(tile(5, 5, 1)));
	}

	@Test
	public void generatedLayerIsByteForByteDeterministic() throws Exception
	{
		int a = tile(10, 10, 0), b = tile(11, 10, 0), c = tile(12, 10, 0);
		int[] cuts = {b, c};
		byte[] first = ComponentLayerWriter.write(RoutingStaticBuilder.generate(chain(a, b, c), cuts));
		byte[] second = ComponentLayerWriter.write(RoutingStaticBuilder.generate(chain(a, b, c), cuts));

		assertTrue(first.length > ComponentLayer.MAGIC.length);
		assertArrayEquals(first, second);
		ComponentLayer layer = read(first);
		assertEquals(1, layer.component(a));
		assertEquals(1, layer.component(b));
		assertEquals(2, layer.component(c));
		assertArrayEquals(new int[] {b, c}, layer.crossings);
	}

	private static SyntheticCollisionMap chain(int a, int b, int c)
	{
		return new SyntheticCollisionMap(Set.of(a, b, c),
			SyntheticCollisionMap.symmetricAdjacency(new int[][] {{a, b}, {b, c}}), 1);
	}

	@Test
	public void missingStreamIsRejected()
	{
		try
		{
			ComponentLayer.read(null);
			throw new AssertionError("a missing resource was accepted");
		}
		catch (IOException expected)
		{
			assertTrue(expected.getMessage(), expected.getMessage().contains(ComponentLayer.RESOURCE));
		}
	}

	@Test
	public void wrongMagicIsRejected()
	{
		byte[] bytes = ComponentLayerWriter.write(layer());
		bytes[0] ^= 1;
		assertRejectedWith("magic", bytes);
	}

	@Test
	public void wrongVersionIsRejected()
	{
		assertRejectedWith("version", new Encoder().varint(ComponentLayer.VERSION + 1).varint(0).varint(0).bytes());
	}

	@Test
	public void everyProperPrefixIsRejectedAsIOException()
	{
		byte[] bytes = ComponentLayerWriter.write(layer());
		for (int length = 0; length < bytes.length; length++)
			assertTrue("prefix " + length, rejected(Arrays.copyOf(bytes, length)).getMessage().contains(ComponentLayer.RESOURCE));
	}

	@Test
	public void trailingByteIsRejected()
	{
		byte[] valid = ComponentLayerWriter.write(layer());
		assertRejectedWith("trailing", Arrays.copyOf(valid, valid.length + 1));
	}

	@Test
	public void countsLargerThanTheFileAreRejectedBeforeAllocating()
	{
		assertRejectedWith("counts", header(Integer.MAX_VALUE, 0).bytes());
		assertRejectedWith("counts", header(0, 1L << 30).bytes());
		assertRejectedWith("counts", header(0, Integer.MAX_VALUE - 1).bytes());
	}

	@Test
	public void oddAndNegativeCountsAreRejected()
	{
		assertRejectedWith("counts", header(0, 1).tile(7).bytes());
		assertRejectedWith("counts", header(0, 3).tile(1).tile(2).tile(3).bytes());
		assertRejectedWith("counts", header(0xffffffffL, 0).bytes());
		assertRejectedWith("counts", header(0, 0xfffffffeL).bytes());
	}

	@Test
	public void runLongerThanSixtyFiveThousandFiveHundredThirtyFiveTilesIsRejected()
	{
		assertRejectedWith("run", header(1, 0).varint(65535).varint(0).varint(1).bytes());
		assertRejectedWith("run", header(1, 0).varint(0xffffffffL).varint(0).varint(1).bytes());
	}

	@Test
	public void componentIdZeroOrAboveTheRunCountIsRejected()
	{
		assertRejectedWith("id", header(2, 0).varint(0).varint(0).varint(0).varint(0).varint(0).varint(1).bytes());
		assertRejectedWith("id", header(2, 0).varint(0).varint(0).varint(0).varint(0).varint(1).varint(3).bytes());
	}

	@Test
	public void runStartingBelowThePreviousRunsEndIsRejected()
	{
		// The first run ends at 2^32, so the second one starts past the end of the tile range.
		assertRejectedWith("run", header(2, 0).varint(15).varint(0).varint(0xfffffff0L).varint(1).varint(1).varint(2).bytes());
		// A gap of 2^32 - 1 after a run ending at 100 wraps to 99.
		assertRejectedWith("run", header(2, 0).varint(99).varint(0).varint(0).varint(0xffffffffL).varint(1).varint(2).bytes());
	}

	@Test
	public void overLongVarintIsRejected()
	{
		byte[] bytes = new Encoder().varint(ComponentLayer.VERSION).fingerprint(0).varint(1).varint(0)
			.raw(0x80, 0x80, 0x80, 0x80, 0x80, 0x00).varint(0).varint(1).bytes();
		assertRejectedWith("varint", bytes);
	}

	@Test
	public void nonCanonicalVarintsAreRejected()
	{
		// 0 with a redundant continuation byte.
		assertRejectedWith("varint", new Encoder().varint(ComponentLayer.VERSION).fingerprint(0).varint(1).varint(0)
			.raw(0x80, 0x00).varint(0).varint(1).bytes());
		// A fifth byte carrying bits above 2^32 would be dropped silently.
		assertRejectedWith("varint", new Encoder().varint(ComponentLayer.VERSION).fingerprint(0).varint(1).varint(0)
			.raw(0xff, 0xff, 0xff, 0xff, 0x1f).varint(0).varint(1).bytes());
	}

	@Test
	public void largestRunAndTheLastTileOfTheRangeAreAccepted() throws Exception
	{
		byte[] bytes = header(2, 0).varint(65534).varint(1).varint(0).varint(0xfffffffeL - 65535).varint(1).varint(2).bytes();
		ComponentLayer layer = read(bytes);

		assertEquals(65535, layer.lengths[0]);
		assertEquals(2, layer.component(-1));
	}

	@Test
	public void writerRefusesLayersTheReaderWouldReject()
	{
		assertWriterRefuses(new ComponentLayer(0, new int[] {0}, new char[] {0}, new int[] {1}, new int[0]));
		assertWriterRefuses(new ComponentLayer(0, new int[] {0}, new char[] {1}, new int[] {0}, new int[0]));
		assertWriterRefuses(new ComponentLayer(0, new int[] {0}, new char[] {1}, new int[] {-3}, new int[0]));
	}

	private static void assertWriterRefuses(ComponentLayer layer)
	{
		try
		{
			ComponentLayerWriter.write(layer);
			throw new AssertionError("the writer accepted an unreadable layer");
		}
		catch (IllegalArgumentException expected)
		{
			assertNotNull(expected.getMessage());
		}
	}

	@Test
	public void layerOfARealisticWorldResolvesEveryWalkableTile() throws Exception
	{
		int a = tile(10, 10, 0), b = tile(11, 10, 0), c = tile(40, 40, 0);
		SyntheticCollisionMap world = new SyntheticCollisionMap(Set.of(a, b, c),
			SyntheticCollisionMap.symmetricAdjacency(new int[][] {{a, b}}), 1);
		ComponentLayer layer = read(ComponentLayerWriter.write(RoutingStaticBuilder.generate(world, new int[0])));

		assertEquals(1, layer.component(a));
		assertEquals(1, layer.component(b));
		assertEquals(2, layer.component(c));
		assertEquals(0, layer.component(tile(41, 40, 0)));
	}
}

package shortestpath.pathfinder.astar;

import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import shortestpath.pathfinder.CollisionMap;
import shortestpath.pathfinder.SplitFlagMap;

/**
 * Serializes a {@link ComponentLayer} in the format {@link ComponentLayer#read} accepts, and
 * generates the packaged {@code routing-components.bin} from the committed collision map and
 * routing cuts: {@code ComponentLayerWriter CUTS OUTPUT}.
 */
public final class ComponentLayerWriter
{
	private ComponentLayerWriter()
	{
	}

	static byte[] write(ComponentLayer layer)
	{
		int runs = layer.starts.length;
		ByteArrayOutputStream out = new ByteArrayOutputStream(runs * 5 + layer.crossings.length * 4 + 40);
		out.write(ComponentLayer.MAGIC, 0, ComponentLayer.MAGIC.length);
		varint(out, ComponentLayer.VERSION);
		for (int shift = 56; shift >= 0; shift -= 8) out.write((int) (layer.fingerprint >>> shift));
		varint(out, runs);
		varint(out, layer.crossings.length);
		for (int i = 0; i < runs; i++)
		{
			if (layer.lengths[i] < 1) throw new IllegalArgumentException("run " + i + " is empty");
			varint(out, layer.lengths[i] - 1);
		}
		for (int i = 0, end = 0; i < runs; i++)
		{
			varint(out, layer.starts[i] - end);
			end = layer.starts[i] + layer.lengths[i];
		}
		for (int i = 0; i < runs; i++)
		{
			if (layer.ids[i] < 1) throw new IllegalArgumentException("run " + i + " has component id " + layer.ids[i]);
			varint(out, layer.ids[i]);
		}
		for (int tile : layer.crossings)
		{
			out.write(tile >>> 24);
			out.write(tile >>> 16);
			out.write(tile >>> 8);
			out.write(tile);
		}
		return out.toByteArray();
	}

	/** Unsigned base-128, least-significant group first. */
	private static void varint(ByteArrayOutputStream out, int value)
	{
		while ((value & ~0x7f) != 0)
		{
			out.write((value & 0x7f) | 0x80);
			value >>>= 7;
		}
		out.write(value);
	}

	public static void main(String[] args) throws IOException
	{
		if (args.length != 2) throw new IllegalArgumentException("usage: ComponentLayerWriter CUTS OUTPUT");
		RoutingCuts cuts = RoutingCuts.read(Files.readAllBytes(Paths.get(args[0])));
		if (cuts.cutCount() == 0) throw new IllegalStateException("no routing cuts in " + args[0]);
		CollisionMap collision = new CollisionMap(SplitFlagMap.fromResources());
		ComponentLayer layer = RoutingStaticBuilder.generate(collision, cuts.pairs());
		byte[] bytes = write(layer);
		Path output = Paths.get(args[1]).toAbsolutePath();
		Files.createDirectories(output.getParent());
		Files.write(output, bytes);
		System.out.println("routing components: " + layer.starts.length + " runs, " + layer.crossings.length / 2
			+ " crossings, " + bytes.length + " bytes -> " + output);
	}
}

package shortestpath.pathfinder.astar;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.fail;

import org.junit.Test;

public class CostArithmeticTest
{
	@Test
	public void addsFiniteCosts()
	{
		assertEquals(7, CostArithmetic.add(3, 4));
		assertEquals(0, CostArithmetic.add(0, 0));
		assertEquals(CostArithmetic.INF - 1, CostArithmetic.add(CostArithmetic.INF - 1, 0));
	}

	@Test
	public void infinitySaturates()
	{
		assertEquals(CostArithmetic.INF, CostArithmetic.add(CostArithmetic.INF, 1));
		assertEquals(CostArithmetic.INF, CostArithmetic.add(1, CostArithmetic.INF));
		assertEquals(CostArithmetic.INF, CostArithmetic.add(CostArithmetic.INF - 1, 1));
	}

	@Test
	public void rejectsNegativeCosts()
	{
		try
		{
			CostArithmetic.add(-1, 0);
			fail("negative costs must be rejected");
		}
		catch (IllegalArgumentException expected)
		{
		}
	}

	@Test
	public void weightsSearchPrioritySafely()
	{
		assertEquals(13, AStarForwardSearch.priority(3, 5, 2));
		assertEquals(CostArithmetic.INF - 1,
			AStarForwardSearch.priority(3, CostArithmetic.INF - 1, Double.MAX_VALUE));
		try
		{
			AStarForwardSearch.validateHeuristicWeight(0);
			fail("zero heuristic weight must be rejected");
		}
		catch (IllegalArgumentException expected)
		{
		}
	}
}

package shortestpath.pathfinder.astar;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.util.Arrays;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import org.junit.Test;
import shortestpath.WorldPointUtil;
import shortestpath.pathfinder.BankVisitState;
import shortestpath.pathfinder.TransportAvailabilityFixture;

/**
 * Covers {@link ExactWalks} on a U-shaped corridor whose ends are 2 tiles apart in a straight line
 * but 10 on foot, with banks (sites) at both ends and at the bend:
 *
 * <pre>
 *   y=13: P (blocked, off the corridor, used from C)
 *   y=12:  C --+--+--+--+
 *   y=11:              B
 *   y=10:  A --+--+--+--+
 * </pre>
 */
public class ExactWalksTest
{
	private static final int A = tile(10, 10);
	private static final int B = tile(14, 11);
	private static final int C = tile(10, 12);
	private static final int POCKET = tile(9, 13);
	private static final int[] CORRIDOR =
	{
		tile(10, 12), tile(11, 12), tile(12, 12), tile(13, 12), tile(14, 12),
		tile(14, 11),
		tile(14, 10), tile(13, 10), tile(12, 10), tile(11, 10), tile(10, 10)
	};

	private static int tile(int x, int y)
	{
		return WorldPointUtil.packWorldPoint(x, y, 0);
	}

	private static SyntheticCollisionMap collision()
	{
		int[][] edges = new int[CORRIDOR.length - 1][];
		for (int i = 1; i < CORRIDOR.length; i++)
			edges[i - 1] = new int[] {CORRIDOR[i - 1], CORRIDOR[i]};
		Map<Integer, int[]> adjacency = SyntheticCollisionMap.symmetricAdjacency(edges);
		adjacency.put(POCKET, new int[] {C});
		return new SyntheticCollisionMap(new HashSet<>(Arrays.asList(
			Arrays.stream(CORRIDOR).boxed().toArray(Integer[]::new))), adjacency, 1);
	}

	private static RoutingStatic corridor() throws Exception
	{
		return RoutingStaticBuilder.build(collision(), Map.of(), Set.of(A, B, C, POCKET), new int[0], A).routingStatic;
	}

	private static int component(RoutingStatic stat)
	{
		return stat.routingComponent(stat.searchIndex(A));
	}

	/** The full pair table's entry for two site tiles. */
	private static int pair(RoutingStatic stat, int[][] table, int left, int right)
	{
		int[] sites = stat.componentSites(component(stat));
		return table[Arrays.binarySearch(sites, stat.siteIndex(left))][Arrays.binarySearch(sites, stat.siteIndex(right))];
	}

	@Test
	public void pairDistancesAreWalksNotChebyshev() throws Exception
	{
		RoutingStatic stat = corridor();
		int[][] table = ExactWalks.pairDistances(stat, component(stat));
		assertEquals(10, pair(stat, table, A, C));
		assertEquals(5, pair(stat, table, A, B));
		assertEquals(5, pair(stat, table, B, C));
		// The blocked pocket is used from C, its only neighbour on the corridor.
		assertEquals(10, pair(stat, table, A, POCKET));
		assertEquals(5, pair(stat, table, B, POCKET));
	}

	@Test
	public void edgesThroughAThirdSiteAreLeftOut() throws Exception
	{
		RoutingStatic stat = corridor();
		ExactWalks walks = stat.exactWalks();
		assertTrue(walks.isExact(component(stat)));
		int[] edges = walks.edges(component(stat));
		for (int i = 0; i < edges.length; i += 3)
		{
			Set<Integer> ends = Set.of(stat.siteTile(edges[i]), stat.siteTile(edges[i + 1]));
			assertFalse("A-C is A-B plus B-C", ends.equals(Set.of(A, C)));
		}
		// The component's only sites are joined without Steiner vertices.
		assertEquals(0, stat.sparseSteinerCount());
	}

	@Test
	public void componentsWithTooManySitesKeepTheirTree() throws Exception
	{
		RoutingStatic stat = corridor();
		assertFalse(ExactWalks.build(stat, 3).isExact(component(stat)));
		assertTrue(ExactWalks.build(stat, 4).isExact(component(stat)));
	}

	@Test
	public void reverseLabelsWalkTheCorridor() throws Exception
	{
		RoutingStatic stat = corridor();
		TargetOverlay overlay = new TargetOverlay(new SiteGraph(stat, account()), collision(), C);
		ReverseLabels sparse = ReverseLabelsOracle.compute(overlay);
		assertEquals(10, sparse.label(stat.siteIndex(A), BankVisitState.CARRIED));
		assertArrayEquals(ReverseLabelsOracle.computeClique(overlay).labels(), sparse.labels());
	}

	private static PreparedRoutingAccount account()
	{
		return PreparedRoutingAccount.compile(TransportAvailabilityFixture.of(),
			TransportAvailabilityFixture.of(), false, Set.of(), 0, true, ignored -> 0);
	}
}

package shortestpath.pathfinder.astar;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

import java.util.Map;
import org.junit.Test;
import shortestpath.WorldPointUtil;
import shortestpath.pathfinder.BankVisitState;
import shortestpath.pathfinder.CollisionMap;
import shortestpath.pathfinder.TransportAvailabilityFixture;
import shortestpath.transport.Transport;
import shortestpath.transport.TransportType;

public class MultiTargetTest
{
	private static final int T3_TARGET = RoutingStaticTestFixture.T3_TARGET;
	private static final int T3_B = RoutingStaticTestFixture.T3_B;
	private static final int T3_D = RoutingStaticTestFixture.T3_D;
	private static final int T3_F = RoutingStaticTestFixture.T3_F;
	private static final int SECOND_SYNTHETIC = WorldPointUtil.packWorldPoint(1005, 1000, 0);

	@Test
	public void overlayOrdersTargetsAndGivesEachSyntheticTargetItsOwnNode() throws Exception
	{
		SiteGraph graph = new SiteGraph(RoutingStaticTestFixture.createT3(), account());
		TargetOverlay overlay = new TargetOverlay(graph, t3Collision(),
			new int[] {T3_D, SECOND_SYNTHETIC, T3_TARGET, T3_B, T3_D});

		assertEquals(4, overlay.targetCount());
		assertEquals(2, overlay.syntheticCount());
		assertEquals(graph.nodeCount() + 2, overlay.queryNodeCount());
		for (int i = 1; i < overlay.targetCount(); i++)
			assertTrue(Integer.compareUnsigned(overlay.packedTarget(i - 1), overlay.packedTarget(i)) < 0);
		for (int i = 0; i < overlay.targetCount(); i++)
		{
			assertEquals(i, overlay.targetIndex(overlay.packedTarget(i)));
			assertEquals(overlay.packedTarget(i), overlay.nodeTile(overlay.targetNode(i)));
		}
		assertEquals(graph.nodeForTile(T3_B), overlay.targetNode(overlay.targetIndex(T3_B)));
		assertTrue(overlay.synthetic(overlay.targetIndex(T3_TARGET)));
		assertTrue(overlay.synthetic(overlay.targetIndex(SECOND_SYNTHETIC)));
		assertFalse(overlay.isTarget(T3_F));
	}

	@Test
	public void cliqueLabelsAreTheMinimumOverSingleTargets() throws Exception
	{
		RoutingStatic stat = RoutingStaticTestFixture.createT3();
		SiteGraph graph = new SiteGraph(stat, account(local(T3_B, T3_D, 7)));
		int[] targets = {T3_TARGET, T3_D, SECOND_SYNTHETIC};
		TargetOverlay multi = new TargetOverlay(graph, t3Collision(), targets);

		ReverseLabels labels = ReverseLabelsOracle.computeClique(multi);

		assertMinimumOverSingles(graph, t3Collision(), targets, labels, false);
		for (int i = 0; i < multi.targetCount(); i++)
		{
			assertEquals(0, labels.targetLabel(i, BankVisitState.CARRIED));
			assertEquals(0, labels.targetLabel(i, BankVisitState.BANKED));
		}
	}

	@Test
	public void sparseLabelsMatchCliqueAndSingleTargetsWithTwoTargets() throws Exception
	{
		RoutingStatic stat = SparseFixture.create();
		SiteGraph graph = new SiteGraph(stat, account());
		CollisionMap collision = SparseFixture.collision();
		int[] targets = {SparseFixture.TARGET, SparseFixture.C};
		TargetOverlay multi = new TargetOverlay(graph, collision, targets);

		ReverseLabels sparse = ReverseLabels.computeSparse(multi);

		assertArrayEquals(ReverseLabelsOracle.computeClique(multi).labels(), sparse.labels());
		assertMinimumOverSingles(graph, collision, targets, sparse, true);
	}

	@Test
	public void heuristicIsTheMinimumOverSingleTargets() throws Exception
	{
		RoutingStatic stat = SparseFixture.create();
		SiteGraph graph = new SiteGraph(stat, account());
		CollisionMap collision = SparseFixture.collision();
		int[] targets = {SparseFixture.TARGET, SparseFixture.C};
		PreparedTarget multi = PreparedTarget.prepare(graph, collision, targets);
		PreparedTarget first = PreparedTarget.prepare(graph, collision, targets[0]);
		PreparedTarget second = PreparedTarget.prepare(graph, collision, targets[1]);

		for (int packed : SparseFixture.PROBES)
		{
			for (BankVisitState banked : BankVisitState.values())
			{
				for (int[] components : new int[][] {{0}, {1}, {0, 1}})
				{
					int expected = Math.min(first.heuristic().estimateRaw(packed, banked, components),
						second.heuristic().estimateRaw(packed, banked, components));
					assertEquals(expected, multi.heuristic().estimateRaw(packed, banked, components));
					assertEquals(expected, multi.heuristic().estimate(packed, banked, components));
				}
			}
		}
	}

	@Test
	public void forwardSearchEndsAtTheCheapestTarget() throws Exception
	{
		RoutingStatic stat = RoutingStaticTestFixture.create();
		SiteGraph graph = new SiteGraph(stat, account(new Transport[] {
			local(RoutingStaticTestFixture.A, RoutingStaticTestFixture.C, 5),
			local(RoutingStaticTestFixture.A, RoutingStaticTestFixture.BANK, 1),
			local(RoutingStaticTestFixture.BANK, RoutingStaticTestFixture.D, 2)}));
		CollisionMap collision = emptyCollision();
		int[] targets = {RoutingStaticTestFixture.C, RoutingStaticTestFixture.D};

		AStarForwardSearch.Result multi = PreparedTarget.prepare(graph, collision, targets)
			.search(RoutingStaticTestFixture.A, () -> false, 1);

		assertTrue(multi.reached());
		assertEquals(3, multi.cost());
		assertEquals(RoutingStaticTestFixture.D, multi.path().get(multi.path().size() - 1).getPackedPosition());
		for (int target : targets)
		{
			AStarForwardSearch.Result single = PreparedTarget.prepare(graph, collision, target)
				.search(RoutingStaticTestFixture.A, () -> false, 1);
			assertTrue(single.cost() >= multi.cost());
		}
	}

	@Test
	public void unreachableTargetsDoNotHideAReachableOne() throws Exception
	{
		RoutingStatic stat = RoutingStaticTestFixture.create();
		SiteGraph graph = new SiteGraph(stat, account(local(RoutingStaticTestFixture.A, RoutingStaticTestFixture.C, 4)));
		int unreachable = WorldPointUtil.packWorldPoint(3000, 3000, 0);

		AStarForwardSearch.Result result = PreparedTarget.prepare(graph, emptyCollision(),
			new int[] {unreachable, RoutingStaticTestFixture.C}).search(RoutingStaticTestFixture.A, () -> false, 1);

		assertTrue(result.reached());
		assertEquals(4, result.cost());
	}

	@Test
	public void sessionCachesTargetSetsRegardlessOfOrder() throws Exception
	{
		AStarRoutingSession session = new AStarRoutingSession();
		CollisionMap collision = emptyCollision();
		SiteGraph graph = session.graph(RoutingStaticTestFixture.create(), account()).value();
		int a = RoutingStaticTestFixture.C, b = RoutingStaticTestFixture.D;

		AStarRoutingSession.Lookup<PreparedTarget> first = session.target(graph, collision, new int[] {a, b});
		AStarRoutingSession.Lookup<PreparedTarget> reordered = session.target(graph, collision, new int[] {b, a, b});

		assertFalse(first.reused());
		assertTrue(reordered.reused());
		assertSame(first.value(), reordered.value());
		assertFalse(session.target(graph, collision, a).reused());
	}

	private static void assertMinimumOverSingles(SiteGraph graph, CollisionMap collision, int[] targets,
		ReverseLabels multi, boolean sparse)
	{
		for (int state = 0; state < graph.stateCount(); state++)
		{
			int expected = CostArithmetic.INF;
			for (int target : targets)
			{
				TargetOverlay single = new TargetOverlay(graph, collision, target);
				ReverseLabels labels = sparse ? ReverseLabels.computeSparse(single) : ReverseLabelsOracle.computeClique(single);
				expected = Math.min(expected, labels.labels()[state]);
			}
			assertEquals("state " + state, expected, multi.labels()[state]);
		}
	}

	private static CollisionMap t3Collision()
	{
		return neighbours(Map.of(
			T3_TARGET, new int[] {RoutingStaticTestFixture.T3_SEARCH_0, RoutingStaticTestFixture.T3_SEARCH_1},
			SECOND_SYNTHETIC, new int[] {RoutingStaticTestFixture.T3_SEARCH_0}));
	}

	private static CollisionMap neighbours(Map<Integer, int[]> neighbours)
	{
		return new CollisionMap(null)
		{
			@Override public int[] ordinaryWalkingNeighbors(int packedPoint)
			{
				int[] result = neighbours.get(packedPoint);
				return result == null ? new int[0] : result.clone();
			}
			@Override public boolean isBlocked(int x, int y, int z)
			{
				return false;
			}
		};
	}

	private static CollisionMap emptyCollision()
	{
		return neighbours(Map.of());
	}

	private static PreparedRoutingAccount account(Transport... local)
	{
		return PreparedRoutingAccount.compile(TransportAvailabilityFixture.of(local),
			TransportAvailabilityFixture.of(), false, java.util.Set.of(), 0, true, ignored -> 0);
	}

	private static Transport local(int origin, int destination, int duration)
	{
		return new Transport.TransportBuilder().origin(origin).destination(destination)
			.type(TransportType.TRANSPORT).duration(duration).build();
	}

	/** The sparse-network world from {@link SparseManhattanTest}. */
	private static final class SparseFixture
	{
		static final int A = WorldPointUtil.packWorldPoint(1000, 1000, 0);
		static final int B = WorldPointUtil.packWorldPoint(1003, 1000, 0);
		static final int C = WorldPointUtil.packWorldPoint(1003, 1004, 0);
		static final int OTHER_PLANE = WorldPointUtil.packWorldPoint(1000, 1000, 1);
		static final int TARGET = WorldPointUtil.packWorldPoint(1001, 1001, 0);
		static final int[] PROBES = {A, B, C, TARGET, OTHER_PLANE, WorldPointUtil.packWorldPoint(1002, 1002, 0)};

		static RoutingStatic create() throws Exception
		{
			return RoutingStatic.takeOwnership(new int[] {A, OTHER_PLANE}, RoutingStaticTestFixture.components(0, 1), new byte[] {0, 0},
				new char[2], new char[2], new int[] {A, B, C, OTHER_PLANE},
				new int[] {0, 1, 2, 3, 4}, new int[] {0, 0, 0, 1}, 2, new int[] {0, 3, 4},
				new int[] {0, 1, 2, 3}, new int[0], new int[0], new int[0], new int[0], 4, 5, 1, 3, 6,
				new int[] {0, 1, 2, 3, 3, 6}, new int[] {4, 4, 4, 0, 1, 2}, new int[] {6, 0, 8, 6, 0, 8});
		}

		static CollisionMap collision()
		{
			return neighbours(Map.of(TARGET, new int[] {A, OTHER_PLANE}));
		}
	}
}

package shortestpath.pathfinder.astar;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;

import java.lang.reflect.Field;
import org.junit.Test;

public class PagedSearchArrayTest
{
	@Test
	public void readsDoNotAllocateAndWritesAllocateOnlyTheirPage() throws Exception
	{
		for (int defaultValue : new int[] {0, CostArithmetic.INF})
		{
			PagedSearchArray array = new PagedSearchArray(2049, defaultValue);
			Field field = PagedSearchArray.class.getDeclaredField("pages");
			field.setAccessible(true);
			int[][] pages = (int[][]) field.get(array);
			assertEquals(3, pages.length);
			for (int index : new int[] {0, 1023, 1024, 2047, 2048})
				assertEquals(defaultValue, array.get(index));
			for (int[] page : pages) assertNull(page);

			array.set(1024, 7);
			assertNull(pages[0]);
			assertNull(pages[2]);
			int[] writtenPage = pages[1];
			assertEquals(1024, writtenPage.length);
			assertEquals(defaultValue, array.get(1025));
			array.set(1024, 3);
			array.set(2047, 0);
			assertSame(writtenPage, pages[1]);
			assertEquals(3, array.get(1024));
			assertEquals(0, array.get(2047));

			array.set(1023, 11);
			array.set(2048, 19);
			assertEquals(11, array.get(1023));
			assertEquals(19, array.get(2048));
			assertEquals(defaultValue, array.get(0));
			assertEquals(defaultValue, new PagedSearchArray(2049, defaultValue).get(1024));
		}
	}
}

package shortestpath.pathfinder.astar;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

import java.util.Set;
import org.junit.Before;
import org.junit.Test;
import shortestpath.WorldPointUtil;
import shortestpath.pathfinder.BankVisitState;
import shortestpath.pathfinder.TransportAvailability;
import shortestpath.pathfinder.TransportAvailabilityFixture;
import shortestpath.transport.Transport;
import shortestpath.transport.TransportType;

public class PreparedRoutingAccountTest
{
	private RoutingStatic stat;
	private int penalty;

	@Before public void setUp() throws Exception
	{
		stat = RoutingStaticTestFixture.create();
		penalty = 4;
	}

	@Test
	public void localTransportsAreOrderedUnsignedAcrossPlanes()
	{
		int[] origins = {
			WorldPointUtil.packWorldPoint(3200, 3200, 3),
			WorldPointUtil.packWorldPoint(3200, 3200, 0),
			WorldPointUtil.packWorldPoint(3201, 3200, 2),
			WorldPointUtil.packWorldPoint(3200, 3201, 1),
		};
		Transport[] transports = new Transport[origins.length];
		for (int i = 0; i < origins.length; i++)
			transports[i] = new Transport.TransportBuilder().origin(origins[i]).destination(origins[i] + 1)
				.type(TransportType.TRANSPORT).duration(1).build();
		TransportAvailability availability = TransportAvailabilityFixture.of(transports);

		PreparedRoutingAccount account = PreparedRoutingAccount.compile(availability, availability, false, java.util.Set.of(), 0, true,
			ignored -> 0);

		PreparedRoutingAccount.View view = account.localView(BankVisitState.CARRIED);
		assertEquals(origins.length, view.destinations.length);
		for (int i = 1; i < view.destinations.length; i++)
			assertTrue(Integer.compareUnsigned(view.origins[i - 1], view.origins[i]) <= 0);
	}

	@Test
	public void compilesSixViewsAndStableSnapshot()
	{
		Transport carriedLocal = local(RoutingStaticTestFixture.A, RoutingStaticTestFixture.BANK, 2);
		Transport sharedLocal = local(RoutingStaticTestFixture.C, RoutingStaticTestFixture.D, 1);
		Transport bankedLocal = local(RoutingStaticTestFixture.BANK, RoutingStaticTestFixture.C, 3);
		Transport wilderness = global(RoutingStaticTestFixture.D, 2, 30);
		Transport ordinary = global(RoutingStaticTestFixture.D, 5, 29);

		PreparedRoutingAccount first =
			PreparedRoutingAccount.compile(availability(carriedLocal, sharedLocal, wilderness, ordinary),
				availability(bankedLocal, sharedLocal, wilderness, ordinary), true, Set.of(RoutingStaticTestFixture.BANK), 0, true, ignored -> penalty);
		PreparedRoutingAccount second =
			PreparedRoutingAccount.compile(availability(ordinary, wilderness, sharedLocal, carriedLocal),
				availability(ordinary, wilderness, sharedLocal, bankedLocal), true, Set.of(RoutingStaticTestFixture.BANK), 0, true, ignored -> penalty);

		assertEquals(2, first.localView(BankVisitState.CARRIED).destinations.length);
		assertEquals(2, first.localView(BankVisitState.BANKED).destinations.length);
		assertEquals(2, first.globalCount(BankVisitState.CARRIED));
		assertEquals(2, first.globalCount(BankVisitState.BANKED));
		assertEquals(1, first.globalCount(TeleportCapability.OVER_20, BankVisitState.CARRIED));
		assertEquals(1, first.globalCount(TeleportCapability.OVER_20, BankVisitState.BANKED));
		assertEquals(6, first.localView(BankVisitState.CARRIED).costs[0]);
		assertEquals(7, first.localView(BankVisitState.BANKED).costs[0]);
		assertEquals(6, first.globalCost(TeleportCapability.OVER_20, BankVisitState.BANKED, 0));
		assertEquals(first.fingerprint(), second.fingerprint());

		// The prepared arrays are query-local; later mutation of a source transport cannot alter them.
		carriedLocal.setDestination(RoutingStaticTestFixture.D);
		assertEquals(RoutingStaticTestFixture.BANK, first.localView(BankVisitState.CARRIED).destinations[0]);
	}

	@Test
	public void classifiesWildernessAtTheDeepWildernessThreshold()
	{
		PreparedRoutingAccount account = PreparedRoutingAccount.compile(
			availability(global(RoutingStaticTestFixture.C, 1, 29), global(RoutingStaticTestFixture.D, 1, 30)),
			availability(), false, Set.of(), 0, true, ignored -> 0);
		assertEquals(2, account.globalCount(BankVisitState.CARRIED));
		assertEquals(1, account.globalCount(TeleportCapability.OVER_20, BankVisitState.CARRIED));
		assertEquals(30, account.globalView(TeleportCapability.OVER_20, BankVisitState.CARRIED).maxWilderness[0]);
	}

	@Test
	public void rejectsMissingEndpointAndSaturatesOverflow()
	{
		try
		{
			new SiteGraph(stat,
				PreparedRoutingAccount.compile(availability(local(RoutingStaticTestFixture.A, 12345, 1)),
					availability(), false, Set.of(), 0, true, ignored -> 0));
			fail("missing endpoint must fail");
		}
		catch (IllegalStateException expected)
		{
		}

		PreparedRoutingAccount overflow = PreparedRoutingAccount.compile(
			availability(local(RoutingStaticTestFixture.A, RoutingStaticTestFixture.BANK, Integer.MAX_VALUE)),
			availability(), false, Set.of(), 0, true, ignored -> 1);
		assertEquals(CostArithmetic.INF, overflow.localView(BankVisitState.CARRIED).costs[0]);
		try
		{
			PreparedRoutingAccount.compile(
				availability(local(RoutingStaticTestFixture.A, RoutingStaticTestFixture.BANK, 1)), availability(),
				false, Set.of(), 0, true, ignored -> - 1);
			fail("negative cost must fail");
		}
		catch (IllegalArgumentException expected)
		{
		}
	}

	private static TransportAvailability availability(Transport... transports)
	{
		return TransportAvailabilityFixture.of(transports);
	}

	private static Transport local(int origin, int destination, int duration)
	{
		return new Transport.TransportBuilder()
			.origin(origin)
			.destination(destination)
			.type(TransportType.TRANSPORT)
			.duration(duration)
			.build();
	}

	private static Transport global(int destination, int duration, int wilderness)
	{
		return new Transport.TransportBuilder()
			.destination(destination)
			.type(TransportType.TELEPORTATION_ITEM)
			.duration(duration)
			.maxWildernessLevel(wilderness)
			.build();
	}
}

package shortestpath.pathfinder.astar;

import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;
import shortestpath.WorldPointUtil;
import shortestpath.pathfinder.BankVisitState;

/**
 * Reverse labels for tests: the transparent component-clique reference the sparse production labels
 * are checked against.
 */
public final class ReverseLabelsOracle
{
	private ReverseLabelsOracle()
	{
	}

	/** The labels production computes; every static, hand-built or derived, carries a sparse network. */
	public static ReverseLabels compute(TargetOverlay overlay)
	{
		return ReverseLabels.computeSparse(overlay);
	}

	/**
	 * Transparent component-clique correctness oracle: every pair of a component's sites walks at
	 * Chebyshev distance, or at the full {@link ExactWalks#pairDistances} table's distance in a
	 * component the network joins by exact walks.
	 */
	public static ReverseLabels computeClique(TargetOverlay overlay)
	{
		long started = System.nanoTime();
		SiteGraph graph = overlay.graph();
		RoutingStatic stat = overlay.routingStatic();
		int spatialCount = graph.spatialNodeCount();
		int[] labels = new int[overlay.queryNodeCount() * 2];
		Arrays.fill(labels, CostArithmetic.INF);
		AStarMinHeap queue = new AStarMinHeap(Math.max(16, labels.length));
		ExactWalks exactWalks = stat.exactWalks();
		Map<Integer, int[][]> pairTables = new HashMap<>();
		int pushes = 0;
		for (int target = 0; target < overlay.targetCount(); target++)
		{
			for (BankVisitState banked : BankVisitState.values())
			{
				if (!overlay.isTerminal(target, banked)) continue;
				int seed = overlay.targetState(target, banked);
				labels[seed] = 0;
				queue.push(0, 0, seed);
				pushes++;
			}
		}
		int settled = 0, stale = 0;
		while (queue.poll())
		{
			int state = queue.state(), cost = queue.cost();
			if (cost != labels[state])
			{
				stale++;
				continue;
			}
			settled++;
			int node = state / 2;
			BankVisitState banked = (state & 1) != 0 ? BankVisitState.BANKED : BankVisitState.CARRIED;
			if (node < graph.nodeCount())
			{
				for (int edge = graph.reverseEdgeStart(state); edge < graph.reverseEdgeEnd(state); edge++)
				{
					if (relax(labels, queue, graph.reverseFromState(edge),
						CostArithmetic.add(cost, graph.reverseCost(edge))))
						pushes++;
				}
			}
			if (node < spatialCount)
			{
				for (int component : stat.siteComponents(node))
				{
					int[] sites = stat.componentSites(component);
					boolean exact = exactWalks != null && exactWalks.isExact(component);
					int[][] pairs = exact ? pairTables.computeIfAbsent(component,
						c -> ExactWalks.pairDistances(stat, c)) : null;
					int self = exact ? Arrays.binarySearch(sites, node) : -1;
					for (int i = 0; i < sites.length; i++)
					{
						int other = sites[i];
						// Relaxing `other` from this site is the walk other -> node.
						int walk = exact ? pairs[i][self] : distance(stat.siteTile(node), stat.siteTile(other));
						if (other != node && relax(labels, queue, SiteGraph.stateId(other, banked),
							CostArithmetic.add(cost, walk)))
							pushes++;
					}
				}
				// Synthetic targets only emit reverse attachments; non-terminal tile estimates
				// also consult the component's finite site labels in PreparedHeuristic.
			}
			else
			{
				int target = overlay.syntheticTarget(node);
				for (int i = 0; target >= 0 && i < overlay.attachmentCount(target); i++)
				{
					if (relax(labels, queue, SiteGraph.stateId(overlay.attachmentSite(target, i), banked),
						CostArithmetic.add(cost, overlay.attachmentCost(target, i))))
						pushes++;
				}
			}
		}
		return new ReverseLabels(overlay, labels, null, null, settled, stale, pushes, 0, 0, 0,
			System.nanoTime() - started);
	}

	private static boolean relax(int[] labels, AStarMinHeap queue, int state, int candidate)
	{
		if (candidate == CostArithmetic.INF || candidate >= labels[state])
			return false;
		labels[state] = candidate;
		queue.push(candidate, candidate, state);
		return true;
	}

	private static int distance(int left, int right)
	{
		return WorldPointUtil.distanceBetween(left, right);
	}
}

package shortestpath.pathfinder.astar;

import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

import java.io.IOException;
import java.io.InputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.Arrays;
import org.junit.Assume;
import org.junit.Test;
import shortestpath.pathfinder.CollisionMap;
import shortestpath.pathfinder.SplitFlagMap;

/**
 * Guards {@code routing-components.bin}: it is derived data, so it must equal what the committed
 * collision map and routing cuts generate. When the map or the cuts change, regenerate it:
 *
 * <pre>ROUTING_COMPONENTS_REGEN=1 ./gradlew -p shortest-path test --tests '*RoutingComponentsFreshnessTest' --rerun</pre>
 *
 * Only the values {@code 1} and {@code true} opt in; any other value is ignored with a stderr
 * note and the file is compared normally. While regenerating nothing is compared, so the test is
 * reported as skipped rather than passed. The write goes to the source tree (the Gradle test working
 * directory is the {@code shortest-path} project directory); a clean re-run then compares.
 */
public class RoutingComponentsFreshnessTest
{
	private static final String REGEN_VARIABLE = "ROUTING_COMPONENTS_REGEN";
	private static final Path COMMITTED = Paths.get("src", "main", "resources", "routing-components.bin");

	@Test
	public void committedLayerMatchesTheCollisionMapAndCuts() throws IOException
	{
		RoutingCuts cuts = RoutingCuts.loadFromResources();
		assertTrue("routing-cuts.bin missing or empty: the freshness check would be vacuous", cuts.cutCount() > 0);

		CollisionMap collision = new CollisionMap(SplitFlagMap.fromResources());
		byte[] expected = ComponentLayerWriter.write(RoutingStaticBuilder.generate(collision, cuts.pairs()));

		if (regenRequested())
		{
			Files.createDirectories(COMMITTED.toAbsolutePath().getParent());
			Files.write(COMMITTED, expected);
			System.err.println(REGEN_VARIABLE + " active - rewrote " + COMMITTED + " (" + expected.length
				+ " bytes), nothing was compared");
			Assume.assumeTrue(REGEN_VARIABLE + " is set, so the layer was rewritten instead of checked", false);
			return;
		}

		byte[] committed;
		try (InputStream stream = ComponentLayer.class.getResourceAsStream(ComponentLayer.RESOURCE))
		{
			if (stream == null) fail("routing-components.bin is missing; " + regenerationHint());
			committed = stream.readAllBytes();
		}
		if (!Arrays.equals(expected, committed))
		{
			fail("routing-components.bin is stale for the committed collision-map.zip and routing-cuts.bin ("
				+ committed.length + " bytes committed, " + expected.length + " bytes generated); " + regenerationHint());
		}
	}

	@Test
	public void committedLayerReadsStrictly() throws IOException
	{
		try (InputStream stream = ComponentLayer.class.getResourceAsStream(ComponentLayer.RESOURCE))
		{
			ComponentLayer layer = ComponentLayer.read(stream);
			assertTrue(layer.starts.length > 0);
			assertTrue("the layer has no crossings", layer.crossings.length > 0);
		}
	}

	private static String regenerationHint()
	{
		return "regenerate it with " + REGEN_VARIABLE + "=1 ./gradlew test --tests '*RoutingComponentsFreshnessTest'"
			+ " --rerun (or the tooling repository's routingComponents task)";
	}

	private static boolean regenRequested()
	{
		String value = System.getenv(REGEN_VARIABLE);
		if (value == null) return false;
		if ("1".equals(value) || "true".equalsIgnoreCase(value)) return true;
		System.err.println(REGEN_VARIABLE + "=" + value + " ignored - regeneration requires " + REGEN_VARIABLE
			+ "=1; comparing against the committed layer normally");
		return false;
	}
}

package shortestpath.pathfinder.astar;

import java.io.*;
import java.nio.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import lombok.*;
import lombok.experimental.Accessors;

/**
 * Separator cut edges for the A* backend, stored as {@code routing-cuts.bin}.
 *
 * <p>The cuts are generated offline with KaHIP by the tooling repository and committed in
 * {@code src/test/resources} as an offline input of the routing-component generator. They only
 * affect performance: {@link RoutingStaticBuilder} ignores cuts that are no longer walking edges or
 * no longer separate anything, so stale cuts never make routes wrong.
 *
 * <p>Format, all little-endian:
 * <pre>
 * 8 bytes  ASCII "RSPCUTS\0"
 * u32      format version, exactly 1
 * u64      FNV-1a 64 of the collision-map.zip bytes the cuts were generated from (informational)
 * i32 x 5  maximum component size, minimum child size, maximum separator size, imbalance, seed
 * u8 + n   KaHIP preconfiguration name, ASCII
 * u32      cut count
 * u32 x 2n cut pairs (from, to): from &lt; to (unsigned), pairs strictly ascending
 * </pre>
 * The reader rejects a wrong header, truncation, unsorted or duplicate pairs, and trailing bytes.
 */
public final class RoutingCuts
{
	public static final String RESOURCE = "/routing-cuts.bin";
	private static final byte[] MAGIC = "RSPCUTS\0".getBytes(StandardCharsets.US_ASCII);
	private static final int FORMAT_VERSION = 1;
	private static final long FNV_OFFSET = 0xcbf29ce484222325L;
	private static final long FNV_PRIME = 0x100000001b3L;

	@Getter @Accessors(fluent = true) private final long collisionFingerprint;
	@Getter @Accessors(fluent = true) private final Parameters parameters;
	private final int[] pairs;

	/** The KaHIP partitioning parameters the cuts were generated with. */
	@EqualsAndHashCode
	public static final class Parameters
	{
		public final int maximumComponentSize;
		public final int minimumChildSize;
		public final int maximumSeparatorSize;
		public final int imbalance;
		public final int seed;
		public final String preconfiguration;

		public Parameters(int maximumComponentSize, int minimumChildSize, int maximumSeparatorSize, int imbalance,
			int seed, String preconfiguration)
		{
			this.maximumComponentSize = maximumComponentSize;
			this.minimumChildSize = minimumChildSize;
			this.maximumSeparatorSize = maximumSeparatorSize;
			this.imbalance = imbalance;
			this.seed = seed;
			this.preconfiguration = Objects.requireNonNull(preconfiguration, "preconfiguration");
			if (preconfiguration.length() > 255 || !StandardCharsets.US_ASCII.newEncoder().canEncode(preconfiguration))
				throw new IllegalArgumentException("preconfiguration must be ASCII and at most 255 characters");
		}

		@Override
		public String toString()
		{
			return maximumComponentSize + " " + minimumChildSize + " " + maximumSeparatorSize + " " + imbalance
				+ " " + seed + " " + preconfiguration;
		}
	}

	/**
	 * @param pairs cut edges as packed {@code (from, to)} tile pairs; they are canonicalised
	 *              ({@code from < to}), sorted and de-duplicated
	 */
	public RoutingCuts(long collisionFingerprint, Parameters parameters, int[] pairs)
	{
		if (pairs.length % 2 != 0) throw new IllegalArgumentException("cut pairs must have even length");
		this.collisionFingerprint = collisionFingerprint;
		this.parameters = Objects.requireNonNull(parameters, "parameters");
		this.pairs = canonicalise(pairs);
	}

	private RoutingCuts(long collisionFingerprint, Parameters parameters, int[] pairs, boolean trusted)
	{
		this.collisionFingerprint = collisionFingerprint;
		this.parameters = parameters;
		this.pairs = pairs;
	}





	public int cutCount()
	{
		return pairs.length / 2;
	}

	/** Cut edges as a flat array: {@code [2*i]} is the lower tile, {@code [2*i+1]} the higher. */
	public int[] pairs()
	{
		return pairs.clone();
	}

	/** No cuts at all: the generated layer has no separators and no crossings. */
	public static RoutingCuts empty()
	{
		return new RoutingCuts(0, new Parameters(0, 0, 0, 0, 0, ""), new int[0]);
	}

	/**
	 * Loads the packaged {@code routing-cuts.bin}, or an empty index when the jar does not
	 * contain it. Missing cuts are not harmless for the generator: the layer it writes then has
	 * no crossings, which {@code RoutingComponentsFreshnessTest} rejects. A corrupt resource
	 * fails loudly, since that indicates a broken build rather than an optional one.
	 */
	public static RoutingCuts loadFromResources()
	{
		try (InputStream stream = RoutingCuts.class.getResourceAsStream(RESOURCE))
		{
			if (stream == null) return empty();
			return read(stream.readAllBytes());
		}
		catch (IOException error)
		{
			throw new IllegalStateException("cannot load " + RESOURCE + ": " + error.getMessage(), error);
		}
	}

	public static RoutingCuts read(byte[] bytes) throws IOException
	{
		ByteBuffer input = ByteBuffer.wrap(bytes).order(ByteOrder.LITTLE_ENDIAN);
		byte[] magic = new byte[MAGIC.length];
		require(input, magic.length, "magic");
		input.get(magic);
		if (!Arrays.equals(magic, MAGIC)) throw new IOException("routing-cuts wrong magic");
		require(input, 4 + 8 + 5 * 4 + 1, "header");
		int version = input.getInt();
		if (version != FORMAT_VERSION) throw new IOException("unsupported routing-cuts version " + version);
		long fingerprint = input.getLong();
		int maximumComponentSize = input.getInt();
		int minimumChildSize = input.getInt();
		int maximumSeparatorSize = input.getInt();
		int imbalance = input.getInt();
		int seed = input.getInt();
		int nameLength = Byte.toUnsignedInt(input.get());
		require(input, nameLength, "preconfiguration");
		byte[] name = new byte[nameLength];
		input.get(name);
		for (byte value : name)
			if (value < 0x20 || value > 0x7e) throw new IOException("routing-cuts preconfiguration is not ASCII");
		require(input, 4, "cut count");
		long count = Integer.toUnsignedLong(input.getInt());
		if (count * 8 != input.remaining())
			throw new IOException(count * 8 > input.remaining() ? "truncated routing-cuts pairs"
				: "routing-cuts has trailing bytes");
		int[] pairs = new int[(int) count * 2];
		for (int i = 0; i < pairs.length; i += 2)
		{
			pairs[i] = input.getInt();
			pairs[i + 1] = input.getInt();
			if (Integer.compareUnsigned(pairs[i], pairs[i + 1]) >= 0)
				throw new IOException("routing-cuts pair " + i / 2 + " is not canonical");
			if (i > 0 && comparePairs(pairs, i - 2, i) >= 0)
				throw new IOException("routing-cuts pairs are not strictly ascending at " + i / 2);
		}
		return new RoutingCuts(fingerprint, new Parameters(maximumComponentSize, minimumChildSize,
			maximumSeparatorSize, imbalance, seed, new String(name, StandardCharsets.US_ASCII)), pairs, true);
	}

	public byte[] write()
	{
		byte[] name = parameters.preconfiguration.getBytes(StandardCharsets.US_ASCII);
		ByteBuffer output = ByteBuffer.allocate(MAGIC.length + 4 + 8 + 5 * 4 + 1 + name.length + 4 + pairs.length * 4)
			.order(ByteOrder.LITTLE_ENDIAN);
		output.put(MAGIC);
		output.putInt(FORMAT_VERSION);
		output.putLong(collisionFingerprint);
		output.putInt(parameters.maximumComponentSize);
		output.putInt(parameters.minimumChildSize);
		output.putInt(parameters.maximumSeparatorSize);
		output.putInt(parameters.imbalance);
		output.putInt(parameters.seed);
		output.put((byte) name.length);
		output.put(name);
		output.putInt(pairs.length / 2);
		for (int value : pairs)
			output.putInt(value);
		return output.array();
	}

	/** FNV-1a 64 over raw bytes; used to identify the collision map a cut file was generated from. */
	public static long fingerprint(byte[] bytes)
	{
		long hash = FNV_OFFSET;
		for (byte value : bytes)
			hash = (hash ^ (value & 0xffL)) * FNV_PRIME;
		return hash;
	}

	private static void require(ByteBuffer input, int bytes, String label) throws IOException
	{
		if (input.remaining() < bytes) throw new IOException("truncated routing-cuts " + label);
	}

	private static int[] canonicalise(int[] raw)
	{
		long[] keys = new long[raw.length / 2];
		for (int i = 0; i < keys.length; i++)
		{
			int a = raw[2 * i], b = raw[2 * i + 1];
			if (a == b) throw new IllegalArgumentException("cut is a self edge");
			int low = Integer.compareUnsigned(a, b) < 0 ? a : b;
			int high = low == a ? b : a;
			keys[i] = (Integer.toUnsignedLong(low) << 32) | Integer.toUnsignedLong(high);
		}
		long[] unique = Arrays.stream(keys).sorted().distinct().toArray();
		int[] result = new int[unique.length * 2];
		for (int i = 0; i < unique.length; i++)
		{
			result[2 * i] = (int) (unique[i] >>> 32);
			result[2 * i + 1] = (int) unique[i];
		}
		return result;
	}

	private static int comparePairs(int[] pairs, int left, int right)
	{
		int compare = Integer.compareUnsigned(pairs[left], pairs[right]);
		return compare != 0 ? compare : Integer.compareUnsigned(pairs[left + 1], pairs[right + 1]);
	}
}

package shortestpath.pathfinder.astar;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

import java.io.IOException;
import java.util.Arrays;
import org.junit.Test;

public class RoutingCutsTest
{
	private static final RoutingCuts.Parameters PARAMETERS =
		new RoutingCuts.Parameters(20000, 500, 32, 40, 42, "strong");

	@Test
	public void roundTripsAndCanonicalisesPairs() throws IOException
	{
		// Reversed, unsorted and duplicated pairs are normalised; high-bit tiles sort unsigned.
		int high = 0x80000001;
		RoutingCuts cuts = new RoutingCuts(0x1234L, PARAMETERS, new int[] {5, 3, high, 1, 3, 5, 2, 4});

		assertArrayEquals(new int[] {1, high, 2, 4, 3, 5}, cuts.pairs());
		RoutingCuts read = RoutingCuts.read(cuts.write());
		assertArrayEquals(cuts.pairs(), read.pairs());
		assertEquals(0x1234L, read.collisionFingerprint());
		assertEquals(PARAMETERS, read.parameters());
		assertArrayEquals(cuts.write(), read.write());
	}

	@Test
	public void parametersEqualityCoversEveryField()
	{
		assertEquals(PARAMETERS, new RoutingCuts.Parameters(20000, 500, 32, 40, 42, "strong"));
		assertEquals(PARAMETERS.hashCode(),
			new RoutingCuts.Parameters(20000, 500, 32, 40, 42, "strong").hashCode());

		// Each field is load-bearing: a single-field mutation is not equal.
		assertNotEquals(PARAMETERS, new RoutingCuts.Parameters(20001, 500, 32, 40, 42, "strong"));
		assertNotEquals(PARAMETERS, new RoutingCuts.Parameters(20000, 501, 32, 40, 42, "strong"));
		assertNotEquals(PARAMETERS, new RoutingCuts.Parameters(20000, 500, 33, 40, 42, "strong"));
		assertNotEquals(PARAMETERS, new RoutingCuts.Parameters(20000, 500, 32, 41, 42, "strong"));
		assertNotEquals(PARAMETERS, new RoutingCuts.Parameters(20000, 500, 32, 40, 43, "strong"));
		assertNotEquals(PARAMETERS, new RoutingCuts.Parameters(20000, 500, 32, 40, 42, "fast"));
	}

	@Test
	public void rejectsMalformedFiles()
	{
		byte[] valid = new RoutingCuts(7L, PARAMETERS, new int[] {1, 2, 3, 4}).write();

		byte[] badMagic = valid.clone();
		badMagic[0] = 'X';
		assertRejected(badMagic, "magic");

		byte[] badVersion = valid.clone();
		badVersion[8] = 2;
		assertRejected(badVersion, "version");

		assertRejected(Arrays.copyOf(valid, valid.length - 1), "truncated");
		assertRejected(Arrays.copyOf(valid, valid.length + 4), "trailing");

		byte[] unsorted = valid.clone();
		int pairs = valid.length - 16;
		System.arraycopy(valid, pairs + 8, unsorted, pairs, 8);
		System.arraycopy(valid, pairs, unsorted, pairs + 8, 8);
		assertRejected(unsorted, "ascending");

		byte[] reversed = valid.clone();
		System.arraycopy(valid, pairs + 4, reversed, pairs, 4);
		System.arraycopy(valid, pairs, reversed, pairs + 4, 4);
		assertRejected(reversed, "canonical");
	}

	@Test
	public void packagedCutsParse()
	{
		RoutingCuts cuts = RoutingCuts.loadFromResources();
		assertTrue(cuts.cutCount() > 0);
	}

	@Test
	public void missingResourceYieldsAnEmptyIndex()
	{
		// The resource is on the test classpath, so exercise the empty form directly:
		// loadFromResources returns it when the stream is null.
		RoutingCuts cuts = RoutingCuts.empty();
		assertEquals(0, cuts.cutCount());
		assertEquals(0, cuts.pairs().length);
	}

	private static void assertRejected(byte[] bytes, String reason)
	{
		try
		{
			RoutingCuts.read(bytes);
			fail("expected rejection: " + reason);
		}
		catch (IOException expected)
		{
			assertTrue(expected.getMessage(), expected.getMessage().contains(reason));
		}
	}
}

package shortestpath.pathfinder.astar;

import java.io.IOException;
import java.util.*;
import lombok.*;
import lombok.experimental.Accessors;
import shortestpath.*;
import shortestpath.pathfinder.*;
import shortestpath.transport.*;

/**
 * Generates the routing component layer ({@link ComponentLayer}) offline and composes it with
 * {@link RoutingStaticLoader}, so tests and tooling derive a {@link RoutingStatic} exactly the way
 * the plugin does from the bundled layer.
 *
 * <p>The layer is derived from the {@link CollisionMap} and the separator cut edges:
 * <ol>
 *   <li>Every walkable tile is enumerated in ascending unsigned packed order.</li>
 *   <li>Cuts that are no longer walking edges are ignored and duplicates dropped.</li>
 *   <li>Routing components: a flood fill over ordinary walking edges that does not cross a valid
 *       cut. Cuts that no longer separate two routing components are dropped; the rest become
 *       crossings. Cuts therefore only affect performance, never routes.</li>
 *   <li>The component ids are stored as runs of consecutive tiles, with the crossings.</li>
 * </ol>
 *
 * <p>{@link #build(CollisionMap, Map, Set, int[], int)} then hands that layer, the raw
 * (account-independent) transports of every {@link TransportType}, and the bank list to
 * {@link RoutingStaticLoader}.
 */
public final class RoutingStaticBuilder
{
	private static final int REGION_SIZE = 64;

	private RoutingStaticBuilder()
	{
	}

	/** Derivation counts of one build, for the cut report and the tests. */
	@AllArgsConstructor(access = AccessLevel.PACKAGE)
	public static final class Diagnostics
	{
		public final long totalNanos;

		/** Every walkable tile of the collision map. */
		public final int walkableTileCount;
		public final int naturalComponentCount;
		public final int routingComponentCount;
		/** The most search tiles in one routing component. */
		public final int largestRoutingComponentSize;
		public final int reachableNaturalComponentCount;

		public final int inputCutCount;
		public final int duplicateCutCount;
		public final int invalidCutCount;
		public final int nonSeparatingCutCount;
		public final int crossingCount;

		public final int searchTileCount;
		public final int siteCount;
		/** Components whose sites the network joins by exact walks. */
		public final int exactComponentCount;

		@Override
		public String toString()
		{
			return "RoutingStaticBuilder.Diagnostics{"
				+ "totalMs=" + (totalNanos / 1_000_000)
				+ ", walkableTileCount=" + walkableTileCount + ", naturalComponentCount=" + naturalComponentCount
				+ ", routingComponentCount=" + routingComponentCount
				+ ", largestRoutingComponentSize=" + largestRoutingComponentSize
				+ ", reachableNaturalComponentCount=" + reachableNaturalComponentCount
				+ ", inputCutCount=" + inputCutCount + ", duplicateCutCount=" + duplicateCutCount
				+ ", invalidCutCount=" + invalidCutCount + ", nonSeparatingCutCount=" + nonSeparatingCutCount
				+ ", crossingCount=" + crossingCount + ", searchTileCount=" + searchTileCount
				+ ", siteCount=" + siteCount + ", exactComponentCount=" + exactComponentCount + "}";
		}
	}

	/** The derived static world plus the diagnostics collected while building it. */
	@AllArgsConstructor(access = AccessLevel.PACKAGE)
	public static final class Result
	{
		public final RoutingStatic routingStatic;
		public final Diagnostics diagnostics;
	}

	/**
	 * Builds the derived {@link RoutingStatic}: generates the layer from the collision map and the
	 * cuts, then loads it with {@link RoutingStaticLoader}.
	 *
	 * @param collision      authoritative walking-neighbour source.
	 * @param rawTransports  the plugin's raw, unfiltered, account-independent transports, keyed by
	 *                       packed origin tile or {@link shortestpath.WorldPointUtil#UNDEFINED} for
	 *                       origin-less (global) transports/teleports &mdash;
	 *                       {@code ResourceLoader.transports()}'s direct result. Must
	 *                       include every {@link TransportType}, seasonal included.
	 * @param bankTiles      the whole bank destination set (the destination TSVs' "bank" column),
	 *                       with no account filtering.
	 * @param cuts           candidate separator cut edges as packed {@code (from, to)} pairs:
	 *                       {@code cuts[2*i]}/{@code cuts[2*i+1]}.
	 */
	public static Result build(CollisionMap collision, Map<Integer, Set<Transport>> rawTransports,
		Set<Integer> bankTiles, int[] cuts) throws IOException
	{
		return build(collision, rawTransports, bankTiles, cuts, RoutingStaticLoader.SEED_TILE);
	}

	/**
	 * Same as {@link #build(CollisionMap, Map, Set, int[])}, but with an overridable structural
	 * reachability seed tile. Production callers use the loader with its fixed seed; this overload
	 * lets synthetic-world unit tests exercise structural reachability without embedding the real
	 * seed tile {@code (3221, 3218, 0)} in every tiny test world.
	 */
	static Result build(CollisionMap collision, Map<Integer, Set<Transport>> rawTransports,
		Set<Integer> bankTiles, int[] cuts, int seedTile) throws IOException
	{
		long started = System.nanoTime();
		WalkableTiles walkable = enumerateWalkableTiles(collision);
		CutSet cutSet = validateCuts(cuts, walkable);
		int[] componentIds = new int[walkable.tiles.length];
		floodFillComponents(walkable, cutSet.blocked, componentIds);
		ComponentLayer layer = formLayer(collision.fingerprint(), walkable, componentIds, cutSet.valid);

		RoutingStatic routingStatic = RoutingStaticLoader.build(collision, rawTransports, bankTiles, layer, seedTile);

		int[] natural = RoutingStaticLoader.naturalComponents(layer);
		int naturalComponentCount = 0;
		for (int id = 1; id < natural.length; id++)
		{
			if (natural[id] == id) naturalComponentCount++;
		}
		int reachableNaturalComponentCount = 0;
		for (boolean reachable : RoutingStaticLoader.structuralReachability(collision, layer, natural,
			new boolean[natural.length], rawTransports, seedTile))
		{
			if (reachable) reachableNaturalComponentCount++;
		}
		int[] searchTilesPerComponent = new int[routingStatic.routingComponentCount()];
		int largestRoutingComponentSize = 0;
		for (int i = 0; i < routingStatic.searchTileCount(); i++)
		{
			largestRoutingComponentSize = Math.max(largestRoutingComponentSize,
				++searchTilesPerComponent[routingStatic.routingComponent(i)]);
		}
		int crossingCount = layer.crossings.length / 2;
		Diagnostics diagnostics = new Diagnostics(System.nanoTime() - started, walkable.tiles.length,
			naturalComponentCount, routingStatic.routingComponentCount() - 1, largestRoutingComponentSize,
			reachableNaturalComponentCount, cuts.length / 2, cutSet.duplicateCount, cutSet.invalidCount,
			cutSet.valid.size() - crossingCount, crossingCount, routingStatic.searchTileCount(),
			routingStatic.siteCount(), routingStatic.exactWalks().exactComponentCount());
		return new Result(routingStatic, diagnostics);
	}

	/**
	 * The routing components of every walkable tile and the separating cuts between them, as the
	 * {@link ComponentLayer} that {@link RoutingStaticLoader} reads. Ids are numbered from 1 in order
	 * of each component's first tile, with the valid cuts blocked; nothing hash-ordered reaches the output.
	 */
	static ComponentLayer generate(CollisionMap collision, int[] cuts)
	{
		WalkableTiles walkable = enumerateWalkableTiles(collision);
		CutSet cutSet = validateCuts(cuts, walkable);
		int[] componentIds = new int[walkable.tiles.length];
		floodFillComponents(walkable, cutSet.blocked, componentIds);
		return formLayer(collision.fingerprint(), walkable, componentIds, cutSet.valid);
	}

	/** The runs of equal component ids over the walkable tiles, plus the valid cuts that separate two components. */
	private static ComponentLayer formLayer(long fingerprint, WalkableTiles walkable, int[] componentIds,
		List<long[]> validCuts)
	{
		int runCount = 0;
		for (int i = 0, length = 0; i < componentIds.length; i++)
		{
			length = extendsRun(walkable, componentIds, i, length) ? length + 1 : 1;
			if (length == 1) runCount++;
		}
		int[] starts = new int[runCount];
		char[] lengths = new char[runCount];
		int[] ids = new int[runCount];
		for (int i = 0, run = -1; i < componentIds.length; i++)
		{
			if (extendsRun(walkable, componentIds, i, run < 0 ? 0 : lengths[run])) lengths[run]++;
			else
			{
				starts[++run] = walkable.tiles[i];
				lengths[run] = 1;
				ids[run] = componentIds[i];
			}
		}

		List<Crossing> crossings = buildCrossings(validCuts, componentIds, walkable);
		int[] crossingTiles = new int[crossings.size() * 2];
		for (int i = 0; i < crossings.size(); i++)
		{
			crossingTiles[2 * i] = crossings.get(i).fromTile;
			crossingTiles[2 * i + 1] = crossings.get(i).toTile;
		}
		return new ComponentLayer(fingerprint, starts, lengths, ids, crossingTiles);
	}

	/** Whether tile {@code index} continues a run of {@code length} tiles ending at the tile before it. */
	private static boolean extendsRun(WalkableTiles walkable, int[] componentIds, int index, int length)
	{
		return index > 0 && length < Character.MAX_VALUE && walkable.tiles[index] == walkable.tiles[index - 1] + 1
			&& componentIds[index] == componentIds[index - 1];
	}

	/**
	 * The ordinary walking graph over every walkable tile, with natural components and structural
	 * reachability computed exactly as {@link #build} does. The tooling cut generator partitions
	 * this graph, so generated cuts and the runtime agree on what a walking edge is.
	 */
	@AllArgsConstructor(access = AccessLevel.PRIVATE)
	public static final class WalkingGraph
	{
		private final WalkableTiles walkable;
		private final int[] naturalId;
		@Getter @Accessors(fluent = true) private final int naturalComponentCount;
		private final boolean[] reachableNatural;

		/** Number of walkable tiles; tile indexes follow ascending unsigned packed order. */
		public int tileCount()
		{
			return walkable.tiles.length;
		}

		public int tile(int index)
		{
			return walkable.tiles[index];
		}

		/** Index of a walkable tile, or -1 when the tile is not walkable. */
		public int indexOf(int tile)
		{
			return tilePosition(walkable, tile);
		}

		/** Natural component id of a tile index, in {@code 1..naturalComponentCount()}. */
		public int naturalComponent(int index)
		{
			return naturalId[index];
		}

		public boolean isStructurallyReachable(int naturalComponent)
		{
			return reachableNatural[naturalComponent];
		}

		/** Indexes of the walkable tiles reachable in one ordinary walking step. */
		public int[] neighbours(int index)
		{
			int[] tiles = ordinaryNeighborsFromMask(walkable.tiles[index], walkable.masks[index]);
			int[] result = new int[tiles.length];
			int count = 0;
			for (int tile : tiles)
			{
				int neighbour = tilePosition(walkable, tile);
				if (neighbour >= 0) result[count++] = neighbour;
			}
			return count == result.length ? result : Arrays.copyOf(result, count);
		}
	}

	/** Builds the walking graph used for cut generation; see {@link WalkingGraph}. */
	public static WalkingGraph walkingGraph(CollisionMap collision, Map<Integer, Set<Transport>> rawTransports)
	{
		return walkingGraph(collision, rawTransports, RoutingStaticLoader.SEED_TILE);
	}

	static WalkingGraph walkingGraph(CollisionMap collision, Map<Integer, Set<Transport>> rawTransports, int seedTile)
	{
		WalkableTiles walkable = enumerateWalkableTiles(collision);
		int[] naturalId = new int[walkable.tiles.length];
		int naturalComponentCount = floodFillComponents(walkable, null, naturalId);
		// Only read in memory for its natural components, never serialized or loaded, so it needs no fingerprint.
		ComponentLayer layer = formLayer(0L, walkable, naturalId, List.of());
		int[] natural = RoutingStaticLoader.naturalComponents(layer);
		boolean[] reachable = RoutingStaticLoader.structuralReachability(collision, layer, natural,
			new boolean[natural.length], rawTransports, seedTile);
		return new WalkingGraph(walkable, naturalId, naturalComponentCount, reachable);
	}

	// ---- Enumeration of every walkable tile in ascending unsigned packed order ----

	@AllArgsConstructor
	private static final class WalkableTiles
	{
		final int[] tiles;
		final byte[] masks;
		/** Per 64-tile group, the group's first index and the bitmask of tiles present. */
		final PrimitiveIntHashMap<long[]> index;
	}

	private static WalkableTiles enumerateWalkableTiles(CollisionMap collision)
	{
		TileSelection selected = TileSelection.allWalkable(collision);
		int[] tiles = new int[selected.tileCount()];
		byte[] masks = new byte[tiles.length];
		int next = 0;
		// Packed tiles sort by plane, then y, then x; emit that order without sorting or copying.
		for (int plane = 0; plane < 4; plane++)
		{
			for (int ry = 0; ry < selected.height; ry++)
			{
				int baseY = (selected.minY + ry) * REGION_SIZE;
				for (int ly = 0; ly < REGION_SIZE; ly++)
				{
					int rowStart = ly * REGION_SIZE;
					for (int rx = 0; rx < selected.width; rx++)
					{
						BitSet region = selected.regions[(rx + ry * selected.width) * 4 + plane];
						if (region == null) continue;
						int baseX = (selected.minX + rx) * REGION_SIZE;
						for (int bit = region.nextSetBit(rowStart); bit >= 0 && bit < rowStart + REGION_SIZE;
							bit = region.nextSetBit(bit + 1))
						{
							int tile = WorldPointUtil.packWorldPoint(baseX + (bit & (REGION_SIZE - 1)), baseY + ly, plane);
							tiles[next] = tile;
							masks[next++] = collision.ordinaryWalkingMask(tile);
						}
					}
				}
			}
		}
		PrimitiveIntHashMap<long[]> index = new PrimitiveIntHashMap<>(tiles.length / 64 + 1);
		for (int i = 0; i < tiles.length; i++)
		{
			int group = tiles[i] >>> 6;
			long[] entry = index.get(group);
			if (entry == null)
			{
				entry = new long[] {i, 0};
				index.put(group, entry);
			}
			entry[1] |= 1L << (tiles[i] & 63);
		}
		return new WalkableTiles(tiles, masks, index);
	}

	/** One bit per walkable tile, allocating bits only for regions that have any. */
	private static final class TileSelection
	{
		final BitSet[] regions;
		final int minX, minY, width, height;

		TileSelection(CollisionMap collision)
		{
			SplitFlagMap.RegionExtent extent = collision.regionExtent();
			minX = extent.getMinX();
			minY = extent.getMinY();
			width = extent.getWidth() + 1;
			height = extent.getHeight() + 1;
			regions = new BitSet[width * height * 4];
		}

		static TileSelection allWalkable(CollisionMap collision)
		{
			TileSelection selected = new TileSelection(collision);
			for (int ry = 0; ry < selected.height; ry++)
			{
				for (int rx = 0; rx < selected.width; rx++)
				{
					int region = rx + ry * selected.width;
					int baseX = (selected.minX + rx) * REGION_SIZE;
					int baseY = (selected.minY + ry) * REGION_SIZE;
					for (int plane = 0; plane < Math.min(4, collision.getRegionPlaneCounts(region)); plane++)
					{
						for (int ly = 0; ly < REGION_SIZE; ly++)
						{
							for (int lx = 0; lx < REGION_SIZE; lx++)
							{
								if (!collision.isBlocked(baseX + lx, baseY + ly, plane))
									selected.mark(region * 4 + plane, ly * REGION_SIZE + lx);
							}
						}
					}
				}
			}
			return selected;
		}

		int tileCount()
		{
			int count = 0;
			for (BitSet region : regions)
				if (region != null) count += region.cardinality();
			return count;
		}

		private void mark(int region, int bit)
		{
			BitSet bits = regions[region];
			if (bits == null) regions[region] = bits = new BitSet(REGION_SIZE * REGION_SIZE);
			bits.set(bit);
		}
	}

	// ---- Flood fill (natural when blocked==null, routing when blocked is a valid-cut set) ----

	/** Returns the number of components assigned (ids {@code 1..count}), 0 if there were no walkable tiles. */
	private static int floodFillComponents(WalkableTiles walkable, int[] blocked, int[] componentOut)
	{
		int n = walkable.tiles.length;
		IntDeque queue = new IntDeque(4096);
		int nextId = 1;
		for (int seed = 0; seed < n; seed++)
		{
			if (componentOut[seed] != 0)
			{
				continue;
			}
			queue.addLast(seed);
			componentOut[seed] = nextId;
			while (!queue.isEmpty())
			{
				int position = queue.pollFirst();
				int tile = walkable.tiles[position];
				int x = WorldPointUtil.unpackWorldX(tile);
				int y = WorldPointUtil.unpackWorldY(tile);
				int plane = WorldPointUtil.unpackWorldPlane(tile);
				int mask = Byte.toUnsignedInt(walkable.masks[position]);
				for (int bit = 0; bit < 8; bit++)
				{
					if ((mask & (1 << bit)) == 0)
					{
						continue;
					}
					int neighbor = WorldPointUtil.packWorldPoint(x + NEIGHBOR_DX[bit], y + NEIGHBOR_DY[bit], plane);
					int neighborPosition = tilePosition(walkable, neighbor);
					if (neighborPosition < 0 || componentOut[neighborPosition] != 0)
					{
						continue;
					}
					if (blocked != null && IntArrays.binarySearch(blocked,
						blockedEdgeKey(tile, neighbor, position, neighborPosition, bit)) >= 0)
					{
						continue;
					}
					componentOut[neighborPosition] = nextId;
					queue.addLast(neighborPosition);
				}
			}
			nextId++;
		}
		return nextId - 1;
	}

	// Clockwise 0-N,1-NE,2-E,3-SE,4-S,5-SW,6-W,7-NW; the bit layout of CollisionMap.ordinaryWalkingMask.
	private static final int[] NEIGHBOR_DX = {0, 1, 1, 1, 0, -1, -1, -1};
	private static final int[] NEIGHBOR_DY = {1, 1, 0, -1, -1, -1, 0, 1};

	private static int[] ordinaryNeighborsFromMask(int tile, byte maskByte)
	{
		int mask = Byte.toUnsignedInt(maskByte);
		int x = WorldPointUtil.unpackWorldX(tile);
		int y = WorldPointUtil.unpackWorldY(tile);
		int z = WorldPointUtil.unpackWorldPlane(tile);
		int[] result = new int[Integer.bitCount(mask)];
		int count = 0;
		for (int bit = 0; bit < 8; bit++)
		{
			if ((mask & (1 << bit)) != 0)
			{
				result[count++] = WorldPointUtil.packWorldPoint(x + NEIGHBOR_DX[bit], y + NEIGHBOR_DY[bit], z);
			}
		}
		return result;
	}

	// ---- Cuts: validity ("ignore cuts that are not current walking edges") + canonical dedup ----

	@AllArgsConstructor
	private static final class CutSet
	{
		final List<long[]> valid; // each entry {a, b} as raw ints boxed in a long[2] for simplicity
		final int[] blocked; // sorted edge keys, see blockedEdgeKey
		final int duplicateCount;
		final int invalidCount;
	}

	private static CutSet validateCuts(int[] cuts, WalkableTiles walkable)
	{
		HashSet<Long> seenCanonical = new HashSet<>();
		int duplicateCount = 0;
		List<long[]> candidates = new ArrayList<>();
		int pairCount = cuts.length / 2;
		for (int i = 0; i < pairCount; i++)
		{
			int rawA = cuts[2 * i];
			int rawB = cuts[2 * i + 1];
			int a = Integer.compareUnsigned(rawA, rawB) <= 0 ? rawA : rawB;
			int b = Integer.compareUnsigned(rawA, rawB) <= 0 ? rawB : rawA;
			long key = canonicalKey(a, b);
			if (!seenCanonical.add(key))
			{
				duplicateCount++;
				continue;
			}
			candidates.add(new long[] {Integer.toUnsignedLong(a), Integer.toUnsignedLong(b)});
		}
		List<long[]> valid = new ArrayList<>();
		int[] blockedKeys = new int[candidates.size()];
		int blockedCount = 0;
		int invalidCount = 0;
		for (long[] candidate : candidates)
		{
			int a = (int) candidate[0];
			int b = (int) candidate[1];
			int posA = tilePosition(walkable, a);
			int[] neighborsOfA = posA < 0 ? new int[0] : ordinaryNeighborsFromMask(a, walkable.masks[posA]);
			if (posA < 0 || !IntArrays.contains(neighborsOfA, 0, neighborsOfA.length, b))
			{
				invalidCount++;
				continue;
			}
			valid.add(candidate);
			int direction = directionIndex(WorldPointUtil.unpackWorldX(b) - WorldPointUtil.unpackWorldX(a),
				WorldPointUtil.unpackWorldY(b) - WorldPointUtil.unpackWorldY(a));
			blockedKeys[blockedCount++] = (posA << 3) | direction;
		}
		int[] blocked = Arrays.copyOf(blockedKeys, blockedCount);
		Arrays.sort(blocked); // keys are non-negative, so signed order is unsigned order
		return new CutSet(valid, blocked, duplicateCount, invalidCount);
	}

	private static long canonicalKey(int a, int b)
	{
		int min = Integer.compareUnsigned(a, b) <= 0 ? a : b;
		int max = Integer.compareUnsigned(a, b) <= 0 ? b : a;
		return (Integer.toUnsignedLong(min) << 32) | Integer.toUnsignedLong(max);
	}

	// ---- Section: routing components / crossings ----

	@AllArgsConstructor
	private static final class Crossing
	{
		final int fromTile, toTile;
	}

	private static List<Crossing> buildCrossings(List<long[]> validCuts, int[] routingId, WalkableTiles walkable)
	{
		List<Crossing> crossings = new ArrayList<>();
		for (long[] cut : validCuts)
		{
			int a = (int) cut[0];
			int b = (int) cut[1];
			int posA = tilePosition(walkable, a);
			int posB = tilePosition(walkable, b);
			if (posA < 0 || posB < 0 || routingId[posA] == routingId[posB])
			{
				continue;
			}
			crossings.add(new Crossing(a, b));
		}
		crossings.sort((left, right) ->
		{
			int cmp = Integer.compareUnsigned(left.fromTile, right.fromTile);
			return cmp != 0 ? cmp : Integer.compareUnsigned(left.toTile, right.toTile);
		});
		return crossings;
	}

	// ---- Small shared utilities ----

	/**
	 * Index of a walkable tile, or -1: the shared map holds {@code {firstIndex, presentBits}}
	 * per 64-tile group, so the index is the group's first index plus the tile's rank among
	 * the group's present bits.
	 */
	private static int tilePosition(WalkableTiles walkable, int tile)
	{
		long[] group = walkable.index.get(tile >>> 6);
		if (group == null)
		{
			return -1;
		}
		long bit = 1L << (tile & 63);
		if ((group[1] & bit) == 0)
		{
			return -1;
		}
		return (int) group[0] + Long.bitCount(group[1] & (bit - 1));
	}

	/** The direction index ({@link #NEIGHBOR_DX}/{@link #NEIGHBOR_DY} order) of a one-step delta. */
	private static int directionIndex(int dx, int dy)
	{
		for (int bit = 0; bit < 8; bit++)
		{
			if (NEIGHBOR_DX[bit] == dx && NEIGHBOR_DY[bit] == dy)
			{
				return bit;
			}
		}
		throw new IllegalArgumentException("non-adjacent edge delta " + dx + "," + dy);
	}

	/**
	 * Canonical key of a blocked walking edge: the index of its unsigned-lowest tile (the
	 * {@code validateCuts} pair order) and the direction from that tile to the other.
	 */
	private static int blockedEdgeKey(int tile, int neighbor, int position, int neighborPosition, int direction)
	{
		boolean tileIsLow = Integer.compareUnsigned(tile, neighbor) <= 0;
		int anchor = tileIsLow ? position : neighborPosition;
		int dir = tileIsLow ? direction : direction ^ 4; // i^4 is the opposite direction in NEIGHBOR_* order
		return (anchor << 3) | dir;
	}
}

package shortestpath.pathfinder.astar;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import java.util.Arrays;
import java.util.Map;
import java.util.Set;
import org.junit.BeforeClass;
import org.junit.Test;
import shortestpath.pathfinder.CollisionMap;
import shortestpath.pathfinder.SplitFlagMap;
import shortestpath.transport.ResourceLoader;
import shortestpath.transport.Transport;

/**
 * Real-data coverage for {@link RoutingStaticBuilder}: derivation succeeds on the committed
 * collision map, the plugin's transports and banks, and the committed {@code routing-cuts.bin},
 * and every {@link RoutingStatic} invariant holds.
 */
public class RoutingStaticBuilderRealDataTest
{
	private static CollisionMap collision;
	private static RoutingStaticBuilder.Result result;

	@BeforeClass
	public static void buildOnce() throws Exception
	{
		collision = new CollisionMap(SplitFlagMap.fromResources());
		Map<Integer, Set<Transport>> transports = ResourceLoader.transports();
		Set<Integer> banks = ResourceLoader.destinations().get("bank");
		int[] cuts = RoutingCuts.loadFromResources().pairs();
		result = RoutingStaticBuilder.build(collision, transports, banks, cuts);
		System.out.println("real-data build: " + result.diagnostics);
	}

	@Test
	public void buildsSuccessfullyWithPlausibleCounts()
	{
		RoutingStatic mine = result.routingStatic;
		// RoutingStatic.takeOwnership() already validated every structural invariant inside build().
		assertTrue("search tile count should be substantial", mine.searchTileCount() > 1_000_000);
		assertTrue("site count should be substantial", mine.siteCount() > 1_000);
		assertTrue("at least one reachable bank", mine.reachableBankCount() > 0);
		assertTrue("routing component count should exceed 1", mine.routingComponentCount() > 1);
	}

	@Test
	public void windingDungeonSitesAreJoinedByTheirWalk()
	{
		// The Ice Queen's Lair tunnel: its two ends are 30 tiles apart but about 185 on foot.
		RoutingStatic mine = result.routingStatic;
		int west = mine.siteIndex(shortestpath.WorldPointUtil.packWorldPoint(2827, 9909, 0));
		int east = mine.siteIndex(shortestpath.WorldPointUtil.packWorldPoint(2857, 9918, 0));
		assertTrue(west >= 0 && east >= 0);
		int component = mine.siteComponents(west)[0];
		assertTrue(mine.exactWalks().isExact(component));
		int[] sites = mine.componentSites(component);
		int[][] table = ExactWalks.pairDistances(mine, component);
		int walk = table[Arrays.binarySearch(sites, west)][Arrays.binarySearch(sites, east)];
		assertTrue("walk " + walk, walk > 3 * 30 && walk < CostArithmetic.INF);
		assertTrue(result.diagnostics.exactComponentCount > 500);
	}

	@Test
	public void mostCommittedCutsStillSeparateComponents()
	{
		// Cuts may lag behind collision map updates; dropped ones only cost performance.
		assertTrue(result.diagnostics.inputCutCount > 0);
		assertTrue("most cuts should still be valid separating crossings on the current map",
			result.diagnostics.crossingCount > result.diagnostics.inputCutCount / 2);
	}

	@Test
	public void reachableBankIndexesExactlyMatchTheDerivedList()
	{
		RoutingStatic mine = result.routingStatic;
		int expectedNodes = 0;
		for (int i = 0; i < mine.reachableBankCount(); i++)
		{
			int tile = mine.reachableBankTile(i);
			assertTrue(mine.isBankSite(mine.siteIndex(tile)));
			int node = mine.searchIndex(tile);
			if (node >= 0)
			{
				assertTrue(mine.isBankNode(node));
				expectedNodes++;
			}
		}
		int actualNodes = 0;
		for (int node = 0; node < mine.searchTileCount(); node++)
		{
			if (mine.isBankNode(node))
			{
				actualNodes++;
			}
		}
		int actualSites = 0;
		for (int site = 0; site < mine.siteCount(); site++)
		{
			if (mine.isBankSite(site))
			{
				actualSites++;
			}
		}
		assertEquals(expectedNodes, actualNodes);
		assertEquals(mine.reachableBankCount(), actualSites);
	}

	@Test
	public void siteAttachmentsMatchCollisionDerivedAttachments()
	{
		RoutingStatic mine = result.routingStatic;
		int mismatches = 0;
		StringBuilder examples = new StringBuilder();
		for (int site = 0; site < mine.siteCount(); site++)
		{
			int[] expected = mine.siteComponents(site);
			int[] actual = mine.attachments(mine.siteTile(site), collision);
			Arrays.sort(expected);
			Arrays.sort(actual);
			if (!Arrays.equals(expected, actual) && mismatches++ < 3)
			{
				examples.append(" site ").append(site).append(" expected=").append(Arrays.toString(expected))
					.append(" actual=").append(Arrays.toString(actual));
			}
		}
		assertEquals(examples.toString(), 0, mismatches);
	}
}

package shortestpath.pathfinder.astar;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import org.junit.Test;
import shortestpath.WorldPointUtil;
import shortestpath.pathfinder.SplitFlagMap;
import shortestpath.pathfinder.TransportAvailability;
import shortestpath.pathfinder.TransportAvailabilityFixture;
import shortestpath.transport.Transport;
import shortestpath.transport.TransportType;

/**
 * Synthetic-world unit tests for {@link RoutingStaticBuilder}, covering rules a whole-map test
 * can't isolate: cut validity, non-separating cuts, transport-only reachability,
 * seasonal reachability and pruning, the empty-cut-list case, and determinism.
 */
public class RoutingStaticBuilderTest
{
	private static int tile(int x, int y)
	{
		return WorldPointUtil.packWorldPoint(x, y, 0);
	}

	private static Transport transport(int origin, int destination, TransportType type)
	{
		return new Transport.TransportBuilder().origin(origin).destination(destination).type(type).duration(1).build();
	}

	private static Map<Integer, Set<Transport>> transports(Transport... transports)
	{
		Map<Integer, Set<Transport>> map = new HashMap<>();
		for (Transport transport : transports)
		{
			map.computeIfAbsent(transport.getOrigin(), k -> new HashSet<>()).add(transport);
		}
		return map;
	}

	private static int[] cuts(int[]... pairs)
	{
		int[] result = new int[pairs.length * 2];
		for (int i = 0; i < pairs.length; i++)
		{
			result[2 * i] = pairs[i][0];
			result[2 * i + 1] = pairs[i][1];
		}
		return result;
	}

	private static int[] pair(int a, int b)
	{
		return new int[] {a, b};
	}

	// ---- A three-tile chain A-B-C, used by several cut-handling tests ----

	private static final int A = tile(10, 10);
	private static final int B = tile(11, 10);
	private static final int C = tile(12, 10);

	private static SyntheticCollisionMap chainWorld()
	{
		Set<Integer> walkable = Set.of(A, B, C);
		Map<Integer, int[]> adjacency =
			SyntheticCollisionMap.symmetricAdjacency(new int[][] {{A, B}, {B, C}});
		return new SyntheticCollisionMap(walkable, adjacency, 1);
	}

	@Test
	public void tileLookupHandlesCollisionsZeroAndUpperPlanes()
	{
		// The ground tiles share a group but leave gaps between their positions.
		Set<Integer> tiles = Set.of(tile(0, 0), tile(15, 0), tile(49, 0), tile(63, 0), tile(31, 1), tile(13, 2),
			tile(47, 2), WorldPointUtil.packWorldPoint(1, 1, 2), WorldPointUtil.packWorldPoint(1, 1, 3));
		RoutingStaticBuilder.WalkingGraph graph = RoutingStaticBuilder.walkingGraph(
			new SyntheticCollisionMap(tiles, Map.of(), 4), Map.of(), tile(0, 0));

		assertEquals(tiles.size(), graph.tileCount());
		for (int index = 0; index < graph.tileCount(); index++)
		{
			assertTrue(tiles.contains(graph.tile(index)));
			assertEquals(index, graph.indexOf(graph.tile(index)));
		}
		assertEquals(-1, graph.indexOf(tile(29, 3)));
		assertEquals(-1, graph.indexOf(tile(14, 0)));
		assertEquals(-1, graph.indexOf(WorldPointUtil.packWorldPoint(2, 1, 3)));
	}

	@Test
	public void noCutsProducesOneNaturalAndOneRoutingComponent() throws Exception
	{
		RoutingStaticBuilder.Result result =
			RoutingStaticBuilder.build(chainWorld(), Map.of(), Set.of(), new int[0], A);

		assertEquals(1, result.diagnostics.naturalComponentCount);
		assertEquals(1, result.diagnostics.routingComponentCount);
		assertEquals(0, result.diagnostics.crossingCount);
		assertEquals(3, result.routingStatic.searchTileCount());
		// With zero cuts, routing ids must exactly track natural ids (same flood fill, no blocking).
		assertEquals(result.diagnostics.naturalComponentCount, result.diagnostics.routingComponentCount);
	}

	@Test
	public void tileEnumerationStaysSortedAcrossRegionsAndPlanes() throws Exception
	{
		int upper = WorldPointUtil.packWorldPoint(1, 1, 3);
		int[] expected = {tile(63, 0), tile(64, 0), tile(0, 1), tile(1, 64),
			WorldPointUtil.packWorldPoint(1, 1, 1), upper};
		Set<Integer> tiles = new HashSet<>();
		for (int tile : expected) tiles.add(tile);
		SyntheticCollisionMap world = new SyntheticCollisionMap(tiles,
			SyntheticCollisionMap.withStubEdges(tiles,
				SyntheticCollisionMap.symmetricAdjacency(new int[][] {{expected[0], expected[1]}}), 0, 1), 4)
		{
			@Override
			public SplitFlagMap.RegionExtent regionExtent()
			{
				return new SplitFlagMap.RegionExtent(0, 0, 1, 1);
			}

			@Override
			public byte getRegionPlaneCounts(int regionIndex)
			{
				return (byte) (regionIndex >= 0 && regionIndex < 4 ? 4 : 0);
			}
		};
		RoutingStaticBuilder.WalkingGraph graph = RoutingStaticBuilder.walkingGraph(world, Map.of(), expected[0]);

		assertEquals(expected.length, graph.tileCount());
		for (int index = 0; index < expected.length; index++)
		{
			assertEquals(expected[index], graph.tile(index));
			assertEquals(index, graph.indexOf(expected[index]));
		}
		assertEquals(1, graph.neighbours(0).length);
		assertEquals(1, graph.neighbours(0)[0]);
		assertEquals(0, graph.neighbours(expected.length - 1).length);
		Transport[] globals = new Transport[expected.length];
		for (int i = 0; i < expected.length; i++)
			globals[i] = transport(WorldPointUtil.UNDEFINED, expected[i], TransportType.SEASONAL_TRANSPORTS);
		RoutingStatic selected = RoutingStaticBuilder.build(world, transports(globals), Set.of(),
			new int[0], expected[0]).routingStatic;
		assertEquals(expected.length, selected.searchTileCount());
		for (int i = 0; i < expected.length; i++) assertEquals(expected[i], selected.searchTile(i));
	}

	@Test
	public void fullAndCandidateEnumerationAgreeWithNonzeroRegionOrigin() throws Exception
	{
		int a = tile(191, 256), b = tile(192, 256);
