		RoutingStaticBuilder.Result result =
			RoutingStaticBuilder.build(seasonalWorld(), transports, Set.of(), new int[0], A1);

		assertEquals(3, result.diagnostics.routingComponentCount);
		assertEquals(4, result.routingStatic.routingComponentCount());
		assertEquals(2, result.routingStatic.searchTileCount());
		assertEquals(-1, result.routingStatic.searchIndex(B1));
		assertEquals(-1, result.routingStatic.searchIndex(C1));
	}

	@Test
	public void cutOnUnreachableLandKeepsItsCrossing() throws Exception
	{
		RoutingStatic loaded = viaLayer(seasonalWorld(), Map.of(), Set.of(), cuts(pair(C1, C2)), A1);

		assertEquals(1, loaded.crossingCount());
		assertEquals(4, loaded.routingComponentCount());
		assertEquals(2, loaded.searchTileCount());
	}

	@Test
	public void blockedGlobalTeleportEndpointAttachesBothIslandsItBorders() throws Exception
	{
		int blocked = tile(39, 20);
		Map<Integer, int[]> adjacency = SyntheticCollisionMap.symmetricAdjacency(
			new int[][] {{A1, A2}, {B1, B2}, {B2, B3}, {C1, C2}});
		adjacency.put(blocked, new int[] {B1, C1});
		SyntheticCollisionMap world = new SyntheticCollisionMap(Set.of(A1, A2, B1, B2, B3, C1, C2), adjacency, 1);
		Map<Integer, Set<Transport>> transports =
			transports(transport(WorldPointUtil.UNDEFINED, blocked, TransportType.SEASONAL_TRANSPORTS));

		RoutingStatic loaded = viaLayer(world, transports, Set.of(C2), new int[0], A1);

		assertEquals(7, loaded.searchTileCount());
		assertEquals(1, loaded.reachableBankCount());
	}

	@Test
	public void verticalNeighboursDoNotWrapAtTheEdgesOfAPlaneOrBetweenPlanes() throws Exception
	{
		int top = WorldPointUtil.packWorldPoint(10, 32767, 0);
		int bottom = WorldPointUtil.packWorldPoint(10, 0, 1);
		int origin = WorldPointUtil.packWorldPoint(10, 0, 0);
		int lowerTwo = WorldPointUtil.packWorldPoint(10, 5, 2);
		int upperTwo = WorldPointUtil.packWorldPoint(10, 6, 2);
		int highest = WorldPointUtil.packWorldPoint(10, 32767, 3);
		// Every tile gets an eastern partner, since a tile with no walking edge has no walking mask.
		Set<Integer> tiles = new HashSet<>(Set.of(top, bottom, origin, lowerTwo, upperTwo, highest));
		int[][] edges = new int[5][];
		int edge = 0;
		for (int tile : new int[] {top, bottom, origin, highest})
		{
			int partner = WorldPointUtil.packWorldPoint(11, WorldPointUtil.unpackWorldY(tile),
				WorldPointUtil.unpackWorldPlane(tile));
			tiles.add(partner);
			edges[edge++] = pair(tile, partner);
		}
		edges[edge] = pair(lowerTwo, upperTwo);
		SyntheticCollisionMap world = new SyntheticCollisionMap(tiles, SyntheticCollisionMap.symmetricAdjacency(edges), 4)
		{
			@Override
			public SplitFlagMap.RegionExtent regionExtent()
			{
				return new SplitFlagMap.RegionExtent(0, 0, 0, 511);
			}

			@Override
			public byte getRegionPlaneCounts(int regionIndex)
			{
				return 4;
			}
		};
		Transport[] globals = new Transport[tiles.size()];
		int next = 0;
		for (int tile : tiles)
			globals[next++] = transport(WorldPointUtil.UNDEFINED, tile, TransportType.SEASONAL_TRANSPORTS);
		Map<Integer, Set<Transport>> transports = transports(globals);

		RoutingStatic loaded = viaLayer(world, transports, Set.of(), new int[0], origin);
		assertEquals(tiles.size(), loaded.searchTileCount());
		assertEquals(-1, loaded.northNode(loaded.searchIndex(top)));
		assertEquals(-1, loaded.southNode(loaded.searchIndex(bottom)));
		assertEquals(-1, loaded.northNode(loaded.searchIndex(highest)));
		assertEquals(-1, loaded.southNode(loaded.searchIndex(origin)));
		assertEquals(loaded.searchIndex(upperTwo), loaded.northNode(loaded.searchIndex(lowerTwo)));
		assertEquals(loaded.searchIndex(lowerTwo), loaded.southNode(loaded.searchIndex(upperTwo)));
	}

	@Test
	public void cutThatIsNotAWalkingEdgeOnUnattachedLandAddsNoRoutingComponent() throws Exception
	{
		// Routing components count the ones a transport, the seed or a crossing attaches to, so the endpoint
		// of a cut that is dropped when the layer is generated does not make its island a candidate.
		RoutingStatic without = viaLayer(seasonalWorld(), Map.of(), Set.of(), new int[0], A1);
		RoutingStatic dead = viaLayer(seasonalWorld(), Map.of(), Set.of(), cuts(pair(C1, tile(53, 20))), A1);

		assertEquals(2, without.routingComponentCount());
		assertEquals(without.routingComponentCount(), dead.routingComponentCount());
		assertEquals(0, dead.crossingCount());
		assertEquals(2, dead.searchTileCount());
	}

	@Test(expected = IllegalStateException.class)
	public void missingStructuralReachabilitySeedIsAHardError() throws Exception
	{
		viaLayer(chainWorld(), Map.of(), Set.of(), new int[0], tile(999, 999));
	}

	@Test
	public void layerThatNoLongerFitsTheCollisionMapIsRejected() throws Exception
	{
		Map<Integer, Set<Transport>> transports = transports(transport(A2, B1, TransportType.SEASONAL_TRANSPORTS));
		ComponentLayer layer = layerOf(seasonalWorld(), new int[0]);
		SyntheticCollisionMap shrunk = new SyntheticCollisionMap(Set.of(A1, A2, B1, B2, C1, C2),
			SyntheticCollisionMap.symmetricAdjacency(new int[][] {{A1, A2}, {B1, B2}, {C1, C2}}), 1);
		// Stamped for the shrunk map, so the content check passes and the per-tile check is what rejects it.
		ComponentLayer restamped = new ComponentLayer(shrunk.fingerprint(), layer.starts, layer.lengths, layer.ids,
			layer.crossings);
		try
		{
			RoutingStaticLoader.build(shrunk, transports, Set.of(), restamped, A1);
			fail("a walkable tile of the layer is blocked in the map");
		}
		catch (IOException expected)
		{
			assertTrue(expected.getMessage(), expected.getMessage().contains("stale"));
		}
	}

	@Test
	public void layerWhoseRunLengthsOverflowTheTileCountIsRejected() throws Exception
	{
		// 40,000 maximal runs hold more tiles than an int can count; none of them has to match the map.
		int runs = 40000;
		int[] starts = new int[runs];
		char[] lengths = new char[runs];
		int[] ids = new int[runs];
		for (int i = 0; i < runs; i++)
		{
			starts[i] = i * Character.MAX_VALUE;
			lengths[i] = Character.MAX_VALUE;
			ids[i] = 1;
		}
		ComponentLayer layer = new ComponentLayer(chainWorld().fingerprint(), starts, lengths, ids, new int[0]);
		try
		{
			RoutingStaticLoader.build(chainWorld(), Map.of(), Set.of(), layer, 0);
			fail("the run lengths add up to more search tiles than the loader can hold");
		}
		catch (IOException expected)
		{
			assertTrue(expected.getMessage(), expected.getMessage().contains("stale"));
		}
	}

	@Test
	public void crossingThatIsNotAWalkingEdgeIsRejected() throws Exception
	{
		ComponentLayer covered = layerOf(chainWorld(), new int[0]);
		// A and C are both in the layer, but B lies between them, so no walking edge joins them.
		ComponentLayer layer = new ComponentLayer(covered.fingerprint, covered.starts, covered.lengths, covered.ids,
			new int[] {A, C});
		try
		{
			RoutingStaticLoader.build(chainWorld(), Map.of(), Set.of(), layer, A);
			fail("the crossing is not a walking edge of the collision map");
		}
		catch (IOException expected)
		{
			assertTrue(expected.getMessage(), expected.getMessage().contains("walking edge"));
		}
	}

	@Test
	public void crossingOutsideTheLayerIsRejected() throws Exception
	{
		ComponentLayer layer = new ComponentLayer(chainWorld().fingerprint(), new int[] {A}, new char[] {1},
			new int[] {1}, new int[] {A, C});
		try
		{
			RoutingStaticLoader.build(chainWorld(), Map.of(), Set.of(), layer, A);
			fail("the crossing endpoint is not covered");
		}
		catch (IOException expected)
		{
			assertTrue(expected.getMessage(), expected.getMessage().contains("stale"));
		}
	}

	private static void assertStale(CollisionMap loaded, ComponentLayer layer)
	{
		try
		{
			RoutingStaticLoader.build(loaded, Map.of(), Set.of(), layer, A);
			fail("the layer was generated for different collision data");
		}
		catch (IOException expected)
		{
			assertTrue(expected.getMessage(), expected.getMessage().contains("stale"));
		}
	}

	@Test
	public void walkableTileAddedToTheMapAfterTheLayerWasGeneratedIsRejected() throws Exception
	{
		// D joins C. Without the content fingerprint the load succeeded and D was silently unroutable.
		int d = tile(13, 10);
		SyntheticCollisionMap grown = new SyntheticCollisionMap(Set.of(A, B, C, d),
			SyntheticCollisionMap.symmetricAdjacency(new int[][] {{A, B}, {B, C}, {C, d}}), 1);

		assertStale(grown, layerOf(chainWorld(), new int[0]));
	}

	@Test
	public void edgeRemovedFromTheMapAfterTheLayerWasGeneratedIsRejected() throws Exception
	{
		// The tile set is unchanged but A and B no longer connect. Without the fingerprint the load
		// succeeded and treated A, B and C as one natural component.
		Set<Integer> tiles = Set.of(A, B, C);
		SyntheticCollisionMap cut = new SyntheticCollisionMap(tiles, SyntheticCollisionMap.withStubEdges(tiles,
			SyntheticCollisionMap.symmetricAdjacency(new int[][] {{B, C}}), -1, 0), 1);

		assertStale(cut, layerOf(chainWorld(), new int[0]));
	}

	@Test
	public void layerGeneratedForTheSameMapIsAccepted() throws Exception
	{
		RoutingStatic loaded = viaLayer(chainWorld(), Map.of(), Set.of(), new int[0], A);

		assertEquals(3, loaded.searchTileCount());
	}
}

package shortestpath.pathfinder.astar;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;

import java.io.IOException;
import java.lang.reflect.Field;
import java.util.LinkedHashMap;
import java.util.Map;
import org.junit.Test;

public class RoutingStaticOwnershipTest
{
	@Test
	public void keepsTheSuppliedArraysAndDoesNotExposeThem() throws Exception
	{
		Map<String, Object> arrays = arrays();
		RoutingStatic stat = takeOwnership(arrays);
		for (Map.Entry<String, Object> entry : arrays.entrySet())
		{
			Field field = RoutingStatic.class.getDeclaredField(entry.getKey());
			field.setAccessible(true);
			assertSame(entry.getKey(), entry.getValue(), field.get(stat));
		}

		int[] components = stat.siteComponents(0);
		int[] sites = stat.componentSites(0);
		components[0] = 99;
		sites[0] = 99;
		assertArrayEquals(new int[] {0}, stat.siteComponents(0));
		assertArrayEquals(new int[] {0, 1}, stat.componentSites(0));
	}

	@Test(expected = IOException.class)
	public void stillRejectsInvalidArrayReferences() throws Exception
	{
		Map<String, Object> arrays = arrays();
		TileComponents invalid = new TileComponents(2, 100);
		invalid.set(0, 99);
		arrays.put("searchComponents", invalid);
		takeOwnership(arrays);
	}

	@Test
	public void neighbourOffsetsHandleAbsentAndLargestRowDistance() throws Exception
	{
		int count = 32769;
		Map<String, Object> arrays = arrays();
		int[] tiles = new int[count];
		for (int i = 0; i < count; i++) tiles[i] = i;
		char[] north = new char[count], south = new char[count];
		north[0] = 32768;
		south[32768] = 32768;
		arrays.put("searchTiles", tiles);
		arrays.put("searchComponents", new TileComponents(count, 1));
		arrays.put("walkingMasks", new byte[count]);
		arrays.put("northOffsets", north);
		arrays.put("southOffsets", south);
		RoutingStatic stat = takeOwnership(arrays);

		assertEquals(32768, stat.northNode(0));
		assertEquals(0, stat.southNode(32768));
		assertEquals(-1, stat.northNode(1));
		assertEquals(-1, stat.southNode(0));
	}

	@Test(expected = IOException.class)
	public void rejectsNeighbourOffsetOutsideTheTileArray() throws Exception
	{
		Map<String, Object> arrays = arrays();
		((char[]) arrays.get("northOffsets"))[0] = 2;
		takeOwnership(arrays);
	}

	@Test
	public void bankBitsKeepWordBoundariesAndLastPartialWord() throws Exception
	{
		int[] tiles = new int[130];
		for (int i = 0; i < tiles.length; i++) tiles[i] = i;
		int[] banks = {0, 63, 64, 129};
		RoutingStatic stat = RoutingStatic.takeOwnership(tiles, new TileComponents(130, 1), new byte[130],
			new char[130], new char[130], banks, new int[] {0, 1, 2, 3, 4}, new int[4], 1,
			new int[] {0, 4}, new int[] {0, 1, 2, 3}, banks, new int[0], new int[0], new int[0],
			4, 4, 0, 0, 0, new int[5], new int[0], new int[0]);

		for (int i = 0; i < tiles.length; i++)
			assertEquals(i == 0 || i == 63 || i == 64 || i == 129, stat.isBankNode(i));
		for (int i = 0; i < banks.length; i++) assertEquals(true, stat.isBankSite(i));
		assertFalse(stat.isBankSite(-1));
		RoutingStatic emptyBanks = RoutingStaticTestFixture.createT3();
		assertFalse(emptyBanks.isBankNode(0));
		assertFalse(emptyBanks.isBankSite(0));
	}

	private static Map<String, Object> arrays()
	{
		Map<String, Object> arrays = new LinkedHashMap<>();
		arrays.put("searchTiles", new int[] {10, 11});
		arrays.put("searchComponents", new TileComponents(2, 1));
		arrays.put("walkingMasks", new byte[] {4, 64});
		arrays.put("northOffsets", new char[2]);
		arrays.put("southOffsets", new char[2]);
		arrays.put("siteTiles", new int[] {10, 11});
		arrays.put("siteComponentOffsets", new int[] {0, 1, 2});
		arrays.put("siteComponentIds", new int[] {0, 0});
		arrays.put("componentSiteOffsets", new int[] {0, 2});
		arrays.put("componentSiteIds", new int[] {0, 1});
		arrays.put("reachableBankTiles", new int[] {11});
		arrays.put("crossingFromSite", new int[] {0});
		arrays.put("crossingToSite", new int[] {1});
		arrays.put("crossingCosts", new int[] {1});
		arrays.put("sparseOffsets", new int[] {0, 1, 2});
		arrays.put("sparseDestinations", new int[] {1, 0});
		arrays.put("sparseWeights", new int[] {2, 2});
		return arrays;
	}

	private static RoutingStatic takeOwnership(Map<String, Object> a) throws IOException
	{
		return RoutingStatic.takeOwnership((int[]) a.get("searchTiles"), (TileComponents) a.get("searchComponents"),
			(byte[]) a.get("walkingMasks"), (char[]) a.get("northOffsets"), (char[]) a.get("southOffsets"),
			(int[]) a.get("siteTiles"), (int[]) a.get("siteComponentOffsets"), (int[]) a.get("siteComponentIds"),
			1, (int[]) a.get("componentSiteOffsets"), (int[]) a.get("componentSiteIds"),
			(int[]) a.get("reachableBankTiles"), (int[]) a.get("crossingFromSite"), (int[]) a.get("crossingToSite"),
			(int[]) a.get("crossingCosts"), 2, 2, 0, 1, 2,
			(int[]) a.get("sparseOffsets"), (int[]) a.get("sparseDestinations"), (int[]) a.get("sparseWeights"));
	}
}

package shortestpath.pathfinder.astar;

import java.io.IOException;
import shortestpath.WorldPointUtil;
import shortestpath.poh.PohService;

/** Tiny valid static routing data for account/site-graph tests. */
public final class RoutingStaticTestFixture
{
	public static final int A = WorldPointUtil.packWorldPoint(1000, 1000, 0);
	public static final int BANK = WorldPointUtil.packWorldPoint(1001, 1000, 0);
	public static final int C = WorldPointUtil.packWorldPoint(1002, 1000, 0);
	public static final int D = WorldPointUtil.packWorldPoint(1003, 1000, 0);
	public static final int POH_ORIGIN = WorldPointUtil.packWorldPoint(1900, 7048, 0);
	public static final int POH_LANDING = WorldPointUtil.packWorldPoint(PohService.POH_LANDING_X, PohService.POH_LANDING_Y, 0);
	public static final int T3_A = WorldPointUtil.packWorldPoint(1000, 1000, 0);
	public static final int T3_B = WorldPointUtil.packWorldPoint(1002, 1000, 0);
	public static final int T3_E = WorldPointUtil.packWorldPoint(1004, 1000, 0);
	public static final int T3_F = WorldPointUtil.packWorldPoint(1006, 1000, 0);
	public static final int T3_C = WorldPointUtil.packWorldPoint(1000, 1002, 0);
	public static final int T3_D = WorldPointUtil.packWorldPoint(1000, 1000, 1);
	public static final int T3_G = WorldPointUtil.packWorldPoint(1002, 1002, 0);
	public static final int T3_TARGET = WorldPointUtil.packWorldPoint(1001, 1001, 0);
	public static final int T3_SEARCH_0 = WorldPointUtil.packWorldPoint(1001, 1000, 0);
	public static final int T3_SEARCH_1 = WorldPointUtil.packWorldPoint(1001, 1002, 0);

	private RoutingStaticTestFixture()
	{
	}

	static TileComponents components(int... ids)
	{
		int count = 0;
		for (int id : ids) count = Math.max(count, id + 1);
		TileComponents components = new TileComponents(ids.length, count);
		for (int i = 0; i < ids.length; i++) components.set(i, ids[i]);
		return components;
	}

	public static RoutingStatic create() throws Exception
	{
		int[] sites = {A, BANK, C, D, POH_ORIGIN, POH_LANDING};
		return takeOwnershipWithNetwork(new int[0], new TileComponents(0, 1), new byte[0], new char[0], new char[0], sites,
			new int[] {0, 1, 2, 3, 4, 5, 6}, new int[] {0, 0, 0, 0, 0, 0}, 1, new int[] {0, 6},
			new int[] {0, 1, 2, 3, 4, 5}, new int[] {BANK}, new int[] {0}, new int[] {2}, new int[] {1});
	}

	public static RoutingStatic createT3() throws Exception
	{
		int[] sites = {T3_A, T3_B, T3_E, T3_F, T3_C, T3_G, T3_D};
		return takeOwnershipWithNetwork(new int[] {T3_SEARCH_0, T3_SEARCH_1}, RoutingStaticTestFixture.components(0, 1), new byte[] {0, 0},
			new char[2], new char[2], sites, new int[] {0, 1, 3, 4, 5, 6, 7, 8},
			new int[] {0, 1, 2, 1, 2, 0, 0, 3}, 4, new int[] {0, 3, 5, 7, 8}, new int[] {0, 4, 5, 1, 2, 1, 3, 6},
			new int[] {T3_B}, new int[0], new int[0], new int[0]);
	}

	public static RoutingStatic createT4Walking() throws Exception
	{
		int[] sites = {A, BANK, C, D};
		return takeOwnershipWithNetwork(new int[] {A, BANK, C}, RoutingStaticTestFixture.components(0, 0, 0),
			new byte[] {4, 68, 64}, new char[3], new char[3], sites,
			new int[] {0, 1, 2, 3, 4}, new int[] {0, 0, 0, 0}, 1, new int[] {0, 4},
			new int[] {0, 1, 2, 3}, new int[] {BANK}, new int[0], new int[0], new int[0]);
	}

	/**
	 * As {@link RoutingStatic#takeOwnership}, with the sparse walking network the builder derives from the
	 * sites and their component attachments, as it does for real data.
	 */
	static RoutingStatic takeOwnershipWithNetwork(int[] searchTiles, TileComponents searchComponents, byte[] walkingMasks,
		char[] northOffsets, char[] southOffsets, int[] siteTiles, int[] siteComponentOffsets, int[] siteComponentIds,
		int routingComponentCount, int[] componentSiteOffsets, int[] componentSiteIds, int[] reachableBankTiles,
		int[] crossingFromSite, int[] crossingToSite, int[] crossingCosts) throws IOException
	{
		SparseWalkingNetworkBuilder.Result network =
			SparseWalkingNetworkBuilder.build(siteTiles, siteComponentOffsets, siteComponentIds);
		return RoutingStatic.takeOwnership(searchTiles, searchComponents, walkingMasks, northOffsets, southOffsets,
			siteTiles, siteComponentOffsets, siteComponentIds, routingComponentCount, componentSiteOffsets,
			componentSiteIds, reachableBankTiles, crossingFromSite, crossingToSite, crossingCosts,
			network.originalCount, network.vertexCount, network.steinerCount, network.undirectedEdgeCount,
			network.adjacencyCount(), network.offsets, network.destinations, network.weights);
	}
}

package shortestpath.pathfinder.astar;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.util.Set;
import org.junit.Test;
import shortestpath.WorldPointUtil;
import shortestpath.pathfinder.CollisionMap;
import shortestpath.pathfinder.TransportAvailabilityFixture;
import shortestpath.pathfinder.WildernessChecker;
import shortestpath.transport.Transport;
import shortestpath.transport.TransportType;

/**
 * {@link SearchRestrictions} mirrors the positional gates legacy checks per edge: neither walking
 * nor a local transport may land inside the wilderness or the league's always-blocked region from
 * outside it, while moving inside the gated area or out of it stays allowed. Global teleports are
 * barred from landing in the wilderness only when cast from outside it, matching the source-tile
 * check legacy runs on its abstract nodes.
 */
public class SearchRestrictionsTest
{
	// Fixture tiles: a short non-wilderness line leading to wilderness tiles. Masks join them in
	// array order, so geometry is irrelevant to the search but the coordinates are real, so the
	// wilderness and region predicates report genuine answers.
	private static final int SAFE2 = WorldPointUtil.packWorldPoint(2998, 3523, 0);
	private static final int SAFE = WorldPointUtil.packWorldPoint(2998, 3524, 0);
	private static final int WILD = WorldPointUtil.packWorldPoint(2995, 3540, 0);
	private static final int WILDT = WorldPointUtil.packWorldPoint(2995, 3541, 0);
	/** Level-25 wilderness: its teleport capability band is OVER_20. */
	private static final int WILD25 = WorldPointUtil.packWorldPoint(3200, 3712, 0);

	private static final SearchRestrictions AVOID_WILDERNESS = SearchRestrictions.of(true, null);
	private static final SearchRestrictions BLOCKED_WILD =
		SearchRestrictions.of(false, tile -> tile == WILD || tile == WILDT);

	@Test
	public void fixtureTilesHaveExpectedStatus()
	{
		assertFalse(WildernessChecker.isInWilderness(SAFE2));
		assertFalse(WildernessChecker.isInWilderness(SAFE));
		assertTrue(WildernessChecker.isInWilderness(WILD));
		assertTrue(WildernessChecker.isInWilderness(WILDT));
		assertEquals(TeleportCapability.OVER_20, TeleportCapability.at(WILD25));
	}

	@Test
	public void walkingIntoWildernessIsGated()
	{
		assertFalse(search(SAFE, WILD, AVOID_WILDERNESS).reached());
		assertTrue(search(SAFE, WILD, SearchRestrictions.none()).reached());
	}

	@Test
	public void leavingWildernessOnFootIsAllowed()
	{
		// The gate bars entering the wilderness, never walking out of it.
		assertTrue(search(WILD, SAFE, AVOID_WILDERNESS).reached());
		assertEquals(1, search(WILD, SAFE, AVOID_WILDERNESS).cost());
	}

	@Test
	public void localTransportIntoWildernessIsGated()
	{
		// Legacy flags transport destination nodes as tiles, so the same positional gate applies
		// to the jump's landing tile; a ditch-style crossing must not bypass it.
		PreparedRoutingAccount account = account(local(SAFE2, WILDT, 3));
		assertFalse(search(SAFE2, WILDT, AVOID_WILDERNESS, account).reached());
		assertTrue(search(SAFE2, WILDT, SearchRestrictions.none(), account).reached());
	}

	@Test
	public void localTransportOutOfWildernessIsAllowed()
	{
		PreparedRoutingAccount account = account(local(WILDT, SAFE2, 3));
		AStarForwardSearch.Result result = search(WILDT, SAFE2, AVOID_WILDERNESS, account);
		assertTrue(result.reached());
		assertEquals(3, result.cost());
	}

	@Test
	public void blockedRegionGatesWalkingAndTransports()
	{
		PreparedRoutingAccount account = account(local(SAFE2, WILDT, 3));
		assertFalse("walked into the blocked region", search(SAFE, WILD, BLOCKED_WILD, account).reached());
		assertFalse("transported into the blocked region",
			search(SAFE2, WILDT, BLOCKED_WILD, account).reached());
		assertTrue(search(SAFE, WILD, SearchRestrictions.none(), account).reached());
		assertTrue(search(SAFE2, WILDT, SearchRestrictions.none(), account).reached());
	}

	@Test
	public void leavingBlockedRegionByTransportIsAllowed()
	{
		PreparedRoutingAccount account = account(local(WILDT, SAFE2, 3));
		assertTrue(search(WILDT, SAFE2, BLOCKED_WILD, account).reached());
	}

	@Test
	public void globalTeleportIntoWildernessIsBarredFromOutside()
	{
		PreparedRoutingAccount account = account(teleport(WILDT, 0));
		assertFalse(search(SAFE2, WILDT, AVOID_WILDERNESS, account).reached());
		assertTrue(search(SAFE2, WILDT, SearchRestrictions.none(), account).reached());
	}

	@Test
	public void globalTeleportIntoWildernessIsAllowedFromInside()
	{
		// Legacy exempts wilderness landings when the cast tile is itself in the wilderness; the
		// capability band carries the same information. A limit-30 teleport is castable in level 25.
		PreparedRoutingAccount account = account(teleport(WILDT, 30));
		assertTrue(search(WILD25, WILDT, AVOID_WILDERNESS, account).reached());
	}

	private static AStarForwardSearch.Result search(int start, int target, SearchRestrictions restrictions)
	{
		return search(start, target, restrictions, account());
	}

	private static AStarForwardSearch.Result search(int start, int target, SearchRestrictions restrictions,
		PreparedRoutingAccount account)
	{
		TargetOverlay overlay = new TargetOverlay(new SiteGraph(routingStatic(), account), emptyCollision(), target);
		PreparedHeuristic heuristic = PreparedHeuristic.prepare(overlay, ReverseLabelsOracle.compute(overlay));
		AStarForwardSearch.Result result = AStarForwardSearch.search(overlay, heuristic, start,
			() -> false, true, 1, restrictions, AStarForwardSearch.NO_PROGRESS);
		AStarForwardSearch.Result oracle = AStarForwardSearch.search(overlay, heuristic, start,
			() -> false, false, 1, restrictions, AStarForwardSearch.NO_PROGRESS);
		assertEquals("optimised search agrees with the unoptimised one", oracle.reached(), result.reached());
		assertEquals("optimised search agrees with the unoptimised one", oracle.cost(), result.cost());
		return result;
	}

	private static PreparedRoutingAccount account(Transport... transports)
	{
		return PreparedRoutingAccount.compile(TransportAvailabilityFixture.of(transports),
			TransportAvailabilityFixture.of(), false, Set.of(), 0, true, ignored -> 0);
	}

	private static Transport local(int origin, int destination, int cost)
	{
		return new Transport.TransportBuilder().origin(origin).destination(destination)
			.type(TransportType.TRANSPORT).duration(cost).build();
	}

	private static Transport teleport(int destination, int maxWildernessLevel)
	{
		return new Transport.TransportBuilder().destination(destination).type(TransportType.TELEPORTATION_MINIGAME)
			.duration(2).maxWildernessLevel(maxWildernessLevel).build();
	}

	/**
	 * {@code SAFE2 - SAFE - WILD} walk each way, {@code WILDT} and {@code WILD25} reachable only by
	 * transport. Mask bit 2 steps to the next array element and bit 6 to the previous one, so the
	 * tiles need no real-world adjacency.
	 */
	private static RoutingStatic routingStatic()
	{
		int[] tiles = {SAFE2, SAFE, WILD, WILDT, WILD25};
		int n = tiles.length;
		int[] siteOffsets = new int[n + 1], componentMembers = new int[n];
		for (int i = 0; i < n; i++)
		{
			siteOffsets[i] = i;
			componentMembers[i] = i;
		}
		siteOffsets[n] = n;
		try
		{
			return RoutingStaticTestFixture.takeOwnershipWithNetwork(tiles, new TileComponents(n, 1),
				new byte[] {4, 68, 64, 0, 0},
				new char[5], new char[5], tiles, siteOffsets,
				new int[n], 1, new int[] {0, n}, componentMembers, new int[0], new int[0], new int[0],
				new int[0]);
		}
		catch (java.io.IOException e)
		{
			throw new AssertionError(e);
		}
	}

	private static CollisionMap emptyCollision()
	{
		return new CollisionMap(null)
		{
			@Override public int[] ordinaryWalkingNeighbors(int packedPoint)
			{
				return new int[0];
			}

			@Override public boolean isBlocked(int x, int y, int z)
			{
				return false;
			}
		};
	}
}

package shortestpath.pathfinder.astar;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import org.junit.Test;
import shortestpath.WorldPointUtil;
import shortestpath.pathfinder.BankVisitState;
import shortestpath.pathfinder.CollisionMap;
import shortestpath.pathfinder.TransportAvailabilityFixture;

public class SparseManhattanTest
{
	private static final int A = WorldPointUtil.packWorldPoint(1000, 1000, 0);
	private static final int B = WorldPointUtil.packWorldPoint(1003, 1000, 0);
	private static final int C = WorldPointUtil.packWorldPoint(1003, 1004, 0);
	private static final int OTHER_PLANE = WorldPointUtil.packWorldPoint(1000, 1000, 1);
	private static final int TARGET = WorldPointUtil.packWorldPoint(1001, 1001, 0);

	@Test
	public void sparseSteinerLabelsMatchCliqueForSyntheticTarget() throws Exception
	{
		RoutingStatic stat = syntheticSparse();
		TargetOverlay target = new TargetOverlay(new SiteGraph(stat, emptyAccount()),
			attachments(A, OTHER_PLANE), TARGET);
		ReverseLabels sparse = ReverseLabels.computeSparse(target);
		ReverseLabels clique = ReverseLabelsOracle.computeClique(target);
		assertArrayEquals(clique.labels(), sparse.labels());
		assertTrue(sparse.sparseRelaxationCount() > 0);
		assertTrue(sparse.attachmentRelaxationCount() > 0);
		assertEquals(0, sparse.targetLabel(BankVisitState.CARRIED));
	}

	@Test
	public void reducedGeneratorsMatchRawSeedsAndRetainOracle() throws Exception
	{
		RoutingStatic stat = syntheticSparse();
		TargetOverlay target = new TargetOverlay(new SiteGraph(stat, emptyAccount()),
			attachments(A, OTHER_PLANE), TARGET);
		ReverseLabels reverse = ReverseLabelsOracle.compute(target);
		PreparedHeuristic heuristic = PreparedHeuristic.prepare(target, reverse);
		for (int packed : new int[] {A, B, C, TARGET, OTHER_PLANE,
			WorldPointUtil.packWorldPoint(1002, 1002, 0)})
		{
			assertEquals(heuristic.estimateRaw(packed, BankVisitState.CARRIED, new int[] {0}),
				heuristic.estimate(packed, BankVisitState.CARRIED, new int[] {0}));
			assertEquals(heuristic.estimateRaw(packed, BankVisitState.BANKED, new int[] {0}),
				heuristic.estimate(packed, BankVisitState.BANKED, new int[] {0}));
		}
		assertEquals(heuristic.rawSeedCount(), heuristic.seedCount(0, BankVisitState.CARRIED) + heuristic.seedCount(0, BankVisitState.BANKED)
			+ heuristic.seedCount(1, BankVisitState.CARRIED) + heuristic.seedCount(1, BankVisitState.BANKED));
		assertEquals(10, heuristic.rawSeedCount());
		assertEquals(4, heuristic.generatorCount());
		assertEquals(0.4, heuristic.generatorRatio(), 0.0);
		assertTrue(heuristic.generatorCount() <= heuristic.rawSeedCount());
		assertTrue(heuristic.generatorCount() > 0);
		assertTrue(heuristic.preparationNanos() >= 0);
	}

	@Test
	public void asymmetricTerminalLayersPreserveSteinerLabelsAndGeneratorProvenance() throws Exception
	{
		RoutingStatic stat = syntheticSparse();
		for (int[] masks : new int[][] {{2}, {2, 3}, {1, 2}})
		{
			int[] tiles = masks.length == 1 ? new int[] {TARGET} : new int[] {TARGET, C};
			TargetOverlay overlay = new TargetOverlay(new SiteGraph(stat, emptyAccount()),
				attachments(A, OTHER_PLANE), tiles, masks);
			ReverseLabels sparse = ReverseLabels.computeSparse(overlay);
			assertArrayEquals(ReverseLabelsOracle.computeClique(overlay).labels(), sparse.labels());
			assertTrue(sparse.sparseRelaxationCount() > 0);
			PreparedHeuristic heuristic = PreparedHeuristic.prepare(overlay, sparse);
			for (int packed : new int[] {A, B, C, TARGET, OTHER_PLANE})
			{
				for (BankVisitState layer : BankVisitState.values())
				{
					for (int[] components : new int[][] {{0}, {1}, {0, 1}})
						assertEquals(heuristic.estimateRaw(packed, layer, components),
							heuristic.estimate(packed, layer, components));
				}
			}
		}
	}

	@Test
	public void emptyComponentsStayUnreachableBeforeAndAfterBanking() throws Exception
	{
		TargetOverlay target = new TargetOverlay(new SiteGraph(syntheticSparse(), emptyAccount()),
			attachments(A), TARGET);
		PreparedHeuristic heuristic = PreparedHeuristic.prepare(target, ReverseLabelsOracle.compute(target));

		for (BankVisitState banked : BankVisitState.values())
		{
			assertEquals(0, heuristic.seedCount(1, banked));
			assertEquals(0, heuristic.generatorCount(1, banked));
			assertEquals(CostArithmetic.INF, heuristic.estimate(OTHER_PLANE, banked, new int[] {1}));
			assertEquals(1, heuristic.estimate(A, banked, new int[] {0}));
			assertEquals(0, heuristic.estimate(TARGET, banked, new int[] {0}));
		}
	}

	private static RoutingStatic syntheticSparse() throws Exception
	{
		int[] sites = {A, B, C, OTHER_PLANE};
		int[] offsets = {0, 1, 2, 3, 4}, components = {0, 0, 0, 1};
		SparseWalkingNetworkBuilder.Result network = SparseWalkingNetworkBuilder.build(sites, offsets, components);
		return RoutingStatic.takeOwnership(new int[] {A, OTHER_PLANE}, RoutingStaticTestFixture.components(0, 1), new byte[] {0, 0},
			new char[2], new char[2], sites, offsets, components, 2, new int[] {0, 3, 4},
			new int[] {0, 1, 2, 3}, new int[0], new int[0], new int[0], new int[0], network.originalCount,
			network.vertexCount, network.steinerCount, network.undirectedEdgeCount, network.adjacencyCount(),
			network.offsets, network.destinations, network.weights);
	}

	private static CollisionMap attachments(int... sites)
	{
		return new CollisionMap(null)
		{
			@Override public int[] ordinaryWalkingNeighbors(int packedPoint)
			{
				return sites.clone();
			}

			@Override public boolean isBlocked(int x, int y, int z)
			{
				return false;
			}
		};
	}

	private static PreparedRoutingAccount emptyAccount()
	{
		return PreparedRoutingAccount.compile(TransportAvailabilityFixture.of(), TransportAvailabilityFixture.of(),
			false, java.util.Set.of(), 0, true, ignored -> 0);
	}
}

package shortestpath.pathfinder.astar;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import java.util.Arrays;
import org.junit.Test;
import shortestpath.WorldPointUtil;

/** Synthetic correctness tests for {@link SparseWalkingNetworkBuilder}. */
public class SparseWalkingNetworkBuilderTest
{
	private static final int INF = Integer.MAX_VALUE;

	@Test
	public void emptyInputProducesEmptyNetwork()
	{
		SparseWalkingNetworkBuilder.Result result =
			SparseWalkingNetworkBuilder.build(new int[0], new int[] {0}, new int[0]);
		assertEquals(0, result.originalCount);
		assertEquals(0, result.vertexCount);
		assertEquals(0, result.steinerCount);
		assertEquals(0, result.undirectedEdgeCount);
		assertArrayEquals(new int[] {0}, result.offsets);
		assertArrayEquals(new int[0], result.destinations);
		assertArrayEquals(new int[0], result.weights);
	}

	@Test
	public void singleSiteProducesSingleIsolatedVertex()
	{
		int tile = WorldPointUtil.packWorldPoint(1000, 1000, 0);
		SparseWalkingNetworkBuilder.Result result =
			SparseWalkingNetworkBuilder.build(new int[] {tile}, new int[] {0, 1}, new int[] {0});
		assertEquals(1, result.originalCount);
		assertEquals(1, result.vertexCount);
		assertEquals(0, result.steinerCount);
		assertEquals(0, result.undirectedEdgeCount);
		assertArrayEquals(new int[] {0, 0}, result.offsets);
	}

	@Test
	public void siteWithNoComponentAttachmentIsIsolated()
	{
		int a = WorldPointUtil.packWorldPoint(1000, 1000, 0);
		int b = WorldPointUtil.packWorldPoint(1010, 1000, 0);
		// Site 0 has no component attachments (empty range); site 1 attaches to component 0 alone.
		SparseWalkingNetworkBuilder.Result result = SparseWalkingNetworkBuilder.build(
			new int[] {a, b}, new int[] {0, 0, 1}, new int[] {0});
		assertEquals(2, result.originalCount);
		assertEquals(2, result.vertexCount);
		assertEquals(0, result.steinerCount);
		assertEquals(0, result.undirectedEdgeCount);
	}

	@Test
	public void distancesEqualDoubledChebyshevWithinOneComponent()
	{
		int[] xs = {1000, 1003, 1003, 998, 1050, 1000, 1200};
		int[] ys = {1000, 1000, 1004, 990, 1050, 1200, 900};
		int[] tiles = new int[xs.length];
		for (int i = 0; i < xs.length; i++)
		{
			tiles[i] = WorldPointUtil.packWorldPoint(xs[i], ys[i], 0);
		}
		int[] offsets = new int[tiles.length + 1];
		int[] ids = new int[tiles.length];
		for (int i = 0; i < tiles.length; i++)
		{
			offsets[i + 1] = i + 1;
			ids[i] = 0;
		}
		SparseWalkingNetworkBuilder.Result result = SparseWalkingNetworkBuilder.build(tiles, offsets, ids);
		assertEquals(tiles.length, result.originalCount);
		assertTrue(result.vertexCount >= result.originalCount);
		assertEquals(result.vertexCount - result.originalCount, result.steinerCount);
		assertEquals(result.undirectedEdgeCount * 2, result.destinations.length);

		for (int i = 0; i < tiles.length; i++)
		{
			for (int j = 0; j < tiles.length; j++)
			{
				if (i == j)
				{
					continue;
				}
				int expected = 2 * WorldPointUtil.distanceBetween(tiles[i], tiles[j]);
				int actual = dijkstra(result, i, j);
				assertEquals("distance " + i + "->" + j, expected, actual);
			}
		}
	}

	@Test
	public void coincidentSitesAreConnectedByZeroWeightEdges()
	{
		int tile = WorldPointUtil.packWorldPoint(1000, 1000, 0);
		int[] tiles = {tile, tile, tile};
		int[] offsets = {0, 1, 2, 3};
		int[] ids = {0, 0, 0};
		SparseWalkingNetworkBuilder.Result result = SparseWalkingNetworkBuilder.build(tiles, offsets, ids);
		assertEquals(3, result.originalCount);
		assertEquals(3, result.vertexCount);
		assertEquals(0, result.steinerCount);
		assertEquals(2, result.undirectedEdgeCount);
		for (int i = 0; i < 3; i++)
		{
			for (int j = 0; j < 3; j++)
			{
				if (i != j)
				{
					assertEquals(0, dijkstra(result, i, j));
				}
			}
		}
	}

	@Test
	public void differentComponentsDoNotConnect()
	{
		int a = WorldPointUtil.packWorldPoint(1000, 1000, 0);
		int b = WorldPointUtil.packWorldPoint(1005, 1000, 0);
		int c = WorldPointUtil.packWorldPoint(1000, 1000, 1);
		int d = WorldPointUtil.packWorldPoint(1005, 1000, 1);
		// Sites 0,1 -> component 0 (plane 0). Sites 2,3 -> component 1 (plane 1, same x/y).
		int[] tiles = {a, b, c, d};
		int[] offsets = {0, 1, 2, 3, 4};
		int[] ids = {0, 0, 1, 1};
		SparseWalkingNetworkBuilder.Result result = SparseWalkingNetworkBuilder.build(tiles, offsets, ids);
		assertEquals(4, result.originalCount);
		assertEquals(INF, dijkstra(result, 0, 2));
		assertEquals(INF, dijkstra(result, 0, 3));
		assertEquals(INF, dijkstra(result, 1, 2));
		assertEquals(INF, dijkstra(result, 1, 3));
		assertEquals(2 * WorldPointUtil.distanceBetween(a, b), dijkstra(result, 0, 1));
		assertEquals(2 * WorldPointUtil.distanceBetween(c, d), dijkstra(result, 2, 3));
	}

	@Test
	public void multiComponentSiteBridgesBothTrees()
	{
		int a = WorldPointUtil.packWorldPoint(1000, 1000, 0);
		int bridge = WorldPointUtil.packWorldPoint(1010, 1000, 0);
		int c = WorldPointUtil.packWorldPoint(1020, 1000, 0);
		int[] tiles = {a, bridge, c};
		// site 1 (bridge) attaches to both component 0 and component 1; sites 0 and 2 attach to
		// only one of them each, mirroring a site straddling two routing components.
		int[] offsets = {0, 1, 3, 4};
		int[] ids = {0, 0, 1, 1};
		SparseWalkingNetworkBuilder.Result result = SparseWalkingNetworkBuilder.build(tiles, offsets, ids);
		assertEquals(3, result.originalCount);
		assertEquals(2 * WorldPointUtil.distanceBetween(a, bridge), dijkstra(result, 0, 1));
		assertEquals(2 * WorldPointUtil.distanceBetween(bridge, c), dijkstra(result, 1, 2));
		// 0 and 2 are never members of the same component's tree, but the bridge site is a
		// vertex shared by both trees, so a path can still transit through it.
		assertEquals(2 * WorldPointUtil.distanceBetween(a, c), dijkstra(result, 0, 2));
	}

	@Test
	public void buildIsDeterministic()
	{
		int[] xs = {1000, 1003, 1003, 998, 1050, 1000, 1200, 1007, 995, 1300};
		int[] ys = {1000, 1000, 1004, 990, 1050, 1200, 900, 1002, 1500, 700};
		int[] tiles = new int[xs.length];
		for (int i = 0; i < xs.length; i++)
		{
			tiles[i] = WorldPointUtil.packWorldPoint(xs[i], ys[i], 0);
		}
		int[] offsets = new int[tiles.length + 1];
		int[] ids = new int[tiles.length];
		for (int i = 0; i < tiles.length; i++)
		{
			offsets[i + 1] = i + 1;
			ids[i] = 0;
		}
		SparseWalkingNetworkBuilder.Result first = SparseWalkingNetworkBuilder.build(tiles, offsets, ids);
		SparseWalkingNetworkBuilder.Result second = SparseWalkingNetworkBuilder.build(tiles, offsets, ids);
		assertEquals(first.originalCount, second.originalCount);
		assertEquals(first.vertexCount, second.vertexCount);
		assertEquals(first.steinerCount, second.steinerCount);
		assertEquals(first.undirectedEdgeCount, second.undirectedEdgeCount);
		assertArrayEquals(first.offsets, second.offsets);
		assertArrayEquals(first.destinations, second.destinations);
		assertArrayEquals(first.weights, second.weights);
	}

	private static void assertArrayEquals(int[] expected, int[] actual)
	{
		assertTrue("expected " + Arrays.toString(expected) + " but was " + Arrays.toString(actual),
			Arrays.equals(expected, actual));
	}

	/** Plain O(V^2) Dijkstra over the built CSR graph, for small test graphs only. */
	private static int dijkstra(SparseWalkingNetworkBuilder.Result net, int source, int target)
	{
		int[] dist = new int[net.vertexCount];
		Arrays.fill(dist, INF);
		dist[source] = 0;
		boolean[] settled = new boolean[net.vertexCount];
		for (int iteration = 0; iteration < net.vertexCount; iteration++)
		{
			int best = -1;
			int bestDist = INF;
			for (int v = 0; v < net.vertexCount; v++)
			{
				if (!settled[v] && dist[v] < bestDist)
				{
					bestDist = dist[v];
					best = v;
				}
			}
			if (best < 0)
			{
				break;
			}
			settled[best] = true;
			for (int edge = net.offsets[best]; edge < net.offsets[best + 1]; edge++)
			{
				int next = net.destinations[edge];
				int candidate = dist[best] + net.weights[edge];
				if (candidate < dist[next])
				{
					dist[next] = candidate;
				}
			}
		}
		return dist[target];
	}
}

package shortestpath.pathfinder.astar;

import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;
import java.util.Set;
import java.util.TreeSet;
import shortestpath.WorldPointUtil;
import shortestpath.pathfinder.CollisionMap;
import shortestpath.pathfinder.SplitFlagMap;

/**
 * A small, entirely in-memory {@link CollisionMap} for {@link RoutingStaticBuilder} unit tests.
 * Every world-scanning entry point {@link RoutingStaticBuilder} uses is overridable on
 * {@link CollisionMap} for exactly this reason: {@link #regionExtent()},
 * {@link #getRegionPlaneCounts(int)}, {@link #isBlocked(int, int, int)},
 * {@link #ordinaryWalkingMask(int)} and {@link #ordinaryWalkingNeighbors(int)}. This class
 * therefore never touches a real {@link SplitFlagMap} or its shared static region-extent state.
 *
 * <p>Test worlds declare walkable tiles and an explicit, small adjacency list per tile (the test
 * author is responsible for keeping it symmetric, exactly like real collision data: if {@code b}
 * is a declared neighbour of {@code a}, {@code a} must also be a declared neighbour of {@code b}).
 * Only ordinary 8-directional adjacency is modelled; no transport-blocked-origin behaviour is
 * needed since {@link RoutingStaticBuilder} never uses that path.
 */
class SyntheticCollisionMap extends CollisionMap
{
	// Matches CollisionMap.ordinaryWalkingNeighbors's own bit layout exactly (0-N..7-NW).
	private static final int[] DX = {0, 1, 1, 1, 0, -1, -1, -1};
	private static final int[] DY = {1, 1, 0, -1, -1, -1, 0, 1};

	private final Set<Integer> walkable;
	private final Map<Integer, int[]> neighbors;
	private final SplitFlagMap.RegionExtent extent;
	private final int planeCount;

	SyntheticCollisionMap(Set<Integer> walkableTiles, Map<Integer, int[]> neighborOverrides, int planeCount)
	{
		super(null);
		this.walkable = walkableTiles;
		this.neighbors = new HashMap<>(neighborOverrides);
		this.extent = new SplitFlagMap.RegionExtent(0, 0, 0, 0);
		this.planeCount = planeCount;
	}

	/** Covers the walkable set and every declared edge, in a fixed order, so any change to either shows. */
	@Override
	public long fingerprint()
	{
		long hash = planeCount;
		for (int tile : new TreeSet<>(walkable)) hash = hash * 1000003L + tile;
		for (int tile : new TreeSet<>(neighbors.keySet()))
		{
			int[] declared = neighbors.get(tile).clone();
			Arrays.sort(declared);
			hash = hash * 1000003L + tile;
			for (int neighbor : declared) hash = hash * 1000003L + neighbor;
		}
		return hash;
	}

	@Override
	public SplitFlagMap.RegionExtent regionExtent()
	{
		return extent;
	}

	@Override
	public byte getRegionPlaneCounts(int regionIndex)
	{
		return regionIndex == 0 ? (byte) planeCount : 0;
	}

	@Override
	public boolean isBlocked(int x, int y, int z)
	{
		return !walkable.contains(WorldPointUtil.packWorldPoint(x, y, z));
	}

	@Override
	public byte ordinaryWalkingMask(int packedPoint)
	{
		if (!walkable.contains(packedPoint))
		{
			return 0;
		}
		int x = WorldPointUtil.unpackWorldX(packedPoint);
		int y = WorldPointUtil.unpackWorldY(packedPoint);
		int z = WorldPointUtil.unpackWorldPlane(packedPoint);
		int[] declared = neighbors.getOrDefault(packedPoint, new int[0]);
		int mask = 0;
		for (int bit = 0; bit < 8; bit++)
		{
			int candidate = WorldPointUtil.packWorldPoint(x + DX[bit], y + DY[bit], z);
			if (contains(declared, candidate))
			{
				mask |= 1 << bit;
			}
		}
		return (byte) mask;
	}

	@Override
	public int[] ordinaryWalkingNeighbors(int packedPoint)
	{
		return neighbors.getOrDefault(packedPoint, new int[0]).clone();
	}

	private static boolean contains(int[] values, int target)
	{
		for (int value : values)
		{
			if (value == target)
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Gives every walkable tile without a declared neighbour one open edge toward {@code (dx, dy)}, at
	 * a tile that is not walkable. A real collision map never has a walkable tile without a walking
	 * edge (a tile with no open cardinal flag is blocked), and the routing loader rejects a zero
	 * walking mask as a stale layer; some synthetic worlds want single tiles, and the stub keeps their
	 * masks non-zero while joining nothing. The stub direction must not point at a search tile.
	 */
	static Map<Integer, int[]> withStubEdges(Set<Integer> walkableTiles, Map<Integer, int[]> adjacency, int dx, int dy)
	{
		Map<Integer, int[]> result = new HashMap<>(adjacency);
		for (int tile : walkableTiles)
		{
			if (result.containsKey(tile)) continue;
			result.put(tile, new int[] {WorldPointUtil.packWorldPoint(WorldPointUtil.unpackWorldX(tile) + dx,
				WorldPointUtil.unpackWorldY(tile) + dy, WorldPointUtil.unpackWorldPlane(tile))});
		}
		return result;
	}

	/** Builds symmetric adjacency from an explicit list of open, undirected tile-pair edges. */
	static Map<Integer, int[]> symmetricAdjacency(int[][] edges)
	{
		Map<Integer, java.util.List<Integer>> adjacency = new HashMap<>();
		for (int[] edge : edges)
		{
			adjacency.computeIfAbsent(edge[0], k -> new java.util.ArrayList<>()).add(edge[1]);
			adjacency.computeIfAbsent(edge[1], k -> new java.util.ArrayList<>()).add(edge[0]);
		}
		Map<Integer, int[]> result = new HashMap<>();
		for (Map.Entry<Integer, java.util.List<Integer>> entry : adjacency.entrySet())
		{
			result.put(entry.getKey(), entry.getValue().stream().mapToInt(Integer::intValue).toArray());
		}
		return result;
	}
}

package shortestpath.pathfinder.astar;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
