/**
 * Covers {@link TargetWalkDistances}: the reverse-BFS walking bound a synthetic target's
 * attachment edges use instead of a bare Chebyshev distance. Earlier fixtures never ran it —
 * their synthetic targets were not search tiles ({@code search()} returned null) or their targets
 * were static sites — so these tests use a U-shaped corridor whose dead end is far closer in a
 * straight line than on foot:
 *
 * <pre>
 *   y=12:  T --+--+--+--+
 *   y=11:              |
 *   y=10:  B +--+--+--+
 * </pre>
 */
public class TargetWalkDistancesTest
{
	private static final int TARGET = tile(10, 12);
	private static final int BANK = tile(10, 10);
	/** A blocked nook east of the corridor, a stand-in for a site on a non-search tile. */
	private static final int POCKET_BANK = tile(15, 10);
	/** A blocked tile inside the bend, a stand-in for a non-search-tile target. */
	private static final int BLOCKED_TARGET = tile(11, 11);
	/** The corridor in walking-distance order from TARGET, so CORRIDOR[i] is i steps away. */
	private static final int[] CORRIDOR =
	{
		tile(10, 12), tile(11, 12), tile(12, 12), tile(13, 12), tile(14, 12),
		tile(14, 11),
		tile(14, 10), tile(13, 10), tile(12, 10), tile(11, 10), tile(10, 10)
	};

	private static int tile(int x, int y)
	{
		return WorldPointUtil.packWorldPoint(x, y, 0);
	}

	private static SyntheticCollisionMap corridorCollision()
	{
		int[][] edges = new int[CORRIDOR.length - 1][];
		for (int i = 1; i < CORRIDOR.length; i++)
		{
			edges[i - 1] = new int[] {CORRIDOR[i - 1], CORRIDOR[i]};
		}
		Map<Integer, int[]> adjacency = SyntheticCollisionMap.symmetricAdjacency(edges);
		// One-way declarations for the blocked tiles: attachment lookups see the corridor as their
		// neighbour, without corridor tiles gaining an edge into a blocked tile.
		adjacency.put(POCKET_BANK, new int[] {tile(14, 10)});
		adjacency.put(BLOCKED_TARGET, new int[] {tile(11, 12), tile(12, 12)});
		return new SyntheticCollisionMap(new HashSet<>(Arrays.asList(
			Arrays.stream(CORRIDOR).boxed().toArray(Integer[]::new))), adjacency, 1);
	}

	private static RoutingStatic corridorStatic(boolean withCut) throws Exception
	{
		int[] cuts = withCut ? new int[] {tile(14, 10), tile(14, 11)} : new int[0];
		return RoutingStaticBuilder.build(corridorCollision(), Map.of(), Set.of(BANK, POCKET_BANK), cuts, BANK)
			.routingStatic;
	}

	private static int[] targetComponents(RoutingStatic stat)
	{
		return new int[] {stat.routingComponent(stat.searchIndex(TARGET))};
	}

	private static TargetOverlay overlay(RoutingStatic stat, int target)
	{
		return new TargetOverlay(new SiteGraph(stat, account()), corridorCollision(), target);
	}

	private static PreparedRoutingAccount account()
	{
		return PreparedRoutingAccount.compile(TransportAvailabilityFixture.of(),
			TransportAvailabilityFixture.of(), false, Set.of(), 0, true, ignored -> 0);
	}

	@Test
	public void searchRunsOnlyForSearchTileTargets() throws Exception
	{
		RoutingStatic stat = corridorStatic(false);

		assertNotNull(TargetWalkDistances.search(stat, TARGET, targetComponents(stat)));
		assertNull(TargetWalkDistances.search(stat, BLOCKED_TARGET, targetComponents(stat)));
	}

	@Test
	public void windingCorridorSitesGetWalkDistanceNotChebyshev() throws Exception
	{
		RoutingStatic stat = corridorStatic(false);
		TargetWalkDistances walk = TargetWalkDistances.search(stat, TARGET, targetComponents(stat));

		assertNotNull(walk);
		for (int i = 0; i < CORRIDOR.length; i++)
		{
			int chebyshev = WorldPointUtil.distanceBetween(TARGET, CORRIDOR[i]);
			assertEquals(Math.max(chebyshev, i), walk.bound(CORRIDOR[i], chebyshev));
		}
		// The far end of the corridor: straight-line distance 2, walking distance 10.
		assertEquals(10, walk.bound(BANK, 2));
		// A site on a blocked tile steps to its nearest reached search-tile neighbour first:
		// (14,11) at distance 5 bounds it at 6, above the Chebyshev 5.
		assertEquals(6, walk.bound(POCKET_BANK, WorldPointUtil.distanceBetween(TARGET, POCKET_BANK)));
	}

	@Test
	public void overlayAttachmentsUseTheWalkingBound() throws Exception
	{
		RoutingStatic stat = corridorStatic(false);
		TargetOverlay overlay = overlay(stat, TARGET);

		assertTrue(overlay.synthetic());
		assertEquals(2, overlay.attachmentCount());
		for (int i = 0; i < overlay.attachmentCount(); i++)
		{
			int site = stat.siteTile(overlay.attachmentSite(i));
			if (site == BANK)
			{
				assertEquals(10, overlay.attachmentCost(i));
			}
			else if (site == POCKET_BANK)
			{
				assertEquals(6, overlay.attachmentCost(i));
			}
			else
			{
				fail("unexpected attachment site " + site);
			}
		}
	}

	@Test
	public void blockedTargetKeepsChebyshevAttachments() throws Exception
	{
		RoutingStatic stat = corridorStatic(false);
		TargetOverlay overlay = overlay(stat, BLOCKED_TARGET);

		assertTrue(overlay.synthetic());
		assertEquals(2, overlay.attachmentCount());
		for (int i = 0; i < overlay.attachmentCount(); i++)
		{
			assertEquals(WorldPointUtil.distanceBetween(BLOCKED_TARGET, stat.siteTile(overlay.attachmentSite(i))),
				overlay.attachmentCost(i));
		}
	}

	@Test
	public void walkBoundStaysInsideTheTargetRoutingComponent() throws Exception
	{
		RoutingStatic stat = corridorStatic(true);
		TargetOverlay overlay = overlay(stat, TARGET);

		// The cut makes the bottom row a second routing component: only the (14,11) crossing
		// endpoint attaches to the target's component, at its real walking distance 5.
		assertEquals(1, overlay.attachmentCount());
		assertEquals(tile(14, 11), stat.siteTile(overlay.attachmentSite(0)));
		assertEquals(5, overlay.attachmentCost(0));

		// Tiles beyond the cut are never reached: their bound is the exhausted frontier's
		// distance (last reached distance 5, plus one).
		TargetWalkDistances walk = TargetWalkDistances.search(stat, TARGET, targetComponents(stat));
		assertEquals(6, walk.bound(BANK, WorldPointUtil.distanceBetween(TARGET, BANK)));
		assertEquals(6, walk.bound(POCKET_BANK, WorldPointUtil.distanceBetween(TARGET, POCKET_BANK)));
	}

	@Test
	public void raisedBoundsKeepTheSearchExact() throws Exception
	{
		List<Integer> corridor = Arrays.stream(CORRIDOR).boxed().collect(Collectors.toList());
		java.util.Collections.reverse(corridor);
		for (boolean cut : new boolean[] {false, true})
		{
			RoutingStatic stat = corridorStatic(cut);
			TargetOverlay overlay = overlay(stat, TARGET);

			AStarForwardSearch.Result result = AStarForwardSearch.search(overlay,
				PreparedHeuristic.prepare(overlay, ReverseLabelsOracle.compute(overlay)), BANK);

			assertTrue(result.reached());
			assertEquals(10, result.cost());
			assertEquals(corridor, result.path().stream()
				.map(PathStep::getPackedPosition).collect(Collectors.toList()));
			assertTrue(result.counters().heuristicCacheHits() > 0);
		}
	}
}

package shortestpath.pathfinder.astar;

import static org.junit.Assert.assertEquals;

import org.junit.Test;
import shortestpath.WorldPointUtil;
import shortestpath.pathfinder.AbstractNodeKind;
import shortestpath.pathfinder.WildernessChecker;

public class TeleportCapabilityTest
{
	/** Legacy's global-teleport band for a tile, as {@code Pathfinder.updateWildernessLevel} narrows it. */
	private static AbstractNodeKind legacyKind(int tile)
	{
		return WildernessChecker.isInLevel30Wilderness(tile) ? AbstractNodeKind.GLOBAL_TELEPORTS_OVER_30
			: WildernessChecker.isInLevel20Wilderness(tile) ? AbstractNodeKind.GLOBAL_TELEPORTS_OVER_20
			: WildernessChecker.isInWilderness(tile) ? AbstractNodeKind.GLOBAL_TELEPORTS_OVER_0
			: AbstractNodeKind.GLOBAL_TELEPORTS_NORMAL;
	}

	@Test
	public void capabilityIsLegacysGlobalTeleportBand()
	{
		for (int plane = 0; plane < 4; plane += 3)
			for (int x = 2900; x < 3500; x++)
				for (int[] ys : new int[][] {{3500, 4250}, {9890, 10420}})
					for (int y = ys[0]; y < ys[1]; y++)
					{
						int tile = WorldPointUtil.packWorldPoint(x, y, plane);
						AbstractNodeKind legacy = legacyKind(tile);
						TeleportCapability capability = TeleportCapability.at(tile);
						assertEquals(x + "," + y + "," + plane, legacy.maxWildernessLevel(), capability.castLevel());
					}
	}

	@Test
	public void bandBoundaries()
	{
		// Wilderness level is (y - 3520) / 8 + 1 above ground, from y = 3525.
		assertEquals(TeleportCapability.ALL, at(3200, 3400));
		assertEquals(TeleportCapability.ALL, at(3200, 3524));
		assertEquals("level 1", TeleportCapability.OVER_0, at(3200, 3525));
		assertEquals("level 13, the obelisk landing", TeleportCapability.OVER_0, at(3156, 3620));
		assertEquals("level 20", TeleportCapability.OVER_0, at(3200, 3679));
		assertEquals("level 21", TeleportCapability.OVER_20, at(3200, 3680));
		assertEquals("level 25", TeleportCapability.OVER_20, at(3200, 3712));
		assertEquals("level 30", TeleportCapability.OVER_20, at(3200, 3759));
		assertEquals("level 31", TeleportCapability.OVER_30, at(3200, 3760));
		assertEquals("Ferox Enclave is not wilderness", TeleportCapability.ALL, at(3130, 3630));
		assertEquals("underground level 1-20", TeleportCapability.OVER_0, at(3000, 10000));
	}

	@Test
	public void eachCapabilityCastsWhatTheOneBeforeItCan()
	{
		TeleportCapability[] order = {TeleportCapability.OVER_30, TeleportCapability.OVER_20,
			TeleportCapability.OVER_0, TeleportCapability.ALL};
		assertEquals(order.length, TeleportCapability.values().length);
		for (int i = 0; i < order.length; i++)
			for (int j = 0; j < order.length; j++)
				assertEquals(order[i] + " allows " + order[j], i >= j, order[i].allows(order[j]));
	}

	private static TeleportCapability at(int x, int y)
	{
		return TeleportCapability.at(WorldPointUtil.packWorldPoint(x, y, 0));
	}
}

package shortestpath.pathfinder.astar;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;

import java.lang.reflect.Field;
import org.junit.Test;

public class TileComponentsTest
{
	@Test
	public void compactStorageKeepsUnsignedValuesThrough65535() throws Exception
	{
		TileComponents components = new TileComponents(3, 65536);
		components.set(0, 0);
		components.set(1, 32768);
		components.set(2, 65535);
		assertEquals(3, components.length());
		assertEquals(0, components.get(0));
		assertEquals(32768, components.get(1));
		assertEquals(65535, components.get(2));
		assertNotNull(storage(components, "compactIds"));
		assertNull(storage(components, "wideIds"));
	}

	@Test
	public void largerWorldUsesFullSizeValuesWithoutTruncating() throws Exception
	{
		TileComponents components = new TileComponents(2, 65537);
		components.set(0, 65535);
		components.set(1, 65536);
		assertEquals(65535, components.get(0));
		assertEquals(65536, components.get(1));
		assertNull(storage(components, "compactIds"));
		assertNotNull(storage(components, "wideIds"));
	}

	@Test(expected = IllegalArgumentException.class)
	public void rejectsValuesOutsideTheWorldsComponentCount()
	{
		new TileComponents(1, 65536).set(0, 65536);
	}

	@Test(expected = IllegalArgumentException.class)
	public void rejectsNegativeValues()
	{
		new TileComponents(1, 1).set(0, -1);
	}

	private static Object storage(TileComponents components, String name) throws Exception
	{
		Field field = TileComponents.class.getDeclaredField(name);
		field.setAccessible(true);
		return field.get(components);
	}
}

package shortestpath.pathfinder.astar;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import java.util.Map;
import java.util.Set;
import org.junit.Test;
import shortestpath.WorldPointUtil;
import shortestpath.pathfinder.BankVisitState;
import shortestpath.pathfinder.TransportAvailabilityFixture;
import shortestpath.transport.Transport;
import shortestpath.transport.TransportType;

/** Correctness and diagnostic counts for unreachable goals the relaxed graph cannot reject. */
public class UnreachableSearchTest
{
	@Test
	public void unavailableBlockedTransportOriginDoesNotConnectItsNeighbouringRooms() throws Exception
	{
		int start = tile(10), left = tile(11), blocked = tile(12), right = tile(13), target = tile(14);
		SyntheticCollisionMap collision = new SyntheticCollisionMap(Set.of(start, left, right, target),
			Map.of(start, new int[] {left}, left, new int[] {start}, blocked, new int[] {left, right},
				right, new int[] {target}, target, new int[] {right}), 1);
		Transport transport = new Transport.TransportBuilder().origin(blocked).destination(right)
			.type(TransportType.TRANSPORT).duration(1).build();
		RoutingStatic stat = RoutingStaticBuilder.build(collision, Map.of(blocked, Set.of(transport)),
			Set.of(), new int[0], start).routingStatic;
		PreparedRoutingAccount account = PreparedRoutingAccount.compile(TransportAvailabilityFixture.of(),
			TransportAvailabilityFixture.of(), false, Set.of(), 0, true, ignored -> 0);
		PreparedTarget prepared = PreparedTarget.prepare(new SiteGraph(stat, account), collision, target);
		AStarForwardSearch.Result result = prepared.search(start, () -> false, 1);

		assertFalse("the account has no transport through the blocked origin", result.reached());
		System.out.println("Unavailable blocked origin: popped=" + result.counters().statesPopped()
			+ ", discovered=" + result.counters().uniqueStatesReached());
		PreparedRoutingAccount enabled = PreparedRoutingAccount.compile(TransportAvailabilityFixture.of(transport),
			TransportAvailabilityFixture.of(transport), false, Set.of(), 0, true, ignored -> 0);
		assertTrue(PreparedTarget.prepare(new SiteGraph(stat, enabled), collision, target)
			.search(start, () -> false, 1).reached());
	}

	@Test
	public void bankOnlyGoalCannotFinishWhenNoBankIsReachable() throws Exception
	{
		int start = tile(10), middle = tile(11), target = tile(12);
		SyntheticCollisionMap collision = new SyntheticCollisionMap(Set.of(start, middle, target),
			SyntheticCollisionMap.symmetricAdjacency(new int[][] {{start, middle}, {middle, target}}), 1);
		RoutingStatic stat = RoutingStaticBuilder.build(collision, Map.of(), Set.of(middle), new int[0], start).routingStatic;
		PreparedRoutingAccount account = PreparedRoutingAccount.compile(TransportAvailabilityFixture.of(),
			TransportAvailabilityFixture.of(), true, Set.of(), 0, true, ignored -> 0);
		PreparedTarget prepared = PreparedTarget.prepare(new SiteGraph(stat, account), collision,
			new int[] {target}, new int[] {2});
		AStarForwardSearch.Result result = prepared.search(start, () -> false, 1, SearchRestrictions.none(),
			AStarForwardSearch.NO_PROGRESS, (tile, banked) -> banked == BankVisitState.BANKED);

		assertFalse("the goal requires a bank visit the account cannot make", result.reached());
		assertEquals(CostArithmetic.INF, prepared.heuristic().estimate(start, BankVisitState.CARRIED));
		assertEquals(0, result.counters().statesPopped());
		System.out.println("Bank-only goal: popped=" + result.counters().statesPopped()
			+ ", discovered=" + result.counters().uniqueStatesReached());
		PreparedRoutingAccount enabled = PreparedRoutingAccount.compile(TransportAvailabilityFixture.of(),
			TransportAvailabilityFixture.of(), true, Set.of(middle), 0, true, ignored -> 0);
		assertTrue(PreparedTarget.prepare(new SiteGraph(stat, enabled), collision, new int[] {target}, new int[] {2})
			.search(start, () -> false, 1, SearchRestrictions.none(), AStarForwardSearch.NO_PROGRESS,
				(tile, banked) -> banked == BankVisitState.BANKED).reached());
	}

	private static int tile(int x)
	{
		return WorldPointUtil.packWorldPoint(x, 10, 0);
	}
}

package shortestpath.pathfinder.astar;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import org.junit.Test;
import shortestpath.WorldPointUtil;
import shortestpath.pathfinder.BankVisitState;
import shortestpath.pathfinder.CollisionMap;
import shortestpath.pathfinder.PathStep;
import shortestpath.pathfinder.TransportAvailabilityFixture;
import shortestpath.transport.Transport;
import shortestpath.transport.TransportType;

/** Global teleports are castable only where their own wilderness limit allows, as in legacy. */
public class WildernessGlobalTeleportTest
{
	private static final int OUTSIDE = WorldPointUtil.packWorldPoint(3200, 3400, 0);
	private static final int LEVEL_13 = WorldPointUtil.packWorldPoint(3156, 3620, 0);
	private static final int LEVEL_25 = WorldPointUtil.packWorldPoint(3200, 3712, 0);
	private static final int LEVEL_31 = WorldPointUtil.packWorldPoint(3200, 3760, 0);
	private static final int TARGET = WorldPointUtil.packWorldPoint(2658, 3157, 0);
	private static final int WALK = 50;
	private static final int TELEPORT = 2;

	@Test
	public void preparedGlobalsFollowEachTeleportsLimit()
	{
		Transport limit0 = teleport(WorldPointUtil.packWorldPoint(1000, 1000, 0), 0);
		Transport limit20 = teleport(WorldPointUtil.packWorldPoint(1001, 1000, 0), 20);
		Transport limit30 = teleport(WorldPointUtil.packWorldPoint(1002, 1000, 0), 30);
		Transport seasonal = new Transport.TransportBuilder().destination(WorldPointUtil.packWorldPoint(1003, 1000, 0))
			.type(TransportType.SEASONAL_TRANSPORTS).duration(TELEPORT).maxWildernessLevel(60).build();
		PreparedRoutingAccount account = account(limit0, limit20, limit30, seasonal);

		// location -> {limit 0, limit 20, limit 30, seasonal (not a teleport type)}
		assertCastable(account, OUTSIDE, true, true, true, true);
		assertCastable(account, LEVEL_13, false, true, true, true);
		assertCastable(account, LEVEL_25, false, false, true, true);
		assertCastable(account, LEVEL_31, false, false, false, true);
	}

	@Test
	public void levelZeroTeleportIsNotCastAfterAnObeliskToLevel13()
	{
		// Deep wilderness start, obelisk to the level-13 landing: Fishing Trawler (level 0) is not castable there.
		Transport obelisk = local(LEVEL_31, LEVEL_13, 1);
		AStarForwardSearch.Result result = search(LEVEL_31, obelisk, local(LEVEL_13, TARGET, WALK), teleport(TARGET, 0));

		assertEquals(1 + WALK, result.cost());
		assertEquals(List.of(LEVEL_31, LEVEL_13, TARGET), tiles(result));
	}

	@Test
	public void level20TeleportIsCastAfterAnObeliskToLevel13()
	{
		AStarForwardSearch.Result result = search(LEVEL_31, local(LEVEL_31, LEVEL_13, 1), local(LEVEL_13, TARGET, WALK),
			teleport(TARGET, 20));

		assertEquals(1 + TELEPORT, result.cost());
	}

	@Test
	public void startingAtLevel13CastsOnlyTeleportsUsableThere()
	{
		assertEquals(WALK, search(LEVEL_13, local(LEVEL_13, TARGET, WALK), teleport(TARGET, 0)).cost());
		assertEquals(TELEPORT, search(LEVEL_13, local(LEVEL_13, TARGET, WALK), teleport(TARGET, 20)).cost());
		assertEquals(TELEPORT, search(LEVEL_13, local(LEVEL_13, TARGET, WALK), teleport(TARGET, 30)).cost());
	}

	@Test
	public void level25CastsOnlyLevel30Teleports()
	{
		assertEquals(WALK, search(LEVEL_25, local(LEVEL_25, TARGET, WALK), teleport(TARGET, 0)).cost());
		assertEquals(WALK, search(LEVEL_25, local(LEVEL_25, TARGET, WALK), teleport(TARGET, 20)).cost());
		assertEquals(TELEPORT, search(LEVEL_25, local(LEVEL_25, TARGET, WALK), teleport(TARGET, 30)).cost());
		// Reached rather than started at.
		assertEquals(1 + WALK, search(LEVEL_31, local(LEVEL_31, LEVEL_25, 1), local(LEVEL_25, TARGET, WALK),
			teleport(TARGET, 20)).cost());
		assertEquals(1 + TELEPORT, search(LEVEL_31, local(LEVEL_31, LEVEL_25, 1), local(LEVEL_25, TARGET, WALK),
			teleport(TARGET, 30)).cost());
	}

	@Test
	public void aboveLevel30NoTeleportIsCast()
	{
		for (int limit : new int[] {0, 20, 30})
			assertEquals("limit " + limit, WALK,
				search(LEVEL_31, local(LEVEL_31, TARGET, WALK), teleport(TARGET, limit)).cost());
	}

	@Test
	public void outsideTheWildernessEveryTeleportIsCast()
	{
		for (int limit : new int[] {0, 20, 30})
			assertEquals("limit " + limit, TELEPORT,
				search(OUTSIDE, local(OUTSIDE, TARGET, WALK), teleport(TARGET, limit)).cost());
	}

	private static void assertCastable(PreparedRoutingAccount account, int location, boolean... expected)
	{
		TeleportCapability capability = TeleportCapability.at(location);
		Set<Integer> castable = new HashSet<>();
		for (int i = 0; i < account.globalCount(capability, BankVisitState.CARRIED); i++)
			castable.add(account.globalDestination(capability, BankVisitState.CARRIED, i));
		for (int i = 0; i < expected.length; i++)
			assertEquals(capability + " destination " + i, expected[i],
				castable.contains(WorldPointUtil.packWorldPoint(1000 + i, 1000, 0)));
	}

	private static AStarForwardSearch.Result search(int start, Transport... transports)
	{
		PreparedRoutingAccount account = account(transports);
		TargetOverlay target = new TargetOverlay(new SiteGraph(routingStatic(), account), emptyCollision(), TARGET);
		AStarForwardSearch.Result result = AStarForwardSearch.search(target,
			PreparedHeuristic.prepare(target, ReverseLabelsOracle.compute(target)), start);
		assertTrue(result.reached());
		AStarForwardSearch.Result oracle = AStarForwardSearch.search(target,
			PreparedHeuristic.prepare(target, ReverseLabelsOracle.compute(target)), start, () -> false, false, 1, SearchRestrictions.none(), AStarForwardSearch.NO_PROGRESS);
		assertEquals("optimised search agrees with the unoptimised one", oracle.cost(), result.cost());
		return result;
	}

	private static List<Integer> tiles(AStarForwardSearch.Result result)
	{
		return result.path().stream().map(PathStep::getPackedPosition).collect(java.util.stream.Collectors.toList());
	}

	private static PreparedRoutingAccount account(Transport... transports)
	{
		return PreparedRoutingAccount.compile(TransportAvailabilityFixture.of(transports),
			TransportAvailabilityFixture.of(), false, Set.of(), 0, true, ignored -> 0);
	}

	private static Transport local(int origin, int destination, int cost)
	{
		return new Transport.TransportBuilder().origin(origin).destination(destination)
			.type(TransportType.TRANSPORT).duration(cost).build();
	}

	private static Transport teleport(int destination, int maxWildernessLevel)
	{
		return new Transport.TransportBuilder().destination(destination).type(TransportType.TELEPORTATION_MINIGAME)
			.duration(TELEPORT).maxWildernessLevel(maxWildernessLevel).build();
	}

	/** One site per tile, no walking: every move is a transport. */
	private static RoutingStatic routingStatic()
	{
		int[] sites = {OUTSIDE, LEVEL_13, LEVEL_25, LEVEL_31, TARGET};
		sites = Arrays.stream(sites).map(t -> t ^ Integer.MIN_VALUE).sorted().map(t -> t ^ Integer.MIN_VALUE).toArray();
		int n = sites.length;
		int[] offsets = new int[n + 1], ids = new int[n], members = new int[n];
		for (int i = 0; i <= n; i++) offsets[i] = i;
		for (int i = 0; i < n; i++) members[i] = i;
		try
		{
			return RoutingStaticTestFixture.takeOwnershipWithNetwork(new int[0], new TileComponents(0, 1), new byte[0],
				new char[0], new char[0], sites, offsets,
				ids, 1, new int[] {0, n}, members, new int[0], new int[0], new int[0], new int[0]);
		}
		catch (java.io.IOException e)
		{
			throw new AssertionError(e);
		}
	}

	private static CollisionMap emptyCollision()
	{
		return new CollisionMap(null)
		{
			@Override public int[] ordinaryWalkingNeighbors(int packedPoint)
			{ return new int[0];
			}
			@Override public boolean isBlocked(int x, int y, int z)
			{ return false;
			}
		};
	}
}

package shortestpath.pathfinder.sailing;

import java.util.List;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import net.runelite.api.gameval.DBTableID;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import static org.mockito.ArgumentMatchers.any;
import org.mockito.Mock;
import static org.mockito.Mockito.when;
import org.mockito.junit.MockitoJUnitRunner;
import shortestpath.TestShortestPathConfig;
import shortestpath.settings.TeleportationItem;
import shortestpath.WorldPointUtil;
import shortestpath.pathfinder.BankVisitState;
import shortestpath.pathfinder.CollisionMap;
