@RunWith(MockitoJUnitRunner.Silent.class)
public class BoatHullTest
{
	// The game's bounds for each boat, in local units: across, along (negative is toward the bow), width, length
	private static final int[] RAFT = {0, 0, 128, 384};
	private static final int[] SKIFF = {0, 0, 256, 640};
	private static final int[] SLOOP = {0, -256, 384, 1280};
	private static final int SOUTH = 0;
	private static final int WEST = 4;
	private static final int NORTH = 8;
	private static final int NORTH_NORTH_EAST = 9;
	private static final int EAST = 12;
	// From the harbour at the Ruins of Unkah to the top of the Elid Delta, past the small islands south of Sophanem
	private static final int UNKAH_HARBOUR = WorldPointUtil.packWorldPoint(3143, 2847, 0);
	private static final int TOP_OF_ELID_DELTA = WorldPointUtil.packWorldPoint(3273, 2738, 0);

	@Mock
	Client client;
	private TestShortestPathConfig config = new TestShortestPathConfig();
	private PathfinderConfig pathfinderConfig;
	private CollisionMap map;

	@Before
	public void before()
	{
		config.set("calculationCutoff", 30);
		config.set("currencyThreshold", 10000000);
		config.set("useTeleportationItems", TeleportationItem.NONE);
		when(client.getDBTableRows(DBTableID.Quest.ID)).thenReturn(List.of());
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getClientThread()).thenReturn(Thread.currentThread());
		when(client.getBoostedSkillLevel(any(Skill.class))).thenReturn(99);
		pathfinderConfig = new TestPathfinderConfig(client, config);
		pathfinderConfig.refresh();
		map = pathfinderConfig.getMap();
	}

	@Test
	public void testSloopFitsAThreeTileGapOnlyWhenLinedUp()
	{
		// Rocks at (2630, 2548) and (2634, 2548) south of Pest Control leave a gap three tiles wide, which a sloop
		// fits through sailing straight north with the boat on a tile centre, touching the rocks either side. In game
		// it only gets through from that spot: from the 3 others across its tile it stops at the rocks
		assertTrue(hull(SLOOP, 0, 0).canMove(map, 2632, 2538, 0, NORTH, 0, 12));
		assertFalse("A quarter tile off centre", hull(SLOOP, -32, 0).canMove(map, 2632, 2538, 0, NORTH, 0, 12));
		assertFalse("A quarter tile the other way", hull(SLOOP, 32, 0).canMove(map, 2632, 2538, 0, NORTH, 0, 12));
		assertFalse("On the tile's west edge", hull(SLOOP, -64, 0).canMove(map, 2632, 2538, 0, NORTH, 0, 12));
		assertFalse("Turned a heading", hull(SLOOP, 0, 0).canMove(map, 2632, 2538, 0, NORTH_NORTH_EAST, 0, 12));
	}

	@Test
	public void testOnlyARaftFitsAOneTileChannel()
	{
		// Rocks either side of x 2796 from y 2962 to 2967 leave a channel one tile wide
		assertTrue(hull(RAFT, 0, 0).canMove(map, 2796, 2963, 0, NORTH, 0, 5));
		assertFalse(hull(SKIFF, 0, 0).canMove(map, 2796, 2963, 0, NORTH, 0, 5));
	}

	@Test
	public void testSkiffFitsPastTheLumSteppingStoneOnlyOnItsTilesSouthEdge()
	{
		// The channel between the Lum Lagoon and the Lumbridge Basin has an Agility shortcut's stepping stone in it at
		// (3214, 3135), with 2 tiles of water between it and the bank to the south. A skiff sailing east along the row
		// just south of the stone fits between them only sitting on its tile's south edge, as in game
		assertTrue(hull(SKIFF, 0, -64).canMove(map, 3207, 3134, 0, EAST, 13, 0));
		assertFalse(hull(SKIFF, 0, -32).canMove(map, 3207, 3134, 0, EAST, 13, 0));
		assertFalse(hull(SKIFF, 0, 0).canMove(map, 3207, 3134, 0, EAST, 13, 0));
		assertFalse(hull(SKIFF, 0, 32).canMove(map, 3207, 3134, 0, EAST, 13, 0));
	}

	@Test
	public void testHullCoversTheTilesUnderIt()
	{
		// A raft is a tile wide and 3 long, so sitting on a tile it covers that tile and the ones fore and aft
		assertTrue(hull(RAFT, 0, 0).covers(NORTH, 0, 1));
		assertTrue(hull(RAFT, 0, 0).covers(NORTH, 0, -1));
		assertFalse(hull(RAFT, 0, 0).covers(NORTH, 1, 0));
		assertTrue(hull(RAFT, 0, 0).covers(EAST, 1, 0));
		assertFalse(hull(RAFT, 0, 0).covers(EAST, 0, 1));
	}

	@Test
	public void testSloopRouteKeepsItsWholeHullClear()
	{
		// From open sea past the rocks off Mudskipper Point to the water off the Pandemonium
		SailingMoves moves = SailingMoves.forSpeed(3.0);
		int start = WorldPointUtil.packWorldPoint(2948, 3074, 0);
		int target = WorldPointUtil.packWorldPoint(3074, 2983, 0);

		List<PathStep> pointPath = findPath(start, target, moves, null);
		List<PathStep> sloopPath = findPath(start, target, moves, hull(SLOOP, 0, 0));

		assertNotNull("Steering only the boat's centre clear takes a sloop over rocks", hullHit(pointPath, moves, 1.5, 3, 7));
		assertNull(hullHit(sloopPath, moves, 1.5, 3, 7));
	}

	@Test
	public void testSloopEndsWithItsHullOverAnOpenSeaTarget()
	{
		// Open sea between Rimmington and Karamja
		SailingMoves moves = SailingMoves.forSpeed(1.5);
		int target = WorldPointUtil.packWorldPoint(2963, 3109, 0);
		List<PathStep> path = findPath(WorldPointUtil.packWorldPoint(2948, 3074, 0), target, moves, hull(SLOOP, 0, 0));

		assertTrue(endsCovering(path, moves, hull(SLOOP, 0, 0), target));
	}

	@Test
	public void testRaftGetsPastTheElidDeltaIslands()
	{
		SailingMoves moves = SailingMoves.forSpeed(1.5);
		List<PathStep> path = findPath(UNKAH_HARBOUR, TOP_OF_ELID_DELTA, moves, hull(RAFT, 0, 0));

		assertTrue(endsCovering(path, moves, hull(RAFT, 0, 0), TOP_OF_ELID_DELTA));
		assertNull(hullHit(path, moves, 0.5, 1.5, 1.5));
	}

	@Test
	public void testSloopCantGetPastTheElidDeltaIslands()
	{
		// As in game, the channels between the islands are too narrow for a sloop
		SailingPathfinder pathfinder = new SailingPathfinder(pathfinderConfig, UNKAH_HARBOUR, Set.of(TOP_OF_ELID_DELTA),
			null, SailingMoves.forSpeed(1.5), hull(SLOOP, 0, 0));
		pathfinder.run();

		assertFalse(pathfinder.getResult().isReached());
	}

	@Test
	public void testBoatSailsOutOfTilesItsHullSitsOn()
	{
		// Moored on the 3x2 shipwreck at (2704-2706, 3050-3051), a raft's hull overlaps blocked tiles
		// where it starts; like a boat on a blocked tile it can sail out of them with its first move,
		// but not over other blocked tiles its hull doesn't already cover
		BoatHull raft = hull(RAFT, 0, 0);
		assertTrue("North over the wreck row its hull sits on", raft.canMove(map, 2705, 3050, 0, NORTH, 0, 3, true));
		assertTrue("South out of the wreck", raft.canMove(map, 2705, 3050, 0, SOUTH, 0, -3, true));
		assertFalse("Only the first move gets the escape", raft.canMove(map, 2705, 3050, 0, NORTH, 0, 3));
		assertFalse("Facing along the wreck, its hull doesn't cover the other row",
			raft.canMove(map, 2705, 3050, 0, WEST, 0, 3, true));

		int start = WorldPointUtil.packWorldPoint(2705, 3050, 0);
		int target = WorldPointUtil.packWorldPoint(2705, 3042, 0);
		findPath(start, target, SailingMoves.forSpeed(1.5), raft);
	}

	@Test
	public void testSailingSearchesWhenNoGoalIsViable()
	{
		// A target on the shipwreck is blocked, and with the unreachable distance at 0 it resolves to
		// no goal tiles: a walking search is skipped outright, but a sailing search still runs — its
		// hull covering the target doesn't need a walkable goal tile
		config.set("unreachableTargetDistanceThreshold", 0);
		pathfinderConfig.refresh();
		int start = WorldPointUtil.packWorldPoint(2705, 3044, 0);
		int target = WorldPointUtil.packWorldPoint(2705, 3050, 0);

		Pathfinder walking = new Pathfinder(pathfinderConfig, start, Set.of(target));
		walking.run();
		assertEquals(0, walking.getResult().getNodesChecked());

		SailingPathfinder sailing = new SailingPathfinder(pathfinderConfig, start, Set.of(target), null,
			SailingMoves.forSpeed(1.5), hull(RAFT, 0, 0));
		sailing.run();
		assertTrue(sailing.getResult().getNodesChecked() > 0);
	}

	@Test
	public void testACostlierMoveStillQueuesWhenItWouldArrive()
	{
		// With the target a tile east, a raft only covers it facing east: if the cheapest route to
		// that tile faces another way, a costlier move facing east must still be queued
		SailingMoves moves = SailingMoves.forSpeed(1.5);
		int target = WorldPointUtil.packWorldPoint(2706, 3049, 0);
		SailingSearch search = new SailingSearch(moves, hull(RAFT, 0, 0), new int[]{target}, new int[]{target});

		int tile = WorldPointUtil.packWorldPoint(2705, 3049, 0);
		int eastMove = moves.indexOf(3, 0);
		int northMove = moves.indexOf(0, 3);
		assertTrue(search.queueArrival(tile, eastMove, 2705, 3049, 0, BankVisitState.CARRIED));
		assertFalse("A move is only let through once", search.queueArrival(tile, eastMove, 2705, 3049, 0, BankVisitState.CARRIED));
		assertFalse("Facing north doesn't cover the target", search.queueArrival(tile, northMove, 2705, 3049, 0, BankVisitState.CARRIED));
		assertFalse("Without a hull, facing doesn't matter", new SailingSearch(moves, null, new int[]{target},
			new int[]{target}).queueArrival(tile, eastMove, 2705, 3049, 0, BankVisitState.CARRIED));
	}

	@Test
	public void testTheStartNodeFacesTheWayTheBoatDoes()
	{
		// The start node has no move to face, so it faces the heading the boat was pointing where the
		// route began; a tile a move reached faces the way it sailed there
		SailingMoves moves = SailingMoves.ESTIMATE;
		NodeGraph graph = new NodeGraph(4);
		int start = graph.createStart(WorldPointUtil.packWorldPoint(2948, 3074, 0));
		int move = moves.indexOf(2, 0);
		int node = graph.createWeightedTile(WorldPointUtil.packWorldPoint(2950, 3074, 0), start, 2000, 0,
			BankVisitState.CARRIED, move);

		SailingSearch facingSouth = new SailingSearch(moves, null, new int[0], new int[0], SOUTH);
		assertEquals(SOUTH, facingSouth.arrivalHeading(graph, start));
		assertEquals("A move's own heading wins", EAST, facingSouth.arrivalHeading(graph, node));

		SailingSearch facingUnknown = new SailingSearch(moves, null, new int[0], new int[0]);
		assertEquals("An unknown start heading still tries them all", WorldPointUtil.UNDEFINED,
			facingUnknown.arrivalHeading(graph, start));
	}

	@Test
	public void testAStartTargetCountsOnlyOnTheBoatsHeading()
	{
		// A sloop reaches 7 tiles toward its bow but only 3 astern: a target 5 tiles north is under the
		// hull only facing north
		int here = WorldPointUtil.packWorldPoint(2948, 3074, 0);
		int[] target = {WorldPointUtil.packWorldPoint(2948, 3079, 0)};
		SailingSearch search = new SailingSearch(SailingMoves.ESTIMATE, hull(SLOOP, 0, 0), target, target);

		assertEquals("Facing south the target is astern, out of the hull", WorldPointUtil.UNDEFINED,
			search.arrivedTarget(here, SOUTH));
		assertEquals("Facing north it's under the bow", target[0], search.arrivedTarget(here, NORTH));
		assertEquals("Unknown heading tries them all", target[0],
			search.arrivedTarget(here, WorldPointUtil.UNDEFINED));
	}

	@Test
	public void testASailingSearchDoesNotArriveOnTheSpotBehindTheStern()
	{
		// Aboard at (2948, 3074) facing south, the target at (2948, 3079) is under the hull only facing
		// north: the search must sail away rather than ending with the boat still on the spot, which is
		// what trying every heading at the start did
		int start = WorldPointUtil.packWorldPoint(2948, 3074, 0);
		int target = WorldPointUtil.packWorldPoint(2948, 3079, 0);

		SailingPathfinder astern = new SailingPathfinder(pathfinderConfig, start, Set.of(target), null,
			SailingMoves.forSpeed(1.5), hull(SLOOP, 0, 0), SOUTH);
		astern.run();
		assertFalse("Arrived on the spot facing away from the target",
			astern.getResult().isReached() && astern.getPath().size() <= 1);
		assertTrue("But still reached it by sailing", astern.getResult().isReached());
		assertTrue(astern.getPath().size() > 1);

		SailingPathfinder facing = new SailingPathfinder(pathfinderConfig, start, Set.of(target), null,
			SailingMoves.forSpeed(1.5), hull(SLOOP, 0, 0), NORTH);
		facing.run();
		assertTrue(facing.getResult().isReached());
		assertEquals("A target already under the bow still arrives on the spot", 1, facing.getPath().size());

		SailingPathfinder noHeading = new SailingPathfinder(pathfinderConfig, start, Set.of(target), null,
			SailingMoves.forSpeed(1.5), hull(SLOOP, 0, 0));
		noHeading.run();
		assertTrue(noHeading.getResult().isReached());
		assertEquals("An unknown heading still counts an under-hull target as arrived", 1,
			noHeading.getPath().size());
	}

	@Test
	public void testRaftSailsOutOfTheLumLagoon()
	{
		// West out of the Lum Lagoon through the channel past the stepping stone (see above)
		SailingMoves moves = SailingMoves.forSpeed(1.5);
		int west = WorldPointUtil.packWorldPoint(3196, 3125, 0);
		List<PathStep> path = findPath(WorldPointUtil.packWorldPoint(3229, 3124, 0), west, moves, hull(RAFT, 0, 0));

		assertTrue(endsCovering(path, moves, hull(RAFT, 0, 0), west));
		assertNull(hullHit(path, moves, 0.5, 1.5, 1.5));
	}

	// The boat sitting (pivotX, pivotY) local units from the centre of its tile
	private static BoatHull hull(int[] bounds, int pivotX, int pivotY)
	{
		return BoatHull.fromBounds(bounds[0], bounds[1], bounds[2], bounds[3], pivotX, pivotY);
	}

	// Whether the boat's hull, where the path ends and facing the way it sailed there, covers the target
	private static boolean endsCovering(List<PathStep> path, SailingMoves moves, BoatHull hull, int target)
	{
		int from = path.get(path.size() - 2).getPackedPosition();
		int end = path.get(path.size() - 1).getPackedPosition();
		int heading = moves.headingOf(WorldPointUtil.unpackWorldX(end) - WorldPointUtil.unpackWorldX(from),
			WorldPointUtil.unpackWorldY(end) - WorldPointUtil.unpackWorldY(from));
		return hull.covers(heading, WorldPointUtil.unpackWorldX(target) - WorldPointUtil.unpackWorldX(end),
			WorldPointUtil.unpackWorldY(target) - WorldPointUtil.unpackWorldY(end));
	}

	private List<PathStep> findPath(int start, int target, SailingMoves moves, BoatHull hull)
	{
		SailingPathfinder pathfinder = new SailingPathfinder(pathfinderConfig, start, Set.of(target), null, moves, hull);
		pathfinder.run();
		assertTrue("Target should be reachable", pathfinder.getResult().isReached());
		return pathfinder.getPath();
	}

	// Checks every move independently of BoatHull: samples the hull's rectangle every quarter tile along the move and
	// tests it against each nearby tile's square, allowing edges to touch. Describes the first blocked tile the hull runs
	// over, or returns null if there are none.
	private String hullHit(List<PathStep> path, SailingMoves moves, double halfWidth, double stern, double bow)
	{
		for (int i = 1; i < path.size(); i++)
		{
			int from = path.get(i - 1).getPackedPosition();
			int to = path.get(i).getPackedPosition();
			int x = WorldPointUtil.unpackWorldX(from);
			int y = WorldPointUtil.unpackWorldY(from);
			int dx = WorldPointUtil.unpackWorldX(to) - x;
			int dy = WorldPointUtil.unpackWorldY(to) - y;
			double angle = moves.headingOf(dx, dy) * Math.PI / 8;
			double forwardX = -Math.sin(angle);
			double forwardY = -Math.cos(angle);
			double halfLength = (stern + bow) / 2;
			int samples = (int) Math.ceil(Math.hypot(dx, dy) * 4);
			for (int s = 0; s <= samples; s++)
			{
				double centreX = x + dx * (double) s / samples + forwardX * (bow - stern) / 2;
				double centreY = y + dy * (double) s / samples + forwardY * (bow - stern) / 2;
				for (int tileX = (int) centreX - 8; tileX <= (int) centreX + 8; tileX++)
				{
					for (int tileY = (int) centreY - 8; tileY <= (int) centreY + 8; tileY++)
					{
						double ex = centreX - tileX;
						double ey = centreY - tileY;
						boolean overlaps = Math.abs(ex) < 0.5 + halfLength * Math.abs(forwardX) + halfWidth * Math.abs(forwardY) - 1e-9
							&& Math.abs(ey) < 0.5 + halfLength * Math.abs(forwardY) + halfWidth * Math.abs(forwardX) - 1e-9
							&& Math.abs(ex * forwardX + ey * forwardY) < halfLength + 0.5 * (Math.abs(forwardX) + Math.abs(forwardY)) - 1e-9
							&& Math.abs(ey * forwardX - ex * forwardY) < halfWidth + 0.5 * (Math.abs(forwardX) + Math.abs(forwardY)) - 1e-9;
						if (overlaps && map.isBlocked(tileX, tileY, 0))
						{
							return "Move " + i + " from (" + x + ", " + y + ") runs the hull over blocked tile (" + tileX + ", " + tileY + ")";
						}
					}
				}
			}
		}
		return null;
	}
}

package shortestpath.pathfinder.sailing;

import java.util.List;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import net.runelite.api.gameval.DBTableID;
import net.runelite.api.gameval.VarbitID;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import static org.mockito.ArgumentMatchers.any;
import org.mockito.Mock;
import static org.mockito.Mockito.when;
import org.mockito.junit.MockitoJUnitRunner;
import shortestpath.TestShortestPathConfig;
import shortestpath.settings.TeleportationItem;
import shortestpath.WorldPointUtil;
import shortestpath.pathfinder.CollisionMap;
import shortestpath.pathfinder.PathStep;
import shortestpath.pathfinder.Pathfinder;
import shortestpath.pathfinder.PathfinderConfig;
import shortestpath.pathfinder.TestPathfinderConfig;

@RunWith(MockitoJUnitRunner.Silent.class)
public class SailingMovesTest
{
	// (2946, 3072) to (2971, 3117) is open sea between Rimmington and Karamja
	private static final int OPEN_SEA_START = WorldPointUtil.packWorldPoint(2948, 3074, 0);

	@Mock
	Client client;
	private TestShortestPathConfig config = new TestShortestPathConfig();
	private PathfinderConfig pathfinderConfig;

	@Before
	public void before()
	{
		config.set("calculationCutoff", 30);
		config.set("currencyThreshold", 10000000);
		config.set("useTeleportationItems", TeleportationItem.NONE);
		when(client.getDBTableRows(DBTableID.Quest.ID)).thenReturn(List.of());
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getClientThread()).thenReturn(Thread.currentThread());
		when(client.getBoostedSkillLevel(any(Skill.class))).thenReturn(99);
		pathfinderConfig = new TestPathfinderConfig(client, config);
		pathfinderConfig.refresh();
	}

	@Test
	public void testEstimateUsesTheGameHeadingsAtSpeedTwo()
	{
		SailingMoves moves = SailingMoves.ESTIMATE;
		assertEquals(16, moves.size());
		// Per tick at speed 2 the game moves N (0,8), NNE (3,7), NE (6,6), ENE (7,3), E (8,0) quarter tiles
		assertMove(moves, "N", 0, 2, 1);
		assertMove(moves, "NNE", 3, 7, 4);
		assertMove(moves, "NE", 3, 3, 2);
		assertMove(moves, "ENE", 7, 3, 4);
		assertMove(moves, "E", 2, 0, 1);
		assertMove(moves, "SSW", -3, -7, 4);
	}

	@Test
	public void testHeadingsDependOnSpeed()
	{
		// NNE is (2,6) quarter tiles per tick at speed 1.5 and (5,13) at 3.5; NE is (9,9) at 3
		assertMove(SailingMoves.forSpeed(1.5), "NNE", 1, 3, 2);
		assertMove(SailingMoves.forSpeed(3.5), "NNE", 5, 13, 4);
		assertMove(SailingMoves.forSpeed(3.0), "NE", 9, 9, 4);
	}

	@Test
	public void testSailingSpeedIsTheBoatsBaseSpeed()
	{
		when(client.getVarbitValue(VarbitID.SAILING_SIDEPANEL_BOAT_BASESPEED)).thenReturn(192);
		pathfinderConfig.refresh();
		assertEquals(1.5, pathfinderConfig.getSailingSpeed(), 0);

		when(client.getVarbitValue(VarbitID.SAILING_SIDEPANEL_BOAT_BASESPEED)).thenReturn(0);
		pathfinderConfig.refresh();
		assertEquals("Falls back to the estimate", SailingMoves.ESTIMATED_SPEED, pathfinderConfig.getSailingSpeed(), 0);
	}

	@Test
	public void testAVeryLowSpeedFallsBackToTheEstimate()
	{
		// Below about 0.125 tiles per tick every heading rounds to no movement; a garbage or stale
		// base-speed reading falls back to the estimate rather than sailing nowhere
		assertSame(SailingMoves.ESTIMATE, SailingMoves.forSpeed(0.01));
	}

	@Test
	public void testAnImpossibleSpeedFallsBackToTheEstimate()
	{
		// The moves a far-too-fast reading builds are so long every leg clips a blocked tile and the
		// search ends at once, so like a negative or NaN one it falls back to the estimate
		assertSame(SailingMoves.ESTIMATE, SailingMoves.forSpeed(512));
		assertSame(SailingMoves.ESTIMATE, SailingMoves.forSpeed(SailingMoves.MAX_SPEED + 1));
		assertSame(SailingMoves.ESTIMATE, SailingMoves.forSpeed(-1));
		assertSame(SailingMoves.ESTIMATE, SailingMoves.forSpeed(Double.NaN));
		assertSame(SailingMoves.ESTIMATE, SailingMoves.forSpeed(0));
		assertTrue(SailingMoves.forSpeed(SailingMoves.MAX_SPEED).size() > 0);
	}

	@Test
	public void testAStaleOrMisScaledBaseSpeedFallsBackToTheEstimate()
	{
		// The side-panel varbit is in 1/128ths of a tile per tick: a stale or mis-scaled read far above
		// a real boat's speed is not a faster boat
		when(client.getVarbitValue(VarbitID.SAILING_SIDEPANEL_BOAT_BASESPEED)).thenReturn(65536);
		pathfinderConfig.refresh();
		assertEquals(SailingMoves.ESTIMATED_SPEED, pathfinderConfig.getSailingSpeed(), 0);

		when(client.getVarbitValue(VarbitID.SAILING_SIDEPANEL_BOAT_BASESPEED)).thenReturn((int) (SailingMoves.MAX_SPEED * 128));
		pathfinderConfig.refresh();
		assertEquals("The fastest real speed still counts", SailingMoves.MAX_SPEED,
			pathfinderConfig.getSailingSpeed(), 0);

		when(client.getVarbitValue(VarbitID.SAILING_SIDEPANEL_BOAT_BASESPEED)).thenReturn((int) (SailingMoves.MAX_SPEED * 128) + 1);
		pathfinderConfig.refresh();
		assertEquals("Just above it does not", SailingMoves.ESTIMATED_SPEED, pathfinderConfig.getSailingSpeed(), 0);
	}

	@Test
	public void testOpenSeaTakesTheDirectHeading()
	{
		// 15 across and 35 up is 5 NNE moves (38 tiles); N, N, NE five times takes as long but sails 41 tiles
		List<PathStep> path = findPath(OPEN_SEA_START, WorldPointUtil.packWorldPoint(2963, 3109, 0), SailingMoves.ESTIMATE);

		assertEquals(6, path.size());
		for (int i = 1; i < path.size(); i++)
		{
			assertEquals("Move " + i + " should be NNE", "NNE", SailingMoves.ESTIMATE.name(moveIndex(path, i)));
		}
	}

	@Test
	public void testRouteAroundLandOnlyUsesBoatHeadings()
	{
		// Port Sarim to The Pandemonium, around Mudskipper Point
		List<PathStep> path = findPath(WorldPointUtil.packWorldPoint(3048, 3184, 0), WorldPointUtil.packWorldPoint(3069, 2983, 0),
			SailingMoves.ESTIMATE);

		for (int i = 1; i < path.size(); i++)
		{
			assertNotEquals("Move " + i + " should be a boat heading", -1, SailingMoves.ESTIMATE.headingOf(dx(path, i), dy(path, i)));
			assertNull("Move " + i + " should not pass over a blocked tile", blockedOnLine(path, i));
		}
	}

	@Test
	public void testSearchWithoutSailingMovesStillWalks()
	{
		int start = OPEN_SEA_START;
		int target = WorldPointUtil.packWorldPoint(2968, 3114, 0);
		Pathfinder pathfinder = new Pathfinder(pathfinderConfig, start, Set.of(target));
		pathfinder.run();
		assertTrue("Target should be reachable", pathfinder.getResult().isReached());
		List<PathStep> path = pathfinder.getPath();

		assertEquals("40 walking steps plus the start tile", 41, path.size());
		for (int i = 1; i < path.size(); i++)
		{
			assertEquals("Step " + i + " should move one tile", 1, Math.max(Math.abs(dx(path, i)), Math.abs(dy(path, i))));
		}
	}

	@Test
	public void testRouteGoesAroundObstacles()
	{
		// A 3x2 shipwreck at (2704-2706, 3050-3051) in open sea blocks the straight line between these points
		int start = WorldPointUtil.packWorldPoint(2705, 3044, 0);
		int target = WorldPointUtil.packWorldPoint(2705, 3057, 0);
		SailingMoves moves = SailingMoves.forSpeed(1.5);

		List<PathStep> path = findPath(start, target, moves);

		assertTrue("Should leave the straight line north, which runs into the wreck",
			path.stream().anyMatch(step -> WorldPointUtil.unpackWorldX(step.getPackedPosition()) != 2705));
		for (int i = 1; i < path.size(); i++)
		{
			assertNotEquals("Move " + i + " should be a boat heading", -1, moves.headingOf(dx(path, i), dy(path, i)));
			assertNull("Move " + i + " should not pass over the shipwreck", blockedOnLine(path, i));
		}
	}

	@Test
	public void testArrivesNextToATargetTheBoatCantStopOn()
	{
		// At speed 2 every move goes an even number of tiles across and up together, so 15 across and 16 up is out of reach
		int target = WorldPointUtil.packWorldPoint(2963, 3090, 0);
		List<PathStep> path = findPath(OPEN_SEA_START, target, SailingMoves.ESTIMATE);

		assertEquals("Ends next to the target", 1, WorldPointUtil.distanceBetween(target, last(path)));
		for (int i = 1; i < path.size(); i++)
		{
			assertNotEquals("Move " + i + " should be a boat heading", -1, SailingMoves.ESTIMATE.headingOf(dx(path, i), dy(path, i)));
		}
	}

	@Test
	public void testLinesDontCrossBlockedTiles()
	{
		// A 3x2 shipwreck at (2704-2706, 3050-3051) in open sea
		CollisionMap map = pathfinderConfig.getMap();
		assertTrue(map.isBlocked(2705, 3050, 0));
		assertTrue("Stops short of the wreck", SailingSearch.canSailLine(map, 2705, 3044, 0, 0, 5));
		assertFalse("Runs into the wreck", SailingSearch.canSailLine(map, 2705, 3044, 0, 0, 13));
		assertFalse("Clips the wreck's corner", SailingSearch.canSailLine(map, 2702, 3048, 0, 3, 3));
		// A boat that starts on a blocked tile can sail out of it, but not further into the blocked tiles
		assertTrue("Leaves the wreck", SailingSearch.canSailLine(map, 2705, 3050, 0, 0, -3));
		assertFalse("Stays in the wreck", SailingSearch.canSailLine(map, 2705, 3050, 0, 0, 3));
	}

	@Test
	public void testSailingSkipsBankVisitsAndTransports()
	{
		// The Bank Boat at (2280, 2544) is a bank out at sea. With paths through a bank turned on, a walking search
		// passing it would consider visiting it; a sailing search only sails, since bank visits and transports cost
		// ticks rather than the distance sailed
		config.set("includeBankPath", true);
		pathfinderConfig.refresh();
		assertTrue(pathfinderConfig.bankAccessible(WorldPointUtil.packWorldPoint(2280, 2544, 0)));

		SailingPathfinder pathfinder = new SailingPathfinder(pathfinderConfig, WorldPointUtil.packWorldPoint(2260, 2544, 0),
			Set.of(WorldPointUtil.packWorldPoint(2300, 2548, 0)), null, SailingMoves.ESTIMATE);
		pathfinder.run();

		assertTrue(pathfinder.getResult().isReached());
		assertEquals("No bank visits or transports queued", 0, pathfinder.getResult().getTransportsChecked());
	}

	private List<PathStep> findPath(int start, int target, SailingMoves sailingMoves)
	{
		SailingPathfinder pathfinder = new SailingPathfinder(pathfinderConfig, start, Set.of(target), null, sailingMoves);
		pathfinder.run();
		assertTrue("Target should be reachable", pathfinder.getResult().isReached());
		return pathfinder.getPath();
	}

	// Checks move i independently of CollisionMap#canSailLine: samples the line between the tile centres every
	// twentieth of a tile, and describes the first blocked tile it passes over after the one it starts on, or returns
	// null if there are none
	private String blockedOnLine(List<PathStep> path, int i)
	{
		CollisionMap map = pathfinderConfig.getMap();
		int from = path.get(i - 1).getPackedPosition();
		int x = WorldPointUtil.unpackWorldX(from);
		int y = WorldPointUtil.unpackWorldY(from);
		int z = WorldPointUtil.unpackWorldPlane(from);
		int samples = (int) Math.ceil(Math.hypot(dx(path, i), dy(path, i)) * 20);
		for (int s = 1; s <= samples; s++)
		{
			// Nudged so that a sample never sits exactly on a tile edge
			int tileX = (int) Math.floor(x + dx(path, i) * (double) s / samples + 0.5 + 1e-6);
			int tileY = (int) Math.floor(y + dy(path, i) * (double) s / samples + 0.5 + 1e-7);
			if ((tileX != x || tileY != y) && map.isBlocked(tileX, tileY, z))
			{
				return "(" + tileX + ", " + tileY + ")";
			}
		}
		return null;
	}

	private static void assertMove(SailingMoves moves, String name, int dx, int dy, int ticks)
	{
		int index = moves.indexOf(dx, dy);
		assertNotEquals(name + " should move (" + dx + ", " + dy + ")", -1, index);
		assertEquals(name, moves.name(index));
		assertEquals(name + " ticks", ticks, moves.ticks(index));
	}

	private static int last(List<PathStep> path)
	{
		return path.get(path.size() - 1).getPackedPosition();
	}

	private static int moveIndex(List<PathStep> path, int i)
	{
		return SailingMoves.ESTIMATE.indexOf(dx(path, i), dy(path, i));
	}

	private static int dx(List<PathStep> path, int i)
	{
		return WorldPointUtil.unpackWorldX(path.get(i).getPackedPosition()) - WorldPointUtil.unpackWorldX(path.get(i - 1).getPackedPosition());
	}

	private static int dy(List<PathStep> path, int i)
	{
		return WorldPointUtil.unpackWorldY(path.get(i).getPackedPosition()) - WorldPointUtil.unpackWorldY(path.get(i - 1).getPackedPosition());
	}
}

package shortestpath.poh;

