package shortestpath.presentation;

import java.util.Map;
import java.util.Set;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.when;
import org.mockito.junit.MockitoJUnitRunner;
import shortestpath.PrimitiveIntHashMap;
import shortestpath.WorldPointUtil;
import shortestpath.pathfinder.PathStep;
import shortestpath.pathfinder.BankVisitState;
import shortestpath.pathfinder.PathfinderConfig;
import shortestpath.pathfinder.TestWorldData;
import shortestpath.transport.Transport;

@RunWith(MockitoJUnitRunner.class)
public class TransportsForEdgeTest
{
	private static final Map<Integer, Set<Transport>> TRANSPORTS = TestWorldData.rawTransports();
	private static final int LUMBRIDGE_LANDING = WorldPointUtil.packWorldPoint(3221, 3218, 0);

	@Mock
	PathfinderConfig pathfinderConfig;

	PathAnnotator annotator;

	private Transport lumbridgeTeleport;
	private Transport lumbridgeHomeTeleport;

	@Before
	public void before()
	{
		annotator = PathAnnotatorTestServices.forTesting();
		annotator.attach(pathfinderConfig);
		for (Transport transport : TRANSPORTS.get(Transport.UNDEFINED_ORIGIN))
		{
			if (transport.getDestination() == LUMBRIDGE_LANDING)
			{
				if ("Lumbridge Teleport".equals(transport.getDisplayInfo()) && lumbridgeTeleport == null)
				{
					lumbridgeTeleport = transport;
				}
				else if ("Lumbridge Home Teleport".equals(transport.getDisplayInfo()) && lumbridgeHomeTeleport == null)
				{
					lumbridgeHomeTeleport = transport;
				}
			}
		}
		Assert.assertNotNull(lumbridgeTeleport);
		Assert.assertNotNull(lumbridgeHomeTeleport);
	}

	private void mockTeleports(Transport... teleports)
	{
		when(pathfinderConfig.getUsableTeleports(any(BankVisitState.class))).thenReturn(teleports);
	}

	private void mockLocalTransports(int origin, Transport... local)
	{
		PrimitiveIntHashMap<Transport[]> packed = new PrimitiveIntHashMap<>(1);
		packed.put(origin, local);
		when(pathfinderConfig.getTransportsPacked(any(BankVisitState.class))).thenReturn(packed);
	}

	private void mockNoLocalTransports()
	{
		when(pathfinderConfig.getTransportsPacked(any(BankVisitState.class))).thenReturn(new PrimitiveIntHashMap<>(0));
	}

	@Test
	public void testWalkedEdgeOntoTeleportLandingShowsNoHint()
	{
		mockTeleports(lumbridgeTeleport, lumbridgeHomeTeleport);
		mockNoLocalTransports();
		// The path walks onto the Lumbridge teleport landing tile — a single-tile
		// edge that cannot be a teleport, so no teleport hint should be produced.
		PathStep from = new PathStep(WorldPointUtil.packWorldPoint(3222, 3218, 0), BankVisitState.CARRIED);
		PathStep to = new PathStep(LUMBRIDGE_LANDING, BankVisitState.CARRIED);
		Assert.assertTrue(annotator.transportsForEdge(from, to).isEmpty());
	}

	@Test
	public void testWalkedEdgeEndingOnTeleportLandingShowsNoHint()
	{
		mockTeleports(lumbridgeTeleport, lumbridgeHomeTeleport);
		mockNoLocalTransports();
		// Same suppression when the landing tile is the last step of the path:
		// the path does not go beyond the tile, so no teleport is used.
		PathStep from = new PathStep(WorldPointUtil.packWorldPoint(3221, 3219, 0), BankVisitState.CARRIED);
		PathStep to = new PathStep(LUMBRIDGE_LANDING, BankVisitState.CARRIED);
		Assert.assertTrue(annotator.transportsForEdge(from, to).isEmpty());
	}

	@Test
	public void testJumpEdgeOntoTeleportLandingKeepsFallback()
	{
		mockTeleports(lumbridgeTeleport, lumbridgeHomeTeleport);
		mockNoLocalTransports();
		// Manually constructed steps carry no transport identity; on an actual
		// jump the teleport remains a candidate.
		PathStep from = new PathStep(WorldPointUtil.packWorldPoint(3200, 3200, 0), BankVisitState.CARRIED);
		PathStep to = new PathStep(LUMBRIDGE_LANDING, BankVisitState.CARRIED);
		Assert.assertEquals(Set.of(lumbridgeTeleport, lumbridgeHomeTeleport), annotator.transportsForEdge(from, to));
	}

	@Test
	public void testRecordedTransportIsReturnedDirectly()
	{
		PathStep from = new PathStep(WorldPointUtil.packWorldPoint(3200, 3200, 0), BankVisitState.CARRIED);
		PathStep to = new PathStep(LUMBRIDGE_LANDING, BankVisitState.CARRIED, lumbridgeTeleport);
		Assert.assertEquals(Set.of(lumbridgeTeleport), annotator.transportsForEdge(from, to));
	}

	@Test
	public void testWalkedEdgeStillReportsLocalTransport()
	{
		// A local transport that moves the player a single tile is still a valid
		// way to traverse a walked edge; only teleports are suppressed.
		Transport adjacentLocal = null;
		for (Map.Entry<Integer, Set<Transport>> entry : TRANSPORTS.entrySet())
		{
			int origin = entry.getKey();
			if (origin == Transport.UNDEFINED_ORIGIN)
			{
				continue;
			}
			for (Transport transport : entry.getValue())
			{
				if ((transport.getType() == null || !transport.getType().isTeleport())
					&& WorldPointUtil.distanceBetween2D(origin, transport.getDestination()) <= 1)
				{
					adjacentLocal = transport;
				}
			}
		}
		Assert.assertNotNull(adjacentLocal);
		mockTeleports(lumbridgeTeleport, lumbridgeHomeTeleport);
		mockLocalTransports(adjacentLocal.getOrigin(), adjacentLocal);
		PathStep from = new PathStep(adjacentLocal.getOrigin(), BankVisitState.CARRIED);
		PathStep to = new PathStep(adjacentLocal.getDestination(), BankVisitState.CARRIED);
		Assert.assertEquals(Set.of(adjacentLocal), annotator.transportsForEdge(from, to));
	}
}

package shortestpath.requirement;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;
import org.junit.Test;
import shortestpath.requirement.model.DestinationRequirements;
import shortestpath.requirement.model.SkillLevels;
import shortestpath.requirement.model.VarCheckType;
import shortestpath.requirement.model.VarRequirement;
import shortestpath.settings.TeleportationItem;
import shortestpath.transport.parser.VarRequirementParser;

/**
 * The bank-destination adapter arm of the middleware: a bank tile's
 * {@link DestinationRequirements} goes through the same
 * {@link Requirements} chain as transports, reading the same refresh
 * snapshot and consulting the same {@link RequirementHooks} seam — a bank
 * tile and a transport can never disagree about the same requirement
 * inside one refresh.
 *
 * <p>The Fortis Colosseum row ({@code 4130>1999}) is the load-bearing
 * real-world case: a strict-greater varplayer gate that must fail closed
 * when the var was never captured.
 */
public class BankRequirementAdapterTest
{
	private static final TeleportationItem MODE = TeleportationItem.INVENTORY;

	private static Requirements requirements(RequirementContext context)
	{
		return RequirementTestFixtures.requirements(context, RequirementTestFixtures.policy(MODE));
	}

	// ------------------------------------------------------------------
	// Empty and absent requirements fast-path.
	// ------------------------------------------------------------------

	@Test
	public void absentAndEmptyRequirementsAreAlwaysSatisfied()
	{
		Requirements requirements = requirements(RequirementTestFixtures.context().build());

		assertTrue(requirements.satisfied(null));
		assertTrue(requirements.satisfied(DestinationRequirements.EMPTY));
		assertEquals(RejectionReason.NONE, requirements.check(DestinationRequirements.EMPTY));

		// A constructed-but-empty requirement is the same fast path: all
		// fields present and empty/zero still count as no requirements.
		DestinationRequirements constructed = new DestinationRequirements(
			SkillLevels.NONE, Set.of(), Set.of(), Set.of());
		assertTrue(constructed.isEmpty());
		assertTrue(requirements.satisfied(constructed));
	}

	// ------------------------------------------------------------------
	// Per-gate coverage through the bank adapter.
	// ------------------------------------------------------------------

	@Test
	public void skillGatedBankFollowsBoostedLevels()
	{
		// Cooks' Guild shape: 99 Cooking.
		int[] skills = new int[SkillLevels.LENGTH];
		skills[Skill.COOKING.ordinal()] = 99;
		DestinationRequirements guild = RequirementTestFixtures.bankRequirements(
			SkillLevels.of(skills), null, null, null);

		assertTrue(requirements(RequirementTestFixtures.context().build()).satisfied(guild));

		int[] below = RequirementTestFixtures.maxedSkills();
		below[Skill.COOKING.ordinal()] = 98;
		RequirementContext underleveled = RequirementTestFixtures.context()
			.boostedSkillLevelsAndMore(below).build();
		assertFalse(requirements(underleveled).satisfied(guild));
		assertEquals(RejectionReason.SKILL_LEVEL, requirements(underleveled).check(guild));
	}

	@Test
	public void questGatedBankFollowsTheHookFedQuestMap()
	{
		DestinationRequirements gated = RequirementTestFixtures.bankRequirements(
			null, Set.of(Quest.BONE_VOYAGE), null, null);

		// Missing from the captured map → NOT_STARTED → fails closed.
		RequirementContext missing = RequirementTestFixtures.context().build();
		assertFalse(requirements(missing).satisfied(gated));
		assertEquals(RejectionReason.QUEST, requirements(missing).check(gated));

		RequirementContext finished = RequirementTestFixtures.context()
			.questStates(Map.of(Quest.BONE_VOYAGE, QuestState.FINISHED)).build();
		assertTrue(requirements(finished).satisfied(gated));
	}

	@Test
	public void varbitGatedBankFollowsCapturedVarbits()
	{
		// Cooks' Guild door: varbit 4481 == 1.
		Set<VarRequirement> varbits = VarRequirementParser.forVarbits().parse("4481=1");
		DestinationRequirements gated = RequirementTestFixtures.bankRequirements(
			null, null, varbits, null);

		assertTrue(requirements(RequirementTestFixtures.context()
			.varbitValues(Map.of(4481, 1)).build()).satisfied(gated));

		RequirementContext closed = RequirementTestFixtures.context()
			.varbitValues(Map.of(4481, 0)).build();
		assertFalse(requirements(closed).satisfied(gated));
		assertEquals(RejectionReason.VARBIT, requirements(closed).check(gated));
	}

	@Test
	public void fortisColosseumVarplayerIsStrictlyGreater()
	{
		// bank.tsv: "1804 9501 0  Fortis Colosseum  ...  4130>1999" — the
		// colosseum bank is locked until varplayer 4130 exceeds 1999.
		Set<VarRequirement> varPlayers = VarRequirementParser.forVarPlayers().parse("4130>1999");
		assertEquals(1, varPlayers.size());
		assertEquals(VarCheckType.GREATER, varPlayers.iterator().next().getCheckType());
		DestinationRequirements fortis = RequirementTestFixtures.bankRequirements(
			null, null, null, varPlayers);

		// Present but below the threshold.
		RequirementContext below = RequirementTestFixtures.context()
			.varPlayerValues(Map.of(4130, 1500)).build();
		assertFalse(requirements(below).satisfied(fortis));
		assertEquals(RejectionReason.VARPLAYER, requirements(below).check(fortis));

		// Exactly at the threshold still fails — the check is strict >.
		RequirementContext at = RequirementTestFixtures.context()
			.varPlayerValues(Map.of(4130, 1999)).build();
		assertFalse(requirements(at).satisfied(fortis));

		// Above the threshold.
		RequirementContext above = RequirementTestFixtures.context()
			.varPlayerValues(Map.of(4130, 2000)).build();
		assertTrue(requirements(above).satisfied(fortis));
		assertEquals(RejectionReason.NONE, requirements(above).check(fortis));

		// The var was never captured: fail closed.
		RequirementContext absent = RequirementTestFixtures.context().build();
		assertFalse(requirements(absent).satisfied(fortis));
		assertEquals(RejectionReason.VARPLAYER, requirements(absent).check(fortis));
	}

	@Test
	public void bankRequirementsCombineConjunctively()
	{
		// A tile carrying two requirement kinds needs all of them.
		int[] skills = new int[SkillLevels.LENGTH];
		skills[Skill.COOKING.ordinal()] = 99;
		DestinationRequirements both = RequirementTestFixtures.bankRequirements(
			SkillLevels.of(skills), null, VarRequirementParser.forVarbits().parse("4481=1"), null);

		RequirementContext varMissing = RequirementTestFixtures.context().build();
		assertFalse(requirements(varMissing).satisfied(both));

		int[] low = RequirementTestFixtures.maxedSkills();
		low[Skill.COOKING.ordinal()] = 1;
		RequirementContext lowSkill = RequirementTestFixtures.context()
			.boostedSkillLevelsAndMore(low).varbitValues(Map.of(4481, 1)).build();
		// Skill is checked before varbits, so the skill verdict wins.
		assertEquals(RejectionReason.SKILL_LEVEL, requirements(lowSkill).check(both));

		RequirementContext passing = RequirementTestFixtures.context()
			.varbitValues(Map.of(4481, 1)).build();
		assertTrue(requirements(passing).satisfied(both));
	}

	// ------------------------------------------------------------------
	// Snapshot contract: a built chain reads the captured maps, not the
	// live source — mutating the source after capture cannot move a verdict.
	// ------------------------------------------------------------------

	@Test
	public void verdictsReadTheCapturedSnapshotNotTheLiveSource()
	{
		MapPlayerStateSource source = new MapPlayerStateSource()
			.varp(4130, 2000);
		DestinationRequirements fortis = RequirementTestFixtures.bankRequirements(
			null, null, null, VarRequirementParser.forVarPlayers().parse("4130>1999"));

		RequirementContext context = RequirementContext.capture(
			source,
			new TestRequirementHooks(),
			RequirementTestFixtures.policy(MODE),
			0L,
			List.of(),
			Map.of(1, fortis),
			null,
			Set.of(),
			false,
			new shortestpath.leagues.LeagueModeState(),
			null, Set.of());
		Requirements requirements = requirements(context);
		assertTrue(requirements.satisfied(fortis));

		// The source now reports a failing value; the already-built chain
		// still reads the snapshot from capture time.
		source.varp(4130, 0);
		assertTrue(requirements.satisfied(fortis));

		// And a fresh capture observes the new value.
		RequirementContext recaptured = RequirementContext.capture(
			source,
			new TestRequirementHooks(),
			RequirementTestFixtures.policy(MODE),
			0L,
			List.of(),
			Map.of(1, fortis),
			null,
			Set.of(),
			false,
			new shortestpath.leagues.LeagueModeState(),
			null, Set.of());
		assertFalse(requirements(recaptured).satisfied(fortis));
	}
}

package shortestpath.requirement;

import java.io.IOException;
import java.io.InputStream;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.List;

import org.junit.Assert;

/**
 * Golden-verdict compare/regenerate helper for the gate-chain parity tests.
 *
 * <p>Each scenario's expected verdict table lives at
 * {@code src/test/resources/gate-chain-parity/<scenario>.txt}, loaded through
 * the test classpath (the Gradle {@code java} plugin puts
 * {@code src/test/resources} on it — no build file change needed). One line
 * per recorded fixture verdict; the comparison is a line diff that reports
 * the first mismatch with its line number so a drift reads immediately.
 *
 * <p>Regeneration is gated on the {@code VERDICT_REGEN} environment
 * variable — an env var rather than a {@code -D} flag because Gradle test
 * JVMs do not inherit CLI system properties without a {@code systemProperty}
 * line in {@code build.gradle}, which stays untouched:
 *
 * <pre>VERDICT_REGEN=1 ./gradlew -p shortest-path test --tests '*GateChainParityTest*'</pre>
 *
 * Only the values {@code 1} and {@code true} opt in — a stray
 * {@code VERDICT_REGEN} set to anything else is ignored with a stderr
 * note, and the suite compares normally. When regen is active a banner and
 * every rewritten file go to stderr so the run cannot read as an ordinary
 * green pass: nothing is compared while regenerating. {@code VERDICT_REGEN}
 * belongs to this suite alone — {@code TRANSCRIPT_REGEN} gates the unrelated
 * overlay draw-call goldens.
 *
 * <p>Regen is for deliberate fixture changes only — the goldens are the
 * gate-chain parity oracle, so a regen that masks accidental verdict drift
 * voids it. The write goes to the source tree (the Gradle test working
 * directory is the {@code shortest-path} project dir — regen fails loudly
 * when the markers are absent), then a clean re-run compares.
 */
final class GateChainParityGolden
{
	private static final String RESOURCE_DIR = "gate-chain-parity";
	private static final boolean REGEN = regenRequested();
	private static boolean regenAnnounced;

	private GateChainParityGolden()
	{
	}

	private static boolean regenRequested()
	{
		String value = System.getenv("VERDICT_REGEN");
		if (value == null)
		{
			return false;
		}
		if ("1".equals(value) || "true".equalsIgnoreCase(value))
		{
			return true;
		}
		// A set-but-unrecognized value must not vacuate the oracle.
		System.err.println("VERDICT_REGEN=" + value + " ignored — regeneration"
			+ " requires VERDICT_REGEN=1; comparing against goldens normally");
		return false;
	}

	static void compareOrRegen(String scenario, List<String> lines)
	{
		String body = String.join("\n", lines) + "\n";
		if (REGEN)
		{
			if (!regenAnnounced)
			{
				regenAnnounced = true;
				System.err.println("VERDICT_REGEN active — rewriting goldens,"
					+ " nothing is being compared");
			}
			regen(scenario, body);
			System.err.println("  rewrote " + scenario + ".txt");
			return;
		}
		String expected = read(scenario);
		String[] expectedLines = expected.split("\n", -1);
		String[] actualLines = body.split("\n", -1);
		for (int i = 0; i < Math.max(expectedLines.length, actualLines.length); i++)
		{
			String e = i < expectedLines.length ? expectedLines[i] : "<missing>";
			String a = i < actualLines.length ? actualLines[i] : "<missing>";
			if (!e.equals(a))
			{
				Assert.fail(scenario + " verdict drift at line " + (i + 1)
					+ "\n  expected: " + e + "\n  actual:   " + a
					+ "\n(regenerate with VERDICT_REGEN=1 only for a deliberate fixture change)");
			}
		}
	}

	private static String read(String scenario)
	{
		String name = RESOURCE_DIR + "/" + scenario + ".txt";
		try (InputStream in = GateChainParityGolden.class.getClassLoader().getResourceAsStream(name))
		{
			if (in == null)
			{
				Assert.fail("missing golden " + name + " — record it with VERDICT_REGEN=1");
			}
			return new String(in.readAllBytes(), StandardCharsets.UTF_8);
		}
		catch (IOException e)
		{
			throw new UncheckedIOException(e);
		}
	}

	private static void regen(String scenario, String body)
	{
		Path out = Paths.get("src/test/resources", RESOURCE_DIR, scenario + ".txt");
		// The write is CWD-relative — refuse when the working directory is
		// not the shortest-path project dir, or the regen would plant a
		// stray golden tree and report a green, vacuous run while the real
		// classpath goldens stay untouched.
		if (!Files.isRegularFile(Paths.get("build.gradle"))
			|| !Files.isDirectory(out.getParent().getParent()))
		{
			Assert.fail("VERDICT_REGEN must run with the shortest-path project dir as"
				+ " the working directory — refusing to write " + out.toAbsolutePath());
		}
		try
		{
			Files.createDirectories(out.getParent());
			Files.write(out, body.getBytes(StandardCharsets.UTF_8));
		}
		catch (IOException e)
		{
			throw new UncheckedIOException(e);
		}
	}
}

package shortestpath.requirement;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.Set;

import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.gameval.ItemID;
import org.junit.Assert;
import org.junit.Test;

import shortestpath.WorldPointUtil;
import shortestpath.leagues.LeagueModeState;
import shortestpath.leagues.LeagueRegion;
import shortestpath.pathfinder.BankVisitState;
import shortestpath.requirement.model.DestinationRequirements;
import shortestpath.requirement.model.ItemRequirement;
import shortestpath.requirement.model.TransportItems;
import shortestpath.requirement.model.Unlock;
import shortestpath.requirement.model.VarCheckType;
import shortestpath.requirement.model.VarRequirement;
import shortestpath.settings.TeleportationItem;
import shortestpath.transport.Transport;
import shortestpath.transport.TransportType;

/**
 * Record-first golden parity matrix over the composite requirement surface.
 * Each transport fixture records {@code check()}'s {@link RejectionReason}
 * plus {@code usable(CARRIED)} and {@code usable(BANKED)} on the eligibility
 * snapshot the context carries; each bank fixture records
 * {@code check(DestinationRequirements)} plus {@code satisfied}. The
 * committed goldens are the oracle the requirement-middleware consolidation
 * must reproduce verbatim — a verdict that drifts reads as a line diff.
 *
 * <p>The grid is deliberately non-vacuous: every {@link TeleportationItem}
 * mode crosses {@code isConsumable} in both directions across three pool
 * states, the divergent {@code usable} tails are pinned individually (the
 * fairy-ring Dramen-staff rule, the balloon log-basket grant, the currency
 * threshold, the item-teleport type set versus the planted-spirit-tree
 * triple), the per-gate rejection reasons each appear, and the null/empty
 * edges record their pass-through verdicts.
 *
 * <p>Fixtures run on the keyed/value substrate — real
 * {@link RequirementContext}/{@link RoutingPolicy}/{@link TransportEligibility}
 * values built through {@link RequirementTestFixtures} and
 * {@link TestRequirementHooks}. The eligibility instance injected into the
 * context is the same object the {@code usable} columns are read from, so
 * the {@code check} and {@code usable} verdicts can never describe different
 * pools. No Mockito — nothing in the chain is an interface boundary a mock
 * could falsy-default.
 */
public class GateChainParityTest
{
	private static final int FALADOR = WorldPointUtil.packWorldPoint(2965, 3378, 0);
	private static final int VARROCK = WorldPointUtil.packWorldPoint(3213, 3424, 0);
	private static final int POH = WorldPointUtil.packWorldPoint(1858, 7051, 0);
	// A real balloon landing (Entrana, 2808 3354 0) so the basket grant is
	// destination-scoped the way the TSV rows are.
	private static final int BALLOON_DEST = WorldPointUtil.packWorldPoint(2808, 3354, 0);
	private static final int BANK_TILE = WorldPointUtil.packWorldPoint(1804, 9501, 0);

	private static final TeleportationItem MODE = TeleportationItem.INVENTORY;
	private static final int LAW_RUNE = ItemID.LAWRUNE;
	private static final int COINS = ItemID.COINS;
	private static final int DRAMEN_STAFF = ItemID.DRAMEN_STAFF;
	private static final int LOGS = ItemID.LOGS;

	private static Transport.TransportBuilder transport(TransportType type)
	{
		return new Transport.TransportBuilder().type(type).origin(FALADOR).destination(VARROCK);
	}

	private static ItemRequirement.Branch branch(int... itemIds)
	{
		return new ItemRequirement.Branch(itemIds, null, null, 1);
	}

	private static ItemRequirement.Branch unlockBranch(Unlock unlock)
	{
		return new ItemRequirement.Branch(null, null, null, 1, unlock);
	}

	private static ItemRequirement item(int itemId)
	{
		return new ItemRequirement(new int[]{itemId}, null, null, 1);
	}

	private static ItemRequirement item(int itemId, int quantity)
	{
		return new ItemRequirement(new int[]{itemId}, null, null, quantity);
	}

	private static TransportItems items(ItemRequirement... requirements)
	{
		return new TransportItems(List.of(requirements));
	}

	/**
	 * The verdict line one transport fixture records: the gate chain's first
	 * rejection, the pool verdicts the same eligibility snapshot reports,
	 * and the {@code gates()} prefix verdict. The line also asserts the
	 * post-split composite invariant: {@code check} is {@code NONE} exactly
	 * when the gate prefix passes and at least one item pool satisfies.
	 */
	private static String verdict(String id, Requirements requirements,
		TransportEligibility eligibility, Transport transport)
	{
		RejectionReason gates = requirements.gates(transport);
		boolean carried = eligibility.usable(transport, BankVisitState.CARRIED);
		boolean banked = eligibility.usable(transport, BankVisitState.BANKED);
		RejectionReason check = requirements.check(transport);
		Assert.assertEquals(id,
			check == RejectionReason.NONE,
			gates == RejectionReason.NONE && (carried || banked));
		return id
			+ " | check=" + check
			+ " | carried=" + carried
			+ " | banked=" + banked
			+ " | gates=" + gates;
	}

	/** The bank-side counterpart: {@code check} reason plus the {@code satisfied} adapter. */
	private static String bankVerdict(String id, Requirements requirements,
		DestinationRequirements destinationRequirements)
	{
		return id
			+ " | check=" + requirements.check(destinationRequirements)
			+ " | satisfied=" + requirements.satisfied(destinationRequirements);
	}

	/**
	 * The widest {@link TransportEligibility} constructor, exposing the knobs
	 * the divergent {@code usable} tails read — fairy-ring staff rule,
	 * currency threshold, declared unlocks and the balloon basket set.
	 */
	private static TransportEligibility eligibility(boolean staffRequired,
		TeleportationItem mode, Map<Integer, Integer> carried, Map<Integer, Integer> bankPath,
		int currencyThreshold, Set<Unlock> unlocks, Set<Integer> basketDestinations)
	{
		return new TransportEligibility(carried, bankPath, Map.of(), -1, Map.of(),
			staffRequired, mode, currencyThreshold, unlocks, true, basketDestinations);
	}

	private static LeagueModeState seasonal(LeagueRegion... unlocked)
	{
		LeagueModeState state = new LeagueModeState();
		// setForTest translates null to an empty EnumSet; Set.of() is empty
		// here, which EnumSet.copyOf rejects.
		state.setForTest(true, unlocked.length == 0 ? null : Set.of(unlocked));
		return state;
	}

	/**
	 * The real capture path: quest states flow through the
	 * {@link TestRequirementHooks#questState} knob into the context's
	 * captured map.
	 */
	private static RequirementContext capture(MapPlayerStateSource source, TestRequirementHooks hooks,
		List<Transport> transports, Map<Integer, DestinationRequirements> bankRequirements)
	{
		return RequirementContext.capture(source, hooks, RequirementTestFixtures.policy(MODE), 0L,
			transports, bankRequirements, null, Set.of(), false, new LeagueModeState(), null, Set.of());
	}

	// ------------------------------------------------------------------
	// Mode × consumable × pool grid — the cells the two divergent mode
	// switches must agree on through every later consolidation step.
	// ------------------------------------------------------------------

	private static List<String> modeGrid(Map<Integer, Integer> carried, Map<Integer, Integer> bankPath)
	{
		List<String> lines = new ArrayList<>();
		for (TeleportationItem mode : TeleportationItem.values())
		{
			for (boolean consumable : new boolean[]{true, false})
			{
				Transport transport = transport(TransportType.TELEPORTATION_ITEM)
					.isConsumable(consumable)
					.itemRequirements(items(item(LAW_RUNE)))
					.build();
				TransportEligibility eligibility = bankPath == null
					? RequirementTestFixtures.eligibility(mode, carried)
					: RequirementTestFixtures.bankedEligibility(mode, carried, bankPath);
				RequirementContext context = RequirementTestFixtures.context()
					.eligibility(eligibility).build();
				lines.add(verdict(mode + "/" + (consumable ? "consumable" : "permanent"),
					RequirementTestFixtures.requirements(context, RequirementTestFixtures.policy(mode)),
					eligibility, transport));
			}
		}
		return lines;
	}

	@Test
	public void modesWithCarriedPool()
	{
		// The carried pool satisfies the single-rune requirement, so the
		// deferring modes pass on both pools.
		GateChainParityGolden.compareOrRegen("modes-carried-pool",
			modeGrid(Map.of(LAW_RUNE, 1), null));
	}

	@Test
	public void modesWithBankedPoolOnly()
	{
		// Only the bank-path pool satisfies — the carried verdict splits off
		// while check() still passes on the banked arm.
		GateChainParityGolden.compareOrRegen("modes-banked-pool",
			modeGrid(Map.of(), Map.of(LAW_RUNE, 1)));
	}

	@Test
	public void modesWithNoPool()
	{
		// Neither pool satisfies: BYPASS modes stay usable, EVALUATE_ITEMS
		// modes report ITEM_REQUIREMENT, REJECT modes report TELEPORT_MODE.
		GateChainParityGolden.compareOrRegen("modes-no-pool",
			modeGrid(Map.of(), null));
	}

	// ------------------------------------------------------------------
	// usable()'s divergent tails — everything after the mode switch.
	// ------------------------------------------------------------------

	@Test
	public void usableFairyRingTails()
	{
		// The Dramen/Lunar-staff rule rides the injected requirement on the
		// wrapped ring — staff-required with no staff fails both pools even
		// when the bank path could supply one, and the not-required case
		// passes with empty pools.
		Transport fairyRing = transport(TransportType.FAIRY_RING).build();
		List<String> lines = new ArrayList<>();

		TransportEligibility staffAbsent = eligibility(true, TeleportationItem.NONE,
			Map.of(), Map.of(), Integer.MAX_VALUE, Set.of(), Set.of());
		lines.add(verdict("fairy-ring/staff-required-absent",
			RequirementTestFixtures.requirements(
				RequirementTestFixtures.context().eligibility(staffAbsent).build(),
				RequirementTestFixtures.policy(TeleportationItem.NONE)),
			staffAbsent, staffAbsent.wrapFairyRingStaff(fairyRing)));

		TransportEligibility staffCarried = eligibility(true, TeleportationItem.NONE,
			Map.of(DRAMEN_STAFF, 1), Map.of(DRAMEN_STAFF, 1), Integer.MAX_VALUE, Set.of(), Set.of());
		lines.add(verdict("fairy-ring/staff-required-carried",
			RequirementTestFixtures.requirements(
				RequirementTestFixtures.context().eligibility(staffCarried).build(),
				RequirementTestFixtures.policy(TeleportationItem.NONE)),
			staffCarried, staffCarried.wrapFairyRingStaff(fairyRing)));

		TransportEligibility staffBanked = eligibility(true, TeleportationItem.NONE,
			Map.of(), Map.of(DRAMEN_STAFF, 1), Integer.MAX_VALUE, Set.of(), Set.of());
		lines.add(verdict("fairy-ring/staff-required-banked-only",
			RequirementTestFixtures.requirements(
				RequirementTestFixtures.context().eligibility(staffBanked).build(),
				RequirementTestFixtures.policy(TeleportationItem.NONE)),
			staffBanked, staffBanked.wrapFairyRingStaff(fairyRing)));

		TransportEligibility noStaff = eligibility(false, TeleportationItem.NONE,
			Map.of(), Map.of(), Integer.MAX_VALUE, Set.of(), Set.of());
		lines.add(verdict("fairy-ring/staff-not-required",
			RequirementTestFixtures.requirements(
				RequirementTestFixtures.context().eligibility(noStaff).build(),
				RequirementTestFixtures.policy(TeleportationItem.NONE)),
			noStaff, noStaff.wrapFairyRingStaff(fairyRing)));

		GateChainParityGolden.compareOrRegen("usable-fairy-ring", lines);
	}

