		// The bypass modes pass gate 15 on empty pools; INVENTORY defers and
		// fails; NONE never reaches the item gate at all.
		Transport teleport = transport(TransportType.TELEPORTATION_ITEM)
			.itemRequirements(items(item(LAW_RUNE)))
			.build();

		for (TeleportationItem mode : new TeleportationItem[]{
			TeleportationItem.ALL, TeleportationItem.UNLOCKED})
		{
			RequirementContext empty = RequirementTestFixtures.context()
				.eligibility(RequirementTestFixtures.eligibility(mode, Map.of()))
				.build();
			assertEquals(mode + " bypasses empty pools",
				RejectionReason.NONE,
				requirements(empty, RequirementTestFixtures.policy(mode)).check(teleport));
		}

		RequirementContext empty = RequirementTestFixtures.context()
			.eligibility(RequirementTestFixtures.eligibility(TeleportationItem.INVENTORY, Map.of()))
			.build();
		assertEquals("INVENTORY defers to the pools",
			RejectionReason.ITEM_REQUIREMENT,
			requirements(empty, RequirementTestFixtures.policy(TeleportationItem.INVENTORY)).check(teleport));

		RequirementContext carried = RequirementTestFixtures.context()
			.eligibility(RequirementTestFixtures.eligibility(TeleportationItem.NONE, Map.of(LAW_RUNE, 1)))
			.build();
		assertEquals("NONE rejects at the mode seat regardless of items",
			RejectionReason.TELEPORT_MODE,
			requirements(carried, RequirementTestFixtures.policy(TeleportationItem.NONE)).check(teleport));
	}

	@Test
	public void seasonalWorldRejectsRegardlessOfMode()
	{
		// The seasonal check sits ahead of the mode dispatch, so deferring
		// and non-consumable modes report SEASONAL_WORLD on a normal world
		// just as NONE and ALL already do.
		RequirementContext normal = RequirementTestFixtures.context().build();
		Transport seasonalTransport = transport(TransportType.SEASONAL_TRANSPORTS).build();
		for (TeleportationItem mode : TeleportationItem.values())
		{
			assertEquals(mode + " must not reach the mode dispatch",
				RejectionReason.SEASONAL_WORLD,
				requirements(normal, RequirementTestFixtures.policy(mode)).check(seasonalTransport));
		}
	}
}

package shortestpath.requirement;

import java.util.EnumSet;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import org.junit.Assert;
import org.junit.Test;
import shortestpath.WorldPointUtil;
import shortestpath.poh.JewelleryBoxTier;
import shortestpath.poh.PohMountedItem;
import shortestpath.poh.PohNexusPortal;
import shortestpath.requirement.model.ItemRequirement;
import shortestpath.requirement.model.TransportItems;
import shortestpath.settings.TeleportationItem;
import shortestpath.transport.Transport;
import shortestpath.transport.TransportType;

/**
 * Adversarial coverage of the destination-scoped option-block gate in
 * {@link Requirements#check}: a {@code rep@dest} record blocks one
 * destination option of one teleport family. A transport row is dropped
 * only when EVERY branch that could satisfy it resolves to a blocked
 * (representative, destination) pair — a sibling destination of the same
 * family, a branch from another family, a non-family item or an unlock
 * alternative all keep the transport routable. The gate must compose with
 * every teleportation-item mode and must never resurrect a NONE-mode
 * rejection.
 *
 * <p>The fixture ids are real family members: {@code 13121} heads the
 * Ardougne-cloaks family (members 13121-13124, 20760; destinations
 * Kandarin Monastery and Ardougne Farm) and {@code 3853} heads the
 * Games-necklace family — the two give genuine cross-family branch cases
 * against the live {@code teleportation_items.tsv} serving rows.
 */
public class RestrictionOptionGateTest
{
	private static final int MONASTERY = WorldPointUtil.packWorldPoint(2607, 3221, 0);
	private static final int FARM = WorldPointUtil.packWorldPoint(2665, 3374, 0);
	private static final int CLOAK_REP = 13121;
	private static final int CLOAK_MEMBER = 13122;
	private static final int GAMES_REP = 3853;
	private static final int GAMES_MEMBER = 3855;
	private static final int OTHER_REP = 9013;
	private static final int XERICS_MEMBER = 13393;
	private static final int COINS = 995;

	private static Transport transportTo(int packedDest, String items)
	{
		return new Transport.TransportBuilder()
			.type(TransportType.TELEPORTATION_ITEM)
			.destination(packedDest)
			.itemRequirements(items)
			.build();
	}

	private static RoutingPolicy policy(TeleportationItem mode,
		Map<Integer, Set<Integer>> optionBlocks)
	{
		return new RoutingPolicy(EnumSet.allOf(TransportType.class), mode,
			true, true, true, true, EnumSet.allOf(PohNexusPortal.class),
			EnumSet.allOf(PohMountedItem.class), JewelleryBoxTier.ORNATE,
			Integer.MAX_VALUE, true, Set.of(), optionBlocks);
	}

	private static RejectionReason check(TeleportationItem mode,
		Map<Integer, Set<Integer>> optionBlocks, Map<Integer, Integer> carried,
		Transport transport)
	{
		RequirementContext context = RequirementTestFixtures.context(
			RequirementTestFixtures.eligibility(mode, carried));
		return RequirementTestFixtures.requirements(context,
			policy(mode, optionBlocks)).check(transport);
	}

	/**
	 * The row serving the blocked destination dies: every OR branch maps to
	 * the cloak family's representative and that representative is blocked
	 * at the farm destination.
	 */
	@Test
	public void optionBlockRejectsWhenEveryBranchResolvesToTheBlockedDestination()
	{
		Transport farm = transportTo(FARM, CLOAK_REP + "=1||" + CLOAK_MEMBER + "=1");

		Assert.assertEquals(RejectionReason.BLOCKED_ITEM,
			check(TeleportationItem.ALL, Map.of(CLOAK_REP, Set.of(FARM)), Map.of(), farm));
	}

	/**
	 * The sibling destination of the same family is untouched: blocking the
	 * farm option must never kill the monastery row.
	 */
	@Test
	public void siblingDestinationOfTheSameFamilyStillRoutes()
	{
		Transport monastery = transportTo(MONASTERY, CLOAK_REP + "=1||" + CLOAK_MEMBER + "=1");

		Assert.assertEquals(RejectionReason.NONE,
			check(TeleportationItem.ALL, Map.of(CLOAK_REP, Set.of(FARM)), Map.of(), monastery));
	}

	/**
	 * Per-item rows die too: a row whose Items cell lists only the blocked
	 * family's ids has no surviving branch at the blocked destination.
	 */
	@Test
	public void perItemRowsAtTheBlockedDestinationDieAsWell()
	{
		Transport perItem = transportTo(FARM, CLOAK_MEMBER + "=1");

		Assert.assertEquals(RejectionReason.BLOCKED_ITEM,
			check(TeleportationItem.ALL, Map.of(CLOAK_REP, Set.of(FARM)), Map.of(), perItem));
	}

	/**
	 * A non-family id in an OR branch is never option-blocked — the coins
	 * alternative keeps the row routable.
	 */
	@Test
	public void nonFamilyItemBranchIsNeverOptionBlocked()
	{
		Transport farm = transportTo(FARM, CLOAK_MEMBER + "=1|" + COINS + "=1");

		Assert.assertEquals(RejectionReason.NONE,
			check(TeleportationItem.ALL, Map.of(CLOAK_REP, Set.of(FARM)), Map.of(), farm));
	}

	/**
	 * Cross-family OR rows are blocked independently: blocking only the
	 * cloak representative drops the cloak branch but the games-necklace
	 * branch still satisfies; blocking both kills the row.
	 */
	@Test
	public void crossFamilyBranchesAreBlockedIndependently()
	{
		Transport farm = transportTo(FARM, CLOAK_MEMBER + "=1|" + GAMES_MEMBER + "=1");

		Assert.assertEquals(RejectionReason.NONE,
			check(TeleportationItem.ALL, Map.of(CLOAK_REP, Set.of(FARM)), Map.of(), farm));
		Assert.assertEquals(RejectionReason.BLOCKED_ITEM,
			check(TeleportationItem.ALL,
				Map.of(CLOAK_REP, Set.of(FARM), GAMES_REP, Set.of(FARM)), Map.of(), farm));
	}

	/**
	 * An unlock alternative carries no item ids, so an option block can
	 * never remove it — the Xeric's-talisman row shape.
	 */
	@Test
	public void unlockBranchSurvivesAnOptionBlock()
	{
		Transport farm = transportTo(FARM, XERICS_MEMBER + "=1|UNLOCK_XERICS_HONOUR=1");

		Assert.assertEquals(RejectionReason.NONE,
			check(TeleportationItem.ALL, Map.of(OTHER_REP, Set.of(FARM)), Map.of(), farm));
	}

	/**
	 * The gate composes with every teleportation-item mode: a transport
	 * serving only the blocked destination is rejected under all nine —
	 * under inventory modes the item is carried so the option block is the
	 * sole cause; under NONE the block still rejects (it never needs the
	 * mode's TELEPORT_MODE verdict).
	 */
	@Test
	public void everyTeleportationItemModeAppliesTheOptionBlock()
	{
		Transport farm = transportTo(FARM, CLOAK_REP + "=1||" + CLOAK_MEMBER + "=1");
		Map<Integer, Set<Integer>> blocks = Map.of(CLOAK_REP, Set.of(FARM));
		Map<Integer, Integer> carried = Map.of(CLOAK_REP, 1);

		for (TeleportationItem mode : TeleportationItem.values())
		{
			RejectionReason reason = check(mode, blocks, carried, farm);
			Assert.assertEquals("mode " + mode + " must reject the option-blocked row",
				RejectionReason.BLOCKED_ITEM, reason);
		}
	}

	/**
	 * The NONE-mode rejection stands on its own and the option logic can
	 * never resurrect it: without a block the verdict is TELEPORT_MODE;
	 * with one it is BLOCKED_ITEM — rejected either way.
	 */
	@Test
	public void noneModeRejectionIsNotResurrectedByOptionLogic()
	{
		Transport farm = transportTo(FARM, CLOAK_REP + "=1");

		Assert.assertEquals(RejectionReason.TELEPORT_MODE,
			check(TeleportationItem.NONE, Map.of(), Map.of(), farm));
		RejectionReason blocked = check(TeleportationItem.NONE,
			Map.of(CLOAK_REP, Set.of(FARM)), Map.of(), farm);
		Assert.assertNotEquals(RejectionReason.NONE, blocked);
	}

	/**
	 * A transport with no Items requirement has no branches the option gate
	 * could kill.
	 */
	@Test
	public void transportsWithoutItemRequirementsAreUnaffected()
	{
		Transport noItems = new Transport.TransportBuilder()
			.type(TransportType.TELEPORTATION_ITEM)
			.destination(FARM)
			.build();

		Assert.assertEquals(RejectionReason.NONE,
			check(TeleportationItem.ALL, Map.of(CLOAK_REP, Set.of(FARM)), Map.of(), noItems));
	}

	/**
	 * Staff (and offhand) substitute arrays do not participate in option
	 * blocking — a requirement satisfiable only through a staff id keeps
	 * its branch even when that id belongs to a blocked family.
	 */
	@Test
	public void staffAndOffhandSubstitutesAreNotOptionBlocked()
	{
		ItemRequirement staffOnly = new ItemRequirement(List.of(
			new ItemRequirement.Branch(null, new int[]{CLOAK_REP}, null, 1)));
		Transport transport = new Transport.TransportBuilder()
			.type(TransportType.TELEPORTATION_ITEM)
			.destination(FARM)
			.itemRequirements(new TransportItems(List.of(staffOnly)))
			.build();

		Assert.assertEquals(RejectionReason.NONE,
			check(TeleportationItem.ALL, Map.of(CLOAK_REP, Set.of(FARM)), Map.of(), transport));
	}

	/**
	 * The policy's option map is deep-frozen: mutating the source map or
	 * its inner sets after construction cannot move the snapshot, and the
	 * handed-out collections reject writes.
	 */
	@Test
	public void policyOptionMapIsDeeplyImmutable()
	{
		Set<Integer> dests = new HashSet<>(Set.of(FARM));
		Map<Integer, Set<Integer>> blocks = new HashMap<>();
		blocks.put(CLOAK_REP, dests);

		RoutingPolicy policy = policy(TeleportationItem.ALL, blocks);

		blocks.put(GAMES_REP, Set.of(MONASTERY));
		dests.add(MONASTERY);
		Assert.assertEquals(Map.of(CLOAK_REP, Set.of(FARM)), policy.blockedOptionDests());
		Assert.assertThrows(UnsupportedOperationException.class,
			() -> policy.blockedOptionDests().get(CLOAK_REP).add(1));
		Assert.assertThrows(UnsupportedOperationException.class,
			() -> policy.blockedOptionDests().put(42, Set.of(1)));
	}

	/**
	 * End-to-end: the CSV record flows through the parser into the policy
	 * and rejects exactly the blocked destination — the sibling routes.
	 */
	@Test
	public void csvOptionRecordFlowsIntoTheGate()
	{
		Set<Integer> blocked = new HashSet<>();
		Map<Integer, Integer> thresholds = new HashMap<>();
		Map<Integer, Set<Integer>> options = new HashMap<>();
		TeleportRestriction.parseBlocked(CLOAK_REP + "@" + FARM, blocked, thresholds, options);

		Assert.assertEquals(RejectionReason.BLOCKED_ITEM,
			check(TeleportationItem.ALL, options, Map.of(), transportTo(FARM, CLOAK_REP + "=1")));
		Assert.assertEquals(RejectionReason.NONE,
			check(TeleportationItem.ALL, options, Map.of(),
				transportTo(MONASTERY, CLOAK_REP + "=1")));
	}

	/**
	 * The empty-block fast path: no rep@dest records means no transport is
	 * ever option-blocked.
	 */
	@Test
	public void emptyOptionMapNeverBlocks()
	{
		Assert.assertEquals(RejectionReason.NONE,
			check(TeleportationItem.ALL, Map.of(), Map.of(), transportTo(FARM, CLOAK_REP + "=1")));
	}
}

package shortestpath.requirement;

import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import org.junit.Assert;
import org.junit.Rule;
import org.junit.Test;
import shortestpath.ItemVariations;
import shortestpath.LogCapture;
import shortestpath.requirement.model.TransportItems;

/**
 * Direct unit coverage of the {@code blockedTeleportItems} CSV contract shared
 * by the sidebar restriction checklist and {@code refresh()}.
 * {@link TeleportRestriction#parseBlocked} reads user- or profile-authored CSV
 * into a blocked-id set plus a per-item threshold map;
 * {@link TeleportRestriction#toCsv} serializes the panel's state back. A bare
 * {@code id} record blocks the item; an {@code id:N} record sets a per-item
 * threshold override of N tiles. Malformed entries are skipped with a warning —
 * the parser must never throw on hand-edited config.
 */
public class TeleportRestrictionTest
{
	@Rule
	public final LogCapture log = new LogCapture("shortestpath.requirement.TeleportRestriction");

	@Test
	public void bareIdsParseIntoTheBlockedSet()
	{
		Set<Integer> blocked = new HashSet<>();
		Map<Integer, Integer> thresholds = new HashMap<>();

		TeleportRestriction.parseBlocked("123,456", blocked, thresholds);

		Assert.assertEquals(Set.of(123, 456), blocked);
		Assert.assertTrue(thresholds.isEmpty());
	}

	@Test
	public void colonEntriesParseIntoTheThresholdMap()
	{
		Set<Integer> blocked = new HashSet<>();
		Map<Integer, Integer> thresholds = new HashMap<>();

		TeleportRestriction.parseBlocked("123:30,7:5", blocked, thresholds);

		Assert.assertTrue(blocked.isEmpty());
		Assert.assertEquals(Map.of(123, 30, 7, 5), thresholds);
	}

	@Test
	public void malformedEntriesAreSkippedAndGoodEntriesSurvive()
	{
		Set<Integer> blocked = new HashSet<>();
		Map<Integer, Integer> thresholds = new HashMap<>();

		// "abc" is not an id; "456:x" has a non-integer threshold — the whole
		// entry is dropped, 456 is NOT partially blocked; "12:3:4" has a second
		// colon making the threshold unparseable; ":5" has an empty id; "12:"
		// has an empty threshold; empty segments between commas are ignored.
		TeleportRestriction.parseBlocked("123,abc,456:x,789:10,,12:3:4,:5,12:", blocked, thresholds);

		Assert.assertEquals(Set.of(123), blocked);
		Assert.assertEquals(Map.of(789, 10), thresholds);
	}

	@Test
	public void duplicateThresholdEntriesKeepTheMax()
	{
		Set<Integer> blocked = new HashSet<>();
		Map<Integer, Integer> thresholds = new HashMap<>();

		TeleportRestriction.parseBlocked("42:10,42:30,42:20", blocked, thresholds);

		Assert.assertEquals(Map.of(42, 30), thresholds);
	}

	@Test
	public void nullAndBlankCsvProduceNoRestrictions()
	{
		for (String csv : new String[]{null, "", "   "})
		{
			Set<Integer> blocked = new HashSet<>();
			Map<Integer, Integer> thresholds = new HashMap<>();

			TeleportRestriction.parseBlocked(csv, blocked, thresholds);

			Assert.assertTrue("csv '" + csv + "' must leave the blocked set empty", blocked.isEmpty());
			Assert.assertTrue("csv '" + csv + "' must leave the threshold map empty", thresholds.isEmpty());
		}
	}

	@Test
	public void whitespaceAroundEntriesIsTolerated()
	{
		Set<Integer> blocked = new HashSet<>();
		Map<Integer, Integer> thresholds = new HashMap<>();

		TeleportRestriction.parseBlocked(" 12 , 34 : 7 ", blocked, thresholds);

		Assert.assertEquals(Set.of(12), blocked);
		Assert.assertEquals(Map.of(34, 7), thresholds);
	}

	@Test
	public void toCsvEmitsSortedBlockedIdsThenSortedThresholdRecords()
	{
		String csv = TeleportRestriction.toCsv(Set.of(300, 100), Map.of(200, 5, 50, 9));

		Assert.assertEquals("100,300,50:9,200:5", csv);
	}

	@Test
	public void toCsvWithEmptyOrNullInputsProducesEmptyString()
	{
		Assert.assertEquals("", TeleportRestriction.toCsv(Set.of(), Map.of()));
		Assert.assertEquals("", TeleportRestriction.toCsv(null, null));
		Assert.assertEquals("", TeleportRestriction.toCsv(Set.of(), null));
		Assert.assertEquals("", TeleportRestriction.toCsv(null, Map.of()));
	}

	@Test
	public void toCsvEmitsOnlyThePopulatedSide()
	{
		Assert.assertEquals("1", TeleportRestriction.toCsv(Set.of(1), null));
		Assert.assertEquals("2:8", TeleportRestriction.toCsv(null, Map.of(2, 8)));
	}

	@Test
	public void csvRoundTripsThroughSerializeAndParse()
	{
		Set<Integer> blocked = Set.of(5, 90);
		Map<Integer, Integer> thresholds = Map.of(7, 3, 42, 100);

		String csv = TeleportRestriction.toCsv(blocked, thresholds);
		Assert.assertEquals("5,90,7:3,42:100", csv);

		Set<Integer> parsedBlocked = new HashSet<>();
		Map<Integer, Integer> parsedThresholds = new HashMap<>();
		TeleportRestriction.parseBlocked(csv, parsedBlocked, parsedThresholds);

		Assert.assertEquals(blocked, parsedBlocked);
		Assert.assertEquals(thresholds, parsedThresholds);
	}

	/**
	 * The parser is permissive: {@code "123,123:30"} lands the id in BOTH
	 * outputs. Disjointness is a writer-side convention (blocking a family
	 * clears its threshold overrides) — hand-edited CSV can overlap, and the
	 * parse must not reject it.
	 */
	@Test
	public void theSameIdMayBeBothBlockedAndThresholded()
	{
		Set<Integer> blocked = new HashSet<>();
		Map<Integer, Integer> thresholds = new HashMap<>();

		TeleportRestriction.parseBlocked("123,123:30", blocked, thresholds);

		Assert.assertEquals(Set.of(123), blocked);
		Assert.assertEquals(Map.of(123, 30), thresholds);
	}

	@Test
	public void repAtDestRecordsParseIntoTheOptionBlockMap()
	{
		Set<Integer> blocked = new HashSet<>();
		Map<Integer, Integer> thresholds = new HashMap<>();
		Map<Integer, Set<Integer>> options = new HashMap<>();

		TeleportRestriction.parseBlocked("13121@87359490,1706,13121@999,2552@5",
			blocked, thresholds, options);

		Assert.assertEquals(Set.of(1706), blocked);
		Assert.assertTrue(thresholds.isEmpty());
		Assert.assertEquals(Map.of(13121, Set.of(87359490, 999), 2552, Set.of(5)), options);
	}

	@Test
	public void malformedAtRecordsAreSkippedAndGoodEntriesSurvive()
	{
		Set<Integer> blocked = new HashSet<>();
		Map<Integer, Integer> thresholds = new HashMap<>();
		Map<Integer, Set<Integer>> options = new HashMap<>();

		// "x@" and "@y" each have one empty side; "a@b" has no ints; "1@2@3"
		// carries a second '@' making the split unparseable; "@" alone has
		// two empty sides. The valid sibling must survive untouched.
		TeleportRestriction.parseBlocked("x@,@y,a@b,1@2@3,@,13121@1234,42",
			blocked, thresholds, options);

		Assert.assertEquals(Set.of(42), blocked);
		Assert.assertTrue(thresholds.isEmpty());
		Assert.assertEquals(Map.of(13121, Set.of(1234)), options);
	}

	@Test
	public void negativeIdsThresholdsAndRepsAreSkipped()
	{
		Set<Integer> blocked = new HashSet<>();
		Map<Integer, Integer> thresholds = new HashMap<>();
		Map<Integer, Set<Integer>> options = new HashMap<>();

		// "-5" is a parseable int but no item id is negative; "12:-3" and
		// "-7:4" carry negative halves that are equally meaningless; a
		// negative rep is no displayItemId. All skip like non-numerics.
		// The destination half stays unchecked: packed destinations at
		// plane >= 2 set the sign bit and are legitimately negative.
		TeleportRestriction.parseBlocked("-5,12:-3,-7:4,-13121@999,13121@-87359490",
			blocked, thresholds, options);

		Assert.assertTrue(blocked.isEmpty());
		Assert.assertTrue(thresholds.isEmpty());
		Assert.assertEquals(Map.of(13121, Set.of(-87359490)), options);
	}

	@Test
	public void toCsvSortsOptionRecordsByRepThenDestination()
	{
		String csv = TeleportRestriction.toCsv(Set.of(300, 100), Map.of(200, 5),
			Map.of(20, Set.of(9, 3), 7, Set.of(11)));

		Assert.assertEquals("100,300,200:5,7@11,20@3,20@9", csv);
	}

	@Test
	public void repAtDestRecordsRoundTripThroughSerializeAndParse()
	{
		Map<Integer, Set<Integer>> options =
			Map.of(13121, Set.of(87359490, 999), 2552, Set.of(42));

		String csv = TeleportRestriction.toCsv(Set.of(12), Map.of(34, 7), options);
		Assert.assertEquals("12,34:7,2552@42,13121@999,13121@87359490", csv);

		Set<Integer> parsedBlocked = new HashSet<>();
		Map<Integer, Integer> parsedThresholds = new HashMap<>();
		Map<Integer, Set<Integer>> parsedOptions = new HashMap<>();
		TeleportRestriction.parseBlocked(csv, parsedBlocked, parsedThresholds, parsedOptions);

		Assert.assertEquals(Set.of(12), parsedBlocked);
		Assert.assertEquals(Map.of(34, 7), parsedThresholds);
		Assert.assertEquals(options, parsedOptions);
	}

	@Test
	public void preFeatureCsvParsesIdenticallyThroughTheThreeOutputOverload()
	{
		Set<Integer> blocked = new HashSet<>();
		Map<Integer, Integer> thresholds = new HashMap<>();
		Map<Integer, Set<Integer>> options = new HashMap<>();

		TeleportRestriction.parseBlocked("123,abc,42:30,42:10", blocked, thresholds, options);

		Assert.assertEquals(Set.of(123), blocked);
		Assert.assertEquals(Map.of(42, 30), thresholds);
		Assert.assertTrue(options.isEmpty());
	}

	@Test
	public void representativeIndexCoversEveryFamilyMember()
	{
		Map<Integer, Integer> index = TeleportRestriction.representativeIndex();
		for (TeleportRestriction.Family family : TeleportRestriction.loadFamilies())
		{
			for (int member : family.memberItemIds())
			{
				Assert.assertEquals("member " + member + " of " + family.name(),
					family.displayItemId(), (int) index.getOrDefault(member, -1));
			}
		}
		Assert.assertTrue("a non-member id resolves to the negative default",
			index.getOrDefault(995, -1) < 0);
	}

	/**
	 * The Ardougne-cloaks family serves two distinct destinations: the
	 * monastery row every cloak reaches plus the farm rows gated on diary
	 * tier — both must surface with their Display-info labels.
	 */
	@Test
	public void ardougneCloaksExposeTheirTwoDestinationOptions()
	{
		int monastery = shortestpath.WorldPointUtil.packWorldPoint(2607, 3221, 0);
		int farm = shortestpath.WorldPointUtil.packWorldPoint(2665, 3374, 0);

		Assert.assertEquals(
			Map.of(monastery, "Kandarin Monastery", farm, "Ardougne Farm"),
			familyNamed("Ardougne cloaks").options());
	}

	/**
	 * The three varbit-gated Ardougne-farm rows (and the three Morytania
	 * slime-pit rows) share their destination and label — they collapse to
	 * one option, not three.
	 */
	@Test
	public void servingRowsSharingADestinationDedupeToOneOption()
	{
		Assert.assertEquals(2, familyNamed("Morytania legs").options().size());
		Assert.assertEquals(2, familyNamed("Ardougne cloaks").options().size());
	}

	/**
	 * A {@code Display info} cell carrying no {@code ':'} labels its option
	 * by the whole cell text.
	 */
	@Test
	public void noColonDisplayInfoLabelsByTheWholeCell()
	{
		TeleportRestriction.Family cowbell = familyNamed("Cowbell amulet");
		Assert.assertEquals(1, cowbell.options().size());
		Assert.assertTrue(cowbell.options().containsValue("Cowbell amulet"));
	}

	/**
	 * A family whose serving rows all reach one destination yields exactly
	 * one option entry — the UI grants it no option surface.
	 */
	@Test
	public void singleDestinationFamilyYieldsOneOptionEntry()
	{
		Assert.assertEquals(1, familyNamed("Fremennik sea boots").options().size());
	}

	/**
	 * The Skills necklace's two Farming Guild arrivals (the plain landing and
	 * the 45-Farming inside arrival) are one in-game teleport name — they
	 * collapse into a single option covering both tiles, while the other
	 * guilds keep their distinct entries.
	 */
	@Test
	public void skillsNecklaceCollapsesTheFarmingGuildArrivalsIntoOneOption()
	{
		TeleportRestriction.Family necklace = familyNamed("Skills necklace (1-6)");
		int farmingGuild = 0;
		for (String label : necklace.options().values())
		{
			if ("Farming Guild".equals(label))
			{
				farmingGuild++;
			}
		}
		Assert.assertEquals("the two Farming Guild arrivals collapse to one option",
			1, farmingGuild);
		Assert.assertEquals("the six real menu entries stay distinct options",
			6, necklace.options().size());
	}

	/**
	 * The house tablet's ten varbit-gated portal towns are not ten player
	 * choices: the in-game menu is "Inside the house" / "Outside the house",
	 * so the family yields exactly those two options.
	 */
	@Test
	public void teleportToHouseTabletYieldsInsideAndOutsideOnly()
	{
		TeleportRestriction.Family house = familyNamed("Teleport to house");
		Assert.assertEquals(2, house.options().size());
		Assert.assertTrue(house.options().containsValue("Inside the house"));
		Assert.assertTrue(house.options().containsValue("Outside the house"));
	}

	/**
	 * The Construction cape's varbit-gated home arrivals and its direct
	 * portal teleports reach the same tiles — they merge under the plain
	 * portal-town name rather than a "Home (town)" variant.
	 */
	@Test
	public void constructionCapeMergesHomeAndPortalRowsUnderTheTownName()
	{
		TeleportRestriction.Family capes =
			familyNamed("Construction cape");
		Assert.assertTrue(capes.options().containsValue("Rimmington"));
		Assert.assertTrue(capes.options().containsValue("Aldarin"));
		Assert.assertFalse(capes.options().containsValue("Home (Rimmington)"));
	}

	/**
	 * The Max cape's varbit-gated "Tele to POH" town arrivals merge into its
	 * unconditional "POH Portals" submenu entries on the shared tiles.
	 */
	@Test
	public void maxCapeMergesTeleToPohRowsUnderPohPortals()
	{
		TeleportRestriction.Family maxCapes = familyNamed("Max cape");
		Assert.assertTrue(maxCapes.options().containsValue("POH Portals: Rimmington"));
		Assert.assertTrue(maxCapes.options().containsValue("POH Portals: Aldarin"));
		Assert.assertFalse(maxCapes.options().containsValue("Tele to POH (Rimmington)"));
	}

	/**
	 * Royal and Grand seed pods are different items whose teleports land on
	 * the same Grand Tree tile — each per-item family yields its own option
	 * named for where the teleport goes.
	 */
	@Test
	public void seedPodFamiliesShareTheGrandTreeOption()
	{
		Assert.assertTrue(familyNamed("Royal seed pod").options()
			.containsValue("Grand Tree"));
		Assert.assertTrue(familyNamed("Grand seed pod").options()
			.containsValue("Grand Tree"));
	}

	/**
	 * An option record naming a group's canonical destination expands to
	 * every destination in the group, so the policy gate sees literal tiles.
	 */
	@Test
	public void expandOptionDestsExpandsACanonicalDestToItsGroup()
	{
		int outside = shortestpath.WorldPointUtil.packWorldPoint(1248, 3719, 0);
		int inside = shortestpath.WorldPointUtil.packWorldPoint(1248, 3725, 0);

		Map<Integer, Set<Integer>> expanded = TeleportRestriction.expandOptionDests(
			Map.of(11105, Set.of(outside)));

		Assert.assertEquals(Set.of(outside, inside), expanded.get(11105));
	}

	/**
	 * A stale record naming a non-canonical member of the group resolves to
	 * the same full group — TSV reordering can never orphan a stored block.
	 */
	@Test
	public void expandOptionDestsExpandsANonCanonicalMemberDestToTheSameGroup()
	{
		int outside = shortestpath.WorldPointUtil.packWorldPoint(1248, 3719, 0);
		int inside = shortestpath.WorldPointUtil.packWorldPoint(1248, 3725, 0);

		Map<Integer, Set<Integer>> expanded = TeleportRestriction.expandOptionDests(
			Map.of(11105, Set.of(inside)));

		Assert.assertEquals(Set.of(outside, inside), expanded.get(11105));
	}

	/**
	 * Records naming an unknown rep, or a rep whose dest belongs to no option
	 * group, pass through as literal blocked tiles — hand-edited or stale CSV
	 * degrades harmlessly rather than dropping the block.
	 */
	@Test
	public void expandOptionDestsPassesUnknownRepsAndDestsThrough()
	{
		Map<Integer, Set<Integer>> expanded = TeleportRestriction.expandOptionDests(
			Map.of(99999, Set.of(12345), 11105, Set.of(54321)));

		Assert.assertEquals(Set.of(12345), expanded.get(99999));
		Assert.assertEquals(Set.of(54321), expanded.get(11105));
	}

	/**
	 * The catch-all {@code # Other} bucket is split so every item family
	 * carries its own name in the restriction checklist — the blocker UI
	 * groups by family, so a shared bucket hid nine unrelated items under
	 * one meaningless heading.
	 */
	@Test
	public void theOtherBucketIsSplitIntoNamedItemFamilies()
	{
		Set<String> names = new HashSet<>();
		for (TeleportRestriction.Family family : TeleportRestriction.loadFamilies())
		{
			names.add(family.name());
		}
		Assert.assertFalse("no catch-all 'Other' family", names.contains("Other"));
		for (String expected : new String[]{
			"Pharaoh's sceptre", "Skull sceptre", "Xeric's talisman", "Chronicle",
			"Amulet of the eye", "Ring of the elements", "Hallowed crystal shard",
			"Ring of shadows", "Pendant of ates"})
		{
			Assert.assertTrue("family '" + expected + "' is its own checklist group",
				names.contains(expected));
		}
	}

	/**
	 * The charged Skull sceptre (9013) and its uncharged variant (21276)
	 * are one item for restriction purposes — toggling one must cover both,
	 * so they stay members of a single family.
	 */
	@Test
	public void skullSceptreGroupsBothItemIdsUnderOneFamily()
	{
		TeleportRestriction.Family sceptre = familyNamed("Skull sceptre");
		Assert.assertEquals(Set.of(9013, 21276), sceptre.memberItemIds());
		Assert.assertEquals(9013, sceptre.displayItemId());
	}

	/**
	 * A family's rep is its lowest member id — the checklist's display icon
	 * and every stored rep-{@code @}-dest record key off it.
	 */
	@Test
	public void splitFamiliesUseTheirLowestMemberIdAsTheDisplayId()
	{
		Map<String, Integer> expectedReps = Map.of(
			"Pharaoh's sceptre", 26948,
			"Xeric's talisman", 13393,
			"Chronicle", 13660,
			"Amulet of the eye", 26914,
			"Ring of the elements", 26818,
			"Hallowed crystal shard", 24709,
			"Ring of shadows", 28327,
			"Pendant of ates", 29893);
		for (Map.Entry<String, Integer> entry : expectedReps.entrySet())
		{
			TeleportRestriction.Family family = familyNamed(entry.getKey());
			Assert.assertEquals(entry.getKey() + " reps by its lowest member id",
				(int) entry.getValue(), family.displayItemId());
		}
	}

	/**
	 * The injected fairy-ring staff requirement is player-restrictable like an
	 * item family: the checklist's code-defined family must cover every staff
	 * variant the injected requirement accepts — the same ItemVariations name —
	 * and blocking the whole set must leave the ring requirement with no
	 * unblocked alternative while blocking a proper subset keeps it routable.
	 */
	@Test
	public void fairyStaffFamilyCoversEveryInjectedStaffVariant()
	{
		TeleportRestriction.Family staves = TeleportRestriction.fairyStaffFamily();

		Set<Integer> injected = new HashSet<>();
		for (int id : ItemVariations.fromName("DRAMEN_STAFF").getIds())
		{
			injected.add(id);
		}
		Assert.assertEquals("the family covers every staff id the ring requirement accepts",
			injected, staves.memberItemIds());
		Assert.assertTrue("displayItemId is a member",
			staves.memberItemIds().contains(staves.displayItemId()));
		for (int id : staves.memberItemIds())
		{
			Assert.assertFalse("member id " + id + " has a non-empty label",
				staves.memberLabels().getOrDefault(id, "").isEmpty());
		}

		// The injected requirement's shape — one AND entry whose OR branches
		// are the staff variants, the same construction
		// TransportEligibility#wrapFairyRingStaff merges onto the ring.
		TransportItems ringRequirement = new TransportItems(
			new int[][]{null},
			new int[][]{ItemVariations.fromName("DRAMEN_STAFF").getIds()},
			new int[][]{null},
			new int[]{1});
		Assert.assertFalse("blocking every staff variant disables the ring",
			ringRequirement.survivesBlockedItems(staves.memberItemIds()));
		Set<Integer> partial = new HashSet<>(staves.memberItemIds());
		partial.remove(partial.iterator().next());
		Assert.assertTrue("a surviving staff variant keeps the ring routable",
			ringRequirement.survivesBlockedItems(partial));
	}

	/**
	 * The staff family is checklist-only: the generated map's invariant —
	 * every member id traces to a {@code teleportation_items.tsv} Items
	 * cell — excludes it, so {@link TeleportRestriction#loadFamilies()} must
	 * not return it while {@link TeleportRestriction#checklistFamilies()}
	 * must add exactly it.
	 */
	@Test
	public void fairyStaffFamilyIsChecklistOnlyNotGenerated()
	{
		Set<Integer> staffIds = TeleportRestriction.fairyStaffFamily().memberItemIds();
		for (TeleportRestriction.Family family : TeleportRestriction.loadFamilies())
		{
			Assert.assertTrue("generated family '" + family.name()
				+ "' owns no fairy staff id",
				Collections.disjoint(family.memberItemIds(), staffIds));
		}

		List<TeleportRestriction.Family> checklist = TeleportRestriction.checklistFamilies();
		Assert.assertEquals("the checklist adds exactly one code-defined family",
			TeleportRestriction.loadFamilies().size() + 1, checklist.size());
		Assert.assertTrue("the added family is the fairy staves",
			checklist.stream().anyMatch(f -> f.name().equals("Fairy staves")));
	}

	private static TeleportRestriction.Family familyNamed(String name)
	{
		for (TeleportRestriction.Family family : TeleportRestriction.loadFamilies())
		{
			if (family.name().equals(name))
			{
				return family;
			}
		}
		throw new AssertionError("no restriction family named " + name);
	}
}

package shortestpath.requirement;

import java.util.Collection;
import java.util.Map;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import shortestpath.requirement.model.VarRequirement;

/**
 * A {@link RequirementHooks} implementation for tests — the same seam the
 * production {@code PathfinderConfig} adapter feeds. Quest state comes from a
 * settable field (the hook is consulted while the context captures declared
 * quests); varbit and varplayer evaluation runs the real
 * {@link VarRequirement#check} semantics against the values the chain passes
 * in — the maps captured into the context under test, mirroring how the
 * config's bypassable methods receive the per-refresh snapshot.
 *
 * <p>The {@code failVarbits}/{@code failVarPlayers} knobs force the failure
 * polarity ({@code true} = a check FAILED) for liveness assertions — the
 * single {@link #varChecks} impl picks the knob matching the dispatched
 * {@link VarRequirement.VarType} kind, so flipping one must move the verdict
 * of a chain that already exists without touching the other var family,
 * proving the gates read the seam per call rather than a frozen copy.
 */
final class TestRequirementHooks implements RequirementHooks
{
	private QuestState questState = QuestState.FINISHED;
	private boolean failVarbits;
	private boolean failVarPlayers;

	TestRequirementHooks questState(QuestState state)
	{
		questState = state;
		return this;
	}

	TestRequirementHooks failVarbits(boolean fail)
	{
		failVarbits = fail;
		return this;
	}

	TestRequirementHooks failVarPlayers(boolean fail)
	{
		failVarPlayers = fail;
		return this;
	}

	@Override
	public QuestState getQuestState(Quest quest)
	{
		return questState;
	}

	@Override
	public boolean varChecks(Collection<VarRequirement> requirements,
		Map<Integer, Integer> values, long evaluationTimeMinutes,
		VarRequirement.VarType kind)
	{
		final boolean fail;
		if (VarRequirement.VarType.VARBIT.equals(kind))
		{
			fail = failVarbits;
		}
		else if (VarRequirement.VarType.VARPLAYER.equals(kind))
		{
			fail = failVarPlayers;
		}
		else
		{
			throw new IllegalArgumentException("unhandled VarType " + kind);
		}
		for (VarRequirement requirement : requirements)
		{
			if (requirement.getVarType() == kind
				&& (fail || !requirement.check(values, evaluationTimeMinutes)))
			{
				return true;
			}
		}
		return false;
	}
}

package shortestpath.requirement;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.doAnswer;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import java.util.List;
import java.util.Map;
import java.util.Set;

import org.junit.Test;

import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import shortestpath.ItemVariations;
import shortestpath.items.ItemStateService;
import shortestpath.items.ItemStateTestServices;
import shortestpath.items.OwnedItems;
import shortestpath.pathfinder.BankVisitState;
import shortestpath.requirement.model.ItemRequirement;
import shortestpath.requirement.model.TransportItems;
import shortestpath.requirement.model.Unlock;
import shortestpath.settings.TeleportationItem;
import shortestpath.transport.Transport;
import shortestpath.transport.TransportType;

/**
 * Adversarial container and pouch cases for {@link TransportEligibility#collect}
 * — the one eligibility collection path shared by {@code RequirementContext.capture}
 * and {@code PathfinderConfig#getEligibility()}.
 */
public class TransportEligibilityCollectTest
{
	// ------------------------------------------------------------------
	// TransportEligibility.collect — adversarial container and pouch cases
	// ------------------------------------------------------------------

	private static final Transport THREE_AIR = needsItem(ItemVariations.fromName("AIR_RUNE").getIds(), 3);
	private static final Transport SHANTAY_GATE = needsItem(ItemVariations.fromName("SHANTAY_PASS").getIds(), 1);

	private static ItemContainer containerOf(Item... items)
	{
		ItemContainer container = mock(ItemContainer.class);
		when(container.getItems()).thenReturn(items);
		return container;
	}

	/**
	 * A {@code PlayerStateSource} Mockito stub: inventory/worn containers and
	 * the pouch runes are fixed; {@code addRunePouchContents} behaves like the
	 * real source — the pouch runes land in {@code owned} only when a pouch is
	 * already there. The Lumbridge diary varbit reads 0 (incomplete).
	 */
	private static PlayerStateSource sourceWith(ItemContainer inventory, ItemContainer worn,
		Map<Integer, Integer> pouchRunes)
	{
		PlayerStateSource source = mock(PlayerStateSource.class);
		when(source.itemContainer(InventoryID.INV)).thenReturn(inventory);
		when(source.itemContainer(InventoryID.WORN)).thenReturn(worn);
		when(source.runePouchContents()).thenReturn(pouchRunes);
		doAnswer(invocation ->
		{
			Map<Integer, Integer> owned = invocation.getArgument(0);
			if (OwnedItems.RUNE_POUCHES.stream().anyMatch(owned::containsKey))
			{
				pouchRunes.forEach((runeId, amount) -> owned.merge(runeId, amount, Integer::sum));
			}
			return null;
		}).when(source).addRunePouchContents(any());
		return source;
	}

	private static TransportEligibility collect(PlayerStateSource source, ItemContainer bank,
		TeleportationItem setting, boolean includeBankPath)
	{
		return TransportEligibility.collect(source, bank, setting,
			Integer.MAX_VALUE, includeBankPath, Set.<Unlock>of(), Set.of());
	}

	private static Transport needsItem(int[] itemIds, int quantity)
	{
		return new Transport.TransportBuilder()
			.type(TransportType.TRANSPORT)
			.itemRequirements(new TransportItems(List.of(
				new ItemRequirement(itemIds, new int[0], new int[0], quantity))))
			.build();
	}

	@Test
	public void collectEligibilityToleratesNullContainers()
	{
		PlayerStateSource source = sourceWith(null, null, Map.of());

		TransportEligibility eligibility = collect(source, null,
			TeleportationItem.INVENTORY_AND_BANK, true);

		assertNotNull(eligibility);
		assertFalse("no pool satisfies an item requirement without containers",
			eligibility.usable(THREE_AIR, BankVisitState.CARRIED));
		assertFalse(eligibility.usable(THREE_AIR, BankVisitState.BANKED));
	}

	@Test
	public void collectEligibilityToleratesEmptyContainers()
	{
		PlayerStateSource source = sourceWith(containerOf(), containerOf(), Map.of());

		TransportEligibility eligibility = collect(source, containerOf(),
			TeleportationItem.INVENTORY_AND_BANK, true);

		assertNotNull(eligibility);
		assertFalse(eligibility.usable(THREE_AIR, BankVisitState.CARRIED));
		assertFalse(eligibility.usable(THREE_AIR, BankVisitState.BANKED));
	}

	@Test
	public void nonPositiveQuantitiesAreSkippedByCollection()
	{
		// A zero-quantity stack and a placeholder (negative id) slot must not
		// count as owned items — the bank effectively holds nothing usable.
		ItemContainer bank = containerOf(new Item(ItemID.AIRRUNE, 0), new Item(-1, 5));
		PlayerStateSource source = sourceWith(null, null, Map.of());

		TransportEligibility eligibility = collect(source, bank,
			TeleportationItem.INVENTORY_AND_BANK, true);

		assertFalse("a zero-quantity air rune cannot satisfy the requirement",
			eligibility.usable(needsItem(ItemVariations.fromName("AIR_RUNE").getIds(), 1), BankVisitState.BANKED));
	}

	@Test
	public void bankSeededViaNoteBankContainerFeedsTheBankedPool()
	{
		ItemStateService service = ItemStateTestServices.forTesting();
		service.noteBankContainer(containerOf(new Item(ItemID.SHANTAY_PASS, 1)));
		PlayerStateSource source = sourceWith(null, null, Map.of());

		TransportEligibility eligibility = collect(source, service.getBank(),
			TeleportationItem.INVENTORY_AND_BANK, true);

		assertFalse("the bank item is not carried", eligibility.usable(SHANTAY_GATE, BankVisitState.CARRIED));
		assertTrue("the bank item enters the bank-path pool", eligibility.usable(SHANTAY_GATE, BankVisitState.BANKED));
	}

	@Test
	public void includeBankPathOffLeavesBankItemsOutOfTheBankedPool()
	{
		ItemStateService service = ItemStateTestServices.forTesting();
		service.noteBankContainer(containerOf(new Item(ItemID.SHANTAY_PASS, 1)));
		PlayerStateSource source = sourceWith(null, null, Map.of());

		TransportEligibility eligibility = collect(source, service.getBank(),
			TeleportationItem.INVENTORY_AND_BANK, false);

		assertFalse("with bank paths off the banked pool is the carried pool",
			eligibility.usable(SHANTAY_GATE, BankVisitState.BANKED));
	}

	@Test
	public void bankedRunePouchSuppliesItsRunesOnTheBankPath()
	{
		ItemStateService service = ItemStateTestServices.forTesting();
		service.noteBankContainer(containerOf(new Item(ItemID.BH_RUNE_POUCH, 1)));
		PlayerStateSource source = sourceWith(null, null, Map.of(ItemID.AIRRUNE, 3));

		TransportEligibility eligibility = collect(source, service.getBank(),
			TeleportationItem.INVENTORY_AND_BANK, true);

		assertFalse("pouch runes are not carried", eligibility.usable(THREE_AIR, BankVisitState.CARRIED));
		assertTrue("a banked pouch's runes feed the bank-path pool",
			eligibility.usable(THREE_AIR, BankVisitState.BANKED));
	}

	@Test
	public void firstPouchInDeclaredOrderIsSelected()
	{
		// The bank holds two pouch variants; the selector must pick the one
		// earliest in the declared pouch order (BH before DIVINE).
		ItemStateService service = ItemStateTestServices.forTesting();
		service.noteBankContainer(containerOf(
			new Item(ItemID.DIVINE_RUNE_POUCH, 1), new Item(ItemID.BH_RUNE_POUCH, 1)));
		PlayerStateSource source = sourceWith(null, null, Map.of(ItemID.AIRRUNE, 3));

		TransportEligibility eligibility = collect(source, service.getBank(),
			TeleportationItem.INVENTORY_AND_BANK, true);
		TransportEligibility.BankPickupPlan plan = eligibility.bankPickupPlan(THREE_AIR);

		assertTrue("the declared-first pouch supplies the runes",
			plan.bankItemIds.contains(ItemID.BH_RUNE_POUCH));
		assertFalse("a later pouch is never the selected one",
			plan.bankItemIds.contains(ItemID.DIVINE_RUNE_POUCH));
	}

	@Test
	public void bankWithoutPouchNeverConsultsPouchRunes()
	{
		// The source reports pouch runes, but without a pouch in the bank the
		// bank-pouch rune pool must stay empty and the pickup unsatisfiable.
		ItemStateService service = ItemStateTestServices.forTesting();
		service.noteBankContainer(containerOf());
		PlayerStateSource source = sourceWith(null, null, Map.of(ItemID.AIRRUNE, 3));

		TransportEligibility eligibility = collect(source, service.getBank(),
			TeleportationItem.INVENTORY_AND_BANK, true);

		assertFalse(eligibility.usable(THREE_AIR, BankVisitState.BANKED));
		assertNull("the bank cannot supply the runes", eligibility.bankPickupPlan(THREE_AIR).items);
	}
}

package shortestpath.requirement.model;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNotSame;

import java.util.List;
import org.junit.Test;

/**
 * Contract pin for {@link ItemRequirement} and {@link ItemRequirement.Branch}
 * equality: a requirement is its ordered branch list, and a branch is its
 * three id arrays, quantity and unlock. Hash-consistency is asserted, never
 * hash values.
 */
public class ItemRequirementTest
{
	@Test
	public void branchEqualityCoversEveryField()
	{
		ItemRequirement.Branch first = new ItemRequirement.Branch(new int[]{1, 2}, null, null, 1);
		ItemRequirement.Branch second = new ItemRequirement.Branch(new int[]{1, 2}, null, null, 1);

		assertNotSame(first, second);
		assertEquals(first, first);
		assertEquals(first, second);
		assertEquals(first.hashCode(), second.hashCode());

		// Each field is part of the key: a single-field mutation is unequal.
		assertNotEquals(first, new ItemRequirement.Branch(new int[]{1, 3}, null, null, 1));
		assertNotEquals(first, new ItemRequirement.Branch(new int[]{1, 2}, new int[]{4}, null, 1));
		assertNotEquals(first, new ItemRequirement.Branch(new int[]{1, 2}, null, new int[]{5}, 1));
		assertNotEquals(first, new ItemRequirement.Branch(new int[]{1, 2}, null, null, 2));
		assertNotEquals(first,
			new ItemRequirement.Branch(new int[]{1, 2}, null, null, 1, Unlock.CANOE_AXE));
		assertFalse(first.equals(null));
		assertNotEquals(first, "branch");
	}

	@Test
	public void requirementEqualityFollowsTheBranchList()
	{
		ItemRequirement first = new ItemRequirement(List.of(
			new ItemRequirement.Branch(new int[]{1, 2}, null, null, 1),
			new ItemRequirement.Branch(new int[]{3}, new int[]{4}, null, 5)));
		ItemRequirement second = new ItemRequirement(List.of(
			new ItemRequirement.Branch(new int[]{1, 2}, null, null, 1),
			new ItemRequirement.Branch(new int[]{3}, new int[]{4}, null, 5)));

		assertNotSame(first, second);
		assertEquals(first, second);
		assertEquals(first.hashCode(), second.hashCode());

		// The array-constructor shape produces an equal requirement.
		assertEquals(new ItemRequirement(new int[]{1, 2}, null, null, 1),
			new ItemRequirement(List.of(new ItemRequirement.Branch(new int[]{1, 2}, null, null, 1))));

		// A differing branch makes the requirement differ.
		ItemRequirement other = new ItemRequirement(List.of(
			new ItemRequirement.Branch(new int[]{1, 2}, null, null, 1),
			new ItemRequirement.Branch(new int[]{3}, new int[]{4}, null, 6)));
		assertNotEquals(first, other);

		// Declaration order is part of the value.
		ItemRequirement reordered = new ItemRequirement(List.of(
			new ItemRequirement.Branch(new int[]{3}, new int[]{4}, null, 5),
			new ItemRequirement.Branch(new int[]{1, 2}, null, null, 1)));
		assertNotEquals(first, reordered);

		assertFalse(first.equals(null));
	}
}

package shortestpath.requirement.model;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNotSame;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

import java.util.Arrays;
import net.runelite.api.Skill;
import org.junit.Test;
import shortestpath.requirement.RejectionReason;

/**
 * Contract pin for {@link SkillLevels}: the extended-index layout
 * ({@code Skill.values().length + 4}), the {@code Max} sentinel, the
 * flyweight {@code NONE} compaction, clone discipline, the per-index
 * maximum table and the folded gate loop ({@code missingRequirement}).
 */
public class SkillLevelsTest
{
	private static final int QP_CAP = 300;

	private static int[] maxed()
	{
		int[] levels = new int[SkillLevels.LENGTH];
		Arrays.fill(levels, 99);
		levels[SkillLevels.TOTAL_LEVEL_INDEX] = 99 * Skill.values().length;
		levels[SkillLevels.COMBAT_LEVEL_INDEX] = 126;
		levels[SkillLevels.QUEST_POINTS_INDEX] = QP_CAP;
		return levels;
	}

	private static SkillLevels requiring(int index, int level)
	{
		int[] levels = new int[SkillLevels.LENGTH];
		levels[index] = level;
		return SkillLevels.of(levels);
	}

	@Test
	public void layoutConstantsMatchTheExtendedIndexContract()
	{
		assertEquals(Skill.values().length + 4, SkillLevels.LENGTH);
		assertEquals(Skill.values().length, SkillLevels.TOTAL_LEVEL_INDEX);
		assertEquals(Skill.values().length + 1, SkillLevels.COMBAT_LEVEL_INDEX);
		assertEquals(Skill.values().length + 2, SkillLevels.QUEST_POINTS_INDEX);
		assertEquals(Skill.values().length + 3, SkillLevels.MUSIC_TRACKS_INDEX);
		assertEquals("the TSV Max sentinel is not a level", Integer.MAX_VALUE, SkillLevels.MAX_LEVEL);
	}

	@Test
	public void ofCompactsNullAndAllZeroOntoNone()
	{
		assertSame(SkillLevels.NONE, SkillLevels.of(null));
		assertSame(SkillLevels.NONE, SkillLevels.of(new int[SkillLevels.LENGTH]));
		assertSame("a short all-zero array still declares nothing",
			SkillLevels.NONE, SkillLevels.of(new int[3]));
		assertTrue(SkillLevels.NONE.isEmpty());
	}

	@Test
	public void ofClonesAndZeroPadsToLength()
	{
		int[] source = new int[SkillLevels.LENGTH];
		source[Skill.AGILITY.ordinal()] = 50;
		SkillLevels wrapped = SkillLevels.of(source);
		assertNotSame(SkillLevels.NONE, wrapped);
		assertEquals(50, wrapped.get(Skill.AGILITY));

		// Mutating the source afterwards changes nothing.
		source[Skill.AGILITY.ordinal()] = 1;
		assertEquals(50, wrapped.get(Skill.AGILITY));

		// Short input pads the tail with zeros; longer input normalises to LENGTH.
		SkillLevels shortWrapped = SkillLevels.of(new int[]{50});
		assertEquals(SkillLevels.LENGTH, shortWrapped.length());
		assertEquals(50, shortWrapped.get(0));
		assertEquals(0, shortWrapped.get(SkillLevels.TOTAL_LEVEL_INDEX));
		assertEquals(SkillLevels.LENGTH,
			SkillLevels.of(new int[SkillLevels.LENGTH + 2]).length());
	}

	@Test
	public void accessorsReadTheSkillOrdinalsAndTail()
	{
		SkillLevels levels = SkillLevels.of(maxed());
		assertEquals(99, levels.get(Skill.COOKING));
		assertEquals(99, levels.get(Skill.COOKING.ordinal()));
		assertEquals(99 * Skill.values().length, levels.totalLevel());
		assertEquals(126, levels.combatLevel());
		assertEquals(QP_CAP, levels.get(SkillLevels.QUEST_POINTS_INDEX));
		assertEquals(levels.totalLevel(), levels.get(SkillLevels.TOTAL_LEVEL_INDEX));
		assertEquals(levels.combatLevel(), levels.get(SkillLevels.COMBAT_LEVEL_INDEX));
	}

	@Test
	public void toArrayHandsOutADefensiveCopy()
	{
		SkillLevels levels = SkillLevels.of(maxed());
		int[] copy = levels.toArray();
		assertArrayEquals(maxed(), copy);
		copy[Skill.COOKING.ordinal()] = 1;
		assertEquals("mutating the copy must not corrupt the value", 99, levels.get(Skill.COOKING));
	}

	@Test
	public void isEmptyReportsOnlyTheAllZeroSet()
	{
		assertTrue(SkillLevels.NONE.isEmpty());
		assertTrue(SkillLevels.of(new int[SkillLevels.LENGTH]).isEmpty());
		assertFalse(requiring(Skill.COOKING.ordinal(), 1).isEmpty());
		assertFalse(requiring(SkillLevels.TOTAL_LEVEL_INDEX, 1).isEmpty());
	}

	@Test
	public void mergeTakesTheElementwiseMaximum()
	{
		SkillLevels cooking50 = requiring(Skill.COOKING.ordinal(), 50);
		SkillLevels cooking70 = requiring(Skill.COOKING.ordinal(), 70);
		SkillLevels merged = SkillLevels.merge(cooking50, cooking70);
		assertEquals(70, merged.get(Skill.COOKING));
		assertEquals(SkillLevels.LENGTH, merged.length());

		// The empty arm hands back the other side — no allocation.
		assertSame(cooking50, SkillLevels.merge(cooking50, SkillLevels.NONE));
		assertSame(cooking70, SkillLevels.merge(SkillLevels.NONE, cooking70));
		assertSame(SkillLevels.NONE, SkillLevels.merge(null, null));
		assertSame(cooking50, SkillLevels.merge(cooking50, null));
		assertSame(cooking70, SkillLevels.merge(null, cooking70));
	}

	@Test
	public void equalsAndHashCodeFollowTheContents()
	{
		SkillLevels first = SkillLevels.of(maxed());
		SkillLevels second = SkillLevels.of(maxed());
		assertNotSame(first, second);
		assertEquals(first, second);
		assertEquals(first.hashCode(), second.hashCode());
		assertEquals(SkillLevels.NONE, SkillLevels.of(new int[SkillLevels.LENGTH]));
		assertNotEquals(first, SkillLevels.NONE);
		assertNotEquals(first, requiring(Skill.COOKING.ordinal(), 99));
	}

	@Test
	public void maximumLevelResolvesTheCapPerIndex()
	{
		assertEquals(99, SkillLevels.maximumLevel(Skill.COOKING.ordinal(), QP_CAP, 99));
		assertEquals(99 * Skill.values().length,
			SkillLevels.maximumLevel(SkillLevels.TOTAL_LEVEL_INDEX, QP_CAP, 99));
		assertEquals(126, SkillLevels.maximumLevel(SkillLevels.COMBAT_LEVEL_INDEX, QP_CAP, 99));
		// The quest-point cap is refresh state — a parameter, not a constant.
		assertEquals(QP_CAP, SkillLevels.maximumLevel(SkillLevels.QUEST_POINTS_INDEX, QP_CAP, 99));
		assertEquals(200, SkillLevels.maximumLevel(SkillLevels.QUEST_POINTS_INDEX, 200, 99));
		assertEquals(700, SkillLevels.maximumLevel(SkillLevels.MUSIC_TRACKS_INDEX, QP_CAP, 700));
		// Out-of-range indices keep the sentinel — they declare no cap.
		assertEquals(SkillLevels.MAX_LEVEL, SkillLevels.maximumLevel(SkillLevels.LENGTH, QP_CAP, 99));
	}

	@Test
	public void missingRequirementSkipsOnlyTheTotalSlotInSeasonalMode()
	{
		int[] seasonalPlayer = maxed();
		seasonalPlayer[SkillLevels.TOTAL_LEVEL_INDEX] = 0;
		SkillLevels player = SkillLevels.of(seasonalPlayer);
		SkillLevels totalGated = requiring(SkillLevels.TOTAL_LEVEL_INDEX, 99 * Skill.values().length);

		assertEquals("seasonal mode skips the total-level check",
			RejectionReason.NONE, player.missingRequirement(totalGated, true, QP_CAP, 99));
		assertEquals("non-seasonal mode still checks the total",
			RejectionReason.SKILL_LEVEL, player.missingRequirement(totalGated, false, QP_CAP, 99));

		// The skip names only the total index — a per-skill shortfall still rejects.
		int[] weakCooking = maxed();
		weakCooking[Skill.COOKING.ordinal()] = 50;
		weakCooking[SkillLevels.TOTAL_LEVEL_INDEX] = 0;
		SkillLevels seasonalWeak = SkillLevels.of(weakCooking);
		assertEquals(RejectionReason.SKILL_LEVEL,
			seasonalWeak.missingRequirement(requiring(Skill.COOKING.ordinal(), 99), true, QP_CAP, 99));
	}

	@Test
	public void missingRequirementReadsMissingIndicesAsZero()
	{
		SkillLevels player = SkillLevels.of(maxed());

		// NONE declares nothing — it can never reject.
		assertEquals(RejectionReason.NONE,
			player.missingRequirement(SkillLevels.NONE, false, QP_CAP, 99));
		assertEquals(RejectionReason.NONE,
			SkillLevels.NONE.missingRequirement(SkillLevels.NONE, false, QP_CAP, 99));

		// A requirement shorter than the player reads 0 past its end.
		SkillLevels shortRequired = SkillLevels.of(new int[]{50});
		assertEquals(RejectionReason.NONE,
			player.missingRequirement(shortRequired, false, QP_CAP, 99));
		assertEquals(RejectionReason.SKILL_LEVEL,
			SkillLevels.NONE.missingRequirement(shortRequired, false, QP_CAP, 99));
	}

	@Test
	public void missingRequirementResolvesMaxPerIndex()
	{
		int[] allMax = new int[SkillLevels.LENGTH];
		Arrays.fill(allMax, SkillLevels.MAX_LEVEL);
		SkillLevels maxRequired = SkillLevels.of(allMax);
		SkillLevels player = SkillLevels.of(maxed());
		assertEquals(RejectionReason.NONE,
			player.missingRequirement(maxRequired, false, QP_CAP, 99));

		// Max on the quest-point slot resolves against the refresh-state cap.
		int[] belowCap = maxed();
		belowCap[SkillLevels.QUEST_POINTS_INDEX] = QP_CAP - 1;
		assertEquals(RejectionReason.SKILL_LEVEL,
			SkillLevels.of(belowCap).missingRequirement(
				requiring(SkillLevels.QUEST_POINTS_INDEX, SkillLevels.MAX_LEVEL), false, QP_CAP, 99));

		// A literal requirement at the Max sentinel resolves the same way.
		SkillLevels literalCap = requiring(Skill.COOKING.ordinal(), SkillLevels.MAX_LEVEL);
		assertEquals(RejectionReason.NONE, player.missingRequirement(literalCap, false, QP_CAP, 99));
	}

	@Test
	public void missingRequirementReportsTheFirstShortfall()
	{
		int[] weak = maxed();
		weak[Skill.COOKING.ordinal()] = 50;
		weak[Skill.ATTACK.ordinal()] = 1;
		SkillLevels player = SkillLevels.of(weak);

		int[] required = new int[SkillLevels.LENGTH];
		required[Skill.COOKING.ordinal()] = 99;
		required[Skill.ATTACK.ordinal()] = 50;
		assertEquals(RejectionReason.SKILL_LEVEL,
			player.missingRequirement(SkillLevels.of(required), false, QP_CAP, 99));

		// Meeting every requirement accepts.
		assertEquals(RejectionReason.NONE,
			player.missingRequirement(requiring(Skill.MAGIC.ordinal(), 50), false, QP_CAP, 99));
	}
}

