		when(client.getVarbitValue(VarbitID.SAILING_SIDEPANEL_BOAT_BASESPEED)).thenReturn(160);
		service.onVarbitChanged(VarbitID.SAILING_SIDEPANEL_BOAT_BASESPEED);

