		verify(scheduler, never()).isNearPath(anyInt());
		verify(scheduler, never()).restart(anyString(), anyInt(), any(Targets.class));
		verify(scheduler, never()).restart(anyString(), anyInt(), any(Targets.class), anyBoolean());
