	/**
	 * The keyed rows that are <i>also</i> declared as {@code @ConfigItem}s so
	 * the stock config panel can reach them — their sidebar read/write path is
	 * unchanged (raw {@code ConfigManager} keyed reads), and they keep their
	 * bundled {@code config-items.tsv} metadata because {@code Settings.item}
	 * resolves the TSV on every seam, including the descriptor-less wrap seam
	 * the panel tests run on. 26 names.
	 */
	private static final Set<String> DECLARED_KEYED_KEYS = new TreeSet<>(Arrays.asList(
		"aStarHeuristicWeight",
		"avoidWilderness",
		"calculationCutoff",
		"cancelInstead",
		"collisionAwareBlockedTargets",
		"costBankVisit",
		"currencyThreshold",
		"finishDistance",
		"highlightBankPickupItems",
		"highlightInventoryItems",
		"highlightSpellbookSpells",
		"includeBankPath",
		"recalculateDistance",
		"respawnPrifddinas",
		"showBankPickupInfo",
		"showTileCounter",
		"showTransportInfo",
		"showUnreachableText",
		"tileCounterStep",
		"unlockCanoeAxe",
		"unlockDragontoothPassage",
		"unlockMorUlRek",
		"unlockXericsHonour",
		"unreachableTargetDistanceThreshold",
		"useSailingMoves",
		"useTeleportationItems"
	));

	/**
	 * Scans every {@code @ConfigItem} on {@link ShortestPathConfig}: the
	 * {@code hidden} flag must agree with pinned membership on every method —
	 * including the getter/setter write pairs — and the collected hidden set
	 * must equal the pinned set exactly.
	 */
	@Test
	public void exactlyThePanelOwnedKeysAreHidden()
	{
		assertEquals("the pinned boundary is 61 keyNames", 61, PANEL_OWNED_KEYS.size());

		// The hidden-key surface lives in the keyed registry, not on the
		// interface: no @ConfigItem may carry hidden=true any more, and every
		// panel-owned key resolves to a keyed registry row with metadata.
		Set<String> annotatedKeys = new TreeSet<>();
		List<String> boundaryViolations = new ArrayList<>();
		for (Method method : ShortestPathConfig.class.getMethods())
		{
			ConfigItem item = method.getAnnotation(ConfigItem.class);
			if (item == null)
			{
				continue;
			}
			annotatedKeys.add(item.keyName());
			if (item.hidden())
			{
				boundaryViolations.add(method.getName() + " (keyName=" + item.keyName() + ")");
			}
		}
		assertTrue("@ConfigItems still carrying hidden=true: " + boundaryViolations,
			boundaryViolations.isEmpty());

		Set<String> missing = new TreeSet<>(PANEL_OWNED_KEYS);
		missing.removeIf(key ->
		{
			ConfigKey row = ConfigKey.forKey(key);
			return row != null && !annotatedKeys.contains(key)
				&& ConfigItems.of(key) != null;
		});
		assertTrue("panel-owned keys missing a keyed row or metadata: " + missing,
			missing.isEmpty());
	}

	/**
	 * Every declared keyed row must keep all three halves of its contract:
	 * a keyed {@link ConfigKey} row (the read/write path the sidebar and the
	 * keyed seam share), a declared {@code @ConfigItem} getter (the stock
	 * panel surface), and a bundled {@code config-items.tsv} row (the
	 * metadata source {@code Settings.item} resolves first on every seam).
	 * Losing any one strands the key on one of the two surfaces.
	 */
	@Test
	public void declaredKeyedRowsStayKeyedAnnotatedAndMetadataComplete()
	{
		assertEquals("the declared keyed set is 26 keyNames", 26, DECLARED_KEYED_KEYS.size());

		Set<String> annotated = new TreeSet<>();
		for (Method method : ShortestPathConfig.class.getMethods())
		{
			ConfigItem item = method.getAnnotation(ConfigItem.class);
			if (item != null && method.getParameterCount() == 0
				&& method.getReturnType() != void.class)
			{
				annotated.add(item.keyName());
			}
		}

		List<String> violations = new ArrayList<>();
		for (String key : DECLARED_KEYED_KEYS)
		{
			ConfigKey row = ConfigKey.forKey(key);
			if (row == null)
			{
				violations.add(key + " lost its keyed ConfigKey row");
			}
			if (!annotated.contains(key))
			{
				violations.add(key + " lost its @ConfigItem declaration");
			}
			if (ConfigItems.of(key) == null)
			{
				violations.add(key + " lost its config-items.tsv metadata row");
			}
		}
		assertTrue("declared keyed rows with a broken leg: " + violations,
			violations.isEmpty());
	}

	/**
	 * For a declared keyed key the TSV row and the {@code @ConfigItem}
	 * annotation describe the same setting twice — the TSV feeds
	 * {@code Settings.item} (sidebar + every descriptor-less seam) while the
	 * annotation feeds the stock panel — so name, description and range
	 * bounds must agree verbatim, or the two surfaces drift.
	 */
	@Test
	public void declaredKeyedMetadataMatchesTheAnnotation()
	{
		List<String> mismatches = new ArrayList<>();
		for (Method method : ShortestPathConfig.class.getMethods())
		{
			ConfigItem item = method.getAnnotation(ConfigItem.class);
			if (item == null || !DECLARED_KEYED_KEYS.contains(item.keyName()))
			{
				continue;
			}
			ConfigItems.Meta meta = ConfigItems.of(item.keyName());
			if (meta == null)
			{
				mismatches.add(item.keyName() + " has no tsv row");
				continue;
			}
			if (!item.name().equals(meta.name()))
			{
				mismatches.add(item.keyName() + " name: tsv='" + meta.name()
					+ "' annotation='" + item.name() + "'");
			}
			if (!item.description().equals(meta.description()))
			{
				mismatches.add(item.keyName() + " description: tsv='" + meta.description()
					+ "' annotation='" + item.description() + "'");
			}
			Range range = method.getAnnotation(Range.class);
			Integer min = range == null ? null : range.min();
			Integer max = range == null ? null : range.max();
			if (!java.util.Objects.equals(min, meta.min()) || !java.util.Objects.equals(max, meta.max()))
			{
				mismatches.add(item.keyName() + " range: tsv=[" + meta.min() + "," + meta.max()
					+ "] annotation=[" + min + "," + max + "]");
			}
		}
		assertTrue("declared keyed rows with drifting metadata: " + mismatches,
			mismatches.isEmpty());
	}

	/**
	 * The settings panel keeps exactly its five real sections — Settings,
	 * Display, Colours, Hotkeys and Debug Options. The two "(Moved To
	 * Sidebar)" pointer sections rendered as empty collapsible headers
	 * once their items went hidden, so they are deleted outright: a
	 * hidden item needs no section to stay hidden. Pinning the set
	 * catches both a re-appearing stub section and an accidentally
	 * dropped real one.
	 */
	@Test
	public void onlyTheRealSettingsSectionsRemain()
	{
		Set<String> sectionNames = new TreeSet<>();
		for (Field field : ShortestPathConfig.class.getDeclaredFields())
		{
			ConfigSection section = field.getAnnotation(ConfigSection.class);
			if (section != null)
			{
				sectionNames.add(section.name());
			}
		}
		assertEquals("the settings surface keeps exactly its five sections",
			new TreeSet<>(Arrays.asList(
				"Settings", "Display", "Colours", "Hotkeys", "Debug Options")),
			sectionNames);
	}

	/**
	 * The sidebar-visibility toggle is a Settings-surface item, not a
	 * panel-owned key: it must exist, stay {@code hidden = false} (so it is
	 * never absorbed into {@link #PANEL_OWNED_KEYS}), live in the Settings
	 * section and default on — the sidebar icon is the panel's only entry
	 * point, so hiding it must be a deliberate opt-out.
	 */
	@Test
	public void sidebarToggleIsAVisibleSettingsItem()
	{
		ConfigItem item = null;
		Method getter = null;
		for (Method method : ShortestPathConfig.class.getMethods())
		{
			ConfigItem found = method.getAnnotation(ConfigItem.class);
			if (found != null && "showSidebarPanel".equals(found.keyName())
				&& method.getParameterCount() == 0 && method.getReturnType() != void.class)
			{
				item = found;
				getter = method;
			}
		}
		assertNotNull("a showSidebarPanel @ConfigItem exists", item);
		assertFalse("the sidebar toggle is not a panel-owned hidden key", item.hidden());
		assertEquals("the toggle lives in the Settings section",
			"sectionSettings", item.section());
		assertEquals("the toggle is a boolean read",
			boolean.class, getter.getReturnType());
		assertTrue("the sidebar icon shows by default — hiding is opt-out",
			new TestShortestPathConfig().showSidebarPanel());
	}
}

package shortestpath.settings;

import static org.junit.Assert.assertEquals;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.SortedSet;
import java.util.TreeSet;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

import org.junit.Test;

import shortestpath.transport.TransportType;

/**
 * The keys routing reads must be exactly the {@link ConfigKey} rows marked
 * {@link Effect#ROUTE_INVALIDATING}: a routing read without the effect leaves
 * a running route stale after the setting changes, and the effect on a key
 * routing never reads restarts searches for nothing.
 *
 * <p>Routing reads its settings in {@code PathfinderConfig}, either as a
 * {@code ConfigKey.X} constant or through a transport type's enabled, cost
 * and differential-cost keys; a {@code flag:} set default also reads its flag.
 */
public class RoutingKeyParityTest
{
	private static final Pattern CONSTANT = Pattern.compile("ConfigKey\\.([A-Z][A-Z_]+)\\b");

	@Test
	public void routingReadsAreExactlyTheRouteInvalidatingRows() throws IOException
	{
		String source = new String(Files.readAllBytes(
			Paths.get("src/main/java/shortestpath/pathfinder/PathfinderConfig.java")));
		SortedSet<ConfigKey> read = new TreeSet<>();
		Matcher constant = CONSTANT.matcher(source);
		while (constant.find())
		{
			read.add(ConfigKey.valueOf(constant.group(1)));
		}
		for (TransportType type : TransportType.values())
		{
			for (String key : new String[]{type.getEnabledKey(), type.getCostKey(), type.differentialCostKey()})
			{
				if (key != null)
				{
					read.add(ConfigKey.forKey(key));
				}
			}
		}
		for (ConfigKey key : new TreeSet<>(read))
		{
			if (key.getFlag() != null)
			{
				read.add(key.getFlag());
			}
		}

		SortedSet<ConfigKey> routeInvalidating = new TreeSet<>();
		for (ConfigKey key : ConfigKey.values())
		{
			if (key.getEffects().contains(Effect.ROUTE_INVALIDATING))
			{
				routeInvalidating.add(key);
			}
		}
		assertEquals(routeInvalidating, read);
	}
}

package shortestpath.settings;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

import java.awt.Color;
import java.lang.invoke.MethodHandles;
import java.lang.reflect.Method;
import java.lang.reflect.Proxy;
import java.util.EnumSet;
import java.util.Map;
import java.util.Set;

import org.junit.Test;

import net.runelite.client.config.ConfigItem;
import shortestpath.ShortestPathConfig;
import shortestpath.TestShortestPathConfig;
import shortestpath.TileCounter;
import shortestpath.TileStyle;
import shortestpath.poh.PohNexusPortal;
import shortestpath.transport.TransportType;

/** A key's value is its override (when it has the key's type), else its stored value, else its default. */
public class SettingsTest
{
	private final TestShortestPathConfig config = new TestShortestPathConfig();
	private final Settings settings = Settings.wrap(config);

	@Test
	public void overrideWinsOverStoredWinsOverDefault()
	{
		assertEquals(100000, settings.num(ConfigKey.CURRENCY_THRESHOLD));
		config.set("currencyThreshold", 40);
		assertEquals(40, settings.num(ConfigKey.CURRENCY_THRESHOLD));
		settings.applyOverrides(Map.of("currencyThreshold", 70));
		assertEquals(70, settings.num(ConfigKey.CURRENCY_THRESHOLD));
		settings.clearOverrides();
		assertEquals(40, settings.num(ConfigKey.CURRENCY_THRESHOLD));
	}

	@Test
	public void overrideOfAnotherTypeIsIgnored()
	{
		settings.applyOverrides(Map.of("avoidWilderness", "no", "currencyThreshold", true, "colourPath", 7));
		assertTrue(settings.bool(ConfigKey.AVOID_WILDERNESS));
		assertEquals(100000, settings.num(ConfigKey.CURRENCY_THRESHOLD));
		assertEquals(new Color(255, 0, 0), settings.get(ConfigKey.COLOUR_PATH));
	}

	@Test
	public void enumOverridesUseTheDisplayName()
	{
		settings.applyOverrides(Map.of("pathStyle", "Arrow line", "showTileCounter", "REMAINING"));
		assertEquals(TileStyle.ARROW_LINE, settings.get(ConfigKey.PATH_STYLE));
		assertEquals(TileCounter.DISABLED, settings.get(ConfigKey.SHOW_TILE_COUNTER));
	}

	@Test
	public void overridesAreKeptVerbatimForTheEcho()
	{
		Map<String, Object> payload = Map.of("notAKey", 1, "useBoats", false);
		settings.applyOverrides(payload);
		assertEquals(payload, settings.getOverrides());
		settings.applyOverrides(Map.of());
		assertEquals("an empty payload keeps the overrides", payload, settings.getOverrides());
	}

	@Test
	public void configuredIgnoresOverrides()
	{
		settings.applyOverrides(Map.of("avoidWilderness", false));
		assertFalse(settings.bool(ConfigKey.AVOID_WILDERNESS));
		assertEquals(true, settings.configured("avoidWilderness"));
	}

	@Test(expected = IllegalArgumentException.class)
	public void configuredRejectsUnknownKeys()
	{
		settings.configured("notAKey");
	}

	@Test
	public void flagSetDefaultFollowsTheFlagUntilTheSetIsWritten()
	{
		config.set("useTeleportationPortalsPoh", true);
		assertEquals(EnumSet.allOf(PohNexusPortal.class), settings.get(ConfigKey.POH_NEXUS_PORTALS));
		settings.applyOverrides(Map.of("useTeleportationPortalsPoh", false));
		assertEquals(Set.of(), settings.get(ConfigKey.POH_NEXUS_PORTALS));
		assertEquals("the panel shows the configured flag",
			EnumSet.allOf(PohNexusPortal.class), settings.configured("pohNexusPortals"));
		config.setPohNexusPortalsValue(Set.of(PohNexusPortal.VARROCK));
		assertEquals(Set.of(PohNexusPortal.VARROCK), settings.get(ConfigKey.POH_NEXUS_PORTALS));
	}

	@Test
	public void transportTypeKeysHaveRows()
	{
		for (TransportType type : TransportType.values())
		{
			for (String key : new String[]{type.getEnabledKey(), type.getCostKey(), type.differentialCostKey()})
			{
				if (key != null)
				{
					assertNotNull(type + " names " + key, ConfigKey.forKey(key));
				}
			}
		}
	}

	/** Display keys appear in RuneLite's config panel too, so their default is declared twice. */
	@Test
	public void defaultsMatchTheConfigItemDefaults() throws Throwable
	{
		ShortestPathConfig defaults = (ShortestPathConfig) Proxy.newProxyInstance(
			ShortestPathConfig.class.getClassLoader(), new Class<?>[]{ShortestPathConfig.class},
			(proxy, method, args) -> MethodHandles.privateLookupIn(ShortestPathConfig.class, MethodHandles.lookup())
				.unreflectSpecial(method, ShortestPathConfig.class).bindTo(proxy).invokeWithArguments(args));
		Settings unwritten = Settings.wrap(defaults);
		for (Method method : ShortestPathConfig.class.getMethods())
		{
			ConfigItem item = method.getAnnotation(ConfigItem.class);
			if (item == null || method.getParameterCount() != 0 || !method.isDefault()
				|| ConfigKey.forKey(item.keyName()) == null)
			{
				continue;
			}
			assertEquals(item.keyName(), method.invoke(defaults), unwritten.configured(item.keyName()));
		}
	}
}

package shortestpath.settings;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.ArgumentMatchers.same;
import static org.mockito.Mockito.doAnswer;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;

import java.util.Map;
import java.util.Set;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicReference;

import javax.swing.SwingUtilities;

import org.junit.Test;

import net.runelite.client.config.ConfigManager;
import net.runelite.client.events.ConfigChanged;
import shortestpath.TestShortestPathConfig;
import shortestpath.poh.PohNexusPortal;

/**
 * Pins the panel write/listen/keyed-read contract on {@link Settings} —
 * the service surface the reworked panel consumes in place of its own
 * writeConfig/registerSync machinery.
 *
 * <p>The ordering contract mirrors the panel machinery it replaces:
 * {@code write()} is the sole mutation path (it delegates straight to
 * {@code ConfigManager.setConfiguration}), the {@link ConfigChanged} a write
 * produces is classified write-originated so it republishes views and yields
 * a normal {@link ConfigChange} fact but never triggers the external-delivery
 * path for that key, and same-key listeners fire synchronously inside
 * {@code write()}. External (non-write-originated) changes deliver their
 * listeners on the EDT via {@code SwingUtilities.invokeLater}.
 *
 * <p>Keyed reads return the configured value — the panel displays what is
 * stored, so payload overrides must not leak into these reads.
 */
public class SettingsWriteListenTest
{
	private static final String GROUP = "shortestpath";

	private static ConfigChanged event(String key)
	{
		ConfigChanged changed = new ConfigChanged();
		changed.setGroup(GROUP);
		changed.setKey(key);
		return changed;
	}

	/**
	 * Flushes the EDT so every invokeLater-delivered listener has run.
	 */
	private static void flushEdt() throws Exception
	{
		SwingUtilities.invokeAndWait(() ->
		{
		});
	}

	private static Settings service(ConfigManager configManager, TestShortestPathConfig config)
	{
		return Settings.wrap(configManager, config);
	}

	@Test
	public void writeDelegatesToConfigManager()
	{
		ConfigManager configManager = mock(ConfigManager.class);
		Settings settings = service(configManager, new TestShortestPathConfig());

		settings.write("avoidWilderness", false);

		verify(configManager).setConfiguration(GROUP, "avoidWilderness", false);
	}

	@Test
	public void unknownKeyWriteStillReachesConfigManager()
	{
		ConfigManager configManager = mock(ConfigManager.class);
		Settings settings = service(configManager, new TestShortestPathConfig());

		settings.write("notARegistryKey", 7);

		verify(configManager).setConfiguration(GROUP, "notARegistryKey", 7);
	}

	@Test
	public void sameKeyListenerFiresSynchronouslyInsideWrite()
	{
		ConfigManager configManager = mock(ConfigManager.class);
		Settings settings = service(configManager, new TestShortestPathConfig());
		AtomicInteger fired = new AtomicInteger();

		settings.listen("avoidWilderness", fired::incrementAndGet);
		settings.write("avoidWilderness", false);

		assertEquals("same-key listener ran inside write()", 1, fired.get());
	}

	@Test
	public void multipleListenersPerKeyAllFire()
	{
		ConfigManager configManager = mock(ConfigManager.class);
		Settings settings = service(configManager, new TestShortestPathConfig());
		AtomicInteger first = new AtomicInteger();
		AtomicInteger second = new AtomicInteger();

		settings.listen("avoidWilderness", first::incrementAndGet);
		settings.listen("avoidWilderness", second::incrementAndGet);
		settings.write("avoidWilderness", false);

		assertEquals(1, first.get());
		assertEquals(1, second.get());
	}

	@Test
	public void differentKeyListenerDoesNotFireOnWrite() throws Exception
	{
		ConfigManager configManager = mock(ConfigManager.class);
		Settings settings = service(configManager, new TestShortestPathConfig());
		AtomicInteger fired = new AtomicInteger();

		settings.listen("avoidWilderness", fired::incrementAndGet);
		settings.write("drawMap", true);
		flushEdt();

		assertEquals("a write to another key never touches this listener", 0, fired.get());
	}

	/**
	 * The echo a write produces must still classify, but
	 * the listener fires exactly once — from the synchronous in-write
	 * delivery, not again through the external path.
	 */
	@Test
	public void writeOriginatedEchoDoesNotDoubleDeliver()
	{
		ConfigManager configManager = mock(ConfigManager.class);
		TestShortestPathConfig config = new TestShortestPathConfig();
		Settings settings = service(configManager, config);
		AtomicInteger fired = new AtomicInteger();
		AtomicReference<ConfigChange> classified = new AtomicReference<>();

		// any(Object.class) pins the (String, String, Object) overload —
		// bare any() would resolve to the (String, String, String) one.
		doAnswer(invocation ->
		{
			// Reproduce ConfigManager's synchronous dispatch: mutate the
			// configured value, then hand the event back to the service.
			ConfigChanged echo = event(invocation.getArgument(1));
			classified.set(settings.onConfigChanged(echo));
			return null;
		}).when(configManager).setConfiguration(anyString(), anyString(), any(Object.class));

		settings.listen("avoidWilderness", fired::incrementAndGet);
		settings.write("avoidWilderness", false);

		assertEquals("listener fired once, inside write()", 1, fired.get());
		ConfigChange fact = classified.get();
		assertNotNull("the write's echo still ran classification", fact);
		assertTrue("write-originated echo still classifies effects",
			fact.getEffects().contains(Effect.ROUTE_INVALIDATING));
	}

	/**
	 * Marshalling is pinned deterministically by consuming the event on the
	 * EDT itself: an invokeLater delivery cannot run before the current EDT
	 * task finishes, so the listener must still be pending when the event
	 * returns — an inline (unmarshalled) delivery would have already fired.
	 */
	@Test
	public void externalChangeDeliversOnEdtNotInline() throws Exception
	{
		ConfigManager configManager = mock(ConfigManager.class);
		Settings settings = service(configManager, new TestShortestPathConfig());
		AtomicInteger fired = new AtomicInteger();

		settings.listen("avoidWilderness", fired::incrementAndGet);
		SwingUtilities.invokeAndWait(() ->
		{
			settings.onConfigChanged(event("avoidWilderness"));
			assertEquals("external delivery is marshalled, not inline", 0, fired.get());
		});
		flushEdt();
		assertEquals("listener ran on the EDT", 1, fired.get());
	}

	@Test
	public void externalChangeForOtherKeyStillDeliversDuringWrite() throws Exception
	{
		ConfigManager configManager = mock(ConfigManager.class);
		Settings settings = service(configManager, new TestShortestPathConfig());
		AtomicInteger ownKey = new AtomicInteger();
		AtomicInteger otherKey = new AtomicInteger();

		doAnswer(invocation ->
		{
			settings.onConfigChanged(event(invocation.getArgument(1)));
			// An unrelated external event arriving mid-write is not
			// write-originated — its listeners still get EDT delivery.
			settings.onConfigChanged(event("drawMap"));
			return null;
		}).when(configManager).setConfiguration(anyString(), anyString(), any(Object.class));

		settings.listen("avoidWilderness", ownKey::incrementAndGet);
		settings.listen("drawMap", otherKey::incrementAndGet);
		settings.write("avoidWilderness", false);
		flushEdt();

		assertEquals("same-key listener fired once inside write()", 1, ownKey.get());
		assertEquals("external event for another key still delivered", 1, otherKey.get());
	}

