	public static SpiritTreeService forTesting(RefreshCoordinator coordinator)
	{
		return new SpiritTreeService(null, null, coordinator);
	}
}

package shortestpath.spirittree;

import java.util.Set;

import shortestpath.settings.Effect;

/**
 * Same-package fixture: the fact's constructor is package-private so only
 * producer paths can mint facts, and the refresh-coordinator test needs to
 * hand the coordinator facts without widening that visibility.
 */
public final class TestTreeChange
{
	private TestTreeChange()
	{
	}

	public static TreeChange of(String key, Set<Effect> effects)
	{
		return new TreeChange(key, effects);
	}
}

package shortestpath.spirittree;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertThrows;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;
import java.util.HashSet;
import java.util.Set;
import org.junit.Test;
import org.mockito.ArgumentCaptor;

import shortestpath.scheduler.RefreshCoordinator;
import shortestpath.settings.Effect;

/**
 * The spirit-tree change fact is the only hand-off between the service and
 * the plugin shell — pin its shape so a drifted value type breaks loudly
 * here rather than silently at the consumption site.
 */
public class TreeChangeTest
{
	@Test
	public void factCarriesKeyAndEffects()
	{
		TreeChange change = new TreeChange("varbit:Port Sarim", Set.of(Effect.ROUTE_INVALIDATING));

		assertEquals("varbit:Port Sarim", change.getKey());
		assertEquals(Set.of(Effect.ROUTE_INVALIDATING), change.getEffects());
	}

	@Test
	public void effectsAreImmutable()
	{
		Set<Effect> mutable = new HashSet<>();
		mutable.add(Effect.ROUTE_INVALIDATING);
		TreeChange change = new TreeChange("menu", mutable);

		mutable.add(Effect.ELIGIBILITY_STALE);
		assertEquals(Set.of(Effect.ROUTE_INVALIDATING), change.getEffects());
		assertThrows(UnsupportedOperationException.class,
			() -> change.getEffects().add(Effect.DISPLAY_ONLY));
	}

	@Test
	public void producersEmitRouteInvalidatingOnly()
	{
		// A changed tree set invalidates running paths but never item or
		// quest eligibility — the service must only ever declare
		// ROUTE_INVALIDATING. Drive every fact source and assert the emitted
		// effect set carries it and nothing else; the public entry points
		// declare theirs to the coordinator while the internal
		// apply* helpers still hand facts to their caller.
		RefreshCoordinator coordinator = mock(RefreshCoordinator.class);
		SpiritTreeService service = SpiritTreeTestServices.forTesting(coordinator);
		service.loadFromProfile();
		ArgumentCaptor<TreeChange> captor = ArgumentCaptor.forClass(TreeChange.class);
		verify(coordinator).treeSetChanged(captor.capture());
		assertEquals(Set.of(Effect.ROUTE_INVALIDATING), captor.getValue().getEffects());

		TreeChange varbit = service.applyVarbitSample("Port Sarim", 20);
		assertEquals(Set.of(Effect.ROUTE_INVALIDATING), varbit.getEffects());

		TreeChange menu = service.applyMenuSnapshot(Set.of("Etceteria"), Set.of("Etceteria"));
		assertEquals(Set.of(Effect.ROUTE_INVALIDATING), menu.getEffects());
	}

	@Test
	public void unchangedObservationsEmitNullFacts()
	{
		SpiritTreeService service = SpiritTreeTestServices.forTesting();
		service.applyVarbitSample("Port Sarim", 20);

		// An identical re-read is not a change — no fact is emitted.
		assertNull(service.applyVarbitSample("Port Sarim", 20));
		assertNull(service.applyMenuSnapshot(Set.of("Port Sarim"), Set.of("Port Sarim")));
	}
}

package shortestpath.transport;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;

import java.util.HashSet;
import java.util.Map;
import java.util.Set;

import org.junit.Test;

import shortestpath.WorldPointUtil;
import shortestpath.pathfinder.BankVisitState;
import shortestpath.requirement.PlayerStateSource;
import shortestpath.requirement.TransportEligibility;
import shortestpath.requirement.TransportEligibility.BankPickupPlan;
import shortestpath.settings.TeleportationItem;

/**
 * The {@link BalloonRoute} enum against the {@code hot_air_balloons.tsv}
 * destination rows, and the destination-scoped
 * {@code UNLOCK_BALLOON_LOG_BASKET} grant: an eligibility snapshot grants the
 * unlock only to a {@link TransportType#HOT_AIR_BALLOON} transport whose
 * destination is one of the configured basket destinations.
 */
public class BalloonRouteTest
{
	private static Transport balloonTo(BalloonRoute route)
	{
		return new Transport.TransportBuilder()
			.type(TransportType.HOT_AIR_BALLOON)
			.destination(route.getPackedDestination())
			.itemRequirements(route.getLogItemId() + "=1|UNLOCK_BALLOON_LOG_BASKET=1")
			.build();
	}

	private static TransportEligibility eligibilityWith(Map<Integer, Integer> carried,
		Map<Integer, Integer> bankHas, Set<Integer> balloonDests)
	{
		return new TransportEligibility(carried, carried, bankHas, -1, Map.of(),
			false, TeleportationItem.NONE, Integer.MAX_VALUE, Set.of(), false,
			balloonDests);
	}

	private static void assertRoute(BalloonRoute route, String label, int x, int y,
		int logItemId, String logLabel)
	{
		assertEquals(label, route.getLabel());
		assertEquals(WorldPointUtil.packWorldPoint(x, y, 0), route.getPackedDestination());
		assertEquals(logItemId, route.getLogItemId());
		assertEquals(logLabel, route.getLogLabel());
	}

	@Test
	public void enumCoversExactlyTheSixTsvRoutes()
	{
		assertEquals(6, BalloonRoute.values().length);
		assertRoute(BalloonRoute.ENTRANA, "Entrana", 2808, 3354, 1511, "logs");
		assertRoute(BalloonRoute.TAVERLEY, "Taverley", 2941, 3420, 1511, "logs");
		assertRoute(BalloonRoute.CRAFTING_GUILD, "Crafting Guild", 2923, 3302, 1521, "oak logs");
		assertRoute(BalloonRoute.VARROCK, "Varrock", 3299, 3482, 1519, "willow logs");
		assertRoute(BalloonRoute.CASTLE_WARS, "Castle Wars", 2459, 3110, 1515, "yew logs");
		assertRoute(BalloonRoute.GRAND_TREE, "Grand Tree", 2478, 3456, 1513, "magic logs");
	}

	@Test
	public void packedDestinationsAreDistinct()
	{
		Set<Integer> dests = new HashSet<>();
		for (BalloonRoute route : BalloonRoute.values())
		{
			dests.add(route.getPackedDestination());
		}
		assertEquals(BalloonRoute.values().length, dests.size());
	}

	@Test
	public void displayLabelNamesRouteAndLog()
	{
		assertEquals("Grand Tree (magic logs)", BalloonRoute.GRAND_TREE.displayLabel());
		assertEquals("Castle Wars (yew logs)", BalloonRoute.CASTLE_WARS.displayLabel());
	}

	@Test
	public void selectedRouteWaivesItsLogRequirement()
	{
		Transport grandTree = balloonTo(BalloonRoute.GRAND_TREE);
		TransportEligibility eligibility = eligibilityWith(Map.of(), Map.of(),
			Set.of(BalloonRoute.GRAND_TREE.getPackedDestination()));

		assertTrue("stocked Grand Tree basket waives the magic log",
			eligibility.usable(grandTree, BankVisitState.CARRIED));
		assertTrue(eligibility.usable(grandTree, BankVisitState.BANKED));
		assertTrue(eligibility.satisfiedByPlayer(grandTree));
	}

	@Test
	public void unselectedRouteStillDemandsItsLog()
	{
		Transport grandTree = balloonTo(BalloonRoute.GRAND_TREE);
		Set<Integer> varrockOnly = Set.of(BalloonRoute.VARROCK.getPackedDestination());

		assertFalse("Varrock's stocked basket does not waive Grand Tree's magic log",
			eligibilityWith(Map.of(), Map.of(), varrockOnly)
				.usable(grandTree, BankVisitState.CARRIED));
		assertFalse(eligibilityWith(Map.of(), Map.of(), varrockOnly)
			.satisfiedByPlayer(grandTree));

		// The route's log itself still satisfies the row when carried.
		assertTrue(eligibilityWith(Map.of(1513, 1), Map.of(), varrockOnly)
			.usable(grandTree, BankVisitState.CARRIED));
	}

	@Test
	public void bankPickupPlanFollowsTheSameGrant()
	{
		Transport grandTree = balloonTo(BalloonRoute.GRAND_TREE);
		Map<Integer, Integer> bankWithLogs = Map.of(1513, 1);

		BankPickupPlan unlocked = eligibilityWith(Map.of(), bankWithLogs,
			Set.of(BalloonRoute.GRAND_TREE.getPackedDestination()))
			.bankPickupPlan(grandTree);
		assertTrue("a stocked basket needs no bank pickup", unlocked.items.isEmpty());

		BankPickupPlan locked = eligibilityWith(Map.of(), bankWithLogs,
			Set.of(BalloonRoute.VARROCK.getPackedDestination()))
			.bankPickupPlan(grandTree);
		assertEquals("an unstocked basket picks up the route's log",
			Map.of(1513, 1L), locked.items);
	}

	@Test
	public void nonBalloonTransportNeverInheritsTheGrant()
	{
		Transport notABalloon = new Transport.TransportBuilder()
			.type(TransportType.TRANSPORT)
			.destination(BalloonRoute.GRAND_TREE.getPackedDestination())
			.itemRequirements("1513=1|UNLOCK_BALLOON_LOG_BASKET=1")
			.build();
		TransportEligibility eligibility = eligibilityWith(Map.of(), Map.of(),
			Set.of(BalloonRoute.GRAND_TREE.getPackedDestination()));

		assertFalse("the basket unlock is balloon-only",
			eligibility.usable(notABalloon, BankVisitState.CARRIED));
		assertFalse(eligibility.satisfiedByPlayer(notABalloon));
	}

	@Test
	public void collectDefaultsToNoUnlockedRoutes()
	{
		Transport grandTree = balloonTo(BalloonRoute.GRAND_TREE);
		TransportEligibility eligibility = TransportEligibility.collect(
			mock(PlayerStateSource.class), null, TeleportationItem.NONE,
			Integer.MAX_VALUE, false, Set.of(), Set.of());

		assertFalse("an empty basket-destination set captures no unlocked balloon routes",
			eligibility.usable(grandTree, BankVisitState.CARRIED));
	}

	@Test
	public void destinationSetIsCapturedImmutably()
	{
		Transport grandTree = balloonTo(BalloonRoute.GRAND_TREE);
		Set<Integer> dests = new HashSet<>();
		TransportEligibility eligibility = eligibilityWith(Map.of(), Map.of(), dests);

		dests.add(BalloonRoute.GRAND_TREE.getPackedDestination());

		assertFalse("a post-construction write must not reach the snapshot",
			eligibility.usable(grandTree, BankVisitState.CARRIED));
	}
}

package shortestpath.transport;

import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.fail;

import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Quest;
import org.junit.Test;
import shortestpath.requirement.model.ItemRequirement;
import shortestpath.requirement.model.TransportItems;
import shortestpath.requirement.model.VarCheckType;
import shortestpath.requirement.model.VarRequirement;

/**
 * Contract pin for {@link LoadInterner}: every {@code intern*} entry point
 * returns the first-inserted canonical instance for equal inputs, and the two
 * documented null arms pass {@code null} through. The interner is
 * package-private, so this suite lives in its package to reach it.
 */
public class LoadInternerTest
{
	private static VarRequirement varbit(int id)
	{
		return new VarRequirement(VarRequirement.VarType.VARBIT, id, 1, VarCheckType.EQUAL);
	}

	private static TransportItems oneItemGroup()
	{
		return new TransportItems(List.of(
			new ItemRequirement(new int[]{1, 2}, new int[0], new int[0], 1)));
	}

	@Test
	public void internVarRequirementReturnsTheCanonicalInstance()
	{
		LoadInterner interner = new LoadInterner();
		VarRequirement first = varbit(123);

		assertSame(first, interner.intern(first));
		assertSame(first, interner.intern(varbit(123)));
	}

	@Test
	public void internTransportItemsReturnsTheCanonicalInstance()
	{
		LoadInterner interner = new LoadInterner();
		TransportItems first = oneItemGroup();

		assertSame(first, interner.intern(first));
		assertSame(first, interner.intern(oneItemGroup()));
	}

	@Test
	public void internTransportItemsPassesNullThrough()
	{
		assertNull(new LoadInterner().intern((TransportItems) null));
	}

	@Test
	public void internVarSetReturnsTheFirstInsertedSet()
	{
		LoadInterner interner = new LoadInterner();
		Set<VarRequirement> first = new HashSet<>(Set.of(varbit(123), varbit(456)));
		// Set equality is order-insensitive; the interned set is the first-seen instance.
		Set<VarRequirement> equal = new HashSet<>(Set.of(varbit(456), varbit(123)));

		assertSame(first, interner.internVarSet(first));
		assertSame(first, interner.internVarSet(equal));
	}

	@Test
	public void internQuestSetReturnsTheFirstInsertedSet()
	{
		LoadInterner interner = new LoadInterner();
		Set<Quest> first = new HashSet<>(Set.of(Quest.COOKS_ASSISTANT, Quest.DEMON_SLAYER));
		Set<Quest> equal = new HashSet<>(Set.of(Quest.DEMON_SLAYER, Quest.COOKS_ASSISTANT));

		assertSame(first, interner.internQuestSet(first));
		assertSame(first, interner.internQuestSet(equal));
	}

	@Test
	public void internStringReturnsTheCanonicalInstanceAndPassesNullThrough()
	{
		LoadInterner interner = new LoadInterner();
		String first = new String("label");

		assertSame(first, interner.internString(first));
		assertSame(first, interner.internString(new String("label")));
		assertNull(interner.internString(null));
	}

	/**
	 * Production-path dedup pin: {@link ResourceLoader#transports()} runs the
	 * interner over every bundled transport TSV, so distinct transports whose
	 * var-requirement sets compare equal must hold the identical Set instance.
	 * Committed transports.tsv permutes rows with identical requirement text;
	 * a scan finding zero sharing means the data shape changed, not the code.
	 */
	@Test
	public void resourceLoaderInternsSharedVarRequirementSets()
	{
		HashMap<Integer, Set<Transport>> transports = ResourceLoader.transports();
		Map<Set<VarRequirement>, Transport> seen = new HashMap<>();
		for (Set<Transport> bucket : transports.values())
		{
			for (Transport transport : bucket)
			{
				Set<VarRequirement> requirements = transport.getVarRequirements();
				if (requirements.isEmpty())
				{
					continue;
				}
				Transport previous = seen.putIfAbsent(requirements, transport);
				if (previous != null && previous != transport)
				{
					assertSame(
						"transports sharing a requirement set must share the interned Set instance",
						previous.getVarRequirements(), requirements);
					return;
				}
			}
		}
		fail("expected committed transports.tsv to share at least one var-requirement set "
			+ "across distinct transports — the interner exists to dedup them");
	}
}

package shortestpath.transport;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import java.util.regex.Pattern;
import org.junit.Assert;
import org.junit.Test;
import shortestpath.ShortestPathPlugin;
import shortestpath.Util;
import shortestpath.WorldPointUtil;
import shortestpath.transport.parser.ItemRequirementParser;
import shortestpath.transport.parser.QuestParser;
import shortestpath.transport.parser.SkillRequirementParser;
import shortestpath.transport.parser.TransportRecord;
import shortestpath.transport.parser.TsvParser;
import shortestpath.requirement.model.SkillLevels;
import shortestpath.requirement.model.VarRequirement;
import shortestpath.transport.parser.VarRequirementParser;

/**
 * Loader-fidelity lint for the committed transport TSV data.
 *
 * The transport parsers degrade silently in several places: {@link TsvParser}
 * maps only the columns a row actually carries, {@code WorldPointParser} turns
 * any non-three-part coordinate into a permutation marker, and the requirement
 * parsers log-and-continue on bad tokens. A malformed row can therefore pass a
 * "file loaded" check while producing no transport at all. These tests run
 * every committed row through the real {@link TsvParser} ->
 * {@link ResourceLoader#addTransportsFromContents} path and assert that a
 * concretely-anchored row always yields a {@link Transport} in the loader's
 * map, that header cells match the canonical {@link TransportRecord.Fields}
 * names exactly, and that requirement cells are fully consumed by their
 * parsers. Failures are collected per file so one run reports every bad row.
 */
public class ResourceLoaderFidelityTest
{
	/**
	 * Every committed transport resource the plugin loads. Explicitly listed so
	 * a file dropped from the data set is a test failure, not an invisible
	 * reduction in coverage.
	 */
	private static final String[] TRANSPORT_RESOURCES = {
		"/transports/agility_shortcuts.tsv",
		"/transports/boats.tsv",
		"/transports/canoes.tsv",
		"/transports/charter_ships.tsv",
		"/transports/fairy_rings.tsv",
		"/transports/gnome_gliders.tsv",
		"/transports/hot_air_balloons.tsv",
		"/transports/magic_carpets.tsv",
		"/transports/magic_mushtrees.tsv",
		"/transports/minecarts.tsv",
		"/transports/quetzal_whistle.tsv",
		"/transports/quetzals.tsv",
		"/transports/seasonal_transports.tsv",
		"/transports/ships.tsv",
		"/transports/spirit_trees.tsv",
		"/transports/teleportation_boxes.tsv",
		"/transports/teleportation_items.tsv",
		"/transports/teleportation_levers.tsv",
		"/transports/teleportation_minigames.tsv",
		"/transports/teleportation_portals.tsv",
		"/transports/teleportation_portals_poh.tsv",
		"/transports/teleportation_spells.tsv",
		"/transports/teleportation_spells_home.tsv",
		"/transports/transports.tsv",
		"/transports/wilderness_obelisks.tsv",
	};

	private static final Set<String> CANONICAL_FIELDS = new HashSet<>(Arrays.asList(
		TransportRecord.Fields.ORIGIN,
		TransportRecord.Fields.DESTINATION,
		TransportRecord.Fields.SKILLS,
		TransportRecord.Fields.ITEMS,
		TransportRecord.Fields.QUESTS,
		TransportRecord.Fields.DURATION,
		TransportRecord.Fields.DISPLAY_INFO,
		TransportRecord.Fields.CONSUMABLE,
		TransportRecord.Fields.WILDERNESS_LEVEL,
		TransportRecord.Fields.OBJECT_INFO,
		TransportRecord.Fields.VARBITS,
		TransportRecord.Fields.VAR_PLAYERS,
		TransportRecord.Fields.REGION_OVERRIDE));

	/**
	 * A concrete coordinate cell is exactly three space-separated unsigned
	 * integers. Anything else non-empty silently becomes a permutation marker
	 * inside {@code WorldPointParser}.
	 */
	private static final Pattern CONCRETE_POINT = Pattern.compile("^\\d+ \\d+ \\d+$");

	/**
	 * A single raw TSV data row, kept parallel to the record list
	 * {@link TsvParser#parse} produces so assertion failures can name the
	 * file line they came from.
	 */
	private static final class RawFile
	{
		final String[] headers;
		final List<String[]> dataFields = new ArrayList<>();
		final List<Integer> lineNumbers = new ArrayList<>();

		RawFile(String[] headers)
		{
			this.headers = headers;
		}
	}

	private static String readResource(String path) throws IOException
	{
		return new String(
			Util.readAllBytes(Objects.requireNonNull(ShortestPathPlugin.class.getResourceAsStream(path))),
			StandardCharsets.UTF_8);
	}

	/**
	 * Independently scans raw file contents the same way {@link TsvParser}
	 * does: first line is the header (a leading {@code #} or {@code # } is
	 * stripped), later lines starting with {@code #} or blank are skipped.
	 */
	private static RawFile scanRaw(String contents)
	{
		String[] lines = contents.split("\n", -1);
		Assert.assertTrue("Transport file is empty", lines.length > 0);

		String headerLine = stripCarriageReturn(lines[0]);
		if (headerLine.startsWith("# "))
		{
			headerLine = headerLine.substring(2);
		}
		else if (headerLine.startsWith("#"))
		{
			headerLine = headerLine.substring(1);
		}
		RawFile raw = new RawFile(headerLine.split("\t"));

		for (int i = 1; i < lines.length; i++)
		{
			String line = stripCarriageReturn(lines[i]);
			if (line.startsWith("#") || line.isBlank())
			{
				continue;
			}
			raw.dataFields.add(line.split("\t", -1));
			raw.lineNumbers.add(i + 1);
		}
		return raw;
	}

	private static String stripCarriageReturn(String line)
	{
		return line.endsWith("\r") ? line.substring(0, line.length() - 1) : line;
	}

	private static int columnIndex(String[] headers, String name)
	{
		for (int i = 0; i < headers.length; i++)
		{
			if (name.equals(headers[i]))
			{
				return i;
			}
		}
		return -1;
	}

	private static String cell(String[] fields, int index)
	{
		if (index < 0 || index >= fields.length)
		{
			return "";
		}
		return fields[index];
	}

	private static boolean isConcrete(String value)
	{
		return CONCRETE_POINT.matcher(value).matches();
	}

	private static int packConcrete(String value)
	{
		String[] parts = value.split(" ");
		return WorldPointUtil.packWorldPoint(
			Integer.parseInt(parts[0]),
			Integer.parseInt(parts[1]),
			Integer.parseInt(parts[2]));
	}

	private static TransportType typeFor(String path)
	{
		for (TransportType type : TransportType.values())
		{
			if (path.equals(type.getResourcePath()))
			{
				return type;
			}
		}
		return null;
	}

	private static boolean mapContainsDestination(Map<Integer, Set<Transport>> transports, int packedDestination)
	{
		for (Set<Transport> set : transports.values())
		{
			for (Transport transport : set)
			{
				if (transport.getDestination() == packedDestination)
				{
					return true;
				}
			}
		}
		return false;
	}

	private static void report(List<String> failures, String checkName)
	{
		if (!failures.isEmpty())
		{
			StringBuilder message = new StringBuilder();
			message.append(String.format("%s found %d problem(s):\n", checkName, failures.size()));
			for (String failure : failures)
			{
				message.append("  ").append(failure).append('\n');
			}
			Assert.fail(message.toString());
		}
	}

	/**
	 * Row-count and parse fidelity: every row whose anchor cell is a concrete
	 * {@code x y z} triple must produce a {@link Transport} through the real
	 * {@link TsvParser} + {@link ResourceLoader#addTransportsFromContents}
	 * path. A row that is well-formed yet yields no map entry is a silent
	 * drop, which is exactly what this test exists to catch.
	 *
	 * Rows whose concrete origin equals their concrete destination are
	 * exempt: {@link ResourceLoader#addTransportsFromContents} documents
	 * that identical A->A transports are intentionally skipped.
	 */
	@Test
	public void testConcreteRowsProduceTransports() throws IOException
	{
		List<String> failures = new ArrayList<>();

		for (String path : TRANSPORT_RESOURCES)
		{
			String contents = readResource(path);
			RawFile raw = scanRaw(contents);

			List<TransportRecord> records = new TsvParser().parse(contents);
			if (records.size() != raw.dataFields.size())
			{
				failures.add(String.format(
					"%s: TsvParser produced %d records from %d data rows",
					path, records.size(), raw.dataFields.size()));
			}

			TransportType type = typeFor(path);
			if (type == null)
			{
				failures.add(path + ": no TransportType maps this resource path");
				continue;
			}

			Map<Integer, Set<Transport>> transports = new HashMap<>();
			ResourceLoader.addTransportsFromContents(transports, contents, type,
				type.hasRadiusThreshold() ? type.getRadiusThreshold() : 0);

			int originIdx = columnIndex(raw.headers, TransportRecord.Fields.ORIGIN);
			int destinationIdx = columnIndex(raw.headers, TransportRecord.Fields.DESTINATION);

			for (int i = 0; i < raw.dataFields.size(); i++)
			{
				String[] fields = raw.dataFields.get(i);
				int lineNo = raw.lineNumbers.get(i);
				String originCell = cell(fields, originIdx);
				String destinationCell = cell(fields, destinationIdx);
				boolean originConcrete = isConcrete(originCell);
				boolean destinationConcrete = isConcrete(destinationCell);

				if (originConcrete)
				{
					int packedOrigin = packConcrete(originCell);

					if (destinationConcrete && packConcrete(destinationCell) == packedOrigin)
					{
						// Identical origin->destination rows are skipped by the
						// loader on purpose; not a silent drop.
						continue;
					}

					Set<Transport> produced = transports.get(packedOrigin);
					if (produced == null || produced.isEmpty())
					{
						failures.add(String.format(
							"%s:%d: concrete origin '%s' produced no transports",
							path, lineNo, originCell));
						continue;
					}

					if (destinationConcrete)
					{
						int packedDestination = packConcrete(destinationCell);
						boolean found = false;
						for (Transport transport : produced)
						{
							if (transport.getDestination() == packedDestination)
							{
								found = true;
								break;
							}
						}
						if (!found)
						{
							failures.add(String.format(
								"%s:%d: no transport from '%s' to concrete destination '%s'",
								path, lineNo, originCell, destinationCell));
						}
					}
				}
				else if (destinationConcrete)
				{
					// Destination-anchored rows (files without an Origin
					// column load under the undefined-origin key) and
					// permutation-destination rows (blank Origin cell) must
					// still surface as a produced transport destination.
					int packedDestination = packConcrete(destinationCell);
					if (!mapContainsDestination(transports, packedDestination))
					{
						failures.add(String.format(
							"%s:%d: concrete destination '%s' produced no transport",
							path, lineNo, destinationCell));
					}
				}
			}
		}

		report(failures, "testConcreteRowsProduceTransports");
	}

	/**
	 * Header coverage: every header cell of every file must be one of the
	 * canonical {@link TransportRecord.Fields} names. The parser maps columns
	 * by exact header text, so a misspelled or padded header silently drops
	 * the entire column.
	 */
	@Test
	public void testHeadersAreCanonical() throws IOException
	{
		List<String> failures = new ArrayList<>();

		for (String path : TRANSPORT_RESOURCES)
		{
			RawFile raw = scanRaw(readResource(path));
			for (String header : raw.headers)
			{
				if (!CANONICAL_FIELDS.contains(header))
				{
					failures.add(String.format(
						"%s: header cell '%s' is not a canonical TransportRecord.Fields column",
						path, header));
				}
			}
		}

		report(failures, "testHeadersAreCanonical");
	}

	/**
	 * Coordinate shape: every non-empty Origin/Destination cell must be a
	 * three-part numeric {@code x y z} triple. Blank cells are permutation
	 * markers and are skipped; any other content silently degrades to a
	 * permutation inside {@code WorldPointParser}.
	 */
	@Test
	public void testConcreteCoordinatesAreThreePartNumeric() throws IOException
	{
		List<String> failures = new ArrayList<>();

		for (String path : TRANSPORT_RESOURCES)
		{
			RawFile raw = scanRaw(readResource(path));
			int originIdx = columnIndex(raw.headers, TransportRecord.Fields.ORIGIN);
			int destinationIdx = columnIndex(raw.headers, TransportRecord.Fields.DESTINATION);

			for (int i = 0; i < raw.dataFields.size(); i++)
			{
				String[] fields = raw.dataFields.get(i);
				int lineNo = raw.lineNumbers.get(i);
				String originCell = cell(fields, originIdx);
				String destinationCell = cell(fields, destinationIdx);

				if (!originCell.isEmpty() && !isConcrete(originCell))
				{
					failures.add(String.format(
						"%s:%d: Origin cell '%s' is not a three-part numeric coordinate",
						path, lineNo, originCell));
				}
				if (!destinationCell.isEmpty() && !isConcrete(destinationCell))
				{
					failures.add(String.format(
						"%s:%d: Destination cell '%s' is not a three-part numeric coordinate",
						path, lineNo, destinationCell));
				}
			}
		}

		report(failures, "testConcreteCoordinatesAreThreePartNumeric");
	}

	/**
	 * Field-parser fidelity: every Varbits/VarPlayers clause, Items
	 * expression, Skills token, and Quests token in every committed row must
	 * be fully consumed by the real field parsers. These parsers
	 * log-and-continue on bad tokens, so a dropped clause is otherwise
	 * invisible: the requirement silently weakens.
	 */
	@Test
	public void testRequirementFieldsFullyParse() throws IOException
	{
		List<String> failures = new ArrayList<>();

		for (String path : TRANSPORT_RESOURCES)
		{
			String contents = readResource(path);
			RawFile raw = scanRaw(contents);
			List<TransportRecord> records = new TsvParser().parse(contents);

			for (int i = 0; i < records.size() && i < raw.lineNumbers.size(); i++)
			{
				TransportRecord record = records.get(i);
				int lineNo = raw.lineNumbers.get(i);

				if (record.has(TransportRecord.Fields.VARBITS))
				{
					for (String clause : record.getVarbits().split(";"))
					{
						if (clause.isEmpty())
						{
							continue;
						}
						Set<VarRequirement> parsed = VarRequirementParser.forVarbits().parse(clause);
						if (parsed.size() != 1)
						{
							failures.add(String.format(
								"%s:%d: Varbits clause '%s' did not parse to exactly one requirement",
								path, lineNo, clause));
						}
					}
				}

				if (record.has(TransportRecord.Fields.VAR_PLAYERS))
				{
					for (String clause : record.getVarPlayers().split(";"))
					{
						if (clause.isEmpty())
						{
							continue;
						}
						Set<VarRequirement> parsed = VarRequirementParser.forVarPlayers().parse(clause);
						if (parsed.size() != 1)
						{
							failures.add(String.format(
								"%s:%d: VarPlayers clause '%s' did not parse to exactly one requirement",
								path, lineNo, clause));
						}
					}
				}

				if (record.has(TransportRecord.Fields.ITEMS)
					&& new ItemRequirementParser().parse(record.getItems()) == null)
				{
					failures.add(String.format(
						"%s:%d: Items cell '%s' failed to parse",
						path, lineNo, record.getItems()));
				}

				if (record.has(TransportRecord.Fields.SKILLS))
				{
					for (String token : record.getSkills().split(";"))
					{
						if (token.isEmpty())
						{
							continue;
						}
						SkillLevels levels = new SkillRequirementParser().parse(token);
						int set = 0;
						for (int level : levels.toArray())
						{
							if (level != 0)
							{
								set++;
							}
						}
						if (set != 1)
						{
							failures.add(String.format(
								"%s:%d: Skills token '%s' did not set exactly one requirement slot",
								path, lineNo, token));
						}
					}
				}

				if (record.has(TransportRecord.Fields.QUESTS))
				{
					for (String token : record.getQuests().split(";"))
					{
						if (token.isEmpty())
						{
							continue;
						}
						if (new QuestParser().parse(token).size() != 1)
						{
							failures.add(String.format(
								"%s:%d: Quests token '%s' matched no Quest enum entry",
								path, lineNo, token));
						}
					}
				}
			}
		}

		report(failures, "testRequirementFieldsFullyParse");
	}
}

package shortestpath.transport;

import java.io.IOException;
import java.io.InputStream;
import java.util.HashMap;
import java.util.Map;
import java.util.Set;
import java.util.stream.Collectors;
import java.util.zip.ZipEntry;
import java.util.zip.ZipInputStream;
import net.runelite.api.Quest;
import net.runelite.api.Skill;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;
import shortestpath.LogCapture;
import shortestpath.WorldPointUtil;
import shortestpath.leagues.LeagueRegion;
import shortestpath.requirement.model.DestinationRequirements;
import shortestpath.requirement.model.SkillLevels;
import shortestpath.requirement.model.VarRequirement;
import shortestpath.requirement.model.TransportItems;
import shortestpath.transport.parser.ItemRequirementParser;

/**
 * Tests for the transports content seam — coverage moved to the loader's
 * typed surface ({@link ResourceLoader#addTransportsFromContents} and
 * {@link ResourceLoader#transports()}).
 *
 * <p>The suite also pins each resource's distinct failure posture and the
 * committed resources' contents: destinations and bank requirements keep
 * their own row idioms (duplicate-header accumulation, drop-arity and
 * keep-arity splits respectively), league regions degrade warn-and-skip,
 * and the collision map hands out a caller-owned stream. The
 * teleport-restriction families reader is panel-side on this stack — its
 * coverage lands with the panel rebase, not here.
 */
public class ResourceLoaderTest
{
	@Rule
	public final LogCapture log = new LogCapture("shortestpath.transport");


	private Map<Integer, Set<Transport>> transports;

	@Before
	public void setUp()
	{
		transports = new HashMap<>();
	}

	// Helper method to get the first transport from a set
	private Transport getFirstTransport(Set<Transport> transportSet)
	{
		Assert.assertFalse("Transport set should not be empty", transportSet.isEmpty());
		return transportSet.iterator().next();
	}

	@Test
	public void testBasicTransportParsing()
	{
		String contents = "# Origin\tDestination\tDuration\n" +
			"3200 3200 0\t3300 3300 0\t5\n";

		ResourceLoader.addTransportsFromContents(transports, contents, TransportType.TRANSPORT, 0);

		int originPacked = WorldPointUtil.packWorldPoint(3200, 3200, 0);
		int destinationPacked = WorldPointUtil.packWorldPoint(3300, 3300, 0);

		Assert.assertTrue("Should contain origin", transports.containsKey(originPacked));
		Set<Transport> transportSet = transports.get(originPacked);
		Assert.assertEquals("Should have exactly one transport", 1, transportSet.size());

		Transport transport = getFirstTransport(transportSet);
		Assert.assertEquals("Origin should match", originPacked, transport.getOrigin());
		Assert.assertEquals("Destination should match", destinationPacked, transport.getDestination());
		Assert.assertEquals("Duration should match", 5, transport.getDuration());
		Assert.assertEquals("Type should match", TransportType.TRANSPORT, transport.getType());
	}

	@Test
	public void testEmptyAndCommentLines()
	{
		String contents = "# Origin\tDestination\tDuration\n" +
			"# This is a comment\n" +
			"\n" +
			"3200 3200 0\t3300 3300 0\t5\n" +
			"\n" +
			"# Another comment\n" +
			"3400 3400 0\t3500 3500 0\t10\n";

		ResourceLoader.addTransportsFromContents(transports, contents, TransportType.TRANSPORT, 0);

		Assert.assertEquals("Should have exactly 2 origins", 2, transports.size());

		int origin1 = WorldPointUtil.packWorldPoint(3200, 3200, 0);
		int origin2 = WorldPointUtil.packWorldPoint(3400, 3400, 0);

		Assert.assertTrue("Should contain first origin", transports.containsKey(origin1));
		Assert.assertTrue("Should contain second origin", transports.containsKey(origin2));

		// Check exact contents for each origin
		int dest1 = WorldPointUtil.packWorldPoint(3300, 3300, 0);
		int dest2 = WorldPointUtil.packWorldPoint(3500, 3500, 0);
		Transport t1 = getFirstTransport(transports.get(origin1));
		Transport t2 = getFirstTransport(transports.get(origin2));
		Assert.assertEquals("Origin1 destination should match", dest1, t1.getDestination());
		Assert.assertEquals("Origin1 duration should match", 5, t1.getDuration());
		Assert.assertEquals("Origin2 destination should match", dest2, t2.getDestination());
		Assert.assertEquals("Origin2 duration should match", 10, t2.getDuration());
