package shortestpath.transport;

import java.util.Arrays;
import java.util.Map;
import java.util.Set;
import net.runelite.api.ItemID;
import org.junit.Assert;
import org.junit.Test;
import shortestpath.WorldPointUtil;
import shortestpath.pathfinder.CollisionMap;
import shortestpath.pathfinder.SplitFlagMap;

public class ZanarisMarketAccessTest
{
	@Test
	public void marketDoorsRequireADiamondToEnterAndAllowFreeExit()
	{
		CollisionMap map = new CollisionMap(SplitFlagMap.fromResources());
		Map<Integer, Set<Transport>> transports = ResourceLoader.transports();
		int[][] crossings = {
			{2469, 4438, 2470, 4438}, {2469, 4437, 2470, 4437},
			{2466, 4434, 2466, 4433}, {2465, 4434, 2465, 4433}
		};
		for (int[] crossing : crossings)
		{
			int outside = WorldPointUtil.packWorldPoint(crossing[0], crossing[1], 0);
			int inside = WorldPointUtil.packWorldPoint(crossing[2], crossing[3], 0);
			Assert.assertFalse(map.isBlocked(crossing[0], crossing[1], 0));
			Assert.assertFalse(map.isBlocked(crossing[2], crossing[3], 0));
			Assert.assertFalse(Arrays.stream(map.ordinaryWalkingNeighbors(outside)).anyMatch(p -> p == inside));
			Assert.assertFalse(Arrays.stream(map.ordinaryWalkingNeighbors(inside)).anyMatch(p -> p == outside));
			Transport entry = edge(transports, outside, inside);
			Assert.assertNotNull(entry.getItemRequirements());
			Assert.assertFalse(entry.getItemRequirements().isSatisfiedBy(Map.of(), Set.of(), 0));
			Assert.assertFalse(entry.getItemRequirements().isSatisfiedBy(Map.of(ItemID.UNCUT_DIAMOND, 1), Set.of(), 0));
			Assert.assertTrue(entry.getItemRequirements().isSatisfiedBy(Map.of(ItemID.DIAMOND, 1), Set.of(), 0));
			Transport exit = edge(transports, inside, outside);
			Assert.assertTrue(exit.getItemRequirements() == null
				|| exit.getItemRequirements().isSatisfiedBy(Map.of(), Set.of(), 0));
		}
	}

	private static Transport edge(Map<Integer, Set<Transport>> transports, int origin, int destination)
	{
		return transports.get(origin).stream()
			.filter(t -> t.getDestination() == destination && t.getObjectInfo().startsWith("Open Magic door "))
			.findFirst().orElseThrow(AssertionError::new);
	}
}

package shortestpath.widgets;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertThrows;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import java.util.Arrays;
import java.util.List;

import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

import net.runelite.api.Client;
import net.runelite.api.widgets.Widget;

/**
 * Pins the widget-access contract the scrape consumers build on: the
 * ordered-children and self-first text shapes (positions are load-bearing
 * — a first-row sentinel and a keyed row both read index 0), the
 * presence predicate, the loud off-client-thread throw on a live client,
 * and the detached-instance collapse that never throws.
 */
@RunWith(MockitoJUnitRunner.Silent.class)
public class GameWidgetsTest
{
	private static final int GROUP = 1234;
	private static final int CHILD = 9;
	private static final int PACKED = 5678;

	@Mock
	Client client;

	private GameWidgets widgets;

	@Before
	public void setUp()
	{
		when(client.getClientThread()).thenReturn(Thread.currentThread());
		widgets = new GameWidgets(client);
	}

	private static Widget child(String text)
	{
		Widget child = mock(Widget.class);
		when(child.getText()).thenReturn(text);
		return child;
	}

	private static Widget container(String selfText, Widget... children)
	{
		Widget container = mock(Widget.class);
		when(container.getText()).thenReturn(selfText);
		when(container.getDynamicChildren()).thenReturn(children);
		return container;
	}

	@Test
	public void detachedInstanceCollapsesToEmptyReads()
	{
		GameWidgets detached = WidgetTestServices.gameWidgets();

		assertEquals(List.of(), detached.childTexts(GROUP, CHILD));
		assertEquals(List.of(), detached.childTexts(PACKED));
		assertEquals(List.of(), detached.selfAndChildTexts(PACKED));
		assertFalse(detached.isWidgetOpen(PACKED));
	}

	@Test
	public void missingWidgetYieldsEmptyReads()
	{
		when(client.getWidget(GROUP, CHILD)).thenReturn(null);
		when(client.getWidget(PACKED)).thenReturn(null);

		assertEquals(List.of(), widgets.childTexts(GROUP, CHILD));
		assertEquals(List.of(), widgets.childTexts(PACKED));
		assertEquals(List.of(), widgets.selfAndChildTexts(PACKED));
		assertFalse(widgets.isWidgetOpen(PACKED));
	}

	@Test
	public void nullDynamicChildrenYieldsEmptyList()
	{
		Widget container = mock(Widget.class);
		when(container.getDynamicChildren()).thenReturn(null);
		when(client.getWidget(GROUP, CHILD)).thenReturn(container);

		assertEquals(List.of(), widgets.childTexts(GROUP, CHILD));
	}

	@Test
	public void childTextsReturnOrderedChildTexts()
	{
		Widget container = container(null, child("row zero"), child("row one"), child("row two"));
		when(client.getWidget(GROUP, CHILD)).thenReturn(container);
		when(client.getWidget(PACKED)).thenReturn(container);

		// The order is the menu order — a sort or dedup would corrupt the
		// first-row sentinel the consumers identify menus by.
		List<String> expected = List.of("row zero", "row one", "row two");
		assertEquals(expected, widgets.childTexts(GROUP, CHILD));
		assertEquals(expected, widgets.childTexts(PACKED));
	}

	@Test
	public void childTextsKeepPositionsOfNullChildrenAndNullTexts()
	{
		Widget nullText = child(null);
		Widget container = container(null, child("first"), null, nullText);
		when(client.getWidget(GROUP, CHILD)).thenReturn(container);

		// A null child slot or a null text keeps its index as a null
		// element — shifting positions would move the first-row sentinel.
		assertEquals(Arrays.asList("first", null, null), widgets.childTexts(GROUP, CHILD));
	}

	@Test
	public void selfAndChildTextsPutsContainerTextFirst()
	{
		Widget container = container("container row", child("keyed one"), child("keyed two"));
		when(client.getWidget(PACKED)).thenReturn(container);

		List<String> texts = widgets.selfAndChildTexts(PACKED);

		// Index 0 is the container's own text — the keyed-row contract the
		// nexus parse is built on.
		assertEquals(List.of("container row", "keyed one", "keyed two"), texts);
		assertEquals("container row", texts.get(0));
	}

	@Test
	public void selfAndChildTextsReadsSelfTextWithoutChildren()
	{
		Widget container = mock(Widget.class);
		when(container.getText()).thenReturn("only the container");
		when(container.getDynamicChildren()).thenReturn(null);
		when(client.getWidget(PACKED)).thenReturn(container);

		assertEquals(List.of("only the container"), widgets.selfAndChildTexts(PACKED));
	}

	@Test
	public void isWidgetOpenReflectsWidgetPresence()
	{
		Widget container = mock(Widget.class);
		when(client.getWidget(PACKED)).thenReturn(container);

		assertTrue(widgets.isWidgetOpen(PACKED));

		when(client.getWidget(PACKED)).thenReturn(null);

		assertFalse(widgets.isWidgetOpen(PACKED));
	}

	@Test
	public void offClientThreadThrowsImmediately()
	{
		// Any thread other than the current one stands in for the client
		// thread — every primitive must fail loudly, not race the client.
		when(client.getClientThread()).thenReturn(new Thread());

		assertThrows(IllegalStateException.class, () -> widgets.childTexts(GROUP, CHILD));
		assertThrows(IllegalStateException.class, () -> widgets.childTexts(PACKED));
		assertThrows(IllegalStateException.class, () -> widgets.selfAndChildTexts(PACKED));
		assertThrows(IllegalStateException.class, () -> widgets.isWidgetOpen(PACKED));
	}
}

package shortestpath.widgets;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNotSame;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

import java.awt.Rectangle;
import java.awt.Shape;
import java.awt.geom.Ellipse2D;
import java.awt.image.BufferedImage;

import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.api.WorldView;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.SpriteID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.worldmap.WorldMap;
import net.runelite.client.game.SpriteManager;

import shortestpath.WorldPointUtil;

/**
 * Pins the load-bearing idioms the geometry move carries: the self-assigning
 * {@code minimapRectangle} bounds check that clears all four minimap caches
 * on any bounds change, the mask-sprite fallback chain, the
 * {@code menuOpened(Point)} single-owner write seam feeding
 * {@code getSelectedWorldPoint}, and the detached-instance sentinels — a
 * geometry built without a client answers null/{@code Integer.MIN_VALUE}/
 * {@link WorldPointUtil#UNDEFINED} and never throws.
 */
@RunWith(MockitoJUnitRunner.Silent.class)
public class WidgetGeometryTest
{
	@Mock
	Client client;

	@Mock
	SpriteManager spriteManager;

	private WidgetGeometry geometry;

	@Before
	public void setUp()
	{
		geometry = new WidgetGeometry(client, spriteManager);
	}

	/**
	 * A mask with an opaque centre on a transparent field — the edge
	 * tracer walks the boundary between the (0,0) outside colour and the
	 * filled pixels, producing a non-empty polygon.
	 */
	private static BufferedImage maskImage()
	{
		BufferedImage image = new BufferedImage(8, 8, BufferedImage.TYPE_INT_ARGB);
		for (int y = 2; y < 6; y++)
		{
			for (int x = 2; x < 6; x++)
			{
				image.setRGB(x, y, 0xFFFFFFFF);
			}
		}
		return image;
	}

	private Widget stubFixedMinimap(Rectangle bounds)
	{
		Widget minimap = mock(Widget.class);
		when(client.isResized()).thenReturn(false);
		when(client.getWidget(InterfaceID.Toplevel.MINIMAP)).thenReturn(minimap);
		when(minimap.isHidden()).thenReturn(false);
		when(minimap.getBounds()).thenReturn(bounds);
		return minimap;
	}

	private Widget stubResizeableMinimap(Rectangle bounds)
	{
		Widget minimap = mock(Widget.class);
		when(client.isResized()).thenReturn(true);
		when(client.getVarbitValue(VarbitID.RESIZABLE_STONE_ARRANGEMENT)).thenReturn(0);
		when(client.getWidget(InterfaceID.ToplevelOsrsStretch.MINIMAP)).thenReturn(minimap);
		when(minimap.isHidden()).thenReturn(false);
		when(minimap.getBounds()).thenReturn(bounds);
		return minimap;
	}

	@Test
	public void detachedInstanceCollapsesToSentinels()
	{
		WidgetGeometry detached = WidgetTestServices.geometry();

		assertNull(detached.getMinimapClipArea());
		assertEquals(Integer.MIN_VALUE, detached.mapWorldPointToGraphicsPointX(0));
		assertEquals(Integer.MIN_VALUE, detached.mapWorldPointToGraphicsPointY(0));
		assertEquals(WorldPointUtil.UNDEFINED, detached.calculateMapPoint(10, 20));
		assertEquals(WorldPointUtil.UNDEFINED, detached.getSelectedWorldPoint());
		assertNull(detached.mapWorldPointToGraphicsPoint(0));
		assertFalse(detached.worldMapOpen());

		// The write seam records without a client and still never throws.
		detached.menuOpened(new Point(4, 4));
		assertEquals(WorldPointUtil.UNDEFINED, detached.getSelectedWorldPoint());
	}

	@Test
	public void clientOnlyInstanceAnswersMapReads()
	{
		// The client-only seam covers the world-map conversions — the
		// sprite-free surface — without wiring a sprite manager.
		WidgetGeometry clientOnly = new WidgetGeometry(client);
		Widget map = mock(Widget.class);
		WorldMap worldMap = mock(WorldMap.class);
		when(client.getWorldMap()).thenReturn(worldMap);
		when(worldMap.getWorldMapZoom()).thenReturn(8f);
		when(worldMap.getWorldMapPosition()).thenReturn(new Point(3200, 3200));
		when(client.getWidget(InterfaceID.Worldmap.MAP_CONTAINER)).thenReturn(map);
		when(map.getBounds()).thenReturn(new Rectangle(0, 0, 512, 352));

		int packed = WorldPointUtil.packWorldPoint(3200, 3200, 0);
		assertEquals(260, clientOnly.mapWorldPointToGraphicsPointX(packed));
		assertEquals(172, clientOnly.mapWorldPointToGraphicsPointY(packed));
		assertEquals(new Point(260, 172), clientOnly.mapWorldPointToGraphicsPoint(packed));
		assertTrue(clientOnly.worldMapOpen());
	}

	@Test
	public void closedWorldMapCollapsesThePointAndTheGuard()
	{
		// MAP_CONTAINER absent: the X/Y pair both answer MIN_VALUE, the
		// composed read must surface null rather than a sentinel pair, and
		// the guard reports closed.
		WidgetGeometry clientOnly = new WidgetGeometry(client);
		WorldMap worldMap = mock(WorldMap.class);
		when(client.getWorldMap()).thenReturn(worldMap);
		when(worldMap.getWorldMapZoom()).thenReturn(8f);
		when(worldMap.getWorldMapPosition()).thenReturn(new Point(3200, 3200));
		when(client.getWidget(InterfaceID.Worldmap.MAP_CONTAINER)).thenReturn(null);

		int packed = WorldPointUtil.packWorldPoint(3200, 3200, 0);
		assertNull(clientOnly.mapWorldPointToGraphicsPoint(packed));
		assertFalse(clientOnly.worldMapOpen());
	}

	@Test
	public void minimapClipCachesWhileBoundsHold()
	{
		stubFixedMinimap(new Rectangle(12, 34, 200, 150));
		when(spriteManager.getSprite(SpriteID.FIXED_MAP_MASK, 0)).thenReturn(maskImage());

		Shape first = geometry.getMinimapClipArea();

		assertNotNull(first);
		assertSame(first, geometry.getMinimapClipArea());
		verify(spriteManager, times(1)).getSprite(SpriteID.FIXED_MAP_MASK, 0);
	}

	@Test
	public void boundsChangeClearsAllFourMinimapCaches()
	{
		Widget fixedMinimap = stubFixedMinimap(new Rectangle(0, 0, 100, 100));
		Widget resizeableMinimap = stubResizeableMinimap(new Rectangle(0, 0, 300, 200));
		when(spriteManager.getSprite(SpriteID.FIXED_MAP_MASK, 0)).thenReturn(maskImage());
		when(spriteManager.getSprite(SpriteID.RESIZE_MAP_MASK, 0)).thenReturn(maskImage());

		// Fixed mode caches the clip and the mask sprite.
		when(client.isResized()).thenReturn(false);
		Shape fixedClip = geometry.getMinimapClipArea();
		assertSame(fixedClip, geometry.getMinimapClipArea());

		// Switching to the resizeable widget moves the bounds — every
		// cache clears and the resizeable pair repopulates.
		when(client.isResized()).thenReturn(true);
		Shape resizeableClip = geometry.getMinimapClipArea();
		assertNotSame(fixedClip, resizeableClip);
		assertSame(resizeableClip, geometry.getMinimapClipArea());

		// Back to fixed: the resizeable bounds are still recorded, so the
		// fixed widget's bounds invalidate again — fixed clip and sprite
		// both recompute rather than resurrecting the stale entries.
		when(client.isResized()).thenReturn(false);
		Shape fixedClipAgain = geometry.getMinimapClipArea();
		assertNotSame(fixedClip, fixedClipAgain);
		assertSame(fixedClipAgain, geometry.getMinimapClipArea());

		verify(spriteManager, times(2)).getSprite(SpriteID.FIXED_MAP_MASK, 0);
		verify(spriteManager, times(1)).getSprite(SpriteID.RESIZE_MAP_MASK, 0);
		verify(fixedMinimap, times(4)).getBounds();
		verify(resizeableMinimap, times(2)).getBounds();
	}

	@Test
	public void hiddenMinimapYieldsNullClip()
	{
		Widget minimap = stubFixedMinimap(new Rectangle(0, 0, 100, 100));
		when(minimap.isHidden()).thenReturn(true);

		assertNull(geometry.getMinimapClipArea());
	}

	@Test
	public void masklessArmFallsBackToEllipseUncached()
	{
		stubFixedMinimap(new Rectangle(10, 20, 100, 80));
		// Sprite not loaded yet — getSprite answers null and the clip
		// degrades to the elliptical approximation each call.
		when(spriteManager.getSprite(SpriteID.FIXED_MAP_MASK, 0)).thenReturn(null);

		Shape clip = geometry.getMinimapClipArea();

		assertTrue(clip instanceof Ellipse2D.Double);
		assertNotSame(clip, geometry.getMinimapClipArea());
	}

	@Test
	public void menuOpenedPointDrivesSelectionWhileMenuOpen()
	{
		Widget map = mock(Widget.class);
		WorldMap worldMap = mock(WorldMap.class);
		when(client.getWidget(InterfaceID.Worldmap.MAP_CONTAINER)).thenReturn(map);
		when(client.getWorldMap()).thenReturn(worldMap);
		when(worldMap.getWorldMapZoom()).thenReturn(8f);
		when(worldMap.getWorldMapPosition()).thenReturn(new Point(3200, 3200));
		when(map.getBounds()).thenReturn(new Rectangle(0, 0, 512, 352));
		// The live mouse sits somewhere else — selection must prefer the
		// recorded menu point while a menu is open.
		when(client.getMouseCanvasPosition()).thenReturn(new Point(276, 188));
		when(client.isMenuOpen()).thenReturn(true);

		geometry.menuOpened(new Point(268, 180));

		assertEquals(WorldPointUtil.packWorldPoint(3201, 3199, 0), geometry.getSelectedWorldPoint());
	}

	@Test
	public void closedMenuFallsBackToMousePosition()
	{
		Widget map = mock(Widget.class);
		WorldMap worldMap = mock(WorldMap.class);
		when(client.getWidget(InterfaceID.Worldmap.MAP_CONTAINER)).thenReturn(map);
		when(client.getWorldMap()).thenReturn(worldMap);
		when(worldMap.getWorldMapZoom()).thenReturn(8f);
		when(worldMap.getWorldMapPosition()).thenReturn(new Point(3200, 3200));
		when(map.getBounds()).thenReturn(new Rectangle(0, 0, 512, 352));
		when(client.getMouseCanvasPosition()).thenReturn(new Point(276, 188));
		when(client.isMenuOpen()).thenReturn(false);

		geometry.menuOpened(new Point(268, 180));

		assertEquals(WorldPointUtil.packWorldPoint(3202, 3198, 0), geometry.getSelectedWorldPoint());
	}

	@Test
	public void noWorldMapAndNoSceneTileYieldsUndefined()
	{
		when(client.getWidget(InterfaceID.Worldmap.MAP_CONTAINER)).thenReturn(null);
		WorldView top = mock(WorldView.class);
		when(client.getTopLevelWorldView()).thenReturn(top);
		when(top.getSelectedSceneTile()).thenReturn(null);

		assertEquals(WorldPointUtil.UNDEFINED, geometry.getSelectedWorldPoint());
	}
}

package shortestpath.widgets;

import net.runelite.api.Client;
import net.runelite.client.game.SpriteManager;

/**
 * Builds {@link GameWidgets} and {@link WidgetGeometry} instances detached
 * from Guice for tests and harnesses. The production instances are the
 * injected singletons.
 */
public final class WidgetTestServices
{
	private WidgetTestServices()
	{
	}

	/**
	 * A detached {@link GameWidgets}. Without a client it collapses to the
	 * empty arms (an empty list, {@code false}) and never throws.
	 */
	public static GameWidgets gameWidgets()
	{
		return new GameWidgets(null);
	}

	/**
	 * A detached {@link WidgetGeometry}. Without a client it collapses to the
	 * no-op arms (null clip areas and the {@code Integer.MIN_VALUE} and
	 * {@link shortestpath.WorldPointUtil#UNDEFINED} sentinels) and never throws.
	 */
	public static WidgetGeometry geometry()
	{
		return new WidgetGeometry(null, null);
	}

	/**
	 * A {@link WidgetGeometry} for callers that exercise the widget-backed
	 * reads: the handed client and sprite manager drive the minimap and
	 * world-map lookups while the instance stays detached from Guice.
	 */
	public static WidgetGeometry geometry(Client client, SpriteManager spriteManager)
	{
		return new WidgetGeometry(client, spriteManager);
	}
}
